    private static var launchDriver: SelfTestLaunchCatalog.Driver {
        .init(
            waitForMainWindow: { waitForMainWindow(then: $0) },
            openSearch: { openSearchThen($0) },
            waitForWorkspace: { waitForWorkspace(then: $0) },
            mainQueue: { DispatchQueue.main.async(execute: $0) },
            background: { DispatchQueue.global(qos: .userInitiated).async(execute: $0) },
            mainActorTask: { action in Task { @MainActor in action() } },
            mainAfter: { delay, action in
                DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: action)
            }
        )
    }

    private static func runUpdatesTest() {
        testLabel = "updates"
        guard let item = updatesMenuItem() else {
            finish(false, "Sparkle-Menüpunkt fehlt im echten App-Menü")
        }
        guard item.action == #selector(SPUStandardUpdaterController.checkForUpdates(_:)),
              item.target is SPUStandardUpdaterController else {
            finish(false, "Update-Menüpunkt zielt nicht direkt auf Sparkle")
        }

        let info = Bundle.main.infoDictionary ?? [:]
        guard info["SUFeedURL"] as? String
                == "https://danielmuellerir.github.io/fastra/appcast.xml",
              (info["SUPublicEDKey"] as? String)?.isEmpty == false,
              info["SUEnableAutomaticChecks"] as? Bool == true,
              info["SUAutomaticallyUpdate"] as? Bool == false,
              info["SUAllowsAutomaticUpdates"] as? Bool == false,
              info["SUEnableSystemProfiling"] as? Bool == false,
              info["SUVerifyUpdateBeforeExtraction"] as? Bool == true,
              info["SURequireSignedFeed"] as? Bool == true else {
            finish(false, "Sparkle-Sicherheitskonfiguration im App-Bundle unvollständig")
        }
        finish(true, "Menüpunkt zielt auf Sparkle; Feed, Signatur und Datenschutz sind konfiguriert")
    }

    // MARK: - Fenster-Polling (statt fixem Start-Guard)

    /// Fensterlose Workspace-Tests brauchen keinen pauschalen Startpuffer.
    /// `Workspace.init` erzeugt den SearchRunner vollständig, bevor es
    /// `Workspace.shared` setzt. Deshalb ist dieser Hook die überprüfbare
    /// Bereitschaftsgrenze für alle Tests, die nur das Modell treiben.
    private static func waitForWorkspace(then body: @escaping () -> Void) {
        // Bisher 300 × 50 ms; dieselbe Rechnung, jetzt als bediente Frist.
        waitFor(budget: 15, pause: 0.05,
                condition: { Workspace.shared != nil },
                onTimeout: { book in
                    finish(false, "Workspace.shared blieb nil — \(book.summary)")
                },
                then: body)
    }

    private static func updatesMenuItem() -> NSMenuItem? {
        NSApp.mainMenu?.items.first?.submenu?.items.first {
            $0.identifier == NSUserInterfaceItemIdentifier("Fastra.CheckForUpdates")
        }
    }

    /// `scheduleUpdateMenuInstallation` läuft nach dem SwiftUI-Scene-Aufbau.
    /// Ein fester Fünf-Sekunden-Puffer wartet auf schnellen Macs fast immer
    /// grundlos. ID, Target und Action bilden zusammen den fertigen Zustand;
    /// bei einem echten Fehler liefert `runUpdatesTest` nach spätestens fünf
    /// Sekunden weiter die präzise Diagnose.
    private static func waitForUpdatesMenu() {
        // Beide Ausgänge führen in den Test: Ist das Menü nach 5 s bedienter
        // Zeit nicht verdrahtet, diagnostiziert `runUpdatesTest` das selbst.
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    guard let item = updatesMenuItem() else { return false }
                    return item.action == #selector(SPUStandardUpdaterController.checkForUpdates(_:))
                        && item.target is SPUStandardUpdaterController
                },
                onTimeout: { _ in runUpdatesTest() },
                then: { runUpdatesTest() })
    }

    /// Pollt (max. ~15 s, 50-ms-Takt), bis ein sichtbares Hauptfenster
    /// existiert, lässt die UI dann 0,5 s setteln und ruft `body`.
    /// Erscheint binnen 15 s keines → FAIL mit Fenster-Dump (das ist dann
    /// ein echter Befund, kein Timing-Artefakt mehr).
    private static func waitForMainWindow(then body: @escaping () -> Void) {
        waitFor(budget: 15, pause: 0.05,
                condition: {
                    NSApp.windows.contains {
                        $0.frameAutosaveName != SearchWindow.frameAutosaveName
                            && $0.contentView != nil && $0.isVisible
                    }
                },
                onTimeout: { book in
                    finish(false, "kein sichtbares Hauptfenster — \(book.summary) — \(windowsSummary())")
                },
                then: {
                    // Einmalige Settle-Pause, bewusst keine Warteschleife.
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { body() }
                })
    }

    /// Einige Editor-Selbsttests brauchen bewusst ein echtes leeres Dokument.
    /// Das Fenster kann sichtbar sein, bevor CodeEditSourceEditor montiert
    /// ist. Dieser Helfer wartet deshalb auf die echte TextView, statt eine
    /// feste Pause zu raten. Screenshot- und Willkommen-Tests verwenden ihn
    /// nicht.
    private static func waitForEditor(
        window: NSWindow,
        then body: @escaping (NSView, TextView) -> Void
    ) {
        guard let root = window.contentView else {
            finish(false, "Hauptfenster ohne contentView")
        }
        // Auch im Willkommens-Zustand ist der Editor montiert; es ist kein
        // vorheriger Klick nötig.
        var editor: TextView?
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    editor = editorTextView(in: root) as? TextView
                    return editor != nil
                },
                onTimeout: { book in
                    finish(false, "Editor nicht montiert — \(book.summary)")
                },
                then: {
                    guard let editor else { finish(false, "Editor nach Erfolg nicht mehr montiert") }
                    body(root, editor)
                })
    }

    /// Wie `waitForEditor`, wartet zusätzlich auf Ankertext und liefert dessen
    /// Bereich. Ein montierter Editor kann noch leer sein; `range(of:)` würde
    /// `NSNotFound` liefern. Diese Range darf nicht als Selektion in den
    /// CodeEditTextView-Attachment-Beobachter und dessen `IndexSet` gelangen.
    private static func waitForEditorShowing(
        window: NSWindow,
        text needle: String,
        onTimeout: @escaping () -> Void,
        then body: @escaping (NSView, TextView, NSRange) -> Void
    ) {
        // Je Durchlauf wird der Editor neu gesucht (er kann zwischenzeitlich
        // umgebaut worden sein); deshalb die asynchrone Variante.
        var shown: (root: NSView, textView: TextView, range: NSRange)?
        waitForAsync(
            budget: 5, pause: 0.05,
            check: { answer in
                waitForEditor(window: window) { root, textView in
                    let found = (textView.string as NSString).range(of: needle)
                    if found.location != NSNotFound {
                        shown = (root, textView, found)
                    }
                    answer(found.location != NSNotFound)
                }
            },
            onTimeout: { _ in onTimeout() },
            then: {
                guard let shown else { finish(false, "Ankertext nach Erfolg nicht mehr im Editor") }
                body(shown.root, shown.textView, shown.range)
            }
        )
    }

    /// Öffnet die Suchmaske (exakt wie CMD+F) und wartet, bis sie sichtbar
    /// ist, dann `body`. Nötig, seit `showSearchDialog` per Default `false`
    /// startet (die Maske öffnet nicht mehr automatisch beim Start). Vorher
    /// muss das Hauptfenster da sein (ContentView appeared → onReceive aktiv),
    /// deshalb wird dieser Helfer aus `waitForMainWindow { … }` heraus gerufen
    /// — gleiches Muster wie der contrast-Test.
    private static func openSearchThen(_ body: @escaping () -> Void) {
        NotificationCenter.default.post(name: .fastraShowSearchFile, object: nil)
        waitForSearchWindow(then: body)
    }

    /// Wie `waitForMainWindow`, aber für die Suchmaske. Sie startet geschlossen;
    /// Aufrufer wie cmdw/fields öffnen sie zuvor über `openSearchThen`
    /// (`.fastraShowSearchFile`).
    private static func waitForSearchWindow(then body: @escaping () -> Void) {
        waitFor(budget: 15, pause: 0.05,
                condition: {
                    NSApp.windows.contains {
                        $0.frameAutosaveName == SearchWindow.frameAutosaveName && $0.isVisible
                    }
                },
                onTimeout: { book in
                    finish(false, "keine sichtbare Suchmaske — \(book.summary) — \(windowsSummary())")
                },
                then: {
                    // Einmalige Settle-Pause, bewusst keine Warteschleife.
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { body() }
                })
    }

    /// Eine Zeile pro Fenster — für FAIL-Diagnosen der Polling-Helfer.
    private static func windowsSummary() -> String {
        if NSApp.windows.isEmpty { return "NSApp.windows ist LEER" }
        return NSApp.windows.map {
            "[\(type(of: $0))] title=\"\($0.title)\" autosave=\"\($0.frameAutosaveName)\" "
            + "visible=\($0.isVisible) contentView=\($0.contentView != nil)"
        }.joined(separator: " · ")
    }

    /// Diagnose (`-selftest windows`): Alle 0,5 s Fenster ausgeben, bis ein
    /// sichtbares Hauptfenster erscheint (PASS mit Zeitangabe) oder rund 10 s
    /// verstrichen sind (FAIL mit letztem Dump).
    private static func runWindowsDump() {
        testLabel = "windows"
        var polls = 0
        waitFor(budget: 10, pause: 0.5,   // 20 × 0,5 s Beobachtungsfenster
                condition: {
                    var lines: [String] = []
                    var foundMain = false
                    for w in NSApp.windows {
                        let isMain = w.frameAutosaveName != SearchWindow.frameAutosaveName
                            && w.contentView != nil && w.isVisible
                        if isMain { foundMain = true }
                        lines.append("  [\(type(of: w))] title=\"\(w.title)\" autosave=\"\(w.frameAutosaveName)\" visible=\(w.isVisible) key=\(w.isKeyWindow) contentView=\(w.contentView != nil) frame=\(w.frame)")
                    }
                    let dump = "t=\(Double(polls) * 0.5)s windows=\(NSApp.windows.count)\n" + lines.joined(separator: "\n")
                    FileHandle.standardError.write(Data("WINDOWDUMP \(dump)\n".utf8))
                    polls += 1
                    return foundMain
                },
                onTimeout: { book in
                    finish(false, "kein sichtbares Hauptfenster — \(book.summary)")
                },
                then: {
                    finish(true, "sichtbares Hauptfenster nach \(Double(polls - 1) * 0.5)s")
                })
    }

