    /// Rekursive Suche, weil SwiftUI den Datei-Menüpunkt in interne Untermenüs
    /// einhängen kann. Modifiers werden bewusst geprüft, damit nicht ein
    /// zufälliger unmodifizierter „n"-Eintrag ausgelöst wird.
    private static func menuItem(forKeyEquivalent key: String, in menu: NSMenu) -> NSMenuItem? {
        for item in menu.items {
            if item.keyEquivalent.lowercased() == key,
               item.keyEquivalentModifierMask.contains(.command) {
                return item
            }
            if let submenu = item.submenu,
               let found = menuItem(forKeyEquivalent: key, in: submenu) {
                return found
            }
        }
        return nil
    }

    /// Testordner des `print`-Selbsttests — `finish` räumt ihn in jedem
    /// Ausgang auf (Erfolg, Fehler, Abbruch).
    private static var printFixtureDirectory: URL?
    /// Testprojekt des tabflood-Selbsttests. Wird in `finish` entfernt: Ein
    /// `defer` in der Prüfmethode lief nie, weil `finish` per `exit()` endet
    /// und den Swift-Stack nicht abwickelt — jeder direkte `-selftest
    /// tabflood`-Lauf ließ ein `fastra-tabflood-*`-Verzeichnis zurück
    private static var tabFloodFixtureDirectory: URL?


    private static var shortSearchFixtureDirectory: URL?
    private static var tabSearchFixtureDirectory: URL?
    private static var testLabel = "findbar"
    private static var testStartedNanoseconds = DispatchTime.now().uptimeNanoseconds

    private static func finish(_ ok: Bool, _ msg: String) -> Never {
        finish(ok ? .pass : .fail, msg)
    }

    /// Temporäre Fixture-Ordner zentral aufräumen. Neue Fixtures hier eintragen,
    /// damit sie auch bei frühem Testabbruch entfernt werden.
    /// Jeder Prozess besitzt ein eigenes UUID-Verzeichnis; kein Test verwendet
    /// die Fixtures über einen Neustart hinweg. Auch `externaldiffcold` legt
    /// für jeden Helfer eigene Fixtures an.
    private static func cleanupFixtureDirectories() {
        if let commandOwnerKeyMonitor {
            NSEvent.removeMonitor(commandOwnerKeyMonitor)
            self.commandOwnerKeyMonitor = nil
        }
        let directories = [shortSearchFixtureDirectory,
                           tabSearchFixtureDirectory,
                           windowRoutingTests.fixtureDirectory,
                           backgroundScrollTests.fixtureDirectory,
                           printFixtureDirectory,
                           tabFloodFixtureDirectory,
                           sidebarToggleFixtureDirectory]
            + sessionRestorationTests.fixtureDirectories
        for directory in directories.compactMap({ $0 }) {
            try? FileManager.default.removeItem(at: directory)
        }
        shortSearchFixtureDirectory = nil
        tabSearchFixtureDirectory = nil
        windowRoutingTests.clearFixtureDirectoryReference()
        backgroundScrollTests.clearFixtureDirectoryReference()
        printFixtureDirectory = nil
        tabFloodFixtureDirectory = nil
        sidebarToggleFixtureDirectory = nil
        sessionRestorationTests.clearFixtureDirectoryReferences()
    }

    private static func finish(_ outcome: SelfTestOutcome, _ msg: String) -> Never {
        cleanupScreenshotFixtures()
        cleanupFixtureDirectories()
        let pasteboardCleanup: SelfTestCompletion.PasteboardCleanup
        switch finishSelfTestPasteboardMutation() {
        case .none: pasteboardCleanup = .none
        case .restored: pasteboardCleanup = .restored
        case .keptNewerContent: pasteboardCleanup = .keptNewerContent
        case .failed(let error): pasteboardCleanup = .failed(error)
        }
        let (finalOutcome, finalMessage) = SelfTestCompletion.resolve(
            outcome: outcome, message: msg, pasteboardCleanup: pasteboardCleanup
        )
        let elapsed = DispatchTime.now().uptimeNanoseconds - testStartedNanoseconds
        let appMilliseconds = elapsed / 1_000_000
        let output = "SELFTEST-METRIC test=\(testLabel) app_ms=\(appMilliseconds)\n"
            + "SELFTEST-RESULT v=1 test=\(testLabel) status=\(finalOutcome.protocolStatus)\n"
            + "SELFTEST \(testLabel): \(finalOutcome.protocolStatus) — \(finalMessage)\n"
        FileHandle.standardError.write(Data(output.utf8))
        exit(finalOutcome == .pass ? 0 : 1)
    }

    // MARK: - Warteschleifen mit Fristbuchhaltung

    /// Wanduhr-Deckel dieses Testprozesses. Braucht `testLabel` und
    /// `testStartedNanoseconds` und muss deshalb hier stehen — beide sind
    /// `private` und damit außerhalb dieser Datei unsichtbar.
    ///
    /// `testLabel` ist beim allerersten Warten (`waitForWorkspace` vor dem
    /// eigentlichen Testrumpf) noch der Vorgabewert. Das ist unschädlich: Der
    /// Vorgabewert führt auf die Standard-Runner-Frist, und genau die gilt für
    /// alle fensterlosen Tests.
    private static func pollHardCap(for budget: TimeInterval) -> TimeInterval {
        let elapsed = Double(DispatchTime.now().uptimeNanoseconds - testStartedNanoseconds)
            / 1_000_000_000
        return SelfTestPolling.hardCap(budget: budget, elapsed: elapsed, test: testLabel)
    }

    /// Wartet, bis `condition` wahr ist, und ruft dann `then`; sonst
    /// `onTimeout` mit der Buchhaltung. Ersetzt die handgezählten
    /// `tick >= N`-Schleifen: `budget` ist genau die alte Rechnung
    /// N × Pause, die Buchhaltung zieht aber Fremdlast auf dem Main-Thread ab
    /// (Begründung in `SelfTestPolling.swift`).
    private static func waitFor(
        budget: TimeInterval,
        pause: TimeInterval,
        condition: @escaping () -> Bool,
        onTimeout: @escaping (SelfTestPollBudget) -> Void,
        then: @escaping () -> Void
    ) {
        SelfTestPolling.waitFor(
            budget: budget, pause: pause, hardCap: pollHardCap(for: budget),
            condition: condition, onTimeout: onTimeout, then: then
        )
    }

    /// Wie `waitFor`, aber mit asynchroner Bedingung.
    private static func waitForAsync(
        budget: TimeInterval,
        pause: TimeInterval,
        check: @escaping (@escaping (Bool) -> Void) -> Void,
        onTimeout: @escaping (SelfTestPollBudget) -> Void,
        then: @escaping () -> Void
    ) {
        SelfTestPolling.waitForAsync(
            budget: budget, pause: pause, hardCap: pollHardCap(for: budget),
            check: check, onTimeout: onTimeout, then: then
        )
    }

