    @MainActor private static func trackedHistoryFromEditMenu(_ action: Selector) async throws {
        guard let main = NSApp.mainMenu,
              let root = main.items.first(where: { $0.submenu?.items.contains(where: { $0.action == action }) == true }),
              let menu = root.submenu else { throw NSError(domain: "SelfTestTrackedMenu", code: 1) }
        var tracking = false, pressed = false
        let began = NotificationCenter.default.addObserver(forName: NSMenu.didBeginTrackingNotification,
            object: main, queue: .main) { _ in tracking = true }
        defer { // trackedHistoryFromEditMenu kehrt vor dem äußeren finish regulär zurück oder wirft.
            NotificationCenter.default.removeObserver(began)
            menu.cancelTracking(); main.cancelTracking()
        }
        let success: Bool = await withCheckedContinuation { continuation in
            var timer: Timer?, ticks = 0
            func conclude(_ value: Bool) {
                timer?.invalidate(); timer = nil
                menu.cancelTracking(); main.cancelTracking()
                DispatchQueue.main.async { continuation.resume(returning: value) }
            }
            timer = Timer(timeInterval: 0.05, repeats: true) { _ in
                ticks += 1
                if ticks >= 160 { conclude(false); return }
                guard tracking, !pressed,
                      let item = menu.items.first(where: { $0.action == action }), item.isEnabled else { return }
                // AXPress am Eintrag führte die Aktion aus, kehrte im
                // Prüflauf aber nicht zurück. Die AppKit-Menüaktion nutzt
                // denselben Responder im bereits geöffneten echten Menü.
                timer?.invalidate(); timer = nil
                pressed = true
                menu.performActionForItem(at: menu.index(of: item))
                conclude(true)
            }
            if let timer { RunLoop.main.add(timer, forMode: .common); RunLoop.main.add(timer, forMode: .eventTracking) }
            DispatchQueue.main.async { _ = root.accessibilityPerformPress() }
        }
        guard success else {
            throw NSError(domain: "SelfTestTrackedMenu", code: 2,
                userInfo: [NSLocalizedDescriptionKey: "Echtes Verlaufsmenü: Beginn=\(tracking), Aktion=\(pressed)"])
        }
        FileHandle.standardError.write(Data(("HISTORY_MENU_TRACKED action=\(NSStringFromSelector(action)) began=\(tracking) pressed=\(pressed) cleanup=cancelTracking\n").utf8))
    }

    @MainActor private static func historyFromEditMenu(_ actionName: String) async throws {
        let action = NSSelectorFromString(actionName)
        if testLabel == "filedifftransfer" {
            try await trackedHistoryFromEditMenu(action)
            return
        }
        guard let main = NSApp.mainMenu,
              let menu = main.items.compactMap(\.submenu).first(where: {
                  $0.items.contains(where: { $0.action == action })
              }) else { throw NSError(domain: "SelfTestMenu", code: 1) }
        menu.update()
        guard let item = menu.items.first(where: { $0.action == action }), item.isEnabled else {
            throw NSError(domain: "SelfTestMenu", code: 2,
                userInfo: [NSLocalizedDescriptionKey: "Native Verlaufsaktion im Bearbeiten-Menü nicht verfügbar"])
        }
        // AppKits Menüaktion trifft den echten Responder-/Undo-Pfad, ohne
        // daneben ein asynchron öffnendes Menü im Test zurückzulassen.
        menu.performActionForItem(at: menu.index(of: item))
        FileHandle.standardError.write(Data(("HISTORY_MENU_ACTION action=\(actionName) method=appkit-menu-action\n").utf8))
    }

    @MainActor private static func requestSystemUndoIfAvailable(before: String, expected: String, mode: String) async throws -> Bool {
        guard let output = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] else { return false }
        let directory = URL(fileURLWithPath: output)
        guard FileManager.default.fileExists(atPath: directory.appendingPathComponent("history-driver-ready").path) else { return false }
        guard let code = historyKeyCode() else { finish(.environment, "Das aktive Tastaturlayout liefert kein Z") }
        let nonce = UUID().uuidString
        let request: [String: Any] = ["mode": mode, "nonce": nonce, "pid": Int(getpid()),
            "keyCode": Int(code), "before": before, "expected": expected]
        try JSONSerialization.data(withJSONObject: request, options: [.sortedKeys]).write(
            to: directory.appendingPathComponent("history-request.json"), options: .atomic)
        let responseURL = directory.appendingPathComponent("history-response.json")
        let response = try await waitForSystemHistoryResponse(at: responseURL, nonce: nonce)
        guard response["ok"] as? Bool == true else {
            throw NSError(domain: "SelfTestSystemHistory", code: 1,
                userInfo: [NSLocalizedDescriptionKey: "Systemtastentreiber meldet einen Fehler: " + String(describing: response)])
        }
        return true
    }

    @MainActor static func waitForSystemHistoryResponse(at url: URL, nonce: String) async throws -> [String: Any] {
        var response: [String: Any]?
        try await nativeUIWait("Systemtastentreiber bestätigt vollständige Zustellung") {
            guard let data = try? Data(contentsOf: url),
                  let decoded = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                  decoded["nonce"] as? String == nonce else { return false }
            response = decoded
            return true
        }
        return response!
    }

    private static func runFindBarTest() {
        testLabel = "findbar"
        // Hauptfenster = sichtbares Fenster, das nicht die Suchmaske ist.
        guard let workspace = Workspace.shared,
              let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }) else {
            finish(false, "kein Hauptfenster gefunden")
        }

        waitForEditor(window: mainWindow) { root, textView in
            prepareFindBarTest(workspace: workspace, mainWindow: mainWindow,
                               root: root, textView: textView)
        }
    }

    private static func prepareFindBarTest(
        workspace: Workspace,
        mainWindow: NSWindow,
        root: NSView,
        textView: TextView
    ) {
        // Voraussetzung, damit der Editor-eigene CMD+F-Monitor überhaupt
        // triggern würde: Hauptfenster Key + Editor ist First Responder.
        // (Genau die Situation, in der der Zombie früher auftrat.)
        // Ein bereits offenes Suchfenster darf den späteren Erfolg nicht vortäuschen.
        workspace.showSearchDialog = false
        // Ein Direktstart besitzt noch keinen App-Fokus. Der zentrale Helfer
        // respektiert die Aktivierungssperre des Runners auch für diese Prüfung.
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)
        _ = mainWindow.makeFirstResponder(textView)

        // Kurz warten: didBecomeKey installiert unseren Monitor neu (neuester).
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
            let isFR = mainWindow.firstResponder === textView
            guard mainWindow.isKeyWindow else {
                finish(.environment, "Hauptfenster vor CMD+F nicht Key-Window")
            }
            guard isFR else { finish(false, "Editor vor CMD+F nicht First Responder") }
            guard !workspace.showSearchDialog, !findBarSearchWindowVisible(for: workspace) else {
                finish(false, "Suchfenster vor CMD+F noch offen; Aufruf wäre nicht nachweisbar")
            }

            // Erst Command-Modifier (flagsChanged), dann F-keyDown — wie ein
            // echtes CMD+F. Der flagsChanged-Event löst den Reinstall unseres
            // keyDown-Monitors aus (siehe AppDelegate.installFlagsMonitor).
            if let flags = NSEvent.keyEvent(
                with: .flagsChanged, location: .zero, modifierFlags: .command,
                timestamp: ProcessInfo.processInfo.systemUptime,
                windowNumber: mainWindow.windowNumber, context: nil,
                characters: "", charactersIgnoringModifiers: "",
                isARepeat: false, keyCode: 55
            ) {
                NSApp.postEvent(flags, atStart: false)
            }
            guard let event = NSEvent.keyEvent(
                with: .keyDown, location: .zero, modifierFlags: .command,
                timestamp: ProcessInfo.processInfo.systemUptime,
                windowNumber: mainWindow.windowNumber, context: nil,
                characters: "f", charactersIgnoringModifiers: "f",
                isARepeat: false, keyCode: 3
            ) else {
                finish(false, "konnte CMD+F-Event nicht bauen")
            }
            // In die Queue posten → durchläuft die lokalen Monitore.
            NSApp.postEvent(event, atStart: false)

            // Wichtig: Nicht nur den Endzustand prüfen. Der „Zombie" blitzt
            // kurz auf (showFindPanel animiert 0,15 s ein) und wird dann vom
            // Reconcile wieder geschlossen — bei einer Einzel-Messung nach
            // 0,6 s ist er längst weg und der Test wäre fälschlich grün.
            // Deshalb pollen wir über ~1,2 s engmaschig und schlagen an,
            // sobald das Panel auch nur einmal sichtbar war.
            pollForFlash(in: root, workspace: workspace, firstResponder: isFR)
        }
    }

    /// Pollt engmaschig, ob das Editor-Find-Panel im Verlauf auch nur
    /// kurz sichtbar wird (Flash). Sobald es einmal auftaucht → FAIL.
    /// Nach Ablauf muss zusätzlich Fastras eigene Suche sichtbar geöffnet sein.
    private static func pollForFlash(in root: NSView, workspace: Workspace,
                                     firstResponder isFR: Bool, tick: Int = 0) {
        let maxTicks = 40            // 40 × 30 ms ≈ 1,2 s Beobachtungsfenster
        if findPanelVisible(in: root) {
            finish(false, "Editor-Find-Panel blitzte auf nach CMD+F (Tick \(tick), firstResponder=\(isFR))")
        }
        if tick >= maxTicks {
            let ownSearchVisible = findBarSearchWindowVisible(for: workspace)
            let passed = findBarObservationPassed(
                editorPanelVisible: false, searchModelVisible: workspace.showSearchDialog,
                searchWindowVisible: ownSearchVisible
            )
            finish(passed, "kein Editor-Find-Panel über \(maxTicks) Ticks nach CMD+F "
                + "(firstResponder=\(isFR), eigeneSuche=\(ownSearchVisible), "
                + "Suchmodell=\(workspace.showSearchDialog))")
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.03) {
            pollForFlash(in: root, workspace: workspace, firstResponder: isFR, tick: tick + 1)
        }
    }

    /// Der Tastaturtest braucht sowohl den negativen als auch den positiven Nachweis.
    static func findBarObservationPassed(
        editorPanelVisible: Bool, searchModelVisible: Bool, searchWindowVisible: Bool
    ) -> Bool {
        !editorPanelVisible && searchModelVisible && searchWindowVisible
    }

    private static func findBarSearchWindowVisible(for workspace: Workspace) -> Bool {
        NSApp.windows.contains {
            $0.identifier == SearchWindow.identifier && $0.isVisible
                && WorkspaceWindowRegistry.workspace(for: $0) === workspace
        }
    }

    /// Prüft, ob Suchen- und Ersetzen-Feld echte, editierbare Texteingaben
    /// sind. Beweist die gemeldeten Bugs (Find-Feld war statisches `Text`,
    /// Replace „nicht änderbar") deterministisch im echten App-Prozess.
    ///
    /// Vorgehen: Suchfenster nach vorn holen, alle editierbaren Text-Inputs
    /// im Fensterbaum einsammeln, jeweils zum First Responder machen und
    /// einen echten Tastendruck hineinposten — danach muss sich der Feld-
    /// Inhalt geändert haben. Findet der Test weniger als zwei editierbare
    /// Felder, fehlt eines (typisch: das Find-Feld) → FAIL.
    private static func runFieldsTest() {
        testLabel = "fields"
        guard let searchWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName == SearchWindow.frameAutosaveName
        }) else {
            finish(false, "Suchfenster nicht gefunden")
        }
        searchWindow.makeKeyAndOrderFront(nil)
        activateApplication(ignoringOtherApps: true)

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            guard let root = searchWindow.contentView else {
                finish(false, "Suchfenster ohne contentView")
            }
            // Seit v0.7 sind Suchen- und Ersetzen-Feld keine SwiftUI-
            // TextFields (NSTextField) mehr, sondern NSTextView-basierte
            // RegexFieldTextViews (Inline-Token-Highlighting). Der Test
            // sammelt deshalb beide Arten ein — fällt eine der beiden
            // Umstellungen je zurück, bleibt der Test trotzdem scharf.
            var fields: [NSView] = []
            collectTypeableFields(in: root, into: &fields)

            guard fields.count >= 2 else {
                finish(false, "nur \(fields.count) editierbares Texteingabe-Feld gefunden (erwartet ≥2: Suchen + Ersetzen)")
            }

            // Jedes Feld real betippen und Änderung verifizieren.
            for (idx, field) in fields.enumerated() {
                let before = readFieldText(field)
                guard searchWindow.makeFirstResponder(field) else {
                    finish(false, "Feld \(idx) (\(describeField(field))) konnte nicht fokussiert werden")
                }
                if let tf = field as? NSTextField {
                    // SwiftUI-TextField bridged auf NSTextField; direktes
                    // Einfügen über den Feld-Editor ist der zuverlässigste
                    // Weg, einen echten Tastendruck nachzubilden.
                    tf.currentEditor()?.insertText("Z")
                } else if let tv = field as? RegexFieldTextView {
                    // NSTextView nimmt insertText direkt — gleicher Pfad
                    // wie eine echte Tastatureingabe (inkl. Delegate).
                    tv.insertText("Z", replacementRange: NSRange(location: NSNotFound, length: 0))
                }
                let after = readFieldText(field)
                if after == before {
                    finish(false, "Feld \(idx) (\(describeField(field))) nahm keine Eingabe an (Inhalt unverändert: \"\(before)\")")
                }
            }
            finish(true, "\(fields.count) editierbare Felder, alle nehmen Eingaben an")
        }
    }

    /// Optionslayout im echten Suchfenster prüfen: Breit stehen alle Schalter
    /// nebeneinander, schmal der zweite Block linksbündig unter RegEx. Kantenmarker
    /// messen das Layout; ein Zustandsmarker prüft, dass „∗ wörtlich“ nach
    /// Pattern-/RegEx-Wechseln im gerenderten Baum aktualisiert wird.
    private static func runSearchOptionsTest() {
        testLabel = "searchoptions"
        guard let ws = Workspace.shared,
              let searchWindow = NSApp.windows.first(where: {
                  $0.frameAutosaveName == SearchWindow.frameAutosaveName
              }),
              let root = searchWindow.contentView else {
            finish(false, "Workspace oder Suchfenster fehlt")
        }

        ws.scope = .file
        ws.useRegex = true
        ws.findPattern = ""
        // Breite selbst herstellen statt sie aus dem geteilten Test-Home zu
        // erben (siehe AGENTS.md, tabcompare-Falle): Bei 1000 pt passen alle
        // Schalter nebeneinander, bei der Mindestbreite nicht.
        setSearchWindowWidth(searchWindow, 1000)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
            guard searchWindow.contentMinSize.height >= 450 else {
                finish(false, "effektive Mindesthöhe \(searchWindow.contentMinSize.height), "
                    + "erwartet mindestens 450")
            }
            guard let (firstPoint, secondPoint) = searchOptionMarkerPoints(in: root) else {
                finish(false, "Optionsmarker im sternlosen RegEx-Zustand unvollständig")
            }
            guard abs(firstPoint.y - secondPoint.y) <= 1,
                  secondPoint.x - firstPoint.x >= 40 else {
                finish(false, "Optionen im breiten Fenster nicht einzeilig: "
                    + "erste=\(firstPoint), zweite=\(secondPoint)")
            }

            setSearchWindowWidth(searchWindow, searchWindow.contentMinSize.width)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                guard let (narrowFirst, narrowSecond) = searchOptionMarkerPoints(in: root) else {
                    finish(false, "Optionsmarker nach dem Verschmälern unvollständig")
                }
                guard abs(narrowFirst.x - narrowSecond.x) <= 1,
                      abs(narrowFirst.y - narrowSecond.y) >= 5 else {
                    finish(false, "Optionen im schmalen Fenster nicht linksbündig zweizeilig: "
                        + "erste=\(narrowFirst), zweite=\(narrowSecond)")
                }

                ws.useRegex = false
                ws.findPattern = "a*b"
                pollSearchOptionsEnabled(ws, root: root)
            }
        }
    }

    // MARK: - dialoglayout: Geometrie der übrigen Dialoge

    /// Geschwister von `searchlayout` für die Dialoge mit fester Größe:
    /// Einstellungen, Dateivergleich sowie die vier Blätter der Suchmaske
    /// (Treffer extrahieren, Vorlagen verwalten, Aus Beispiel, Datei-Set).
    /// Pro Dialog: kein Bedienelement außerhalb des Inhalts, kein sichtbares
    /// Bedienelement mit null Breite oder Höhe. Mit `FASTRA_DIALOGLAYOUT_DIR`
    /// entsteht je Dialog ein PNG (`dialog-<name>.png`) für die Sichtprüfung.
    private static func runDialogLayoutTest() {
        testLabel = "dialoglayout"
        guard let ws = Workspace.shared,
              let searchWindow = NSApp.windows.first(where: {
                  $0.frameAutosaveName == SearchWindow.frameAutosaveName
              }),
              let mainWindow = mainWindowForAXChecks() else {
            finish(false, "Workspace, Suchfenster oder Hauptfenster fehlt")
        }
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-dialoglayout-\(UUID().uuidString)")
        shortSearchFixtureDirectory = directory
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            try "alpha\n".write(to: directory.appendingPathComponent("sample.txt"),
                                atomically: true, encoding: .utf8)
        } catch { finish(false, "Dialog-Fixture: \(error.localizedDescription)") }
        ws.openProject(at: directory)
        ws.scope = .project
        ws.findPattern = "alpha"

        let pngDirectory = ProcessInfo.processInfo.environment["FASTRA_DIALOGLAYOUT_DIR"]
            .map { URL(fileURLWithPath: $0) }
        var findings: [String] = []

        // (Name, Öffnen, Wurzel-View finden, Schließen)
        // `open` meldet mit `false`, dass der Dialog gar nicht erst geöffnet
        // werden konnte; der Schritt endet dann sofort mit einem Befund.
        typealias Step = (name: String, open: () -> Bool, root: () -> NSView?, close: () -> Void)
        func searchSheet(_ key: String) -> Step {
            (name: key,
             open: { NotificationCenter.default.post(name: .fastraSelfTestSearchSheet, object: ws,
                                                     userInfo: ["sheet": key])
                     return true },
             root: { searchWindow.attachedSheet?.contentView },
             close: { NotificationCenter.default.post(name: .fastraSelfTestSearchSheet, object: ws,
                                                      userInfo: ["sheet": "close"]) })
        }
        let steps: [Step] = [
            (name: "settings",
             // Über den echten Menüpunkt (⌘,): Der Selector der Settings-Szene
             // ist je macOS-Version anders benannt; der Menüeintrag kennt ihn.
             open: {
                 // Kein Ersatz-Selector: Ein anderer Dialog würde den fehlgeschlagenen
                 // Aufruf der Einstellungen verdecken, statt dessen Layout zu prüfen.
                 guard let item = NSApp.mainMenu?.items.first?.submenu?.items
                     .first(where: { $0.keyEquivalent == "," }) else {
                     findings.append("settings: Menüeintrag ⌘, fehlt")
                     return false
                 }
                 guard let action = item.action else {
                     findings.append("settings: Menüeintrag ⌘, hat keine Action")
                     return false
                 }
                 NSApp.sendAction(action, to: item.target, from: item)
                 return true
             },
             root: { NSApp.windows.first { window in
                 window.isVisible && window.contentView.map { markerViewExists(probe: $0) } == true
             }?.contentView },
             close: { NSApp.windows.first { window in
                 window.isVisible && window.contentView.map { markerViewExists(probe: $0) } == true
             }?.close() }),
            (name: "compare",
             open: { ws.showCompareFilesDialog = true
                     return true },
             root: { mainWindow.attachedSheet?.contentView },
             close: { ws.showCompareFilesDialog = false }),
            searchSheet("extraction"),
            searchSheet("patterns"),
            searchSheet("example"),
            searchSheet("fileset"),
        ]
        var index = 0
        func step() {
            guard index < steps.count else {
                finish(findings.isEmpty,
                       findings.isEmpty
                       ? "\(steps.count) Dialoge: alle Bedienelemente innerhalb des Inhalts und sichtbar bemessen"
                       : findings.joined(separator: " | "))
            }
            let current = steps[index]
            index += 1
            guard current.open() else { step(); return }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                guard let root = current.root() else {
                    let titles = NSApp.windows.filter(\.isVisible).map(\.title).joined(separator: ", ")
                    findings.append("\(current.name): Dialog nicht gefunden (sichtbar: \(titles))")
                    step(); return
                }
                root.layoutSubtreeIfNeeded()
                var outside: [String] = []
                collectControlsOutside(root.bounds.insetBy(dx: -1, dy: -1), in: root, root: root, into: &outside)
                if !outside.isEmpty {
                    findings.append("\(current.name): außerhalb: " + outside.prefix(3).joined(separator: ", "))
                }
                var collapsed: [String] = []
                collectCollapsedControls(in: root, into: &collapsed)
                if !collapsed.isEmpty {
                    findings.append("\(current.name): null Breite/Höhe: " + collapsed.prefix(3).joined(separator: ", "))
                }
                if let pngDirectory {
                    try? FileManager.default.createDirectory(at: pngDirectory, withIntermediateDirectories: true)
                    if let bitmap = root.bitmapImageRepForCachingDisplay(in: root.bounds) {
                        root.cacheDisplay(in: root.bounds, to: bitmap)
                        try? bitmap.representation(using: .png, properties: [:])?
                            .write(to: pngDirectory.appendingPathComponent("dialog-\(current.name).png"),
                                   options: .atomic)
                    }
                }
                if current.name == "settings" {
                    guard let marker = markerView(id: "markdownVisualDefault", in: root),
                          let scroll = marker.enclosingScrollView, let document = scroll.documentView else {
                        findings.append("settings: Markdown-Einstellung fehlt")
                        current.close(); step(); return
                    }
                    let frame = marker.convert(marker.bounds, to: document)
                    let clip = scroll.contentView
                    clip.scroll(to: NSPoint(x: clip.bounds.minX, y: max(0, frame.minY - 60)))
                    scroll.reflectScrolledClipView(clip)
                    root.layoutSubtreeIfNeeded()
                    if let pngDirectory, let bitmap = root.bitmapImageRepForCachingDisplay(in: root.bounds) {
                        root.cacheDisplay(in: root.bounds, to: bitmap)
                        try? bitmap.representation(using: .png, properties: [:])?
                            .write(to: pngDirectory.appendingPathComponent("dialog-settings-markdown.png"), options: .atomic)
                    }
                }
                current.close()
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { step() }
            }
        }
        step()
    }

    /// Enthält der Baum die Einstellungs-Sonde (`SettingsWindowProbe`)?
    private static func markerViewExists(probe view: NSView) -> Bool {
        if view is SettingsWindowProbe { return true }
        return view.subviews.contains { markerViewExists(probe: $0) }
    }

    /// Sichtbare Bedienelemente ohne Ausdehnung — das Bild eines Pickers,
    /// den SwiftUI bei Platzmangel auf null Breite drückt.
    private static func collectCollapsedControls(in view: NSView, into result: inout [String]) {
        if view.isHidden { return }
        if view is NSControl, view.frame.width < 1 || view.frame.height < 1 {
            result.append("\(type(of: view)) \(view.frame)")
        }
        for sub in view.subviews { collectCollapsedControls(in: sub, into: &result) }
    }

    // MARK: - searchfocus: Suchfeld hat nach jedem Öffnen den Fokus

    /// Die Maske in allen drei Bereichen schließen und neu öffnen. Jedes Mal
    /// muss das Suchfeld First Responder sein, auch wenn vorher „Ausschlüsse“
    /// fokussiert war. AppKits Tab-Reihenfolge allein genügt dafür nicht.
    private static func runSearchFocusTest() {
        testLabel = "searchfocus"
        guard let ws = Workspace.shared,
              let searchWindow = NSApp.windows.first(where: {
                  $0.frameAutosaveName == SearchWindow.frameAutosaveName
              }),
              let root = searchWindow.contentView else {
            finish(false, "Workspace oder Suchfenster fehlt")
        }
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-searchfocus-\(UUID().uuidString)")
        shortSearchFixtureDirectory = directory
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            try "alpha\n".write(to: directory.appendingPathComponent("sample.txt"),
                                atomically: true, encoding: .utf8)
        } catch { finish(false, "Fokus-Fixture: \(error.localizedDescription)") }
        ws.openProject(at: directory)
        ws.recentSearchFolders = [SearchFolderEntry(path: directory.path, enabled: true)]

        func findField() -> RegexFieldTextView? {
            var fields: [NSView] = []
            collectTypeableFields(in: root, into: &fields)
            return fields.compactMap { $0 as? RegexFieldTextView }
                .first { $0.accessibilityIdentifier() == "fastra.findField" }
        }
        func focusIsFindField() -> Bool {
            guard let field = findField() else { return false }
            return searchWindow.isVisible && searchWindow.firstResponder === field
        }

        // Ablauf: (Notification, Erwartung an den Bereich, Vorbereitung)
        let steps: [(String, Notification.Name, Workspace.SearchScope)] = [
            ("⌘F nach Schließen", .fastraShowSearchFile, .file),
            ("⇧⌘F mit Projekt nach Schließen", .fastraShowSearchFolder, .project),
            ("⇧⌘F erneut nach Klick in Ausschlüsse und Schließen", .fastraShowSearchFolder, .project),
            ("Menü „In Projekt oder Ordnern suchen…“ bei offener Maske", .fastraShowSearchFolderForced, .project),
        ]
        var index = 0
        func runStep() {
            guard index < steps.count else {
                finish(true, "\(steps.count) Öffnungen: Suchfeld war jedes Mal First Responder "
                    + "(Datei und Projekt, auch nach Klick in Ausschlüsse)")
            }
            let (label, name, expectedScope) = steps[index]
            index += 1
            // Vor Schritt 3 und 4 „Ausschlüsse“ fokussieren und den Fokus bestätigen.
            // Schritt 4 holt die bereits offene Maske nur vor; ohne diesen Vorzustand
            // könnte der Test mit dem Suchfokus aus Schritt 3 unverdient bestehen.
            if index >= 3 {
                guard let exclusions = editableTextField(id: "fastra.projectExclusions", in: root),
                      searchWindow.makeFirstResponder(exclusions),
                      !focusIsFindField() else {
                    finish(false, "\(label): Fokus ließ sich nicht auf „Ausschlüsse“ legen")
                }
            }
            // Bei den ersten drei Schritten die Maske vorher schließen; der
            // letzte Schritt holt die offene Maske nur nach vorn.
            guard index < 4 else {
                NotificationCenter.default.post(name: name, object: ws)
                pollSearchFocus(label: label, expectedScope: expectedScope, ws: ws,
                                focused: focusIsFindField, next: runStep)
                return
            }
            ws.findPattern = ""
            ws.showSearchDialog = false
            // Das Ausblenden läuft über SwiftUI-onChange → orderOut; unter
            // Last kann das länger als einen Durchlauf dauern. Bis zu 20
            // Prüfläufe warten.
            pollSearchHidden(searchWindow) { hidden in
                guard hidden else {
                    finish(false, "\(label): Maske wurde nicht ausgeblendet "
                        + "(showSearchDialog=\(ws.showSearchDialog), visible=\(searchWindow.isVisible))")
                }
                NotificationCenter.default.post(name: name, object: ws)
                pollSearchFocus(label: label, expectedScope: expectedScope, ws: ws,
                                focused: focusIsFindField, next: runStep)
            }
        }
        runStep()
    }

    /// Nur bediente Durchläufe zählen (20 à 0,1 s). Eine absolute Wanduhrfrist
    /// kann durch fremde Main-Thread-Arbeit verstreichen, ohne dass der Test
    /// überhaupt prüfen konnte.
    private static func pollSearchHidden(_ window: NSWindow,
                                         completion: @escaping (Bool) -> Void) {
        waitFor(budget: 2, pause: 0.1,
                condition: { !window.isVisible },
                onTimeout: { _ in completion(false) },
                then: { completion(true) })
    }

    private static func pollSearchFocus(label: String, expectedScope: Workspace.SearchScope,
                                        ws: Workspace, focused: @escaping () -> Bool,
                                        next: @escaping () -> Void) {
        waitFor(budget: 2, pause: 0.05,
                condition: focused,
                onTimeout: { book in
                    finish(false, "\(label): Suchfeld nicht First Responder "
                        + "(FirstResponder=\(String(describing: NSApp.keyWindow?.firstResponder))) — \(book.summary)")
                },
                then: {
                    guard ws.scope == expectedScope else {
                        finish(false, "\(label): Bereich \(ws.scope.rawValue), erwartet \(expectedScope.rawValue)")
                    }
                    // Erst im nächsten Durchlauf schließen. `showSearchDialog` direkt wieder
                    // auf `false` zu setzen würde SwiftUI zu true→false zusammenfassen;
                    // `onChange` sähe keine Änderung und ließe die Maske sichtbar.
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { next() }
                })
    }

    private static func runSearchApprovalTest(closeOnly: Bool = false) {
        testLabel = closeOnly ? "searchapprovalclose" : "searchapproval"
        Task { @MainActor in
            guard let ws = Workspace.shared, let window = CommandTargeting.registeredWindow(for: ws),
                  let search = NSApp.windows.first(where: { $0.frameAutosaveName == SearchWindow.frameAutosaveName }) else {
                finish(false, "Dokument- oder Suchfenster fehlt")
            }
            var stage = "Fixture"
            let originalAppearance = NSApp.appearance
            var permissionFixtures: [URL] = []
            @MainActor func cleanup() {
                NSApp.appearance = originalAppearance
                for file in permissionFixtures {
                    try? FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: file.path)
                }
            }
            func require(_ value: Bool, _ message: String) throws {
                if !value { throw NSError(domain: "SearchApprovalSelfTest", code: 1, userInfo: [NSLocalizedDescriptionKey: message]) }
            }
            func requireValue<T>(_ value: T?, _ message: String) throws -> T {
                guard let value else { throw NSError(domain: "SearchApprovalSelfTest", code: 2, userInfo: [NSLocalizedDescriptionKey: message]) }
                return value
            }
            @MainActor func wait(_ detail: String = "Zustand", _ condition: @MainActor () -> Bool) async throws {
                var budget = SelfTestPollBudget(budget: 10, pause: 0.03, hardCap: 18,
                    now: ProcessInfo.processInfo.systemUptime)
                while !condition() {
                    try require(budget.recordMiss(now: ProcessInfo.processInfo.systemUptime) == .keepWaiting,
                                "Zustand wurde nicht bereit: " + stage + " / " + detail + " (aktiv=\(NSApp.isActive), Key=\(NSApp.keyWindow?.frameAutosaveName ?? "nil"), HauptfensterKey=\(window.isKeyWindow), Editorfokus=\(window.firstResponder === CommandTargeting.editorTextView(for: ws)), Undo=\(CommandTargeting.editorTextView(for: ws)?.undoManager?.canUndo == true), Redo=\(CommandTargeting.editorTextView(for: ws)?.undoManager?.canRedo == true), Text=\(String(reflecting: ws.activeTab.map { String($0.content.prefix(120)) })), Freigaben=\(ws.searchApproval.approvedIDs.count))")
                    try await Task.sleep(for: .milliseconds(30))
                }
            }
            @MainActor func click(_ id: String, in target: NSWindow) throws {
                guard let root = target.contentView, let marker = markerView(id: id, in: root) else {
                    try require(false, "Bedienelement fehlt: " + id); return
                }
                target.makeKeyAndOrderFront(nil)
                let rect = marker.convert(marker.bounds, to: nil)
                try require(sendMouseClick(at: NSPoint(x: rect.midX, y: rect.midY), in: target, modifiers: [], viaApp: true),
                            "Klick fehlgeschlagen: " + id)
            }
            @MainActor func checkbox(_ id: String) throws -> NSButton {
                func find(in view: NSView) -> NSButton? {
                    if let button = view as? NSButton, button.accessibilityIdentifier() == id + "-control" { return button }
                    for child in view.subviews { if let found = find(in: child) { return found } }
                    return nil
                }
                guard let root = search.contentView, let button = find(in: root) else {
                    throw NSError(domain: "SearchApprovalSelfTest", code: 4, userInfo: [NSLocalizedDescriptionKey: "Native Checkbox fehlt: " + id])
                }
                return button
            }
            @MainActor func sheet() -> NSWindow? {
                search.sheets.first { $0.contentView.flatMap { markerView(id: "searchApprovalSheet", in: $0) } != nil }
            }
            @MainActor func capture(_ name: String, in target: NSWindow) async throws {
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_SEARCHLAYOUT_DIR"] else { return }
                // Ein View-Cache lässt AppKits Sheet-Hintergrund transparent
                // und zeichnet native Knöpfe ohne ihren Bildschirm-Verbund.
                let snapshot: TypeScrollSnapshot? = await withCheckedContinuation { continuation in
                    typeScrollCapture(window: target) { continuation.resume(returning: $0) }
                }
                guard let snapshot, snapshot.source == "screen" else {
                    cleanup()
                    finish(.environment, "Echte Fensteraufnahme fehlt; Aufnahmediagnose im Testlog: " + name)
                }
                let output = URL(fileURLWithPath: directory).appendingPathComponent(name + ".png")
                try FileManager.default.createDirectory(at: output.deletingLastPathComponent(), withIntermediateDirectories: true)
                try snapshot.data.write(to: output)
                FileHandle.standardError.write(Data(("SEARCH_APPROVAL_CAPTURE " + name + " source=" + snapshot.source + "\n").utf8))
            }
            @MainActor func captureMatrix(_ name: String, in target: NSWindow, minimumWidth: CGFloat, minimumHeight: CGFloat) async throws {
                for (mode, appearance) in [("light", NSAppearance.Name.aqua), ("dark", .darkAqua)] {
                    NSApp.appearance = NSAppearance(named: appearance)
                    for width in [minimumWidth, 1000] {
                        target.setContentSize(NSSize(width: width, height: minimumHeight))
                        try await Task.sleep(for: .milliseconds(350))
                        try require(abs((target.contentView?.bounds.width ?? 0) - width) < 1, "Angeforderte Breite fehlt")
                        try await capture(name + "-" + mode + "-" + String(Int(width)), in: target)
                    }
                }
            }
            @MainActor func preview() async throws -> NSWindow {
                try await wait { search.contentView.flatMap { markerView(id: "searchApprovalPreviewReady", in: $0) } != nil }
                try click("searchApprovalPreview", in: search)
                try await wait { sheet()?.contentView.flatMap { markerView(id: "searchApprovalApplyReady", in: $0) } != nil }
                return sheet()!
            }
            @MainActor func approve(_ id: UUID) async throws {
                let marker = "searchApprove-" + id.uuidString
                try await wait("Checkbox aktiviert") { (try? checkbox(marker).isEnabled) == true }
                try click(marker, in: search)
                try await wait("Checkbox angewählt") { ws.searchApproval.approvedIDs.contains(id) && (try? checkbox(marker).state) == .on }
            }
            @MainActor func ready(_ scope: Workspace.SearchScope) async throws {
                ws.scope = scope
                try await wait {
                    guard ws.searchApproval.isComplete, let id = ws.navMatches.first?.id, let root = search.contentView else { return false }
                    return markerView(id: "searchApprove-" + id.uuidString, in: root) != nil
                }
            }
            do {
                let fixtureDirectory = selfTestTemporaryDirectory().appendingPathComponent("Freigaben-\(UUID().uuidString)")
                shortSearchFixtureDirectory = fixtureDirectory
                try FileManager.default.createDirectory(at: fixtureDirectory, withIntermediateDirectories: true)
                // canonicalPathKey löst erst vorhandene Pfade auf; sonst
                // vergleicht der Test /tmp mit dem enumerierten /private/tmp.
                let root = fixtureDirectory.canonicalFileURL
                shortSearchFixtureDirectory = root
                let a = root.appendingPathComponent("A.txt"), b = root.appendingPathComponent("B.txt"), ro = root.appendingPathComponent("Z-read-only.txt")
                let diskOriginal = Data("foo\r\nfoo\n".utf8)
                try diskOriginal.write(to: a); try Data("foo\n".utf8).write(to: b); try Data("foo\n".utf8).write(to: ro)
                try FileManager.default.setAttributes([.posixPermissions: 0o400], ofItemAtPath: ro.path)
                permissionFixtures.append(ro)
                ws.openProject(at: root)
                ws.recentSearchFolders = [SearchFolderEntry(path: root.path, enabled: true)]
                let first = EditorTab(title: "Erstes.txt", path: "", content: "foo\n🙂 foo\n")
                let second = EditorTab(title: "Zweites.txt", path: "", content: "foo\nfoo\n")
                let locked = EditorTab(title: "Read-only.txt", path: "", content: "foo\n", readOnlyReason: "Selftest")
                ws.tabs = [first, second, locked]; ws.activeTabID = first.id
                ws.findPattern = "foo"; ws.replacePattern = "bar"; ws.useRegex = false
                ws.showSearchDialog = true
                @MainActor func closeDuringSynchronization() async throws {
                    stage = "Schließen während WebKit-Synchronisierung"
                    var markdown = EditorTab(title: "Cancel.md", path: "", content: "# foo\n\nfoo\n")
                    markdown.markdownVisualOverride = true
                    ws.tabs = [markdown]; ws.activeTabID = markdown.id
                    try await ready(.file)
                    try await wait("WebKit bereit") { ws.visualMarkdownEditor?.ready == true }
                    try await approve(ws.navMatches[0].id)
                    let target = try await preview()
                    let before = try requireValue(ws.activeTab?.content, "Quellbasis fehlt")
                    try require(before == markdown.content && ws.lastSearchApprovalMemoryChange == nil, "Quellbasis änderte sich schon vor Apply")
                    guard let web = ws.visualMarkdownEditor?.web else { try require(false, "WebKit fehlt"); return }
                    var busyFinished = false
                    // Hält nur den getrennten Webprozess kurz auf, damit der
                    // native Schließenklick vor der PrepareAction-Antwort läuft.
                    web.callAsyncJavaScript("const end = Date.now() + 1000; while (Date.now() < end) {} return true;",
                        arguments: [:], in: nil, in: .page) { _ in busyFinished = true }
                    try click("searchApprovalApply", in: target)
                    try await wait("Sichtbare Apply-Vorbereitung") {
                        sheet() === target && target.contentView.flatMap { markerView(id: "searchApprovalPreparing", in: $0) } != nil
                    }
                    try require(!busyFinished, "WebKit-Antwort war bereits vor dem Abbrechen fertig")
                    try require(ws.activeTab?.content == before && ws.lastSearchApprovalMemoryChange == nil,
                                "Apply war bereits vor dem Abbrechen beendet")
                    try click("searchApprovalClose", in: target)
                    try await wait("Sheet geschlossen und WebKit-Antwort beendet") { sheet() == nil && busyFinished }
                    try await Task.sleep(for: .milliseconds(700))
                    let evidence = "vorher=\(String(reflecting: before)), nachher=\(String(reflecting: ws.activeTab?.content)), Speicheränderung=\(ws.lastSearchApprovalMemoryChange != nil)"
                    FileHandle.standardError.write(Data(("SEARCH_APPROVAL_CLOSE " + evidence + "\n").utf8))
                    try require(ws.activeTab?.content == before, "Quelle änderte sich nach Abbrechen: " + evidence)
                    try require(ws.lastSearchApprovalMemoryChange == nil, "Geschlossene Vorschau hinterließ eine Speicheränderung: " + evidence)
                }
                if closeOnly {
                    try await closeDuringSynchronization()
                    cleanup()
                    finish(true, "Natives Schließen während der realen WebKit-Synchronisierung verhindert verspätetes Apply")
                }
                stage = "Layout und Checkboxen"
                for scope in Workspace.SearchScope.allCases {
                    stage = "Layout und Checkboxen · " + scope.rawValue
                    try await ready(scope)
                    try click("searchApproveNone", in: search)
                    try await wait { ws.searchApproval.approvedIDs.isEmpty }
                    let hit = try requireValue(ws.navMatches.first(where: { ws.editableSearchMatchIDs.contains($0.id) && (!scope.isFolderLike || $0.url == a) }),
                        "Treffer fehlt (\(ws.navMatches.count) Treffer, \(ws.editableSearchMatchIDs.count) editierbar)")
                    let active = ws.activeMatchIndex
                    try await approve(hit.id)
                    try require(ws.activeMatchIndex == active, "Freigabe löst eine Treffernavigation aus")
                    let groupID = scope == .file ? "buffer" : scope == .open ? first.id.uuidString : a.path
                    let groupMarker = "searchApproveFile-" + groupID
                    try await wait { (try? checkbox(groupMarker).state) == .mixed }
                    try require(try checkbox(groupMarker).state == .mixed, "Dateifreigabe zeigt keinen Teilzustand")
                    try click(groupMarker, in: search)
                    try await wait { ws.searchApproval.approvedIDs.count == 2 }
                    try click(groupMarker, in: search)
                    try await wait { ws.searchApproval.approvedIDs.isEmpty }
                    try await approve(hit.id)
                    for (mode, appearance) in [("light", NSAppearance.Name.aqua), ("dark", .darkAqua)] {
                        NSApp.appearance = NSAppearance(named: appearance)
                        for width in [max(520, search.contentMinSize.width), 1000] {
                            search.setContentSize(NSSize(width: width, height: 760))
                            try await Task.sleep(for: .milliseconds(350))
                            guard let content = search.contentView else { try require(false, "Suchinhalt fehlt"); continue }
                            var outside: [String] = []
                            collectControlsOutside(content.bounds.insetBy(dx: -1, dy: -1), in: content, root: content, into: &outside)
                            try require(outside.isEmpty, "\(scope.rawValue)/\(mode)/\(width): Controls außerhalb: \(outside.prefix(3))")
                            for id in ["fastra.findField", "fastra.replaceField"] {
                                try require((markerView(id: id, in: content)?.bounds.width ?? 0) >= 100, "Feld zu schmal: " + id)
                            }
                            try await capture("approval-\(scope.rawValue)-\(mode)-\(Int(width))", in: search)
                        }
                    }
                    try click("searchApproveAll", in: search)
                    try await wait { ws.searchApproval.approvedIDs == ws.editableSearchMatchIDs }
                    try require(ws.searchApproval.approvedIDs.count == (scope == .file ? 2 : scope == .open ? 4 : 3), "Alle erfasst schreibgeschützte Treffer oder lässt editierbare aus")
                    try click("searchApproveNone", in: search)
                    try await wait { ws.searchApproval.approvedIDs.isEmpty }
                }
                NSApp.appearance = NSAppearance(named: .aqua)
                stage = "Datei: vollständige Teilfreigabevorschau"
                try await ready(.file)
                let selected = ws.navMatches[1].id
                try await approve(selected)
                let fileSheet = try await preview()
                try require(ws.activeTab?.content == first.content, "Vorschau ändert den Speicher")
                for (mode, appearance) in [("light", NSAppearance.Name.aqua), ("dark", .darkAqua)] {
                    NSApp.appearance = NSAppearance(named: appearance)
                    for width in [CGFloat(620), 1000] {
                        fileSheet.setContentSize(NSSize(width: width, height: width == 620 ? 440 : 650))
                        try await Task.sleep(for: .milliseconds(300))
                        try await capture("approval-preview-\(mode)-\(Int(width))", in: fileSheet)
                    }
                }
                try click("searchApprovalApply", in: fileSheet)
                try await wait { sheet() == nil && ws.activeTab?.content == "foo\n🙂 bar\n" }
                stage = "Datei: Dokumentfokus vor nativem Undo"
                guard let close = search.standardWindowButton(.closeButton) else { try require(false, "Schließenknopf der Suchmaske fehlt"); return }
                let closePoint = close.convert(NSPoint(x: close.bounds.midX, y: close.bounds.midY), to: nil)
                try require(sendMouseClick(at: closePoint, in: search, modifiers: [], viaApp: true), "Suchmaske nicht schließbar")
                try await wait("Suchmaske tatsächlich geschlossen") { !search.isVisible && !ws.showSearchDialog }
                window.makeKeyAndOrderFront(nil)
                try await wait("Montierter Editor zeigt Apply") {
                    CommandTargeting.editorTextView(for: ws)?.window === window
                        && CommandTargeting.editorTextView(for: ws)?.string == "foo\n🙂 bar\n"
                }
                guard let editor = CommandTargeting.editorTextView(for: ws) else { try require(false, "Editor fehlt"); return }
                try require(window.makeFirstResponder(nil), "Alter Fokus ließ sich nicht freigeben")
                let visible = editor.visibleRect
                let editorPoint = editor.convert(NSPoint(x: visible.minX + min(100, visible.width / 2),
                    y: visible.minY + min(20, visible.height / 2)), to: nil)
                try require(sendMouseClick(at: editorPoint, in: window, modifiers: [], viaApp: true), "Nativer Editorklick fehlt")
                try await wait("Hauptfenster/Editorfokus und Undo verfügbar") {
                    NSApp.keyWindow === window && window.isKeyWindow && window.firstResponder === editor && editor.undoManager?.canUndo == true
                }
                stage = "Datei: erste native Rücknahme"
                postHistoryKey(windowNumber: window.windowNumber)
                try await wait("Originaltext nach Cmd-Z") { ws.activeTab?.content == first.content }
                stage = "Datei: natives Wiederholen"
                try await wait("Redo verfügbar") { editor.undoManager?.canRedo == true }
                try await redoFromEditMenu()
                try await wait("Apply-Text nach Redo-Menü") { ws.activeTab?.content == "foo\n🙂 bar\n" }
                stage = "Datei: zweite native Rücknahme"
                var secondUndoMethod = "menu"
                let historyDirectory = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"].map { URL(fileURLWithPath: $0) }
                if try await requestSystemUndoIfAvailable(before: "foo\n🙂 bar\n", expected: first.content, mode: "undo-after-redo") {
                    secondUndoMethod = "system-command-z"
                } else {
                    try await undoFromEditMenu()
                }
                try await wait("Originaltext nach zweiter nativer Rücknahme (" + secondUndoMethod + ")") { ws.activeTab?.content == first.content }
                if let historyDirectory {
                    try FileManager.default.createDirectory(at: historyDirectory, withIntermediateDirectories: true)
                    let proof: [String: Any] = ["firstUndo": "appkit-command-z", "redo": "appkit-menu-action", "secondUndo": secondUndoMethod,
                        "originalRestored": ws.activeTab?.content == first.content]
                    try JSONSerialization.data(withJSONObject: proof, options: [.sortedKeys]).write(
                        to: historyDirectory.appendingPathComponent("native-history.json"), options: .atomic)
                }
                stage = "Geöffnet: zwei Dokumente und gemeinsame Rücknahme"
                ws.showSearchDialog = true
                try await ready(.open)
                let one = try requireValue(ws.navMatches.first(where: { $0.tabID == first.id }), "Erster Dokumenttreffer fehlt")
                let two = try requireValue(ws.navMatches.first(where: { $0.tabID == second.id }), "Zweiter Dokumenttreffer fehlt")
                try await approve(one.id); try await approve(two.id)
                let openSheet = try await preview()
                try click("searchApprovalApply", in: openSheet)
                try await wait { sheet() == nil && ws.tabs.first(where: { $0.id == second.id })?.content == "bar\nfoo\n" }
                try require(ws.tabs.first(where: { $0.id == first.id })?.content == "bar\n🙂 foo\n", "Falscher Treffer im ersten Dokument")
                try require(ws.tabs.first(where: { $0.id == locked.id })?.content == locked.content, "Read-only-Tab verändert")
                try click("searchApprovalMemoryUndo", in: search)
                try await wait { ws.tabs.first(where: { $0.id == first.id })?.content == first.content && ws.tabs.first(where: { $0.id == second.id })?.content == second.content }
                stage = "Ordner: Teilfreigabe, Platte und Backup-Undo"
                try await ready(.folder)
                let diskHits = ws.navMatches.filter { $0.url == a }
                try require(diskHits.count == 2, "Dateitreffer fehlen")
                let diskHit = diskHits[1]
                try await approve(diskHit.id)
                let diskSheet = try await preview()
                try click("searchApprovalApply", in: diskSheet)
                try await wait { !ws.folderApplying && ws.lastApplySession != nil }
                try require(try Data(contentsOf: a) == Data("foo\r\nbar\n".utf8), "Nicht freigegebener Treffer verändert")
                try require(try Data(contentsOf: b) == Data("foo\n".utf8) && Data(contentsOf: ro) == Data("foo\n".utf8), "Nicht freigegebene Datei verändert")
                let diskUndoWasMounted = search.contentView.flatMap { markerView(id: "searchApprovalDiskUndo", in: $0) } != nil
                let diskUndoWaitStart = ProcessInfo.processInfo.systemUptime
                // Der fertige Plattenauftrag garantiert noch keinen SwiftUI-Render.
                // Erst das geschlossene Sheet und der sichtbare Knopf erlauben den Klick.
                try await wait("Backup-Rückgängig montiert und Sheet geschlossen") {
                    sheet() == nil && search.contentView.flatMap { markerView(id: "searchApprovalDiskUndo", in: $0) } != nil
                }
                if let directory = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] {
                    let proof: [String: Any] = ["mountedAfterModelCompletion": diskUndoWasMounted,
                        "mountedBeforeClick": true, "sheetClosedBeforeClick": sheet() == nil,
                        "waitMilliseconds": (ProcessInfo.processInfo.systemUptime - diskUndoWaitStart) * 1000]
                    try JSONSerialization.data(withJSONObject: proof, options: [.sortedKeys]).write(
                        to: URL(fileURLWithPath: directory).appendingPathComponent("disk-undo-readiness.json"), options: .atomic)
                }
                try click("searchApprovalDiskUndo", in: search)
                try await wait { !ws.folderApplying && (try? Data(contentsOf: a)) == diskOriginal }
                stage = "Veraltetes Sheet und reale neue Suchoption"
                try await ready(.file)
                try await approve(ws.navMatches[0].id)
                let staleSheet = try await preview()
                ws.tabs[0].content = "external foo\n"
                try await wait { staleSheet.contentView.flatMap { markerView(id: "searchApprovalApplyBlocked", in: $0) } != nil }
                try await captureMatrix("approval-stale", in: staleSheet, minimumWidth: 620, minimumHeight: 440)
                try click("searchApprovalClose", in: staleSheet)
                try await wait { sheet() == nil && ws.searchApproval.isComplete }
                try await approve(ws.navMatches[0].id)
                guard let field = search.contentView.flatMap({ markerView(id: "fastra.replaceField", in: $0) }) as? NSTextView else { try require(false, "Ersetzen-Feld fehlt"); return }
                search.makeKeyAndOrderFront(nil); try require(search.makeFirstResponder(field), "Ersetzen-Fokus fehlt")
                field.selectAll(nil)
                for (text, code) in [("b", UInt16(11)), ("a", 0), ("z", 6)] { postKey(text, keyCode: code, windowNumber: search.windowNumber) }
                try await wait { ws.replacePattern == "baz" && ws.searchApproval.approvedIDs.isEmpty }
                stage = "Geöffnet: tatsächliche Trefferkappung"
                let many = String(repeating: "foo\n", count: 6000)
                let manyA = EditorTab(title: "LimitedA.txt", path: "", content: many)
                let manyB = EditorTab(title: "LimitedB.txt", path: "", content: many)
                ws.tabs = [manyA, manyB]; ws.activeTabID = manyA.id
                ws.scope = .open; ws.replacePattern = "bar"
                try await wait("Gekappte Geöffnet-Liste sichtbar") {
                    !ws.bufferSearching && ws.openResultsWereCapped && search.contentView.flatMap { markerView(id: "searchCappedResults", in: $0) } != nil
                }
                try require(ws.searchApproval.ticket == nil && !ws.searchApproval.isComplete, "Gekappte Geöffnet-Liste ist freigabefähig")
                try await captureMatrix("approval-capped-open", in: search, minimumWidth: max(520, search.contentMinSize.width), minimumHeight: 760)
                stage = "Ordner: Kappung pro Datei unter dem Gesamtlimit"
                try Data(String(repeating: "foo\n", count: 6000).utf8).write(to: a, options: .atomic)
                ws.scope = .folder
                try await wait("Kappung pro Datei sichtbar") {
                    !ws.folderSearching && ws.folderResultsContainCappedFiles && !ws.folderResultsWereCapped
                        && search.contentView.flatMap { markerView(id: "searchCappedResults", in: $0) } != nil
                }
                try require(ws.navMatches.count == 5002 && ws.folderTotalMatches == 6002,
                            "Falsche sichtbare/gezählte Trefferzahl bei Kappung pro Datei")
                try require(!ws.searchApproval.isComplete && ws.searchApproval.ticket == nil, "Teilweise Dateiliste ist freigabefähig")
                try await captureMatrix("approval-capped-file", in: search, minimumWidth: max(520, search.contentMinSize.width), minimumHeight: 760)
                stage = "Ordner: tatsächliche Gesamtkappung"
                try Data(String(repeating: "foo\n", count: 12_000).utf8).write(to: a, options: .atomic)
                ws.runFolderSearchNow()
                try await wait("Gekappte Ordnerliste sichtbar") {
                    !ws.folderSearching && ws.folderResultsWereCapped && search.contentView.flatMap { markerView(id: "searchCappedResults", in: $0) } != nil
                }
                try require(ws.searchApproval.ticket == nil && !ws.searchApproval.isComplete, "Gekappte Ordnerliste ist freigabefähig")
                try await captureMatrix("approval-capped-folder", in: search, minimumWidth: max(520, search.contentMinSize.width), minimumHeight: 760)
                stage = "Fehlende Suchquelle"
                try diskOriginal.write(to: a, options: .atomic)
                ws.recentSearchFolders.append(SearchFolderEntry(path: root.appendingPathComponent("missing-source").path, enabled: true))
                try await wait("Fehlerhafte Quelle sichtbar") { !ws.folderSearching && ws.searchError != nil }
                try require(ws.searchApproval.ticket == nil && ws.folderResults.isEmpty, "Fehlerhafte Teilsuche ist freigabefähig")
                try await captureMatrix("approval-missing-source", in: search, minimumWidth: max(520, search.contentMinSize.width), minimumHeight: 760)
                stage = "Nicht lesbare und zu große Suchquellen"
                let unreadable = root.appendingPathComponent("Nicht-lesbar.txt"), large = root.appendingPathComponent("Zu-gross.txt")
                try Data("foo\n".utf8).write(to: unreadable)
                permissionFixtures.append(unreadable)
                try FileManager.default.setAttributes([.posixPermissions: 0o000], ofItemAtPath: unreadable.path)
                try require(FileManager.default.createFile(atPath: large.path, contents: Data()), "Große Fixture fehlt")
                let handle = try FileHandle(forWritingTo: large)
                try handle.truncate(atOffset: FileLoader.largeFileThreshold + 1)
                try handle.close()
                ws.recentSearchFolders = [SearchFolderEntry(path: root.path, enabled: true)]
                ws.runFolderSearchNow()
                try await wait("Erklärte unvollständige Suche sichtbar") {
                    !ws.folderSearching && ws.searchApprovalIncompleteFiles.count == 2
                        && search.contentView.flatMap { markerView(id: "searchIncompleteFiles", in: $0) } != nil
                }
                try require(ws.searchError == nil && !ws.searchApproval.isComplete && ws.searchApproval.ticket == nil,
                            "Unvollständige Dateien fehlen oder geben Apply frei")
                try await captureMatrix("approval-incomplete-files", in: search, minimumWidth: max(520, search.contentMinSize.width), minimumHeight: 760)
                cleanup()
                finish(true, "Native Treffer-/Dateifreigabe, Alle/Keine, 16 Bereich/Theme/Breite-Ansichten, vier vollständige Vorschauansichten, 24 Fehler-/Cap-Ansichten, Speicher-/Platten-Apply, natives Undo/Redo, gemeinsame Rücknahme, Read-only und Ticketentwertung bestanden")
            } catch { cleanup(); finish(false, stage + ": " + error.localizedDescription) }
        }
    }

    // MARK: - searchlayout: Geometrie der Suchmaske je Bereich und Breite

    /// Vermisst Datei, Geöffnet, Ordner und Projekt bei Mindestbreite und
    /// 1000 pt. Pro Kombination prüfen: einzeilige Tab-Beschriftungen unter
    /// 30 pt Höhe, alle Controls innerhalb des Fensters, mindestens 25 % Höhe
    /// für die Trefferliste abzüglich `wrappedOptionsRowHeight` bei Umbruch.
    ///
    /// Varianten: `plain` mit leeren Standardwerten; `regexGroups` mit acht
    /// fangenden Gruppen; `wildcards` mit acht Sternen. Die letzten beiden
    /// verwenden einen 60 Zeichen langen Vorlagen- und 70 Zeichen langen
    /// Datei-Set-Namen. Eingabefelder müssen mindestens 100 pt breit bleiben;
    /// die acht Pillen erreichen genau `PillTrayLayout.maxWidth` und scrollen.
    ///
    /// Mit `FASTRA_SEARCHLAYOUT_DIR` je Kombination ein PNG zur Sichtprüfung
    /// ablegen: `search-<bereich>-<breite>[-variante].png`.
    private static func runSearchLayoutTest() {
        testLabel = "searchlayout"
        guard let ws = Workspace.shared,
              let searchWindow = NSApp.windows.first(where: {
                  $0.frameAutosaveName == SearchWindow.frameAutosaveName
              }),
              let root = searchWindow.contentView else {
            finish(false, "Workspace oder Suchfenster fehlt")
        }
        // Projekt-Fixture, damit der Projekt-Bereich wählbar ist.
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-searchlayout-\(UUID().uuidString)")
        shortSearchFixtureDirectory = directory
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            try "alpha beta\n".write(to: directory.appendingPathComponent("sample.txt"),
                                     atomically: true, encoding: .utf8)
        } catch { finish(false, "Layout-Fixture: \(error.localizedDescription)") }
        ws.openProject(at: directory)
        ws.recentSearchFolders = [SearchFolderEntry(path: directory.path, enabled: true)]
        ws.useRegex = false
        ws.findPattern = ""
        ws.replacePattern = ""

        // Lange Nutzernamen: eigene Vorlage (in der isolierten Suite — die
        // Suchmaske lädt dieselbe Bibliothek) und ein Datei-Set des
        // temporären Projekts.
        let library = MainActor.assumeIsolated { PatternLibrary(defaults: workspaceDefaults()) }
        let longTemplateID = "selftest-searchlayout-langer-name"
        let longTemplate = PatternTemplate(
            id: longTemplateID,
            name: "Sehr lange eigene Vorlage mit einem Namen aus sechzig Zeichen",
            category: .words, regex: "(a)(b)(c)(d)(e)(f)(g)(h)", exampleMatch: "abcdefgh"
        )
        do { try MainActor.assumeIsolated { try library.save(longTemplate) } } catch {
            finish(false, "Layout-Fixture: Vorlage nicht speicherbar: \(error.localizedDescription)")
        }
        let longSet = ProjectFileSet(
            name: "Ein sehr langes Datei-Set mit siebzig Zeichen Namen für die Layoutprüfung",
            paths: ["."]
        )
        let defaultSetID = ws.projectSearchConfiguration.activeSetID
        ws.projectSearchConfiguration.fileSets.append(longSet)

        enum LayoutVariant: String, CaseIterable {
            case plain, regexGroups, wildcards
            var suffix: String { self == .plain ? "" : "-\(rawValue)" }
        }
        func apply(_ variant: LayoutVariant) {
            switch variant {
            case .plain:
                ws.useRegex = false
                ws.findPattern = ""
                ws.selectedTemplateID = nil
                ws.projectSearchConfiguration.activeSetID = defaultSetID
            case .regexGroups:
                ws.useRegex = true
                ws.findPattern = "(alpha)(beta)(gamma)(delta)(epsilon)(zeta)(eta)(theta)"
                ws.selectedTemplateID = longTemplateID
                ws.projectSearchConfiguration.activeSetID = longSet.id
            case .wildcards:
                ws.useRegex = false
                ws.findPattern = "a*b*c*d*e*f*g*h*"
                ws.selectedTemplateID = longTemplateID
                ws.projectSearchConfiguration.activeSetID = longSet.id
            }
        }

        let widths: [CGFloat] = [max(500, searchWindow.contentMinSize.width), 1000]
        var combinations: [(Workspace.SearchScope, CGFloat, LayoutVariant)] = []
        for variant in LayoutVariant.allCases {
            for scope in Workspace.SearchScope.allCases {
                for width in widths { combinations.append((scope, width, variant)) }
            }
        }
        let pngDirectory = ProcessInfo.processInfo.environment["FASTRA_SEARCHLAYOUT_DIR"]
            .map { URL(fileURLWithPath: $0) }
        // Dieselbe Stufe, die der Fensterrahmen per Environment weitergibt —
        // die Pillenreihe skaliert mit ihr, ihre Obergrenze also auch.
        let uiScale = UIZoom.scale(for: workspaceDefaults().integer(forKey: UIZoom.defaultsKey))
        let pillLimit = PillTrayLayout.maxWidth * uiScale
        var findings: [String] = []
        var index = 0

        func step() {
            guard index < combinations.count else {
                apply(.plain)
                MainActor.assumeIsolated { library.delete(id: longTemplateID) }
                // Test-Einstellungen vor `exit()` synchronisieren: AppKits Beenden-Hooks
                // laufen dabei nicht. Sonst kann die temporäre Vorlage für folgende Tests
                // erhalten bleiben (wie in `runSoakRounds`).
                workspaceDefaults().synchronize()
                finish(findings.isEmpty,
                       findings.isEmpty
                       ? "\(combinations.count) Bereich/Breite/Varianten-Kombinationen: Tabs "
                         + "einzeilig, alle Bedienelemente im Fenster, Felder ≥ 100 pt, "
                         + "Pillenreihe begrenzt, Trefferliste ≥ 25 % der Höhe"
                       : findings.joined(separator: " | "))
            }
            let (scope, width, variant) = combinations[index]
            index += 1
            apply(variant)
            ws.scope = scope
            var size = searchWindow.contentLayoutRect.size
            size.width = width
            size.height = max(700, searchWindow.contentMinSize.height)
            searchWindow.setContentSize(size)
            // Der Bereichswechsel animiert 0,22 s, und die ausgehende Fläche
            // des alten Bereichs bleibt währenddessen im Baum — eine Messung
            // nach 0,5 s traf sie noch (Dateitypen-Picker des Ordner-Bereichs
            // mit 670 pt Breite). Deshalb eine volle Sekunde warten.
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                root.layoutSubtreeIfNeeded()
                let label = "\(scope.rawValue)@\(Int(width))\(variant.suffix)"
                let bounds = root.bounds.insetBy(dx: -1, dy: -1)
                // Eingabefelder: Vorlagenmenü, Datei-Set-Picker und Pillen sind
                // `fixedSize`; die Felder müssen trotzdem bedienbar bleiben.
                for fieldID in ["fastra.findField", "fastra.replaceField"] {
                    guard let field = markerView(id: fieldID, in: root) else {
                        findings.append("\(label): \(fieldID) fehlt"); continue
                    }
                    let rect = field.convert(field.bounds, to: root)
                    if rect.width < 100 {
                        findings.append("\(label): \(fieldID) nur \(Int(rect.width)) pt breit")
                    }
                }
                if variant != .plain {
                    if let tray = markerView(id: "pillTray", in: root) {
                        let rect = tray.convert(tray.bounds, to: root)
                        // Rahmen der PillTray gegen die echte Obergrenze prüfen. Acht Pillen
                        // sind zusammen breiter als diese; die Reihe muss sie erreichen, statt auf
                        // null Breite zusammenzufallen.
                        if rect.width > pillLimit + 2 {
                            findings.append("\(label): Pillenreihe \(Int(rect.width)) pt breit "
                                + "statt höchstens \(Int(pillLimit))")
                        } else if rect.width < pillLimit - 2 {
                            findings.append("\(label): Pillenreihe nur \(Int(rect.width)) statt "
                                + "\(Int(pillLimit)) pt breit — acht Pillen füllen sie nicht")
                        }
                    } else {
                        findings.append("\(label): Pillenreihe fehlt")
                    }
                }
                for s in Workspace.SearchScope.allCases {
                    guard let tab = markerView(id: "scopeTab-\(s.rawValue)", in: root) else {
                        findings.append("\(label): Tab \(s.rawValue) fehlt"); continue
                    }
                    let rect = tab.convert(tab.bounds, to: root)
                    if rect.height >= 30 || rect.width < 20 {
                        findings.append("\(label): Tab \(s.rawValue) nicht einzeilig \(rect)")
                    }
                }
                var outside: [String] = []
                collectControlsOutside(bounds, in: root, root: root, into: &outside)
                if !outside.isEmpty {
                    findings.append("\(label): außerhalb des Fensters: " + outside.prefix(3).joined(separator: ", "))
                }
                if let list = markerView(id: "hitList", in: root) {
                    let rect = list.convert(list.bounds, to: root)
                    // Im Ordner-Bereich beanspruchen gemerkte Ordner zusätzliche Höhe.
                    // Der Trefferliste stehen mindestens 25 % der Fensterhöhe zu, abzüglich
                    // der tatsächlich gemessenen zweiten Optionszeile bei Umbruch.
                    let wrapped = wrappedOptionsRowHeight(in: root)
                    let required = root.bounds.height * 0.25 - wrapped
                    if rect.height < required {
                        findings.append("\(label): Trefferliste nur \(Int(rect.height)) von "
                            + "\(Int(root.bounds.height)) pt (verlangt \(Int(required)), "
                            + "Optionsumbruch \(Int(wrapped)) pt)")
                    }
                } else {
                    findings.append("\(label): Trefferlisten-Marker fehlt")
                }
                if let pngDirectory {
                    try? FileManager.default.createDirectory(at: pngDirectory, withIntermediateDirectories: true)
                    if let bitmap = root.bitmapImageRepForCachingDisplay(in: root.bounds) {
                        root.cacheDisplay(in: root.bounds, to: bitmap)
                        let file = pngDirectory.appendingPathComponent(
                            "search-\(scope.rawValue)-\(Int(width))\(variant.suffix).png")
                        try? bitmap.representation(using: .png, properties: [:])?
                            .write(to: file, options: .atomic)
                    }
                }
                step()
            }
        }
        step()
    }

    /// Höhe, die der Umbruch der Optionszeile kostet: der Abstand zwischen
    /// der Zeile des ersten Schalters („RegEx", Marker `searchOptionFirst`)
    /// und der Zeile von „∗ wörtlich" (Marker `wildcardLiteralOption-*`).
    /// Stehen beide in derselben Reihe, ist der Umbruch 0.
    private static func wrappedOptionsRowHeight(in root: NSView) -> CGFloat {
        func marker(prefix: String, in view: NSView) -> NSView? {
            if view.accessibilityIdentifier().hasPrefix(prefix) { return view }
            for sub in view.subviews {
                if let found = marker(prefix: prefix, in: sub) { return found }
            }
            return nil
        }
        guard let first = markerView(id: "searchOptionFirst", in: root),
              let literal = marker(prefix: "wildcardLiteralOption-", in: root) else { return 0 }
        let firstMidY = first.convert(first.bounds, to: root).midY
        let literalMidY = literal.convert(literal.bounds, to: root).midY
        let delta = abs(literalMidY - firstMidY)
        // Unter einer halben Schalterhöhe ist es dieselbe Reihe.
        return delta > 8 ? delta : 0
    }

    /// Sammelt Bedienelemente (NSControl, NSTextView), deren Rechteck über
    /// den Fensterinhalt hinausragt. Inhalte von ScrollViews sind ausgenommen:
    /// Dort ist Überstand normal und wird vom Clip abgeschnitten.
    private static func collectControlsOutside(_ bounds: NSRect, in view: NSView,
                                               root: NSView, into result: inout [String]) {
        if view is NSScrollView { return }
        if view is NSControl || view is NSTextView {
            let rect = view.convert(view.bounds, to: root)
            if rect.width > 0, rect.height > 0, !bounds.contains(rect) {
                result.append("\(type(of: view)) \(rect)")
            }
        }
        for sub in view.subviews {
            collectControlsOutside(bounds, in: sub, root: root, into: &result)
        }
    }

    /// Setzt die Fensterbreite bei fester linker oberer Ecke.
    private static func setSearchWindowWidth(_ window: NSWindow, _ width: CGFloat) {
        var frame = window.frame
        frame.size.width = max(width, window.contentMinSize.width)
        window.setFrame(frame, display: true)
    }

    /// Linke Kanten von „RegEx" und „Nur in Auswahl" in Root-Koordinaten;
    /// `nil`, wenn ein Marker fehlt oder „∗ wörtlich" nicht als deaktiviert
    /// gerendert ist.
    private static func searchOptionMarkerPoints(in root: NSView) -> (NSPoint, NSPoint)? {
        guard let first = markerView(id: "searchOptionFirst", in: root),
              let second = markerView(id: "searchOptionSecond", in: root),
              markerView(id: "wildcardLiteralOption-disabled-off", in: root) != nil else {
            return nil
        }
        return (first.convert(NSPoint.zero, to: root), second.convert(NSPoint.zero, to: root))
    }

    private static func pollSearchOptionsEnabled(_ ws: Workspace, root: NSView) {
        waitFor(budget: 2, pause: 0.05,
                condition: { markerView(id: "wildcardLiteralOption-enabled-off", in: root) != nil },
                onTimeout: { book in
                    finish(false, "∗ wörtlich wurde mit Plain-Text-Stern nicht aktiv — \(book.summary)")
                },
                then: {
                    ws.treatWildcardLiterally = true
                    ws.findPattern = "ab"
                    pollSearchOptionsReset(ws, root: root)
                })
    }

    private static func pollSearchOptionsReset(_ ws: Workspace, root: NSView) {
        waitFor(budget: 2, pause: 0.05,
                condition: {
                    markerView(id: "wildcardLiteralOption-disabled-off", in: root) != nil
                        && !ws.treatWildcardLiterally
                },
                onTimeout: { book in
                    finish(false, "∗ wörtlich blieb nach Entfernen des Sterns aktiv/gewählt — \(book.summary)")
                },
                then: { runShortFolderSearchOptionsTest(ws, root: root) })
    }

    /// Die Kurzsuche muss über die sichtbaren Bedienelemente funktionieren.
    /// Die Mindestbreite wird selbst gesetzt, nicht aus einem früheren Test geerbt.
    private static func runShortFolderSearchOptionsTest(_ ws: Workspace, root: NSView) {
        guard let window = root.window else { finish(false, "Suchfenster fehlt") }
        var size = window.contentLayoutRect.size
        size.width = window.contentMinSize.width
        size.height = max(size.height, window.contentMinSize.height)
        window.setContentSize(size)
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-short-search-\(UUID().uuidString)")
        shortSearchFixtureDirectory = directory
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            try "a ab\n".write(to: directory.appendingPathComponent("sample.txt"),
                               atomically: true, encoding: .utf8)
        } catch { finish(false, "Kurzsuch-Fixture: \(error.localizedDescription)") }
        ws.scope = .folder
        ws.recentSearchFolders = [SearchFolderEntry(path: directory.path, enabled: true)]
        ws.fileTypeFilter = .knownText
        ws.useRegex = false
        ws.wholeWord = false
        ws.findPattern = "a"
        pollShortSearchStep("Aufforderung für ein Zeichen", ready: {
            ws.waitingForShortFolderSearch
                && markerView(id: "shortFolderSearchPrompt", in: root) != nil
        }) {
            // Der Scope-Wechsel animiert alte und neue SwiftUI-Flächen kurz
            // gleichzeitig. Erst auslaufen lassen, dann neu messen und klicken.
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                root.layoutSubtreeIfNeeded()
                guard let button = markerView(id: "folderSearchButton", in: root),
                      let prompt = markerView(id: "shortFolderSearchPrompt", in: root) else {
                    finish(false, "Suchen-Knopf oder Kurzsuch-Hinweis fehlt")
                }
                // Beide Flächen müssen bei der kleinsten Fensterbreite vollständig
                // sichtbar bleiben; sonst wäre der Klick nur zufällig erfolgreich.
                for view in [button, prompt] {
                    let rect = view.convert(view.bounds, to: root)
                    guard rect.width > 0, rect.height > 0,
                          root.bounds.insetBy(dx: -1, dy: -1).contains(rect) else {
                        finish(false, "Kurzsuch-Bedienelement bei Mindestbreite abgeschnitten: \(rect)")
                    }
                }
                if let destination = ProcessInfo.processInfo.environment["FASTRA_SHORT_SEARCH_SCREENSHOT"] {
                    guard let bitmap = root.bitmapImageRepForCachingDisplay(in: root.bounds) else {
                        finish(false, "Suchfenster konnte nicht aufgenommen werden")
                    }
                    root.cacheDisplay(in: root.bounds, to: bitmap)
                    guard let png = bitmap.representation(using: .png, properties: [:]) else {
                        finish(false, "Suchfenster-PNG konnte nicht erzeugt werden")
                    }
                    do { try png.write(to: URL(fileURLWithPath: destination), options: .atomic) }
                    catch { finish(false, "Suchfenster-PNG konnte nicht gespeichert werden") }
                }
                let point = button.convert(NSPoint(x: button.bounds.midX, y: button.bounds.midY), to: nil)
                // Über die echte Event-Queue zustellen: Der AppKit-NSButton wartet beim
                // Mouse-down in seiner Tracking-Schleife auf das Mouse-up. Ein synchrones
                // `window.sendEvent` könnte dieses erst nach Rückkehr liefern und blockieren.
                guard sendMouseClick(at: point, in: window, modifiers: [], viaApp: true) else {
                    finish(false, "Mausklick auf Suchen nicht zustellbar")
                }
                pollShortSearchStep("Maus-Suche mit einem Zeichen", ready: {
                    !ws.folderSearching && !ws.folderNeedsSearch && ws.folderTotalMatches == 2
                        && markerView(id: "shortFolderSearchPrompt", in: root) == nil
                }) {
                    runShortSearchReturn(ws, root: root, pattern: "ab", expectedMatches: 1) {
                        runShortSearchReturn(ws, root: root, pattern: "zz", expectedMatches: 0) {
                            verifyShortSearchEmptyStates(ws, root: root)
                        }
                    }
                }
            }
        }
    }

    private static func runShortSearchReturn(_ ws: Workspace, root: NSView,
                                            pattern: String, expectedMatches: Int,
                                            completion: @escaping () -> Void) {
        var fields: [NSView] = []
        collectTypeableFields(in: root, into: &fields)
        guard let field = fields.compactMap({ $0 as? RegexFieldTextView }).first(where: {
            $0.accessibilityIdentifier() == "fastra.findField"
        }), let window = root.window, window.makeFirstResponder(field) else {
            finish(false, "Suchfeld für Return nicht fokussierbar")
        }
        // Echte Texteingabe mit sofortigem Return: der noch wartende Live-
        // Debounce darf den ausdrücklich gestarteten Lauf nicht zurücksetzen.
        field.setSelectedRange(NSRange(location: 0, length: field.string.utf16.count))
        field.insertText(pattern, replacementRange: field.selectedRange())
        field.insertNewline(nil)
        // Frühestens nach dem 120-ms-Debounce prüfen, auch wenn die winzige
        // Fixture schneller fertig ist. Sonst bliebe der Rücksetzfehler unsichtbar.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) {
            pollShortSearchStep("Return-Suche \(pattern)", ready: {
                ws.findPattern == pattern && !ws.folderSearching && !ws.folderNeedsSearch
                    && ws.folderTotalMatches == expectedMatches
                    && markerView(id: "shortFolderSearchPrompt", in: root) == nil
            }, completion: completion)
        }
    }

    private static func verifyShortSearchEmptyStates(_ ws: Workspace, root: NSView) {
        func hintVisible(_ text: String) -> Bool {
            markerView(id: "searchEmptyHint-\(L10n.string(text))", in: root) != nil
        }
        pollShortSearchStep("Abgeschlossene Kurzsuche ohne Treffer", ready: {
            hintVisible("Keine Treffer in den durchsuchten Ordnern.")
        }) {
            ws.folderMatchNavigationBecameStale()
            pollShortSearchStep("Veraltete Ergebnisse", ready: {
                hintVisible("Die Dateien wurden geändert. Erneut suchen, um aktuelle Treffer zu sehen.")
                    && markerView(id: "shortFolderSearchPrompt", in: root) == nil
            }) {
                ws.findPattern = ""
                pollShortSearchStep("Leere Eingabe", ready: {
                    hintVisible("Suchausdruck eingeben…") && !ws.waitingForShortFolderSearch
                }) {
                    ws.recentSearchFolders = []
                    ws.findPattern = "a"
                    pollShortSearchStep("Fehlende Suchwurzel", ready: {
                        hintVisible("Kein Ordner ausgewählt. Mindestens einen aktivieren.")
                            && !ws.waitingForShortFolderSearch
                    }) {
                        finish(true, "Optionen breit einzeilig, schmal zweizeilig/linksbündig; Kurzsuche per Maus und Return "
                            + "bei Mindestbreite; Abschluss-, Leer-, Wurzel- und Veraltet-Hinweise korrekt")
                    }
                }
            }
        }
    }

    private static func pollShortSearchStep(_ label: String,
                                           ready: @escaping () -> Bool,
                                           completion: @escaping () -> Void) {
        waitFor(budget: 5, pause: 0.05,
                condition: ready,
                onTimeout: { book in finish(false, "Kurzsuche: \(label) nicht erreicht — \(book.summary)") },
                then: completion)
    }

    /// Prüft den gemeldeten Alt-Treffer-Zustand am echten Projekt-Filterfeld:
    /// Ein AppKit-Einfügevorgang muss die gebundene Konfiguration ohne
    /// Debounce ändern. Noch im selben Main-Thread-Umlauf verschwinden die
    /// Treffer der vorherigen Semantik; Navigation, Vorschau und Apply bleiben
    /// bis zum neuen Ergebnis gesperrt. Die gemessene Dauer schützt außerdem
    /// davor, teure Projektarbeit versehentlich in den TextField-Setter zu
    /// verschieben.
    private static func runProjectInputTest() {
        testLabel = "projectinput"
        guard let ws = Workspace.shared,
              let searchWindow = NSApp.windows.first(where: {
                  $0.frameAutosaveName == SearchWindow.frameAutosaveName
              }),
              let root = searchWindow.contentView else {
            finish(false, "Workspace oder Suchfenster fehlt")
        }

        let fm = FileManager.default
        let projectRoot = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-projectinput-\(UUID().uuidString)")
        let file = projectRoot.appendingPathComponent("alt.txt")
        do {
            try fm.createDirectory(at: projectRoot, withIntermediateDirectories: true)
            try "ALTER_TREFFER".write(to: file, atomically: true, encoding: .utf8)
        } catch {
            try? fm.removeItem(at: projectRoot)
            finish(false, "Projekt-Fixture nicht schreibbar: \(error.localizedDescription)")
        }

        ws.openProject(at: projectRoot)
        ws.scope = .project
        ws.findPattern = "ALT"
        ws.useRegex = false

        // Konfigurationsänderungen auslaufen lassen, dann bewusst die alte
        // Trefferbasis injizieren. Bis zu 20 Mal auf das ausgelegte Feld warten,
        // damit ein verzögerter Bereichswechsel nicht als fehlendes Feld gilt.
        pollProjectExclusionsField(root: root) { found in
            guard let field = found else {
                ws.closeProject()
                try? fm.removeItem(at: projectRoot)
                finish(false, "Projekt-Ausschlussfeld nicht im echten Fenster gefunden")
            }
            let options = SearchOptions(find: "ALT", replace: "", isRegex: false)
            let match = BufferSearch.Match(
                range: NSRange(location: 0, length: 3),
                line: 1, column: 1, matchText: "ALT", replacedText: ""
            )
            ws.folderResults = [FolderSearch.PerFileResult(
                url: file, matches: [match], totalMatches: 1,
                skipped: nil, snapshot: nil, searchOptions: options
            )]
            ws.folderTotalMatches = 1
            MainActor.assumeIsolated {
                if let token = ws.beginSearchResultRun() {
                    ws.commitSearchResult(token, publication: .folder(.init(
                        perFile: ws.folderResults, invalidPatternMessage: nil, wasCapped: false)))
                }
            }
            guard ws.navMatches.count == 1 else {
                ws.closeProject()
                try? fm.removeItem(at: projectRoot)
                finish(false, "Alt-Treffer war vor der Eingabe nicht navigierbar")
            }
            guard searchWindow.makeFirstResponder(field),
                  let editor = field.currentEditor() as? NSTextView else {
                ws.closeProject()
                try? fm.removeItem(at: projectRoot)
                finish(false, "Projekt-Ausschlussfeld wurde nicht First Responder")
            }

            let insertionRange = NSRange(
                location: field.stringValue.utf16.count, length: 0
            )
            let started = ProcessInfo.processInfo.systemUptime
            editor.insertText(", userPreferences.*" as NSString,
                              replacementRange: insertionRange)
            let elapsed = ProcessInfo.processInfo.systemUptime - started
            let clearedSynchronously = ws.folderResults.isEmpty
                && ws.folderTotalMatches == 0
                && ws.navMatches.isEmpty
                && (ws.folderSearching || ws.folderNeedsSearch)
                && !ws.applyAllInFolder()
            let textArrived = field.stringValue.contains("userPreferences.*")
            let resultCount = ws.folderResults.count
            let navigationCount = ws.navMatches.count
            let searching = ws.folderSearching
            let needsSearch = ws.folderNeedsSearch

            ws.closeProject()
            try? fm.removeItem(at: projectRoot)
            guard textArrived, elapsed < 0.25, clearedSynchronously else {
                finish(false, String(
                    format: "Filtereingabe/Invalidierung fehlerhaft: Text=%@, %.3f s, "
                        + "Ergebnisse=%d, Navigation=%d, searching=%@, needs=%@",
                    textArrived ? "ok" : "fehlt", elapsed,
                    resultCount, navigationCount,
                    searching ? "ja" : "nein",
                    needsSearch ? "ja" : "nein"
                ))
            }
            finish(true, String(
                format: "echte Filtereingabe in %.3f s; Alt-Treffer, Navigation "
                    + "und Apply sofort invalidiert", elapsed
            ))
        }
    }

    /// Zählt nur bediente Durchläufe (20 à 0,1 s) wie `pollSearchHidden`:
    /// Fremdlast auf dem Main-Thread verbraucht die Frist nicht.
    private static func pollProjectExclusionsField(root: NSView,
                                                   completion: @escaping (NSTextField?) -> Void) {
        var field: NSTextField?
        waitFor(budget: 2, pause: 0.1,
                condition: {
                    field = editableTextField(id: "fastra.projectExclusions", in: root)
                    return field != nil
                },
                onTimeout: { _ in completion(nil) },
                then: { completion(field) })
    }

    private static func editableTextField(id: String, in view: NSView) -> NSTextField? {
        if let field = view as? NSTextField,
           field.isEditable, field.isEnabled,
           (field.accessibilityIdentifier() == id
            // SwiftUI hängt den Identifier je nach macOS-Version an seinen
            // Wrapper statt an das innere NSTextField. Der in Deutsch und
            // Englisch eindeutige Placeholder hält den End-to-End-Test dann
            // am selben produktiven Feld, ohne Feldreihenfolgen zu raten.
            || field.placeholderString?.contains("generated.swift") == true) {
            return field
        }
        for child in view.subviews {
            if let field = editableTextField(id: id, in: child) { return field }
        }
        return nil
    }

    /// Prüft, dass ein Tab-Wechsel (wie nach einem Datei-Drop) den Editor-
    /// Inhalt tatsächlich austauscht. Hintergrund: CodeEditSourceEditor setzt
    /// seinen Text nur in `makeNSViewController` — Binding-Änderungen werden
    /// nicht zurück in die TextView geschoben. Deshalb koppeln wir die View
    /// per `.id(activeTab.id)` an die Tab-ID, damit sie beim Tab-Wechsel neu
    /// erzeugt wird. Dieser Test belegt die Neuerzeugung über die Objekt-
    /// Identität der TextView (vorher ≠ nachher) und prüft, dass der aktive
    /// Tab den neuen Datei-Inhalt trägt. Genau der „Drop legt Tab an, zeigt
    /// aber keinen Inhalt"-Bug.
    private static func runTabSwitchTest() {
        testLabel = "tabswitch"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }) else {
            finish(false, "kein Hauptfenster gefunden")
        }

        waitForEditor(window: mainWindow) { root, tv1 in
            prepareTabSwitchTest(ws: ws, root: root, tv1: tv1)
        }
    }

    private static func prepareTabSwitchTest(ws: Workspace, root: NSView, tv1: TextView) {
        let id1 = ObjectIdentifier(tv1)
        // Genau der manuell gefundene Fehler: Eine kurze Auswahl aus Datei A
        // durfte beim Öffnen von Datei B nicht auf deren erste Zeichen
        // übertragen werden.
        tv1.selectionManager.setSelectedRange(NSRange(location: 0, length: 5))

        // Temp-Datei mit eindeutigem Markerinhalt anlegen und laden →
        // neuer Tab, activeTabID wechselt. loadFile ist jetzt asynchron
        // (v0.9): Folge-Schritte in der Completion, damit der Inhalt beim
        // Prüfen wirklich im Tab steht.
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-tabswitch-\(UUID().uuidString).txt")
        let marker = "TABSWITCH_MARKER_CONTENT"
        do { try marker.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        // Temp-Datei-Löschung in die Completion verschoben (war vorher sofort
        // nach loadFile — jetzt erst nach dem Laden, damit der Hintergrund-Task
        // die Datei noch lesen kann).
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else {
                finish(false, "loadFile schlug fehl (completion false)")
            }
            // SwiftUI Zeit geben, den Editor via `.id` neu zu erzeugen.
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                guard let tv2 = editorTextView(in: root) as? TextView else {
                    finish(false, "keine Editor-TextView nach dem Tab-Wechsel")
                }
                let recreated = ObjectIdentifier(tv2) != id1
                let modelOK = ws.activeTab?.content == marker
                let resultingSelections = tv2.selectionManager.textSelections
                    .map(\.range)
                // CESE kann bis zum ersten Fokus entweder noch keine
                // TextSelection oder bereits den Einfügepunkt (0, 0)
                // besitzen. Beides ist korrekt; entscheidend ist, dass keine
                // nichtleere Auswahl aus dem vorigen Tab übrig bleibt.
                let selectionOK = resultingSelections.allSatisfy {
                    $0.length == 0
                }
                if !recreated {
                    finish(false, "Editor-TextView NICHT neu erzeugt — Inhalt bliebe stehen (genau der Drop-Bug)")
                } else if !modelOK || tv2.string != marker {
                    finish(false, "Editor neu erzeugt, aber Modell und sichtbarer Text entsprechen nicht dem neuen Inhalt")
                } else if !selectionOK {
                    finish(false, "Auswahl aus dem vorigen Tab wurde übernommen: "
                        + "\(resultingSelections)")
                } else {
                    finish(true, "Editor neu erzeugt, neuer Inhalt und eigene Einfügemarke statt fremder Auswahl")
                }
            }
        }
    }

    // MARK: - -selftest tabclosehit / tabcompare

    private static func runTabCommitFocusTest() {
        testLabel = "tabcommitfocus"
        Task { @MainActor in
            guard let ws = Workspace.shared, let window = CommandTargeting.registeredWindow(for: ws) else {
                finish(false, "Dokumentfenster fehlt")
            }
            let original = window.contentView
            let backgroundWorkspace = Workspace()
            let backgroundWindow = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 700, height: 500),
                styleMask: [.titled, .closable], backing: .buffered, defer: false)
            backgroundWindow.isReleasedWhenClosed = false
            let base = selfTestTemporaryDirectory().appendingPathComponent("tab-commit-focus-\(UUID().uuidString)")
            do {
                try FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
                ws.tabs = ["first.txt", "second.txt"].map { name in
                    EditorTab(title: name, path: base.appendingPathComponent(name).path,
                              url: base.appendingPathComponent(name), content: name)
                }
                for tab in ws.tabs { try tab.content.write(to: tab.url!, atomically: true, encoding: .utf8) }
                var markdownTab = EditorTab(title: "background.md", path: base.appendingPathComponent("background.md").path,
                                            url: base.appendingPathComponent("background.md"), content: "# Hintergrund\n\n- Eintrag\n")
                markdownTab.markdownVisualOverride = true
                backgroundWorkspace.tabs = [markdownTab]
                backgroundWorkspace.activeTabID = markdownTab.id
                backgroundWindow.contentView = NSHostingView(rootView: VStack(spacing: 0) {
                    TabBarView()
                    MarkdownVisualEditorView(workspace: backgroundWorkspace, tab: markdownTab)
                }.environmentObject(backgroundWorkspace))
                backgroundWindow.orderBack(nil)
                ws.activeTabID = ws.tabs[0].id
                ws.commitMessage = ""
                let host = NSHostingView(rootView: VStack {
                    TabBarView()
                    TextField("Nachricht (⌘Enter committet)", text: Binding(get: { ws.commitMessage }, set: { ws.commitMessage = $0 }), axis: .vertical)
                        .textFieldStyle(.plain).padding(8)
                        .background(SelfTestMarker(id: "commitFocusField"))
                    Spacer()
                }.environmentObject(ws))
                window.contentView = host
                window.setContentSize(NSSize(width: 900, height: 500))
                var stage = "Leiste aufbauen"
                func wait(_ condition: () -> Bool) async throws {
                    for _ in 0..<100 {
                        if condition() { return }
                        try await Task.sleep(nanoseconds: 30_000_000)
                    }
                    throw NSError(domain: "TabCommitFocus", code: 1, userInfo: [NSLocalizedDescriptionKey: "Zielzustand fehlt (\(stage)); responder=\(String(describing: window.firstResponder))"])
                }
                func click(_ id: String) throws {
                    host.layoutSubtreeIfNeeded()
                    guard let marker = markerView(id: id, in: host), !marker.visibleRect.isEmpty else {
                        throw NSError(domain: "TabCommitFocus", code: 2, userInfo: [NSLocalizedDescriptionKey: "Klickziel fehlt: " + id])
                    }
                    let point = marker.convert(NSPoint(x: marker.bounds.midX, y: marker.bounds.midY), to: nil)
                    guard sendMouseClick(at: point, in: window, modifiers: [], viaApp: true) else {
                        throw NSError(domain: "TabCommitFocus", code: 3)
                    }
                }
                try await wait { markerView(id: "documentTabFrame-\(ws.tabs[1].id.uuidString)", in: host) != nil }
                try await wait { backgroundWorkspace.visualMarkdownEditor?.ready == true }
                host.layoutSubtreeIfNeeded()
                try await Task.sleep(nanoseconds: 250_000_000)
                stage = "Kontrollklick ohne Feldfokus"
                try click("documentTabFrame-\(ws.tabs[1].id.uuidString)")
                try await wait { ws.activeTabID == ws.tabs[1].id }
                func textInputs(_ view: NSView) -> [NSView] {
                    var result: [NSView] = []
                    if let text = view as? NSTextView, text.isEditable { result.append(text) }
                    else if let field = view as? NSTextField, field.isEditable { result.append(field) }
                    for child in view.subviews { result += textInputs(child) }
                    return result
                }
                for cycle in 0..<12 {
                    stage = "Feld eingeben \(cycle)"
                    guard let field = textInputs(host).first, window.makeFirstResponder(field) else {
                        throw NSError(domain: "TabCommitFocus", code: 4, userInfo: [NSLocalizedDescriptionKey: "Commit-Feld nicht fokussierbar"])
                    }
                    if let field = field as? NSTextField { field.currentEditor()?.insertText("L") }
                    else if let text = field as? NSTextView { text.insertText("L", replacementRange: NSRange(location: NSNotFound, length: 0)) }
                    try await wait { ws.commitMessage.hasSuffix("L") }
                    let target = ws.tabs.first { $0.id != ws.activeTabID }!.id
                    stage = "Tabklick nach Feldfokus \(cycle)"
                    try click("documentTabFrame-\(target.uuidString)")
                    try await wait { ws.activeTabID == target }
                    ws.commitMessage = ""
                }
                guard backgroundWorkspace.activeTab?.content == markdownTab.content else {
                    throw NSError(domain: "TabCommitFocus", code: 5, userInfo: [NSLocalizedDescriptionKey: "Hintergrunddokument verändert"])
                }
                backgroundWindow.contentView = nil
                backgroundWindow.close()
                window.contentView = original
                try? FileManager.default.removeItem(at: base)
                finish(true, "12 reale Tabklicks nach Commit-Eingaben mit zweitem WYSIWYG-Fenster")
            } catch {
                backgroundWindow.contentView = nil
                backgroundWindow.close()
                window.contentView = original
                try? FileManager.default.removeItem(at: base)
                finish(false, error.localizedDescription)
            }
        }
    }

    /// Ein externer Maus-Treiber liest nur die Koordinaten des isolierten
    /// Testfensters. Das native Drop-Ziel erhält den echten Datei-Pasteboard,
    /// kein MockDraggingInfo und keinen direkt aufgerufenen Provider.
    private static func runTabFileDragTest() {
        testLabel = "tabfiledrag"
        Task { @MainActor in
            guard let ws = Workspace.shared,
                  let window = CommandTargeting.registeredWindow(for: ws),
                  let outputPath = ProcessInfo.processInfo.environment["FASTRA_TABDRAG_DIR"] else {
                finish(.environment, "Tab-Drag benötigt FASTRA_TABDRAG_DIR und den externen Maus-Treiber")
            }
            let output = URL(fileURLWithPath: outputPath)
            let base = selfTestTemporaryDirectory().appendingPathComponent("tab-drag-\(UUID().uuidString)")
            let source = base.appendingPathComponent("Bericht #1 🇩🇪.txt")
            let probe = FileDragProbeView(frame: NSRect(x: 0, y: 0, width: 460, height: 160))
            let destination = NSWindow(contentRect: probe.frame, styleMask: [.titled, .closable],
                                       backing: .buffered, defer: false)
            destination.isReleasedWhenClosed = false
            // Der Quellklick holt das große Editorfenster nach vorn. Das
            // eigene Testziel muss trotzdem sichtbar und treffbar bleiben.
            destination.level = .floating
            destination.title = "Datei-Drop-Testziel"
            destination.contentView = probe
            do {
                try FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
                try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true)
                try "Gespeichert\n".write(to: source, atomically: true, encoding: .utf8)
                var loaded = false
                ws.loadFile(at: source) { loaded = $0 }
                for _ in 0..<200 where !loaded { try await Task.sleep(nanoseconds: 50_000_000) }
                guard loaded, let index = ws.tabs.firstIndex(where: {
                    $0.url?.resolvingSymlinksInPath() == source.resolvingSymlinksInPath()
                }) else {
                    throw NSError(domain: "TabFileDrag", code: 1)
                }
                window.setContentSize(NSSize(width: 1100, height: 700))
                window.makeKeyAndOrderFront(nil)
                activateApplication(ignoringOtherApps: true)
                try await Task.sleep(nanoseconds: 500_000_000)
                guard let editor = CommandTargeting.editorTextView(for: ws) else {
                    throw NSError(domain: "TabFileDrag", code: 5)
                }
                editor.insertText("Ungespeicherte Editorfassung\n",
                                  replacementRange: NSRange(location: 0, length: (editor.string as NSString).length))
                for _ in 0..<100 where ws.tabs[index].content != "Ungespeicherte Editorfassung\n" {
                    try await Task.sleep(nanoseconds: 50_000_000)
                }
                guard let root = window.contentView,
                      let marker = markerView(id: "documentTabFrame-\(ws.tabs[index].id.uuidString)", in: root) else {
                    throw NSError(domain: "TabFileDrag", code: 2)
                }
                let local = marker.convert(NSPoint(x: marker.bounds.minX + 28, y: marker.bounds.midY), to: nil)
                let start = window.convertPoint(toScreen: local)
                destination.setFrameOrigin(NSPoint(x: window.frame.minX + 180, y: window.frame.minY + 150))
                destination.orderFront(nil)
                let end = destination.convertPoint(toScreen: NSPoint(x: 230, y: 80))
                let screenTop = NSScreen.screens.first?.frame.maxY ?? 0
                var hit = root.hitTest(root.convert(local, from: nil))
                var hitChain: [String] = []
                while let view = hit { hitChain.append(String(describing: type(of: view))); hit = view.superview }
                func dragFrames(_ view: NSView) -> [String] {
                    let own = String(describing: type(of: view)).contains("TabFileDragView")
                        ? [NSStringFromRect(view.convert(view.bounds, to: nil)) + " hidden=\(view.isHidden)"] : []
                    return own + view.subviews.flatMap(dragFrames)
                }
                let ready: [String: Any] = ["pid": ProcessInfo.processInfo.processIdentifier,
                    "hit": hitChain, "window": NSStringFromRect(window.frame),
                    "dragViews": dragFrames(root),
                    "source": [start.x, screenTop - start.y], "target": [end.x, screenTop - end.y]]
                let sourceFrame = window.frame
                try JSONSerialization.data(withJSONObject: ready).write(to: output.appendingPathComponent("ready.json"), options: .atomic)
                for _ in 0..<600 where probe.received == nil { try await Task.sleep(nanoseconds: 50_000_000) }
                guard let received = probe.received,
                      received.resolvingSymlinksInPath() == source.resolvingSymlinksInPath(),
                      window.frame == sourceFrame else {
                    throw NSError(domain: "TabFileDrag", code: 3, userInfo: [NSLocalizedDescriptionKey: "Echter Drag: URL \(probe.received?.path ?? "fehlt"), Fenster unverändert=\(window.frame == sourceFrame), Hit=\(hitChain.joined(separator: " → "))"])
                }
                let copy = base.appendingPathComponent("Kopie.txt")
                try FileManager.default.copyItem(at: received, to: copy)
                guard try String(contentsOf: copy, encoding: .utf8) == "Gespeichert\n",
                      ws.tabs[index].content == "Ungespeicherte Editorfassung\n",
                      ws.tabs[index].hasUnsavedChanges else {
                    throw NSError(domain: "TabFileDrag", code: 4)
                }
                let data = await withCheckedContinuation { continuation in
                    typeScrollCapture(window: window) { continuation.resume(returning: $0?.data) }
                }
                if let data { try data.write(to: output.appendingPathComponent("tab.png")) }
                destination.close()
                try? FileManager.default.removeItem(at: base)
                finish(true, "Echter Tab-Drag übergibt Datei-URL mit Leerzeichen, Raute und Emoji; Drop-Ziel kopiert gespeicherte Fassung, Editoränderung bleibt ungespeichert")
            } catch {
                destination.close()
                try? FileManager.default.removeItem(at: base)
                finish(false, error.localizedDescription)
            }
        }
    }

    private static func runDiffExportTest() {
        testLabel = "diffexport"
        SelfTestDiffExport.run(runtime: .init(
