            }
        ))
    }

    private static func runSourceProvenanceTest() {
        testLabel = "sourceprovenance"
        Task { @MainActor in
            let base = selfTestTemporaryDirectory().appendingPathComponent("source-provenance-\(UUID().uuidString)")
            let controller = LocalControlController()
            func require(_ value: Bool, _ message: String) throws {
                if !value { throw NSError(domain: "SourceProvenanceSelfTest", code: 1,
                                           userInfo: [NSLocalizedDescriptionKey: message]) }
            }
            @MainActor func terminal(_ request: ControlRequest) async throws -> ControlJob {
                let accepted = try controller.execute(request).job!
                for _ in 0..<200 {
                    let job = try controller.execute(ControlRequest(operation: "status", jobID: accepted.id)).job!
                    if job.isTerminal {
                        return job
                    }
                    try await Task.sleep(nanoseconds: 50_000_000)
                }
                throw ControlFailure.expired
            }
            @MainActor func ready(_ request: ControlRequest) async throws -> ControlJob {
                let job = try await terminal(request)
                guard job.state == "ready", job.adopted == true else { throw job.error ?? ControlFailure.source }
                return job
            }
            @MainActor func capture(_ name: String, session: ControlSnapshotWindow) async throws {
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_SOURCEPROVENANCE_DIR"], !directory.isEmpty else { return }
                let url = URL(fileURLWithPath: directory).appendingPathComponent(name + ".png")
                try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                let data = await withCheckedContinuation { continuation in
                    typeScrollCapture(window: session.window) { continuation.resume(returning: $0?.data) }
                }
                guard let data else { throw ControlFailure.source }
                try data.write(to: url)
            }
            func originScroll(_ view: NSView) -> NSScrollView? {
                if let scroll = view as? NSScrollView, scroll.accessibilityIdentifier() == "controlSnapshotProvenance" { return scroll }
                return view.subviews.lazy.compactMap(originScroll).first
            }
            do {
                try FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
                let outer = base.appendingPathComponent("Archiv #1 🇩🇪.zip")
                let sender = base.appendingPathComponent("materialisiert.txt")
                let zip = "UEsDBBQAAAAIAMWaRl36ggNyWAAAAIwAAAAJAAAASW5uZW4uemlwC/BmZhFhYGDgYDg6yy1Wvj1WAMQTBmJuIM7LL8msSs3TK6ko8T57RvvZL4P9taoC64NWaPmffcLEEODNyCTCjFs7DDQwMqAaFuDNygYSYgRCSyBtC1YGAFBLAQIUAxQAAAAIAMWaRl36ggNyWAAAAIwAAAAJAAAAAAAAAAAAAACAAQAAAABJbm5lbi56aXBQSwUGAAAAAAEAAQA3AAAAfwAAAAAA"
                let archive = Data(base64Encoded: zip)!
                try archive.write(to: outer)
                let bytes = Data("eins\n🇩🇪 zwei\n".utf8)
                let generation = try ControlSourceSnapshot.generation(at: outer)
                activateApplication(ignoringOtherApps: true)
                var ownFiles: [URL] = []
                for binding in ["sha256", "generation"] {
                    try bytes.write(to: sender, options: .atomic)
                    let source = ControlSourceProvenance(runID: UUID(), kind: "archiveMaterialization",
                        hitIdentity: ControlHitIdentity(filesystemPath: outer.path, archiveMembers: ["Innen.zip", "notizen.txt"],
                            archiveMemberBytes: ["Innen.zip", "notizen.txt"].map { Data($0.utf8).base64EncodedString() }),
                        sourceGeneration: generation, archiveBinding: binding,
                        outerSHA256: binding == "sha256" ? FileSnapshot.sha256Hex(archive) : nil,
                        positionBinding: binding == "sha256" ? "exactUTF16" : "unboundHit", searchEvidence: "🇩🇪")
                    let request = ControlRequest(operation: "sourceSnapshot", path: sender.path,
                        sha256: FileSnapshot.sha256Hex(bytes), location: binding == "sha256" ? 5 : 0,
                        length: binding == "sha256" ? 4 : 0, provenance: source)
                    let job = try await ready(request)
                    guard let session = controller.snapshotWindowsForTesting.first(where: { $0.sessionID == job.sessionID }),
                          let snapshot = session.sourceSnapshot else { throw ControlFailure.invalidID }
                    ownFiles.append(snapshot.fileURL)
                    try FileManager.default.removeItem(at: sender)
                    try require(session.textView.string == "eins\n🇩🇪 zwei\n" && !session.textView.isEditable,
                                "Entfernte Senderdatei beeinträchtigt den schreibgeschützten Snapshot")
                    try require(try FileSnapshot.read(from: snapshot.fileURL).snapshot.sha256 == request.sha256,
                                "Eigene Sitzungskopie weicht vom übernommenen Inhalt ab")
                    try require(controller.objects().contains { $0.sessionID == job.sessionID && $0.provenance == source },
                                "Inventar verlor die Herkunft")
                    for width: CGFloat in [400, 760, 1100] {
                        session.window.setContentSize(NSSize(width: width, height: 650))
                        session.window.makeKeyAndOrderFront(nil)
                        try await Task.sleep(nanoseconds: 250_000_000)
                        try require(session.confirms(ControlSelection(location: request.location!, length: request.length!)),
                                    "Auswahl ging nach Fensteränderung verloren")
                        try await capture("\(binding)-\(Int(width))", session: session)
                        if width == 400 {
                            guard let origin = session.window.contentView.flatMap(originScroll),
                                  let text = origin.documentView as? NSTextView else { throw ControlFailure.source }
                            try require(text.string == ControlSnapshotWindow.provenanceDescription(source), "Herkunftsbereich verlor Mitgliedsidentität")
                            let before = origin.contentView.bounds.origin.y
                            text.scrollRangeToVisible(NSRange(location: max(0, text.string.utf16.count - 1), length: 1))
                            try await Task.sleep(nanoseconds: 150_000_000)
                            try require(origin.contentView.bounds.origin.y > before, "Lange Herkunft lässt sich nicht bis zum Ende scrollen")
                            try await capture("\(binding)-400-bottom", session: session)
                            origin.contentView.scroll(to: .zero)
                            origin.reflectScrolledClipView(origin.contentView)
                        }
                    }
                    _ = try controller.execute(ControlRequest(operation: "close", sessionID: job.sessionID))
                    try require(!FileManager.default.fileExists(atPath: snapshot.fileURL.path), "Schließen ließ eine Sitzungskopie zurück")
                }
                let collisionOuter = base.appendingPathComponent("gleiche-Namen.tar.gz")
                let collisionArchive = Data(base64Encoded: "H4sIAAAAAAAC/+3TMQrCQBAF0K1zipxAVo3JeSxSpLEwK4oX8BjWejpPoC5pBBsrQyDvwfCHaab6r0U6pfBfMaurasjsO2NcrT/7cG+WmyaUMYzg0KftPr8M89R2u754XC+3PPfyfGy7IjAfz6n2v9Z//QcAAAAAAAAA4Jc3FLafhgAoAAA=")!
                try collisionArchive.write(to: collisionOuter)
                let collisionGeneration = try ControlSourceSnapshot.generation(at: collisionOuter)
                var collisionDocuments: [UUID] = []
                var collisionOrigins: [String] = []
                for byte: UInt8 in [0xff, 0xfe] {
                    try bytes.write(to: sender, options: .atomic)
                    let source = ControlSourceProvenance(runID: UUID(), kind: "archiveMaterialization",
                        hitIdentity: ControlHitIdentity(filesystemPath: collisionOuter.path, archiveMembers: ["�.txt"],
                            archiveMemberBytes: [Data([byte] + Array(".txt".utf8)).base64EncodedString()]),
                        sourceGeneration: collisionGeneration, archiveBinding: "sha256",
                        outerSHA256: FileSnapshot.sha256Hex(collisionArchive), positionBinding: "unboundHit")
                    let request = ControlRequest(operation: "sourceSnapshot", path: sender.path,
                        sha256: FileSnapshot.sha256Hex(bytes), location: 0, length: 0, provenance: source)
                    let job = try await ready(request)
                    let session = controller.snapshotWindowsForTesting.first { $0.sessionID == job.sessionID }!
                    collisionDocuments.append(job.documentID)
                    collisionOrigins.append(ControlSnapshotWindow.provenanceDescription(source))
                    ownFiles.append(session.sourceSnapshot!.fileURL)
                    try FileManager.default.removeItem(at: sender)
                    session.window.makeKeyAndOrderFront(nil)
                    try await capture("same-name-\(byte)", session: session)
                }
                try require(Set(collisionDocuments).count == 2 && Set(collisionOrigins).count == 2,
                            "Gleiche Anzeigenamen vermischen Dokument- oder Herkunftsidentität")
                controller.closeAllSessions()
                try bytes.write(to: sender, options: .atomic)
                let checkedSource = ControlSourceProvenance(runID: UUID(), kind: "archiveMaterialization",
                    hitIdentity: ControlHitIdentity(filesystemPath: outer.path, archiveMembers: ["Innen.zip", "notizen.txt"],
                        archiveMemberBytes: ["Innen.zip", "notizen.txt"].map { Data($0.utf8).base64EncodedString() }),
                    sourceGeneration: generation, archiveBinding: "sha256", outerSHA256: FileSnapshot.sha256Hex(archive), positionBinding: "exactUTF16")
                var wrongHash = ControlRequest(operation: "sourceSnapshot", path: sender.path,
                    sha256: String(repeating: "0", count: 64), location: 5, length: 4, provenance: checkedSource)
                for failure in ["wrong-hash", "source-swap"] {
                    if failure == "source-swap" {
                        var changed = archive; changed[0] ^= 1
                        try changed.write(to: outer, options: .atomic)
                        wrongHash.id = UUID(); wrongHash.deadline = Date().timeIntervalSince1970 + 10
                        wrongHash.sha256 = FileSnapshot.sha256Hex(bytes)
                    }
                    let job = try await terminal(wrongHash)
                    let session = controller.snapshotWindowsForTesting.first { $0.sessionID == job.sessionID }!
                    try require(job.state == "failed" && job.error == .stale && job.adopted == false
                                && session.sourceSnapshot == nil, "Fehlerhafte Übergabe bestätigte eine Übernahme")
                    session.window.makeKeyAndOrderFront(nil)
                    try await capture(failure, session: session)
                    _ = try controller.execute(ControlRequest(operation: "close", sessionID: job.sessionID))
                }
                controller.closeAllSessions()
                try require(ownFiles.allSatisfy { !FileManager.default.fileExists(atPath: $0.path) }, "Sitzungsspeicher blieb erhalten")
                try? FileManager.default.removeItem(at: base)
                finish(true, "ZIP/TAR: starke und ausdrücklich schwächere Herkunft, identische Anzeigenamen mit verschiedenen Bytes, falscher Hash, Quellentausch, UTF-16-Auswahl, Senderdatei-Entfernung und Cleanup; 400/760/1100 pt einschließlich Herkunftsscroll")
            } catch {
                controller.closeAllSessions()
                try? FileManager.default.removeItem(at: base)
                finish(false, error.localizedDescription)
            }
        }
    }

    private final class FileDragProbeView: NSView {
        var received: URL?
        override init(frame: NSRect) {
            super.init(frame: frame)
            registerForDraggedTypes([.fileURL])
            let label = NSTextField(labelWithString: "Datei hier ablegen")
            label.frame = NSRect(x: 30, y: 60, width: 380, height: 24)
            addSubview(label)
        }
        required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }
        override func draggingEntered(_ sender: NSDraggingInfo) -> NSDragOperation {
            FileHandle.standardError.write(Data("TABDRAG target entered: \(sender.draggingPasteboard.types ?? [])\n".utf8))
            return .copy
        }
        override func performDragOperation(_ sender: NSDraggingInfo) -> Bool {
            let urls = sender.draggingPasteboard.readObjects(forClasses: [NSURL.self],
                options: [.urlReadingFileURLsOnly: true]) as? [URL]
            guard let urls, urls.count == 1 else { return false }
            received = urls[0]
            return true
        }
    }

    /// Prüft die echte Klickfläche des kleinen Tab-X. Der Ziel-Tab ist
    /// absichtlich inaktiv: Trifft der synthetische Randklick fälschlich den
    /// Tab statt des Schließen-Buttons, wird er nur ausgewählt und der Test
    /// erkennt den Unterschied unabhängig am Workspace-Zustand.
    private static func runTabCloseHitTest() {
        testLabel = "tabclosehit"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks() else {
            finish(false, "Workspace oder Hauptfenster nicht erreichbar")
        }

        ws.openNewTab()
        guard let targetID = ws.activeTabID else {
            finish(false, "Ziel-Tab nicht erzeugbar")
        }
        ws.openNewTab()
        guard let keeperID = ws.activeTabID, keeperID != targetID else {
            finish(false, "aktiver Kontroll-Tab nicht erzeugbar")
        }

        pollTabCloseTarget(
            ws,
            window: window,
            targetID: targetID,
            keeperID: keeperID)
    }

    /// Viele Tabs erzeugen echten horizontalen Überlauf. Manuelles Scrollen
    /// bleibt zunächst unangetastet; erst der folgende Dokumentwechsel muss
    /// den aktiven Tab vollständig in den sichtbaren Clip zurückholen.
    private static func runTabVisibilityTest() {
        testLabel = "tabvisibility"
        guard let workspace = Workspace.shared,
              let window = mainWindowForAXChecks(),
              let content = window.contentView else {
            finish(false, "Workspace oder Hauptfenster nicht erreichbar")
        }
        for index in 1...18 {
            workspace.openNewTab()
            if let activeID = workspace.activeTabID,
               let tabIndex = workspace.tabs.firstIndex(where: { $0.id == activeID }) {
                workspace.tabs[tabIndex].title = "Sehr langer Dokumentname \(index) für Tab-Sichtbarkeit.md"
            }
        }
        guard let lastID = workspace.activeTabID,
              let firstID = workspace.tabs.first?.id else {
            finish(false, "Test-Tabs nicht erzeugbar")
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
            guard let lastMarker = markerView(
                id: "documentTabFrame-\(lastID.uuidString)", in: content
            ), let scrollView = lastMarker.enclosingScrollView else {
                finish(false, "vollflächiger Tab-Marker oder ScrollView fehlt")
            }
            let clip = scrollView.contentView
            let maximumX = max(0, (scrollView.documentView?.bounds.width ?? 0)
                               - clip.bounds.width)
            guard maximumX > 40 else {
                finish(false, "Tab-Leiste erzeugte keinen echten horizontalen Überlauf")
            }

            clip.scroll(to: NSPoint(x: 0, y: clip.bounds.minY))
            scrollView.reflectScrolledClipView(clip)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                guard clip.bounds.minX < 2 else {
                    finish(false, "manuelles Scrollen wurde ohne Modelländerung überschrieben")
                }
                // Zwei Modelländerungen im selben SwiftUI-Update würden von
                // „letzter Tab → erster → letzter Tab“ wieder auf den
                // Ausgangswert zusammenfallen; ein echter Nutzerwechsel hat
                // ebenfalls mindestens einen Runloop dazwischen.
                workspace.selectTab(id: firstID)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                    workspace.selectTab(id: lastID)
                    pollActiveTabVisible(workspace, content: content, tabID: lastID,
                                         manualMaximum: maximumX)
                }
            }
        }
    }

    private static func pollActiveTabVisible(_ workspace: Workspace, content: NSView,
                                             tabID: UUID, manualMaximum: CGFloat) {
        waitFor(budget: 2, pause: 0.05,
                condition: {
                    guard let marker = markerView(id: "documentTabFrame-\(tabID.uuidString)", in: content),
                          let scrollView = marker.enclosingScrollView else { return false }
                    let clip = scrollView.contentView
                    let frame = marker.convert(marker.bounds, to: clip)
                    return frame.minX >= clip.bounds.minX - 1
                        && frame.maxX <= clip.bounds.maxX + 1
                        && frame.width > 20
                },
                onTimeout: { book in
                    finish(false, "aktiver Tab nach Dokumentwechsel nicht vollständig sichtbar — \(book.summary)")
                },
                then: {
                    finish(true, "manueller Scroll blieb stehen; Dokumentwechsel zeigte aktiven "
                        + "Tab vollständig (Überlauf \(Int(manualMaximum)) pt)")
                })
    }

    private static func pollTabCloseTarget(
        _ ws: Workspace,
        window: NSWindow,
        targetID: UUID,
        keeperID: UUID
    ) {
        var marker: NSView?
        waitFor(budget: 2, pause: 0.05,
                condition: {
                    guard let content = window.contentView else { return false }
                    marker = markerView(id: "tabClose-\(targetID.uuidString)", in: content)
                    return marker != nil
                },
                onTimeout: { book in
                    finish(false, "AppKit-Marker des Tab-X fehlt — \(book.summary)")
                },
                then: {
                    guard let marker else { finish(false, "Tab-X-Marker nach Erfolg verschwunden") }
                    let minimumSide: CGFloat = 22
                    guard marker.bounds.width >= minimumSide,
                          marker.bounds.height >= minimumSide else {
                        finish(
                            false,
                            "Tab-X-Hitbereich ist nur "
                                + "\(Int(marker.bounds.width))×\(Int(marker.bounds.height)) pt"
                        )
                    }

                    // Einen Punkt innerhalb der rechten Kante klicken, nicht bloß das
                    // Symbolzentrum. Genau dort fiel der kleine verschachtelte Button
                    // bisher auf den umgebenden Tab zurück.
                    let edge = NSPoint(x: marker.bounds.maxX - 1, y: marker.bounds.midY)
                    let point = marker.convert(edge, to: nil)
                    guard sendMouseClick(at: point, in: window, modifiers: []) else {
                        finish(false, "Randklick auf das Tab-X nicht erzeugbar")
                    }

                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) {
                        let closed = !ws.tabs.contains(where: { $0.id == targetID })
                        let keeperStayedActive = ws.activeTabID == keeperID
                        finish(
                            closed && keeperStayedActive,
                            closed && keeperStayedActive
                                ? "mindestens 22×22 pt; Randklick schließt nur den Ziel-Tab"
                                : "Randklick schloss den Ziel-Tab nicht eindeutig "
                                    + "(geschlossen=\(closed), Kontroll-Tab aktiv=\(keeperStayedActive))"
                        )
                    }
                })
    }

    /// Prüft den echten Shift-Klick auf einen zweiten Tab, die zwei sichtbar
    /// unterscheidbaren Auswahlrollen sowie den vorausgefüllten Vergleichs-
    /// dialog. Die Modelltests allein würden eine tote Modifier-Geste oder
    /// fehlende SwiftUI-Vorbelegung nicht erkennen.
    private static func runTabComparisonTest() {
        testLabel = "tabcompare"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks(),
              let content = window.contentView else {
            finish(false, "Workspace oder Hauptfenster nicht erreichbar")
        }

        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-tabcompare-\(UUID().uuidString)")
        // Der lange Name schützt zugleich den realen Klickpfad eines in der
        // Mitte gekürzten Tabs vor Rückfällen zu fensterbreiten Tabs.
        let longName = String(repeating: "sehr-langer-dateiname-", count: 8)
            + "links.txt"
        let leftURL = directory.appendingPathComponent(longName)
        let rightURL = directory.appendingPathComponent("rechts.txt")
        do {
            try FileManager.default.createDirectory(
                at: directory,
                withIntermediateDirectories: true
            )
            try "links\n".write(
                to: leftURL,
                atomically: true,
                encoding: .utf8
            )
            try "rechts\n".write(
                to: rightURL,
                atomically: true,
                encoding: .utf8
            )
        } catch {
            finish(
                false,
                "Tabvergleich-Fixtures nicht anlegbar: \(error.localizedDescription)"
            )
        }

        ws.loadFile(at: leftURL) { leftOK in
            guard leftOK else {
                try? FileManager.default.removeItem(at: directory)
                finish(false, "linke Fixture nicht ladbar")
            }
            ws.loadFile(at: rightURL) { rightOK in
                guard rightOK else {
                    try? FileManager.default.removeItem(at: directory)
                    finish(false, "rechte Fixture nicht ladbar")
                }
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.7) {
                    guard let leftTab = ws.tabs.first(where: {
                        $0.url?.standardizedFileURL == leftURL.standardizedFileURL
                    }), let rightTab = ws.tabs.first(where: {
                        $0.url?.standardizedFileURL == rightURL.standardizedFileURL
                    }), ws.activeTabID == rightTab.id else {
                        try? FileManager.default.removeItem(at: directory)
                        finish(false, "Fixture-Tabs oder eindeutiger aktueller Tab fehlen")
                    }

                    do {
                        // Vorbedingung bewusst herstellen: Passen beide Tabs
                        // nicht gleichzeitig in die Leiste, muss der Test den
                        // Ziel-Tab selbst sichtbar scrollen. Ob das überhaupt
                        // vorkommt, hing bisher an der Fensterbreite, die ein
                        // früherer Test im Lauf hinterlassen hatte — deshalb
                        // fiel der Fehler nur in bestimmten Reihenfolgen auf.
                        tabCompareStripOverflow = scrollTabStripToEnd(in: content)
                        armSingleShiftClick(
                            leftTab.id, in: window, content: content,
                            directory: directory
                        ) {
                            pollShiftSelectedTabs(
                                ws,
                                window: window,
                                directory: directory,
                                leftID: leftTab.id,
                                rightID: rightTab.id)
                        }
                    }
                }
            }
        }
    }

    /// Scrollt die Tab-Leiste ans rechte Ende, sofern sie überhaupt überläuft.
    /// Dient nur dazu, den weggescrollten Ziel-Tab reproduzierbar herzustellen.
    /// Rückgabe: der erreichte Überlauf in Punkten (0 = alles passt nebeneinander).
    @discardableResult
    private static func scrollTabStripToEnd(in content: NSView) -> CGFloat {
        var scrollView: NSScrollView?
        func findStrip(_ view: NSView) {
            guard scrollView == nil else { return }
            if view.accessibilityIdentifier().hasPrefix("documentTabFrame-") {
                scrollView = view.enclosingScrollView
                return
            }
            view.subviews.forEach(findStrip)
        }
        findStrip(content)
        guard let scrollView, let documentView = scrollView.documentView else {
            return 0
        }
        let clip = scrollView.contentView
        let maximumX = documentView.bounds.width - clip.bounds.width
        guard maximumX > 1 else { return 0 }      // kein Überlauf, nichts zu tun
        clip.scroll(to: NSPoint(x: maximumX, y: clip.bounds.origin.y))
        scrollView.reflectScrolledClipView(clip)
        scrollView.window?.layoutIfNeeded()
        return maximumX
    }

    /// Scrollt die Tab-Leiste so weit, dass der Tab mit `id` vollständig im
    /// sichtbaren Bereich liegt — genau das, was ein Nutzer vor dem Klick auf
    /// einen weit rechts liegenden Tab selbst tut. Der reguläre AppKit-Weg
    /// (`contentView.scroll` + `reflectScrolledClipView`) ist der einzige, der
    /// die SwiftUI-ScrollView im Test wirklich bewegt (siehe AGENTS.md).
    /// `false` heißt: Marker oder ScrollView noch nicht da.
    @discardableResult
    private static func scrollTabIntoView(id: UUID, in content: NSView) -> Bool {
        guard let frameMarker = markerView(
                id: "documentTabFrame-\(id.uuidString)", in: content),
              let scrollView = frameMarker.enclosingScrollView,
              let documentView = scrollView.documentView else {
            return false
        }
        let clip = scrollView.contentView
        let tabRect = frameMarker.convert(frameMarker.bounds, to: documentView)
        let maximumX = max(0, documentView.bounds.width - clip.bounds.width)
        var origin = clip.bounds.origin
        if tabRect.minX < clip.bounds.minX {
            origin.x = max(0, tabRect.minX - 8)
        } else if tabRect.maxX > clip.bounds.maxX {
            origin.x = min(maximumX, tabRect.maxX - clip.bounds.width + 8)
        } else {
            return true                       // liegt bereits vollständig frei
        }
        clip.scroll(to: origin)
        scrollView.reflectScrolledClipView(clip)
        // Ohne erzwungenes Layout misst der Aufrufer gleich darauf noch die
        // Position vor dem Scrollen und klickt daneben.
        scrollView.window?.layoutIfNeeded()
        return true
    }

    /// Klickt mittig auf einen Tab-Marker; `nil` bedeutet Erfolg, sonst folgt
    /// der Fehlertext. Der Punkt muss innerhalb der sichtbaren Tab-Leiste liegen:
    /// Weggescrollte Tabs behalten ihre NSView, deren Mittelpunkt andere Controls
    /// treffen könnte.
    private static func sendTabClick(
        on view: NSView,
        in window: NSWindow,
        modifiers: NSEvent.ModifierFlags
    ) -> String? {
        let local = NSPoint(x: view.bounds.midX, y: view.bounds.midY)
        let point = view.convert(local, to: nil)
        if let clip = view.enclosingScrollView?.contentView {
            let strip = clip.convert(clip.bounds, to: nil)
            guard strip.insetBy(dx: -1, dy: -1).contains(point) else {
                return "Klickpunkt \(point) liegt außerhalb der sichtbaren "
                    + "Tab-Leiste \(strip)"
            }
        }
        guard sendMouseClick(at: point, in: window, modifiers: modifiers) else {
            return "Mausereignis nicht erzeugbar"
        }
        return nil
    }

    /// Den Ziel-Tab sichtbar scrollen und den Klickpunkt per Hit-Test bestätigen,
    /// dann genau einen Shift-Klick senden. Vorbedingungen und Klick liegen im
    /// selben synchronen Durchlauf. Keine Klickwiederholung: Sie könnte verdecken,
    /// dass das Produkt den ersten Nutzerklick verwirft.
    private static func armSingleShiftClick(
        _ id: UUID,
        in window: NSWindow,
        content: NSView,
        directory: URL,
        completion: @escaping () -> Void
    ) {
        // Messen, prüfen und klicken in einem Main-Thread-Durchlauf:
        // `window.sendEvent` stellt synchron zu. Eine tickübergreifende Ruheprüfung
        // kann mit SwiftUIs gespeichertem Scroll-Offset pendeln; der Klick liegt
        // deshalb in der Bedingung der Warteschleife, nicht in deren Fortsetzung.
        var lastBlocker = ""
        waitFor(budget: 10, pause: 0.05,
                condition: {
                    func tryAgain(blocker: String) -> Bool {
                        lastBlocker = blocker
                        return false
                    }
                    scrollTabIntoView(id: id, in: content)
                    guard let idleTab = markerView(
                        id: "documentTab-idle-\(id.uuidString)", in: content
                    ), let strip = idleTab.enclosingScrollView else {
                        return tryAgain(blocker: "Tab-Marker oder Leisten-ScrollView fehlt")
                    }
                    let local = NSPoint(x: idleTab.bounds.midX, y: idleTab.bounds.midY)
                    let point = idleTab.convert(local, to: nil)
                    let clip = strip.contentView
                    let stripRect = clip.convert(clip.bounds, to: nil)
                    guard stripRect.insetBy(dx: -1, dy: -1).contains(point) else {
                        return tryAgain(blocker: "Punkt \(point) außerhalb der "
                            + "sichtbaren Leiste \(stripRect)")
                    }
                    // Hit-Test aus Sicht des Fensters: Der Punkt muss wirklich in der
                    // Tab-Leiste landen, nicht auf einem darüberliegenden Bedienelement.
                    let inSuperview = content.superview?.convert(point, from: nil)
                        ?? content.convert(point, from: nil)
                    guard let hit = content.hitTest(inSuperview),
                          hit.isDescendant(of: strip) else {
                        let hitDescription = content.hitTest(inSuperview)
                            .map { String(describing: type(of: $0)) } ?? "nichts"
                        return tryAgain(blocker: "Hit-Test bei \(point) trifft "
                            + "\(hitDescription) statt der Tab-Leiste")
                    }
                    guard sendMouseClick(at: point, in: window, modifiers: .shift) else {
                        try? FileManager.default.removeItem(at: directory)
                        finish(false, "Mausereignis nicht erzeugbar")
                    }
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: directory)
                    finish(false, "Vorbedingung des Shift-Klicks nicht erreicht "
                        + "(letzter Blocker: \(lastBlocker)) — \(book.summary)")
                },
                then: completion)
    }

    /// Sendet einen synthetischen Linksklick. Standardweg ist `window.sendEvent`
    /// (bewährt für Buttons und Modifier-Gesten). `viaApp` legt die Events
    /// stattdessen mit `NSApp.postEvent` in die reguläre Event-Queue: Nur die
    /// echte Event-Schleife setzt `NSApp.currentEvent`, aus dem z.B. der
    /// Zeilen-Handler der Änderungen-Ansicht Modifier und Klickzahl liest.
    private static func sendMouseClick(
        at point: NSPoint,
        in window: NSWindow,
        modifiers: NSEvent.ModifierFlags,
        viaApp: Bool = false,
        clickCount: Int = 1
    ) -> Bool {
        let time = ProcessInfo.processInfo.systemUptime
        guard let down = NSEvent.mouseEvent(
            with: .leftMouseDown,
            location: point,
            modifierFlags: modifiers,
            timestamp: time,
            windowNumber: window.windowNumber,
            context: nil,
            eventNumber: 0,
            clickCount: clickCount,
            pressure: 1
        ), let up = NSEvent.mouseEvent(
            with: .leftMouseUp,
            location: point,
            modifierFlags: modifiers,
            timestamp: time + 0.04,
            windowNumber: window.windowNumber,
            context: nil,
            eventNumber: 1,
            clickCount: clickCount,
            pressure: 0
        ) else {
            return false
        }
        if viaApp {
            NSApp.postEvent(down, atStart: false)
            NSApp.postEvent(up, atStart: false)
        } else {
            window.sendEvent(down)
            window.sendEvent(up)
        }
        return true
    }


    /// Scrollt eine gefundene `NSScrollView` um `points` nach unten. Das
    /// documentView der SwiftUI-Hosting-ScrollView ist geflippt (y wächst nach
    /// unten), ein positiver Wert bewegt den Inhalt also weiter nach hinten.
    private static func scrollGitChangesList(_ scroll: NSScrollView,
                                             by points: CGFloat) {
        let clip = scroll.contentView
        let maximum = max(0, (scroll.documentView?.bounds.height ?? 0)
                          - clip.bounds.height)
        let y = min(points, maximum)
        clip.scroll(to: NSPoint(x: 0, y: y))
        scroll.reflectScrolledClipView(clip)
        scroll.window?.layoutIfNeeded()
    }

    private static func pollShiftSelectedTabs(
        _ ws: Workspace,
        window: NSWindow,
        directory: URL,
        leftID: UUID,
        rightID: UUID
    ) {
        let content = window.contentView
        var currentMarker: NSView?
        var comparisonMarker: NSView?
        waitFor(budget: 6, pause: 0.1,
                condition: {
                    currentMarker = content.flatMap {
                        markerView(
                            id: "documentTab-current-\(rightID.uuidString)",
                            in: $0
                        )
                    }
                    comparisonMarker = content.flatMap {
                        markerView(
                            id: "documentTab-comparison-\(leftID.uuidString)",
                            in: $0
                        )
                    }
                    return ws.activeTabID == rightID
                        && ws.comparisonTabID == leftID
                        && ws.selectedComparisonTabIDs == [leftID, rightID]
                        && currentMarker != nil
                        && comparisonMarker != nil
                },
                onTimeout: { book in
                    // Der eine gesendete Shift-Klick blieb ohne Wirkung — das ist
                    // jetzt ein echter Befund: Alle Vorbedingungen (sichtbar, stabil,
                    // Hit-Test trifft die Leiste) hat `armSingleShiftClick` vor dem
                    // Ereignis hergestellt. Bewusst keine Klick-Wiederholung, sonst
                    // bestünde der Test auch, wenn das Produkt den ersten echten
                    // Nutzerklick verwirft.
                    // Diagnose vor dem Aufräumen erheben — der Test löscht den
                    // Fixture-Ordner selbst, danach misst jede Prüfung nur noch
                    // die eigene Aufräumarbeit.
                    let fixtureExists = FileManager.default
                        .fileExists(atPath: directory.path)
                    let fixtureCount = (try? FileManager.default
                        .contentsOfDirectory(atPath: directory.path).count) ?? -1
                    try? FileManager.default.removeItem(at: directory)
                    // Welche Tab-Marker liegen im geprüften Fenster wirklich?
                    // Ohne diese Liste ist nicht unterscheidbar, ob der Klick
                    // danebenging oder ob die Prüfung im falschen Fenster sucht.
                    var markerIDs: [String] = []
                    func collectMarkers(_ view: NSView) {
                        let id = view.accessibilityIdentifier()
                        if id.hasPrefix("documentTab-") {
                            markerIDs.append(id)
                        }
                        view.subviews.forEach(collectMarkers)
                    }
                    content.map(collectMarkers)
                    let windowCount = NSApp.windows.filter {
                        $0.frameAutosaveName != SearchWindow.frameAutosaveName
                            && $0.isVisible && $0.contentView != nil
                    }.count
                    finish(
                        false,
                        "Der einzelne Shift-Klick blieb ohne Wirkung: "
                            + "aktiv=\(ws.activeTabID?.uuidString ?? "nil"), "
                            + "Vergleich=\(ws.comparisonTabID?.uuidString ?? "nil"), "
                            + "Marker aktuell=\(currentMarker != nil), "
                            + "zweiter=\(comparisonMarker != nil), "
                            + "Tabs=\(ws.tabs.count) "
                            + "[\(ws.tabs.map { $0.title }.joined(separator: ", "))], "
                            + "links noch da=\(ws.tabs.contains { $0.id == leftID }), "
                            + "rechts noch da=\(ws.tabs.contains { $0.id == rightID }), "
                            + "Fixture-Ordner=\(fixtureExists) "
                            + "mit \(fixtureCount) Dateien, "
                            + "Fenster=\(windowCount), "
                            + "Fenster-Marker=\(markerIDs.count): "
                            + "\(markerIDs.prefix(6).joined(separator: " | ")) — \(book.summary)"
                    )
                },
                then: {
                    guard ws.presentComparisonForSelectedTabs(contextTabID: leftID) else {
                        try? FileManager.default.removeItem(at: directory)
                        finish(false, "Kontextaktion akzeptiert den markierten Tab nicht")
                    }
                    pollPrefilledComparisonSheet(
                        ws,
                        window: window,
                        directory: directory,
                        leftID: leftID,
                        rightID: rightID
                    )
                })
    }

    private static func pollPrefilledComparisonSheet(
        _ ws: Workspace,
        window: NSWindow,
        directory: URL,
        leftID: UUID,
        rightID: UUID
    ) {
        waitFor(budget: 4, pause: 0.1,
                condition: {
                    guard let sheet = window.attachedSheet,
                          let content = sheet.contentView else { return false }
                    let leftReady = markerView(
                        id: "compare-left-tab-\(leftID.uuidString)",
                        in: content
                    ) != nil
                    let rightReady = markerView(
                        id: "compare-right-tab-\(rightID.uuidString)",
                        in: content
                    ) != nil
                    return leftReady && rightReady
                },
                onTimeout: { book in
                    ws.showCompareFilesDialog = false
                    try? FileManager.default.removeItem(at: directory)
                    finish(
                        false,
                        "Vergleichs-Sheet nicht mit beiden markierten Tabs vorgefüllt — \(book.summary)"
                    )
                },
                then: {
                    ws.showCompareFilesDialog = false
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                        guard let root = window.contentView else {
                            try? FileManager.default.removeItem(at: directory)
                            finish(false, "Fensterinhalt für den Folgeklick fehlt")
                        }
                        scrollTabIntoView(id: leftID, in: root)
                        guard let comparisonTab = markerView(
                            id: "documentTab-comparison-\(leftID.uuidString)",
                            in: root
                        ) else {
                            try? FileManager.default.removeItem(at: directory)
                            finish(false, "Marker des markierten Tabs fehlt")
                        }
                        if let failure = sendTabClick(
                            on: comparisonTab, in: window, modifiers: []
                        ) {
                            try? FileManager.default.removeItem(at: directory)
                            finish(false, "normaler Folgeklick nicht ausführbar: \(failure)")
                        }
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) {
                            let cleared = ws.activeTabID == leftID
                                && ws.comparisonTabID == nil
                            try? FileManager.default.removeItem(at: directory)
                            finish(
                                cleared,
                                cleared
                                    ? "Shift-Klick behält Primärtab; zwei Markierungsrollen; "
                                        + "Dialog links/rechts vorgefüllt; Normalklick räumt auf "
                                        + "(Leisten-Überlauf beim Klick: "
                                        + "\(Int(tabCompareStripOverflow)) pt)"
                                    : "Normalklick räumte die Zwei-Tab-Auswahl nicht auf"
                            )
                        }
                    }
                })
    }

    // MARK: - -selftest softwrapprofiles

    /// Prüft die komplette Formatprofil-Kette im echten Editor:
    /// TXT-Default an Fensterrand, eine als JSON gemerkte `.txt` ebenfalls
    /// an Fensterrand, Markdown-Default an, 4D-Default aus,
    /// sofortiger CESE-Reconcile ohne Inhalts-/Selektions-/Dirty-/Undo-
    /// Änderung, Vererbung an einen neuen 4D-Tab und appweite Rückschaltung
    /// beider offenen 4D-Tabs. Zusätzlich muss der checkbare Hauptmenüpunkt
    /// jeden Zustand spiegeln. Echte Hilfsfenster sperren anschließend den
    /// Menüpunkt und Shortcut, ohne Profile oder letzten Kontext zu ändern.
    private static func runSoftWrapProfilesTest() {
        testLabel = "softwrapprofiles"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }) else {
            finish(false, "kein Hauptfenster gefunden")
        }

        waitForEditor(window: mainWindow) { root, _ in
            let base = selfTestTemporaryDirectory()
                .appendingPathComponent("fastra-softwrap-\(UUID().uuidString)")
            shortSearchFixtureDirectory = base
            let textURL = base.appendingPathComponent("notizen.txt")
            let jsonInTextURL = base.appendingPathComponent("daten-json.txt")
            let markdownURL = base.appendingPathComponent("notizen.md")
            let firstFourDURL = base.appendingPathComponent("erste.4dm")
            let secondFourDURL = base.appendingPathComponent("zweite.4dm")
            let longLine = String(repeating: "Soft-Wrap-Prüfung ", count: 40)
            do {
                try FileManager.default.createDirectory(
                    at: base, withIntermediateDirectories: true
                )
                try ("Notizen\n\n\(longLine)\n")
                    .write(to: textURL, atomically: true, encoding: .utf8)
                // Eine logische Zeile wie im gemeldeten Problemfall. Die
                // Dateiendung bleibt `.txt`; die gemerkte manuelle Formatwahl
                // darunter simuliert das erneute Öffnen als JSON.
                try (#"{"payload":""#
                    + String(repeating: "A7+/qZ09_-?mN4xB", count: 512)
                    + #""}"#)
                    .write(to: jsonInTextURL, atomically: true, encoding: .utf8)
                try ("# Notizen\n\n\(longLine)\n")
                    .write(to: markdownURL, atomically: true, encoding: .utf8)
                try ("// Erste 4D-Methode\n\(longLine)\n")
                    .write(to: firstFourDURL, atomically: true, encoding: .utf8)
                try ("// Zweite 4D-Methode\n\(longLine)\n")
                    .write(to: secondFourDURL, atomically: true, encoding: .utf8)
            } catch {
                finish(false, "Fixtures nicht anlegbar: \(error.localizedDescription)")
            }
            ws.languageChoices.setChoiceID(
                LanguageMenuSupport.Entry.grammar(.json).id,
                for: jsonInTextURL
            )

            ws.loadFile(at: textURL) { ok in
                guard ok else {
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "TXT-Fixture nicht ladbar")
                }
                pollSoftWrapState(
                    ws: ws, root: root, expectedFormat: .plainText,
                    expectedWrap: true, expectedTarget: .window,
                    label: "TXT-Werkseinstellung am Fensterrand") {
                    ws.loadFile(at: jsonInTextURL) { ok in
                        guard ok else {
                            try? FileManager.default.removeItem(at: base)
                            finish(false, "als JSON gemerkte TXT-Fixture nicht ladbar")
                        }
                        pollSoftWrapState(
                            ws: ws, root: root,
                            expectedFormat: .grammar(.json),
                            expectedWrap: true, expectedTarget: .window,
                            requireWrappedGeometry: true,
                            label: "gemerkte JSON-Wahl einer TXT-Megazeile") {
                            ws.loadFile(at: markdownURL) { ok in
                                guard ok else {
                                    try? FileManager.default.removeItem(at: base)
                                    finish(false, "Markdown-Fixture nicht ladbar")
                                }
                                pollSoftWrapState(
                                    ws: ws, root: root,
                                    expectedFormat: .grammar(.markdown),
                                    expectedWrap: true,
                                    label: "Markdown-Werkseinstellung") {
                                    loadFirstFourDForSoftWrapTest(
                                        ws: ws, root: root, base: base,
                                        firstURL: firstFourDURL,
                                        secondURL: secondFourDURL
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private static func loadFirstFourDForSoftWrapTest(
        ws: Workspace, root: NSView, base: URL, firstURL: URL, secondURL: URL
    ) {
        ws.loadFile(at: firstURL) { ok in
            guard ok else {
                try? FileManager.default.removeItem(at: base)
                finish(false, "erste 4D-Fixture nicht ladbar")
            }
            pollSoftWrapState(
                ws: ws, root: root, expectedFormat: .fourD,
                expectedWrap: false, label: "4D-Werkseinstellung") {
                guard let firstTabID = ws.activeTabID,
                      let textView = editorTextView(in: root) as? TextView else {
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "erste 4D-TextView nicht erreichbar")
                }
                let viewID = ObjectIdentifier(textView)
                let selection = NSRange(location: 3, length: 5)
                textView.selectionManager.setSelectedRange(selection)
                let content = textView.string
                let dirty = ws.activeTab?.isDirty
                let canUndo = textView.undoManager?.canUndo

                Task { @MainActor in
                    do {
                        guard let menuItem = findMenuItem(titled: "Soft Wrap", in: NSApp.mainMenu) else {
                            throw NSError(domain: "SelfTestSoftWrapMenu", code: 1)
                        }
                        guard let window = root.window else {
                            throw NSError(domain: "SelfTestSoftWrapMenu", code: 2)
                        }
                        activateApplication(ignoringOtherApps: true)
                        window.makeKeyAndOrderFront(nil)
                        try await awaitCommandOwnerState("erstes Soft-Wrap-Dokument ist Befehlsziel") {
                            NSApp.isActive && window.isKeyWindow
                                && WorkspaceWindowRegistry.workspace(for: window) === ws
                        }
                        try await performCommandOwnerMenuItem(menuItem, ticks: 80, pause: 0.1)
                        pollSoftWrapState(
                            ws: ws, root: root, expectedFormat: .fourD,
                            expectedWrap: true, label: "4D live eingeschaltet") {
                            guard let reconciled = editorTextView(in: root) as? TextView,
                                  ObjectIdentifier(reconciled) == viewID,
                                  reconciled.string == content,
                                  reconciled.selectedRange() == selection,
                                  ws.activeTab?.isDirty == dirty,
                                  reconciled.undoManager?.canUndo == canUndo else {
                                try? FileManager.default.removeItem(at: base)
                                finish(false, "Soft-Wrap-Umschalten veränderte "
                                    + "TextView-Identität, Inhalt, Auswahl, Dirty- oder Undo-Zustand")
                            }

                            ws.loadFile(at: secondURL) { ok in
                                guard ok else {
                                    try? FileManager.default.removeItem(at: base)
                                    finish(false, "zweite 4D-Fixture nicht ladbar")
                                }
                                pollSoftWrapState(
                                    ws: ws, root: root, expectedFormat: .fourD,
                                    expectedWrap: true, label: "neuer 4D-Tab übernimmt Profil") {
                                    guard let secondTabID = ws.activeTabID,
                                          secondTabID != firstTabID else {
                                        try? FileManager.default.removeItem(at: base)
                                        finish(false, "zweite 4D-Datei erzeugte keinen eigenen Tab")
                                    }
                                    ws.toggleSoftWrap()
                                    pollSoftWrapState(
                                        ws: ws, root: root, expectedFormat: .fourD,
                                        expectedWrap: false, label: "zweiter 4D-Tab schaltet aus") {
                                        verifyBothFourDTabsAreUnwrapped(
                                            ws: ws, root: root, base: base,
                                            firstTabID: firstTabID,
                                            secondTabID: secondTabID
                                        )
                                    }
                                }
                            }
                        }
                    } catch {
                        try? FileManager.default.removeItem(at: base)
                        finish(error is SelfTestMenuRootExchange.EnvironmentFailure ? .environment : .fail,
                               "Hauptmenü Soft Wrap: \(error.localizedDescription)")
                    }
                }
            }
        }
    }

    private static func verifyBothFourDTabsAreUnwrapped(
        ws: Workspace, root: NSView, base: URL,
        firstTabID: UUID, secondTabID: UUID
    ) {
        ws.activeTabID = firstTabID
        pollSoftWrapState(
            ws: ws, root: root, expectedFormat: .fourD,
            expectedWrap: false, label: "erster offener 4D-Tab folgt global") {
            ws.activeTabID = secondTabID
            pollSoftWrapState(
                ws: ws, root: root, expectedFormat: .fourD,
                expectedWrap: false, label: "zweiter offener 4D-Tab bleibt synchron") {
                runSoftWrapAuxiliaryWindowChecks(ws: ws, root: root, base: base)
            }
        }
    }

    /// Hilfsfenster behalten den Settingskontext, dürfen das zuletzt bediente
    /// Dokumentprofil aber weder per Menü noch per Tastenkürzel verändern.
    private static func runSoftWrapAuxiliaryWindowChecks(ws: Workspace, root: NSView, base: URL) {
        Task { @MainActor in
            guard let firstWindow = root.window else { finish(false, "4D-Dokumentfenster fehlt") }
            let second = DocumentWindowController.openNewDocument(defaults: workspaceDefaults())
            guard let secondWindow = CommandTargeting.documentWindow(for: second) else {
                finish(false, "zweites Dokumentfenster für Soft-Wrap-Zielprüfung fehlt")
            }
            do {
                var loaded = false
                second.loadFile(at: base.appendingPathComponent("notizen.txt")) { loaded = $0 }
                try await awaitCommandOwnerState("verschiedene Soft-Wrap-Dokumentprofile bereit") {
                    loaded && ws.activeDocumentFormat.id == .fourD && !ws.softWrapEnabled
                        && second.activeDocumentFormat.id == .plainText && second.softWrapEnabled
                        && CommandTargeting.editorTextView(for: second)?.wrapLines == true
                }
                // Bewusste Dokumentwechsel gehören zum Aufbau, nicht zur
                // Rückgabe aus einem Hilfsfenster. Beide Haken müssen sichtbar stimmen.
                for (window, expected) in [(firstWindow, false), (secondWindow, true)] {
                    window.makeKeyAndOrderFront(nil)
                    try await awaitCommandOwnerState("Dokument-Haken vor Hilfsfenster") {
                        NSApp.mainMenu?.update()
                        let item = findMenuItem(titled: "Soft Wrap", in: NSApp.mainMenu)
                        return window.isKeyWindow && item?.isEnabled == true
                            && item?.state == (expected ? .on : .off)
                    }
                }
                let profilesBeforeShortcut = try JSONDecoder().decode(
                    SoftWrapProfileStore.Payload.self,
                    from: workspaceDefaults().data(forKey: "editor.formatProfiles") ?? Data()
                )
                let revisionBeforeShortcut = second.softWrapProfiles.revision
                try await deliverSoftWrapShortcut(to: secondWindow)
                try await awaitCommandOwnerState("positiver ⇧⌘L-Kontrolllauf schaltet genau einmal aus") {
                    !second.softWrapEnabled && !ws.softWrapEnabled
                        && second.softWrapProfiles.revision == revisionBeforeShortcut &+ 1
                }
                try await deliverSoftWrapShortcut(to: secondWindow)
                try await awaitCommandOwnerState("zweiter ⇧⌘L stellt das Profil genau einmal zurück") {
                    second.softWrapEnabled && !ws.softWrapEnabled
                        && second.softWrapProfiles.revision == revisionBeforeShortcut &+ 2
                        && (try? JSONDecoder().decode(SoftWrapProfileStore.Payload.self,
                            from: workspaceDefaults().data(forKey: "editor.formatProfiles") ?? Data())) == profilesBeforeShortcut
                }
                let firstRevision = ws.softWrapProfiles.revision
                let secondRevision = second.softWrapProfiles.revision
                let storedProfiles = workspaceDefaults().data(forKey: "editor.formatProfiles")
                func profilesAreUntouched() -> Bool {
                    !ws.softWrapEnabled && second.softWrapEnabled
                        && ws.softWrapProfiles.revision == firstRevision
                        && second.softWrapProfiles.revision == secondRevision
                        && workspaceDefaults().data(forKey: "editor.formatProfiles") == storedProfiles
                }
                typealias Auxiliary = (label: String, item: () -> NSMenuItem?, matches: (NSWindow?) -> Bool)
                let auxiliaries: [Auxiliary] = [
                    ("Hilfe", { findMenuItem(titled: L10n.string("Fastra-Hilfe"), in: NSApp.mainMenu) },
                     HelpWindow.isHelpWindow),
                    ("Einstellungen", { menuItem(forExactKeyEquivalent: ",", modifiers: .command,
                                                  in: NSApp.mainMenu) },
                     SettingsWindowConfiguration.isSettingsWindow),
                    ("Über", { findMenuItem(titled: L10n.string("Über Fastra"), in: NSApp.mainMenu) },
                     AboutWindow.isAboutWindow)
                ]
                for auxiliary in auxiliaries {
                    guard let openingItem = auxiliary.item() else {
                        finish(false, auxiliary.label + ": echter Menüeintrag fehlt")
                    }
                    try await performCommandOwnerMenuItem(openingItem)
                    try await awaitCommandOwnerState(auxiliary.label + " Key und Soft Wrap deaktiviert") {
                        NSApp.mainMenu?.update()
                        let item = findMenuItem(titled: "Soft Wrap", in: NSApp.mainMenu)
                        return auxiliary.matches(NSApp.keyWindow) && item?.isEnabled == false
                            && item?.state == .off
                    }
                    guard let auxiliaryWindow = NSApp.keyWindow,
                          ActiveDocumentContext.shared.workspace === second,
                          profilesAreUntouched(),
                          let wrapItem = findMenuItem(titled: "Soft Wrap", in: NSApp.mainMenu) else {
                        finish(false, auxiliary.label + ": Dokumentkontext oder Profil vor Bedienung verändert")
                    }
                    try await performCommandOwnerMenuItem(wrapItem, ticks: 80, pause: 0.1,
                                                          expectsEnabled: false, expectedState: .off)
                    guard auxiliary.matches(NSApp.keyWindow), profilesAreUntouched(),
                          ActiveDocumentContext.shared.workspace === second,
                          CommandTargeting.targetWorkspace() == nil else {
                        finish(false, auxiliary.label + ": deaktivierte Menüprobe änderte Profil, Key oder Dokumentkontext")
                    }
                    try await deliverSoftWrapShortcut(to: auxiliaryWindow)
                    guard auxiliary.matches(NSApp.keyWindow), profilesAreUntouched(),
                          ActiveDocumentContext.shared.workspace === second,
                          CommandTargeting.targetWorkspace() == nil else {
                        finish(false, auxiliary.label + ": Soft Wrap änderte Hintergrundprofil oder Settingskontext")
                    }
                    auxiliaryWindow.close()
                    // Den Rückweg nicht mit makeKey/makeFirstResponder reparieren.
                    try await awaitCommandOwnerState(auxiliary.label + " gibt letzten Dokumentkontext frei") {
                        NSApp.mainMenu?.update()
                        let item = findMenuItem(titled: "Soft Wrap", in: NSApp.mainMenu)
                        return secondWindow.isKeyWindow && item?.isEnabled == true && item?.state == .on
                    }
                }
                firstWindow.makeKeyAndOrderFront(nil)
                try await awaitCommandOwnerState("4D-Haken nach Hilfsfenstern weiterhin aus") {
                    NSApp.mainMenu?.update()
                    let item = findMenuItem(titled: "Soft Wrap", in: NSApp.mainMenu)
                    return firstWindow.isKeyWindow && item?.isEnabled == true && item?.state == .off
                        && profilesAreUntouched()
                }
                finish(true, "bestehende Formatprofilkette synchron; Hilfe, Einstellungen und Über "
                    + "sperren natives Soft-Wrap-Menü und Shortcut ohne Profiländerung; "
                    + "letzter Dokumentkontext und getrennte Dokument-Haken erhalten")
            } catch {
                finish(error is SelfTestMenuRootExchange.EnvironmentFailure ? .environment
                    : ((error as NSError).domain == "SelfTestTrackedMainMenu" || NSApp.isActive ? .fail : .environment),
                       "Soft-Wrap-Hilfsfenster: \(error.localizedDescription)")
            }
        }
    }

    private static func pollSoftWrapState(
        ws: Workspace, root: NSView,
        expectedFormat: DocumentFormatID, expectedWrap: Bool,
        expectedTarget: SoftWrapTarget? = nil,
        requireWrappedGeometry: Bool = false,
        label: String, completion: @escaping () -> Void
    ) {
        var textView: TextView?
        var menuItem: NSMenuItem?
        var layoutFragmentCount = 0
        waitFor(budget: 8, pause: 0.1,
                condition: {
                    textView = editorTextView(in: root) as? TextView
                    // Der Poll beobachtet den Haken; die tatsächliche Bedienung
                    // öffnet und validiert das Menü getrennt im Tracking-Helfer.
                    NSApp.mainMenu?.update()
                    menuItem = findMenuItem(titled: "Soft Wrap", in: NSApp.mainMenu)
                    let menuMatches = menuItem?.state == (expectedWrap ? .on : .off)
                    let targetMatches = expectedTarget.map { ws.softWrapTarget == $0 } ?? true
                    layoutFragmentCount = 0
                    var geometryMatches = !requireWrappedGeometry
                    if requireWrappedGeometry, let textView,
                       let scrollView = textView.enclosingScrollView {
                        textView.layoutManager.layoutLines()
                        layoutFragmentCount = Array(textView.layoutManager.lineStorage)
                            .reduce(0) { $0 + $1.data.lineFragments.count }
                        geometryMatches = layoutFragmentCount > 1
                            && !scrollView.hasHorizontalScroller
                    }
                    return ws.activeDocumentFormat.id == expectedFormat
                        && ws.softWrapEnabled == expectedWrap
                        && textView?.wrapLines == expectedWrap
                        && menuMatches && targetMatches && geometryMatches
                },
                onTimeout: { book in
                    finish(false, "\(label) nicht sichtbar: "
                        + "format=\(ws.activeDocumentFormat.id.rawValue), "
                        + "store=\(ws.softWrapEnabled), textView=\(String(describing: textView?.wrapLines)), "
                        + "menu=\(String(describing: menuItem?.state.rawValue)), "
                        + "target=\(ws.softWrapTarget.rawValue), "
                        + "Fragmente=\(layoutFragmentCount), "
                        + "H-Scroller=\(String(describing: textView?.enclosingScrollView?.hasHorizontalScroller)) "
                        + "— \(book.summary)")
                },
                then: completion)
    }

    private static func findMenuItem(titled title: String, in menu: NSMenu?) -> NSMenuItem? {
        guard let menu else { return nil }
        for item in menu.items {
            if item.title == title { return item }
            if let found = findMenuItem(titled: title, in: item.submenu) {
                return found
            }
        }
        return nil
    }

    // MARK: - -selftest softwrapindent

    /// Treibt das gespeicherte Formatprofil durch den normalen SwiftUI-Editor.
    /// Kernabfragen werden gegen sichtbare Fragment-Views und echte Klicks geprüft.
    private static func runSoftWrapIndentTest() {
        testLabel = "softwrapindent"
        guard let ws = Workspace.shared,
              let window = NSApp.orderedWindows.first(where: {
                  $0.isVisible && $0.frameAutosaveName != SearchWindow.frameAutosaveName
              }), let root = window.contentView else {
            finish(false, "Dokumentfenster fehlt")
        }
        let row = "    " + String(repeating: "Wort 👨‍👩‍👧‍👦 e\u{301} ", count: 25)
        let content = row + "\n \t  " + String(repeating: "Text 🇩🇪 ", count: 12)
            + "\n    " + String(repeating: "weiter ", count: 1500)
        let fixture = selfTestTemporaryDirectory().appendingPathComponent("fastra-softwrapindent-\(UUID().uuidString).txt")
        do { try content.write(to: fixture, atomically: true, encoding: .utf8) }
        catch { finish(false, "Fixture nicht schreibbar") }
        workspaceDefaults().set(true, forKey: "editor.showMinimap")
        ws.loadFile(at: fixture) { ok in
            try? FileManager.default.removeItem(at: fixture)
            guard ok else { finish(false, "Fixture nicht ladbar") }
            pollForStableSoftWrapEditor(ws: ws, root: root) { initial, _ in
                let identity = ObjectIdentifier(initial)
                ws.setIndentWidth(2)
                ws.setEditorTabWidth(8)
                ws.setSoftWrapEnabled(false)
                ws.setSoftWrapIndentation(.reverse)
                waitFor(budget: 5, pause: 0.05, condition: {
                    guard let tv = editorTextView(in: root) as? TextView else { return false }
                    return tv.layoutManager.softWrapIndentation == .reverse && !tv.wrapLines
                }, onTimeout: { _ in finish(false, "Profilwechsel aktiviert Wrap oder erreicht den Controller nicht") }, then: {
                    let widths: [CGFloat] = [760, 1100]
                    let combinations = widths.flatMap { width in
                        [0, 3].flatMap { zoom in
                            SoftWrapTarget.allCases.flatMap { target in
                                SoftWrapIndentation.allCases.map { (width, zoom, target, $0) }
                            }
                        }
                    }
                    var index = 0
                    func findMinimap(_ view: NSView) -> MinimapView? {
                        if let mini = view as? MinimapView { return mini }
                        return view.subviews.compactMap { findMinimap($0) }.first
                    }
                    func step() {
                        guard index < combinations.count else {
                            runSoftWrapIndentDragChecks(ws: ws, window: window, root: root, modeIndex: 0) {
                                func done() {
                                    window.orderOut(nil)
                                    finish(true, "36 Profilkombinationen: 3 Modi × 3 Ziele × 2 Breiten × 2 Zoomstufen; sichtbare Fragmente, Klick/Caret, Auswahl, NSTextInput-Komposition, Rechteck-Paste/Undo/Redo, Minimap sowie echter Drag/Auto-Scroll in allen Modi; reale IME separat abnehmen")
                                }
                                guard let directory = ProcessInfo.processInfo.environment["FASTRA_SOFTWRAPINDENT_REVIEW_DIR"],
                                      !directory.isEmpty else {
                                    done(); return
                                }
                                // Optionales Abnahmefenster innerhalb derselben isolierten
                                // Testinstanz; kein Zugriff auf den normalen Arbeitsbereich.
                                let base = URL(fileURLWithPath: directory)
                                window.setContentSize(NSSize(width: CGFloat(Int(ProcessInfo.processInfo.environment["FASTRA_SOFTWRAPINDENT_REVIEW_WIDTH"] ?? "760") ?? 760), height: 800))
                                ws.setSoftWrapIndentation(.firstLine)
                                var prepared = false
                                waitFor(budget: 5, pause: 0.05, condition: {
                                    guard let tv = editorTextView(in: root) as? TextView,
                                          tv.layoutManager.softWrapIndentation == .firstLine else { return false }
                                    root.layoutSubtreeIfNeeded()
                                    tv.selectionManager.setSelectedRange(NSRange(location: 4, length: 0))
                                    if let scroll = tv.enclosingScrollView {
                                        scroll.contentView.scroll(to: .zero)
                                        scroll.reflectScrolledClipView(scroll.contentView)
                                    }
                                    let wasPrepared = prepared
                                    prepared = true
                                    return wasPrepared
                                }, onTimeout: { _ in finish(false, "Abnahme-Profil nicht bereit") }, then: {
                                    do {
                                        try FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
                                        try Data("ready\n".utf8).write(to: base.appendingPathComponent("ready"))
                                    } catch { finish(.environment, "Abnahme-Marker nicht schreibbar") }
                                })
                                waitFor(budget: 300, pause: 0.1, condition: {
                                    if let tv = editorTextView(in: root) as? TextView {
                                        let manager = tv.layoutManager!
                                        var geometry = "mode=\(manager.softWrapIndentation.rawValue) columns=\(manager.softWrapIndentationColumns)\n"
                                        for index in 0...2 {
                                            guard let line = manager.textLineForIndex(index) else { continue }
                                            let fragments = line.data.lineFragments.prefix(2).map { fragment in
                                                let view = tv.subviews.compactMap { $0 as? LineFragmentView }
                                                    .first(where: { $0.lineFragment === fragment.data })
                                                return "\(fragment.index):offset=\(fragment.data.xOffset),view=\(view?.frame.minX ?? -1)"
                                            }.joined(separator: ";")
                                            geometry += "line=\(index) firstText=\(manager.rectForOffset(line.range.location + 4)?.minX ?? -1) \(fragments)\n"
                                        }
                                        try? Data(geometry.utf8).write(to: base.appendingPathComponent("geometry.txt"))
                                    }
                                    return FileManager.default.fileExists(atPath: base.appendingPathComponent("continue").path)
                                }, onTimeout: { _ in finish(.environment, "Manuelle Abnahme nicht freigegeben") }, then: {
                                    guard (editorTextView(in: root) as? TextView)?.string == content else {
                                        finish(false, "Abnahmefenster enthält nicht zurückgenommene Testeingabe")
                                    }
                                    done()
                                })
                            }
                            return
                        }
                        let (width, zoom, target, mode) = combinations[index]
                        window.setContentSize(NSSize(width: width, height: 800))
                        workspaceDefaults().set(zoom, forKey: DocumentZoom.defaultsKey)
                        ws.setPageGuideColumn(36)
                        ws.setSoftWrapFixedColumn(32)
                        ws.selectSoftWrapTarget(target)
                        ws.setSoftWrapIndentation(mode)
                        let label = "\(mode.rawValue)/\(target.rawValue)/\(Int(width))/zoom\(zoom)"
                        var sawReady = false
                        waitFor(budget: 8, pause: 0.05, condition: {
                            guard let tv = editorTextView(in: root) as? TextView,
                                  let mini = findMinimap(root), !mini.isHidden,
                                  ObjectIdentifier(tv) == identity,
                                  tv.string == content, ws.activeTab?.content == content,
                                  tv.layoutManager.softWrapIndentation == mode,
                                  tv.layoutManager.softWrapIndentationColumns == 2,
                                  abs(tv.font.pointSize - 13 * DocumentZoom.scale(for: zoom)) < 0.1 else { return false }
                            root.layoutSubtreeIfNeeded()
                            mini.contentView.layoutSubtreeIfNeeded()
                            guard tv.wrapLines && tv.layoutManager.lineStorage.first?.data.lineFragments.count ?? 0 > 1 else { return false }
                            // Das Reconcile setzt den Manager vor dem nächsten
                            // SwiftUI-Layout; auch die weiteren Zeilen müssen folgen.
                            let wasReady = sawReady
                            sawReady = true
                            return wasReady
                        }, onTimeout: { _ in
                            let tv = editorTextView(in: root) as? TextView
                            finish(false, "\(label): Reconcile/Minimap nicht bereit; Editoridentität=\(tv.map { ObjectIdentifier($0) == identity } ?? false), Text=\(tv?.string == content), Modell=\(ws.activeTab?.content == content)")
                        }, then: {
                            guard let tv = editorTextView(in: root) as? TextView,
                                  ObjectIdentifier(tv) == identity, tv.string == content,
                                  let mini = findMinimap(root) else { finish(false, "\(label): Editor/Inhalt ersetzt") }
                            window.makeFirstResponder(tv)
                            let manager = tv.layoutManager!
                            if let scroll = tv.enclosingScrollView {
                                scroll.contentView.scroll(to: .zero)
                                scroll.reflectScrolledClipView(scroll.contentView)
                            }
                            if let tabLine = manager.textLineForIndex(1),
                               let tabFragment = tabLine.data.lineFragments.first(where: { $0.index == 1 }) {
                                let firstText = manager.rectForOffset(tabLine.range.location + 4)!.minX
                                let cell = (" " as NSString).size(withAttributes: [.font: tv.font, .kern: tv.kern]).width
                                let expected = mode == .flushLeft ? manager.edgeInsets.left
                                    : firstText + (mode == .reverse ? 2 * cell : 0)
                                guard abs(manager.fragmentOriginX(for: tabFragment.data) - expected) < 0.6,
                                      let view = tv.subviews.compactMap({ $0 as? LineFragmentView }).first(where: {
                                          $0.lineFragment === tabFragment.data
                                      }), abs(view.frame.minX - expected) < 0.6 else {
                                    finish(false, "\(label): sichtbarer Tab-Einzug passt nicht zur ersten Zeile/Stufe")
                                }
                            }
                            guard let line = manager.lineStorage.first,
                                  let fragment = line.data.lineFragments.first(where: { $0.index == 1 }) else {
                                finish(false, "\(label): Folgefragment fehlt")
                            }
                            let cell = (" " as NSString).size(withAttributes: [.font: tv.font, .kern: tv.kern]).width
                            let expected = CGFloat(mode == .flushLeft ? 0 : mode == .firstLine ? 4 : 6) * cell
                            let offset = line.range.location + fragment.range.location
                            guard abs(fragment.data.xOffset - expected) < 0.6,
                                  let visible = tv.subviews.compactMap({ $0 as? LineFragmentView }).first(where: {
                                      $0.lineFragment === fragment.data
                                  }), abs(visible.frame.minX - manager.edgeInsets.left - expected) < 0.6 else {
                                finish(false, "\(label): sichtbarer Ursprung falsch")
                            }
                            let clickLocal = NSPoint(x: visible.frame.minX + 0.1, y: visible.frame.midY)
                            guard sendMouseClick(at: tv.convert(clickLocal, to: nil), in: window, modifiers: []),
                                  tv.selectedRange() == NSRange(location: offset, length: 0),
                                  let caret = manager.rectForOffset(offset), abs(caret.minX - visible.frame.minX) < 0.6 else {
                                finish(false, "\(label): Klick/Caret neben sichtbarem Text; offset=\(offset), selection=\(tv.selectedRange()), frame=\(visible.frame), rect=\(String(describing: manager.rectForOffset(offset))), click=\(clickLocal), viewport=\(tv.visibleRect), hit=\(String(describing: window.contentView?.hitTest(tv.convert(clickLocal, to: window.contentView))))")
                            }
                            // NSTextInputClient wird von echter IME und Kandidatenfenster benutzt.
                            let screenRect = tv.firstRect(forCharacterRange: NSRange(location: offset, length: 0), actualRange: nil)
                            let observedScreen = window.convertToScreen(tv.convert(visible.frame, to: nil))
                            guard abs(screenRect.minX - observedScreen.minX) < 0.6,
                                  tv.characterIndex(for: NSPoint(x: screenRect.minX + 0.1, y: screenRect.midY)) == offset else {
                                finish(false, "\(label): IME-Position/Hit-Test falsch")
                            }
                            tv.setMarkedText("かな" as NSString, selectedRange: NSRange(location: 2, length: 0),
                                replacementRange: NSRange(location: NSNotFound, length: 0))
                            manager.layoutLines()
                            guard tv.hasMarkedText(), tv.markedRange().location == offset else {
                                finish(false, "\(label): Komposition nicht am geklickten Fragment")
                            }
                            let markedRect = tv.firstRect(forCharacterRange: tv.markedRange(), actualRange: nil)
                            guard abs(markedRect.minX - screenRect.minX) < 0.6 else {
                                finish(false, "\(label): Kandidatenanker bei Komposition verschoben")
                            }
                            tv.unmarkText()
                            guard tv.string == content else { finish(false, "\(label): Abbruch der Komposition verändert den Text") }
                            manager.layoutLines()
                            let selected = (content as NSString).rangeOfComposedCharacterSequence(at: offset)
                            tv.selectionManager.setSelectedRange(selected)
                            guard let fill = manager.rectsFor(range: selected).first,
                                  abs(fill.minX - manager.edgeInsets.left - expected) < 0.6 else {
                                finish(false, "\(label): Auswahl neben Text")
                            }
                            mini.synchronizeFastraFragmentGeometry()
                            mini.contentView.layoutSubtreeIfNeeded()
                            let miniature = mini.contentView.subviews.compactMap { $0 as? LineFragmentView }
                            guard miniature.contains(where: { $0.lineFragment?.documentRange.location == offset }) else {
                                finish(false, "\(label): Minimap nutzt andere Fragmentgrenzen")
                            }
                            // Logische Rechteckzeilen bleiben trotz vieler Folgefragmente zwei.
                            tv.selectionManager.setSelectedRange(NSRange(location: 4, length: 4))
                            guard tv.fastraSelectColumn(upwards: false),
                                  let column = tv.fastraColumnSelectionSnapshot,
                                  column.lineIndices == [0, 1] else {
                                finish(false, "\(label): Rechteck zählt Folgefragmente als Zeilen")
                            }
                            let beforeUndo = tv._undoManager?.undoCount ?? 0
                            writeSelfTestPasteboardString("A\nB")
                            tv.paste(tv)
                            guard tv.string != content, tv._undoManager?.undoCount == beforeUndo + 1 else {
                                finish(false, "\(label): Rechteck-Paste/Undo-Gruppe falsch")
                            }
                            let pasted = tv.string
                            tv._undoManager?.undo()
                            guard tv.string == content else { finish(false, "\(label): Undo falsch") }
                            tv._undoManager?.redo()
                            guard tv.string == pasted else { finish(false, "\(label): Redo falsch") }
                            tv._undoManager?.undo()
                            tv._undoManager?.clearStack()
                            tv.selectionManager.setSelectedRange(selected)
                            manager.layoutLines()
                            if let scroll = tv.enclosingScrollView {
                                scroll.contentView.scroll(to: .zero)
                                scroll.reflectScrolledClipView(scroll.contentView)
                            }
                            func next() {
                                index += 1
                                DispatchQueue.main.async(execute: step)
                            }
                            if zoom == 0, target == .window,
                               let directory = ProcessInfo.processInfo.environment["FASTRA_SOFTWRAPINDENT_DIR"] {
                                window.contentView?.displayIfNeeded()
                                let url = URL(fileURLWithPath: directory).appendingPathComponent("editor-\(mode.rawValue)-\(Int(width)).png")
                                typeScrollSystemCapture(windowNumber: window.windowNumber) { data in
                                    guard let data else { finish(.environment, "Fensteraufnahme fehlt") }
                                    do {
                                        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                                        try data.write(to: url)
                                    } catch { finish(.environment, "Aufnahme nicht speicherbar") }
                                    next()
                                }
                            } else { next() }
                        })
                    }
                    step()
                })
            }
        }
    }

    private static func runSoftWrapIndentDragChecks(
        ws: Workspace, window: NSWindow, root: NSView, modeIndex: Int,
        completion: @escaping () -> Void
    ) {
        guard modeIndex < SoftWrapIndentation.allCases.count else { completion(); return }
        let mode = SoftWrapIndentation.allCases[modeIndex]
        ws.selectSoftWrapTarget(.window)
        ws.setSoftWrapIndentation(mode)
        workspaceDefaults().set(0, forKey: DocumentZoom.defaultsKey)
        waitFor(budget: 5, pause: 0.05, condition: {
            guard let tv = editorTextView(in: root) as? TextView else { return false }
            return tv.layoutManager.softWrapIndentation == mode && abs(tv.font.pointSize - 13) < 0.1
        }, onTimeout: { _ in finish(false, "Drag-Profil nicht reconciled") }, then: {
            guard let tv = editorTextView(in: root) as? TextView,
                  let scroll = tv.enclosingScrollView else { finish(false, "Drag-Editor fehlt") }
            guard NSApp.isActive, window.isKeyWindow, window.makeFirstResponder(tv) else {
                finish(.environment, "Drag-Test benötigt tatsächlichen Fensterfokus")
            }
            scroll.contentView.scroll(to: .zero)
            scroll.reflectScrolledClipView(scroll.contentView)
            tv.layoutManager.layoutLines()
            guard tv.frame.height > scroll.documentVisibleRect.height else {
                finish(false, "Drag-Fixture nicht scrollbar: Text=\(tv.frame.height), sichtbar=\(scroll.documentVisibleRect.height)")
            }
            guard let first = tv.layoutManager.lineStorage.first,
                  let fragment = first.data.lineFragments.first(where: { $0.index == 1 }),
                  let view = tv.subviews.compactMap({ $0 as? LineFragmentView }).first(where: {
                      $0.lineFragment === fragment.data
                  }) else { finish(false, "Drag-Folgefragment fehlt") }
            let anchor = first.range.location + fragment.range.location
            tv.selectionManager.setSelectedRange(NSRange(location: anchor, length: 0))
            let point = tv.convert(NSPoint(x: view.frame.minX + 0.1, y: view.frame.midY), to: nil)
            let target = NSPoint(x: point.x, y: -40)
            let before = scroll.documentVisibleRect.minY
            func event(_ type: NSEvent.EventType, _ at: NSPoint) -> NSEvent {
                let time = ProcessInfo.processInfo.systemUptime
                guard let result = NSEvent.mouseEvent(with: type, location: at, modifierFlags: [],
                    timestamp: time, windowNumber: window.windowNumber, context: nil,
                    eventNumber: Int(time * 1000), clickCount: 1, pressure: type == .leftMouseUp ? 0 : 1) else {
                    finish(false, "Drag-Ereignis fehlt")
                }
                return result
            }
            tv.mouseDown(with: event(.leftMouseDown, point))
            var tick = 0
            waitFor(budget: 2, pause: 0.03, condition: {
                NSApp.postEvent(event(.leftMouseDragged, target), atStart: false)
                tick += 1
                return tick >= 25
            }, onTimeout: { _ in finish(false, "Drag-Ereignisfolge nicht abgeschlossen") }, then: {
                // Vor dem nächsten Modus muss Mouse-up wirklich zugestellt sein;
                // sonst löscht es den bereits neu gesetzten Drag-Anker.
                var mouseUpDelivered = false
                let monitor = NSEvent.addLocalMonitorForEvents(matching: .leftMouseUp) { event in
                    if event.windowNumber == window.windowNumber { mouseUpDelivered = true }
                    return event
                }
                NSApp.postEvent(event(.leftMouseUp, target), atStart: false)
                waitFor(budget: 2, pause: 0.05, condition: {
                    mouseUpDelivered && tv.selectedRange().location == anchor && tv.selectedRange().length > 0
                        && scroll.documentVisibleRect.minY > before + 1
                }, onTimeout: { _ in
                    if let monitor { NSEvent.removeMonitor(monitor) }
                    finish(false, "\(mode.rawValue): Drag-Anker/Auto-Scroll falsch: Auswahl=\(tv.selectedRange()), Anker=\(anchor), vorher=\(before), nachher=\(scroll.documentVisibleRect.minY)")
                }, then: {
                    if let monitor { NSEvent.removeMonitor(monitor) }
                    runSoftWrapIndentDragChecks(ws: ws, window: window, root: root,
                        modeIndex: modeIndex + 1, completion: completion)
                })
            })
        })
    }

    // MARK: - -selftest softwrapindentcore

    /// Paket 02 prüft den Layoutkern direkt. Profilaktivierung und Menü folgen separat.
    private static func runSoftWrapIndentCoreTest() {
        testLabel = "softwrapindentcore"
        let content = "    " + String(repeating: "Wort 👨‍👩‍👧‍👦 e\u{301} ", count: 8)
            + "\n \t  " + String(repeating: "Langtoken", count: 50)
        let controller = TextViewController(string: content, language: .default,
            configuration: .init(appearance: .init(theme: EditorView.fastraTheme,
                font: .monospacedSystemFont(ofSize: 15, weight: .regular),
                wrapLines: true, tabWidth: 4),
                layout: .init(contentInsets: NSEdgeInsets(top: 0, left: 0, bottom: 0, right: 0),
                    additionalTextInsets: NSEdgeInsets(top: 0, left: 0, bottom: 0, right: 0)),
                peripherals: .init(showMinimap: false)),
            cursorPositions: [])
        controller.loadView()
        controller.view.wantsLayer = true
        let window = NSWindow(contentRect: NSRect(x: 150, y: 150, width: 700, height: 500),
            styleMask: [.titled, .closable, .resizable], backing: .buffered, defer: false)
        window.isReleasedWhenClosed = false
        window.appearance = NSAppearance(named: .aqua)
        window.title = "Soft Wrap – Layoutkern"
        window.contentViewController = controller
        activateApplication(ignoringOtherApps: true)
        window.makeKeyAndOrderFront(nil)
        window.makeFirstResponder(controller.textView)
        let textView = controller.textView!
        let manager = textView.layoutManager!
        let undoBefore = textView.undoManager?.canUndo
        let snapshotDir = ProcessInfo.processInfo.environment["FASTRA_SOFTWRAPINDENT_DIR"]
        let combinations = [CGFloat(300), CGFloat(700)].flatMap { width in
            SoftWrapIndentation.allCases.map { (width, $0) }
        }
        var index = 0
        func step() {
            guard index < combinations.count else {
                guard textView.string == content, textView.undoManager?.canUndo == undoBefore else {
                    finish(false, "Layout hat Text oder Undo verändert")
                }
                window.orderOut(nil)
                window.close()
                finish(true, "3 Modi × 2 Breiten: Fragment-Views, reduzierter Umbruchraum, echte Klicks und Screenshots; reine Kernabnahme")
            }
            let (width, mode) = combinations[index]
            window.setContentSize(NSSize(width: width, height: 500))
            manager.softWrapIndentation = mode
            manager.softWrapIndentationColumns = 4
            var previousFrames: [NSRect]?
            waitFor(budget: 5, pause: 0.05, condition: {
                guard window.isKeyWindow, textView.window === window,
                      abs(controller.view.bounds.width - width) < 1 else { return false }
                controller.view.layoutSubtreeIfNeeded()
                manager.layoutLines()
                let frames = [textView.frame, controller.view.bounds,
                    textView.enclosingScrollView?.contentView.bounds ?? .zero]
                let stable = previousFrames == frames
                previousFrames = frames
                return stable
            }, onTimeout: { _ in
                finish(.environment, "Kernfenster nicht bereit: key=\(window.isKeyWindow), montiert=\(textView.window === window), Breite=\(controller.view.bounds.width), erwartet=\(width)")
            }, then: {
                controller.view.layoutSubtreeIfNeeded()
                manager.layoutLines()
                let cell = (" " as NSString).size(withAttributes: [.font: textView.font, .kern: textView.kern]).width
                let expected = mode == .flushLeft ? 0 : (mode == .firstLine ? 4 : 8) * cell
                guard let line = manager.lineStorage.first,
                      let continuation = line.data.lineFragments.first(where: { $0.index == 1 }) else {
                    finish(false, "Folgefragment fehlt")
                }
                let offset = line.range.location + continuation.range.location
                guard abs(continuation.data.xOffset - expected) < 0.6,
                      let rect = manager.rectForOffset(offset),
                      abs(rect.minX - manager.edgeInsets.left - expected) < 0.6 else {
                    finish(false, "\(mode.rawValue)/\(width): Ursprung inkonsistent")
                }
                // Sichtbarer NSView-Ursprung wird unabhängig von rectForOffset beobachtet.
                guard textView.subviews.contains(where: { view in
                    String(describing: type(of: view)).contains("LineFragmentView")
                        && abs(view.frame.minY - rect.minY) < 0.6
                        && abs(view.frame.minX - manager.edgeInsets.left - expected) < 0.6
                }) else { finish(false, "Fragment-View zeichnet am falschen Ursprung") }
                for fragment in line.data.lineFragments {
                    let available = manager.maxLineLayoutWidth - fragment.data.xOffset
                    if fragment.data.width > available + 0.6 {
                        let ns = content as NSString
                        let cluster = ns.rangeOfComposedCharacterSequence(at: fragment.range.location)
                        guard fragment.range.length == cluster.length else {
                            finish(false, "Folgefragment überschreitet reduzierten Umbruchraum")
                        }
                    }
                }
                let range = NSRange(location: offset, length: 4)
                guard let selected = manager.rectsFor(range: range).first,
                      abs(selected.minX - rect.minX) < 1 else {
                    finish(false, "Auswahlrechteck liegt neben dem Text")
                }
                textView.selectionManager.setSelectedRange(range)
                func finishStep() {
                    // Die asynchrone Aufnahme kann weitere AppKit-Layouts zulassen.
                    // Messung und synchrone Klickzustellung bleiben im selben Durchlauf.
                    manager.layoutLines()
                    guard let currentLine = manager.lineStorage.first,
                          let currentFragment = currentLine.data.lineFragments.first(where: { $0.index == 1 }) else {
                        finish(false, "Folgefragment vor Klick verschwunden")
                    }
                    let currentOffset = currentLine.range.location + currentFragment.range.location
                    guard let currentRect = manager.rectForOffset(currentOffset),
                          abs(currentRect.minX - manager.edgeInsets.left - expected) < 0.6 else {
                        finish(false, "Fragmentursprung vor Klick inkonsistent")
                    }
                    let click = textView.convert(NSPoint(x: currentRect.minX + 0.1, y: currentRect.midY), to: nil)
                    guard sendMouseClick(at: click, in: window, modifiers: []) else {
                        finish(false, "Klick konnte nicht zugestellt werden")
                    }
                    guard textView.selectedRange() == NSRange(location: currentOffset, length: 0) else {
                        finish(false, "Klick auf Folgefragment landet auf \(textView.selectedRange()), erwartet \(currentOffset)")
                    }
                    index += 1
                    DispatchQueue.main.async(execute: step)
                }
                if let snapshotDir {
                    // Die Testauswahl darf die erste Zeile im Vergleichsbild nicht wegscrollen.
                    manager.layoutLines()
                    if let scrollView = textView.enclosingScrollView {
                        let clip = scrollView.contentView
                        clip.scroll(to: textView.convert(.zero, to: clip))
                        scrollView.reflectScrolledClipView(scrollView.contentView)
                    }
                    manager.layoutLines()
                    guard let firstView = textView.subviews.first(where: { view in
                              String(describing: type(of: view)).contains("LineFragmentView")
                                  && abs(view.frame.minY - line.yPos) < 0.6
                                  && abs(view.frame.minX - manager.edgeInsets.left) < 0.6
                          }),
                          firstView.bounds.height > 1,
                          abs(firstView.visibleRect.minY - firstView.bounds.minY) < 0.6,
                          firstView.visibleRect.maxY >= firstView.bounds.maxY - 0.6 else {
                        finish(false, "Erstes Fragment im Vergleichsbild abgeschnitten")
                    }
                    window.contentView?.displayIfNeeded()
                    let url = URL(fileURLWithPath: snapshotDir, isDirectory: true)
                        .appendingPathComponent("core-\(mode.rawValue)-\(Int(width)).png")
                    // Der vorhandene System-Aufnahmeweg erfasst das echte Fenster,
                    // ohne Cache-/Layer-Koordinaten beim Rasterisieren umzudeuten.
                    typeScrollSystemCapture(windowNumber: window.windowNumber) { data in
                        guard let data else { finish(.environment, "Fensteraufnahme nicht verfügbar") }
                        do {
                            try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                            try data.write(to: url)
                        } catch { finish(.environment, "Snapshot nicht speicherbar") }
                        finishStep()
                    }
                } else {
                    finishStep()
                }
            })
        }
        DispatchQueue.main.async(execute: step)
    }

    // MARK: - -selftest softwrapmodes

    /// Prüft die drei Umbruchziele am laufenden Editor. Der Test misst die
    /// echte CodeEdit-Layoutbreite, die Seitenlinienposition und die
    /// Fortschrittsgarantie der erzeugten Fragmente. Zielwechsel, Resize und
    /// Font-Zoom dürfen dabei weder Text noch Auswahl, Dirty- oder Undo-Zustand
    /// verändern.
    private static func runSoftWrapModesTest() {
        testLabel = "softwrapmodes"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }) else {
            finish(false, "kein Hauptfenster gefunden")
        }

        waitForEditor(window: mainWindow) { root, _ in
            let tmp = selfTestTemporaryDirectory()
                .appendingPathComponent(
                    "fastra-softwrapmodes-\(UUID().uuidString).md"
                )
            let content = "Start\t"
                + String(repeating: "Wort ", count: 90)
                + String(repeating: "Langtoken", count: 80)
                + " 👨‍👩‍👧‍👦 Ende\n"
            do {
                try content.write(to: tmp, atomically: true, encoding: .utf8)
            } catch {
                finish(false, "Fixture nicht schreibbar: \(error.localizedDescription)")
            }

            ws.loadFile(at: tmp) { ok in
                try? FileManager.default.removeItem(at: tmp)
                guard ok else { finish(false, "Markdown-Fixture nicht ladbar") }
                // Bewusst der stabile Editor: Sonst merkt der Test die Identität
                // einer TextView, die gleich planmäßig ersetzt wird (isLoading-
                // Flip), und vergleicht später gegen ein totes Objekt.
                pollForStableSoftWrapEditor(ws: ws, root: root) { textView, _ in
                    let selection = NSRange(location: 2, length: 7)
                    textView.selectionManager.setSelectedRange(selection)
                    let identity = ObjectIdentifier(textView)
                    let textBefore = textView.string
                    let dirtyBefore = ws.activeTab?.isDirty
                    let canUndoBefore = textView.undoManager?.canUndo

                    logEditorIdentity("Start", root: root, expected: identity)
                    ws.setShowPageGuide(true)
                    ws.setPageGuideColumn(40)
                    ws.selectSoftWrapTarget(.window)
                    pollSoftWrapWindowGeometry(
                        ws: ws, root: root, guideColumn: 40) {
                        logEditorIdentity("nach Ziel=Fenster",
                                          root: root, expected: identity)
                        ws.setSoftWrapFixedColumn(40)
                        pollSoftWrapGeometry(
                            ws: ws, root: root, expectedTarget: .fixedColumn,
                            wrapColumn: 40, guideColumn: 40,
                            label: "feste Spalte") { _ in
                            logEditorIdentity("nach Ziel=feste Spalte 40",
                                              root: root, expected: identity)
                            ws.setPageGuideColumn(55)
                            ws.selectSoftWrapTarget(.pageGuide)
                            pollSoftWrapGeometry(
                                ws: ws, root: root, expectedTarget: .pageGuide,
                                wrapColumn: 55, guideColumn: 55,
                                label: "Seitenlinie") { pageGuideWidth in
                                logEditorIdentity("nach Ziel=Seitenlinie",
                                                  root: root, expected: identity)
                                var narrowFrame = mainWindow.frame
                                narrowFrame.size.width = 430
                                ws.setSoftWrapFixedColumn(120)
                                mainWindow.setFrame(narrowFrame, display: true)
                                pollSoftWrapGeometry(
                                    ws: ws, root: root,
                                    expectedTarget: .fixedColumn,
                                    wrapColumn: 120, guideColumn: 55,
                                    requireViewportClamp: true,
                                    label: "Viewport-Obergrenze") { _ in
                                    logEditorIdentity("nach Schmal-Resize auf 430",
                                                      root: root, expected: identity)
                                    ws.setPageGuideColumn(55)
                                    ws.selectSoftWrapTarget(.pageGuide)
                                    logEditorIdentity("nach Ziel=Seitenlinie (2.)",
                                                      root: root, expected: identity)
                                    mainWindow.setContentSize(
                                        NSSize(width: 900, height: 600)
                                    )
                                    logEditorIdentity("direkt nach Resize auf 900",
                                                      root: root, expected: identity)
                                    // Das Resize erst vollständig durch SwiftUI
                                    // reconciliieren lassen. Würden wir die
                                    // Controller-Schrift vorher ändern, spielt das
                                    // anschließende View-Update absichtlich die
                                    // aktuelle App-Zoom-Konfiguration wieder ein.
                                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                                        logEditorIdentity("0,6 s nach Resize",
                                                          root: root, expected: identity)
                                        guard let zoomController =
                                            sourceEditorController(for: textView) else {
                                            // Diagnose statt bloßem „verloren": Hängt die
                                            // gemerkte TextView überhaupt noch im Baum,
                                            // wie viele gibt es, und ist die aktuell
                                            // gefundene eine andere? Damit lässt sich
                                            // unterscheiden, ob nur die Responder-Kette
                                            // kurz unterbrochen ist oder der Editor
                                            // wirklich neu aufgebaut wurde.
                                            let live = editorTextView(in: root) as? TextView
                                            let sameView = live.map {
                                                ObjectIdentifier($0) == identity
                                            } ?? false
                                            finish(false, "Controller vor Font-Zoom verloren "
                                                   + "(TextViews im Baum: "
                                                   + "\(editorTextViewCount(in: root)); "
                                                   + "gemerkte TextView noch im Fenster: "
                                                   + "\(textView.window != nil); "
                                                   + "aktuell gefundene ist dieselbe: "
                                                   + "\(sameView))")
                                        }
                                        var zoomed = zoomController.configuration
                                        zoomed.appearance.font =
                                            .monospacedSystemFont(
                                                ofSize: 20, weight: .regular
                                            )
                                        zoomController.configuration = zoomed
                                        pollSoftWrapGeometry(
                                            ws: ws, root: root,
                                            expectedTarget: .pageGuide,
                                            wrapColumn: 55, guideColumn: 55,
                                            minimumConfiguredWidth: pageGuideWidth,
                                            label: "Font-Zoom") { _ in
                                            // Jede Bedingung einzeln melden. Vorher
                                            // fasste eine Sammelmeldung sechs
                                            // Zusagen zusammen; ein Fehlschlag sagte
                                            // dann nicht, was sich geändert hatte,
                                            // und war nicht diagnostizierbar
                                            guard let current =
                                                    editorTextView(in: root) as? TextView else {
                                                finish(false, "Editor-TextView nach dem Zoom "
                                                       + "nicht im View-Baum erreichbar")
                                            }
                                            var deviations: [String] = []
                                            if ObjectIdentifier(current) != identity {
                                                deviations.append(
                                                    "Editoridentität gewechselt (Editor neu "
                                                    + "aufgebaut; TextViews im Baum: "
                                                    + "\(editorTextViewCount(in: root)))")
                                            }
                                            if current.string != textBefore {
                                                deviations.append(
                                                    "Editortext geändert "
                                                    + "(\(current.string.count) statt "
                                                    + "\(textBefore.count) Zeichen)")
                                            }
                                            if current.selectedRange() != selection {
                                                deviations.append(
                                                    "Auswahl \(current.selectedRange()) statt "
                                                    + "\(selection)")
                                            }
                                            if ws.activeTab?.content != textBefore {
                                                deviations.append("Tab-Inhalt geändert")
                                            }
                                            if ws.activeTab?.isDirty != dirtyBefore {
                                                deviations.append(
                                                    "Dirty-Zustand "
                                                    + "\(String(describing: ws.activeTab?.isDirty))"
                                                    + " statt \(String(describing: dirtyBefore))")
                                            }
                                            if current.undoManager?.canUndo != canUndoBefore {
                                                deviations.append(
                                                    "Undo-Zustand "
                                                    + "\(String(describing: current.undoManager?.canUndo))"
                                                    + " statt \(String(describing: canUndoBefore))")
                                            }
                                            guard deviations.isEmpty else {
                                                finish(false, "Zielwechsel/Resize/Zoom: "
                                                       + deviations.joined(separator: "; "))
                                            }
                                            let fragments = Array(
                                                current.layoutManager.lineStorage
                                            ).flatMap {
                                                Array($0.data.lineFragments)
                                            }
                                            guard fragments.count > 1,
                                                  fragments.allSatisfy({
                                                      $0.range.length > 0
                                                  }) else {
                                                finish(
                                                    false,
                                                    "Wort-/Langtoken-/Unicode-Umbruch "
                                                        + "erzeugte leere Fragmente"
                                                )
                                            }
                                            finish(
                                                true,
                                                "Fenster, Seitenlinie und feste Spalte "
                                                    + "reagieren auf Resize/Zoom; Textzustand "
                                                    + "und Unicode-Fragmente bleiben intakt"
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // MARK: - -selftest softwrapanchor

    /// Reproduziert den sichtbaren Sprung beim Ein-/Ausschalten von Soft Wrap.
    /// Entscheidend ist nicht der absolute Scrollwert: Bei langen Zeilen ändert
    /// sich die Dokumenthöhe stark. Unabhängig beobachtet wird deshalb die
    /// tatsächlich oberste logische Textzeile über `textLineForPosition`.
    private static func runSoftWrapAnchorTest() {
        testLabel = "softwrapanchor"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }

        let longTail = String(repeating: "Wortgruppe ", count: 32)
        let content = (1...2_400).map {
            "Ankerzeile \($0)\t\(longTail)Ende \($0)"
        }.joined(separator: "\n")
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-softwrapanchor-\(UUID().uuidString).txt"
            )
        do {
            try content.write(to: tmp, atomically: true, encoding: .utf8)
        } catch {
            finish(false, "Fixture nicht schreibbar: \(error.localizedDescription)")
        }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "Text-Fixture nicht ladbar") }
            // `loadFile` meldet den Inhalt, bevor der isLoading-Flip seinen
            // planmäßigen Editor-Neuaufbau sicher beendet hat. Eine nur kurz
            // gefundene TextView kann deshalb später vom Fenster getrennt
            // sein und ihre Zielzeile niemals auslegen. Derselbe stabile
            // Editor-Wächter schützt bereits `softwrapmodes`.
            pollForStableSoftWrapEditor(ws: ws, root: root) { textView, _ in
                ws.setSoftWrapFixedColumn(40)
                pollSoftWrapState(
                    ws: ws, root: root, expectedFormat: .plainText,
                    expectedWrap: true, label: "Anker-Fixture umbrochen") {
                    let textBefore = textView.string
                    let selectionBefore = textView.selectedRange()
                    let dirtyBefore = ws.activeTab?.isDirty
                    let canUndoBefore = textView.undoManager?.canUndo
                    let targetTopLine = 1_799
                    convergeSoftWrapAnchor(
                        textView: textView, targetLine: targetTopLine) { expectedTopLine in
                        ws.toggleSoftWrap()
                        observeSoftWrapAnchor(
                            ws: ws, textView: textView,
                            expectedWrap: false,
                            expectedTopLine: expectedTopLine,
                            tick: 0, observedLines: [],
                            maximumDrift: 0
                        ) {
                            ws.toggleSoftWrap()
                            observeSoftWrapAnchor(
                                ws: ws, textView: textView,
                                expectedWrap: true,
                                expectedTopLine: expectedTopLine,
                                tick: 0, observedLines: [],
                                maximumDrift: 0
                            ) {
                                guard textView.string == textBefore,
                                      textView.selectedRange() == selectionBefore,
                                      ws.activeTab?.content == textBefore,
                                      ws.activeTab?.isDirty == dirtyBefore,
                                      textView.undoManager?.canUndo == canUndoBefore else {
                                    finish(
                                        false,
                                        "Umschalten veränderte Text, Auswahl, "
                                            + "Dirty- oder Undo-Zustand"
                                    )
                                }
                                verifySoftWrapGutterExtremes(
                                    textView: textView,
                                    window: mainWindow
                                ) {
                                    finish(
                                        true,
                                        "oberste Textzeile \(expectedTopLine + 1) "
                                            + "blieb mit synchronem Gutter bei "
                                            + "Aus und Ein ohne Zwischenabweichung identisch; "
                                            + "Dokumentanfang und -ende stimmen ebenfalls"
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // MARK: - -selftest selectionscroll

    /// Prüft im gepackten Editor den NSTextInputClient-Befehl, den AppKit für
    /// Shift+Pfeil nach unten aufruft. Die Messung verwendet bewusst die
    /// bewegte Range-Kante selbst und nicht CodeEdits Scroll-Hilfsfunktion.
    private static func runSelectionScrollTest() {
        testLabel = "selectionscroll"
        sessionRestorationTests.runSelectionScrollTest()
    }





    /// Scrollt iterativ, bis die Zielzeile wirklich oben liegt. Ein einmalig
    /// aus `rectForOffset` berechneter Wert wäre bei noch nicht ausgelegten
    /// langen Umbruchzeilen nur eine Schätzung und kein unabhängiger Repro.
    private static func convergeSoftWrapAnchor(
        textView: TextView, targetLine: Int,
        completion: @escaping (Int) -> Void
    ) {
        // Das Layout von 2.400 langen Umbruchzeilen brauchte nach einem
        // vollständigen GUI-Lauf auf demselben Mac einmal mehr als 1,5 s.
        // Der Erfolgsweg wartet nicht länger; nur der noch nicht layoutete
        // Zwischenzustand erhält dieselbe robuste 5-s-Frist wie andere
        // Editor-Selbsttests. Jeder Durchlauf prüft zuerst den Stand der
        // vorherigen Nachziehung und scrollt danach erneut nach.
        var layoutSeen = false
        var shownLine: Int?
        var gutterLine: Int?
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    if layoutSeen {
                        shownLine = textView.layoutManager.textLineForPosition(
                            textView.visibleRect.minY
                        )?.index
                        gutterLine = firstGutterLine(for: textView)
                        if let shown = shownLine, gutterLine == shown,
                           abs(shown - targetLine) <= 1 {
                            return true
                        }
                    }
                    guard let scrollView = textView.enclosingScrollView,
                          let line = textView.layoutManager.textLineForIndex(targetLine),
                          let rect = textView.layoutManager.rectForOffset(
                            line.range.location
                          ) else {
                        // Noch kein Layout für die Zielzeile: Unter Last ist das ein
                        // normaler Zwischenzustand, kein Befund.
                        return false
                    }
                    layoutSeen = true
                    let targetY = max(
                        rect.minY - scrollView.contentInsets.top,
                        0
                    )
                    scrollView.contentView.scroll(
                        to: NSPoint(
                            x: scrollView.contentView.bounds.origin.x,
                            y: targetY
                        )
                    )
                    scrollView.reflectScrolledClipView(scrollView.contentView)
                    textView.layoutManager.layoutLines()
                    return false
                },
                onTimeout: { book in
                    guard layoutSeen else {
                        finish(false, "Ankerzeile \(targetLine + 1) nicht layoutbar — \(book.summary)")
                    }
                    finish(
                        false,
                        "Ankerzeile \(targetLine + 1) nicht oben erreichbar; "
                            + "Text=\(shownLine.map { String($0 + 1) } ?? "nil"), "
                            + "Gutter=\(gutterLine.map { String($0 + 1) } ?? "nil") — \(book.summary)"
                    )
                },
                then: {
                    guard let shownLine else { finish(false, "Ankerzeile nach Erfolg nicht bestimmbar") }
                    completion(shownLine)
                })
    }

    /// Beobachtet nicht nur den Endzustand: Jede sichtbare Zwischenposition
    /// zählt. So schützt der Test auch vor den früheren asynchronen
    /// Nachkorrekturen, die den Text fast eine Sekunde auf- und abbewegten.
    private static func observeSoftWrapAnchor(
        ws: Workspace, textView: TextView,
        expectedWrap: Bool, expectedTopLine: Int,
        tick: Int, observedLines: [Int],
        maximumDrift: CGFloat,
        completion: @escaping () -> Void
    ) {
        let wrapApplied = ws.softWrapEnabled == expectedWrap
            && textView.wrapLines == expectedWrap
        let shown = textView.layoutManager.textLineForPosition(
            textView.visibleRect.minY
        )?.index
        let gutterShown = firstGutterLine(for: textView)

        var nextObservedLines = observedLines
        var nextMaximumDrift = maximumDrift
        if wrapApplied, let shown {
            if nextObservedLines.last != shown {
                nextObservedLines.append(shown)
            }
            if let anchor = textView.layoutManager.textLineForIndex(
                expectedTopLine
            ), let rect = textView.layoutManager.rectForOffset(
                anchor.range.location
            ) {
                nextMaximumDrift = max(
                    nextMaximumDrift,
                    abs(rect.minY - textView.visibleRect.minY)
                )
            }
        }

        if tick >= 60 {
            guard wrapApplied,
                  shown == expectedTopLine,
                  gutterShown == shown,
                  !nextObservedLines.isEmpty,
                  nextObservedLines.allSatisfy({ $0 == expectedTopLine }),
                  nextMaximumDrift <= 2 else {
                finish(
                    false,
                    "Soft Wrap \(expectedWrap ? "Ein" : "Aus") zappelte: "
                        + "erwartet Zeile \(expectedTopLine + 1), "
                        + "Gutter=\(gutterShown.map { String($0 + 1) } ?? "nil"), "
                        + "Folge=\(nextObservedLines.map { $0 + 1 }), "
                        + "maximale Drift=\(Int(nextMaximumDrift)) pt"
                )
            }
            completion()
            return
        }

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.02) {
            observeSoftWrapAnchor(
                ws: ws, textView: textView,
                expectedWrap: expectedWrap,
                expectedTopLine: expectedTopLine,
                tick: tick + 1,
                observedLines: nextObservedLines,
                maximumDrift: nextMaximumDrift,
                completion: completion
            )
        }
    }

    /// Liest dieselbe Zeilenmenge, die der echte CodeEdit-Gutter in seinem
    /// nächsten Zeichenlauf verwenden wird. Der frühere Test beobachtete nur
    /// den TextView und konnte einen entgegengesetzt scrollenden Gutter daher
    /// trotz korrekter Textzeile nicht erkennen.
    private static func firstGutterLine(for textView: TextView) -> Int? {
        guard let root = sourceEditorController(for: textView)?.view,
              let gutter = findView(named: "GutterView", in: root)
                as? GutterView else {
            return nil
        }
        return gutter.visibleLineIndicesForDrawing.first
    }

    /// Liest, ab welcher Zeile der Gutter zuletzt wirklich gezeichnet hat —
    /// aus dem Zeichenprotokoll des echten draw-Laufs, nicht aus der
    /// Vorberechnung derselben Zeilenauswahl. Nur so fällt auch eine falsche
    /// Y-Umrechnung der gezeichneten Nummern auf.
    private static func firstDrawnGutterLine(for textView: TextView) -> Int? {
        guard let root = sourceEditorController(for: textView)?.view,
              let gutter = findView(named: "GutterView", in: root)
                as? GutterView else {
            return nil
        }
        return gutter.lastDrawnLineNumbers.first?.index
    }

    /// Prüft zusätzlich die beiden Stellen, an denen der spiegelverkehrte
    /// Gutter im realen Befund am deutlichsten auffiel. In einer geeigneten
    /// GUI-Sitzung kann der Test bei Bedarf zwei Fensterbilder aus den
    /// Layer-Backing-Stores schreiben; dafür ist keine
    /// Bildschirmaufnahme-Berechtigung nötig.
    private static func verifySoftWrapGutterExtremes(
        textView: TextView,
        window: NSWindow,
        completion: @escaping () -> Void
    ) {
        guard let scrollView = textView.enclosingScrollView else {
            finish(false, "Editor-ScrollView für Gutter-Randprüfung fehlt")
        }
        let screenshotDirectory = ProcessInfo.processInfo.environment[
            "FASTRA_SOFTWRAPANCHOR_SCREENSHOT_DIR"
        ].map { URL(fileURLWithPath: $0, isDirectory: true) }

        scrollView.contentView.scroll(
            to: NSPoint(x: scrollView.contentView.bounds.origin.x, y: 0)
        )
        scrollView.reflectScrolledClipView(scrollView.contentView)
        textView.updatedViewport(scrollView.documentVisibleRect)
        textView.layoutManager.layoutLines(in: textView.visibleRect)

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) {
            let topText = textView.layoutManager.textLineForPosition(
                textView.visibleRect.minY
            )?.index
            let topGutter = firstGutterLine(for: textView)
            guard let topText, topText <= 1, topGutter == topText else {
                finish(
                    false,
                    "Gutter am Dokumentanfang abweichend: Text="
                        + "\(topText.map { String($0 + 1) } ?? "nil"), Gutter="
                        + "\(topGutter.map { String($0 + 1) } ?? "nil")"
                )
            }
            window.contentView?.displayIfNeeded()
            let topDrawn = firstDrawnGutterLine(for: textView)
            guard topDrawn == topText else {
                finish(
                    false,
                    "Gutter zeichnete am Dokumentanfang ab Zeile "
                        + "\(topDrawn.map { String($0 + 1) } ?? "nil") statt "
                        + "\(String(topText + 1))"
                )
            }
            let topImage = screenshotDirectory == nil
                ? nil : typeScrollLayerSnapshot(window: window)

            let documentHeight = scrollView.documentView?.bounds.maxY
                ?? textView.bounds.maxY
            let bottomY = max(
                documentHeight - scrollView.contentView.bounds.height,
                0
            )
            scrollView.contentView.scroll(
                to: NSPoint(
                    x: scrollView.contentView.bounds.origin.x,
                    y: bottomY
                )
            )
            scrollView.reflectScrolledClipView(scrollView.contentView)
            textView.updatedViewport(scrollView.documentVisibleRect)
            textView.layoutManager.layoutLines(in: textView.visibleRect)

            DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) {
                let bottomText = textView.layoutManager.textLineForPosition(
                    textView.visibleRect.minY
                )?.index
                let bottomGutter = firstGutterLine(for: textView)
                guard let bottomText, bottomText > 2_300,
                      bottomGutter == bottomText else {
                    finish(
                        false,
                        "Gutter am Dokumentende abweichend: Text="
                            + "\(bottomText.map { String($0 + 1) } ?? "nil"), Gutter="
                            + "\(bottomGutter.map { String($0 + 1) } ?? "nil")"
                    )
                }
                window.contentView?.displayIfNeeded()
                let bottomDrawn = firstDrawnGutterLine(for: textView)
                guard bottomDrawn == bottomText else {
                    finish(
                        false,
                        "Gutter zeichnete am Dokumentende ab Zeile "
                            + "\(bottomDrawn.map { String($0 + 1) } ?? "nil") statt "
                            + "\(String(bottomText + 1))"
                    )
                }

                if let screenshotDirectory {
                    window.contentView?.displayIfNeeded()
                    guard let topImage,
                          let bottomImage = typeScrollLayerSnapshot(window: window) else {
                        finish(false, "Gutter-Fensterbilder konnten nicht gerendert werden")
                    }
                    let topURL = screenshotDirectory
                        .appendingPathComponent("softwrapanchor-top.png")
                    let bottomURL = screenshotDirectory
                        .appendingPathComponent("softwrapanchor-bottom.png")
                    do {
                        try topImage.write(to: topURL, options: .atomic)
                        try bottomImage.write(to: bottomURL, options: .atomic)
                    } catch {
                        finish(
                            false,
                            "Gutter-Fensterbilder nicht schreibbar: "
                                + error.localizedDescription
                        )
                    }
                    FileHandle.standardError.write(
                        Data(
                            "SOFTWRAPANCHOR-SHOTS \(topURL.path) \(bottomURL.path)\n".utf8
                        )
                    )
                }
                completion()
            }
        }
    }

    /// Wartet nach einem Dateiwechel, bis TextView und der zugehörige
    /// CodeEdit-Controller gemeinsam in der Responderkette angekommen sind.
    /// Wartet auf einen Editor, der sich nicht mehr ändert — Voraussetzung
    /// dafür, seine Identität als Vergleichsbasis zu merken.
    ///
    /// Hintergrund: `EditorView` erzeugt den SourceEditor
    /// bewusst neu, sobald `isLoading` auf false kippt (siehe Kommentar an
    /// `sourceEditor` — nur so übernimmt CodeEditSourceEditor den geladenen
    /// Inhalt). `pollForSoftWrapEditor` liefert aber schon die TextView davor.
    /// Wer dort die Identität merkt, vergleicht später gegen einen Editor, der
    /// planmäßig ersetzt wurde — der Test war dadurch in etwa jedem vierten
    /// Lauf rot, ohne dass am Produkt etwas defekt war.
    ///
    /// Zwei Bedingungen, beide nötig: Der Tab meldet sich als fertig geladen,
    /// und dieselbe TextView überlebt drei aufeinanderfolgende Prüfungen.
    private static func pollForStableSoftWrapEditor(
        ws: Workspace, root: NSView,
        completion: @escaping (TextView, TextViewController) -> Void
    ) {
        let requiredStableTicks = 3
        var previous: ObjectIdentifier?
        var sightings = 0
        var loaded = false
        var found: (TextView, TextViewController)?
        waitFor(budget: 8, pause: 0.1,
                condition: {
                    loaded = ws.activeTab.map { !$0.isLoading } ?? false
                    guard loaded, let textView = editorTextView(in: root) as? TextView,
                          let controller = sourceEditorController(for: textView) else {
                        previous = nil
                        sightings = 0
                        return false
                    }
                    let current = ObjectIdentifier(textView)
                    // Andere (oder erste) TextView → Zählung neu beginnen.
                    sightings = previous == current ? sightings + 1 : 1
                    previous = current
                    guard sightings >= requiredStableTicks else { return false }
                    found = (textView, controller)
                    return true
                },
                onTimeout: { book in
                    finish(false, "Editor wurde nicht stabil "
                           + "(geladen: \(loaded), TextViews: \(editorTextViewCount(in: root))) — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Editor nach Erfolg verschwunden") }
                    completion(found.0, found.1)
                })
    }

    private static func pollForSoftWrapEditor(
        root: NSView,
        completion: @escaping (TextView, TextViewController) -> Void
    ) {
        var found: (TextView, TextViewController)?
        waitFor(budget: 8, pause: 0.1,
                condition: {
                    guard let textView = editorTextView(in: root) as? TextView,
                          let controller = sourceEditorController(for: textView) else { return false }
                    found = (textView, controller)
                    return true
                },
                onTimeout: { book in
                    finish(false, "TextViewController nicht erreichbar — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Editor nach Erfolg verschwunden") }
                    completion(found.0, found.1)
                })
    }

    private static func pollSoftWrapWindowGeometry(
        ws: Workspace, root: NSView, guideColumn: Int,
        completion: @escaping () -> Void
    ) {
        waitFor(budget: 8, pause: 0.1,
                condition: {
                    guard let textView = editorTextView(in: root) as? TextView,
                          let controller = sourceEditorController(for: textView),
                          let guide = findView(named: "ReformattingGuideView", in: root) else { return false }
                    textView.layoutManager.layoutLines()
                    let fontWidth = (" " as NSString).size(
                        withAttributes: [.font: controller.font]
                    ).width
                    let characterWidth = max(fontWidth + textView.kern, 1)
                    let expectedGuideWidth = CGFloat(guideColumn) * characterWidth
                    let guideOffset = guide.frame.minX
                        - textView.layoutManager.edgeInsets.left
                    let fragments = Array(textView.layoutManager.lineStorage).flatMap {
                        Array($0.data.lineFragments)
                    }
                    return ws.softWrapEnabled
                        && ws.softWrapTarget == .window
                        && ws.effectiveSoftWrapColumn == nil
                        && ws.pageGuideColumn == guideColumn
                        && ws.showPageGuide
                        && textView.wrapLines
                        && textView.layoutManager.maximumWrapWidth == nil
                        && !guide.isHidden
                        && abs(guideOffset - expectedGuideWidth) < 1.1
                        && fragments.count > 1
                },
                onTimeout: { book in
                    finish(
                        false,
                        "Fensterbreite nicht korrekt: "
                            + "target=\(ws.softWrapTarget.rawValue), "
                            + "column=\(String(describing: ws.effectiveSoftWrapColumn)) — \(book.summary)"
                    )
                },
                then: completion)
    }

    private static func pollSoftWrapGeometry(
        ws: Workspace, root: NSView,
        expectedTarget: SoftWrapTarget,
        wrapColumn: Int, guideColumn: Int,
        requireViewportClamp: Bool = false,
        minimumConfiguredWidth: CGFloat? = nil,
        label: String,
        completion: @escaping (CGFloat) -> Void
    ) {
        var configured: CGFloat?
        waitFor(budget: 8, pause: 0.1,
                condition: {
                    guard let textView = editorTextView(in: root) as? TextView,
                          let controller = sourceEditorController(for: textView),
                          let configuredWidth = textView.layoutManager.maximumWrapWidth,
                          let guide = findView(named: "ReformattingGuideView", in: root) else { return false }
                    textView.layoutManager.layoutLines()
                    let fontWidth = (" " as NSString).size(
                        withAttributes: [.font: controller.font]
                    ).width
                    let characterWidth = max(fontWidth + textView.kern, 1)
                    let expectedWrapWidth = CGFloat(wrapColumn) * characterWidth
                    let expectedGuideWidth = CGFloat(guideColumn) * characterWidth
                    let guideOffset = guide.frame.minX
                        - textView.layoutManager.edgeInsets.left
                    let widthMatches = abs(configuredWidth - expectedWrapWidth) < 1
                    let guideMatches = abs(guideOffset - expectedGuideWidth) < 1.1
                    let clampMatches = !requireViewportClamp
                        || textView.layoutManager.maxLineLayoutWidth < configuredWidth
                    let zoomMatches = minimumConfiguredWidth.map {
                        configuredWidth > $0
                    } ?? true
                    guard ws.softWrapEnabled,
                          ws.softWrapTarget == expectedTarget,
                          ws.effectiveSoftWrapColumn == wrapColumn,
                          ws.pageGuideColumn == guideColumn,
                          ws.showPageGuide,
                          textView.wrapLines,
                          !guide.isHidden,
                          widthMatches, guideMatches, clampMatches, zoomMatches else { return false }
                    configured = configuredWidth
                    return true
                },
                onTimeout: { book in
                    let textView = editorTextView(in: root) as? TextView
                    finish(
                        false,
                        "\(label) nicht korrekt: "
                            + "target=\(ws.softWrapTarget.rawValue), "
                            + "column=\(String(describing: ws.effectiveSoftWrapColumn)), "
                            + "configured=\(String(describing: textView?.layoutManager.maximumWrapWidth)), "
                            + "layout=\(String(describing: textView?.layoutManager.maxLineLayoutWidth)) — \(book.summary)"
                    )
                },
                then: {
                    guard let configured else { finish(false, "\(label): Umbruchbreite nach Erfolg verschwunden") }
                    completion(configured)
                })
    }

    private static func sourceEditorController(
        for textView: TextView
    ) -> TextViewController? {
        var responder: NSResponder? = textView
        var remaining = 50
        while let current = responder, remaining > 0 {
            if let controller = current as? TextViewController {
                return controller
            }
            responder = current.nextResponder
            remaining -= 1
        }
        return nil
    }

    /// Belegt end-to-end, dass der Editor Syntax-Highlighting wirklich färbt:
    /// eine Python-Datei mit Keyword/String/Kommentar wird in einen Tab
    /// geladen; danach müssen im echten Editor-TextStorage mehrere
    /// verschiedene Vordergrundfarben stehen. Fängt die Bug-Klasse „Sprache
    /// erkannt, aber alles monochrom" — Unit-Tests
    /// sehen die nicht, weil der Pfad CodeLanguage → TreeSitterClient →
    /// Query-Bundle → Attribut-Anwendung nur im echten App-Prozess läuft.
    /// Tree-sitter arbeitet asynchron → engmaschig pollen statt Einmal-Messung.
    private static func runHighlightTest() {
        testLabel = "highlight"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        _ = mainWindow

        SelfTestHighlighting(
            workspace: ws, root: root, waitFor: waitFor, finish: finish,
            editorTextView: editorTextView,
            fourDExpectedColors: fourDExpectedColors,
            fourDComponentMethodExpectedColor: fourDComponentMethodExpectedColor,
            storageSubstringHasColor: storageSubstringHasColor,
            storageSubstringHasStyle: storageSubstringHasStyle
        ).runHighlightTest()
    }

    // MARK: - 4D-Vervollständigung

    private static func runFourDCompletionTest() {
        testLabel = "completion4d"
        fourDCompletionTests.runFourDCompletionTest()
    }

    /// Behält den regulären Testeingang bei, ohne den Runtimebesitzer aufzubauen.
    static func waitForCompletionPopupClosure(
        isVisible: @escaping () -> Bool,
        escape: @escaping () -> Void,
        forceClose: @escaping () -> Void,
        schedule: @escaping (Double, @escaping () -> Void) -> Void,
        completion: @escaping (Bool) -> Void
    ) {
        SelfTestFourDCompletion.waitForCompletionPopupClosure(
            isVisible: isVisible, escape: escape, forceClose: forceClose,
            schedule: schedule, completion: completion
        )
    }

    // MARK: - 4D-Highlighting

    /// Beobachtet die echten 4D-Vordergrundfarben im gepackten Bundle —
    /// erst im hellen, dann im dunklen Erscheinungsbild (die 4D-Themes sind
    /// pro Dokument aktiv und stammen aus light.json/dark.json). Prüft je
    /// Modus Befehl, Schlüsselwort, lokale und Prozessvariable, Tabelle,
    /// Feld, Kommentar sowie eine indizierte Projektmethode.
    private static func runFourDHighlightTest() {
        testLabel = "highlight4d"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }

        SelfTestHighlighting(
            workspace: ws, root: root, waitFor: waitFor, finish: finish,
            editorTextView: editorTextView,
            fourDExpectedColors: fourDExpectedColors,
            fourDComponentMethodExpectedColor: fourDComponentMethodExpectedColor,
            storageSubstringHasColor: storageSubstringHasColor,
            storageSubstringHasStyle: storageSubstringHasStyle
        ).runFourDHighlightTest()
    }

    /// Erwartete 4D-Vordergrundfarben aus den öffentlichen Test-Fixtures.
    private static func fourDExpectedColors(dark: Bool) -> [(String, Int, Int, Int)] {
        dark
            ? [("Befehl", 0xB5, 0xD6, 0xDD), ("Keyword", 0xE1, 0xDC, 0x32),
               ("$lokal", 0x00, 0xF9, 0xCC), ("Prozessvariable", 0xD7, 0xF6, 0x92),
               ("Tabelle", 0xB7, 0x4D, 0x00), ("Feld", 0xBA, 0xD8, 0x0A),
               ("String", 0x94, 0xCE, 0x9F),
               ("Kommentar", 0x74, 0xC5, 0xEA)]
            : [("Befehl", 0x06, 0x8C, 0x00), ("Keyword", 0x03, 0x4D, 0x00),
               ("$lokal", 0x00, 0x70, 0xF5), ("Prozessvariable", 0x9E, 0x60, 0x00),
               ("Tabelle", 0x43, 0x99, 0xD0), ("Feld", 0x39, 0x80, 0xB2),
               ("String", 0x2F, 0x5D, 0x3A),
               ("Kommentar", 0x7F, 0x7E, 0x80)]
    }

    private static func fourDComponentMethodExpectedColor(dark: Bool) -> (Int, Int, Int) {
        dark ? (0xFF, 0x9D, 0x3F) : (0xB3, 0x47, 0x00)
    }

    /// Prüft die Farbe genau am Namen der indizierten Projektmethode. Ein
    /// bloßes Vorkommen der Befehlsfarbe würde nicht beweisen, dass der
    /// Methodenindex die sonst gleichfarbige `ALERT`-Zeile verlassen hat.
    private static func storageSubstringHasColor(_ substring: String, in root: NSView,
                                                  r: Int, g: Int, b: Int) -> Bool {
        guard let textView = editorTextView(in: root) as? TextView,
              let storage = textView.textStorage,
              let range = textView.string.range(of: substring) else { return false }
        let nsRange = NSRange(range, in: textView.string)
        guard
              nsRange.location != NSNotFound,
              let color = storage.attribute(.foregroundColor, at: nsRange.location,
                                            effectiveRange: nil) as? NSColor,
              let srgb = color.usingColorSpace(.sRGB) else { return false }
        let tolerance = 1.5 / 255.0
        return abs(srgb.redComponent - Double(r) / 255) < tolerance
            && abs(srgb.greenComponent - Double(g) / 255) < tolerance
            && abs(srgb.blueComponent - Double(b) / 255) < tolerance
    }

    private static func storageSubstringHasStyle(_ substring: String, in root: NSView,
                                                 bold: Bool, italic: Bool) -> Bool {
        guard let textView = editorTextView(in: root) as? TextView,
              let storage = textView.textStorage,
              let range = textView.string.range(of: substring) else { return false }
        let nsRange = NSRange(range, in: textView.string)
        guard nsRange.location != NSNotFound,
              let font = storage.attribute(.font, at: nsRange.location,
                                           effectiveRange: nil) as? NSFont else { return false }
        let traits = NSFontManager.shared.traits(of: font)
        return traits.contains(.boldFontMask) == bold && traits.contains(.italicFontMask) == italic
    }

    // MARK: - Leaks-Szenario

    /// Diagnose-Szenario für den `leaks`-Durchlauf: übt Bildvorschau, PDF-
    /// Vorschau, Hex-Ansicht und XPath-Leiste je einmal aus, schließt die
    /// Tabs wieder und meldet dann `LEAKSCENARIO READY <pid>` auf stderr.
    /// Danach bleibt der Prozess ~60 s am Leben, damit ein äußeres Skript
    /// `leaks <pid>` gegen die laufende App ausführen kann.
    private static func runLeakScenario() {
        testLabel = "leakscenario"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-leaks-\(UUID().uuidString)")
        let png = base.appendingPathComponent("bild.png")
        let pdf = base.appendingPathComponent("doku.pdf")
        let xml = base.appendingPathComponent("daten.xml")
        let txt = base.appendingPathComponent("hex.txt")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            try writeSolidPNG(to: png, width: 640, height: 320)
            // Die PNG-Erzeugung und NSImage können das Farbprofil umrechnen.
            // Dieselbe dekodierte Eingabe liefert den Vergleichswert; das Bild
            // selbst wird nicht über die spätere Leckmessung hinweg gehalten.
            guard let source = NSImage(contentsOf: png), let color = centerColor(of: source) else {
                finish(false, "Leak-Szenario: PNG-Fixture nicht dekodierbar")
            }
            leakScenarioImageColor = color
            try writeSinglePagePDF(to: pdf)
            try "<lager><regal id=\"1\"><fach>Grüße</fach></regal></lager>"
                .write(to: xml, atomically: true, encoding: .utf8)
            try "Hexbeispiel 0123456789".write(to: txt, atomically: true,
                                               encoding: .utf8)
        } catch {
            finish(false, "Fixtures nicht schreibbar: \(error.localizedDescription)")
        }

        loadLeakScenarioStage(ws: ws, base: base, stage: .image)
    }

    private static var leakScenarioImageColor: NSColor?

    private enum LeakScenarioStage: String {
        case image, pdf, hex, xpathPanel, xpathSelection, closed

        var fileName: String? {
            switch self {
            case .image: return "bild.png"
            case .pdf: return "doku.pdf"
            case .hex: return "hex.txt"
            case .xpathPanel: return "daten.xml"
            case .xpathSelection, .closed: return nil
            }
        }
    }

    /// Erst nach einer beobachteten Ansicht zur nächsten Datei wechseln.
    /// Die Lade-Completion allein belegt noch keine montierte SwiftUI-View.
    private static func loadLeakScenarioStage(ws: Workspace, base: URL, stage: LeakScenarioStage) {
        guard let name = stage.fileName else {
            finish(false, "Leak-Szenario: Phase ohne Ladedatei")
        }
        let url = base.appendingPathComponent(name)
        ws.loadFile(at: url) { ok in
            guard ok else {
                try? FileManager.default.removeItem(at: base)
                finish(false, "Leak-Szenario: Laden von \(url.lastPathComponent) fehlgeschlagen")
            }
            if stage == .hex { ws.setViewMode(.hex) }
            if stage == .xpathPanel {
                NotificationCenter.default.post(name: .fastraShowXPathBar, object: ws)
            }
            pollLeakScenarioStage(ws: ws, base: base, stage: stage)
        }
    }

    private static func pollLeakScenarioStage(ws: Workspace, base: URL,
                                              stage: LeakScenarioStage) {
        // Views nur während dieser Messung halten. Über die Wartephase
        // gehaltene Vorschauen würden die spätere Speicherdiagnose verfälschen.
        waitFor(budget: 10, pause: 0.1,
                condition: {
                    var ready = false
                    if let root = MainActor.assumeIsolated({
                        CommandTargeting.documentWindow(for: ws)?.contentView
                    }) {
                        switch stage {
                        case .image:
                            if let image = previewImageView(in: root)?.image,
                               let color = centerColor(of: image), let expected = leakScenarioImageColor {
                                ready = image.size == NSSize(width: 640, height: 320)
                                    && abs(color.redComponent - expected.redComponent) < 0.01
                                    && abs(color.greenComponent - expected.greenComponent) < 0.01
                                    && abs(color.blueComponent - expected.blueComponent) < 0.01
                                    && abs(color.alphaComponent - expected.alphaComponent) < 0.01
                            }
                        case .pdf:
                            ready = firstPDFView(in: root)?.document?.pageCount == 1
                        case .hex:
                            // Dieser Abzug stammt aus onVisiblePage der montierten
                            // Hex-Ansicht, nachdem sie den Dateiabschnitt geladen hat.
                            ready = ws.visiblePrintPage?.url == base.appendingPathComponent("hex.txt").canonicalFileURL
                                && ws.visiblePrintPage?.text.contains("Hexbeispiel") == true
                        case .xpathPanel:
                            ready = MainActor.assumeIsolated {
                                guard let panel = XPathPanelController.lastShown,
                                      panel.isVisible, let model = panel.model else { return false }
                                model.query = "//fach"
                                return true
                            }
                        case .xpathSelection:
                            if let tv = editorTextView(in: root) as? TextView {
                                let expected = (tv.string as NSString).range(of: "fach>Grüße")
                                ready = expected.location != NSNotFound
                                    && tv.selectedRange() == NSRange(location: expected.location, length: 4)
                            }
                        case .closed:
                            ready = ws.tabs.count == 1 && ws.activeTab?.url == nil
                                && previewImageView(in: root) == nil && firstPDFView(in: root) == nil
                                && ws.visiblePrintPage == nil
                                && MainActor.assumeIsolated {
                                    XPathPanelController.lastShown?.isVisible != true
                                }
                        }
                    }
                    return ready
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    let window = MainActor.assumeIsolated { CommandTargeting.documentWindow(for: ws) }
                    let image = window?.contentView.flatMap { previewImageView(in: $0)?.image }
                    let color = image.flatMap { centerColor(of: $0) }
                    finish(false, "Leak-Szenario: Ansicht/Sprung/Aufräumen in Phase \(stage.rawValue) nicht bestätigt; "
                        + "Fenster=\(window != nil), sichtbar=\(window?.isVisible ?? false), "
                        + "Bild=\(image != nil), Farbe=\(String(describing: color)), "
                        + "aktiver Tab=\(ws.activeTab?.url?.lastPathComponent ?? "nil"), "
                        + "Hex-Abzug=\(String(describing: ws.visiblePrintPage)) — \(book.summary)")
                },
                then: {
                    switch stage {
                    case .image:
                        loadLeakScenarioStage(ws: ws, base: base, stage: .pdf)
                    case .pdf:
                        loadLeakScenarioStage(ws: ws, base: base, stage: .hex)
                    case .hex:
                        loadLeakScenarioStage(ws: ws, base: base, stage: .xpathPanel)
                    case .xpathPanel:
                        pollLeakScenarioStage(ws: ws, base: base, stage: .xpathSelection)
                    case .xpathSelection:
                        MainActor.assumeIsolated { XPathPanelController.lastShown?.close() }
                        // Auch wenn das Laden den anfänglichen Leertab ersetzt hat,
                        // darf keine Fixture als vermeintlicher Leertab übrig bleiben.
                        ws.openNewTab()
                        guard let keep = ws.activeTabID else {
                            finish(false, "Leak-Szenario: neuer Leertab fehlt")
                        }
                        ws.closeOtherTabs(keeping: keep)
                        pollLeakScenarioStage(ws: ws, base: base, stage: .closed)
                    case .closed:
                        finishLeakScenario(base: base)
                    }
                })
    }

    private static func finishLeakScenario(base: URL) {
        try? FileManager.default.removeItem(at: base)
        FileHandle.standardError.write(Data(
            "LEAKSCENARIO READY \(ProcessInfo.processInfo.processIdentifier)\n".utf8))
        // Kein finish(): Der Prozess bleibt für den leaks-Angriff am Leben
        // und beendet sich nach 60 s selbst (SELFTEST-Zeile für den Runner).
        DispatchQueue.main.asyncAfter(deadline: .now() + 60) {
            finish(true, "Leak-Szenario ausgeübt (Bild/PDF/Hex/XPath)")
        }
    }

    // MARK: - XPath-Leiste

    /// Öffnet die echte XPath-Leiste über die Menü-Notification und prüft,
    /// dass eine getippte Query den Editor wirklich zur Fundstelle springen
    /// lässt (tatsächliche Selektion in der CodeEdit-TextView, nicht nur
    /// Modellzustand) — Panel-Öffnen + Springen End-to-End.
    private static func runXPathTest() {
        testLabel = "xpath"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }

        // Selbst geschriebene Fixture mit Multibyte-Inhalt vor dem Ziel.
        //
        // Bewusst groß: Der XPath-Index entsteht asynchron. Bei einer winzigen
        // Datei ist er manchmal schon fertig, bevor der Test tippt — dann liefe
        // der Test am eigentlichen Risiko vorbei (Tippen vor fertigem Index)
        // und wäre je nach Systemlast mal grün, mal rot. Die Füllelemente
        // machen den Bau lang genug, dass der Fall zuverlässig eintritt.
        var filler = ""
        for identifier in 100..<4100 {
            filler += "    <regal id=\"\(identifier)\">"
                + "<fach>Füllfach \(identifier)</fach></regal>\n"
        }
        let xml = """
        <?xml version="1.0" encoding="UTF-8"?>
        <lager ort="Köln 🙂">
            <regal id="1"><fach>Grüße</fach></regal>
        \(filler)    <regal id="42"><fach>Zielfach</fach></regal>
        </lager>
        """
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-xpath-\(UUID().uuidString).xml")
        do { try xml.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            guard ok else {
                try? FileManager.default.removeItem(at: tmp)
                finish(false, "loadFile (.xml) schlug fehl")
            }
            guard ws.activeTabSupportsXPath else {
                try? FileManager.default.removeItem(at: tmp)
                finish(false, "XPath für .xml nicht verfügbar (activeTabSupportsXPath=false)")
            }
            // Panel über den echten Menü-Pfad öffnen.
            NotificationCenter.default.post(name: .fastraShowXPathBar, object: nil)
            pollXPathPanel(ws: ws, root: root, xml: xml, tmp: tmp)
        }
    }

    private static func pollXPathPanel(ws: Workspace, root: NSView, xml: String,
                                       tmp: URL) {
        // Panel-Sichtbarkeit + Modell-Zugriff sind MainActor-isoliert; die
        // Selbsttests laufen auf dem Main-Thread → Isolierung übernehmen.
        var model: XPathBarModel?
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    model = MainActor.assumeIsolated {
                        let visible = NSApp.windows.contains {
                            $0.identifier == XPathPanelController.panelIdentifier && $0.isVisible
                        }
                        return visible ? XPathPanelController.lastShown?.model : nil
                    }
                    return model != nil
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: tmp)
                    finish(false, "XPath-Panel erschien nicht — \(book.summary)")
                },
                then: {
                    guard let model else { finish(false, "XPath-Panel nach Erfolg verschwunden") }
                    // Festhalten, ob der Index beim Tippen schon stand. Nur wenn nicht,
                    // prüft der Lauf den eigentlich riskanten Fall.
                    let indexWasReady = MainActor.assumeIsolated { model.index != nil }
                    // Query in das echte Modell tippen (Live-Springen).
                    MainActor.assumeIsolated { model.query = "//regal[@id='42']/fach" }
                    // Erwartete Fundstelle unabhängig berechnen: Name des
                    // <fach>-Elements im Zielregal.
                    let ns = xml as NSString
                    let target = ns.range(of: "fach>Zielfach")
                    let expected = NSRange(location: target.location, length: 4)
                    pollXPathSelection(root: root, expected: expected, tmp: tmp,
                                       indexWasReady: indexWasReady)
                })
    }

    private static func pollXPathSelection(root: NSView, expected: NSRange,
                                           tmp: URL, indexWasReady: Bool) {
        var selection: NSRange?
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    selection = (editorTextView(in: root) as? TextView)?
                        .selectionManager.textSelections.first?.range
                    return selection?.location == expected.location
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: tmp)
                    finish(false, "kein Sprung zur Fundstelle — \(book.summary) "
                        + "(erwartet \(expected), Selektion \(String(describing: selection)), "
                        + "Index beim Tippen fertig: \(indexWasReady))")
                },
                then: {
                    guard let selection else { finish(false, "Selektion nach Erfolg verschwunden") }
                    // Panel wieder schließen (Aufräumen), Datei löschen.
                    MainActor.assumeIsolated { XPathPanelController.lastShown?.close() }
                    try? FileManager.default.removeItem(at: tmp)
                    // Ehrlich ausweisen, welcher Fall geprüft wurde: Stand der Index
                    // schon, lief der Test am eigentlichen Risiko vorbei.
                    let scope = indexWasReady
                        ? "Index war bereits fertig — verpasster Sprung NICHT geprüft"
                        : "getippt vor fertigem Index (nachgeholter Sprung)"
                    finish(true, "XPath-Panel öffnet und springt zur echten Fundstelle "
                        + "(Selektion @\(selection.location); \(scope))")
                })
    }

    // MARK: - Ansichts-Umschalter + Vorschau

    /// Prüft die Read-only-Vorschau mit echter Beobachtung (Muster
    /// `highlight`): Ein rotes PNG muss als tatsächlich dekodiertes Bild in
    /// der View-Hierarchie ankommen (Pixelfarbe wird gesampelt, nicht nur
    /// Modellzustand), der Umschalter muss die Ansicht real wechseln, und
    /// ein generiertes PDF muss als PDFKit-Dokument mit einer Seite gerendert
    /// werden.
    private static func runPreviewRenderTest() {
        testLabel = "previewrender"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }

        // Rotes 64×32-PNG erzeugen (Rot ist als Sample-Farbe eindeutig).
        let png = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-previewrender-\(UUID().uuidString).png")
        do { try writeSolidPNG(to: png, width: 64, height: 32) }
        catch { finish(false, "PNG nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: png) { ok in
            guard ok else {
                try? FileManager.default.removeItem(at: png)
                finish(false, "loadFile (PNG) schlug fehl")
            }
            guard ws.activeViewMode == .preview else {
                try? FileManager.default.removeItem(at: png)
                finish(false, "PNG öffnet nicht in der Vorschau (Modus: \(ws.activeViewMode))")
            }
            pollImagePreview(root: root, ws: ws, png: png)
        }
    }

    /// Wartet, bis das dekodierte Bild wirklich in der View-Hierarchie hängt,
    /// und sampelt dann die Mittelpixel-Farbe.
    private static func pollImagePreview(root: NSView, ws: Workspace, png: URL) {
        var image: NSImage?
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    image = previewImageView(in: root)?.image
                    return image != nil
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: png)
                    finish(false, "kein gerendertes Vorschaubild — \(book.summary)")
                },
                then: {
                    guard let image, let color = centerColor(of: image) else {
                        try? FileManager.default.removeItem(at: png)
                        finish(false, "Vorschaubild nicht sampelbar")
                    }
                    guard color.redComponent > 0.8, color.greenComponent < 0.2,
                          color.blueComponent < 0.2 else {
                        try? FileManager.default.removeItem(at: png)
                        finish(false, "Vorschaubild hat falsche Farbe: \(color)")
                    }
                    // Umschalter real prüfen: Hex → Bildfläche verschwindet.
                    ws.setViewMode(.hex)
                    pollPreviewGone(root: root, ws: ws, png: png)
                })
    }

    /// Nach dem Umschalten auf Hex darf keine Bildfläche mehr da sein.
    private static func pollPreviewGone(root: NSView, ws: Workspace, png: URL) {
        waitFor(budget: 10, pause: 0.25,
                condition: { previewImageView(in: root) == nil },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: png)
                    finish(false, "Umschalter auf Hex entfernt die Bildvorschau nicht — \(book.summary)")
                },
                then: {
                    try? FileManager.default.removeItem(at: png)
                    runPDFPreviewPart(root: root, ws: ws)
                })
    }

    /// PDF-Teil: einseitiges PDF erzeugen, laden, echtes PDFKit-Dokument
    /// in der Hierarchie beobachten.
    private static func runPDFPreviewPart(root: NSView, ws: Workspace) {
        let pdf = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-previewrender-\(UUID().uuidString).pdf")
        do { try writeSinglePagePDF(to: pdf) }
        catch { finish(false, "PDF nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: pdf) { ok in
            guard ok else {
                try? FileManager.default.removeItem(at: pdf)
                finish(false, "loadFile (PDF) schlug fehl")
            }
            guard ws.activeViewMode == .preview else {
                try? FileManager.default.removeItem(at: pdf)
                finish(false, "PDF öffnet nicht in der Vorschau (Modus: \(ws.activeViewMode))")
            }
            pollPDFPreview(root: root, pdf: pdf)
        }
    }

    private static func pollPDFPreview(root: NSView, pdf: URL) {
        waitFor(budget: 10, pause: 0.25,
                condition: { firstPDFView(in: root)?.document?.pageCount == 1 },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: pdf)
                    finish(false, "kein gerendertes PDF — \(book.summary)")
                },
                then: {
                    try? FileManager.default.removeItem(at: pdf)
                    finish(true, "Bildvorschau rendert rot + Umschalter wirkt + PDF zeigt 1 Seite")
                })
    }

    /// Sucht die Bildvorschau-Fläche über ihren Accessibility-Identifier.
    private static func previewImageView(in view: NSView) -> NSImageView? {
        if let imageView = view as? NSImageView,
           imageView.accessibilityIdentifier() == "imagePreviewSurface" {
            return imageView
        }
        for sub in view.subviews {
            if let found = previewImageView(in: sub) { return found }
        }
        return nil
    }

    private static func firstPDFView(in view: NSView) -> PDFView? {
        if let pdfView = view as? PDFView { return pdfView }
        for sub in view.subviews {
            if let found = firstPDFView(in: sub) { return found }
        }
        return nil
    }

    /// Mittelpixel-Farbe eines NSImage (sRGB) — echte Dekodier-Beobachtung.
    private static func centerColor(of image: NSImage) -> NSColor? {
        var rect = NSRect(origin: .zero, size: image.size)
        guard let cg = image.cgImage(forProposedRect: &rect, context: nil, hints: nil) else {
            return nil
        }
        let bitmap = NSBitmapImageRep(cgImage: cg)
        return bitmap.colorAt(x: bitmap.pixelsWide / 2, y: bitmap.pixelsHigh / 2)?
            .usingColorSpace(.sRGB)
    }

    /// Einfarbig rotes PNG über CoreGraphics schreiben.
    private static func writeSolidPNG(to url: URL, width: Int, height: Int,
                                      color: NSColor = NSColor(srgbRed: 1, green: 0, blue: 0, alpha: 1)) throws {
        guard let rep = NSBitmapImageRep(
            bitmapDataPlanes: nil, pixelsWide: width, pixelsHigh: height,
            bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
            colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0
        ) else { throw CocoaError(.fileWriteUnknown) }
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
        color.setFill()
        NSRect(x: 0, y: 0, width: width, height: height).fill()
        NSGraphicsContext.restoreGraphicsState()
        guard let data = rep.representation(using: .png, properties: [:]) else {
            throw CocoaError(.fileWriteUnknown)
        }
        try data.write(to: url)
    }

    /// Einseitiges PDF über CGContext schreiben.
    private static func writeSinglePagePDF(to url: URL) throws {
        var mediaBox = CGRect(x: 0, y: 0, width: 200, height: 100)
        guard let context = CGContext(url as CFURL, mediaBox: &mediaBox, nil) else {
            throw CocoaError(.fileWriteUnknown)
        }
        context.beginPDFPage(nil)
        context.setFillColor(CGColor(srgbRed: 0, green: 0, blue: 1, alpha: 1))
        context.fill(CGRect(x: 20, y: 20, width: 160, height: 60))
        context.endPDFPage()
        context.closePDF()
    }

    /// Prüft den Treffer-Sprung bis zur tatsächlichen Editor-Selektion auf einer
    /// späten Zeile. Unterschiedlich lange Vorzeilen mit Umlaut und Emoji decken
    /// UTF-16- und Normalisierungsabweichungen auf. Die Such-Engine findet das
    /// Zielwort; `postMatchJump` verwendet wie die GUI Zeile und Spalte.
    /// Der zurückgelesene selektierte Text muss dem Treffer entsprechen, damit
    /// auch CESEs Zeile/Spalte-Mapping geprüft ist.
    private static func runJumpTest() {
        testLabel = "jump"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }

        // App nach vorn + Hauptfenster key — wie im echten Bedienfall, wenn
        // der Nutzer einen Treffer anspringt. Ohne aktives Key-Window legt
        // CodeEditSourceEditor keine sichtbare Selektion an.
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)

        // Unterschiedlich lange Vorzeilen mit Umlaut/Emoji und eindeutigem
        // Zielwort auf der letzten Zeile. Nacheinander LF und reines CR prüfen;
        // eine LF-only-Zeilenzählung würde den CR-Fall falsch zuordnen.
        let baseLines = ["Müller wohnt in der Beispielstraße zwölf 😀", "x",
                         "mittellange dritte Zeile zum Variieren der Länge", "ZIELWORT"]
        let lfContent = baseLines.joined(separator: "\n")
        let crContent = baseLines.joined(separator: "\r")

        runJumpCase(ws: ws, mainWindow: mainWindow, root: root,
                    content: lfContent, label: "LF") {
            runJumpCase(ws: ws, mainWindow: mainWindow, root: root,
                        content: crContent, label: "CR") {
                finish(true, "Sprung selektierte exakt \"ZIELWORT\" in LF- UND CR-Datei "
                       + "(Zeilenzählung CR-bewusst — Klick-Sprung im 4D-Log-Fall belegt)")
            }
        }
    }

    /// Führt einen Jump-Fall aus (LF oder CR): Datei laden, Zielwort über die
    /// echte Such-Engine bestimmen, exakt wie die GUI über postMatchJump
    /// springen und die zurückgelesene Editor-Selektion prüfen. Bei Erfolg
    /// `onPass()`, bei Fehler sofortiger FAIL (mit Fall-Label).
    private static func runJumpCase(ws: Workspace, mainWindow: NSWindow, root: NSView,
                                    content: String, label: String,
                                    onPass: @escaping () -> Void) {
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-jump-\(label)-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "(\(label)) Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        // loadFile ist asynchron (v0.9): Folge-Schritte + Datei-Löschung in
        // die Completion (Datei muss beim Hintergrund-Read noch existieren).
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "(\(label)) loadFile schlug fehl (completion false)") }
            // Der Editor wird nach dem Dateiwechel neu eingehängt. Seine
            // Bereitschaft beobachten statt eine feste Renderdauer zu raten.
            pollForJumpEditor(
                root: root, expectedContent: content, label: label) { tv in
                // Editor zum First Responder machen — sonst landet die Selektion
                // u.U. nicht im selectionManager (wie im Findbar-Test).
                _ = mainWindow.makeFirstResponder(tv)

                // Treffer über die echte Such-Engine (gleicher Pfad wie die GUI-
                // Trefferliste), damit Zeile/Spalte konsistent sind.
                let opts = SearchOptions(find: "ZIELWORT", replace: "",
                                         isRegex: false, caseSensitive: true)
                let result = BufferSearch.find(in: ws.activeTab?.content ?? "", options: opts)
                guard let match = result.matches.first else {
                    finish(false, "(\(label)) Such-Engine fand ZIELWORT nicht (Inhalt nicht geladen?)")
                }

                // Sprung exakt wie GUI: Zeile/Spalte-Pfad über postMatchJump.
                // Die Selektionsprüfung löst die Editor-View pro Tick neu auf
                // (siehe pollForSelection) — `tv` hier nicht weiterreichen.
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                    NotificationCenter.default.postMatchJump(match, for: ws)
                    pollForSelection(in: root, expected: match.matchText,
                                     expectedContent: content,
                                     label: label, onPass: onPass)
                }
            }
        }
    }

    private static func pollForJumpEditor(
        root: NSView, expectedContent: String, label: String,
        completion: @escaping (TextView) -> Void
    ) {
        var textView: TextView?
        waitFor(budget: 4, pause: 0.1,
                condition: {
                    guard let candidate = editorTextView(in: root) as? TextView,
                          candidate.string == expectedContent else { return false }
                    textView = candidate
                    return true
                },
                onTimeout: { book in
                    finish(
                        false,
                        "(\(label)) Editor-TextView mit geladenem Inhalt nicht erreichbar — \(book.summary)"
                    )
                },
                then: {
                    guard let textView else { finish(false, "(\(label)) Editor nach Erfolg verschwunden") }
                    completion(textView)
                })
    }

    // MARK: - -selftest ghosttext

    /// Sichert gegen den „Text-Geist": Der
    /// CodeEditTextView-Typesetter verwendete den absoluten Endindex eines
    /// Zeilenumbruchs als `NSRange.length`. Ab dem zweiten Umbruchfragment
    /// überlappten die gezeichneten CoreText-Bereiche dadurch immer stärker →
    /// dasselbe Wort erschien mehrfach und Text lief rechts hinaus.
    ///
    /// CESE positioniert jedes Zeilenfragment als eigene `LineFragmentView`-
    /// Subview der `TextView`. Der Test lädt sehr lange Zeilen, erzwingt einen
    /// Breitenwechsel und prüft nach jedem Settle drei Invarianten:
    ///   (a) CoreText-Nutzlast und `documentRange` sind gleich lang,
    ///   (b) bei Umbruch an ist keine Fragment-View breiter als die Grenze,
    ///   (c) keine zwei Live-Views belegen denselben Dokumentbereich.
    /// Genau diese Render-Fehlerklasse entgeht reinen Modell-Tests: Der
    /// gespeicherte Text war auch beim Geist jederzeit korrekt.
    private static func runGhostTextTest() {
        testLabel = "ghosttext"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)

        // Mehrere Zeilen deutlich breiter als das Testfenster erzwingen Umbruch;
        // das wiederholte Wort macht ein überbreites Restfragment sichtbar.
        let long = String(repeating: "Willkommensbildschirm ", count: 40)
        let content = (1...6).map { "Zeile \($0): \(long)" }.joined(separator: "\n")
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-ghosttext-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            // Nach Einfügen langen Inhalts in einen frischen Editor und nach jeder
            // Breitenänderung die Zeicheninvariante prüfen. Beide Wege können veraltete
            // Umbruchfragmente sichtbar machen.
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) {
                if let violation = ghostViolation(in: root) {
                    finish(false, "Text-Geist nach Laden: \(violation)")
                }
                var f = mainWindow.frame
                f.size.width = 700
                mainWindow.setFrame(f, display: true)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                    if let violation = ghostViolation(in: root) {
                        finish(false, "Text-Geist nach Resize: \(violation)")
                    }
                    finish(true, "kein Text-Geist nach Laden und Resize "
                           + "(keine überlappenden/überlaufenden Fragment-Views)")
                }
            }
        }
    }

    /// Prüft die aktuell im Editor gezeichneten Zeilenfragmente auf die zwei
    /// Geist-Signaturen. Gibt `nil` zurück, wenn alles sauber ist, sonst eine
    /// erklärende Meldung. Sammelt die `LineFragmentView`s rekursiv aus dem
    /// TextView-Teilbaum (robust, falls CESE sie je in einen Container legt).
    static func ghostViolation(in root: NSView) -> String? {
        guard let tv = editorTextView(in: root) as? TextView else {
            return "keine prüfbare Editor-TextView vorhanden"
        }
        var fragments: [LineFragmentView] = []
        func collect(_ view: NSView) {
            if let frag = view as? LineFragmentView { fragments.append(frag) }
            view.subviews.forEach(collect)
        }
        collect(tv)

        // Nur Live-Fragmente: geparkte Reuse-Views sind versteckt / auf .zero.
        let live = fragments.filter {
            !$0.isHidden && $0.frame != .zero && $0.lineFragment != nil
        }
        guard !live.isEmpty else {
            return "keine lebenden Zeilenfragmente vorhanden"
        }

        let wrapWidth = tv.layoutManager.maxLineLayoutWidth
        // (a) Direkter Wächter für den gefundenen Root Cause: Der Range des
        // gezeichneten CTLine-Inhalts darf nicht länger sein als der zugehörige
        // Dokumentbereich. Beim Bug war ab Fragment 2 `lineBreak` (Endindex)
        // statt `lineBreak - start` (Länge) an CoreText gegangen.
        for v in live {
            let fragment = v.lineFragment!
            let drawnLength = fragment.contents.reduce(0) { $0 + $1.length }
            if drawnLength != fragment.documentRange.length {
                return "CoreText-Nutzlast und Dokumentbereich sind verschieden lang "
                    + "(drawn=\(drawnLength), documentRange=\(fragment.documentRange)) — "
                    + "Umbruchfragmente überlappen intern"
            }
        }
        // (b) Überlauf: bei endlicher Umbruch-Breite (Umbruch an) darf kein
        // sichtbares Fragment breiter als diese Breite sein. Ein zu breites
        // Fragment ist die überlaufende „Willkommensb"-Rest-View aus dem Screenshot.
        if wrapWidth.isFinite {
            for v in live where v.frame.width > wrapWidth + 2 {
                let r = v.lineFragment!.documentRange
                return "sichtbares Zeilenfragment breiter als die Umbruch-Breite "
                    + "(frameW=\(Int(v.frame.width)) > wrap=\(Int(wrapWidth)), documentRange=\(r), "
                    + "live-Fragmente=\(live.count)) — nicht umbrochene/überlaufende Geist-View"
            }
        }
        // (a) Überlappung: zwei sichtbare Fragmente, deren documentRange sich
        // schneidet → derselbe Text ist zweimal ausgelegt (Geist + korrekte
        // Umbruch-Version nebeneinander). Benachbarte Umbruch-Fragmente einer
        // Zeile haben lückenlose, nicht überlappende Ranges → kein Fehlalarm.
        for i in 0..<live.count {
            let a = live[i].lineFragment!.documentRange
            guard a.location != NSNotFound else { continue }
            for j in (i + 1)..<live.count {
                let b = live[j].lineFragment!.documentRange
                guard b.location != NSNotFound else { continue }
                if NSIntersectionRange(a, b).length > 0 {
                    return "zwei sichtbare Fragmente mit überlappendem Text "
                        + "(documentRange a=\(a), b=\(b)) — Zeile doppelt ausgelegt"
                }
            }
        }
        return nil
    }

    private static func runStructuredJSONTest() {
        testLabel = "jsonstress"
        Task { @MainActor in
            guard let ws = Workspace.shared, let window = CommandTargeting.registeredWindow(for: ws) else {
                finish(false, "Dokumentfenster fehlt")
            }
            activateApplication(ignoringOtherApps: true)
            window.makeKeyAndOrderFront(nil)
            let focusDeadline = ProcessInfo.processInfo.systemUptime + 2
            while (!NSApp.isActive || !window.isKeyWindow),
                  ProcessInfo.processInfo.systemUptime < focusDeadline {
                try? await Task.sleep(for: .milliseconds(50))
            }
            guard NSApp.isActive, window.isKeyWindow else {
                finish(.environment, "JSON-Tastaturtest benötigt aktiven Dokumentfokus")
            }
            workspaceDefaults().set(true, forKey: "editor.showMinimap")
            var stage = "Vorbereitung", lastBeat = ProcessInfo.processInfo.systemUptime, maxGap = 0.0
            let heartbeat = Timer(timeInterval: 0.05, repeats: true) { _ in
                MainActor.assumeIsolated {
                    let now = ProcessInfo.processInfo.systemUptime
                    maxGap = max(maxGap, now - lastBeat); lastBeat = now
                }
            }
            RunLoop.main.add(heartbeat, forMode: .common)
            func require(_ condition: Bool, _ message: String) throws {
                if !condition { throw NSError(domain: "JSONStress", code: 1, userInfo: [NSLocalizedDescriptionKey: stage + ": " + message]) }
            }
            func metric(_ detail: String) {
                FileHandle.standardError.write(Data(("JSONSTRESS phase=\(stage) \(detail) footprint=\(physicalFootprint()) max_main_gap_ms=\(Int(maxGap * 1000))\n").utf8))
            }
            @MainActor func wait(_ seconds: Double = 10, _ condition: @MainActor () -> Bool) async throws {
                let deadline = ProcessInfo.processInfo.systemUptime + seconds
                while !condition() {
                    try require(ProcessInfo.processInfo.systemUptime < deadline, "Zeitgrenze \(seconds)s überschritten")
                    try await Task.sleep(for: .milliseconds(25))
                }
            }
            @MainActor func geometry(minimap: Bool, wrap: Bool) -> Bool {
                func find(_ view: NSView) -> MinimapView? {
                    if let mini = view as? MinimapView { return mini }
                    return view.subviews.lazy.compactMap { find($0) }.first
                }
                guard let root = window.contentView, let mini = find(root),
                      let editor = CommandTargeting.editorTextView(for: ws),
                      editor.wrapLines == wrap, mini.isHidden == !minimap,
                      let scroll = editor.enclosingScrollView,
                      scroll.hasHorizontalScroller == !wrap,
                      editor.visibleRect.width > 100, editor.visibleRect.height > 100 else { return false }
                let visible = editor.subviews.compactMap { $0 as? LineFragmentView }
                    .filter { $0.frame.intersects(editor.visibleRect) && $0.lineFragment != nil }
                guard !visible.isEmpty else { return false }
                if minimap {
                    let frame = mini.convert(mini.bounds, to: editor)
                    guard frame.width > 30, frame.minX > editor.visibleRect.minX,
                          frame.maxX <= editor.visibleRect.maxX + 2,
                          mini.contentView.subviews.contains(where: { $0 is LineFragmentView }) else { return false }
                    if wrap {
                        let right = editor.layoutManager.edgeInsets.left + editor.layoutManager.wrapLinesWidth
                        guard right <= frame.minX + 2,
                              visible.allSatisfy({ $0.frame.maxX <= frame.minX + 2 }) else { return false }
                    }
                }
                return !wrap || (editor.layoutManager.lineStorage.first?.data.lineFragments.count ?? 0) > 1
            }
            @MainActor func load(_ url: URL) async throws -> TextView {
                var loaded: Bool?
                ws.loadFile(at: url) { loaded = $0 }
                try await wait { loaded != nil }
                try require(loaded == true, "Datei nicht geöffnet")
                ws.setLanguageOverride(.json); ws.setSoftWrapEnabled(true)
                try await wait {
                    guard let editor = CommandTargeting.editorTextView(for: ws) else { return false }
                    return editor.length > 0 && geometry(minimap: true, wrap: true)
                        && ((editor.layoutManager.lineStorage.first?.data.lineFragments.count ?? 0) > 1)
                        && ws.activeDocumentFormattingID == .grammar(.json)
                }
                guard let editor = CommandTargeting.editorTextView(for: ws) else { throw NSError(domain: "JSONStress", code: 2) }
                try require(window.makeFirstResponder(editor), "Editorfokus fehlt")
                return editor
            }
            @MainActor func capture(_ name: String) async throws {
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_JSONSTRESS_DIR"] else { return }
                let snapshot: TypeScrollSnapshot? = await withCheckedContinuation { continuation in
                    typeScrollCapture(window: window) { continuation.resume(returning: $0) }
                }
                try require(snapshot?.source == "screen", "Echte Fensteraufnahme fehlt")
                let url = URL(fileURLWithPath: directory).appendingPathComponent(name + ".png")
                try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                try snapshot?.data.write(to: url)
            }
            @MainActor func delayedIndicator() async throws {
                guard let documentID = ws.activeDocumentID else {
                    throw NSError(domain: "JSONStress", code: 5)
                }
                let originalFrame = window.frame
                defer { ws.documentTransformationActivity = nil; window.setFrame(originalFrame, display: true) }
                @MainActor func marker(_ id: String) -> Bool {
                    window.contentView.map { markerView(id: id, in: $0) != nil } ?? false
                }
                for (name, width) in [("minimum", MainWindowSizing.minimumWidth), ("wide", 1100)] {
                    window.setContentSize(NSSize(width: width, height: 600))
                    let started = ProcessInfo.processInfo.systemUptime
                    ws.documentTransformationActivity = DocumentTransformationActivity(documentID: documentID,
                        label: L10n.string("Dokument wird formatiert…"))
                    try await wait(2) { marker("documentTransformationPending") }
                    try await Task.sleep(for: .milliseconds(250))
                    try require(!marker("documentTransformationVisible"), "Aktivitätshinweis erscheint ohne Verzögerung")
                    try await wait(5) { marker("documentTransformationVisible") }
                    metric("indicator=\(name) visible_ms=\(Int((ProcessInfo.processInfo.systemUptime - started) * 1000))")
                    try await capture("00-delayed-indicator-" + name)
                    ws.documentTransformationActivity = nil
                    try await wait(2) { !marker("documentTransformationVisible") && !marker("documentTransformationPending") }
                }
            }
            @MainActor func menu(_ title: String) async throws {
                guard let main = NSApp.mainMenu,
                      let root = main.items.first(where: { $0.title == L10n.string("Text") }),
                      let textMenu = root.submenu else {
                    throw NSError(domain: "JSONStress", code: 3,
                        userInfo: [NSLocalizedDescriptionKey: "Text-Menü fehlt"])
                }
                // SwiftUI validiert die Einträge erst beim echten Öffnen.
                // Der Timer muss auch in AppKits Menü-Tracking laufen.
                let failure: String? = await withCheckedContinuation { continuation in
                    var timer: Timer?, ticks = 0, opened = false, pressed = false, finished = false
                    var activeMenu = textMenu
                    var navigationPending = false, previousHighlight: String?
                    var began: NSObjectProtocol?, ended: NSObjectProtocol?
                    func finishMenu(_ error: String?) {
                        guard !finished else { return }
                        finished = true
                        timer?.invalidate(); timer = nil
                        if let began { NotificationCenter.default.removeObserver(began) }
                        if let ended { NotificationCenter.default.removeObserver(ended) }
                        if error != nil { activeMenu.cancelTracking(); main.cancelTracking() }
                        RunLoop.main.perform(inModes: [.default]) {
                            continuation.resume(returning: error)
                        }
                    }
                    began = NotificationCenter.default.addObserver(
                        forName: NSMenu.didBeginTrackingNotification, object: nil, queue: .main
                    ) { notification in
                        let current = main.items.first(where: { $0.title == L10n.string("Text") })?.submenu
                        if let menu = notification.object as? NSMenu, menu === main || menu === current {
                            activeMenu = current ?? activeMenu
                            opened = true
                        }
                    }
                    ended = NotificationCenter.default.addObserver(
                        forName: NSMenu.didEndTrackingNotification, object: nil, queue: .main
                    ) { notification in
                        if opened, let menu = notification.object as? NSMenu, menu === main || menu === activeMenu {
                            finishMenu(pressed ? nil : "Text-Menü ohne Auswahl geschlossen: " + title)
                        }
                    }
                    timer = Timer(timeInterval: 0.05, repeats: true) { _ in
                        ticks += 1
                        // SwiftUI kann das Untermenue nach einer Dokumentaenderung ersetzen.
                        activeMenu = main.items.first(where: { $0.title == L10n.string("Text") })?.submenu ?? activeMenu
                        if opened, !pressed, let item = findMenuItem(titled: L10n.string(title), in: activeMenu),
                           item.isEnabled {
                            if activeMenu.highlightedItem?.title == item.title {
                                pressed = true
                                postKey("\r", keyCode: 36, windowNumber: window.windowNumber)
                            } else {
                                let highlightedTitle = activeMenu.highlightedItem?.title
                                if navigationPending, highlightedTitle != previousHighlight {
                                    navigationPending = false
                                }
                                // postEvent stellt nur zu: erst nach sichtbarer Bewegung
                                // weitergehen, sonst überspringen gepufferte Pfeile das Ziel.
                                if !navigationPending {
                                    previousHighlight = highlightedTitle
                                    navigationPending = true
                                    postKey("\u{F701}", keyCode: 125, windowNumber: window.windowNumber)
                                }
                            }
                        }
                        if ticks >= 100 {
                            finishMenu("Text-Menü nicht bedienbar: " + title + "; geöffnet=\(opened); gesendet=\(pressed); markiert=\(activeMenu.highlightedItem?.title ?? "nil"); "
                                + activeMenu.items.map { "\($0.title):\($0.isEnabled)" }.joined(separator: ", "))
                        }
                    }
                    if let timer {
                        RunLoop.main.add(timer, forMode: .common)
                        RunLoop.main.add(timer, forMode: .eventTracking)
                    }
                    DispatchQueue.main.async { _ = root.accessibilityPerformPress() }
                }
                try require(failure == nil, failure ?? "Text-Menü nicht bedienbar")
            }
            @MainActor func transformed(pretty: Bool, progressCapture: String) async throws {
                @MainActor func hasResult() -> Bool {
                    ws.activeTab?.content.prefix(128).contains("\n") == pretty
                }
                try await wait(2) { ws.documentTransformationActivity != nil || hasResult() }
                metric("menu_started=true activity=\(ws.documentTransformationActivity != nil)")
                try await wait(5) {
                    ws.documentTransformationActivity == nil || window.contentView.map {
                        markerView(id: "documentTransformationVisible", in: $0) != nil
                    } == true
                }
                if ws.documentTransformationActivity != nil { try await capture(progressCapture) }
                try await wait(120) { ws.documentTransformationActivity == nil && hasResult() }
            }
            @MainActor func exercise() async throws -> String {
                // Registriert zusätzlich für finish(): auch Helfer mit eigenem
                // Fehlerabschluss räumen diese ausschließlich künstlichen Dateien ab.
                let base = makeScreenshotFixtureDirectory()
                defer { try? FileManager.default.removeItem(at: base) }
                let fixtures = try await Task.detached(priority: .userInitiated) { () throws -> (String, URL, URL, Int) in
                    let blob = String(repeating: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+=", count: 1720)
                    let object: [String: Any] = ["alpha": ["blob": blob, "items": [["id": 1, "tags": ["one", "two"]]]],
                                               "beta": ["blob": blob, "items": [["id": 2, "values": [1, 2, 3]]]]]
                    let payload = String(decoding: try JSONSerialization.data(withJSONObject: object, options: [.sortedKeys]), as: UTF8.self)
                    let small = base.appendingPathComponent("manual-json.txt"), large = base.appendingPathComponent("large-array.txt")
                    try ("[" + Array(repeating: payload, count: 5).joined(separator: ",") + "]").write(to: small, atomically: true, encoding: .utf8)
                    let count = (100_000_000 + payload.utf8.count) / (payload.utf8.count + 1)
                    FileManager.default.createFile(atPath: large.path, contents: nil)
                    let handle = try FileHandle(forWritingTo: large)
                    // Dieser Worker kehrt vor dem äußeren finish zurück oder wirft.
                    defer { try? handle.close() }
                    try handle.write(contentsOf: Data("[".utf8))
                    for index in 0..<count { try handle.write(contentsOf: Data(((index == 0 ? "" : ",") + payload).utf8)) }
                    try handle.write(contentsOf: Data("]".utf8))
                    return (payload, small, large, count * (payload.utf8.count + 1) + 1)
                }.value
                try require(fixtures.3 >= 100_000_000, "Große Fixture liegt unter 100 MB")
                stage = "1MB öffnen"
                let editor = try await load(fixtures.1)
                stage = "Verzögerter Aktivitätshinweis"
                try await delayedIndicator()
                stage = "Klammerauswahl ohne Fensterwechsel"
                let blockSource = editor.string as NSString
                let arrayRange = blockSource.range(of: "[\"one\",\"two\"]")
                let objectRange = blockSource.range(of: "{\"id\":1,\"tags\":[\"one\",\"two\"]}")
                try require(arrayRange.location != NSNotFound && objectRange.location != NSNotFound,
                            "Klammer-Fixture fehlt")
                editor.selectionManager.setSelectedRange(NSRange(location: arrayRange.location + 3, length: 0))
                editor.scrollSelectionToVisible()
                try await wait {
                    editor.layoutManager.rectForOffset(arrayRange.location + 3)?.intersects(editor.visibleRect) == true
                }
                postKey("b", keyCode: 11, windowNumber: window.windowNumber, modifiers: .command)
                try await wait { editor.fastraSafeSelectedRange == arrayRange }
                try await capture("01-one-megabyte-wrapped")
                postKey("b", keyCode: 11, windowNumber: window.windowNumber, modifiers: .command)
                try await wait { editor.fastraSafeSelectedRange == objectRange }
                metric("array_and_parent_selected=true")
                var expected = ws.activeTab!.content
                let warmFootprint = physicalFootprint()
                writeSelfTestPasteboardString("," + fixtures.0)
                stage = "30 echte Cmd+V"
                for index in 1...30 {
                    try require(NSApp.isActive && window.isKeyWindow, "Dokumentfokus verloren")
                    editor.selectionManager.setSelectedRange(NSRange(location: editor.length - 1, length: 0))
                    expected = String(expected.dropLast()) + "," + fixtures.0 + "]"
                    let expectedLength = (expected as NSString).length
                    postKey("v", keyCode: 9, windowNumber: window.windowNumber, modifiers: .command)
                    try await wait { editor.length == expectedLength && ws.activeTab.map { ($0.content as NSString).length } == expectedLength }
                    let editorSnapshot = editor.string, modelSnapshot = ws.activeTab!.content, wanted = expected
                    let exact = await Task.detached { editorSnapshot == wanted && modelSnapshot == wanted }.value
                    try require(exact, "Editor/Modell nach Paste \(index) verändert")
                    try require(editor.fastraSafeSelectedRange == NSRange(location: expectedLength - 1, length: 0), "Cursor nach Paste \(index) falsch")
                    metric("paste=\(index) bytes=\(expectedLength)")
                }
                let pasteGrowth = Int64(physicalFootprint()) - Int64(warmFootprint)
                metric("paste_growth_bytes=\(pasteGrowth)")
                try require(maxGap < 1, "Einfügen pausierte den Main-Thread \(Int(maxGap * 1000))ms (Grenze <1000ms)")
                stage = "100MB öffnen"
                let openedAt = ProcessInfo.processInfo.systemUptime
                let largeEditor = try await load(fixtures.2)
                let openSeconds = ProcessInfo.processInfo.systemUptime - openedAt
                try require(openSeconds < 10 && largeEditor.length >= 100_000_000, "100 MB nicht binnen 10s sichtbar und vollständig")
                let compact = ws.activeTab!.content
                metric("bytes=\(largeEditor.length) visible_ms=\(Int(openSeconds * 1000))")
                try await capture("02-hundred-megabytes-wrapped")
                for enabled in [false, true] {
                    stage = enabled ? "100MB Minimap an" : "100MB Minimap aus"
                    workspaceDefaults().set(enabled, forKey: "editor.showMinimap")
                    try await wait { geometry(minimap: enabled, wrap: true) }
                    metric("minimap=\(enabled) wrap_width=\(CommandTargeting.editorTextView(for: ws)?.layoutManager.wrapLinesWidth ?? 0)")
                }
                try await capture("03-hundred-megabytes-minimap-restored")
                for enabled in [false, true] {
                    stage = enabled ? "100MB Umbruch an" : "100MB Umbruch aus"
                    ws.toggleSoftWrap()
                    try await wait { geometry(minimap: true, wrap: enabled) }
                    metric("wrap=\(enabled)")
                }
                CommandTargeting.editorTextView(for: ws)?.selectionManager.setSelectedRange(NSRange(location: 0, length: 0))
                stage = "100MB Textmenü formatieren"
                let formatStarted = ProcessInfo.processInfo.systemUptime
                try await menu("Dokument formatieren")
                try await transformed(pretty: true, progressCapture: "04-formatting-progress")
                metric("elapsed_ms=\(Int((ProcessInfo.processInfo.systemUptime - formatStarted) * 1000))")
                stage = "100MB Textmenü minifizieren"
                let minifyStarted = ProcessInfo.processInfo.systemUptime
                CommandTargeting.editorTextView(for: ws)?.selectionManager.setSelectedRange(NSRange(location: 0, length: 0))
                try await menu("Dokument minifizieren")
                try await transformed(pretty: false, progressCapture: "05-minifying-progress")
                let roundtrip = ws.activeTab!.content, drawn = CommandTargeting.editorTextView(for: ws)?.string
                try require(await Task.detached { roundtrip == compact && drawn == compact }.value, "Formatieren/Minifizieren verändert JSON")
                metric("elapsed_ms=\(Int((ProcessInfo.processInfo.systemUptime - minifyStarted) * 1000))")
                try await Task.sleep(for: .milliseconds(100))
                // Der volle 100-MB-Reflow hat ein eigenes Budget; interaktive
                // Einfuegungen werden oben weiterhin strenger begrenzt.
                try require(maxGap < 3, "Main-Thread pausierte maximal \(Int(maxGap * 1000))ms (Grenze <3000ms)")
                return "30 Cmd+V unverändert; 100 MB binnen \(Int(openSeconds * 1000))ms sichtbar, Umbruch und echtes Textmenü geprüft; Main maximal \(Int(maxGap * 1000))ms, Paste-Speicherwachstum \(pasteGrowth) Bytes"
            }
            do { let result = try await exercise(); heartbeat.invalidate(); finish(true, result) }
            catch { heartbeat.invalidate(); metric("failed=true"); finish(NSApp.isActive ? .fail : .environment, error.localizedDescription) }
        }
    }

    private static func runBracketSelectionTest() {
        testLabel = "bracketselection"
        guard let ws = Workspace.shared, let window = mainWindowForAXChecks() else {
            finish(false, "Dokumentfenster fehlt")
        }
        let object = #"{name:'😀', text:'} \' [', /* } ] ( */ nested:{n:1}}"#
        let source = "[\n  \(object),\n  {}\n]"
        let file = selfTestTemporaryDirectory().appendingPathComponent("block.js")
        do { try Data(source.utf8).write(to: file) }
        catch { finish(false, "JavaScript-Fixture nicht schreibbar") }
        ws.loadFile(at: file) { ok in
            guard ok else { finish(false, "JavaScript-Fixture lädt nicht") }
            Task { @MainActor in
                try? await Task.sleep(for: .milliseconds(600))
                guard let target = CommandTargeting.target(), target.workspace === ws else {
                    finish(false, "Editorziel fehlt")
                }
                guard NSApp.isActive, window.isKeyWindow else {
                    finish(.environment, "Tastaturtest benötigt den aktiven Dokumentfokus")
                }
                let editor = target.textView
                guard window.makeFirstResponder(editor) else { finish(false, "Editorfokus fehlt") }
                let expected = (source as NSString).range(of: object)
                editor.selectionManager.setSelectedRange(NSRange(location: expected.upperBound - 1, length: 0))
                let untouchedUndo = editor.undoManager?.canUndo
                func pressCommandB() {
                    postKey("b", keyCode: 11, windowNumber: window.windowNumber, modifiers: .command)
                }
                pressCommandB()
                waitFor(budget: 5, pause: 0.05, condition: {
                    editor.fastraSafeSelectedRange == expected
                }, onTimeout: { _ in finish(false, "Objekt samt Klammern nicht ausgewählt") }) {
                    if let directory = ProcessInfo.processInfo.environment["FASTRA_BRACKET_SELECTION_DIR"],
                       let root = window.contentView,
                       let bitmap = root.bitmapImageRepForCachingDisplay(in: root.bounds) {
                        root.cacheDisplay(in: root.bounds, to: bitmap)
                        let destination = URL(fileURLWithPath: directory)
                        try? FileManager.default.createDirectory(at: destination, withIntermediateDirectories: true)
                        try? bitmap.representation(using: .png, properties: [:])?.write(
                            to: destination.appendingPathComponent("javascript-block.png"))
                    }
                    pressCommandB()
                    waitFor(budget: 5, pause: 0.05, condition: {
                        editor.fastraSafeSelectedRange == NSRange(location: 0, length: source.utf16.count)
                    }, onTimeout: { _ in finish(false, "Auswahl nicht auf Array erweitert") }) {
                        guard editor.string == source, ws.activeTab?.content == source,
                              editor.undoManager?.canUndo == untouchedUndo,
                              (try? String(contentsOf: file, encoding: .utf8)) == source else {
                            finish(false, "Erweiterung, Text- oder Undo-Erhalt fehlgeschlagen")
                        }
                        workspaceDefaults().set(false, forKey: MarkdownEditingMode.defaultsKey)
                        workspaceDefaults().set(false, forKey: "markdown.integratedPreview")
                        ws.setLanguageOverride(.markdown)
                        Task { @MainActor in
                            try? await Task.sleep(for: .milliseconds(600))
                            guard let markdown = CommandTargeting.target(),
                                  window.makeFirstResponder(markdown.textView) else {
                                finish(false, "Markdown verliert den Fett-Shortcut")
                            }
                            markdown.textView.selectionManager.setSelectedRange((source as NSString).range(of: "name"))
                            pressCommandB()
                            let formatted = source.replacingOccurrences(of: "name", with: "**name**")
                            waitFor(budget: 5, pause: 0.05, condition: {
                                markdown.textView.string == formatted
                            }, onTimeout: { _ in finish(false, "Command-B formatiert Markdown nicht fett") }) {
                                ws.setLanguageOverride(.javascript)
                                waitFor(budget: 5, pause: 0.05, condition: {
                                    !ws.activeTabIsMarkdown
                                        && CommandTargeting.target()?.textView.string == formatted
                                }, onTimeout: { _ in finish(false, "JavaScript-Editor nach Formatwechsel fehlt") }) {
                                    guard let json = CommandTargeting.target(),
                                          window.makeFirstResponder(json.textView) else {
                                        finish(false, "JavaScript-Fokus nach Markdown fehlt")
                                    }
                                    let expectedObject = (formatted as NSString).range(of:
                                        object.replacingOccurrences(of: "name", with: "**name**"))
                                    json.textView.selectionManager.setSelectedRange(
                                        NSRange(location: expectedObject.upperBound - 1, length: 0))
                                    // Ohne erneutes Öffnen des Bearbeiten-Menüs:
                                    // auch alte Menü-Kürzel müssen aktuell routen.
                                    pressCommandB()
                                    waitFor(budget: 5, pause: 0.05, condition: {
                                        json.textView.fastraSafeSelectedRange == expectedObject
                                    }, onTimeout: { _ in finish(false, "Command-B bleibt nach Formatwechsel bei Markdown hängen") }) {
                                        let template = "function f() { return `literal } ${JSON.stringify({n: 1})} (`; }"
                                        let templateFile = selfTestTemporaryDirectory().appendingPathComponent("interpolation.js")
                                        do { try Data(template.utf8).write(to: templateFile) }
                                        catch { finish(false, "Template-Fixture nicht schreibbar") }
                                        ws.loadFile(at: templateFile) { loaded in
                                            guard loaded else { finish(false, "Template-Fixture lädt nicht") }
                                            Task { @MainActor in
                                                try? await Task.sleep(for: .milliseconds(600))
                                                guard let target = CommandTargeting.target(),
                                                      window.makeFirstResponder(target.textView) else {
                                                    finish(false, "Template-Editorfokus fehlt")
                                                }
                                                let object = (template as NSString).range(of: "{n: 1}")
                                                let call = (template as NSString).range(of: "({n: 1})")
                                                target.textView.selectionManager.setSelectedRange(
                                                    NSRange(location: object.location + 1, length: 0))
                                                pressCommandB()
                                                waitFor(budget: 5, pause: 0.05, condition: {
                                                    target.textView.fastraSafeSelectedRange == object
                                                }, onTimeout: { _ in finish(false, "Template-Objekt nicht ausgewählt") }) {
                                                    pressCommandB()
                                                    waitFor(budget: 5, pause: 0.05, condition: {
                                                        target.textView.fastraSafeSelectedRange == call
                                                    }, onTimeout: { _ in finish(false, "Template-Auswahl nicht auf Aufruf erweitert") }) {
                                                        finish(true, "Command-B: JavaScript-Objekt, Array und Template-Interpolation; Text/Undo erhalten; Markdown und Formatwechsel korrekt")
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // MARK: - -selftest wordclick

    /// Reproduziert den Doppelklick-Fehler aus einer langen Markdown-Zeile im
    /// echten Split-Editor: Wortanfang und Wortende müssen über ihre sichtbaren
    /// Trefferflächen jeweils zum ganzen Wort aufgelöst werden.
    private static func runWordDoubleClickTest() {
        testLabel = "wordclick"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks() else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        let fallbackText = wordClickFixtureContent()
        let text: String
        if let path = ProcessInfo.processInfo.environment["FASTRA_WORDCLICK_FIXTURE"],
           let fixture = try? String(contentsOfFile: path, encoding: .utf8) {
            // Lokale Realdatei für die Erstdiagnose; der normale Selbsttest
            // bleibt mit dem neutralen Größenabbild vollständig portabel.
            text = fixture
        } else {
            text = fallbackText
        }
        guard let target = wordClickTargetRange(in: text) else {
            finish(false, "Zielbereich fehlt im Doppelklick-Fixture")
        }
        let unrelated = NSRange(
            location: max(target.location - 12, 0), length: 10
        )
        let suffix = (text as NSString).substring(with: NSRange(
            location: target.location + 2, length: target.length - 2
        ))
        let initial = NSMutableString(string: text)
        initial.deleteCharacters(in: NSRange(
            location: target.location + 2,
            length: target.length - 2
        ))
        let initialText = initial as String
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-wordclick-\(UUID().uuidString).md")
        do { try Data(initialText.utf8).write(to: tmp) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        let environment = ProcessInfo.processInfo.environment
        let requestedWindowWidth = environment["FASTRA_WORDCLICK_WINDOW_WIDTH"]
            .flatMap(Double.init) ?? 1100
        let requestedSidebarWidth = environment["FASTRA_WORDCLICK_SIDEBAR_WIDTH"]
            .flatMap(Double.init) ?? 360.08984375
        let requestedPreviewWidth = environment["FASTRA_WORDCLICK_PREVIEW_WIDTH"]
            .flatMap(Double.init) ?? 422.6640625
        ws.sidebarWidth = requestedSidebarWidth
        ws.markdownPreviewWidth = requestedPreviewWidth
        // Diese Geometrie traf den gemeldeten Fragment-Grenzfall
        // deterministisch. Optionale Werte bleiben für die Erstdiagnose.
        window.setContentSize(NSSize(width: requestedWindowWidth, height: 800))
        workspaceDefaults().set(true, forKey: "markdown.integratedPreview")
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "Markdown-Fixture lädt nicht") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                guard let root = window.contentView,
                      let textView = editorTextView(in: root) as? TextView,
                      textView.string == initialText else {
                    finish(false, "Markdown-TextView mit Fixture fehlt")
                }
                window.makeFirstResponder(textView)
                prepareWordClickInitialLayout(
                    textView: textView, window: window,
                    expectedText: text, target: target,
                    unrelated: unrelated, suffix: suffix)
            }
        }
    }

    /// Erzeugt vor der Einfügung bewusst reale Fragmente für den nur zwei
    /// Zeichen langen Wortanfang. Ein bloßer Reload des fertigen Worts würde
    /// den gemeldeten stehengebliebenen Layoutzustand nicht reproduzieren.
    private static func prepareWordClickInitialLayout(
        textView: TextView, window: NSWindow, expectedText: String,
        target: NSRange, unrelated: NSRange, suffix: String
    ) {
        let initialTarget = NSRange(location: target.location, length: 2)
        waitFor(budget: 4, pause: 0.1,
                condition: {
                    // Jeder Durchlauf zieht nach: scrollen, auslegen, messen.
                    textView.scrollToRange(initialTarget)
                    textView.layoutManager.layoutLines()
                    guard let rect = textView.layoutManager.rectForOffset(target.location + 1),
                          rect.width > 0, textView.visibleRect.intersects(rect) else { return false }
                    return true
                },
                onTimeout: { book in
                    finish(false, "kurzer Wortanfang wird nicht real sichtbar — \(book.summary)")
                },
                then: {
                    textView.selectionManager.setSelectedRange(NSRange(
                        location: target.location + 2, length: 0
                    ))
                    textView.insertText(
                        suffix,
                        replacementRange: NSRange(location: NSNotFound, length: 0)
                    )
                    pollWordClickMutation(
                        textView: textView, window: window, expectedText: expectedText,
                        target: target, unrelated: unrelated)
                })
    }

