    private static func pollShortSelectionEditorReady(
        window: NSWindow, expectedText: String
    ) {
        var found: (textView: TextView, scrollView: NSScrollView)?
        waitFor(budget: 10, pause: 0.1,
                condition: {
                    guard let root = window.contentView,
                          markdownWebView(in: root) != nil,
                          let textView = editorTextView(in: root) as? TextView,
                          textView.string == expectedText,
                          let scrollView = textView.enclosingScrollView else { return false }
                    found = (textView, scrollView)
                    return true
                },
                onTimeout: { book in
                    finish(false, "Markdown-Split mit Fixture nicht bereit — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Editor nach Erfolg verschwunden") }
                    let (textView, scrollView) = found
                    guard window.makeFirstResponder(textView) else {
                        finish(false, "Editor wird nicht First Responder")
                    }
                    textView.layoutManager.layoutLines()
                    textView.selectionManager.setSelectedRange(
                        NSRange(location: 0, length: 0)
                    )
                    if let flags = NSEvent.keyEvent(
                        with: .flagsChanged, location: .zero,
                        modifierFlags: .shift,
                        timestamp: ProcessInfo.processInfo.systemUptime,
                        windowNumber: window.windowNumber, context: nil,
                        characters: "", charactersIgnoringModifiers: "",
                        isARepeat: false, keyCode: 56
                    ) {
                        NSApp.postEvent(flags, atStart: false)
                    }
                    sendShortSelectionKey(
                        textView: textView, scrollView: scrollView,
                        window: window, step: 0
                    )
                })
    }

    /// 64 echte Shift+↓ — deutlich mehr als die Datei visuelle Zeilen hat,
    /// damit die Kante sicher bis ans Dateiende läuft. Nach jedem Tastendruck
    /// (plus Runloop-Takt) muss die bewegte Kante im Viewport liegen.
    private static func sendShortSelectionKey(
        textView: TextView, scrollView: NSScrollView,
        window: NSWindow, step: Int
    ) {
        guard let key = NSEvent.keyEvent(
            with: .keyDown, location: .zero,
            modifierFlags: .shift,
            timestamp: ProcessInfo.processInfo.systemUptime,
            windowNumber: window.windowNumber, context: nil,
            characters: "\u{F701}",
            charactersIgnoringModifiers: "\u{F701}",
            isARepeat: step > 0, keyCode: 125
        ) else {
            finish(false, "konnte Shift+Pfeil-nach-unten nicht bauen")
        }
        NSApp.postEvent(key, atStart: false)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.06) {
            let range = textView.selectedRange()
            let visible = scrollView.documentVisibleRect
            if range.length > 0,
               let activeRect = textView.layoutManager.rectForOffset(
                   NSMaxRange(range)
               ),
               // Halbe Zeilenhöhe Toleranz: Der verzögerte Abgleich aus
               // Patch 4r darf einen Takt hinterherlaufen, aber nie eine
               // ganze Zeile verlieren.
               activeRect.minY > visible.maxY + activeRect.height / 2 {
                finish(false, "Schritt \(step): bewegte Kante \(activeRect) "
                    + "unterhalb des Viewports \(visible)")
            }
            if step < 63 {
                sendShortSelectionKey(
                    textView: textView, scrollView: scrollView,
                    window: window, step: step + 1
                )
                return
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                let finalRange = textView.selectedRange()
                let finalVisible = scrollView.documentVisibleRect
                guard finalRange.length > 0,
                      NSMaxRange(finalRange)
                          == (textView.string as NSString).length,
                      let edge = textView.layoutManager.rectForOffset(
                          NSMaxRange(finalRange)
                      ) else {
                    finish(false, "Auswahl erreicht das Dateiende nicht: "
                        + "\(textView.selectedRange())")
                }
                guard finalVisible.maxY >= edge.maxY - 1 else {
                    finish(false, "Dateiende-Kante \(edge) liegt unter dem "
                        + "Viewport \(finalVisible)")
                }
                finish(true, "bewegte Kante blieb über 64 Shift+↓ sichtbar "
                    + "bis ans Dateiende (Viewport \(finalVisible))")
            }
        }
    }

    // MARK: - -selftest dragscroll

    /// Maus-Drag-Selektion über den unteren Fensterrand hinaus: Der Editor
    /// muss automatisch mitscrollen und die bewegte Kante sichtbar halten,
    /// statt die Auswahl unsichtbar unter dem Viewport weiterwachsen zu
    /// lassen.
    /// Einstieg des langen Dauertests. Die Arbeit selbst liegt in
    /// `SoakTest`; hier steht nur die Phasensteuerung.
    ///
    /// Parameter kommen als reguläre Defaults-Argumente:
    ///   -soakPhase 1|2|3   Abschnitt des Laufs (Phase 2 folgt einem Neustart)
    ///   -soakRounds  N     Aktionen je Phase
    ///   -soakDir     Pfad  Arbeitsverzeichnis mit den Testdokumenten;
    ///                      optional liegen unter `real/` Kopien echter
    ///                      Dokumente (Markdown-Ordner, RTFD-Bundle)
    ///   -soakLog     Pfad  gemeinsames Befundprotokoll aller Phasen
    ///   -soak4DProject Pfad  Wurzel eines echten 4D-Projekts (optional,
    ///                      Phase 3)
    ///   -soak4DMethod  Pfad  vom Skript gewählte `.4dm`-Methode (optional;
    ///                      ohne sie entfällt das 4D-Szenario)
    @MainActor
    private static func runSoakTest() {
        testLabel = "soak"
        let defaults = UserDefaults.standard
        let phase = max(1, defaults.integer(forKey: "soakPhase"))
        let rounds = max(1, defaults.integer(forKey: "soakRounds"))
        guard let directoryPath = defaults.string(forKey: "soakDir"),
              let logPath = defaults.string(forKey: "soakLog") else {
            finish(false, "soakDir und soakLog müssen übergeben werden")
        }
        let directory = URL(fileURLWithPath: directoryPath)
        let logURL = URL(fileURLWithPath: logPath)
        let pasteboardBackupURL = directory.appendingPathComponent("pasteboard-backup.plist")
        do {
            // Nach einem Absturz der vorigen Phase liegt deren Sicherung noch
            // da. Sie gehört zurück, bevor diese Phase einen neuen Stand merkt
            // — es sei denn, inzwischen hat jemand anders kopiert; dann bleibt
            // der neuere Inhalt stehen (Besitzprüfung in der Wiederherstellung).
            _ = try restoreSoakPasteboardIfPresent(from: pasteboardBackupURL)
        } catch {
            finish(false, "liegengebliebene Zwischenablage nicht wiederherstellbar: "
                   + error.localizedDescription)
        }
        guard let workspace = Workspace.shared,
              mainWindowForAXChecks() != nil else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        SoakTest.reset()
        // Ab hier wandert jeder Befund sofort ins gemeinsame Protokoll. Wird
        // die Phase abgeschossen — etwa von der Frist des Runners —, bleibt
        // alles Beobachtete erhalten; vorher war es restlos weg.
        SoakTest.beginReport(at: logURL)
        SoakTest.currentPhase = "\(phase)"
        // Startwert aus der Phase: wechselnde Abläufe, aber wiederholbar.
        SoakTest.seedRandom(UInt64(phase) &* 7_919 &+ 1)
        // Der Dauertest kopiert selbst (⌘C) und darf fremden
        // Clipboard-Inhalt nicht zerstören: am Anfang sichern, am
        // Phasenende wiederherstellen.
        do {
            try backupSoakPasteboard(to: pasteboardBackupURL)
        } catch {
            finish(selfTestPasteboardOutcome(for: error), "Zwischenablage nicht sicherbar: "
                   + error.localizedDescription)
        }

        if phase == 1 {
            let documents = SoakTest.prepareDocuments(in: directory, count: 3)
            guard documents.count == 3 else {
                finish(false, "Testdokumente nicht erzeugbar")
            }
            let textDocument = SoakTest.prepareTextDocument(in: directory)
            // Erstes Dokument ins vorhandene Fenster, für die übrigen je ein
            // eigenes Fenster — so entsteht die Mehrfenster-Lage, in der die
            // gemeldeten Fehler auftraten. Ins erste Fenster kommt zusätzlich
            // ein Text-Tab: Erst ein Nicht-Markdown-Dokument (kein leerer
            // Tab, der nur die Startansicht zeigt) kann eine
            // stehengebliebene Markdown-Vorschau überhaupt aufdecken.
            workspace.loadFile(at: documents[0]) { _ in
                workspace.loadFile(at: textDocument) { _ in
                    // Fensteraufbau und Rundenstart als Fortsetzung, weil
                    // davor optional noch ein echtes Markdown-Dokument als
                    // weiterer Tab ins erste Fenster kommt.
                    let openWindowsThenRun = {
                        for document in documents.dropFirst() {
                            let extra = DocumentWindowController.openNewDocument()
                            extra.loadFile(at: document) { _ in }
                        }
                        waitForSoakWindows(expected: 3, tick: 0) {
                            // Ein optional bereitgestelltes echtes
                            // RTFD-Bundle wird nach dem Fensteraufbau über
                            // den echten Öffnen-Pfad umgewandelt und sofort
                            // weiterbearbeitet; erst danach starten die
                            // Runden. (Die Umwandlung schreibt ihr Ergebnis
                            // neben die Quelle, also ins Arbeitsverzeichnis.)
                            if let bundle = SoakTest.realRTFDBundle(in: directory) {
                                SoakTest.runRTFDImport(bundle: bundle,
                                                       workspace: workspace) {
                                    runSoakRounds(rounds: rounds, done: 0,
                                                  logURL: logURL)
                                }
                            } else {
                                runSoakRounds(rounds: rounds, done: 0,
                                              logURL: logURL)
                            }
                        }
                    }
                    if let realMarkdown = SoakTest.realMarkdownDocument(in: directory) {
                        workspace.loadFile(at: realMarkdown) { _ in
                            openWindowsThenRun()
                        }
                    } else {
                        openWindowsThenRun()
                    }
                }
            }
            return
        }

        // Phase 2 und 3 folgen einem Neustart: Erst prüfen, was die
        // Sitzungswiederherstellung geliefert hat, dann weiterarbeiten.
        waitForSoakWindows(expected: 3, tick: 0) {
            SoakTest.checkInvariants(action: "nach dem Neustart",
                                     before: SoakTest.snapshot(),
                                     target: nil, expectedWindowCount: 3)
            // Phase 3 optional mit echtem 4D-Projekt: neues Fenster, Projekt
            // öffnen, Sprachfunktionen prüfen — danach normale Runden, an
            // denen das 4D-Fenster teilnimmt.
            if phase >= 3,
               let projectPath = defaults.string(forKey: "soak4DProject"),
               !projectPath.isEmpty {
                guard let methodPath = defaults.string(forKey: "soak4DMethod"),
                      !methodPath.isEmpty,
                      FileManager.default.fileExists(atPath: methodPath) else {
                    // Die Methode (längste git-saubere) wählt das Skript aus;
                    // ohne diese Angabe bewusst nicht selbst wählen, sondern
                    // das Szenario überspringen.
                    SoakTest.note("4D-Szenario übersprungen: -soak4DMethod "
                                  + "fehlt oder zeigt auf keine Datei")
                    runSoakRounds(rounds: rounds, done: 0, logURL: logURL)
                    return
                }
                SoakTest.runFourDScenario(
                    projectURL: URL(fileURLWithPath: projectPath),
                    methodURL: URL(fileURLWithPath: methodPath)
                ) {
                    runSoakRounds(rounds: rounds, done: 0, logURL: logURL)
                }
                return
            }
            runSoakRounds(rounds: rounds, done: 0, logURL: logURL)
        }
    }

    // MARK: - Zwischenablage sichern und zurückgeben

    /// Eine itemgetreue Sicherung der Zwischenablage: je Item die eigene
    /// Kombination aus Typ-Name und Daten. Bewusst nur aus Zeichenketten und
    /// Daten gebaut, damit sie sich unverändert als Property-List speichern
    /// lässt.
    private typealias StoredPasteboardItems = SelfTestPasteboardBackup.Items

    /// Liest alle Items der allgemeinen Zwischenablage itemgetreu aus.
    private static func capturePasteboardItems() throws -> StoredPasteboardItems {
        try (NSPasteboard.general.pasteboardItems ?? []).map { item in
            var stored: [String: Data] = [:]
            for type in item.types {
                guard let data = item.data(forType: type) else {
                    throw NSError(
                        domain: "FastraSelfTestPasteboard", code: 4,
                        userInfo: [NSLocalizedDescriptionKey:
                            "Zwischenablage-Typ \(type.rawValue) ließ sich nicht vollständig sichern"]
                    )
                }
                stored[type.rawValue] = data
            }
            return stored
        }
    }

    /// Erwartungswert für Copy-/Cut-Pfade, die genau ein Plain-Text-Item
    /// schreiben sollen. Nicht nur der sichtbare String zählt: Ein fremdes
    /// HTML-/RTF-Item mit demselben Text darf nie als test-eigener Inhalt
    /// bestätigt und beim Aufräumen überschrieben werden.
    private static func plainTextPasteboardItems(
        _ string: String
    ) throws -> StoredPasteboardItems {
        let item = NSPasteboardItem()
        guard item.setString(string, forType: .string) else {
            throw NSError(domain: "FastraSelfTestPasteboard", code: 12,
                          userInfo: [NSLocalizedDescriptionKey:
                            "erwarteter Plain-Text ließ sich nicht vorbereiten"])
        }
        var stored: [String: Data] = [:]
        for type in item.types {
            guard let data = item.data(forType: type) else {
                throw NSError(domain: "FastraSelfTestPasteboard", code: 13,
                              userInfo: [NSLocalizedDescriptionKey:
                                "erwarteter Plain-Text-Typ ließ sich nicht lesen"])
            }
            stored[type.rawValue] = data
        }
        return [stored]
    }

    /// Schreibt eine Sicherung itemgetreu zurück. Nimmt AppKit einen Typ oder
    /// die Items nicht an, wirft der Aufruf: Ein stilles Verschlucken würde
    /// genau den Verlust verstecken, gegen den gesichert wurde.
    private static func preparedPasteboardItems(
        _ stored: StoredPasteboardItems
    ) throws -> [NSPasteboardItem] {
        var items: [NSPasteboardItem] = []
        for storedItem in stored {
            let item = NSPasteboardItem()
            for (rawType, data) in storedItem {
                guard item.setData(data, forType: NSPasteboard.PasteboardType(rawValue: rawType))
                else {
                    throw NSError(domain: "FastraSoakPasteboard", code: 2,
                                  userInfo: [NSLocalizedDescriptionKey:
                                    "Pasteboard-Typ \(rawType) ließ sich nicht vorbereiten"])
                }
            }
            items.append(item)
        }
        return items
    }

    private static func writePreparedPasteboardItems(
        _ items: [NSPasteboardItem]
    ) throws {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        if !items.isEmpty, !pasteboard.writeObjects(items) {
            throw NSError(domain: "FastraSoakPasteboard", code: 3,
                          userInfo: [NSLocalizedDescriptionKey:
                            "gesicherte Pasteboard-Items wurden nicht angenommen"])
        }
    }

    private static func writePasteboardItems(_ stored: StoredPasteboardItems) throws {
        try writePreparedPasteboardItems(preparedPasteboardItems(stored))
    }

    /// Besitznachweis über `NSPasteboard.changeCount`. Der Zähler steigt
    /// systemweit bei jedem Schreiben. Merkt sich ein Test den Stand direkt
    /// nach seiner eigenen Änderung, erkennt er später sicher, ob der Inhalt
    /// noch der eigene ist: Ist der Zähler weitergelaufen, hat inzwischen
    /// jemand anders kopiert — meist der Nutzer selbst. Dann darf keine
    /// Sicherung zurückgeschrieben werden, sonst verschwindet dessen frische
    /// Kopie. (Ein Selbsttest kann sein eigenes Schreiben nicht am Zähler
    /// erkennen, deshalb wird der Stand ausdrücklich nach jeder eigenen
    /// Änderung neu gemerkt.)
    private static func pasteboardIsStillOwned(since ownedChangeCount: Int) -> Bool {
        NSPasteboard.general.changeCount == ownedChangeCount
    }

    /// Kurze Selbsttests mit Copy/Paste sichern die Nutzer-Zwischenablage im
    /// Speicher. Vor jeder test-eigenen Änderung werden der erwartete nächste
    /// Zählerstand und der Zustand „noch unbestätigt“ atomar persistiert. Erst
    /// die Nachkontrolle bestätigt den Testbesitz. Ein Absturz dazwischen
    /// bewahrt die private Sicherung, schreibt sie aber nicht automatisch über
    /// einen möglicherweise inzwischen kopierten Nutzerinhalt.
    private static let selfTestPasteboardSession = SelfTestPasteboardSession(
        backend: SelfTestPasteboardSession<[NSPasteboardItem]>.Backend(
            currentChangeCount: { NSPasteboard.general.changeCount },
            captureItems: { try capturePasteboardItems() },
            persistBackup: { try persistSelfTestPasteboardBackup($0) },
            abandonBackup: {
                if let url = selfTestPasteboardBackupURL {
                    try? FileManager.default.removeItem(at: url)
                }
            },
            prepareRestore: { try preparedPasteboardItems($0) },
            writeRestore: { try writePreparedPasteboardItems($0) }
        )
    )

    /// Der Runner gibt einen Pfad in seiner Wegwerf-Sandbox vor. Die Datei
    /// überlebt einen Absturz des App-Prozesses, sodass der Runner die
    /// Zwischenablage anschließend zurückgeben kann. Ein direkter Aufruf ohne
    /// Runner bleibt im Speicher abgesichert und erzeugt keine lose Datei.
    private static var selfTestPasteboardBackupURL: URL? {
        guard let directory = ProcessInfo.processInfo.environment[
            "FASTRA_SELFTEST_PASTEBOARD_DIR"
        ], !directory.isEmpty else { return nil }
        return URL(fileURLWithPath: directory, isDirectory: true)
            .appendingPathComponent("pasteboard-backup.plist")
    }

    private static func persistSelfTestPasteboardBackup(
        _ backup: SoakPasteboardBackup
    ) throws {
        guard let url = selfTestPasteboardBackupURL else { return }
        let plist: [String: Any] = [
            soakPasteboardItemsKey: backup.items,
            soakPasteboardOwnedKey: backup.ownedChangeCount,
            soakPasteboardConfirmedKey: backup.mutationConfirmed,
        ]
        let data = try PropertyListSerialization.data(
            fromPropertyList: plist, format: .binary, options: 0
        )
        try data.write(to: url, options: .atomic)
    }

    /// Muss unmittelbar vor jeder eigenen Änderung aufgerufen werden. Hat der
    /// Nutzer seit der vorigen Teständerung selbst kopiert, endet der Test als
    /// Umgebungsfehler, statt den neueren Inhalt nochmals zu überschreiben.
    private static func prepareSelfTestPasteboardMutation() throws {
        try selfTestPasteboardSession.prepare()
    }

    private static func noteSelfTestPasteboardMutation(
        expectedItems: StoredPasteboardItems
    ) throws {
        try selfTestPasteboardSession.note(expectedItems: expectedItems)
    }

    /// Schreibt genau ein vorbereitetes Test-Item über `clearContents`/`setData`.
    /// Die Nachkontrolle bestätigt den vorbereiteten Zähler und Inhalt.
    private static func writeSelfTestPasteboardItem(_ item: NSPasteboardItem) {
        var expectedItem: [String: Data] = [:]
        for type in item.types {
            guard let data = item.data(forType: type) else {
                finish(false, "Testinhalt ließ sich nicht vollständig vorbereiten")
            }
            expectedItem[type.rawValue] = data
        }
        prepareSelfTestPasteboardMutationOrFinish()
        let pasteboard = NSPasteboard.general
        let clearReturnedChangeCount = pasteboard.clearContents()
        for type in item.types {
            guard let data = item.data(forType: type),
                  pasteboard.setData(data, forType: type) else {
                finish(false, "Testinhalt wurde von der Zwischenablage nicht angenommen")
            }
        }
        fputs(
            "SELFTEST-PASTEBOARD-PHASE test=\(testLabel) "
                + "expected-session=\(selfTestPasteboardSession.expectedChangeCount.map(String.init) ?? "nil") "
                + "clear-returned=\(clearReturnedChangeCount) "
                + "fixture-types=\(expectedItem.keys.sorted().joined(separator: ","))\n",
            stderr
        )
        noteSelfTestPasteboardMutationOrFinish(expectedItems: [expectedItem])
    }

    private static func writeSelfTestPasteboardString(_ string: String) {
        let item = NSPasteboardItem()
        guard item.setString(string, forType: .string) else {
            finish(false, "Testtext ließ sich für die Zwischenablage nicht vorbereiten")
        }
        writeSelfTestPasteboardItem(item)
    }

    private static func writeSelfTestPasteboardData(
        _ data: Data, type: NSPasteboard.PasteboardType
    ) {
        let item = NSPasteboardItem()
        guard item.setData(data, forType: type) else {
            finish(false, "Testdaten ließen sich für die Zwischenablage nicht vorbereiten")
        }
        writeSelfTestPasteboardItem(item)
    }

    private static func prepareSelfTestPasteboardMutationOrFinish() {
        do { try prepareSelfTestPasteboardMutation() }
        catch { finish(selfTestPasteboardOutcome(for: error), error.localizedDescription) }
    }

    private static func noteSelfTestPasteboardMutationOrFinish(
        expectedItems: StoredPasteboardItems
    ) {
        do {
            try noteSelfTestPasteboardMutation(expectedItems: expectedItems)
        }
        catch {
            finish(
                selfTestPasteboardOutcome(for: error),
                "Zwischenablage-Sicherung konnte nicht fortgeschrieben werden: "
                    + error.localizedDescription
            )
        }
    }

    /// Zwischenablagefehler unterscheiden: Code 1/5 bedeutet fremdes Kopieren
    /// während des Laufs. Code 4 bedeutet, dass ein zugesagter Inhalt nicht
    /// lesbar war oder sich die Zwischenablage zwischen Typliste und Zugriff
    /// änderte. Diese Umgebungsfälle belegen keinen Produktfehler.
    static func selfTestPasteboardOutcome(for error: Error) -> SelfTestOutcome {
        SelfTestPasteboardSession<[NSPasteboardItem]>.outcome(for: error)
    }

    private static func finishSelfTestPasteboardMutation() -> SelfTestCompletion.PasteboardCleanup {
        selfTestPasteboardSession.finish()
    }

    /// Der Dauertest kopiert selbst in die Zwischenablage. Fremder Inhalt wird
    /// deshalb itemgetreu gesichert: Jedes Item behält seine eigene Kombination
    /// aus Typen und Daten. Die Datei lässt auch den Runner nach einem Absturz
    /// oder Timeout wiederherstellen. Mitgesichert wird der `changeCount`-Stand
    /// nach der letzten test-eigenen Änderung — er entscheidet beim
    /// Wiederherstellen darüber, ob die Zwischenablage überhaupt noch dem Test
    /// gehört. Der Stand gehört deshalb auch in die Datei: Nach einem Absturz
    /// spielt ein frischer Prozess die Sicherung ein und hat kein Gedächtnis.
    private typealias SoakPasteboardBackup = SelfTestPasteboardBackup
    private static var soakPasteboardBackup: SoakPasteboardBackup?
    private static var soakPasteboardBackupFileURL: URL?
    private static let soakPasteboardItemsKey = "items"
    private static let soakPasteboardOwnedKey = "ownedChangeCount"
    private static let soakPasteboardConfirmedKey = "mutationConfirmed"

    /// Ablageort der Sicherung. Protokoll und Sicherung liegen im selben
    /// Arbeitsverzeichnis, das der Runner anlegt.
    private static func soakPasteboardBackupURL(logURL: URL) -> URL {
        logURL.deletingLastPathComponent()
            .appendingPathComponent("pasteboard-backup.plist")
    }

    @MainActor
    private static func backupSoakPasteboard(to backupURL: URL) throws {
        SoakTest.confirmedCopy = nil
        // Vor der ersten eigenen Änderung ist der aktuelle Zählerstand der
        // eigene Bezugspunkt: Solange er gilt, hat niemand anders geschrieben.
        let backup = try SoakPasteboardBackup.capture(
            currentChangeCount: { NSPasteboard.general.changeCount },
            captureItems: { try capturePasteboardItems() }
        )
        soakPasteboardBackupFileURL = backupURL
        try writeSoakPasteboardBackup(backup, to: backupURL)
    }

    @MainActor
    private static func writeSoakPasteboardBackup(_ backup: SoakPasteboardBackup,
                                                  to backupURL: URL) throws {
        let plist: [String: Any] = [
            soakPasteboardItemsKey: backup.items,
            soakPasteboardOwnedKey: backup.ownedChangeCount,
            soakPasteboardConfirmedKey: backup.mutationConfirmed,
        ]
        let data = try PropertyListSerialization.data(
            fromPropertyList: plist, format: .binary, options: 0)
        try data.write(to: backupURL, options: .atomic)
        soakPasteboardBackup = backup
    }

    /// Journaliert vor dem echten ⌘C den exakt erwarteten nächsten Zähler als
    /// unbestätigt. Erst die Nachkontrolle macht ihn wiederherstellbar. Bei
    /// einem Absturz in der Lücke bleibt die Sicherung für eine manuelle
    /// Rettung erhalten, ohne möglicherweise fremden Inhalt zu überschreiben.
    @MainActor
    static func prepareSoakPasteboardMutation() -> Bool {
        SoakTest.confirmedCopy = nil
        guard var backup = soakPasteboardBackup else { return false }
        guard NSPasteboard.general.changeCount == backup.ownedChangeCount,
              backup.mutationConfirmed,
              let backupURL = soakPasteboardBackupFileURL else { return false }
        backup.ownedChangeCount &+= 1
        backup.mutationConfirmed = false
        do {
            try writeSoakPasteboardBackup(backup, to: backupURL)
            return true
        }
        catch {
            SoakTest.record("Besitzstand der Zwischenablage wird vorbereitet",
                            error.localizedDescription)
            return false
        }
    }

    @MainActor
    private static func noteSoakPasteboardOwnership(
        changeCount: Int, expectedString: String
    ) {
        guard var backup = soakPasteboardBackup,
              backup.ownedChangeCount == changeCount,
              NSPasteboard.general.changeCount == changeCount else {
            SoakTest.record(
                "Besitzstand der Zwischenablage wird bestätigt",
                "⌘C änderte den globalen Zähler nicht genau einmal"
            )
            return
        }
        guard let expectedItems = try? plainTextPasteboardItems(expectedString),
              let actualItems = try? capturePasteboardItems(),
              actualItems == expectedItems else {
            SoakTest.record(
                "Besitzstand der Zwischenablage wird bestätigt",
                "Zähler passte, die vollständigen Clipboard-Items stammen aber "
                + "nicht aus der Testauswahl"
            )
            return
        }
        guard let backupURL = soakPasteboardBackupFileURL else {
            SoakTest.record("Besitzstand der Zwischenablage wird bestätigt",
                            "Sicherungsdatei fehlt")
            return
        }
        backup.mutationConfirmed = true
        do {
            try writeSoakPasteboardBackup(backup, to: backupURL)
            SoakTest.confirmedCopy = SoakTest.CopiedText(
                changeCount: changeCount, text: expectedString)
        } catch {
            SoakTest.record("Besitzstand der Zwischenablage wird bestätigt",
                            error.localizedDescription)
        }
    }

    /// Ergebnis eines Wiederherstellungsversuchs.
    private enum SoakPasteboardRestoreOutcome: Equatable {
        /// Sicherung war da und wurde eingespielt.
        case restored
        /// Es lag gar keine Sicherung vor. (Eine bewusst leere Zwischenablage
        /// ist dagegen eine vorhandene, leere Sicherung.)
        case noBackup
        /// Nach der letzten test-eigenen Änderung hat jemand anders kopiert.
        /// Der neuere Inhalt bleibt unangetastet.
        case keptForeignContent
    }

    /// Stellt eine gespeicherte Zwischenablage wieder her — aber nur, wenn sie
    /// noch dem Test gehört (siehe `pasteboardIsStillOwned`).
    @MainActor
    @discardableResult
    private static func restoreSoakPasteboardIfPresent(
        from backupURL: URL
    ) throws -> SoakPasteboardRestoreOutcome {
        let fileManager = FileManager.default
        var backup: SoakPasteboardBackup
        if let inMemory = soakPasteboardBackup {
            backup = inMemory
        } else {
            guard fileManager.fileExists(atPath: backupURL.path) else { return .noBackup }
            let data = try Data(contentsOf: backupURL)
            guard let plist = try PropertyListSerialization.propertyList(
                from: data, options: [], format: nil) as? [String: Any],
                  let items = plist[soakPasteboardItemsKey] as? StoredPasteboardItems,
                  let owned = plist[soakPasteboardOwnedKey] as? Int,
                  let confirmed = plist[soakPasteboardConfirmedKey] as? Bool else {
                throw NSError(domain: "FastraSoakPasteboard", code: 1,
                              userInfo: [NSLocalizedDescriptionKey:
                                "Sicherungsdatei hat kein gültiges Format "
                                + "(\(soakPasteboardItemsKey)/\(soakPasteboardOwnedKey)/"
                                + "\(soakPasteboardConfirmedKey))"])
            }
            backup = SoakPasteboardBackup(items: items,
                                          ownedChangeCount: owned,
                                          mutationConfirmed: confirmed)
        }

        guard backup.mutationConfirmed else {
            throw NSError(
                domain: "FastraSoakPasteboard", code: 7,
                userInfo: [NSLocalizedDescriptionKey:
                    "vorbereitete Zwischenablage-Änderung wurde vor dem Abbruch "
                    + "nicht bestätigt; neuer Inhalt bleibt unangetastet und die "
                    + "private Sicherung wird aufbewahrt"]
            )
        }

        // Fremder, neuerer Inhalt bleibt stehen. Die Sicherung wird trotzdem
        // verworfen: Die Entscheidung ist endgültig, ein späterer Versuch
        // käme zum selben Ergebnis und die Datei bliebe ewig liegen.
        guard pasteboardIsStillOwned(since: backup.ownedChangeCount) else {
            soakPasteboardBackup = nil
            if fileManager.fileExists(atPath: backupURL.path) {
                try fileManager.removeItem(at: backupURL)
            }
            return .keptForeignContent
        }

        let preparedItems = try preparedPasteboardItems(backup.items)
        // `clearContents` erhöht den globalen Zähler genau einmal. Der
        // erwartete Stand muss vor dem Restore auf Platte stehen: Scheitert
        // danach `writeObjects`, kann derselbe oder ein frischer Prozess die
        // Sicherung weiterhin eindeutig als eigenen Schreibversuch erkennen.
        backup.ownedChangeCount &+= 1
        backup.mutationConfirmed = false
        try writeSoakPasteboardBackup(backup, to: backupURL)
        try writePreparedPasteboardItems(preparedItems)
        guard NSPasteboard.general.changeCount == backup.ownedChangeCount else {
            throw NSError(domain: "FastraSoakPasteboard", code: 8,
                          userInfo: [NSLocalizedDescriptionKey:
                            "Zwischenablage-Rückgabe änderte den Zähler unerwartet"])
        }
        backup.mutationConfirmed = true
        try writeSoakPasteboardBackup(backup, to: backupURL)
        soakPasteboardBackup = nil
        if fileManager.fileExists(atPath: backupURL.path) {
            try fileManager.removeItem(at: backupURL)
        }
        return .restored
    }

    /// Kleiner fensterloser Hilfsaufruf für `soak-test.sh`. Er wird nach einem
    /// harten Abbruch in einem frischen App-Prozess gestartet, damit AppKit die
    /// itemgetreue Sicherung zurückschreiben kann.
    @MainActor
    private static func runSoakPasteboardRestore() {
        testLabel = "soakpasteboardrestore"
        guard let directoryPath = UserDefaults.standard.string(forKey: "soakDir") else {
            finish(false, "soakDir muss übergeben werden")
        }
        let backupURL = URL(fileURLWithPath: directoryPath)
            .appendingPathComponent("pasteboard-backup.plist")
        do {
            switch try restoreSoakPasteboardIfPresent(from: backupURL) {
            case .restored:
                finish(true, "Zwischenablage itemgetreu wiederhergestellt")
            case .noBackup:
                finish(true, "keine liegengebliebene Zwischenablage-Sicherung")
            case .keptForeignContent:
                finish(true, "Zwischenablage inzwischen anderweitig beschrieben — "
                       + "neuerer Inhalt bleibt unangetastet")
            }
        } catch {
            finish(false, "Zwischenablage nicht wiederherstellbar: "
                   + error.localizedDescription)
        }
    }

    /// Der Dauertest teilt eine zufällig benannte Suite über drei App-Starts.
    /// Erst danach darf sie verschwinden. Der eigene Hilfsprozess macht das
    /// über dieselbe cfprefsd-saubere Routine wie die Unit-Tests.
    private static func runSoakDefaultsPurge() {
        testLabel = "soakdefaultspurge"
        guard let suiteName = ProcessInfo.processInfo.environment[
            "FASTRA_SELFTEST_DEFAULTS_SUITE"
        ], !suiteName.isEmpty else {
            finish(false, "FASTRA_SELFTEST_DEFAULTS_SUITE fehlt")
        }
        guard TestDefaultsPurge.register(suiteName) else {
            finish(false, "Test-Preferences-Suite ließ sich nicht beim Runner anmelden")
        }
        let remaining = TestDefaultsPurge.purgeRegistered(only: suiteName)
        guard remaining.isEmpty else {
            finish(false, "Test-Preferences-Suite blieb erhalten")
        }
        finish(true, "Test-Preferences-Suite entfernt")
    }

    /// Wartet, bis die erwartete Zahl Dokumentfenster wirklich steht.
    /// Ein Dauertest, der auf halb aufgebauten Fenstern losläuft, meldet
    /// Scheinbefunde.
    @MainActor
    private static func waitForSoakWindows(expected: Int, tick: Int,
                                           then body: @escaping @MainActor () -> Void) {
        if SoakTest.documentWindows().count >= expected {
            // Kurz nachlaufen lassen: Fenster stehen, Inhalte laden noch.
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                MainActor.assumeIsolated { body() }
            }
            return
        }
        if tick >= 200 {
            SoakTest.record("Fenster stehen nach dem Start",
                            "erwartet \(expected), tatsächlich "
                            + "\(SoakTest.documentWindows().count) nach 20 s")
            body()
            return
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
            MainActor.assumeIsolated {
                waitForSoakWindows(expected: expected, tick: tick + 1, then: body)
            }
        }
    }

    /// Führt die Runden mit Pausen aus — bewusst nicht in einer engen
    /// Schleife: Zwischen den Aktionen müssen Layout, Vorschau und
    /// Hintergrundarbeit tatsächlich laufen, sonst prüft der Test einen
    /// Zustand, den es im Betrieb nie gibt.
    @MainActor
    private static func runSoakRounds(rounds: Int, done: Int, logURL: URL,
                                      focusTick: Int = 0) {
        guard done < rounds else {
            // Der Selbsttest beendet über exit(), nicht über NSApp.terminate —
            // applicationShouldTerminate und damit das reguläre Sichern der
            // Sitzung laufen also nie. Damit die nächste Phase die Fenster
            // wiederfindet, hier ausdrücklich speichern. synchronize(),
            // weil exit() das Zurückschreiben an cfprefsd nicht abwartet.
            SessionRestorationCoordinator.captureCurrentSession(
                defaults: workspaceDefaults())
            workspaceDefaults().synchronize()
            // Fremden Clipboard-Inhalt wiederherstellen, bevor der Prozess
            // endet — der Dauertest hat ihn möglicherweise überschrieben.
            // Hat der Nutzer nach der letzten test-eigenen Kopie selbst etwas
            // kopiert, bleibt sein neuerer Inhalt stehen.
            let backupURL = soakPasteboardBackupURL(logURL: logURL)
            do {
                let outcome = try restoreSoakPasteboardIfPresent(from: backupURL)
                if outcome == .keptForeignContent {
                    SoakTest.note("Zwischenablage zeigte am Phasenende fremden, "
                                  + "neueren Inhalt — Sicherung bewusst nicht eingespielt")
                }
            } catch {
                SoakTest.record("Zwischenablage wird wiederhergestellt",
                                error.localizedDescription)
            }
            SoakTest.validateRoundCoverage()
            do {
                try SoakTest.appendReport(to: logURL)
            } catch {
                finish(false, "Dauertest-Protokoll konnte nicht gespeichert werden "
                    + "(\(SoakTest.findings.count) bisherige Befunde): "
                    + error.localizedDescription)
            }
            finish(SoakTest.phaseOutcome,
                   "Dauertest: \(SoakTest.completedRounds) Arbeitsrunden, "
                   + "\(SoakTest.findings.count) Invarianten-Verstöße, "
                   + "\(SoakTest.environmentIssues.count) Umgebungsprobleme "
                   + "— Protokoll: " + logURL.lastPathComponent)
        }
        // Aktivierung und Key-Window-Wechsel sind asynchron. Ein sofortiges
        // ⌘Z/⌘C/⌘V würde sonst gelegentlich noch an die vorherige App
        // beziehungsweise gar keinen Responder gehen. Das wäre ein Fehler des
        // Testtreibers: Ein echter Mausklick liefert seine Aktion erst nach dem
        // Fokuswechsel. Bis zu zwei Sekunden auf vollständigen Editoraufbau
        // und Fokus warten; ein Fenster allein genügt nicht als Aktionsziel.
        if let issue = SoakTest.prepareFrontWindowForAction() {
            if focusTick < 40 {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                    MainActor.assumeIsolated {
                        runSoakRounds(rounds: rounds, done: done, logURL: logURL,
                                      focusTick: focusTick + 1)
                    }
                }
            } else {
                SoakTest.recordPreparationIssue(issue)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                    MainActor.assumeIsolated {
                        runSoakRounds(rounds: rounds, done: done + 1,
                                      logURL: logURL)
                    }
                }
            }
            return
        }
        let pending = SoakTest.startRound()
        // Erst einen Runloop-Durchlauf setzen lassen, dann den tatsächlichen
        // View-Zustand abwarten: Unter Last braucht SwiftUI für den Abbau der
        // Vorschau gelegentlich mehrere Transaktionen. Eine starre 100-ms-
        // Annahme meldete dann den alten View-Baum als Produktfehler. Nach
        // höchstens zwei Sekunden prüft der Test trotzdem und meldet eine
        // wirklich hängen gebliebene Vorschau unverändert rot.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
            MainActor.assumeIsolated {
                finishSoakRoundWhenViewsSettled(
                    pending, rounds: rounds, done: done, logURL: logURL)
            }
        }
    }

    @MainActor
    private static func finishSoakRoundWhenViewsSettled(
        _ pending: SoakTest.PendingRound?,
        rounds: Int,
        done: Int,
        logURL: URL,
        tick: Int = 0
    ) {
        let bindings = SoakTest.unsettledEditorBindings()
        if (SoakTest.hasPreviewOnNonMarkdownTab() || !bindings.isEmpty), tick < 40 {
            if tick == 0, !bindings.isEmpty {
                SoakTest.note("Editoraufbau nach \(pending?.label ?? "Aktion") noch ausstehend: "
                              + bindings.joined(separator: "; "))
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                MainActor.assumeIsolated {
                    finishSoakRoundWhenViewsSettled(
                        pending, rounds: rounds, done: done,
                        logURL: logURL, tick: tick + 1)
                }
            }
            return
        }
        if tick > 0, bindings.isEmpty {
            SoakTest.note("Ansichten nach \(pending?.label ?? "Aktion") nach weiteren \(tick * 50) ms bereit")
        }
        if let pending { SoakTest.finishRound(pending) }
        // Nur eine nachweislich erfolgreiche ⌘C-Aktion darf Besitz
        // begründen. Bei jeder anderen Aktion könnte eine Änderung des
        // systemweiten Zählers vom Nutzer stammen.
        if let owned = pending?.pasteboardChangeCount,
           let expected = pending?.pasteboardExpectedString {
            noteSoakPasteboardOwnership(changeCount: owned,
                                         expectedString: expected)
        }
        // Die restliche Pause hält den Abstand zwischen Aktionen wie bisher.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
            MainActor.assumeIsolated {
                runSoakRounds(rounds: rounds, done: done + 1, logURL: logURL)
            }
        }
    }

    /// Gegenstück zu `dragscroll`: Drag innerhalb des sichtbaren Ausschnitts
    /// darf nicht scrollen. Mit Markdown-Vorschau prüfen, weil die Kopplung der
    /// Editorzeile eine zweite Scrollquelle einführt. Zusammen belegen beide
    /// Tests erforderliches Autoscroll außerhalb und Ruhe innerhalb des Viewports.
    private static func runDragNoScrollTest() {
        testLabel = "dragnoscroll"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks() else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        ws.sidebarWidth = 216.13671875
        ws.markdownPreviewWidth = 332.3515625
        workspaceDefaults().set(true, forKey: "markdown.integratedPreview")
        window.setContentSize(NSSize(width: 1100, height: 800))
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-dragnoscroll-\(UUID().uuidString)", isDirectory: true
            )
        let file = directory.appendingPathComponent("lang.md")
        let text = (1...800).map { "Zeile \($0) mit genug Text zum Markieren" }
            .joined(separator: "\n") + "\n"
        do {
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )
            try Data(text.utf8).write(to: file)
        }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: file) { ok in
            try? FileManager.default.removeItem(at: directory)
            guard ok else { finish(false, "Fixture lädt nicht") }
            waitForEditorShowing(
                window: window, text: "Zeile 400 ",
                onTimeout: { finish(false, "Editor zeigt den Inhalt nicht binnen 5 s") }
            ) { root, textView, _ in
                guard let scrollView = textView.enclosingScrollView else {
                    finish(false, "keine ScrollView am Editor")
                }
                // Die Vorschau muss wirklich stehen — sonst prüft der Test
                // eine Konstellation, die es beim Nutzer gar nicht gab.
                guard markdownWebView(in: root) != nil else {
                    finish(false, "Markdown-Vorschau nicht aufgebaut")
                }
                guard window.makeFirstResponder(textView) else {
                    finish(false, "Editor wird nicht First Responder")
                }
                textView.layoutManager.layoutLines()
                // In die Mitte des Dokuments scrollen, damit nach oben und
                // unten Platz zum (fälschlichen) Scrollen bleibt.
                scrollView.contentView.scroll(
                    to: NSPoint(x: 0, y: max(0, textView.frame.height / 2))
                )
                scrollView.reflectScrolledClipView(scrollView.contentView)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                    beginDragNoScroll(textView: textView, scrollView: scrollView,
                                      window: window)
                }
            }
        }
    }

    private static func beginDragNoScroll(
        textView: TextView, scrollView: NSScrollView, window: NSWindow
    ) {
        let visible = scrollView.documentVisibleRect
        // Startpunkt klar innerhalb: 120 Punkte unter der Oberkante des
        // sichtbaren Ausschnitts, waagerecht in der Textspalte.
        let startInView = NSPoint(x: visible.minX + 200, y: visible.minY + 120)
        let startInWindow = textView.convert(startInView, to: nil)
        let initialTop = visible.minY
        let time = ProcessInfo.processInfo.systemUptime
        guard let down = NSEvent.mouseEvent(
            with: .leftMouseDown, location: startInWindow, modifierFlags: [],
            timestamp: time, windowNumber: window.windowNumber, context: nil,
            eventNumber: Int(time * 1_000), clickCount: 1, pressure: 1
        ) else {
            finish(false, "Maus-Down nicht erzeugbar")
        }
        textView.mouseDown(with: down)
        continueDragNoScroll(
            textView: textView, scrollView: scrollView, window: window,
            startInView: startInView, initialTop: initialTop, step: 0
        )
    }

    /// Zieht die Maus schrittweise nach oben — jeder Schritt zwei Punkte,
    /// alle klar innerhalb des sichtbaren Ausschnitts.
    ///
    /// Die Bewegung ist wesentlich: Ein Drag, der immer wieder denselben Punkt
    /// meldet, ändert die Auswahl nur einmal. Der Fehler entsteht aber erst
    /// durch die fortlaufende Änderung — sie schreibt über SwiftUI eine
    /// jeweils veraltete Cursorposition zurück, und deren Anzeige zieht die
    /// Ansicht mit. Ein Test mit stehendem Zielpunkt übersieht das (erst so
    /// bemerkt: die erste Fassung dieses Tests bestand trotz des Fehlers).
    private static func continueDragNoScroll(
        textView: TextView, scrollView: NSScrollView, window: NSWindow,
        startInView: NSPoint, initialTop: CGFloat, step: Int
    ) {
        let maxSteps = 30
        // Nach oben wandern, aber nie über die Oberkante des Ausschnitts
        // hinaus: 30 Schritte à 2 Punkte = 60 Punkte, Startpunkt lag 120
        // Punkte darunter.
        let dragInView = NSPoint(x: startInView.x,
                                 y: startInView.y - CGFloat(step) * 2)
        let dragLocation = textView.convert(dragInView, to: nil)
        let time = ProcessInfo.processInfo.systemUptime
        if let drag = NSEvent.mouseEvent(
            with: .leftMouseDragged, location: dragLocation,
            modifierFlags: [], timestamp: time,
            windowNumber: window.windowNumber, context: nil,
            eventNumber: Int(time * 1_000) + step + 1, clickCount: 1,
            pressure: 1
        ) {
            NSApp.postEvent(drag, atStart: false)
        }
        if step < maxSteps {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.03) {
                continueDragNoScroll(
                    textView: textView, scrollView: scrollView, window: window,
                    startInView: startInView, initialTop: initialTop,
                    step: step + 1
                )
            }
            return
        }
        let upTime = ProcessInfo.processInfo.systemUptime
        if let up = NSEvent.mouseEvent(
            with: .leftMouseUp, location: dragLocation, modifierFlags: [],
            timestamp: upTime, windowNumber: window.windowNumber, context: nil,
            eventNumber: Int(upTime * 1_000) + 99, clickCount: 1, pressure: 0
        ) {
            NSApp.postEvent(up, atStart: false)
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
            let range = textView.selectedRange()
            let movedBy = abs(scrollView.documentVisibleRect.minY - initialTop)
            // Erst belegen, dass der Drag überhaupt ankam — sonst bestünde der
            // Test auch bei wirkungslosen Ereignissen.
            guard range.length > 0 else {
                finish(false, "Drag erzeugte keine Auswahl — Ereignisse kamen "
                    + "nicht an, der Test wäre wertlos")
            }
            // 1 Punkt Toleranz für Rundung im Layout.
            guard movedBy <= 1 else {
                finish(false, "Ansicht ist beim Markieren INNERHALB des "
                    + "Fensters um \(Int(movedBy)) Punkte gewandert "
                    + "(y=\(Int(initialTop)) → "
                    + "\(Int(scrollView.documentVisibleRect.minY)))")
            }
            finish(true, "Markieren innerhalb des Fensters bewegt die Ansicht "
                + "nicht (Auswahl \(range.length) Zeichen, y unverändert bei "
                + "\(Int(initialTop)))")
        }
    }

    private static func runDragScrollTest() {
        testLabel = "dragscroll"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks() else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        ws.sidebarWidth = 216.13671875
        ws.markdownPreviewWidth = 332.3515625
        workspaceDefaults().set(true, forKey: "markdown.integratedPreview")
        window.setContentSize(NSSize(width: 1100, height: 800))
        // Die kurze Umbruch-Fixture passt bei breitem Editor vollständig ins
        // Fenster. Mehr Text schafft einen echten Scrollbereich; beginDragScroll
        // prüft diese Vorbedingung zusätzlich an der tatsächlichen Geometrie.
        let text = String(repeating: rightEdgeFixtureContent(), count: 4)
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-dragscroll-\(UUID().uuidString)", isDirectory: true
            )
        let tmp = directory.appendingPathComponent("ziehen.md")
        do {
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )
            try Data(text.utf8).write(to: tmp)
        }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: directory)
            guard ok else { finish(false, "Markdown-Fixture lädt nicht") }
            pollDragScrollEditorReady(window: window, expectedText: text)
        }
    }

    private static func pollDragScrollEditorReady(
        window: NSWindow, expectedText: String
    ) {
        var found: (textView: TextView, scrollView: NSScrollView)?
        waitFor(budget: 10, pause: 0.1,
                condition: {
                    guard let root = window.contentView,
                          markdownWebView(in: root) != nil,
                          let textView = editorTextView(in: root) as? TextView,
                          textView.string == expectedText,
                          let scrollView = textView.enclosingScrollView else { return false }
                    found = (textView, scrollView)
                    return true
                },
                onTimeout: { book in
                    finish(false, "Markdown-Split mit Fixture nicht bereit — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Editor nach Erfolg verschwunden") }
                    guard window.makeFirstResponder(found.textView) else {
                        finish(false, "Editor wird nicht First Responder")
                    }
                    found.textView.layoutManager.layoutLines()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                        beginDragScroll(
                            textView: found.textView, scrollView: found.scrollView, window: window
                        )
                    }
                })
    }

    /// Startet den Drag mit einem echten Maus-Down im Text und zieht dann
    /// unter den unteren Fensterrand. Die Folgeereignisse laufen über die
    /// App-Eventqueue, damit `window.currentEvent` und der produktive
    /// Autoscroll-Timer genauso arbeiten wie bei einer physischen Maus.
    private static func beginDragScroll(
        textView: TextView, scrollView: NSScrollView, window: NSWindow
    ) {
        let visibleHeight = scrollView.documentVisibleRect.height
        guard textView.frame.height > visibleHeight else {
            finish(false, "Drag-Fixture ist nicht scrollbar "
                   + "(Text-Höhe=\(textView.frame.height), sichtbar=\(visibleHeight), "
                   + "Breite=\(textView.frame.width), Zeichen=\(textView.string.utf16.count))")
        }
        guard let startRect = textView.layoutManager.rectForOffset(10) else {
            finish(false, "Startzeichen ohne Rechteck")
        }
        // Bewusst die linke Zeichenhälfte: Die Caret-Rundung ist an der
        // Zeichenmitte mehrdeutig, der Anker soll eindeutig bei Offset 10
        // liegen.
        let startInWindow = textView.convert(
            NSPoint(x: startRect.minX + 1, y: startRect.midY), to: nil
        )
        let initialTop = scrollView.documentVisibleRect.minY
        let time = ProcessInfo.processInfo.systemUptime
        guard let down = NSEvent.mouseEvent(
            with: .leftMouseDown, location: startInWindow, modifierFlags: [],
            timestamp: time, windowNumber: window.windowNumber, context: nil,
            eventNumber: Int(time * 1_000), clickCount: 1, pressure: 1
        ) else {
            finish(false, "Maus-Down nicht erzeugbar")
        }
        textView.mouseDown(with: down)
        // Zielpunkt 40 Punkte unter dem Fenster (Fensterkoordinaten sind
        // unten-basiert, also negativ).
        let dragLocation = NSPoint(x: startInWindow.x, y: -40)
        continueDragScroll(
            textView: textView, scrollView: scrollView, window: window,
            dragLocation: dragLocation, initialTop: initialTop, step: 0
        )
    }

    private static func continueDragScroll(
        textView: TextView, scrollView: NSScrollView, window: NSWindow,
        dragLocation: NSPoint, initialTop: CGFloat, step: Int
    ) {
        let time = ProcessInfo.processInfo.systemUptime
        if let drag = NSEvent.mouseEvent(
            with: .leftMouseDragged, location: dragLocation,
            modifierFlags: [], timestamp: time,
            windowNumber: window.windowNumber, context: nil,
            eventNumber: Int(time * 1_000) + step + 1, clickCount: 1,
            pressure: 1
        ) {
            NSApp.postEvent(drag, atStart: false)
        }
        if step < 45 {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.03) {
                continueDragScroll(
                    textView: textView, scrollView: scrollView, window: window,
                    dragLocation: dragLocation, initialTop: initialTop,
                    step: step + 1
                )
            }
            return
        }
        let upTime = ProcessInfo.processInfo.systemUptime
        if let up = NSEvent.mouseEvent(
            with: .leftMouseUp, location: dragLocation, modifierFlags: [],
            timestamp: upTime, windowNumber: window.windowNumber, context: nil,
            eventNumber: Int(upTime * 1_000) + 99, clickCount: 1, pressure: 0
        ) {
            NSApp.postEvent(up, atStart: false)
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
            let range = textView.selectedRange()
            let visible = scrollView.documentVisibleRect
            guard range.length > 0 else {
                finish(false, "Drag erzeugte keine Auswahl")
            }
            // Der Anker muss am angeklickten Zeichen bleiben, auch wenn das
            // erste Drag-Ereignis bereits weit unterhalb des Fensters liegt.
            guard range.location == 10 else {
                finish(false, "Drag-Anker verrutscht: Auswahl beginnt bei "
                    + "\(range.location) statt am Klickpunkt 10")
            }
            guard visible.minY > initialTop else {
                finish(false, "Editor scrollte beim Drag über den unteren "
                    + "Rand nicht mit (Viewport weiter bei y=\(visible.minY), "
                    + "Auswahl \(range), App aktiv=\(NSApp.isActive), "
                    + "Fenster key=\(window.isKeyWindow))")
            }
            guard let edge = textView.layoutManager.rectForOffset(
                NSMaxRange(range)
            ), edge.minY <= visible.maxY + edge.height / 2 else {
                finish(false, "Auswahlkante liegt nach dem Drag unter dem "
                    + "Viewport (Auswahl \(range), Viewport \(visible))")
            }
            finish(true, "Drag-Autoscroll folgt: Viewport von "
                + "y=\(Int(initialTop)) auf y=\(Int(visible.minY)), "
                + "Auswahl \(range) mit sichtbarer Kante")
        }
    }

    // MARK: - -selftest dirtyundo

    /// Punkt im Tab über den echten Editorpfad: Einfügen macht dirty,
    /// Rückgängig auf den exakten Ladezustand macht wieder sauber, Redo
    /// wieder dirty, und manuelles Löschen der Einfügung (ohne Undo) räumt
    /// den Punkt ebenfalls ab.
    private static func runDirtyUndoTest() {
        testLabel = "dirtyundo"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks(),
              let root = window.contentView else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        let content = "Zeile 1\nZeile 2\nZeile 3\n"
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-dirtyundo-\(UUID().uuidString)", isDirectory: true
            )
        let tmp = directory.appendingPathComponent("punkt.md")
        do {
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )
            try Data(content.utf8).write(to: tmp)
        }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: directory)
            guard ok else { finish(false, "loadFile schlug fehl") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                guard let tv = editorTextView(in: root) as? TextView,
                      tv.string == content else {
                    finish(false, "Editor-TextView mit Fixture fehlt")
                }
                guard ws.activeTab?.isDirty == false else {
                    finish(false, "Tab ist direkt nach dem Laden dirty")
                }
                // Zwei Leerzeilen ans Ende anhängen.
                tv.selectionManager.setSelectedRange(NSRange(
                    location: (content as NSString).length, length: 0
                ))
                tv.insertText(
                    "\n\n",
                    replacementRange: NSRange(location: NSNotFound, length: 0)
                )
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                    guard ws.activeTab?.isDirty == true else {
                        finish(false, "Einfügen setzte den Punkt nicht")
                    }
                    tv.undoManager?.undo()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                        guard tv.string == content else {
                            finish(false, "Undo stellte den Ladezustand nicht her")
                        }
                        guard ws.activeTab?.isDirty == false else {
                            finish(false, "Punkt blieb trotz exakter Rücknahme "
                                + "per Undo bestehen")
                        }
                        tv.undoManager?.redo()
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                            guard ws.activeTab?.isDirty == true else {
                                finish(false, "Redo setzte den Punkt nicht erneut")
                            }
                            // Manuelles Löschen statt Undo: gleicher Inhalt,
                            // gleicher Anspruch.
                            let full = tv.string as NSString
                            tv.replaceCharacters(
                                in: NSRange(location: full.length - 2, length: 2),
                                with: ""
                            )
                            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                                guard tv.string == content else {
                                    finish(false, "manuelles Löschen stellte den "
                                        + "Inhalt nicht wieder her")
                                }
                                finish(ws.activeTab?.isDirty == false,
                                       ws.activeTab?.isDirty == false
                                       ? "Punkt folgt Laden→Einfügen→Undo→Redo→"
                                         + "manuellem Löschen korrekt"
                                       : "Punkt blieb nach manuellem Löschen "
                                         + "der Einfügung bestehen")
                            }
                        }
                    }
                }
            }
        }
    }

    // MARK: - -selftest typescroll

    private static func runTypeScrollTest() {
        testLabel = "typescroll"
        typeScrollTests.runTypeScrollTest()
    }

    /// Fensterinhalt als PNG aufnehmen. Bevorzugt `screencapture` (echte
    /// Bildschirm-Wahrheit); ohne Aufnahme-Berechtigung ersatzweise ein
    /// Render der aktuellen Layer-Backing-Stores — auch das zeigt veraltete
    /// Zeichnung, weil `CALayer.render(in:)` vorhandene Inhalte verwendet
    /// statt neu durch `draw(_:)` zu gehen.
    struct TypeScrollSnapshot {
        let data: Data
        // Bildrand in ungeflippten Fensterkoordinaten. Der Layer-Fallback
        // beginnt am Inhalt, screencapture am vollständigen Fensterrahmen.
        let windowRect: NSRect
        let source: String
    }

    private static func typeScrollCapture(window: NSWindow,
                                          completion: @escaping (TypeScrollSnapshot?) -> Void) {
        let frame = NSRect(origin: .zero, size: window.frame.size)
        let screenCaptureAllowed = CGPreflightScreenCaptureAccess()
        FileHandle.standardError.write(Data((
            "SELFTEST_CAPTURE preflight=\(screenCaptureAllowed) window=\(window.windowNumber)"
                + " visible=\(window.isVisible) key=\(window.isKeyWindow)\n"
        ).utf8))
        SelfTestCaptureRouting.capture(
            screenCaptureAllowed: screenCaptureAllowed,
            systemCapture: { callback in
                typeScrollSystemCapture(windowNumber: window.windowNumber) { data in
                    callback(data.map { TypeScrollSnapshot(data: $0, windowRect: frame, source: "screen") })
                }
            },
            fallback: {
                guard let view = window.contentView,
                      let data = typeScrollLayerSnapshot(window: window) else { return nil }
                return TypeScrollSnapshot(data: data,
                    windowRect: view.convert(view.bounds, to: nil), source: "layer")
            },
            completion: completion
        )
    }

    static func typeScrollPixelEvaluation(before: TypeScrollSnapshot,
                                          after: TypeScrollSnapshot,
                                          region: NSRect, excluded: [NSRect])
        -> (outcome: SelfTestOutcome, info: String) {
        SelfTestTypeScroll.typeScrollPixelEvaluation(before: before, after: after,
                                                     region: region, excluded: excluded)
    }

    private static func typeScrollSystemCapture(windowNumber: Int,
                                                completion: @escaping (Data?) -> Void) {
        let url = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-typescroll-\(UUID().uuidString).png")
        // Aufnahme und Datei-Lesen blockieren den Main-Thread nicht. Der
        // vorhandene Runner beendet auch einen SIGTERM ignorierenden Prozess.
        GitRunner.runExecutable(
            URL(fileURLWithPath: "/usr/sbin/screencapture"),
            arguments: ["-l\(windowNumber)", "-o", "-x", url.path],
            in: selfTestTemporaryDirectory(),
            outputLimit: GitOutputLimit(stdoutBytes: 1024, stderrBytes: 4096),
            policy: GitExecutionPolicy(timeout: 5, terminationGracePeriod: 0.5),
            completionQueue: .global(qos: .userInitiated)
        ) { outcome in
            defer { try? FileManager.default.removeItem(at: url) }
            let diagnostic: String
            switch outcome {
            case .completed(let result):
                diagnostic = "completed exit=\(result.exitCode) stderr=\(String(reflecting: result.stderrForDisplay))"
            case .startFailed(let failure):
                diagnostic = "startFailed reason=\(String(reflecting: failure))"
            case .cancelled:
                diagnostic = "cancelled"
            case .timedOut:
                diagnostic = "timedOut"
            case .captureFailed(let failure):
                diagnostic = "captureFailed exit=\(failure.partialResult.exitCode)"
                    + " stdoutError=\(String(reflecting: failure.stdoutError))"
                    + " stderrError=\(String(reflecting: failure.stderrError))"
                    + " stderr=\(String(reflecting: failure.partialResult.stderrForDisplay))"
            }
            FileHandle.standardError.write(Data((
                "SELFTEST_CAPTURE window=\(windowNumber) outcome=\(diagnostic)\n"
            ).utf8))
            let data: Data?
            if case .completed(let result) = outcome, result.ok {
                do {
                    data = try Data(contentsOf: url)
                } catch {
                    let readError = error as NSError
                    FileHandle.standardError.write(Data((
                        "SELFTEST_CAPTURE window=\(windowNumber) pngReadFailed"
                            + " domain=\(readError.domain) code=\(readError.code)"
                            + " reason=\(String(reflecting: readError.localizedDescription))\n"
                    ).utf8))
                    data = nil
                }
            } else {
                data = nil
            }
            // Layer-Fallback, Texteingabe und nächste Teststufe gehören auf Main.
            DispatchQueue.main.async { completion(data) }
        }
    }

    /// Ersatz-Aufnahme aus den CALayer-Backing-Stores des Fensterinhalts.
    private static func typeScrollLayerSnapshot(window: NSWindow) -> Data? {
        guard let view = window.contentView, let layer = view.layer else {
            return nil
        }
        let scale = window.backingScaleFactor
        let width = Int(view.bounds.width * scale)
        let height = Int(view.bounds.height * scale)
        guard width > 0, height > 0,
              let rep = NSBitmapImageRep(
                bitmapDataPlanes: nil, pixelsWide: width, pixelsHigh: height,
                bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true,
                isPlanar: false, colorSpaceName: .deviceRGB,
                bytesPerRow: 0, bitsPerPixel: 0
              ),
              let context = NSGraphicsContext(bitmapImageRep: rep) else {
            return nil
        }
        // CALayer zeichnet in einem nach oben wachsenden Koordinatensystem,
        // PNG-Zeilen werden hier aber von oben nach unten gelesen. Ohne die
        // Spiegelung wäre ein gespeichertes Diagnosebild auf dem Kopf.
        context.cgContext.translateBy(x: 0, y: CGFloat(height))
        context.cgContext.scaleBy(x: scale, y: -scale)
        layer.render(in: context.cgContext)
        return rep.representation(using: .png, properties: [:])
    }


    // MARK: - -selftest emojisplit

    /// Emojis (UTF-16-Surrogatpaare) dürfen im Editor nie in zwei sichtbare
    /// Zeichen zerfallen: weder durch Attributläufe des Highlighters noch
    /// durch Umbruchfragmente oder die Glyphen des Typesetters.
    private static func runEmojiSplitTest() {
        testLabel = "emojisplit"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks() else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        ws.sidebarWidth = 216.13671875
        ws.markdownPreviewWidth = 332.3515625
        workspaceDefaults().set(true, forKey: "markdown.integratedPreview")
        window.setContentSize(NSSize(width: 1100, height: 800))
        let text: String
        if let path = ProcessInfo.processInfo.environment["FASTRA_EMOJI_FIXTURE"],
           let fixture = try? String(contentsOfFile: path, encoding: .utf8) {
            // Reale Datei für die Erstdiagnose; der normale Lauf nutzt das
            // neutrale Abbild mit derselben Emoji-Konstellation.
            text = fixture
        } else {
            text = emojiSplitFixtureContent()
        }
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-emojisplit-\(UUID().uuidString)", isDirectory: true
            )
        let tmp = directory.appendingPathComponent("emoji.md")
        do {
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )
            try Data(text.utf8).write(to: tmp)
        }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: directory)
            guard ok else { finish(false, "Markdown-Fixture lädt nicht") }
            pollEmojiSplitEditorReady(window: window, expectedText: text)
        }
    }

    /// Neutrales Abbild der Repro-Datei: mehrere lange Zeilen, am Ende eine
    /// Zeile mit drei Emojis in Anführungszeichen, ohne abschließenden
    /// Zeilenumbruch — exakt die gemeldete Konstellation.
    private static func emojiSplitFixtureContent() -> String {
        var lines = (1...9).map { index in
            "- " + String(
                repeating: "xxxx xxxxxxx xxx ",
                count: 8 + index % 4
            )
        }
        lines.append(
            "- Xxxx: Xxxx Xxxxx Xxxxx Xxxxxxx: xxxxxxxxx Xxxx "
            + "xxxxxxxxxxxxx: \"XXXX XXXXX: Xxxxxx Xxx xxxx xxxx "
            + "xxxxxxxx xxxx 🎶🤮🎶\" - xx xxxxxxx? "
        )
        return lines.joined(separator: "\n")
    }

    private static func pollEmojiSplitEditorReady(
        window: NSWindow, expectedText: String
    ) {
        var textView: TextView?
        waitFor(budget: 10, pause: 0.1,
                condition: {
                    guard let root = window.contentView,
                          markdownWebView(in: root) != nil,
                          let candidate = editorTextView(in: root) as? TextView,
                          candidate.string == expectedText else { return false }
                    textView = candidate
                    return true
                },
                onTimeout: { book in
                    finish(false, "Markdown-Split mit Fixture nicht bereit — \(book.summary)")
                },
                then: {
                    guard let textView else { finish(false, "Editor nach Erfolg verschwunden") }
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                        analyzeEmojiClusters(textView: textView)
                    }
                })
    }

    /// Schiebt die Umbruchgrenze durch die Emoji-Zeile: Für jede Vorschau-
    /// Breite von 260 bis 500 Punkten in 2er-Schritten wird neu ausgelegt
    /// und erneut auf Surrogat-Zerfall geprüft.
    private static func sweepEmojiWidths(
        textView: TextView, width: Double, collected: [String]
    ) {
        guard width <= 500 else {
            finish(collected.isEmpty,
                   collected.isEmpty
                   ? "Emojis blieben über alle 121 Umbruchbreiten intakt"
                   : "Emoji zerfällt: "
                     + collected.prefix(8).joined(separator: " ;; ")
                     + " (insgesamt \(collected.count) Befunde)")
        }
        Workspace.shared?.markdownPreviewWidth = width
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
            textView.layoutManager.layoutLines()
            let problems = emojiClusterProblems(textView: textView)
                .map { "Breite \(Int(width)): \($0)" }
            sweepEmojiWidths(
                textView: textView, width: width + 2,
                collected: collected + problems
            )
        }
    }

    /// Prüft jedes Emoji-Vorkommen auf drei Zerfallsarten: Attributlauf-
    /// Grenze im Surrogatpaar, Fragmentgrenze im Surrogatpaar und Glyphen,
    /// die auf dem Trailing-Surrogat beginnen.
    private static func analyzeEmojiClusters(textView: TextView) {
        // Ans Dateiende scrollen, damit die Zielzeile real ausgelegt ist —
        // und dem asynchronen, viewport-getriebenen Highlighter danach Zeit
        // geben, seine Attributläufe wirklich anzuwenden.
        let ns = textView.string as NSString
        textView.scrollToRange(NSRange(location: ns.length, length: 0))
        textView.layoutManager.layoutLines()
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) {
            analyzeEmojiClustersAfterHighlight(textView: textView)
        }
    }

    private static func analyzeEmojiClustersAfterHighlight(textView: TextView) {
        textView.layoutManager.layoutLines()
        let initialProblems = emojiClusterProblems(textView: textView)
            .map { "Nutzergeometrie: \($0)" }
        sweepEmojiWidths(
            textView: textView, width: 260, collected: initialProblems
        )
    }

    /// Liefert alle gefundenen Zerfallsarten für sämtliche Emoji-Vorkommen
    /// im aktuellen Layoutzustand.
    private static func emojiClusterProblems(textView: TextView) -> [String] {
        let ns = textView.string as NSString
        var clusters: [NSRange] = []
        for emoji in ["🎶", "🤮"] {
            var search = NSRange(location: 0, length: ns.length)
            while true {
                let found = ns.range(of: emoji, options: [], range: search)
                guard found.location != NSNotFound else { break }
                clusters.append(found)
                let next = found.location + found.length
                search = NSRange(location: next, length: ns.length - next)
            }
        }
        guard clusters.count >= 3 else {
            return ["Fixture enthält nicht die erwarteten Emojis"]
        }
        var problems: [String] = []
        for cluster in clusters.sorted(by: { $0.location < $1.location }) {
            // 1) Attributläufe des Storages dürfen das Paar nicht teilen.
            var runRanges: [NSRange] = []
            textView.textStorage.enumerateAttributes(
                in: cluster, options: []
            ) { _, range, _ in runRanges.append(range) }
            if runRanges.count > 1 {
                problems.append("Attributlauf-Grenze in \(cluster): \(runRanges)")
            }
            // 2) Umbruchfragmente dürfen das Paar nicht teilen; 3) keine
            // Glyphe darf auf dem Trailing-Surrogat beginnen.
            guard let linePosition = textView.layoutManager.textLineForOffset(
                cluster.location
            ) else {
                problems.append("keine Layoutzeile für \(cluster)")
                continue
            }
            let lineStart = linePosition.range.location
            for fragmentPosition in linePosition.data.lineFragments {
                let fragmentRange = NSRange(
                    location: lineStart + fragmentPosition.range.location,
                    length: fragmentPosition.range.length
                )
                for boundary in [fragmentRange.location, fragmentRange.max]
                where boundary > cluster.location && boundary < cluster.max {
                    problems.append("Fragmentgrenze bei \(boundary) "
                        + "im Emoji \(cluster)")
                }
                guard fragmentRange.intersection(cluster)?.length ?? 0 > 0
                else { continue }
                for content in fragmentPosition.data.contents {
                    guard case .text(let ctLine) = content.data else { continue }
                    // CTLine-Indizes sind je nach Erzeugung zeilen- oder
                    // fragmentrelativ; der Stringbereich der Linie verrät die
                    // Basis.
                    let ctRange = CTLineGetStringRange(ctLine)
                    let base = ctRange.location
                        >= fragmentPosition.range.location
                        ? lineStart
                        : fragmentRange.location
                    let runs = CTLineGetGlyphRuns(ctLine)
                        as? [CTRun] ?? []
                    for run in runs {
                        let glyphCount = CTRunGetGlyphCount(run)
                        guard glyphCount > 0 else { continue }
                        var indices = [CFIndex](repeating: 0, count: glyphCount)
                        CTRunGetStringIndices(
                            run, CFRange(location: 0, length: glyphCount),
                            &indices
                        )
                        for index in indices {
                            let absolute = base + index
                            if absolute > cluster.location
                                && absolute < cluster.max {
                                problems.append("Glyphe beginnt mitten im "
                                    + "Emoji \(cluster) (Offset \(absolute))")
                            }
                        }
                    }
                }
            }
        }
        return problems
    }

    // MARK: - -selftest emojipaste

    /// Ein per ⌘V eingefügtes ⏸️ (U+23F8 U+FE0F) muss sofort als Farb-Emoji
    /// ausgelegt sein. Die getypesetteten Glyphen prüfen, nicht nur den korrekten
    /// Textspeicher; ein Tab-Wechsel darf zum Aktualisieren nicht nötig sein.
    private static func runEmojiPasteTest() {
        testLabel = "emojipaste"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks() else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-emojipaste-\(UUID().uuidString)", isDirectory: true
            )
        // Mit integrierter Vorschau prüfen.
        workspaceDefaults().set(true, forKey: "markdown.integratedPreview")
        window.setContentSize(NSSize(width: 1100, height: 800))
        let tmp = directory.appendingPathComponent("paste.md")
        // Lange Zeile: Bei aktivem Umbruch verschiebt jedes eingefügte Emoji
        // die Umbruchkante — genau die Konstellation, in der ein Cluster
        // zwischen zwei Umbruchfragmente geraten kann.
        let longLine = "Hier folgt das Symbol: "
            + String(repeating: "wort ", count: 40)
        let text = "Erste Zeile\n\(longLine)\nDritte Zeile\n"
        do {
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )
            try Data(text.utf8).write(to: tmp)
        }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: directory)
            guard ok else { finish(false, "Fixture lädt nicht") }
            if !ws.softWrapEnabled { ws.toggleSoftWrap() }
            waitForEditorShowing(
                window: window,
                text: "Dritte Zeile",
                onTimeout: {
                    finish(false, "Editor zeigt den Fixture-Text nicht binnen 5 s")
                }
            ) { _, textView, _ in
                guard textView.string == text else {
                    finish(false, "Editor zeigt den Fixture-Text nicht")
                }
                let start = (text as NSString).range(of: "Symbol: ").upperBound
                // Sweep über die zweite Zeile: Das Emoji wird nacheinander an
                // wachsenden Positionen eingefügt. Jedes bereits eingefügte
                // Emoji verschiebt die Umbruchkanten weiter — so wandert die
                // Kante durch die Einfügestellen.
                pasteEmojiStep(textView: textView, location: start, step: 0)
            }
        }
    }

    /// Ein Sweep-Schritt: Emoji per echtem Paste einfügen, auslegen lassen,
    /// Darstellung prüfen, dann weiter.
    private static func pasteEmojiStep(textView: TextView, location: Int, step: Int) {
        let maximumSteps = 12
        guard location <= (textView.string as NSString).length else {
            finish(false, "Einfügeposition liegt hinter dem Text")
        }
        textView.selectionManager.setSelectedRange(NSRange(location: location, length: 0))
        // Echter Paste-Weg über das Pasteboard. Die runnerweite, itemgetreue
        // Sicherung wird erst beim Testabschluss zurückgegeben und überlebt
        // auch einen App-Absturz.
        writeSelfTestPasteboardString("\u{23F8}\u{FE0F}")
        textView.paste(textView)

        // Highlighter und Auslegung einen Moment arbeiten lassen — genau in
        // diesem Fenster trat die falsche Darstellung auf.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) {
            let ns = textView.string as NSString
            let stored = NSRange(location: location, length: 2)
            guard stored.upperBound <= ns.length,
                  ns.substring(with: stored) == "\u{23F8}\u{FE0F}" else {
                finish(false, "Emoji-Sequenz U+23F8 U+FE0F steht nach dem Einfügen "
                    + "nicht an Position \(location) — Variantenselektor verloren")
            }
            textView.layoutManager.layoutLines()
            let problems = emojiPresentationProblems(textView: textView, range: stored)
            guard problems.isEmpty else {
                finish(false, "Emoji an Position \(location) (Schritt \(step)) falsch "
                    + "ausgelegt: " + problems.joined(separator: "; "))
            }
            // Zusätzlich echte Pixel prüfen: Ein Glyph-Run aus einer Emoji-
            // Schrift allein belegt noch keine farbige Darstellung.
            let drawing = emojiDrawingEvaluation(textView: textView, range: stored)
            guard drawing.outcome == .pass else {
                finish(drawing.outcome, "Emoji an Position \(location) (Schritt \(step)): "
                    + drawing.info)
            }
            if step >= maximumSteps {
                checkEmojiInPreview(stepCount: maximumSteps + 1)
                return
            }
            // Nächste Stelle ein Stück weiter rechts in derselben Zeile.
            pasteEmojiStep(textView: textView, location: location + 9, step: step + 1)
        }
    }

    /// Rendert den Emoji-Bereich und bewertet die tatsächlich erfassten Pixel.
    private static func emojiDrawingEvaluation(
        textView: TextView, range: NSRange
    ) -> (outcome: SelfTestOutcome, info: String) {
        guard let rect = textView.layoutManager.rectForOffset(range.location) else {
            return (.environment, "Pixelmessung nicht möglich: kein Zeichenrechteck")
        }
        // Etwas Luft um die Glyphzelle, damit das Emoji sicher drin liegt.
        let area = rect.insetBy(dx: -2, dy: -2)
        guard area.width > 1, area.height > 1,
              let bitmap = textView.bitmapImageRepForCachingDisplay(in: area) else {
            return emojiPixelEvaluation(bitmap: nil)
        }
        textView.cacheDisplay(in: area, to: bitmap)
        return emojiPixelEvaluation(bitmap: bitmap)
    }

    static func emojiPixelEvaluation(bitmap: NSBitmapImageRep?)
        -> (outcome: SelfTestOutcome, info: String) {
        guard let bitmap else { return (.environment, "Pixelmessung nicht möglich: keine Aufnahme") }
        var sawColor = false
        var visiblePixels = 0
        for x in 0..<bitmap.pixelsWide {
            for y in 0..<bitmap.pixelsHigh {
                guard let color = bitmap.colorAt(x: x, y: y)?
                    .usingColorSpace(.sRGB) else { continue }
                guard color.alphaComponent > 0.2 else { continue }
                visiblePixels += 1
                let red = color.redComponent, green = color.greenComponent
                let blue = color.blueComponent
                let spread = max(red, green, blue) - min(red, green, blue)
                // Grautöne (Text, Hintergrund) haben kaum Farbabstand.
                if spread > 0.15 { sawColor = true }
            }
        }
        guard visiblePixels > 0 else {
            return (.environment, "Pixelmessung nicht möglich: keine sichtbaren RGB-Pixel")
        }
        return sawColor ? (.pass, "farbige Pixel beobachtet")
            : (.fail, "gezeichneter Bereich ist einfarbig — "
                + "kein farbiges Emoji nachgewiesen")
    }

    /// Zweiter Teil des Tests: Die integrierte Markdown-Vorschau aktualisiert
    /// sich live über `document.body.innerHTML` statt neu zu laden. Auch dieser
    /// Weg muss den Variantenselektor behalten — sonst zeigte die Vorschau die
    /// schmale Textform, bis ein Tab-Wechsel sie neu aufbaut.
    private static func checkEmojiInPreview(stepCount: Int) {
        guard let window = mainWindowForAXChecks(),
              let root = window.contentView,
              let webView = markdownWebView(in: root) else {
            let result = emojiPreviewEvaluation(shown: nil, stepCount: stepCount)
            finish(result.passed, result.info)
        }
        // Der Vorschau Zeit für das Live-Update lassen.
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) {
            webView.evaluateJavaScript("document.body.innerText") { value, error in
                guard let shown = value as? String else {
                    finish(false, "Vorschau-Text nicht lesbar: "
                        + (error?.localizedDescription ?? "kein Wert"))
                }
                let result = emojiPreviewEvaluation(shown: shown, stepCount: stepCount)
                finish(result.passed, result.info)
            }
        }
    }

    static func emojiPreviewEvaluation(shown: String?, stepCount: Int) -> (passed: Bool, info: String) {
        guard let shown else {
            return (false, "Die für diesen Test eingeschaltete Markdown-Vorschau fehlt")
        }
        // Über die Skalare zählen: Swifts String-Suche vergleicht
        // Graphem-Cluster, ein nacktes U+23F8 würde in "⏸️" gar nicht
        // gefunden — genau der Unterschied, um den es hier geht.
        let scalars = Array(shown.unicodeScalars)
        var bare = 0
        var full = 0
        for (index, scalar) in scalars.enumerated() where scalar.value == 0x23F8 {
            bare += 1
            if index + 1 < scalars.count, scalars[index + 1].value == 0xFE0F {
                full += 1
            }
        }
        if bare == 0 {
            return (false, "Vorschau zeigt das eingefügte Symbol gar nicht")
        } else if full < bare {
            return (false, "Vorschau verliert den Variantenselektor: "
                + "\(bare) Basiszeichen, davon nur \(full) mit U+FE0F")
        } else if full != stepCount {
            return (false, "Vorschau enthält \(full) vollständige Emojis statt \(stepCount)")
        } else {
            return (true, "Eingefügtes ⏸️ bleibt in Editor (\(stepCount) Stellen, "
                + "auch an Umbruchkanten) und in der Live-Vorschau (\(full)×) "
                + "vollständig")
        }
    }

    /// Meldet, wenn die Emoji-Sequenz nicht als ein Glyph aus einer Emoji-
    /// Schrift gesetzt wird. Genau daran unterscheidet sich die schmale
    /// Textform (zwei Runs bzw. Monospace-Schrift) vom Farb-Emoji.
    private static func emojiPresentationProblems(
        textView: TextView, range: NSRange
    ) -> [String] {
        guard let line = textView.layoutManager.textLineForOffset(range.location) else {
            return ["Zeile zur Emoji-Position nicht auffindbar"]
        }
        var problems: [String] = []
        var covered = false
        for fragment in line.data.lineFragments {
            for content in fragment.data.contents {
                guard case .text(let ctLine) = content.data else { continue }
                // CTLine und CTRun zählen beide relativ zum Zeilen-Text (der
                // Typesetter wird pro logischer Zeile erzeugt) — deshalb nur
                // den Zeilenanfang addieren, nicht zusätzlich den Fragment-
                // Anfang.
                let lineStart = line.range.location
                for run in (CTLineGetGlyphRuns(ctLine) as? [CTRun]) ?? [] {
                    let runRange = CTRunGetStringRange(run)
                    let absolute = NSRange(
                        location: lineStart + runRange.location,
                        length: runRange.length
                    )
                    guard absolute.intersection(range) != nil else { continue }
                    covered = true
                    let attributes = CTRunGetAttributes(run) as NSDictionary
                    var fontName = "—"
                    if let raw = attributes[kCTFontAttributeName as String] {
                        fontName = CTFontCopyPostScriptName(raw as! CTFont) as String
                    }
                    let glyphs = CTRunGetGlyphCount(run)
                    if !fontName.contains("Emoji") {
                        problems.append(
                            "Run \(absolute) nutzt \(fontName) statt einer Emoji-Schrift"
                        )
                    } else if absolute.length == range.length && glyphs != 1 {
                        problems.append(
                            "Run \(absolute) liefert \(glyphs) Glyphen statt einem"
                        )
                    }
                }
            }
        }
        if !covered {
            problems.append("kein Glyph-Run deckt die Emoji-Position ab")
        }
        return problems
    }

    // MARK: - -selftest emojipreview

    /// Prüft die Präsentationsgrenze zwischen Editor und Vorschau. Ohne U+FE0F
    /// kann CoreText für `⏸` auf Apple Color Emoji zurückfallen, während WebKit
    /// vor der Schriftwahl die Textpräsentation bestimmt. Fastra verändert die
    /// Quelldaten dabei nicht.
    /// Vier WebView-Fälle nach Pixel-Farbe prüfen: Basiszeichen und vollständige
    /// Emoji-Sequenz, jeweils als Inline-Code und Fließtext. Eine Emoji-Schrift
    /// allein darf die Textform nicht ändern; globales `font-variant-emoji` würde
    /// auch Pfeile und Häkchen verändern.
    private static func runEmojiPreviewTest() {
        testLabel = "emojipreview"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks() else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        workspaceDefaults().set(true, forKey: "markdown.integratedPreview")
        window.setContentSize(NSSize(width: 1100, height: 800))
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-emojipreview-\(UUID().uuidString)", isDirectory: true
            )
        let tmp = directory.appendingPathComponent("preview.md")
        // Erste Zeile: Basiszeichen als Inline-Code. Zweite Zeile: vollständige
        // Emoji-Sequenz als Kontrollfall.
        let text = "Code nackt `\u{23F8}` Ende\n\nCode voll `\u{23F8}\u{FE0F}` Ende\n\n"
            + "Fließtext nackt **\u{23F8}** Ende\n\nFließtext voll *\u{23F8}\u{FE0F}* Ende\n"
        do {
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )
            try Data(text.utf8).write(to: tmp)
        }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: directory)
            guard ok else { finish(false, "Fixture lädt nicht") }
            pollEmojiPreviewReady(window: window)
        }
    }

    private static func pollEmojiPreviewReady(window: NSWindow) {
        var webView: WKWebView?
        waitFor(budget: 10, pause: 0.1,
                condition: {
                    webView = window.contentView.flatMap { markdownWebView(in: $0) }
                    return webView != nil
                },
                onTimeout: { book in finish(false, "Vorschau nicht bereit — \(book.summary)") },
                then: {
                    guard let webView else { finish(false, "Vorschau nach Erfolg verschwunden") }
                    DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                        measureEmojiPreviewColors(
                            webView: webView,
                            pending: [
                                ("code-nackt", "document.querySelectorAll('code')[0]"),
                                ("code-voll", "document.querySelectorAll('code')[1]"),
                                ("text-nackt", "document.querySelector('strong')"),
                                ("text-voll", "document.querySelector('em')")
                            ],
                            results: []
                        )
                    }
                })
    }

    /// Fotografiert je Fall das Element und meldet, ob es farbig ist.
    private static func measureEmojiPreviewColors(
        webView: WKWebView, pending: [(String, String)],
        results: [(label: String, coloredPixels: Int)]
    ) {
        guard let (label, expression) = pending.first else {
            let details = results.map {
                "\($0.label): \($0.coloredPixels > 0 ? "farbig (\($0.coloredPixels) Pixel)" : "einfarbig")"
            }.joined(separator: "; ")
            let full = results.filter { $0.label.hasSuffix("voll") }
            let bare = results.filter { $0.label.hasSuffix("nackt") }
            // Mit Variantenselektor muss die Vorschau farbig zeichnen.
            if full.contains(where: { $0.coloredPixels == 0 }) {
                finish(false, "⏸️ mit U+FE0F wird in der Vorschau nicht farbig "
                    + "gezeichnet: \(details)")
            } else if bare.contains(where: { $0.coloredPixels > 0 }) {
                // Gegenrichtung: Würde die Vorschau auch das nackte Zeichen
                // farbig zeichnen (etwa durch ein global gesetztes
                // `font-variant-emoji: emoji`), kippten auch Pfeile und Häkchen
                // in Emoji-Form. Das wäre eine Produktentscheidung, keine
                // Nebenwirkung — deshalb schlägt der Wächter hier bewusst an.
                finish(false, "Vorschau zeichnet auch das NACKTE ⏸ farbig — "
                    + "Emoji-Präsentation wurde erzwungen: \(details)")
            } else {
                finish(true, "Vorschau folgt Unicode: ⏸️ (mit U+FE0F) farbig, "
                    + "nacktes ⏸ als Textform — anders als der Editor daneben, "
                    + "der über CoreTexts Schriftrückfall ein Farb-Emoji zeigt: "
                    + "\(details)")
            }
        }
        let script = """
        (function(){
          const el = \(expression);
          if (!el) return null;
          const r = el.getBoundingClientRect();
          return [r.left + window.scrollX, r.top + window.scrollY, r.width, r.height];
        })()
        """
        webView.evaluateJavaScript(script) { value, _ in
            guard let numbers = value as? [Double], numbers.count == 4 else {
                finish(false, "Element \(label) in der Vorschau nicht gefunden")
            }
            let rect = CGRect(x: numbers[0], y: numbers[1],
                              width: max(numbers[2], 1), height: max(numbers[3], 1))
            let configuration = WKSnapshotConfiguration()
            configuration.rect = rect
            webView.takeSnapshot(with: configuration) { image, error in
                guard let image, let bitmap = NSBitmapImageRep(data: image.tiffRepresentation ?? Data()) else {
                    finish(false, "Snapshot für \(label) fehlgeschlagen: "
                        + (error?.localizedDescription ?? "kein Bild"))
                }
                var colored = 0
                for x in 0..<bitmap.pixelsWide {
                    for y in 0..<bitmap.pixelsHigh {
                        guard let color = bitmap.colorAt(x: x, y: y)?
                            .usingColorSpace(.sRGB) else { continue }
                        let spread = max(color.redComponent, color.greenComponent,
                                         color.blueComponent)
                            - min(color.redComponent, color.greenComponent,
                                  color.blueComponent)
                        if spread > 0.15 { colored += 1 }
                    }
                }
                measureEmojiPreviewColors(
                    webView: webView,
                    pending: Array(pending.dropFirst()),
                    results: results + [(label: label, coloredPixels: colored)]
                )
            }
        }
    }

    // MARK: - -selftest tabscroll

    /// Der sichtbare Ausschnitt muss den Tab-Wechsel überleben. CESEs bloßes
    /// Sichtbarmachen der Einfügemarke ersetzt nicht die Wiederherstellung des
    /// vorherigen Viewports.
    private static func runTabScrollTest() {
        testLabel = "tabscroll"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks() else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        window.setContentSize(NSSize(width: 1000, height: 600))
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-tabscroll-\(UUID().uuidString)", isDirectory: true
            )
        let longFile = directory.appendingPathComponent("lang.txt")
        let shortFile = directory.appendingPathComponent("kurz.txt")
        let longText = (1...600).map { "Zeile \($0) mit etwas Text" }
            .joined(separator: "\n") + "\n"
        do {
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )
            try Data(longText.utf8).write(to: longFile)
            try Data("Kurze Datei\n".utf8).write(to: shortFile)
        }
        catch { finish(false, "Temp-Dateien nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: longFile) { ok in
            guard ok else {
                try? FileManager.default.removeItem(at: directory)
                finish(false, "lange Datei lädt nicht")
            }
            guard let longTabID = ws.activeTabID else {
                try? FileManager.default.removeItem(at: directory)
                finish(false, "kein aktiver Tab für die lange Datei")
            }
            // Cursor in die Mitte des Dokuments und dorthin scrollen — erst,
            // wenn der Editor den Inhalt der langen Datei wirklich zeigt.
            waitForEditorShowing(
                window: window, text: "Zeile 300 ",
                onTimeout: {
                    try? FileManager.default.removeItem(at: directory)
                    finish(false, "Editor zeigt den Inhalt der langen Datei "
                        + "nicht binnen 5 s")
                }
            ) { root, textView, middle in
                textView.selectionManager.setSelectedRange(
                    NSRange(location: middle.location, length: 0)
                )
                textView.scrollToRange(NSRange(location: middle.location, length: 0))
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                    guard let clipView = textView.enclosingScrollView?.contentView else {
                        try? FileManager.default.removeItem(at: directory)
                        finish(false, "keine ScrollView am Editor")
                    }
                    let expected = clipView.bounds.origin.y
                    guard expected > 100 else {
                        try? FileManager.default.removeItem(at: directory)
                        finish(false, "Ausgangsposition nicht gescrollt (y=\(expected))")
                    }
                    // Zweite Datei öffnen (wechselt den Tab) …
                    ws.loadFile(at: shortFile) { ok2 in
                        try? FileManager.default.removeItem(at: directory)
                        guard ok2 else { finish(false, "kurze Datei lädt nicht") }
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.7) {
                            // … und zurückwechseln.
                            ws.selectTab(id: longTabID)
                            DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) {
                                guard let tv = editorTextView(in: root) as? TextView,
                                      let clip = tv.enclosingScrollView?.contentView else {
                                    finish(false, "Editor nach dem Rückwechsel nicht auffindbar")
                                }
                                let actual = clip.bounds.origin.y
                                let delta = abs(actual - expected)
                                if delta <= 4 {
                                    finish(true, "Ausschnitt überlebt den Tab-Wechsel "
                                        + "(y=\(Int(actual)) statt Sprung auf die Cursorzeile)")
                                } else {
                                    finish(false, "Scrollposition geändert: erwartet y≈"
                                        + "\(Int(expected)), tatsächlich \(Int(actual))")
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /// Wiederholte Mauswechsel dürfen weder Treffer-Auswahl noch Ausschnitt
    /// verändern. Beide Dokumente bleiben während der ganzen Folge geöffnet.
    private static func runTabSearchMemoryTest() {
        testLabel = "tabsearchmemory"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks(), let root = window.contentView else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        window.setContentSize(NSSize(width: 1100, height: 650))
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-tabsearch-\(UUID().uuidString)")
        tabSearchFixtureDirectory = directory
        let needle = "Beispielkontakt"
        let contents = [360, 780].map { line in
            (1...1200).map { index in
                "<contact id=\"\(index)\"><name>\(index == line ? needle : "Kontakt \(index)")</name></contact>"
            }.joined(separator: "\n")
        }
        var ids: [UUID] = []
        var selections: [NSRange] = []
        var offsets: [CGFloat] = []
        var restoreTrace: [String] = []
        let diagnostics = ws.scrollRestoreDiagnostics
        diagnostics.observer = { message in
            restoreTrace.append(message)
            if restoreTrace.count > 200 { restoreTrace.removeFirst() }
        }
        func done(_ ok: Bool, _ message: String) -> Never {
            diagnostics.observer = nil
            if !ok {
                FileHandle.standardError.write(Data((restoreTrace.joined(separator: "\n") + "\n").utf8))
            }
            try? FileManager.default.removeItem(at: directory)
            tabSearchFixtureDirectory = nil
            finish(ok, message)
        }
        func cycle(_ step: Int) {
            guard step < 48 else {
                done(true, "48 Mauswechsel erhalten beide Suchauswahlen und Ausschnitte")
            }
            let index = step % 2
            scrollTabIntoView(id: ids[index], in: root)
            guard let marker = markerView(id: "documentTab-idle-\(ids[index].uuidString)", in: root),
                  let strip = marker.enclosingScrollView else {
                done(false, "Tab-Marker fehlt bei Wechsel \(step)")
            }
            let point = marker.convert(NSPoint.zero, to: nil)
            guard strip.contentView.convert(strip.contentView.bounds, to: nil).contains(point),
                  sendMouseClick(at: point, in: window, modifiers: []) else {
                done(false, "Tab-Klick nicht ausführbar")
            }
            // Der Neuaufbau und die begrenzte Scroll-Wiederherstellung sind
            // asynchron. Erst ihren Endzustand beobachten, dann zusätzlich
            // prüfen, dass spätere Rückmeldungen ihn nicht wieder verlieren.
            var observed = "Editor nicht bereit"
            waitFor(budget: 3, pause: 0.05, condition: {
                guard ws.activeTabID == ids[index],
                      let tv = editorTextView(in: root) as? TextView,
                      tv.string == contents[index],
                      let clip = tv.enclosingScrollView?.contentView else { return false }
                let selected = tv.selectionManager.textSelections.map(\.range)
                let y = clip.bounds.origin.y
                observed = "Auswahl \(selected) statt \(selections[index]); y=\(Int(y)) statt \(Int(offsets[index]))"
                return selected == [selections[index]] && abs(y - offsets[index]) <= 4
            }, onTimeout: { book in
                done(false, "Wechsel \(step + 1), Tab \(index): \(observed) — \(book.summary)")
            }, then: {
                let observeUntil = ProcessInfo.processInfo.systemUptime + (step < 12 ? 0.5 : 0.15)
                waitFor(budget: 2, pause: 0.05, condition: {
                    guard let tv = editorTextView(in: root) as? TextView,
                          ws.activeTabID == ids[index], tv.string == contents[index],
                          let clip = tv.enclosingScrollView?.contentView else {
                        done(false, "Dokument nach Wechsel \(step + 1) verloren")
                    }
                    let selected = tv.selectionManager.textSelections.map(\.range)
                    let y = clip.bounds.origin.y
                    guard selected == [selections[index]], abs(y - offsets[index]) <= 4 else {
                        done(false, "Nachlauf von Wechsel \(step + 1), Tab \(index): Auswahl \(selected); y=\(Int(y)) statt \(Int(offsets[index]))")
                    }
                    return ProcessInfo.processInfo.systemUptime >= observeUntil
                }, onTimeout: { book in
                    done(false, "Nachbeobachtung nicht abgeschlossen — \(book.summary)")
                }, then: { cycle(step + 1) })
            })
        }
        func prepare(_ index: Int) {
            guard index < 2 else { cycle(0); return }
            let file = directory.appendingPathComponent("Kontakte \(index).vcf.xml")
            do {
                try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
                try contents[index].write(to: file, atomically: true, encoding: .utf8)
            } catch { done(false, "Fixture nicht schreibbar") }
            ws.loadFile(at: file) { ok in
                guard ok, let id = ws.activeTabID else { done(false, "Fixture lädt nicht") }
                ids.append(id)
                pollForJumpEditor(root: root, expectedContent: contents[index], label: "Tab \(index)") { tv in
                    _ = window.makeFirstResponder(tv)
                    let result = BufferSearch.find(in: contents[index], options: SearchOptions(
                        find: needle, replace: "", isRegex: false, caseSensitive: true))
                    guard let match = result.matches.first else { done(false, "Suchtreffer fehlt") }
                    // Wie nach einem Klick in die frisch geöffnete Datei:
                    // Der Fokus-Helfer muss den initialen Cursor gesetzt haben.
                    waitFor(budget: 2, pause: 0.05, condition: {
                        guard let current = editorTextView(in: root) as? TextView,
                              current.string == contents[index] else { return false }
                        return !current.selectionManager.textSelections.isEmpty
                    }, onTimeout: { book in
                        done(false, "Editor ohne initialen Cursor — \(book.summary)")
                    }, then: {
                        NotificationCenter.default.postMatchJump(match, for: ws)
                        let expected = (contents[index] as NSString).range(of: needle)
                        var lastY: CGFloat?
                        var stableTicks = 0
                        var observed = "Editor fehlt"
                        waitFor(budget: 5, pause: 0.1, condition: {
                            guard let current = editorTextView(in: root) as? TextView,
                                  current.string == contents[index],
                                  let clip = current.enclosingScrollView?.contentView else {
                                return false
                            }
                            let ranges = current.selectionManager.textSelections.map(\.range)
                            let y = clip.bounds.origin.y
                            observed = "Tab \(index): Auswahl \(ranges), y=\(Int(y))"
                            let ready = ranges == [expected] && y > 100
                            stableTicks = ready && lastY.map { abs($0 - y) < 1 } == true
                                ? stableTicks + 1 : 0
                            lastY = y
                            return stableTicks >= 3
                        }, onTimeout: { book in
                            done(false, "Suchsprung nicht bereit: \(observed) — \(book.summary)")
                        }, then: {
                            guard let y = lastY else { done(false, "Ausschnitt fehlt") }
                            selections.append(expected)
                            offsets.append(y)
                            prepare(index + 1)
                        })
                    })
                }
            }
        }
        prepare(0)
    }

