    // MARK: - -selftest comment4d

    /// Ein Edit innerhalb eines langen `/* … */`-Blocks darf die
    /// Kommentarfarbe hinter der Editposition nicht löschen. CESE färbt nach
    /// einem Edit chunkweise ab der Editposition neu; der 4D-Provider muss
    /// seine Token deshalb auf den angefragten Chunk zuschneiden.
    private static func runFourDCommentEditTest() {
        testLabel = "comment4d"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks(),
              let root = window.contentView else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        var lines = ["// Kopfzeile", "/* Modernisierung"]
        lines.append("- Ankerzeile für den Edit xx")
        lines.append(contentsOf: (1...24).map {
            "- Punkt \($0): " + String(repeating: "x", count: 40 + $0 % 7)
        })
        lines.append("- Schlusszeile QQZWEIQQ")
        lines.append("*/")
        lines.append("ALERT(\"ok\")")
        let code = lines.joined(separator: "\n")
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent(
                "fastra-comment4d-\(UUID().uuidString)", isDirectory: true
            )
        let tmp = directory.appendingPathComponent("Kommentar.4dm")
        do {
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )
            try Data(code.utf8).write(to: tmp)
        }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }
        // Fester Hellmodus wie im highlight4d-Test: erwartete Farben sind
        // Fixture-Werte, kein Systemzustand.
        NSApp.appearance = NSAppearance(named: .aqua)
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: directory)
            guard ok else { finish(false, "loadFile (.4dm) schlug fehl") }
            pollFourDCommentInitialColor(root: root, code: code)
        }
    }

    private static func pollFourDCommentInitialColor(
        root: NSView, code: String
    ) {
        let comment = fourDExpectedColors(dark: false)[7]
        var textView: TextView?
        waitFor(budget: 15, pause: 0.25,
                condition: {
                    guard let candidate = editorTextView(in: root) as? TextView,
                          candidate.string == code else { return false }
                    if storageSubstringHasColor("QQZWEIQQ", in: root,
                                                r: comment.1, g: comment.2, b: comment.3) {
                        textView = candidate
                        return true
                    }
                    // CESE hebt abschnittsweise den sichtbaren Bereich hervor. Die
                    // geprüfte Schlusszeile deshalb zuerst wirklich sichtbar machen;
                    // eine bestimmte gespeicherte Fensterhöhe darf den Test nicht
                    // entscheiden. Nach dem Edit weiter oben muss ihre Farbe bleiben.
                    candidate.scrollToRange((code as NSString).range(of: "QQZWEIQQ"))
                    candidate.layoutManager.layoutLines()
                    return false
                },
                onTimeout: { book in
                    NSApp.appearance = nil
                    finish(false, "Kommentarfarbe erscheint initial nicht — \(book.summary)")
                },
                then: {
                    guard let textView else { finish(false, "Editor nach Erfolg verschwunden") }
                    // Edit am Ende der Ankerzeile mitten im Kommentarblock.
                    let anchor = (code as NSString).range(of: "- Ankerzeile für den Edit xx")
                    textView.selectionManager.setSelectedRange(
                        NSRange(location: anchor.max, length: 0)
                    )
                    textView.insertText(
                        "yy", replacementRange: NSRange(location: NSNotFound, length: 0)
                    )
                    DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                        pollFourDCommentColorAfterEdit(root: root)
                    }
                })
    }

    private static func pollFourDCommentColorAfterEdit(root: NSView) {
        let comment = fourDExpectedColors(dark: false)[7]
        let commandColor = fourDExpectedColors(dark: false)[0]
        var closingKept = false
        var commandKept = false
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    closingKept = storageSubstringHasColor(
                        "QQZWEIQQ", in: root, r: comment.1, g: comment.2, b: comment.3
                    )
                    commandKept = storageSubstringHasColor(
                        "ALERT", in: root,
                        r: commandColor.1, g: commandColor.2, b: commandColor.3
                    )
                    return closingKept && commandKept
                },
                onTimeout: { book in
                    NSApp.appearance = nil
                    finish(false, "nach dem Edit im Kommentarblock: Schlusszeile "
                        + "kommentarfarben=\(closingKept), ALERT befehlsfarben=\(commandKept) — \(book.summary)")
                },
                then: {
                    NSApp.appearance = nil
                    finish(true, "Kommentarfarbe bleibt nach Edit im Block bis zum "
                        + "Blockende erhalten")
                })
    }

    // MARK: - -selftest sighelp4d

    /// End-to-End-Prüfung der 4D-Parameterhilfe: Cursor in die Klammern eines
    /// Projektmethoden-Aufrufs setzen → Panel mit Signatur und Kommentarkopf
    /// erscheint; Cursor an den Zeilenanfang → Panel verschwindet.
    private static func runFourDSignatureHelpTest() {
        testLabel = "sighelp4d"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks(),
              let root = window.contentView else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        let projectRoot = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-sighelp4d-\(UUID().uuidString)")
        let methods = projectRoot.appendingPathComponent(
            "Project/Sources/Methods", isDirectory: true
        )
        let target = methods.appendingPathComponent("Begruessung.4dm")
        let outer = methods.appendingPathComponent("Verpacke.4dm")
        let inner = methods.appendingPathComponent("InnereFormel.4dm")
        let caller = methods.appendingPathComponent("Aufrufer.4dm")
        let targetSource = """
        //%attributes = {}
        // Baut die Grußformel.
        // Zweite Kopfzeile mit Details.
        #DECLARE($name_t : Text; $anzahl_i : Integer)->$gruss_t : Text
        $gruss_t:="Hallo "+$name_t
        """
        let outerSource = """
        //%attributes = {}
        // Verpackt einen Text.
        #DECLARE($inhalt_t : Text; $breite_i : Integer)->$paket_t : Text
        $paket_t:="["+$inhalt_t+"]"
        """
        // Die innere Stufe braucht eine andere Signatur als der erste
        // Aufruf: Ein unverändertes altes Panel darf sie nicht bestätigen.
        let innerSource = """
        // Berechnet die innere Formel.
        #DECLARE($eingabe_t : Text; $faktor_i : Integer)->$ergebnis_t : Text
        $ergebnis_t:=$eingabe_t
        """
        // Geteilte Methode einer entpackten Komponente — sie muss in der
        // Parameterhilfe genauso funktionieren wie eine Projektmethode.
        let componentMethods = projectRoot.appendingPathComponent(
            "Components/Werkzeug.4dbase/Project/Sources/Methods", isDirectory: true
        )
        let componentTarget = componentMethods.appendingPathComponent("Werkzeug_Miss.4dm")
        let componentSource = """
        //%attributes = {"shared":true}
        // Misst einen Text.
        #DECLARE($text_t : Text)->$laenge_i : Integer
        $laenge_i:=Length($text_t)
        """
        // Zeile 2: einfacher Aufruf. Zeile 3: verschachtelter Aufruf — die
        // innere Methode ist Argument der äußeren. Zeile 4: Komponente.
        let callerSource = """
        // Aufrufer
        Begruessung("Welt";2)
        Verpacke(InnereFormel("Du";1);80)
        Werkzeug_Miss("Probe")
        """
        do {
            try FileManager.default.createDirectory(
                at: methods, withIntermediateDirectories: true
            )
            try FileManager.default.createDirectory(
                at: componentMethods, withIntermediateDirectories: true
            )
            try targetSource.write(to: target, atomically: true, encoding: .utf8)
            try outerSource.write(to: outer, atomically: true, encoding: .utf8)
            try innerSource.write(to: inner, atomically: true, encoding: .utf8)
            try componentSource.write(to: componentTarget, atomically: true,
                                      encoding: .utf8)
            try callerSource.write(to: caller, atomically: true, encoding: .utf8)
        } catch {
            try? FileManager.default.removeItem(at: projectRoot)
            finish(false, "4D-Fixture nicht schreibbar: \(error.localizedDescription)")
        }
        ws.openProject(at: projectRoot)
        pollFourDSignatureIndexReady(
            ws: ws, root: root, window: window,
            projectRoot: projectRoot, caller: caller)
    }

    private static func pollFourDSignatureIndexReady(
        ws: Workspace, root: NSView, window: NSWindow,
        projectRoot: URL, caller: URL
    ) {
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    ws.fourDProjectMethodNames.contains("begruessung")
                        && ws.fourDProjectMethodNames.contains("verpacke")
                        && ws.fourDProjectMethodNames.contains("innereformel")
                        && ws.fourDComponentMethods["werkzeug_miss"] != nil
                },
                onTimeout: { book in
                    ws.closeProject()
                    try? FileManager.default.removeItem(at: projectRoot)
                    finish(false, "Projekt-/Komponentenindex ist unvollständig — \(book.summary)")
                },
                then: {
                    ws.loadFile(at: caller) { ok in
                        guard ok else {
                            ws.closeProject()
                            try? FileManager.default.removeItem(at: projectRoot)
                            finish(false, "Aufrufer.4dm lädt nicht")
                        }
                        DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                            guard let textView = editorTextView(in: root) as? TextView else {
                                ws.closeProject()
                                try? FileManager.default.removeItem(at: projectRoot)
                                finish(false, "Editor-TextView fehlt")
                            }
                            window.makeFirstResponder(textView)
                            // Cursor hinter das erste Argument: innerhalb der Klammern.
                            let ns = textView.string as NSString
                            let anchor = ns.range(of: "\"Welt\"")
                            guard anchor.location != NSNotFound else {
                                ws.closeProject()
                                try? FileManager.default.removeItem(at: projectRoot)
                                finish(false, "Aufrufzeile fehlt im Editor")
                            }
                            textView.selectionManager.setSelectedRange(
                                NSRange(location: anchor.max, length: 0)
                            )
                            pollFourDSignaturePanelVisible(
                                ws: ws, window: window, textView: textView,
                                projectRoot: projectRoot)
                        }
                    }
                })
    }

    private static func fourDSignaturePanelText(window: NSWindow) -> String? {
        for child in window.childWindows ?? [] {
            guard child.isVisible, child.styleMask.contains(.borderless),
                  let content = child.contentView else { continue }
            for view in content.subviews {
                if let label = view as? NSTextField {
                    return label.attributedStringValue.string
                }
            }
        }
        return nil
    }

    private static func pollFourDSignaturePanelVisible(
        ws: Workspace, window: NSWindow, textView: TextView,
        projectRoot: URL
    ) {
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard let text = fourDSignaturePanelText(window: window) else { return false }
                    return text.contains("Begruessung")
                        && text.contains("$name_t : Text")
                        && text.contains("$anzahl_i : Integer")
                        && text.contains("$gruss_t : Text")
                        && text.contains("Baut die Grußformel.")
                        && text.contains("Zweite Kopfzeile mit Details.")
                },
                onTimeout: { book in
                    let seen = fourDSignaturePanelText(window: window) ?? "(kein Panel)"
                    ws.closeProject()
                    try? FileManager.default.removeItem(at: projectRoot)
                    finish(false, "Parameterhilfe erscheint nicht korrekt — \(book.summary); "
                        + "gesehen: \(seen.prefix(300))")
                },
                then: {
                    // Verschachtelter Aufruf: Cursor in die Klammern der inneren
                    // Methode, die selbst Argument der äußeren ist.
                    let ns = textView.string as NSString
                    let inner = ns.range(of: "\"Du\"")
                    guard inner.location != NSNotFound else {
                        ws.closeProject()
                        try? FileManager.default.removeItem(at: projectRoot)
                        finish(false, "verschachtelte Aufrufzeile fehlt")
                    }
                    textView.selectionManager.setSelectedRange(
                        NSRange(location: inner.max, length: 0)
                    )
                    pollFourDSignatureNestedInner(
                        ws: ws, window: window, textView: textView,
                        projectRoot: projectRoot)
                })
    }

    /// Im verschachtelten Aufruf muss die innere Methode angezeigt werden.
    private static func pollFourDSignatureNestedInner(
        ws: Workspace, window: NSWindow, textView: TextView,
        projectRoot: URL
    ) {
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard let text = fourDSignaturePanelText(window: window) else { return false }
                    return text.contains("InnereFormel")
                        && text.contains("$eingabe_t : Text")
                        && text.contains("$faktor_i : Integer")
                        && text.contains("$ergebnis_t : Text")
                        && text.contains("Berechnet die innere Formel.")
                        && !text.contains("Begruessung")
                        && !text.contains("Verpacke")
                },
                onTimeout: { book in
                    let seen = fourDSignaturePanelText(window: window) ?? "(kein Panel)"
                    ws.closeProject()
                    try? FileManager.default.removeItem(at: projectRoot)
                    finish(false, "verschachtelt: innere Methode erscheint nicht — \(book.summary); "
                        + "gesehen: \(seen.prefix(300))")
                },
                then: {
                    // Cursor hinter die innere schließende Klammer (vor `;80`):
                    // jetzt gilt wieder der äußere Aufruf, aktiver Parameter 0.
                    let ns = textView.string as NSString
                    let closing = ns.range(of: "\"Du\";1)")
                    guard closing.location != NSNotFound else {
                        ws.closeProject()
                        try? FileManager.default.removeItem(at: projectRoot)
                        finish(false, "innere schließende Klammer fehlt")
                    }
                    textView.selectionManager.setSelectedRange(
                        NSRange(location: closing.max, length: 0)
                    )
                    pollFourDSignatureNestedOuter(
                        ws: ws, window: window, textView: textView,
                        projectRoot: projectRoot)
                })
    }

    /// Hinter der inneren Klammer zeigt das Panel wieder die äußere Methode.
    private static func pollFourDSignatureNestedOuter(
        ws: Workspace, window: NSWindow, textView: TextView,
        projectRoot: URL
    ) {
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard let text = fourDSignaturePanelText(window: window) else { return false }
                    return text.contains("Verpacke")
                        && text.contains("$inhalt_t : Text")
                        && text.contains("Verpackt einen Text.")
                        && !text.contains("$eingabe_t")
                },
                onTimeout: { book in
                    let seen = fourDSignaturePanelText(window: window) ?? "(kein Panel)"
                    ws.closeProject()
                    try? FileManager.default.removeItem(at: projectRoot)
                    finish(false, "verschachtelt: äußere Methode erscheint hinter der "
                        + "inneren Klammer nicht — \(book.summary); gesehen: \(seen.prefix(300))")
                },
                then: {
                    // Cursor in den Aufruf der Komponentenmethode.
                    let ns = textView.string as NSString
                    let componentCall = ns.range(of: "\"Probe\"")
                    guard componentCall.location != NSNotFound else {
                        ws.closeProject()
                        try? FileManager.default.removeItem(at: projectRoot)
                        finish(false, "Komponenten-Aufrufzeile fehlt")
                    }
                    textView.selectionManager.setSelectedRange(
                        NSRange(location: componentCall.max, length: 0)
                    )
                    pollFourDSignatureComponent(
                        ws: ws, window: window, textView: textView,
                        projectRoot: projectRoot
                    )
                })
    }

    /// Geteilte Komponentenmethoden zeigen wie Projektmethoden Signatur und
    /// Kommentarkopf.
    private static func pollFourDSignatureComponent(
        ws: Workspace, window: NSWindow, textView: TextView,
        projectRoot: URL
    ) {
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard let text = fourDSignaturePanelText(window: window) else { return false }
                    return text.contains("Werkzeug_Miss")
                        && text.contains("$text_t : Text")
                        && text.contains("$laenge_i : Integer")
                        && text.contains("Misst einen Text.")
                },
                onTimeout: { book in
                    let seen = fourDSignaturePanelText(window: window) ?? "(kein Panel)"
                    ws.closeProject()
                    try? FileManager.default.removeItem(at: projectRoot)
                    finish(false, "Komponentenmethode erscheint nicht in der "
                        + "Parameterhilfe — \(book.summary); gesehen: \(seen.prefix(300))")
                },
                then: {
                    // Cursor an den Zeilenanfang → Panel muss verschwinden.
                    textView.selectionManager.setSelectedRange(
                        NSRange(location: 0, length: 0)
                    )
                    pollFourDSignaturePanelGone(
                        ws: ws, window: window, projectRoot: projectRoot
                    )
                })
    }

    private static func pollFourDSignaturePanelGone(
        ws: Workspace, window: NSWindow, projectRoot: URL
    ) {
        waitFor(budget: 10, pause: 0.25,
                condition: { fourDSignaturePanelText(window: window) == nil },
                onTimeout: { book in
                    ws.closeProject()
                    try? FileManager.default.removeItem(at: projectRoot)
                    finish(false, "Parameterhilfe bleibt außerhalb der Klammern sichtbar — \(book.summary)")
                },
                then: {
                    ws.closeProject()
                    try? FileManager.default.removeItem(at: projectRoot)
                    finish(true, "Parameterhilfe zeigt Signatur samt Kommentarkopf, "
                        + "wechselt verschachtelt zwischen innerer und äußerer "
                        + "Methode, kennt geteilte Komponentenmethoden und "
                        + "verschwindet außerhalb der Klammern")
                })
    }

    // MARK: - -selftest sighelpshot

    /// Diagnose: baut dieselbe Szene wie `sighelp4d` auf, lässt das Panel
    /// stehen und gibt Fenster-Nummern von Hauptfenster und Panel fürs
    /// Capture aus.
    private static func runFourDSignatureHelpShot() {
        testLabel = "sighelpshot"
        guard let ws = Workspace.shared,
              let window = mainWindowForAXChecks(),
              let root = window.contentView else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        let projectRoot = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-sighelpshot-\(UUID().uuidString)")
        let methods = projectRoot.appendingPathComponent(
            "Project/Sources/Methods", isDirectory: true
        )
        let target = methods.appendingPathComponent("Begruessung.4dm")
        let caller = methods.appendingPathComponent("Aufrufer.4dm")
        let targetSource = """
        //%attributes = {}
        // Baut die Grußformel für die Startseite.
        // Ruft niemand nachts an, bleibt der Gruß freundlich.
        #DECLARE($name_t : Text; $anzahl_i : Integer)->$gruss_t : Text
        $gruss_t:="Hallo "+$name_t
        """
        let callerSource = """
        // Aufrufer
        Begruessung("Welt";2)
        """
        do {
            try FileManager.default.createDirectory(
                at: methods, withIntermediateDirectories: true
            )
            try targetSource.write(to: target, atomically: true, encoding: .utf8)
            try callerSource.write(to: caller, atomically: true, encoding: .utf8)
        } catch {
            finish(false, "Fixture nicht schreibbar: \(error.localizedDescription)")
        }
        ws.openProject(at: projectRoot)
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
            ws.loadFile(at: caller) { ok in
                guard ok else { finish(false, "Aufrufer lädt nicht") }
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                    guard let textView = editorTextView(in: root) as? TextView
                    else { finish(false, "TextView fehlt") }
                    window.makeFirstResponder(textView)
                    let ns = textView.string as NSString
                    let anchor = ns.range(of: "\"Welt\"")
                    textView.selectionManager.setSelectedRange(
                        NSRange(location: anchor.max, length: 0)
                    )
                    DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                        window.orderFront(nil)
                        let panelNumber = (window.childWindows ?? [])
                            .first { $0.styleMask.contains(.borderless) }?
                            .windowNumber ?? -1
                        let line = "SIGHELPSHOT-WINDOW \(window.windowNumber) "
                            + "PANEL \(panelNumber)\n"
                        FileHandle.standardError.write(Data(line.utf8))
                        DispatchQueue.main.asyncAfter(deadline: .now() + 12) {
                            exit(0)
                        }
                    }
                }
            }
        }
    }

    // MARK: - -selftest replaceall

    /// Nach „Alle ersetzen“ den tatsächlichen Editor-Text prüfen, nicht nur
    /// das Modell. CodeEditSourceEditor übernimmt Binding-Änderungen nicht von
    /// selbst; `applyAllInActiveBuffer` erhöht deshalb `editorReloadNonce` und
    /// erzeugt den Editor neu.
    private static func runReplaceAllTest() {
        testLabel = "replaceall"
        // Fenster und Workspace als Registry-Paar holen. Eine eigene Fenstersuche
        // könnte bei mehreren Dokumenten den falschen Editor prüfen.
        pollSharedWorkspaceWindow { ws, mainWindow, root in
            runReplaceAllTestBody(ws: ws, mainWindow: mainWindow, root: root)
        }
    }

    private static func runReplaceAllTestBody(
        ws: Workspace, mainWindow: NSWindow, root: NSView
    ) {
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)

        // Exakt der Präsentations-Demo-Inhalt („Nachname, Vorname" je Zeile),
        // 9 Treffer für `(\w+), (\w+)` (Leerzeile + Listen zählen nicht doppelt).
        let content = ["Mustermann, Max", "Mustermann, Erika", "Lovelace, Ada",
                       "Turing, Alan", "Hopper, Grace", "Karpathy, Andrej", "",
                       "ring, The", "Matrix, The", "Empire Strikes Back, The"]
            .joined(separator: "\n")
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-replaceall-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            // SwiftUI/CESE Zeit geben, den Editor mit dem Inhalt zu erzeugen.
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                guard let tvView = editorTextView(in: root), let tv = tvView as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                // Vorbedingung: Editor zeigt vor dem Replace den Original-Text.
                guard (tv.string as NSString).contains("Mustermann, Max") else {
                    finish(false, "Editor zeigt vor dem Replace nicht den Original-Text "
                        + "(string-Anfang: \(String(tv.string.prefix(40))))")
                }
                // Der Produkt-Runner arbeitet bewusst nur bei offener
                // Suchmaske: Seit v1.77 filtert `SearchRunner` alle
                // Live-Trigger weg, solange `showSearchDialog` falsch ist —
                // sonst würde schon das Laden eines Tabs einen Volltextlauf
                // über Megazeilen anstoßen. Dieser Test setzte den Zustand
                // nicht und wartete deshalb auf eine Suche, die nie startete
                // (beobachtet als total=0, searching=false).
                ws.showSearchDialog = true
                ws.scope = .file
                ws.useRegex = true
                ws.caseSensitive = false
                ws.replacePattern = "$2 $1"
                ws.findPattern = #"(\w+), (\w+)"#
                pollReplaceAllReady(ws, root: root)
            }
        }
    }

    /// Wartet, bis die (async) Suche die 9 Demo-Treffer geliefert hat, ruft
    /// dann `applyAllInActiveBuffer()` (exakt der „Alle ersetzen"-Pfad) und
    /// pollt anschließend den echten Editor-Text.
    private static func pollReplaceAllReady(_ ws: Workspace, root: NSView) {
        waitFor(budget: 3, pause: 0.03,
                condition: { !ws.bufferSearching && ws.bufferTotalMatches == 9 },
                onTimeout: { book in
                    finish(false, "(replaceall) Suche lieferte nicht 9 Treffer "
                        + "(total=\(ws.bufferTotalMatches), searching=\(ws.bufferSearching), "
                        + "error=\(ws.searchError ?? "nil")) — \(book.summary)")
                },
                then: {
                    ws.applyAllInActiveBuffer()
                    // Modell-Soll: das, was die Engine produziert. Erst das Modell prüfen
                    // (muss korrekt ersetzt sein), dann die View dagegen abgleichen.
                    let expected = ws.activeTab?.content ?? ""
                    guard expected.contains("Max Mustermann"),
                          !expected.contains("Mustermann, Max") else {
                        finish(false, "Modell-Replace selbst falsch: content=\(String(expected.prefix(60)))")
                    }
                    pollReplaceAllVisible(ws, root: root, expected: expected)
                })
    }

    /// Pollt den echten Editor-`.string` (jedes Mal frisch aus der View-
    /// Hierarchie geholt, weil der Editor neu erzeugt wird), bis er den
    /// vollständig ersetzten Text zeigt. Eine einzelne richtige Ersetzung
    /// genügt nicht: Auch die übrigen Ersetzungen und Dokumentteile zählen.
    private static func pollReplaceAllVisible(_ ws: Workspace, root: NSView,
                                              expected: String) {
        waitFor(budget: 3, pause: 0.03,
                condition: { (editorTextView(in: root) as? TextView)?.string == expected },
                onTimeout: { book in
                    let now = (editorTextView(in: root) as? TextView)?.string ?? "<kein Editor>"
                    finish(false, "(replaceall) Editor zeigt nach dem Replace weiter den ALTEN Text — "
                        + "Neuerzeugung wirkte nicht. string-Anfang: \(String(now.prefix(60))) — \(book.summary)")
                },
                then: {
                    finish(true, "Editor zeigt nach Alle-ersetzen den vollständigen Modell-Inhalt")
                })
    }

    // MARK: - -selftest pilldrop

    /// Gruppen-Drop bei bereits fokussiertem Ersetzen-Feld und nahe dessen
    /// unterem Rand prüfen. Ein `NSDraggingInfo`-Mock mit „$1“ treibt die
    /// Drag-Destination-Methoden des äußeren `RegexFieldScrollView`; echtes
    /// Maus-Dragging wird damit nicht geprüft.
    private static func runPillDropTest() {
        testLabel = "pilldrop"
        guard let searchWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName == SearchWindow.frameAutosaveName
        }) else { finish(false, "Suchfenster nicht gefunden") }
        searchWindow.makeKeyAndOrderFront(nil)
        activateApplication(ignoringOtherApps: true)

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            guard let root = searchWindow.contentView else {
                finish(false, "Suchfenster ohne contentView")
            }
            guard let replaceField = findReplaceField(in: root) else {
                finish(false, "Ersetzen-Feld (fastra.replaceField) nicht gefunden")
            }
            // Feld leeren + fokussieren — genau die Bug-Bedingung (fokussiertes Feld).
            replaceField.string = ""
            guard searchWindow.makeFirstResponder(replaceField),
                  replaceField.window?.firstResponder === replaceField else {
                finish(false, "Ersetzen-Feld konnte nicht fokussiert werden (kein First Responder)")
            }
            guard let dropSurface = replaceField.enclosingScrollView
                    as? RegexFieldScrollView else {
                finish(false, "Ersetzen-Feld besitzt kein vollflächiges Drop-Ziel")
            }

            // NSDraggingInfo liefert Fensterkoordinaten. Wir zielen bewusst nur
            // einen Punkt oberhalb des unteren sichtbaren ScrollView-Rands.
            let lowerEdge = NSPoint(x: dropSurface.bounds.minX + 8,
                                    y: dropSurface.bounds.minY + 1)
            let windowPoint = dropSurface.convert(lowerEdge, to: nil)
            let mock = MockDraggingInfo(string: "$1", location: windowPoint)
            // 1) Annahme am unteren Rand: muss .copy liefern.
            let op = dropSurface.draggingEntered(mock)
            guard op.contains(.copy) else {
                finish(false, "(unterer Rand, fokussiert) draggingEntered lieferte "
                    + "rawValue=\(op.rawValue), erwartet .copy")
            }
            // 2) Drop ausführen: Feldinhalt muss danach $1 enthalten.
            let accepted = dropSurface.performDragOperation(mock)
            let shown = replaceField.string
            if accepted && shown.contains("$1") {
                finish(true, "Komplette Feldhöhe nimmt Pillen-Drop bei Fokus an: "
                    + "unterer Rand=.copy, performDrag fügte $1 ein (Inhalt: \(shown))")
            } else {
                finish(false, "(unterer Rand, fokussiert) performDragOperation=\(accepted), "
                    + "Feld-Inhalt \(shown) enthält kein $1")
            }
        }
    }

    /// Findet die `RegexFieldTextView` des Ersetzen-Feldes über ihren
    /// Accessibility-Identifier (in `RegexFieldView.makeNSView` gesetzt).
    private static func findReplaceField(in view: NSView) -> RegexFieldTextView? {
        if let tv = view as? RegexFieldTextView,
           tv.accessibilityIdentifier() == "fastra.replaceField" {
            return tv
        }
        for sub in view.subviews {
            if let f = findReplaceField(in: sub) { return f }
        }
        return nil
    }

    /// Minimaler `NSDraggingInfo`-Mock für `pilldrop`: trägt einen String auf
    /// einer eigenen Pasteboard, alle übrigen Protokoll-Member sind triviale
    /// Stubs. Reicht, um die Drag-Destination-Overrides headless zu prüfen —
    /// echtes Maus-Dragging lässt sich nicht automatisieren.
    private final class MockDraggingInfo: NSObject, NSDraggingInfo {
        private let pasteboard: NSPasteboard
        var draggingLocation: NSPoint

        init(string: String, location: NSPoint) {
            self.pasteboard = NSPasteboard(name: NSPasteboard.Name("fastra.test.pilldrop"))
            self.pasteboard.clearContents()
            self.pasteboard.setString(string, forType: .string)
            self.draggingLocation = location
            super.init()
        }

        init(fileURL: URL, location: NSPoint) {
            self.pasteboard = NSPasteboard(
                name: NSPasteboard.Name("fastra.test.file-drop.\(UUID().uuidString)")
            )
            self.pasteboard.clearContents()
            self.pasteboard.writeObjects([fileURL as NSURL])
            self.draggingLocation = location
            super.init()
        }

        var draggingPasteboard: NSPasteboard { pasteboard }
        // Externer Drag (nicht das Feld selbst) → die Overrides greifen.
        var draggingSource: Any? { nil }
        var draggingDestinationWindow: NSWindow? { nil }
        var draggingSourceOperationMask: NSDragOperation { .copy }
        var draggedImageLocation: NSPoint { draggingLocation }
        var draggedImage: NSImage? { nil }
        var draggingSequenceNumber: Int { 0 }
        var draggingFormation: NSDraggingFormation = .default
        var animatesToDestination: Bool = false
        var numberOfValidItemsForDrop: Int = 1
        var springLoadingHighlight: NSSpringLoadingHighlight { .none }
        func resetSpringLoading() {}
        func slideDraggedImage(to screenPoint: NSPoint) {}
        func enumerateDraggingItems(options enumOpts: NSDraggingItemEnumerationOptions,
                                    for view: NSView?,
                                    classes classArray: [AnyClass],
                                    searchOptions: [NSPasteboard.ReadingOptionKey: Any],
                                    using block: (NSDraggingItem, Int, UnsafeMutablePointer<ObjCBool>) -> Void) {}
    }

    // MARK: - -selftest navmatch

    /// Navigation bei aktiver Suchmaske prüfen: Trefferklick oder ⌘G muss den
    /// Sprung im Editor sichtbar machen, während die Maske Key-Window bleibt.
    /// Anders als `jump` wird das Hauptfenster nicht künstlich vorab aktiviert.
    private static func runNavMatchTest() {
        testLabel = "navmatch"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        // 3 Treffer „TREFFER" auf Zeile 2/4/6.
        let content = ["zeile eins ohne", "TREFFER zwei hier", "zeile drei nix",
                       "TREFFER vier da", "zeile fuenf nix", "TREFFER sechs"].joined(separator: "\n")
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-navmatch-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                guard let tvView = editorTextView(in: root), let tv = tvView as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                // Realistisch: die Suchmaske nach vorn holen + zum Key-Window
                // machen — so wie es ist, wenn der Nutzer dort einen Treffer
                // anklickt. Nicht das Hauptfenster aktivieren (das war der
                // unrealistische Trick des jump-Tests).
                guard let searchWin = NSApp.windows.first(where: {
                    $0.frameAutosaveName == SearchWindow.frameAutosaveName && $0.isVisible
                }) else { finish(false, "keine sichtbare Suchmaske") }
                activateApplication(ignoringOtherApps: true)
                searchWin.makeKeyAndOrderFront(nil)

                ws.scope = .file
                ws.useRegex = false
                ws.caseSensitive = true
                ws.findPattern = "TREFFER"
                pollNavReady(ws, tv: tv, searchWindow: searchWin, originalText: content)
            }
        }
    }

    /// Wartet auf drei Treffer und drückt Return im echten Suchfeld. Das muss
    /// Treffer 0 aktivieren und den Fokus an die Trefferliste weitergeben.
    private static func pollNavReady(_ ws: Workspace, tv: TextView,
                                     searchWindow: NSWindow, originalText: String) {
        waitFor(budget: 3, pause: 0.03,
                condition: { !ws.bufferSearching && ws.bufferMatches.count == 3 },
                onTimeout: { book in
                    finish(false, "(navmatch) Suche lieferte nicht 3 Treffer "
                        + "(count=\(ws.bufferMatches.count), searching=\(ws.bufferSearching), "
                        + "error=\(ws.searchError ?? "nil")) — \(book.summary)")
                },
                then: {
                    guard let root = searchWindow.contentView else {
                        finish(false, "(navmatch) Suchmaske ohne contentView")
                    }
                    var fields: [NSView] = []
                    collectTypeableFields(in: root, into: &fields)
                    guard let findField = fields.compactMap({ $0 as? RegexFieldTextView }).first(where: {
                        $0.accessibilityIdentifier() == "fastra.findField"
                    }), searchWindow.makeFirstResponder(findField) else {
                        finish(false, "(navmatch) Suchfeld nicht gefunden/fokussierbar")
                    }
                    // Derselbe AppKit-onSubmit-Pfad wie eine physische Return-Taste.
                    findField.insertNewline(nil)
                    pollNavSelection(ws, tv: tv, searchWindow: searchWindow,
                                     originalText: originalText, expectedIndex: 0,
                                     thenPressReturnInList: true, findField: findField)
                })
    }

    /// Prüft unabhängig beobachtbar: richtige Selektion, Suchfenster bleibt
    /// Key, Editor bleibt ohne First-Responder und sein Text unverändert.
    private static func pollNavSelection(_ ws: Workspace, tv: TextView,
                                         searchWindow: NSWindow, originalText: String,
                                         expectedIndex: Int, thenPressReturnInList: Bool,
                                         findField: RegexFieldTextView? = nil) {
        var sel = NSRange(location: NSNotFound, length: 0)
        waitFor(budget: 1.8, pause: 0.03,
                condition: {
                    let editorText = tv.string as NSString
                    sel = tv.selectedRange()
                    return ws.activeMatchIndex == expectedIndex
                        && sel.location != NSNotFound && sel.length > 0
                        && NSMaxRange(sel) <= editorText.length
                },
                onTimeout: { book in
                    finish(false, "(navmatch) Treffer \(expectedIndex) wurde nicht "
                        + "aktiv-selektiert (activeMatchIndex=\(ws.activeMatchIndex), "
                        + "selectedRange=\(sel)) — Navigation aus der Suchmaske wirkungslos — \(book.summary)")
                },
                then: {
                    let editorText = tv.string as NSString
                    let selectedText = editorText.substring(with: sel)
                    if selectedText != "TREFFER" {
                        finish(false, "(navmatch) Sprung selektierte \"\(selectedText)\", erwartet \"TREFFER\"")
                    }
                    guard searchWindow.isKeyWindow else {
                        // Zwei Fälle unterscheiden: Eine fremde aktive App verhindert den Test
                        // (Umgebung, Exit 2); bei aktiver Fastra ist ein falsches eigenes Key-Window
                        // der hier geprüfte Produktfehler.
                        let keyDesc = NSApp.keyWindow.map {
                            "[\(type(of: $0))] \"\($0.title)\""
                        } ?? "keins"
                        guard NSApp.isActive else {
                            finish(.environment, "Umgebungsproblem: Fastra ist nach Treffer "
                                   + "\(expectedIndex) nicht mehr aktiv — eine andere App "
                                   + "hat den Fokus geholt (keyWindow=\(keyDesc)). "
                                   + "Test auf einem unbenutzten Mac wiederholen.")
                        }
                        finish(false, "(navmatch) Suchmaske verlor nach Treffer "
                               + "\(expectedIndex) den Key-Status an ein anderes "
                               + "Fastra-Fenster (keyWindow=\(keyDesc))")
                    }
                    if tv.window?.firstResponder === tv {
                        finish(false, "(navmatch) Editor wurde nach Treffer \(expectedIndex) First Responder")
                    }
                    guard tv.string == originalText else {
                        finish(false, "(navmatch) Dokumenttext wurde durch Return verändert")
                    }
                    if thenPressReturnInList {
                        guard let findField else {
                            finish(false, "(navmatch) Referenz auf das Suchfeld fehlt")
                        }
                        pollNavListFocusThenReturn(
                            ws, tv: tv, searchWindow: searchWindow,
                            originalText: originalText, findField: findField
                        )
                        return
                    }
                    finish(true, "Return im Suchfeld fokussiert Treffer 1; Pfeil-runter in der "
                        + "Trefferliste springt zu Treffer 2; Suchmaske bleibt Key, Editor unverändert")
                })
    }

    /// Wartet auf den echten Fokuswechsel aus dem Suchfeld, bevor der Test die
    /// Listen-Navigation prüft. SwiftUI setzt `@FocusState` erst nach einem
    /// variablen Layoutlauf um; eine feste 100-ms-Pause schickte das Event
    /// unter Last gelegentlich noch einmal ans Suchfeld und prüfte damit einen
    /// zweiten „ersten Treffer“ statt Navigation in der Trefferliste.
    ///
    /// Geprüft wird mit Pfeil-runter statt Return: Der Button „Nächster"
    /// besitzt in Nicht-Ordner-Bereichen einen fensterweiten Return-Shortcut
    /// und würde ein Return auch ohne Listenfokus zum zweiten Treffer
    /// weiterreichen — der Test bestünde dann trotz defekter Fokusübergabe.
    /// Pfeiltasten verarbeitet ausschließlich die fokussierte Trefferliste
    /// (`onMoveCommand`); bleibt der Sprung aus, ist der Listenfokus wirklich
    /// defekt.
    private static func pollNavListFocusThenReturn(
        _ ws: Workspace,
        tv: TextView,
        searchWindow: NSWindow,
        originalText: String,
        findField: RegexFieldTextView
    ) {
        waitFor(budget: 3, pause: 0.03,
                condition: {
                    guard let responder = searchWindow.firstResponder else { return false }
                    return responder !== findField
                },
                onTimeout: { book in
                    finish(false, "(navmatch) Trefferliste übernahm den Fokus nicht "
                        + "(FirstResponder=\(String(describing: searchWindow.firstResponder))) — \(book.summary)")
                },
                then: {
                    postKey("\u{F701}", keyCode: 125, windowNumber: searchWindow.windowNumber)
                    pollNavSelection(
                        ws, tv: tv, searchWindow: searchWindow,
                        originalText: originalText, expectedIndex: 1,
                        thenPressReturnInList: false
                    )
                })
    }

    /// Auf eine Selektion warten und ihren Text mit dem Treffer vergleichen.
    /// Eine falsche Selektion oder ihr Ausbleiben ist ein Fehler.
    /// Die TextView je Durchlauf neu auflösen: Ein Remount kann die zuvor erfasste
    /// View ersetzen. Nur bediente Durchläufe zählen, keine fremde Main-Thread-Last.
    private static func pollForSelection(in root: NSView, expected: String,
                                         expectedContent: String,
                                         label: String,
                                         onPass: @escaping () -> Void) {
        // ≈ 3 s bediente Beobachtung im 30-ms-Takt.
        var editorFound = false
        var sel = NSRange(location: NSNotFound, length: 0)
        var selectedText = ""
        waitFor(budget: 3, pause: 0.03,
                condition: {
                    guard let tv = editorTextView(in: root) as? TextView,
                          tv.string == expectedContent else {
                        // Editor gerade (wieder) im Umbau — weiter beobachten.
                        editorFound = false
                        return false
                    }
                    editorFound = true
                    let editorText = tv.string as NSString
                    sel = tv.selectedRange()
                    guard sel.location != NSNotFound, sel.length > 0,
                          NSMaxRange(sel) <= editorText.length else { return false }
                    selectedText = editorText.substring(with: sel)
                    return true
                },
                onTimeout: { book in
                    guard editorFound else {
                        finish(false, "(\(label)) Editor mit erwartetem Inhalt blieb "
                            + "verschwunden — \(book.summary)")
                    }
                    finish(false, "(\(label)) Sprung setzte keine Selektion (selectedRange=\(sel)) — \(book.summary)")
                },
                then: {
                    if selectedText == expected {
                        onPass()
                    } else {
                        finish(false, "(\(label)) Sprung daneben: selektiert \"\(selectedText)\", "
                               + "erwartet \"\(expected)\" — genau der Offset-Drift")
                    }
                })
    }

    // MARK: - -selftest scrolljump

    /// Treffersortierung und Scrollen im laufenden Editor prüfen: 2500 Zeilen
    /// laden, echte Suche ausführen, aufsteigende Trefferfolge verlangen und zu
    /// einem Treffer ab Zeile 1900 springen. `rectForOffset` und `visibleRect`
    /// müssen belegen, dass der Treffer im sichtbaren Bereich liegt.
    private static func runScrollJumpTest() {
        testLabel = "scrolljump"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)

        // 2500 Zeilen, jede mit einem eindeutigen „ende"-Treffer.
        var lines: [String] = []
        lines.reserveCapacity(2500)
        for i in 1...2500 { lines.append("Zeile \(i): wert ende") }
        let content = lines.joined(separator: "\n")
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-scroll-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                guard let tvView = editorTextView(in: root), let tv = tvView as? TextView else {
                    finish(false, "Editor-TextView nicht als CodeEditTextView.TextView erreichbar")
                }
                _ = mainWindow.makeFirstResponder(tv)

                let opts = SearchOptions(find: "ende", replace: "",
                                         isRegex: false, caseSensitive: true)
                let result = BufferSearch.find(in: ws.activeTab?.content ?? "", options: opts)
                let lineSeq = result.matches.map(\.line)
                guard !lineSeq.isEmpty else {
                    finish(false, "keine Treffer gefunden (Inhalt nicht geladen?)")
                }
                // Treffer müssen aufsteigend sortiert sein.
                if lineSeq != lineSeq.sorted() {
                    finish(false, "bufferMatches NICHT aufsteigend nach Zeile — erste: \(lineSeq.prefix(8))")
                }
                // Sprung-Ziel weit unten (innerhalb des 2000er-Materialisierungs-Caps).
                guard let target = result.matches.first(where: { $0.line >= 1900 }) else {
                    finish(false, "kein Treffer ab Zeile 1900 — max gelistete Zeile \(lineSeq.max() ?? 0)")
                }
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                    NotificationCenter.default.postMatchJump(target, for: ws)
                    pollForScrollVisible(tv, matchLocation: target.range.location,
                                         line: target.line)
                }
            }
        }
    }

    /// Pollt, bis der Treffer-Rect (via `rectForOffset`) den sichtbaren Bereich
    /// des Editors schneidet — belegt, dass der Sprung wirklich dorthin
    /// gescrollt hat. FAIL, wenn der Treffer nach ~2 s nicht in Sicht ist
    /// (z.B. weil fälschlich an den Datei-Anfang gescrollt wurde).
    private static func pollForScrollVisible(_ tv: TextView, matchLocation: Int,
                                             line: Int) {
        var rect: CGRect?
        var visible = CGRect.zero
        waitFor(budget: 2, pause: 0.05,
                condition: {
                    rect = tv.layoutManager.rectForOffset(matchLocation)
                    visible = tv.visibleRect
                    guard let rect else { return false }
                    return visible.intersects(rect)
                },
                onTimeout: { book in
                    guard let rect else {
                        finish(false, "rectForOffset lieferte nil für Zeile \(line) — \(book.summary)")
                    }
                    finish(false, "Treffer NICHT in Sicht: Zeile \(line) liegt bei matchY=\(Int(rect.midY)), "
                           + "sichtbar nur \(Int(visible.minY))–\(Int(visible.maxY)) (scrollte an den Anfang?) — \(book.summary)")
                },
                then: {
                    guard let rect else { finish(false, "Treffer-Rect nach Erfolg verschwunden") }
                    finish(true, "Sprung scrollte Zeile \(line) in Sicht "
                           + "(matchY=\(Int(rect.midY)), sichtbar \(Int(visible.minY))–\(Int(visible.maxY)))")
                })
    }

    /// Sammelt alle editierbaren `NSTextField` (SwiftUI-`TextField` bridged
    /// darauf) rekursiv ein. Nicht-editierbare Labels (SwiftUI-`Text` →
    /// `NSTextField` mit `isEditable == false`) werden ausgeschlossen.
    private static func collectEditableFields(in view: NSView, into out: inout [NSTextField]) {
        if let tf = view as? NSTextField, tf.isEditable, tf.isEnabled {
            out.append(tf)
        }
        for sub in view.subviews { collectEditableFields(in: sub, into: &out) }
    }

    /// Sammelt beide Arten betippbarer Eingabefelder ein: klassische
    /// editierbare `NSTextField` und die `RegexFieldTextView`s der
    /// Suchmaske (NSTextView-Subklasse, seit v0.7 — Token-Highlighting).
    private static func collectTypeableFields(in view: NSView, into out: inout [NSView]) {
        if let tf = view as? NSTextField, tf.isEditable, tf.isEnabled {
            out.append(tf)
        } else if let tv = view as? RegexFieldTextView, tv.isEditable {
            out.append(tv)
        }
        for sub in view.subviews { collectTypeableFields(in: sub, into: &out) }
    }

    /// Aktueller Text eines betippbaren Felds (beide Arten).
    private static func readFieldText(_ field: NSView) -> String {
        if let tf = field as? NSTextField { return tf.stringValue }
        if let tv = field as? RegexFieldTextView { return tv.string }
        return ""
    }

    private static func describe(_ field: NSTextField) -> String {
        "\(type(of: field)) ph=\"\(field.placeholderString ?? "")\""
    }

    /// Beschreibung für Fehlermeldungen — beide Feld-Arten.
    private static func describeField(_ field: NSView) -> String {
        if let tf = field as? NSTextField { return describe(tf) }
        if let tv = field as? RegexFieldTextView {
            return "RegexFieldTextView ph=\"\(tv.placeholder)\""
        }
        return String(describing: type(of: field))
    }

    // MARK: - -selftest hscroll

    /// Horizontalen Scrollbereich bei ausgeschaltetem Umbruch prüfen:
    /// `documentView` muss für lange Zeilen breiter als der Viewport und
    /// `hasHorizontalScroller` gesetzt sein. Messwerte auch bei Erfolg ausgeben.
    /// Das Plain-Text-Profil unabhängig von Nutzer-Defaults und Altschlüssel setzen.
    private static func runHScrollTest() {
        testLabel = "hscroll"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)

        // 40 sehr lange Zeilen (~430 Zeichen) → weit breiter als jedes Fenster.
        let longTail = String(repeating: "lang_", count: 80)
        var lines: [String] = []
        for i in 1...40 { lines.append("Zeile \(i) \(longTail) ENDE\(i)") }
        let content = lines.joined(separator: "\n")
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-hscroll-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            // Das Profil des geladenen Textdokuments setzen, nicht das zuvor aktive.
            ws.setSoftWrapEnabled(false)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.9) {
                guard let tvView = editorTextView(in: root), let tv = tvView as? TextView else {
                    finish(false, "Editor-TextView nicht als CodeEditTextView.TextView erreichbar")
                }
                guard let sv = tv.enclosingScrollView else {
                    finish(false, "kein enclosingScrollView am Editor-TextView")
                }
                let evaluation = horizontalScrollEvaluation(textView: tv, scrollView: sv)
                finish(evaluation.passed, evaluation.info)
            }
        }
    }

    /// Liest den Scrollnachweis am echten Editor für den In-App-Test.
    static func horizontalScrollEvaluation(
        textView tv: TextView, scrollView sv: NSScrollView
    ) -> (passed: Bool, info: String) {
        let clipW = sv.contentView.bounds.width
        let wrap = tv.wrapLines
        let estimatedWidth = tv.layoutManager.estimatedWidth()
        let documentWidth = sv.documentView?.frame.width ?? 0
        let hasH = sv.hasHorizontalScroller
        let style = sv.scrollerStyle == .overlay ? "overlay" : "legacy"
        let info = "wrap=\(wrap) clipW=\(Int(clipW)) hasH=\(hasH) style=\(style) "
            + "est=\(Int(estimatedWidth)) docW=\(Int(documentWidth))"
        // Nur beobachten: Ein selbst ausgelöstes Layout würde einen fehlenden
        // produktiven Layout-Trigger gerade vor seiner Prüfung verdecken.
        let scrollable = !wrap && clipW > 0 && documentWidth > clipW + 1 && hasH
        return (scrollable,
                (scrollable ? "horizontal scrollbar OK: " : "NICHT horizontal scrollbar: ") + info)
    }

    // MARK: - -selftest crjump

    /// Tiefe Treffer-Sprünge bei reinen CR-Zeilenenden prüfen. Nach dem Sprung
    /// mit `textLineForPosition(visibleRect.midY)` die tatsächlich sichtbare Zeile
    /// bestimmen. Das ist unabhängig von `rectForOffset`, dessen Höhenschätzung
    /// auch der Sprung selbst verwendet. Indizes zur Diagnose ausgeben.
    private static func runCRJumpTest() {
        testLabel = "crjump"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)

        // 41000 lange Zeilen mit reinen CR-Trennern und Ziel auf Zeile 40000.
        // Rund 280 Zeichen pro Zeile erzeugen bei Umbruch variable Höhen; große
        // Tiefe macht kumulierte Schätzfehler in `convergeScroll` erkennbar.
        let tail = String(repeating: "gg.4DProject.M[2568][Web021] WebDebugLog SendFile ", count: 5)
        var lines: [String] = []
        for i in 1...41000 { lines.append("Zeile \(i) \(tail) \(i == 40000 ? "ZIELMARKE" : "ende")") }
        let content = lines.joined(separator: "\r")
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-crjump-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            // 41k lange Zeilen → CESE-Editor-Mount braucht spürbar länger als bei
            // 3000 (Mount blockiert proportional, vgl. loadperf). Mehr Settle-Zeit,
            // sonst misst der Test, bevor das Layout steht.
            DispatchQueue.main.asyncAfter(deadline: .now() + 2.5) {
                guard let tvView = editorTextView(in: root), let tv = tvView as? TextView else {
                    finish(false, "Editor-TextView nicht als CodeEditTextView.TextView erreichbar")
                }
                _ = mainWindow.makeFirstResponder(tv)
                let opts = SearchOptions(find: "ZIELMARKE", replace: "", isRegex: false, caseSensitive: true)
                let result = BufferSearch.find(in: ws.activeTab?.content ?? "", options: opts)
                guard let match = result.matches.first else {
                    finish(false, "ZIELMARKE nicht gefunden (Inhalt/CR nicht geladen?)")
                }
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                    NotificationCenter.default.postMatchJump(match, for: ws)
                    // Settle lassen, dann unabhängig prüfen, welche Zeile sichtbar ist.
                    // 2,0 s statt 1,3 s — convergeScroll iteriert bei Tiefe 40000
                    // länger bis zur Konvergenz.
                    DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
                        let vis = tv.visibleRect
                        let shownMid = tv.layoutManager.textLineForPosition(vis.midY)?.index
                        let shownTop = tv.layoutManager.textLineForPosition(vis.minY)?.index
                        let byIndex = tv.layoutManager.textLineForIndex(match.line - 1)?.index
                        let byOffset = tv.layoutManager.textLineForOffset(match.range.location)?.index
                        let info = "matchLine=\(match.line) loc=\(match.range.location) "
                            + "textLineForIndex=\(byIndex.map(String.init) ?? "nil") "
                            + "textLineForOffset=\(byOffset.map(String.init) ?? "nil") "
                            + "sichtbarMitte(1-based)=\(shownMid.map { String($0 + 1) } ?? "nil") "
                            + "sichtbarOben(1-based)=\(shownTop.map { String($0 + 1) } ?? "nil") "
                            + "visY=\(Int(vis.minY))-\(Int(vis.maxY))"
                        if let s = shownMid, abs((s + 1) - match.line) <= 15 {
                            finish(true, "CR-Sprung korrekt: \(info)")
                        } else {
                            finish(false, "CR-Sprung FALSCH (Ziel nicht sichtbar): \(info)")
                        }
                    }
                }
            }
        }
    }

    // MARK: - -selftest textop

    /// Verifiziert den Menüleisten-Pfad der BBEdit-„Text"-Operationen
    /// end-to-end: Buffer laden, `.fastraTextOp` (uppercase) und danach beide
    /// `.fastraSortLines`-Richtungen posten — exakt wie es das „Text"-Menü tut.
    /// Geprüft wird jeweils der echte Editor-Inhalt. Deckt Observer
    /// (AppDelegate) → EditorContextMenu → native TextView → Undo-fähige
    /// Ersetzung ab.
    private static func runTextWorkflowMultiTest(onlyOneSided: Bool = false) {
        testLabel = onlyOneSided ? "textworkflowonesided" : "textworkflowmulti"
        Task { @MainActor in
            guard let ws = Workspace.shared, let window = CommandTargeting.registeredWindow(for: ws) else { finish(false, "Dokumentfenster fehlt") }
            let base = selfTestTemporaryDirectory().canonicalFileURL.appendingPathComponent("WorkflowMulti-" + UUID().uuidString)
            let root = base.appendingPathComponent("inputs")
            let one = root.appendingPathComponent("one.txt"), two = root.appendingPathComponent("two.txt")
            let original = "b  \na  \n", expected = "B\nA\n"
            var stage = "Vorbereitung", trackingMenus = Set<ObjectIdentifier>()
            let begin = NotificationCenter.default.addObserver(forName: NSMenu.didBeginTrackingNotification, object: nil, queue: .main) { event in
                if let menu = event.object as? NSMenu { trackingMenus.insert(ObjectIdentifier(menu)) }
            }
            let end = NotificationCenter.default.addObserver(forName: NSMenu.didEndTrackingNotification, object: nil, queue: .main) { event in
                if let menu = event.object as? NSMenu { trackingMenus.remove(ObjectIdentifier(menu)) }
            }
            @MainActor func cleanup() {
                NotificationCenter.default.removeObserver(begin); NotificationCenter.default.removeObserver(end)
                let mayRemoveFixtures = ws.textWorkflowSession?.isDiskOperation != true
                ws.textWorkflowSession?.close(); ws.folderApplyBackupRoot = nil
                if mayRemoveFixtures { try? FileManager.default.removeItem(at: base) }
            }
            func require(_ value: Bool, _ detail: String) throws {
                if !value { throw NSError(domain: "WorkflowMultiSelfTest", code: 1, userInfo: [NSLocalizedDescriptionKey: detail]) }
            }
            @MainActor func wait(_ condition: @MainActor () -> Bool) async throws {
                for _ in 0..<300 { if condition() { return }; try await Task.sleep(for: .milliseconds(50)) }
                try require(condition(), "Zustand wurde nicht bereit")
            }
            @MainActor func click(_ id: String, in target: NSWindow) throws {
                guard let root = target.contentView, let marker = markerView(id: id, in: root) else { try require(false, "Control fehlt: " + id); return }
                let rect = marker.convert(marker.bounds, to: nil)
                try require(sendMouseClick(at: NSPoint(x: rect.midX, y: rect.midY), in: target, modifiers: [], viaApp: true), "Klick fehlgeschlagen: " + id)
            }
            @MainActor func capture(_ name: String, in target: NSWindow) async throws {
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] else { return }
                let url = URL(fileURLWithPath: directory).appendingPathComponent(name + ".png")
                try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                let data: Data? = await withCheckedContinuation { done in typeScrollCapture(window: target) { done.resume(returning: $0?.data) } }
                try require(data != nil, "Fensteraufnahme fehlt")
                try data?.write(to: url)
            }
            @MainActor func select(_ id: String, delta: Int, in sheet: NSWindow) async throws {
                try click(id, in: sheet)
                try await Task.sleep(for: .milliseconds(350))
                for _ in 0..<abs(delta) {
                    postKey(delta > 0 ? "\u{F701}" : "\u{F700}", keyCode: delta > 0 ? 125 : 126, windowNumber: sheet.windowNumber)
                }
                postKey("\r", keyCode: 36, windowNumber: sheet.windowNumber)
                try await wait { trackingMenus.isEmpty && sheet.isKeyWindow }
                try await Task.sleep(for: .milliseconds(400))
            }
            @MainActor func matrix(_ name: String, in sheet: NSWindow, requiresDiff: Bool = true, errorAtEnd: Bool? = nil) async throws {
                for (mode, appearance) in [("light", NSAppearance.Name.aqua), ("dark", .darkAqua)] {
                    NSApp.appearance = NSAppearance(named: appearance)
                    for (size, width) in [("minimum", CGFloat(900)), ("wide", CGFloat(1200))] {
                        sheet.setContentSize(NSSize(width: width, height: size == "minimum" ? 760 : 820))
                        try await Task.sleep(for: .milliseconds(300))
                        guard let content = sheet.contentView else { try require(false, "Dialoginhalt fehlt"); return }
                        try require(abs(content.bounds.width - width) < 1, "Angeforderte Dialogbreite nicht erreicht: \(content.bounds.width)/\(width)")
                        if let atEnd = errorAtEnd {
                            guard let scroll = markerView(id: "textWorkflowErrorContent", in: content)?.enclosingScrollView,
                                  let document = scroll.documentView else { try require(false, "Fehlerliste ist nicht scrollbar"); return }
                            let top = document.isFlipped ? document.bounds.minY : document.bounds.maxY - scroll.contentView.bounds.height
                            let bottom = document.isFlipped ? document.bounds.maxY - scroll.contentView.bounds.height : document.bounds.minY
                            let target = atEnd ? bottom : top
                            scroll.contentView.scroll(to: NSPoint(x: 0, y: target))
                            scroll.reflectScrolledClipView(scroll.contentView)
                            try await Task.sleep(for: .milliseconds(100))
                            try require(scroll.contentView.bounds.height <= 96 && document.bounds.height > scroll.contentView.bounds.height + 20,
                                        "Fehlerliste ist nicht auf einen scrollbaren Bereich begrenzt")
                            try require(abs(scroll.contentView.bounds.minY - target) < 1, "Angefordertes Listenende nicht erreicht")
                            if atEnd { try require(abs(scroll.contentView.bounds.minY - top) > 10, "Fehlerliste wurde nicht gescrollt") }
                        }
                        try await capture(name + "-" + mode + "-" + size, in: sheet)
                        if requiresDiff {
                            guard let viewport = markerView(id: "dualPaneDiffViewport", in: content) else { try require(false, "Diff-Ansicht fehlt"); return }
                            let rect = viewport.convert(viewport.bounds, to: content).intersection(content.bounds)
                            try require(rect.width >= 300 && rect.height >= 80, "Diff bei Mindestgröße nicht erreichbar: \(rect)")
                            if name == "one-sided-unicode-lines", size == "minimum" {
                                func horizontalScroll(in view: NSView) -> NSScrollView? {
                                    if let scroll = view as? NSScrollView,
                                       let document = scroll.documentView,
                                       document.bounds.width > scroll.contentView.bounds.width + 20 { return scroll }
                                    for child in view.subviews { if let found = horizontalScroll(in: child) { return found } }
                                    return nil
                                }
                                guard let scroll = horizontalScroll(in: content), let document = scroll.documentView else {
                                    try require(false, "Schmaler Diff hat keinen horizontalen Scrollbereich"); return
                                }
                                let before = scroll.contentView.bounds.minX
                                let end = document.bounds.maxX - scroll.contentView.bounds.width
                                scroll.contentView.scroll(to: NSPoint(x: end, y: scroll.contentView.bounds.minY))
                                scroll.reflectScrolledClipView(scroll.contentView)
                                try await Task.sleep(for: .milliseconds(100))
                                try require(scroll.contentView.bounds.minX > before + 20 && abs(scroll.contentView.bounds.minX - end) < 1,
                                            "Rechtes Diff-Ende wurde nicht erreicht")
                                try await capture(name + "-" + mode + "-" + size + "-scrolled", in: sheet)
                                scroll.contentView.scroll(to: NSPoint(x: before, y: scroll.contentView.bounds.minY))
                                scroll.reflectScrolledClipView(scroll.contentView)
                            }
                        }
                        for id in ["textWorkflowClose", "textWorkflowApply"] {
                            guard let marker = markerView(id: id, in: content) else { try require(false, "Control fehlt: " + id); return }
                            try require(content.bounds.contains(marker.convert(NSPoint.zero, to: content)), "Control außerhalb des Dialogs: " + id)
                        }
                    }
                }
            }
            do {
                try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
                try Data(original.utf8).write(to: one); try Data("TWO\n".utf8).write(to: two)
                window.setContentSize(NSSize(width: 1200, height: 850))
                activateApplication(ignoringOtherApps: true); window.makeKeyAndOrderFront(nil)
                try await wait { window.isVisible && window.isKeyWindow && NSApp.isActive }
                for url in [two, one] {
                    stage = "Datei laden: " + url.lastPathComponent
                    var loaded = false; ws.loadFile(at: url) { loaded = $0 }
                    try await wait { loaded && CommandTargeting.editorTextView(for: ws)?.string == (url == one ? original : "TWO\n") }
                }
                ws.tabs.removeAll { $0.url == nil }
                ws.folderApplyBackupRoot = base.appendingPathComponent("journal")
                stage = "Dialog öffnen"
                ws.presentTextWorkflows()
                try await wait { ws.textWorkflowSession != nil && !window.sheets.isEmpty }
                var session = ws.textWorkflowSession!, sheet = window.sheets[0]
                if onlyOneSided {
                    stage = "Einseitige Unicode-Zeilen"
                    var insertion = TextWorkflowStep(kind: .prefixLines)
                    insertion.argument = "\u{200B}\r\n"
                    session.new()
                    session.definition = TextWorkflow(name: "Unicode Lines", steps: [insertion])
                    try click("textWorkflowSave", in: sheet)
                    try await wait { !session.dirty }
                    try click("textWorkflowPreview", in: sheet)
                    try await wait { session.canApply && session.representationDetails }
                    try require(session.diffDocument?.result?.rows.contains(where: { ($0.before ?? $0.after ?? "").contains("\\u{200B}") }) == true
                                && session.diffDocument?.result?.rows.contains(where: { ($0.before ?? $0.after ?? "").contains("⟦CRLF⟧") }) == true,
                                "Einseitige unsichtbare Zeilen sind nicht annotiert")
                    try await matrix("one-sided-unicode-lines", in: sheet)
                    try require(try String(contentsOf: one, encoding: .utf8) == original, "Unicode-Vorschau hat Platte verändert")
                    try click("textWorkflowClose", in: sheet)
                    try await wait { ws.textWorkflowSession == nil && window.sheets.isEmpty }
                    cleanup()
                    finish(true, "Einseitige Unicode-/CRLF-Zeilen im echten Ablaufdialog, hell/dunkel, Mindestbreite/breit")
                }
                session.definition = TextWorkflow(name: "Multi Workflow", steps: [.init(kind: .trimTrailing), .init(kind: .uppercase)])
                try click("textWorkflowSave", in: sheet)
                try await wait { !session.dirty }
                stage = "Offene Dokumente: Bereich wählen"
                try await select("textWorkflowBatchScope", delta: 1, in: sheet)
                try require(session.scope == .openDocuments, "Bereichsauswahl hat offene Dokumente nicht gewählt")
                stage = "Offene Dokumente: Vorschau berechnen"
                try click("textWorkflowPreview", in: sheet)
                try await wait { session.batch?.entries.count == 2 && session.canApply }
                try require(try String(contentsOf: one, encoding: .utf8) == original, "Vorschau hat Platte verändert")
                guard let firstID = session.batch?.entries.first(where: { $0.title == "one.txt" })?.id else { throw NSError(domain: "WorkflowMultiSelfTest", code: 2) }
                stage = "Offene Dokumente: Änderungsdatei wählen"
                try await capture("diagnose-before-input-selection", in: sheet)
                try click("textWorkflowInput-" + firstID, in: sheet)
                try await wait { session.selectedInputID == firstID && session.canApply }
                try await matrix("open", in: sheet)
                try await select("textWorkflowPreviewChoice", delta: 1, in: sheet)
                try await wait { session.selectedPreview == 0 && session.diffDocument != nil }
                try require(!session.canApply, "Schrittvorschau gibt Apply frei")
                try await matrix("open-step", in: sheet)
                try await select("textWorkflowPreviewChoice", delta: -1, in: sheet)
                try await wait { session.canApply }
                try click("textWorkflowApply", in: sheet)
                try await wait { session.appliedDocuments != nil && ws.tabs.first(where: { $0.url == one })?.content == expected }
                try require(try String(contentsOf: one, encoding: .utf8) == original, "Speicher-Apply hat Platte verändert")
                try await matrix("open-applied", in: sheet, requiresDiff: false)
                try click("textWorkflowMemoryUndo", in: sheet)
                try await wait { ws.tabs.first(where: { $0.url == one })?.content == original && session.memoryRestored }
                try click("textWorkflowMemoryUndo", in: sheet)
                try await wait { ws.tabs.first(where: { $0.url == one })?.content == expected && !session.memoryRestored }
                try click("textWorkflowMemoryUndo", in: sheet)
                try await wait { ws.tabs.first(where: { $0.url == one })?.content == original }
                stage = "Geschlossener Tab und gemeinsame Rücknahme"
                try click("textWorkflowClose", in: sheet)
                try await wait { ws.textWorkflowSession == nil && window.sheets.isEmpty }
                if let tab = ws.tabs.first(where: { $0.url == one }) { ws.closeTab(id: tab.id) }
                var reopened = false
                ws.loadFile(at: one) { reopened = $0 }
                try await wait { reopened && CommandTargeting.editorTextView(for: ws)?.string == original }
                ws.presentTextWorkflows()
                try await wait { ws.textWorkflowSession != nil && !window.sheets.isEmpty }
                session = ws.textWorkflowSession!; sheet = window.sheets[0]
                try await select("textWorkflowBatchScope", delta: 1, in: sheet)
                try require(!session.canRestoreDocuments && session.appliedDocuments != nil, "Geschlossener Tab ließ gemeinsame Rücknahme zu")
                try await matrix("open-restore-unavailable", in: sheet, requiresDiff: false)
                stage = "Ordner und wirkungslose Fremdänderung"
                session.folderURLs = [root]
                try await select("textWorkflowBatchScope", delta: 1, in: sheet)
                try require(session.scope == .folder, "Ordnerbereich fehlt")
                try click("textWorkflowPreview", in: sheet)
                try await wait { session.batch?.entries.count == 2 && session.canApply }
                try await matrix("folder", in: sheet)
                try Data("external\n".utf8).write(to: two)
                try click("textWorkflowApply", in: sheet)
                try await wait { !session.isBusy && session.error != nil }
                try require(try String(contentsOf: one, encoding: .utf8) == original, "Fremdänderung ließ Teil-Apply zu")
                try await matrix("folder-stale", in: sheet, requiresDiff: false)
                try Data("TWO\n".utf8).write(to: two)
                try click("textWorkflowPreview", in: sheet)
                try await wait { session.canApply }
                try click("textWorkflowApply", in: sheet)
                try await wait { !session.isBusy && session.diskAppliedSession != nil && ws.tabs.first(where: { $0.url == one })?.content == expected }
                try require(try String(contentsOf: one, encoding: .utf8) == expected, "Platten-Apply fehlt")
                try await matrix("folder-applied", in: sheet, requiresDiff: false)
                try click("textWorkflowDiskUndo", in: sheet)
                try await wait { !session.isBusy && session.diskAppliedSession == nil && ws.tabs.first(where: { $0.url == one })?.content == original }
                try require(try String(contentsOf: one, encoding: .utf8) == original, "Platten-Rücknahme fehlt")
                stage = "Projekt"
                ws.projectURL = root
                session.projectSetID = ws.projectSearchConfiguration.activeSetID
                try await select("textWorkflowBatchScope", delta: 1, in: sheet)
                try require(session.scope == .project, "Projektbereich fehlt")
                try click("textWorkflowPreview", in: sheet)
                try await wait { session.canApply && session.batch?.entries.count == 2 }
                try await matrix("project", in: sheet)
                stage = "Fehler und Abbruch"
                try Data([0, 1, 2]).write(to: root.appendingPathComponent("binary.txt"))
                try click("textWorkflowPreview", in: sheet)
                try await wait { !session.isBusy && session.batch?.entries.count == 3 }
                try require(!session.canApply && session.batch?.entries.contains(where: { $0.issue != nil }) == true, "Fehlerhafte Vorschau gibt Apply frei")
                let errorID = session.batch!.entries.first(where: { $0.issue != nil })!.id
                try click("textWorkflowInput-" + errorID, in: sheet)
                try await matrix("project-error", in: sheet, requiresDiff: false)
                session.calculate(); session.abortCalculation()
                try await Task.sleep(for: .milliseconds(300))
                try require(!session.isBusy && session.batch == nil && !session.canApply, "Abbruch veröffentlichte alte Vorschau")
                try require(try String(contentsOf: one, encoding: .utf8) == original, "Abbruch hat Platte verändert")
                try click("textWorkflowClose", in: sheet)
                try await wait { ws.textWorkflowSession == nil && window.sheets.isEmpty }
                stage = "Einseitige Unicode-Zeilen"
                try await wait { CommandTargeting.editorTextView(for: ws)?.string == original }
                ws.presentTextWorkflows()
                try await wait { ws.textWorkflowSession != nil && !window.sheets.isEmpty }
                session = ws.textWorkflowSession!; sheet = window.sheets[0]
                var insertion = TextWorkflowStep(kind: .prefixLines)
                insertion.argument = "\u{200B}\r\n"
                session.new()
                session.definition = TextWorkflow(name: "Unicode Lines", steps: [insertion])
                try click("textWorkflowSave", in: sheet)
                try await wait { !session.dirty }
                try click("textWorkflowPreview", in: sheet)
                try await wait { session.canApply && session.representationDetails }
                try require(session.diffDocument?.result?.rows.contains(where: { ($0.before ?? $0.after ?? "").contains("\\u{200B}") }) == true
                            && session.diffDocument?.result?.rows.contains(where: { ($0.before ?? $0.after ?? "").contains("⟦CRLF⟧") }) == true,
                            "Einseitige unsichtbare Zeilen sind nicht annotiert")
                try await matrix("one-sided-unicode-lines", in: sheet)
                try require(try String(contentsOf: one, encoding: .utf8) == original, "Unicode-Vorschau hat Platte verändert")
                try click("textWorkflowClose", in: sheet)
                try await wait { ws.textWorkflowSession == nil && window.sheets.isEmpty }
                stage = "Lange nachträgliche Konfliktliste"
                let conflictRoot = base.appendingPathComponent("conflicts")
                try FileManager.default.createDirectory(at: conflictRoot, withIntermediateDirectories: true)
                var conflictIDs = Set<UUID>()
                for index in 0..<40 {
                    let name = "\(index)-" + String(repeating: "a", count: 180) + ".txt"
                    let url = conflictRoot.appendingPathComponent(name).canonicalFileURL
                    try Data("one".utf8).write(to: url)
                    var tab = EditorTab(title: name, path: url.path, url: url, content: "one")
                    tab.recordSavedContentBaseline()
                    conflictIDs.insert(tab.id); ws.tabs.append(tab)
                }
                ws.presentTextWorkflows()
                try await wait { ws.textWorkflowSession != nil && !window.sheets.isEmpty }
                session = ws.textWorkflowSession!; sheet = window.sheets[0]
                session.new()
                session.definition = TextWorkflow(name: "Conflict List", steps: [.init(kind: .uppercase)])
                session.folderURLs = [conflictRoot]
                try await select("textWorkflowBatchScope", delta: 2, in: sheet)
                try require(session.scope == .folder, "Konfliktprobe benötigt Ordnerbereich")
                try click("textWorkflowSave", in: sheet)
                try await wait { !session.dirty }
                try click("textWorkflowPreview", in: sheet)
                try await wait { session.canApply && session.batch?.entries.count == 40 }
                for index in ws.tabs.indices where conflictIDs.contains(ws.tabs[index].id) {
                    ws.tabs[index].content = "dirty"; ws.tabs[index].isDirty = true
                }
                try click("textWorkflowApply", in: sheet)
                try await wait { !session.isBusy && session.error != nil }
                try require(session.error?.contains("39-" + String(repeating: "a", count: 180) + ".txt") == true,
                            "Konfliktliste enthält nicht alle Eingaben")
                try await matrix("folder-conflicts-top", in: sheet, requiresDiff: false, errorAtEnd: false)
                try await matrix("folder-conflicts-end", in: sheet, requiresDiff: false, errorAtEnd: true)
                for tab in ws.tabs where conflictIDs.contains(tab.id) {
                    try require(try Data(contentsOf: tab.url!) == Data("one".utf8), "Konfliktprüfung hat Platte verändert")
                }
                try click("textWorkflowClose", in: sheet)
                try await wait { ws.textWorkflowSession == nil && window.sheets.isEmpty }
                ws.tabs.removeAll { conflictIDs.contains($0.id) }
                cleanup()
                finish(true, "Offene Dokumente, Ordner/Projekt, vollständige Vorschau, Schritte, Speicher-/Platten-Apply und geschützte Rücknahme, wirkungslose Fremdänderung, Fehler und Abbruch")
            } catch {
                if let current = ws.textWorkflowSession {
                    let inputs = current.batch?.entries.map { entry in
                        [entry.title, entry.id, entry.issue ?? "OK"].joined(separator: ":")
                    }.joined(separator: "|") ?? "nil"
                    let flags = "scope=\(current.scope) busy=\(current.isBusy) dirty=\(current.dirty) canApply=\(current.canApply)"
                    let selection = "selected=\(current.selectedInputID ?? "nil") preview=\(current.selectedPreview) diff=\(current.diffDocument?.result != nil)"
                    fputs("WORKFLOW-DIAG \(flags) \(selection) inputs=\(inputs)\n", stderr)
                    let project = current.workspace?.projectURL
                    let paths = current.workspace?.projectSearchConfiguration.activeSet?.paths.joined(separator: "|") ?? "nil"
                    fputs("WORKFLOW-SOURCE project=\(project?.path ?? "nil") standard=\(project?.standardizedFileURL.path ?? "nil") paths=\(paths)\n", stderr)
                }
                try? await capture("diagnose-failure", in: window.sheets.first ?? window)
                let foreground = NSWorkspace.shared.frontmostApplication
                let message = "Mehrdokumentabläufe [\(stage)]: \(error.localizedDescription); \(ws.textWorkflowSession?.error ?? ""); aktiv=\(NSApp.isActive), key=\(window.isKeyWindow), Sheetkey=\(window.sheets.first?.isKeyWindow == true), Frontmost=\(foreground?.bundleIdentifier ?? "nil")/\(foreground?.processIdentifier ?? -1)"
                ws.textWorkflowSession?.abortCalculation()
                try? await wait { ws.textWorkflowSession?.isBusy != true }
                cleanup()
                finish(false, message)
            }
        }
    }

    private static func runExistingFileSaveTest() {
        testLabel = "saveexisting"
        Task { @MainActor in
            guard let ws = Workspace.shared, let window = CommandTargeting.registeredWindow(for: ws),
                  let fixturePath = ProcessInfo.processInfo.environment["FASTRA_SAVEEXISTING_DIR"] else {
                finish(false, "Externe Bestandsdateien oder Dokumentfenster fehlen")
            }
            let base = URL(fileURLWithPath: fixturePath).canonicalFileURL
            let variants = ["clean", "stale", "corrupt", "directory", "symlink"]
            let baseline = "Bestand äöü 😀\n\nVor Ergebnis\n"
            let defaults = workspaceDefaults(), oldWarning = ws.saveSafetyWarningHandler
            let oldVisual = defaults.object(forKey: MarkdownEditingMode.defaultsKey)
            let oldPreview = defaults.object(forKey: "markdown.integratedPreview")
            var stage = "Extern vorbereitete Bestandsdateien", warning: String?, editDiagnostic = ""
            func require(_ value: Bool, _ message: String) throws {
                if !value { throw NSError(domain: "ExistingSaveSelfTest", code: 1, userInfo: [NSLocalizedDescriptionKey: message]) }
            }
            @MainActor func wait(_ condition: @MainActor () -> Bool) async throws {
                for _ in 0..<240 { if condition() { return }; try await Task.sleep(for: .milliseconds(50)) }
                try require(condition(), "Zustand nicht bereit: \(stage)")
            }
            @MainActor func webViews(_ root: NSView) -> [WKWebView] {
                if let web = root as? WKWebView { return [web] }
                return root.subviews.flatMap { webViews($0) }
            }
            @MainActor func open(_ file: URL, visual: Bool) async throws {
                defaults.set(visual, forKey: MarkdownEditingMode.defaultsKey)
                var loaded = false
                ws.loadFile(at: file) { loaded = $0 }
                try await wait { loaded && ws.activeTab?.url?.canonicalFileURL == file.canonicalFileURL }
                if visual { try await wait { ws.visualMarkdownEditor?.ready == true && ws.visualMarkdownEditor?.tabID == ws.activeTabID } }
                else { try await wait { CommandTargeting.editorTextView(for: ws)?.string == ws.activeTab?.content } }
            }
            @MainActor func renderedContains(_ web: WKWebView, _ text: String) async -> Bool {
                for _ in 0..<120 {
                    if let found = try? await web.callAsyncJavaScript("return !!document.body?.innerText.includes(text)",
                        arguments: ["text": text], in: nil, contentWorld: .page) as? Bool, found { return true }
                    try? await Task.sleep(for: .milliseconds(50))
                }
                return false
            }
            ws.saveSafetyWarningHandler = { warning = $0 + ": " + $1 }
            defaults.set(true, forKey: "markdown.integratedPreview")
            @MainActor func restoreState() {
                ws.saveSafetyWarningHandler = oldWarning
                defaults.set(oldVisual, forKey: MarkdownEditingMode.defaultsKey)
                defaults.set(oldPreview, forKey: "markdown.integratedPreview")
            }
            do {
                try require(base.lastPathComponent.hasPrefix("saveexisting."), "Unbekanntes Bestands-Testverzeichnis")
                // Diese Dateien stammen vom Runner vor dem App-Start; die App
                // darf sich ihre Ausgangsdatei hier nicht selbst erzeugen.
                for variant in variants {
                    for name in ["normal.txt", "preview.md", "visual.md"] {
                        try require(try String(contentsOf: base.appendingPathComponent(variant).appendingPathComponent(name), encoding: .utf8) == baseline,
                                    "Externe Ausgangsdatei fehlt oder wurde schon geändert: \(variant)/\(name)")
                    }
                }
                window.setContentSize(NSSize(width: 1100, height: 720))
                // Der letzte Tab schließt das Fenster. Ein nicht leerer
                // Anker hält es für das anschließende frische Öffnen bereit.
                let anchor = EditorTab(title: "Prüffenster.txt", path: "—", content: "Speicherprüfung")
                ws.tabs.append(anchor); ws.activeTabID = anchor.id
                activateApplication(ignoringOtherApps: true); window.makeKeyAndOrderFront(nil)
                try await wait { NSApp.isActive && window.isKeyWindow }
                let cases = variants.flatMap { variant in
                    [("normal.txt", false), ("preview.md", false), ("visual.md", true)].map { (variant, $0.0, $0.1) }
                }
                for (variant, name, visual) in cases {
                    let file = base.appendingPathComponent(variant).appendingPathComponent(name)
                    var expected = baseline, visualBeforeSave = ""
                    stage = "\(variant)/\(name): Öffnen"
                    try await open(file, visual: visual)
                    if variant == "clean" {
                        for (keyCode, modifiers, selected) in [
                            (UInt16(123), NSEvent.ModifierFlags([.command, .shift]), "Vor "),
                            (UInt16(124), NSEvent.ModifierFlags([.command, .shift]), "Ergebnis"),
                            (UInt16(124), NSEvent.ModifierFlags([.option, .shift]), "Ergebnis")
                        ] {
                            stage = "\(name): Zeilenauswahl Taste \(keyCode)"
                            let characters = keyCode == 123 ? "\u{F702}" : "\u{F703}"
                            if visual, let web = ws.visualMarkdownEditor?.web {
                                try require(window.makeFirstResponder(web), "WYSIWYG bekommt keinen Auswahlfokus")
                                _ = try await web.callAsyncJavaScript("""
                                    const root=document.querySelector('#fastra-visual'),walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
                                    let n;while(walker.nextNode()){if(walker.currentNode.data.includes('Vor Ergebnis')){n=walker.currentNode;break;}}
                                    root.focus();getSelection().collapse(n,n.data.indexOf('Ergebnis'));
                                    """, arguments: [:], in: nil, contentWorld: .page)
                                postKey(characters, keyCode: keyCode, windowNumber: window.windowNumber, modifiers: modifiers)
                                var actual = ""
                                for _ in 0..<120 {
                                    actual = try await web.evaluateJavaScript("getSelection().toString()") as? String ?? ""
                                    if actual == selected { break }
                                    try await Task.sleep(for: .milliseconds(50))
                                }
                                try require(actual == selected, "WYSIWYG-Auswahl stimmt nicht: \(String(reflecting: actual))")
                            } else if let editor = CommandTargeting.editorTextView(for: ws) {
                                try require(window.makeFirstResponder(editor), "Texteditor bekommt keinen Auswahlfokus")
                                let cursor = (editor.string as NSString).range(of: "Ergebnis").location
                                editor.selectionManager.setSelectedRange(NSRange(location: cursor, length: 0))
                                postKey(characters, keyCode: keyCode, windowNumber: window.windowNumber, modifiers: modifiers)
                                try await wait {
                                    let range = editor.fastraSafeSelectedRange
                                    return range.length > 0 && (editor.string as NSString).substring(with: range) == selected
                                }
                            } else { throw NSError(domain: "fixture", code: 5) }
                            try require(ws.activeTab?.isDirty == false, "Zeilenauswahl verändert das Dokument")
                            print("LINE_SELECTION mode=\(name) key=\(keyCode) modifiers=\(modifiers.rawValue) pass")
                        }
                    }
                    for round in 1...2 {
                        stage = "\(variant)/\(name): Runde \(round), Bearbeiten"
                        editDiagnostic = ""
                        let oldText = round == 1 ? "Ergebnis" : "Ergebnis Änderung 1"
                        let newText = "Ergebnis Änderung \(round)"
                        if visual {
                            guard let web = ws.visualMarkdownEditor?.web else { throw NSError(domain: "fixture", code: 1) }
                            try require(window.makeFirstResponder(web), "WYSIWYG bekommt keinen Fokus")
                            let edit = try await web.callAsyncJavaScript("""
                                const root=document.querySelector('#fastra-visual'),walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
                                let n;while(walker.nextNode()){if(walker.currentNode.data.includes(oldText)){n=walker.currentNode;break;}}
                                if(!n)throw Error('Ausgangstext fehlt');
                                root.focus();
                                const r=document.createRange(),start=n.data.indexOf(oldText);r.setStart(n,start);r.setEnd(n,start+oldText.length);
                                getSelection().removeAllRanges();getSelection().addRange(r);const applied=document.execCommand('insertText',false,newText);
                                fastraVisual.flush();
                                return JSON.stringify({applied,markdown:fastraVisual.markdown(),html:root.innerHTML});
                                """, arguments: ["oldText": oldText, "newText": newText], in: nil, contentWorld: .page)
                            editDiagnostic = String(describing: edit)
                        } else {
                            guard let editor = CommandTargeting.editorTextView(for: ws) else { throw NSError(domain: "fixture", code: 2) }
                            try require(window.makeFirstResponder(editor), "Texteditor bekommt keinen Fokus")
                            let range = (editor.string as NSString).range(of: oldText)
                            try require(range.location != NSNotFound, "Ausgangstext fehlt im sichtbaren Editor")
                            editor.selectionManager.setSelectedRange(range); editor.insertText(newText, replacementRange: range)
                        }
                        expected = expected.replacingOccurrences(of: oldText, with: newText)
                        try await wait { ws.activeTab?.isDirty == true && ws.activeTab?.content == expected }
                        if visual, let web = ws.visualMarkdownEditor?.web {
                            visualBeforeSave = try await web.evaluateJavaScript("document.querySelector('#fastra-visual').innerText") as? String ?? ""
                        }
                        stage = "\(variant)/\(name): Runde \(round), ⌘S"
                        warning = nil
                        postCmd("s", keyCode: 1, windowNumber: window.windowNumber)
                        try await wait { warning != nil || ws.activeTab?.isDirty == false }
                        try require(warning == nil, warning ?? "")
                        try require(try Data(contentsOf: file) == Data(expected.utf8), "Plattenbytes weichen nach ⌘S ab")
                        let id = ws.activeTabID!
                        let oldWeb = ws.visualMarkdownEditor?.web
                        ws.closeTab(id: id)
                        try await wait { !ws.tabs.contains { $0.id == id } }
                        stage = "\(variant)/\(name): Runde \(round), frisch Öffnen"
                        try await open(file, visual: visual)
                        try require(ws.activeTabID != id && ws.activeTab?.content == expected && ws.activeTab?.isDirty == false,
                                    "Frisch geöffneter Tab zeigt nicht den gespeicherten Inhalt")
                        if visual {
                            guard let web = ws.visualMarkdownEditor?.web else { throw NSError(domain: "fixture", code: 3) }
                            try require(web !== oldWeb, "Alter WYSIWYG-Editor wurde wiederverwendet")
                            let visible = try await web.evaluateJavaScript("document.querySelector('#fastra-visual').innerText") as? String
                            try require(visible == visualBeforeSave, "Sichtbarer WYSIWYG-Inhalt verändert sich nach Speichern und Öffnen")
                            try require(try await web.evaluateJavaScript("document.querySelector('#fastra-visual').textContent.includes('Änderung \(round)')") as? Bool == true,
                                        "WYSIWYG zeigt die gespeicherte Änderung nicht")
                        } else {
                            try require(CommandTargeting.editorTextView(for: ws)?.string == expected, "Texteditor zeigt veraltete Daten")
                            if name == "preview.md" {
                                guard let root = window.contentView, let preview = webViews(root).first else { throw NSError(domain: "fixture", code: 4) }
                                try await wait { !preview.isLoading }
                                try require(await renderedContains(preview, "Änderung \(round)"),
                                            "Markdown-Vorschau zeigt die gespeicherte Änderung nicht")
                            }
                        }
                        if variant == "clean", round == 2,
                           let path = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] {
                            let image = URL(fileURLWithPath: path).appendingPathComponent("saveexisting-\(name).png")
                            try FileManager.default.createDirectory(at: image.deletingLastPathComponent(), withIntermediateDirectories: true)
                            await withCheckedContinuation { (done: CheckedContinuation<Void, Never>) in
                                typeScrollCapture(window: window) { snapshot in try? snapshot?.data.write(to: image); done.resume() }
                            }
                        }
                        print("SAVEEXISTING variant=\(variant) mode=\(name) round=\(round) reopened=pass")
                    }
                    if let id = ws.activeTabID { ws.closeTab(id: id); try await wait { !ws.tabs.contains { $0.id == id } } }
                }
                restoreState()
                window.orderOut(nil)
                finish(true, "Fünf Temp-Dateizustände in Normal, Markdown-Vorschau und WYSIWYG je zweimal an Bestandsdateien bearbeitet, per ⌘S gespeichert und frisch geöffnet; Plattenbytes und sichtbarer Inhalt stimmen")
            } catch {
                restoreState()
                window.orderOut(nil)
                finish(false, stage + ": " + error.localizedDescription + "\nModell: " + (ws.activeTab?.content ?? "nil") + "\nEingabe: " + editDiagnostic)
            }
        }
    }

    private static func runTextWorkflowTest() {
        testLabel = "textworkflow"
        Task { @MainActor in
            guard let ws = Workspace.shared, let window = CommandTargeting.registeredWindow(for: ws) else { finish(false, "Dokumentfenster fehlt") }
            let source = "b  \na  \n", expected = "B\nA\n"
            let base = selfTestTemporaryDirectory().appendingPathComponent("TextWorkflow-\(UUID().uuidString)")
            let file = base.appendingPathComponent("Ablauf.txt")
            var stage = "Vorbereitung"
            var diagnostics = [String]()
            let keyMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
                diagnostics.append("Taste: \(event.keyCode), Modifier: \(event.modifierFlags.rawValue), Zeichen: \(event.characters ?? ""), Fenster: \(event.windowNumber)")
                return event
            }
            var trackingMenus = Set<ObjectIdentifier>()
            let menus = NotificationCenter.default.addObserver(forName: NSMenu.didBeginTrackingNotification, object: nil, queue: .main) { notification in
                if let menu = notification.object as? NSMenu {
                    trackingMenus.insert(ObjectIdentifier(menu))
                    diagnostics.append("Menü beginnt \(ObjectIdentifier(menu)): \(menu.title), Einträge=\(menu.items.prefix(5).map { "\($0.title) [\($0.state.rawValue)]" })")
                }
            }
            let menusEnded = NotificationCenter.default.addObserver(forName: NSMenu.didEndTrackingNotification, object: nil, queue: .main) { notification in
                if let menu = notification.object as? NSMenu {
                    trackingMenus.remove(ObjectIdentifier(menu))
                    diagnostics.append("Menü endet \(ObjectIdentifier(menu)): \(menu.title)")
                }
            }
            @MainActor func diagnose(_ label: String) {
                let editor = CommandTargeting.editorTextView(for: ws)
                diagnostics.append("Fensterbindung: Key=\(NSApp.keyWindow?.windowNumber ?? -1), Dokument=\(window.windowNumber), Sheet-Keys=\(window.sheets.map { "\($0.windowNumber):\($0.isKeyWindow)" }), offene Menüs=\(trackingMenus.map { String(describing: $0) }.sorted())")
                if let session = ws.textWorkflowSession {
                    diagnostics.append("Modell: Vorschau=\(session.selectedPreview), canApply=\(session.canApply), dirty=\(session.dirty), busy=\(session.isBusy), diff=\(session.diffDocument != nil), revision=\(session.snapshot.revision)/\(ws.activeTab?.contentRevision ?? 0)")
                    diagnostics.append("Ablaufname: \(String(reflecting: session.definition.name)); gespeicherte Namen: \(session.saved.map { String(reflecting: $0.name) }); Store: \((try? TextWorkflowStore().load().map { String(reflecting: $0.name) }) ?? [])")
                }
                diagnostics.append("Auswahl: Editor=\(String(describing: editor?.fastraSafeSelectedRange)), Snapshot=\(String(describing: ws.textWorkflowSession?.snapshot.selection)), nurAuswahl=\(ws.textWorkflowSession?.selectionOnly == true)")
                diagnostics.append("\(label): aktiv=\(NSApp.isActive), key=\(window.isKeyWindow), Sheets=\(window.sheets.count), Responder=\(String(describing: window.firstResponder)), Editor=\(String(describing: editor)), Undo=\(editor?.undoManager?.canUndo == true), Redo=\(editor?.undoManager?.canRedo == true), Undoziel=\(String(describing: NSApp.target(forAction: NSSelectorFromString("undo:")))), Redoziel=\(String(describing: NSApp.target(forAction: NSSelectorFromString("redo:")))), Text=\(String(reflecting: ws.activeTab?.content))")
            }
            func require(_ value: Bool, _ text: String) throws {
                if !value { throw NSError(domain: "TextWorkflowSelfTest", code: 1, userInfo: [NSLocalizedDescriptionKey: text]) }
            }
            @MainActor func wait(_ condition: @MainActor () -> Bool) async throws {
                for _ in 0..<250 { if condition() { return }; try await Task.sleep(for: .milliseconds(50)) }
                try require(condition(), "Zustand wurde nicht bereit")
            }
            @MainActor func click(_ id: String, in target: NSWindow) -> Bool {
                guard let root = target.contentView, let marker = markerView(id: id, in: root) else { return false }
                let rect = marker.convert(marker.bounds, to: nil)
                let point = NSPoint(x: rect.midX, y: rect.midY)
                var hit = root.hitTest(root.convert(point, from: nil))
                var chain = [String]()
                while let view = hit, chain.count < 5 { chain.append(String(describing: type(of: view))); hit = view.superview }
                diagnostics.append("Klick \(id): Punkt=\(point), Marker=\(rect), Treffer=\(chain)")
                return sendMouseClick(at: point, in: target, modifiers: [], viaApp: true)
            }
            @MainActor func requirePreviewVisible(in target: NSWindow) async throws {
                try await wait {
                    guard let root = target.contentView, let viewport = markerView(id: "dualPaneDiffViewport", in: root) else { return false }
                    let visible = viewport.convert(viewport.bounds, to: root).intersection(root.bounds)
                    return visible.height >= 66
                }
            }
            @MainActor func capture(_ name: String, in target: NSWindow) async {
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] else { return }
                let url = URL(fileURLWithPath: directory).appendingPathComponent(name + ".png")
                try? FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                await withCheckedContinuation { (done: CheckedContinuation<Void, Never>) in
                    typeScrollCapture(window: target) { snapshot in try? snapshot?.data.write(to: url); done.resume() }
                }
            }
            @MainActor func openMenu() async throws {
                try await trackedMainMenuItem(rootTitle: L10n.string("Text"),
                    label: L10n.string("Gespeicherte Textabläufe…"), ticks: 100, pause: 0.05) { menu in
                    menu.items.first { $0.title == L10n.string("Gespeicherte Textabläufe…") }
                }
            }
            do {
                try FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
                try source.write(to: file, atomically: true, encoding: .utf8)
                var loaded = false
                ws.loadFile(at: file) { loaded = $0 }
                window.setContentSize(NSSize(width: 1100, height: 700))
                NSApp.appearance = NSAppearance(named: .aqua)
                activateApplication(ignoringOtherApps: true); window.makeKeyAndOrderFront(nil)
                try await wait { loaded && CommandTargeting.editorTextView(for: ws)?.string == source }
                stage = "Echtes Textmenü"
                try await openMenu()
                try await wait { ws.textWorkflowSession != nil && !window.sheets.isEmpty }
                let sheet = window.sheets[0], session = ws.textWorkflowSession!
                stage = "Name eingeben"
                try require(click("textWorkflowName", in: sheet), "Namensfeld fehlt")
                try await wait { (sheet.firstResponder as? NSTextView)?.isFieldEditor == true }
                guard let field = sheet.firstResponder as? NSTextView else { throw NSError(domain: "TextWorkflowSelfTest", code: 3) }
                field.selectAll(nil); field.insertText("Native Workflow 😀", replacementRange: NSRange(location: 0, length: field.string.utf16.count))
                try await wait { session.definition.name == "Native Workflow 😀" }
                stage = "Schritt hinzufügen"
                var chosen = false
                var menuTimer: Timer?
                let observer = NotificationCenter.default.addObserver(forName: NSMenu.didBeginTrackingNotification, object: nil, queue: .main) { notification in
                    guard let menu = notification.object as? NSMenu else { return }
                    var ticks = 0
                    menuTimer?.invalidate()
                    menuTimer = Timer(timeInterval: 0.05, repeats: true) { _ in
                        ticks += 1
                        if let item = menu.items.first(where: { $0.title == TextOpKind.uppercase.title }), item.isEnabled {
                            menuTimer?.invalidate(); menuTimer = nil
                            chosen = true
                            _ = item.accessibilityPerformPress()
                        } else if ticks >= 200 { menuTimer?.invalidate(); menuTimer = nil; menu.cancelTracking() }
                    }
                    if let menuTimer { RunLoop.main.add(menuTimer, forMode: .common); RunLoop.main.add(menuTimer, forMode: .eventTracking) }
                }
                try require(click("textWorkflowAddStep", in: sheet), "Schritte-Menü fehlt")
                try await wait { chosen && session.definition.steps.count == 2 }
                NotificationCenter.default.removeObserver(observer)
                try require(click("textWorkflowSave", in: sheet), "Speichern fehlt")
                try await wait { !session.dirty && session.saved.count == 1 }
                stage = "Vorschau"
                try require(click("textWorkflowPreview", in: sheet), "Vorschaubutton fehlt")
                try await wait { session.canApply && session.preview?.output == expected }
                try require(ws.activeTab?.content == source && (try? String(contentsOf: file, encoding: .utf8)) == source, "Vorschau schreibt vor Apply")
                try await requirePreviewVisible(in: sheet)
                await capture("workflow-light-wide", in: sheet)
                stage = "Schrittvorschau"
                try require(click("textWorkflowPreviewChoice", in: sheet), "Vorschau-Auswahl fehlt")
                try await Task.sleep(for: .milliseconds(350))
                postKey("\u{F701}", keyCode: 125, windowNumber: sheet.windowNumber)
                postKey("\r", keyCode: 36, windowNumber: sheet.windowNumber)
                try await wait { session.selectedPreview == 0 && session.diffDocument != nil }
                try require(!session.canApply, "Zwischenergebnis darf nicht als Gesamtergebnis angewendet werden")
                try await requirePreviewVisible(in: sheet)
                await capture("workflow-step-preview", in: sheet)
                stage = "Schrittmenü vollständig geschlossen"
                try await wait { trackingMenus.isEmpty && sheet.isKeyWindow && NSApp.isActive }
                // Der native Pop-up-Button nimmt während seiner Schließanimation
                // noch keinen zweiten Klick an. Die schnelle Mini-Vorschau kann
                // ihren Diff vorher bereits geliefert haben.
                try await Task.sleep(for: .milliseconds(400))
                stage = "Gesamtergebnis über sichtbaren Menüeintrag"
                diagnose("Vor Rückwechsel zur Gesamtvorschau")
                try require(click("textWorkflowPreviewChoice", in: sheet), "Gesamtergebnis-Auswahl fehlt")
                try await Task.sleep(for: .milliseconds(350))
                postKey("\u{F700}", keyCode: 126, windowNumber: sheet.windowNumber)
                postKey("\r", keyCode: 36, windowNumber: sheet.windowNumber)
                try await wait { session.selectedPreview == -1 && session.canApply }
                for (name, appearance, width) in [
                    ("workflow-light-minimum", NSAppearance.Name.aqua, CGFloat(900)),
                    ("workflow-dark-wide", NSAppearance.Name.darkAqua, CGFloat(1100)),
                    ("workflow-dark-minimum", NSAppearance.Name.darkAqua, CGFloat(900))
                ] {
                    NSApp.appearance = NSAppearance(named: appearance)
                    sheet.setContentSize(NSSize(width: width, height: 760))
                    try await Task.sleep(for: .milliseconds(300))
                    try await requirePreviewVisible(in: sheet)
                    await capture(name, in: sheet)
                }
                stage = "Apply und natives Undo"
                try require(click("textWorkflowApply", in: sheet), "Apply fehlt")
                try await wait { ws.textWorkflowSession == nil && ws.activeTab?.content == expected }
                try require((try? String(contentsOf: file, encoding: .utf8)) == source, "Apply schreibt ungefragt auf Platte")
                stage = "Dokument: normalen Editorfokus nach Sheet prüfen"
                try await wait {
                    guard window.sheets.isEmpty, window.isKeyWindow,
                          let editor = CommandTargeting.editorTextView(for: ws) else { return false }
                    return window.firstResponder === editor && editor.string == expected
                }
                guard let editor = CommandTargeting.editorTextView(for: ws) else { throw NSError(domain: "TextWorkflowSelfTest", code: 4) }
                diagnose("Vor nativem Undo ohne Fokuskorrektur")
                stage = "Dokument: natives Undo"
                postHistoryKey(windowNumber: window.windowNumber)
                try await wait { ws.activeTab?.content == source }
                diagnose("Nach nativem Undo")
                stage = "Dokument: natives Redo"
                try await wait { editor.undoManager?.canRedo == true }
                try await redoFromEditMenu()
                try await wait { ws.activeTab?.content == expected }
                try await Task.sleep(for: .milliseconds(300))
                await capture("workflow-after-redo", in: window)
                ws.saveActiveTab()
                try await wait { ws.activeTab?.isDirty == false && (try? String(contentsOf: file, encoding: .utf8)) == expected }
                stage = "Gespeicherten Ablauf erneut öffnen"
                diagnose("Vor erneutem Öffnen")
                try await openMenu()
                diagnose("Nach erneutem Öffnen")
                try await wait { ws.textWorkflowSession?.definition.name == "Native Workflow 😀" && !window.sheets.isEmpty }
                try require(ws.textWorkflowSession?.definition.steps.count == 2, "Gespeicherte Schritte fehlen")
                stage = "Gespeicherten Ablauf schließen"
                diagnose("Vor Schließbereitschaft")
                try await wait {
                    stage = trackingMenus.isEmpty
                        ? "Gespeicherten Ablauf schließen: Sheet-Key"
                        : "Gespeicherten Ablauf schließen: Menüende"
                    return trackingMenus.isEmpty && window.sheets.first?.isKeyWindow == true
                }
                try require(window.sheets[0].contentView.map { markerViewExists(id: "textWorkflowClose", in: $0) } == true, "Schließen fehlt")
                // Das sichtbare Schließen-Kürzel prüft den nativen Cancel-Pfad;
                // ein synthetischer Mausklick konnte hier noch die Menüanimation treffen.
                stage = "Gespeicherten Ablauf schließen: Escape senden"
                diagnose("Vor Escape")
                postKey("\u{1b}", keyCode: 53, windowNumber: window.sheets[0].windowNumber, modifiers: [])
                stage = "Gespeicherten Ablauf schließen: Escape abgeschlossen"
                try await wait { ws.textWorkflowSession == nil && window.sheets.isEmpty && window.isKeyWindow }
                stage = "Datei schließen und erneut öffnen"
                let closedID = ws.activeTabID!
                ws.openNewTab()
                try await wait { ws.activeTabID != closedID }
                ws.closeTab(id: closedID)
                try await wait { !ws.tabs.contains(where: { $0.id == closedID }) }
                loaded = false
                ws.loadFile(at: file) { loaded = $0 }
                try await wait { loaded && ws.activeTab?.content == expected && CommandTargeting.editorTextView(for: ws)?.string == expected }
                stage = "Auswahl: Editor nach Wiederöffnen bereit"
                try await wait { window.sheets.isEmpty && window.isKeyWindow }
                try await Task.sleep(for: .milliseconds(300))
                guard let selectionEditor = CommandTargeting.editorTextView(for: ws) else { throw NSError(domain: "TextWorkflowSelfTest", code: 5) }
                try require(window.makeFirstResponder(selectionEditor), "Auswahleditor nahm keinen Fokus an")
                selectionEditor.insertText("b", replacementRange: NSRange(location: 0, length: 1))
                let selectionSource = "b\nA\n"
                try await wait { ws.activeTab?.content == selectionSource }
                try await Task.sleep(for: .milliseconds(300))
                try require(CommandTargeting.editorTextView(for: ws) === selectionEditor, "Editor wurde während der Auswahlvorbereitung ersetzt")
                selectionEditor.selectionManager.setSelectedRange(NSRange(location: 0, length: 0))
                stage = "Auswahl: echte Shift-Pfeiltaste"
                postKey("\u{F703}", keyCode: 124, windowNumber: window.windowNumber, modifiers: .shift)
                try await wait { selectionEditor.fastraSafeSelectedRange == NSRange(location: 0, length: 1) }
                diagnose("Vor Öffnen der Auswahlvorschau")
                stage = "Auswahl: Snapshot im nativen Dialog"
                try await openMenu()
                try await wait { ws.textWorkflowSession?.snapshot.selection == NSRange(location: 0, length: 1) && !window.sheets.isEmpty }
                let selectionSheet = window.sheets[0], selectionSession = ws.textWorkflowSession!
                func segmentedControl(in view: NSView) -> NSSegmentedControl? {
                    if let control = view as? NSSegmentedControl, control.segmentCount == 2 { return control }
                    return view.subviews.lazy.compactMap { segmentedControl(in: $0) }.first
                }
                guard let root = selectionSheet.contentView, let control = segmentedControl(in: root) else { throw NSError(domain: "TextWorkflowSelfTest", code: 6) }
                let point = control.convert(NSPoint(x: control.bounds.width * 0.75, y: control.bounds.midY), to: nil)
                try require(sendMouseClick(at: point, in: selectionSheet, modifiers: [], viaApp: true), "Auswahlsegment nicht bedienbar")
                stage = "Auswahl: Wirkbereich umschalten"
                try await wait { selectionSession.selectionOnly }
                stage = "Auswahl: Vorschau berechnen"
                try require(click("textWorkflowPreview", in: selectionSheet), "Auswahlvorschau fehlt")
                try await wait { selectionSession.canApply && selectionSession.preview?.output == expected }
                try require(ws.activeTab?.content == selectionSource, "Auswahlvorschau verändert das Dokument")
                try await requirePreviewVisible(in: selectionSheet)
                await capture("workflow-selection-preview", in: selectionSheet)
                try require(click("textWorkflowApply", in: selectionSheet), "Auswahl anwenden fehlt")
                try await wait { ws.textWorkflowSession == nil && ws.activeTab?.content == expected }
                try await wait { window.sheets.isEmpty && window.isKeyWindow }
                try require(window.makeFirstResponder(selectionEditor), "Auswahleditor nahm nach dem Sheet keinen Fokus an")
                stage = "Auswahl: natives Undo"
                postHistoryKey(windowNumber: window.windowNumber)
                try await wait { ws.activeTab?.content == selectionSource }
                try require((try? String(contentsOf: file, encoding: .utf8)) == expected, "Auswahl-Apply oder Undo schreibt ungefragt auf Platte")
                if let keyMonitor { NSEvent.removeMonitor(keyMonitor) }
                NotificationCenter.default.removeObserver(menus)
                NotificationCenter.default.removeObserver(menusEnded)
                finish(true, "Echtes Textmenü, Name, Schritte-Menü, Speichern, native Schritt-/Endvorschau, Dokument/Auswahl, Apply, natives Undo/Redo, Datei speichern, schließen/wiederöffnen und Ablauf neu laden; hell/dunkel bei Mindestgröße und breit geprüft")
            } catch {
                diagnose("Fehler")
                if stage == "Dokument: natives Redo" {
                    diagnostics.append("Direkte native Redo-Aktion: \(NSApp.sendAction(NSSelectorFromString("redo:"), to: nil, from: nil))")
                    try? await Task.sleep(for: .milliseconds(300))
                    diagnose("Nach direkter nativer Redo-Aktion")
                }
                fputs((diagnostics.joined(separator: "\n") + "\n").cString(using: .utf8)!, stderr)
                if let keyMonitor { NSEvent.removeMonitor(keyMonitor) }
                NotificationCenter.default.removeObserver(menus)
                NotificationCenter.default.removeObserver(menusEnded)
                await capture("workflow-failure", in: window.sheets.first ?? window)
                finish(error is SelfTestMenuRootExchange.EnvironmentFailure ? .environment : .fail,
                       "Textabläufe [\(stage)]: \(error.localizedDescription); Fehler=\(ws.textWorkflowSession?.error ?? "keiner")")
            }
        }
    }

    private static func runTextOpTest() {
        testLabel = "textop"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)

        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-textop-\(UUID().uuidString).txt")
        do {
            try "beta\nalpha\ngamma\n".write(
                to: tmp, atomically: true, encoding: .utf8
            )
        }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.9) {
                guard let tv = editorTextView(in: root) as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                _ = mainWindow.makeFirstResponder(tv)
                // Keine Selektion → ganze Datei. Posten wie das „Text"-Menü.
                NotificationCenter.default.post(name: .fastraTextOp,
                                                object: TextOpKind.uppercase.rawValue)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                    guard tv.string == "BETA\nALPHA\nGAMMA\n" else {
                        finish(false, "Großschreibung erreichte den echten Editor nicht")
                    }
                    NotificationCenter.default.post(
                        name: .fastraSortLines,
                        object: LineOperations.SortDirection.ascending.rawValue
                    )
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                        guard tv.string == "ALPHA\nBETA\nGAMMA\n" else {
                            finish(false, "aufsteigende Sortierung: \(tv.string.debugDescription)")
                        }
                        NotificationCenter.default.post(
                            name: .fastraSortLines,
                            object: LineOperations.SortDirection.descending.rawValue
                        )
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                            let expected = "GAMMA\nBETA\nALPHA\n"
                            guard tv.string == expected else {
                                finish(false, "absteigende Sortierung: "
                                    + "\(tv.string.debugDescription)")
                            }
                            checkEmojiPresentationTextOp(tv: tv)
                        }
                    }
                }
            }
        }
    }

    /// Letzter `textop`-Schritt: „Emoji-Darstellung erzwingen“ und Undo über den
    /// Menüweg am echten Editor prüfen. `⏸` soll geändert werden, das Kontrollzeichen
    /// bleibt unangetastet.
    private static func checkEmojiPresentationTextOp(tv: TextView) {
        let source = "Pause \u{23F8} und \u{00A9} 2026\n"
        tv.selectionManager.setSelectedRange(
            NSRange(location: 0, length: (tv.string as NSString).length)
        )
        tv.insertText(source, replacementRange: NSRange(location: NSNotFound, length: 0))
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
            tv.selectionManager.setSelectedRange(NSRange(location: 0, length: 0))
            NotificationCenter.default.post(
                name: .fastraTextOp,
                object: TextOpKind.addEmojiPresentation.rawValue
            )
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                let expected = "Pause \u{23F8}\u{FE0F} und \u{00A9} 2026\n"
                guard tv.string == expected else {
                    finish(false, "Emoji-Darstellung erzwingen erreichte den "
                        + "Editor nicht: \(tv.string.debugDescription)")
                }
                NotificationCenter.default.post(
                    name: .fastraTextOp,
                    object: TextOpKind.removeEmojiPresentation.rawValue
                )
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                    finish(tv.string == source,
                           "Text-Op, beide Sortierrichtungen und die "
                            + "Emoji-Darstellung (hin und zurück) im echten Editor")
                }
            }
        }
    }

    // MARK: - -selftest joinundo

    /// Regression für den konkret gemeldeten Fall: Eine per Cmd+A vollständig
    /// ausgewählte CSS-Datei wird ohne Soft Wrap verbunden. Die Vollauswahl
    /// darf danach weder den Editor leerräumen noch nach Undo einen leeren
    /// Bildschirm oberhalb von Zeile 1 hinterlassen. Der Modelltext allein
    /// reicht als Prüfung nicht, weil er beim ursprünglichen Fehler jederzeit
    /// vollständig war.
    private static func runJoinUndoTest() {
        testLabel = "joinundo"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }

        var lines = (1...12).flatMap { index in
            [
                ".c\(index) {",
                "  color: #123456;",
                "  margin: \(index)px;",
                "}",
                ""
            ]
        }
        lines.append("/* Ende */")
        let content = lines.joined(separator: "\n")
        let fullSelection = NSRange(
            location: 0,
            length: (content as NSString).length
        )
        let joined = TextOperations.joinLines(
            in: content,
            selection: fullSelection
        )?.newText
        guard let joined else {
            finish(false, "Join-Lines-Fixture lieferte kein Ergebnis")
        }
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-joinundo-\(UUID().uuidString).css")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                guard let tv = editorTextView(in: root) as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                tv.layoutManager.wrapLines = false
                tv.selectAll(nil)
                tv.layoutManager.layoutLines()
                NotificationCenter.default.post(
                    name: .fastraTextOp,
                    object: TextOpKind.joinLines.rawValue
                )

                DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                    let joinedVisible = visibleTextFragmentCount(in: tv)
                    let joinedSelection = tv.selectedRange()
                    let joinedTextCorrect = tv.string == joined

                    tv.undoManager?.undo()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                        let undoVisible = visibleTextFragmentCount(in: tv)
                        let undoSelection = tv.selectedRange()
                        let undoTextCorrect = tv.string == content
                        tv.undoManager?.redo()
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                            let redoVisible = visibleTextFragmentCount(in: tv)
                            let redoSelection = tv.selectedRange()
                            let redoTextCorrect = tv.string == joined
                            let ok = joinedTextCorrect
                                && joinedVisible > 0
                                && joinedSelection == NSRange(location: 0, length: 0)
                                && undoTextCorrect
                                && undoVisible > 0
                                && undoSelection == NSRange(location: 0, length: 0)
                                && redoTextCorrect
                                && redoVisible > 0
                                && redoSelection == NSRange(location: 0, length: 0)
                            finish(
                                ok,
                                "Join: Text=\(joinedTextCorrect), sichtbare Fragmente="
                                    + "\(joinedVisible), Auswahl=\(joinedSelection), Zeichen="
                                    + "\((content as NSString).length); "
                                    + "Undo: Text=\(undoTextCorrect), sichtbare Fragmente="
                                    + "\(undoVisible), Auswahl=\(undoSelection); "
                                    + "Redo: Text=\(redoTextCorrect), sichtbare Fragmente="
                                    + "\(redoVisible), Auswahl=\(redoSelection)"
                            )
                        }
                    }
                }
            }
        }
    }

    /// Zählt echte, nicht geparkte Text-Views im sichtbaren Editorbereich.
    /// Das ist unabhängig von `rectForOffset`: genau die war bei früheren
    /// Layoutfehlern trotz leerer Darstellung scheinbar plausibel.
    private static func visibleTextFragmentCount(in textView: TextView) -> Int {
        var fragments: [LineFragmentView] = []
        func collect(_ view: NSView) {
            if let fragment = view as? LineFragmentView {
                fragments.append(fragment)
            }
            view.subviews.forEach(collect)
        }
        collect(textView)
        return fragments.filter {
            !$0.isHidden
                && $0.frame != .zero
                && ($0.lineFragment?.documentRange.length ?? 0) > 0
                && ($0.lineFragment?.contents.reduce(0) {
                    $0 + $1.length
                } ?? 0) > 0
                && $0.frame.intersects(textView.visibleRect)
        }.count
    }

    // MARK: - -selftest colsel

    /// Verifiziert den öffentlichen Option-Drag-Pfad ohne Soft Wrap. Die
    /// Punkt-API ist exakt dieselbe, die `mouseDragged` verwendet; geprüft
    /// werden nicht nur mehrere Cursor, sondern die exakten Teilbereiche.
    private static func runColumnSelectionTest() {
        testLabel = "colsel"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        activateApplication(ignoringOtherApps: true)
        mainWindow.makeKeyAndOrderFront(nil)

        // Gleich lange Zeilen (Monospace) → saubere Spalten.
        let content = "ABCDEFGH\nABCDEFGH\nABCDEFGH\nABCDEFGH"
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-colsel-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.9) {
                guard let tv = editorTextView(in: root) as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                tv.layoutManager.wrapLines = false
                tv.layoutSubtreeIfNeeded()
                // Offset 2 = Zeile 0, Spalte 2. Offset 32 = Zeile 3, Spalte 5
                // (je Zeile 8 Zeichen + \n = 9; 3*9 + 5 = 32).
                guard let rA = tv.layoutManager.rectForOffset(2),
                      let rB = tv.layoutManager.rectForOffset(32) else {
                    finish(false, "rectForOffset nil (Layout noch nicht bereit?)")
                }
                let pA = CGPoint(x: rA.minX, y: rA.midY)
                let pB = CGPoint(x: rB.minX, y: rB.midY)
                tv.selectColumns(betweenPointA: pA, pointB: pB)
                let snapshot = tv.fastraColumnSelectionSnapshot
                let values = snapshot?.ranges.map {
                    (tv.string as NSString).substring(with: $0)
                }
                let ok = snapshot?.lineIndices == [0, 1, 2, 3]
                    && snapshot?.lowerColumn == 2
                    && snapshot?.upperColumn == 5
                    && values == ["CDE", "CDE", "CDE", "CDE"]
                finish(ok,
                       "Option-Drag: Zeilen=\(snapshot?.lineIndices ?? []), "
                       + "Spalten=\(snapshot?.lowerColumn ?? -1)…"
                       + "\(snapshot?.upperColumn ?? -1), Werte=\(values ?? [])")
            }
        }
    }

    // MARK: - -selftest colselwrap

    /// Soft Wrap darf keine zusätzliche Rechteckzeile erzeugen. Der Test
    /// umfasst kurze/leere Zeilen, Tabs, CRLF und zusammengesetzte Grapheme;
    /// Vorwärts- und Rückwärtsauswahl müssen dieselben logischen Zeilen treffen.
    private static func runWrappedColumnSelectionTest() {
        testLabel = "colselwrap"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }

        let lines = [
            "abCDE" + String(repeating: " langeZeile", count: 12),
            "xy",
            "",
            "\tABCD",
            "ab👩‍💻e\u{301}Z",
        ]
        let content = lines.joined(separator: "\r\n")
        var starts: [Int] = []
        var offset = 0
        for (index, line) in lines.enumerated() {
            starts.append(offset)
            offset += (line as NSString).length
            if index < lines.count - 1 { offset += 2 }
        }
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-colselwrap-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.9) {
                guard let tv = editorTextView(in: root) as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                let charWidth = max(
                    (" " as NSString).size(withAttributes: [
                        .font: tv.font,
                        .kern: tv.kern,
                    ]).width,
                    1
                )
                tv.layoutManager.wrapLines = true
                tv.layoutManager.maximumWrapWidth = charWidth * 9
                tv.layoutManager.layoutLines()

                let firstFragments = Array(tv.layoutManager.lineStorage)
                    .first.map { Array($0.data.lineFragments).count } ?? 0
                tv.selectionManager.setSelectedRange(
                    NSRange(location: starts[0] + 2, length: 3)
                )
                for _ in 1..<lines.count {
                    guard tv.fastraSelectColumn(upwards: false) else {
                        finish(false, "Select Down endete vor der letzten logischen Zeile")
                    }
                }
                guard let forward = tv.fastraColumnSelectionSnapshot else {
                    finish(false, "Vorwärtsauswahl lieferte keinen Rechteckzustand")
                }
                let values = forward.ranges.map {
                    (tv.string as NSString).substring(with: $0)
                }
                let expectedValues = ["CDE", "", "", "\tA", "👩‍💻e\u{301}Z"]
                let textBefore = tv.string
                let rangesBefore = forward.ranges

                // Dieselbe Geometrie rückwärts aufbauen. Der letzte echte
                // Teilbereich ist graphem-sicher und bestimmt wieder Spalte 2…5.
                tv.selectionManager.setSelectedRange(forward.ranges[4])
                for _ in 1..<lines.count {
                    guard tv.fastraSelectColumn(upwards: true) else {
                        finish(false, "Select Up endete vor der ersten logischen Zeile")
                    }
                }
                guard let reverse = tv.fastraColumnSelectionSnapshot else {
                    finish(false, "Rückwärtsauswahl lieferte keinen Rechteckzustand")
                }

                // Wrap-Ziel ändern und Wrap kurz aus-/einschalten: weder Text
                // noch echte UTF-16-Bereiche dürfen sich dadurch verändern.
                tv.layoutManager.maximumWrapWidth = charWidth * 14
                tv.layoutManager.wrapLines = false
                tv.layoutManager.layoutLines()
                tv.layoutManager.wrapLines = true
                tv.layoutManager.layoutLines()
                let afterToggle = tv.fastraColumnSelectionSnapshot

                let ok = firstFragments > 1
                    && forward.lineIndices == [0, 1, 2, 3, 4]
                    && forward.lowerColumn == 2
                    && forward.upperColumn == 5
                    && values == expectedValues
                    && reverse.lineIndices == forward.lineIndices
                    && reverse.ranges == rangesBefore
                    && afterToggle?.ranges == rangesBefore
                    && tv.string == textBefore
                finish(
                    ok,
                    "Fragmente Zeile 1=\(firstFragments), logische Zeilen="
                        + "\(forward.lineIndices), Werte=\(values), "
                        + "rückwärts=\(reverse.ranges == rangesBefore), "
                        + "Wrap-Umschaltung=\(afterToggle?.ranges == rangesBefore)"
                )
            }
        }
    }

    // MARK: - -selftest colpaste

    /// Copy/Paste, Tippen, Löschen, Cut, Paste Column und eine Zeichen-
    /// Transformation müssen alle Rechteckteile bearbeiten und je genau eine
    /// Undo-Gruppe erzeugen.
    private static func runColumnPasteTest() {
        testLabel = "colpaste"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }

        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-colpaste-\(UUID().uuidString).txt")
        do {
            try "abCDef\nabXYef\nab12ef".write(
                to: tmp, atomically: true, encoding: .utf8
            )
        } catch {
            finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)")
        }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.9) {
                guard let tv = editorTextView(in: root) as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                var failures: [String] = []
                func check(_ condition: @autoclosure () -> Bool, _ label: String) {
                    if !condition() { failures.append(label) }
                }
                func selectThree(
                    _ text: String,
                    start: Int = 2,
                    length: Int = 2
                ) -> Int {
                    tv.setText(text)
                    tv._undoManager?.clearStack()
                    tv.selectionManager.setSelectedRange(
                        NSRange(location: start, length: length)
                    )
                    check(tv.fastraSelectColumn(upwards: false), "Select Down 1")
                    check(tv.fastraSelectColumn(upwards: false), "Select Down 2")
                    return tv._undoManager?.undoCount ?? -1
                }
                func checkOneUndo(_ before: Int, _ label: String) {
                    check(
                        tv._undoManager?.undoCount == before + 1,
                        "\(label): nicht genau eine Undo-Gruppe"
                    )
                }

                NSApp.mainMenu?.update()
                let pasteColumnItem = findMenuItem(
                    titled: L10n.string("Spalte einfügen"),
                    in: NSApp.mainMenu
                )
                let selectUpItem = findMenuItem(
                    titled: L10n.string("Rechteckauswahl nach oben"),
                    in: NSApp.mainMenu
                )
                let selectDownItem = findMenuItem(
                    titled: L10n.string("Rechteckauswahl nach unten"),
                    in: NSApp.mainMenu
                )
                let upArrow = String(UnicodeScalar(NSUpArrowFunctionKey)!)
                let downArrow = String(UnicodeScalar(NSDownArrowFunctionKey)!)
                check(
                    pasteColumnItem?.keyEquivalent.lowercased() == "v"
                        && pasteColumnItem?.keyEquivalentModifierMask
                            == [.command, .control],
                    "Menü/Kürzel für Paste Column fehlt"
                )
                check(
                    selectUpItem?.keyEquivalent == upArrow
                        && selectUpItem?.keyEquivalentModifierMask
                            == [.control, .shift],
                    "Menü/Kürzel für Select Up fehlt"
                )
                check(
                    selectDownItem?.keyEquivalent == downArrow
                        && selectDownItem?.keyEquivalentModifierMask
                            == [.control, .shift],
                    "Menü/Kürzel für Select Down fehlt"
                )

                let base = "abCDef\nabXYef\nab12ef"

                _ = selectThree(base)
                prepareSelfTestPasteboardMutationOrFinish()
                tv.copy(tv)
                guard let expectedColumnCopy = try? plainTextPasteboardItems(
                    "CD\nXY\n12\n") else {
                    finish(false, "Erwarteter Rechteck-Copy ließ sich nicht vorbereiten")
                }
                noteSelfTestPasteboardMutationOrFinish(
                    expectedItems: expectedColumnCopy)
                check(
                    NSPasteboard.general.string(forType: .string)
                        == "CD\nXY\n12\n",
                    "Rechteck-Copy falsch"
                )

                var undoBefore = selectThree(base)
                writeSelfTestPasteboardString("Q")
                tv.paste(tv)
                check(tv.string == "abQef\nabQef\nabQef", "Fill-down Paste falsch")
                checkOneUndo(undoBefore, "Fill-down Paste")
                tv._undoManager?.undo()
                check(tv.string == base, "Fill-down Undo falsch")
                tv._undoManager?.redo()
                check(tv.string == "abQef\nabQef\nabQef", "Fill-down Redo falsch")

                undoBefore = selectThree(base)
                writeSelfTestPasteboardString("1\n22")
                tv.paste(tv)
                check(
                    tv.string == "ab1ef\nab22ef\nabef",
                    "Mismatch-Regel (fehlende Clipboard-Zeile leert Rest) falsch"
                )
                checkOneUndo(undoBefore, "Mehrzeiliges Paste")

                undoBefore = selectThree(base)
                tv.insertText(
                    "T" as NSString,
                    replacementRange: NSRange(location: NSNotFound, length: 0)
                )
                check(tv.string == "abTef\nabTef\nabTef", "Tippen auf Rechteck falsch")
                checkOneUndo(undoBefore, "Tippen")

                undoBefore = selectThree(base)
                tv.deleteBackward(nil)
                check(tv.string == "abef\nabef\nabef", "Backspace auf Rechteck falsch")
                checkOneUndo(undoBefore, "Backspace")

                let shortRows = "abcdef\nab\nabc"
                undoBefore = selectThree(shortRows, start: 4, length: 1)
                tv.deleteBackward(nil)
                check(
                    tv.string == "abcdf\nab\nabc",
                    "Backspace löschte außerhalb kurzer Rechteckzeilen"
                )
                checkOneUndo(undoBefore, "Backspace mit kurzen Zeilen")

                undoBefore = selectThree(shortRows, start: 4, length: 1)
                writeSelfTestPasteboardString("Q")
                tv.paste(tv)
                check(
                    tv.string == "abcdQf\nabQ\nabcQ",
                    "Normales Paste polsterte kurze Zeilen unerwartet"
                )
                checkOneUndo(undoBefore, "Paste mit kurzen Zeilen")

                undoBefore = selectThree(base)
                prepareSelfTestPasteboardMutationOrFinish()
                tv.cut(tv)
                noteSelfTestPasteboardMutationOrFinish(
                    expectedItems: expectedColumnCopy)
                check(tv.string == "abef\nabef\nabef", "Cut auf Rechteck falsch")
                check(
                    NSPasteboard.general.string(forType: .string)
                        == "CD\nXY\n12\n",
                    "Cut-Clipboard falsch"
                )
                checkOneUndo(undoBefore, "Cut")

                // Paste Column an Spalte 4: kurze Zeilen werden mit Tabs
                // aufgefüllt, weil das aktive Einrückungsprofil Tabs nutzt.
                let padded = "abcdef\nab\nabc"
                undoBefore = selectThree(padded, start: 4, length: 1)
                tv.fastraColumnIndentationUnit = "\t"
                writeSelfTestPasteboardString("X\nY\nZ")
                NotificationCenter.default.post(
                    name: .fastraPasteColumn,
                    object: nil
                )
                check(
                    tv.string == "abcdXf\nab\tY\nabc\tZ",
                    "Paste Column/Tab-Padding falsch: \(tv.string.debugDescription)"
                )
                checkOneUndo(undoBefore, "Paste Column")
                tv.fastraColumnIndentationUnit = "    "

                // Unterschiedliche Ergebnislängen (ß → SS) prüfen zugleich
                // Transformationsrouting und Range-Neuberechnung.
                let transformBase = "abßz\nabxy\nabéz"
                undoBefore = selectThree(transformBase, start: 2, length: 1)
                NotificationCenter.default.post(
                    name: .fastraTextOp,
                    object: TextOpKind.uppercase.rawValue
                )
                check(
                    tv.string == "abSSz\nabXy\nabÉz",
                    "Rechteck-Transformation falsch: \(tv.string.debugDescription)"
                )
                checkOneUndo(undoBefore, "Rechteck-Transformation")
                tv._undoManager?.undo()
                check(tv.string == transformBase, "Transformations-Undo falsch")

                // Nullbereiche kurzer Zeilen dürfen keinesfalls als
                // „keine Auswahl = ganzes Dokument" transformiert werden.
                let shortTransform = "abcdez\nab\nabc"
                undoBefore = selectThree(shortTransform, start: 4, length: 1)
                NotificationCenter.default.post(
                    name: .fastraTextOp,
                    object: TextOpKind.uppercase.rawValue
                )
                check(
                    tv.string == "abcdEz\nab\nabc",
                    "Transformation verließ kurze Rechteckzeilen"
                )
                checkOneUndo(undoBefore, "Transformation mit kurzen Zeilen")

                finish(
                    failures.isEmpty,
                    failures.isEmpty
                        ? "Copy/Paste/Tippen/Backspace/Cut/Paste Column/"
                            + "Transformation jeweils über drei logische Zeilen "
                            + "und eine Undo-Gruppe"
                        : failures.joined(separator: "; ")
                )
            }
        }
    }

    private static func runGutterDimmingTest() {
        testLabel = "gutterdim"
        guard Workspace.shared != nil,
              let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }) else {
            finish(false, "kein Hauptfenster gefunden")
        }

        waitForEditor(window: mainWindow) { root, _ in
            checkGutterDimming(in: root)
        }
    }

    private static func checkGutterDimming(in root: NSView) {
        guard let gutter = findView(named: "GutterView", in: root) else {
            finish(false, "echter CodeEditSourceEditor-Gutter nicht gefunden")
        }
        GutterDimming.apply(in: root, windowIsKey: false)
        let dimmed = gutter.alphaValue
        GutterDimming.apply(in: root, windowIsKey: true)
        let active = gutter.alphaValue
        finish(dimmed < 0.5 && active == 1,
               "echter Gutter alpha hinten=\(dimmed), vorn=\(active)")
    }

    // MARK: - -selftest filemodes

    private static func runFileModesTest() {
        testLabel = "filemodes"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory().appendingPathComponent(
            "fastra-filemodes-\(UUID().uuidString)", isDirectory: true
        )
        let binary = base.appendingPathComponent("binary.dat")
        let large = base.appendingPathComponent("large.log")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            try Data([0x46, 0x41, 0x53, 0x54, 0, 0x52, 0x41]).write(to: binary)
            _ = FileManager.default.createFile(atPath: large.path, contents: nil)
            let handle = try FileHandle(forWritingTo: large)
            let chunk = Data(repeating: 0x41, count: 1024 * 1024)
            var remaining = FileLoader.editableFileThreshold + 101
            while remaining > 0 {
                let count = min(UInt64(chunk.count), remaining)
                try handle.write(contentsOf: chunk.prefix(Int(count)))
                remaining -= count
            }
            try handle.close()
        } catch {
            try? fm.removeItem(at: base)
            finish(false, "Setup fehlgeschlagen: \(error.localizedDescription)")
        }

        ws.loadFile(at: binary) { binaryOK in
            guard binaryOK, ws.activeTab?.displayMode == .hex,
                  ws.activeTab?.content.isEmpty == true else {
                try? fm.removeItem(at: base)
                finish(false, "Binärdatei wurde nicht als Hex geroutet")
            }
            ws.loadFile(at: large) { largeOK in
                let tab = ws.activeTab
                let ok = largeOK && tab?.displayMode == .chunkedText
                    && tab?.content.isEmpty == true
                    && (tab?.fileSize ?? 0) > FileLoader.editableFileThreshold
                try? fm.removeItem(at: base)
                finish(ok, ok
                       ? "Null-Byte → Hex; >128 MiB Text → Abschnittsansicht ohne Voll-Buffer"
                       : "Großdatei falsch geroutet: Modus=\(String(describing: tab?.displayMode)), Dateibytes=\(tab?.fileSize ?? 0), Pufferzeichen=\(tab?.content.utf16.count ?? 0)")
            }
        }
    }

    /// Findet die Haupt-Textfläche des Editors. CodeEditSourceEditor nutzt
    /// keine `NSTextView`, sondern eine eigene `TextView: NSView` (Modul
    /// CodeEditTextView) — daher Suche über den Klassennamen.
    private static func editorTextView(in view: NSView) -> NSView? {
        let name = String(describing: type(of: view))
        if name.contains("TextView"), view.acceptsFirstResponder, view.frame.height > 50 {
            return view
        }
        for sub in view.subviews {
            if let tv = editorTextView(in: sub) { return tv }
        }
        return nil
    }

    /// TextView-Identität an mehreren Schritten protokollieren, um einen
    /// Neuaufbau beim Resize zuzuordnen. Ausgabe nach stderr hält das
    /// maschinenlesbare SELFTEST-Ergebnis unverändert.
    private static func logEditorIdentity(_ step: String, root: NSView,
                                          expected: ObjectIdentifier) {
        let live = editorTextView(in: root) as? TextView
        let same = live.map { ObjectIdentifier($0) == expected } ?? false
        let state = live == nil ? "keine TextView"
            : (same ? "unverändert" : "ERSETZT")
        let line = "SELFTEST-DEBUG \(testLabel) [\(step)]: \(state) "
            + "(TextViews: \(editorTextViewCount(in: root)))\n"
        FileHandle.standardError.write(Data(line.utf8))
    }

    /// Zählt die Editor-TextViews im Baum. Diagnose für den Fall, dass die
    /// Suchheuristik oben eine andere TextView liefert als erwartet: Steht hier
    /// 2, hängt der alte Editor noch im Baum, während der neue schon da ist —
    /// dann ist der Editor tatsächlich neu aufgebaut worden. Steht hier 1,
    /// zeigt die Abweichung auf etwas anderes.
    private static func editorTextViewCount(in view: NSView) -> Int {
        let name = String(describing: type(of: view))
        var count = 0
        if name.contains("TextView"), view.acceptsFirstResponder, view.frame.height > 50 {
            count += 1
        }
        for sub in view.subviews { count += editorTextViewCount(in: sub) }
        return count
    }

    private static func findView(named className: String, in view: NSView) -> NSView? {
        let name = String(describing: type(of: view))
        if name == className || name.hasSuffix(".\(className)") { return view }
        for child in view.subviews {
            if let found = findView(named: className, in: child) { return found }
        }
        return nil
    }

    /// `true`, wenn irgendwo ein sichtbares CodeEditSourceEditor-Find-Panel
    /// hängt (Klassenname enthält „FindPanel", nicht versteckt, sichtbare Höhe).
    private static func findPanelVisible(in view: NSView) -> Bool {
        let name = String(describing: type(of: view))
        if name.contains("FindPanel"), !view.isHidden, view.frame.height > 1,
           view.window != nil {
            return true
        }
        return view.subviews.contains { findPanelVisible(in: $0) }
    }

    /// Fensterloser End-to-End-Test des Geöffnet-Scopes (BBEdit „Open text
    /// documents"): drei In-Memory-Tabs, Live-Suche über den echten
    /// SearchRunner-Pfad (Combine-Trigger + Task.detached), dann
    /// „Alle ersetzen" über alle Tabs. Prüft genau die Verdrahtung, die
    /// die reinen Unit-Tests umgehen (Runner-Async-Pfad).
    private static func runOpenScopeTest() {
        testLabel = "openscope"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        // Der Produkt-Runner arbeitet bewusst nur bei offener Suchmaske.
        // Dieser fensterlose Test setzt deshalb denselben aktiven Zustand.
        ws.showSearchDialog = true
        // Tabs direkt setzen — der Geöffnet-Scope sucht Tab-Inhalte
        // (auch ungespeicherte), keine Dateien. Genau das testen wir.
        ws.tabs = [
            EditorTab(title: "open-a.txt", path: "—",
                      content: "eins MARKER\nzwei\nMARKER drei"),
            EditorTab(title: "open-b.txt", path: "—", content: "MARKER"),
            EditorTab(title: "open-c.txt", path: "—", content: "ohne Treffer"),
        ]
        ws.activeTabID = ws.tabs[0].id
        ws.scope = .open
        ws.useRegex = false
        ws.caseSensitive = true
        ws.findPattern = "MARKER"
        ws.replacePattern = "ERSETZT"
        pollOpenResults(ws)
    }

    /// Pollt auf das erwartete Geöffnet-Ergebnis (3 Treffer in 2 Tabs),
    /// dann Teil b: Alle ersetzen. Max. ~2 s (Debounce 120 ms + Async-Lauf).
    private static func pollOpenResults(_ ws: Workspace) {
        // Bisher 67 × 30 ms ≈ 2 s.
        waitFor(budget: 2.01, pause: 0.03,
                condition: { ws.openTotalMatches == 3 && ws.openResults.count == 2 },
                onTimeout: { book in
                    finish(false, "(a) Timeout: openTotalMatches=\(ws.openTotalMatches), "
                        + "Gruppen=\(ws.openResults.count) — \(book.summary)")
                }) {
            // Gruppen-Reihenfolge = Tab-Reihenfolge; Zeile/Spalte tab-lokal.
            guard ws.openResults[0].title == "open-a.txt",
                  ws.openResults[0].matches.count == 2,
                  ws.openResults[0].matches[1].line == 3,
                  ws.openResults[1].title == "open-b.txt" else {
                finish(false, "(a) Gruppen falsch: \(ws.openResults.map { "\($0.title):\($0.matches.count)" })")
            }
            // ── Teil b: Alle ersetzen über alle Tabs ────────────────────
            let changed = ws.applyAllInOpenTabs()
            guard changed == 2 else {
                finish(false, "(b) applyAllInOpenTabs änderte \(changed) statt 2 Tabs")
            }
            guard ws.tabs[0].content == "eins ERSETZT\nzwei\nERSETZT drei",
                  ws.tabs[0].isDirty,
                  ws.tabs[1].content == "ERSETZT", ws.tabs[1].isDirty,
                  ws.tabs[2].content == "ohne Treffer", !ws.tabs[2].isDirty else {
                finish(false, "(b) Tab-Inhalte nach Ersetzen falsch: \(ws.tabs.map(\.content))")
            }
            finish(true, "Geöffnet-Scope: 3 Treffer in 2 Tabs, Alle-ersetzen änderte genau 2 Tabs")
        }
    }

    /// Anders als finish() durchläuft diese Probe den echten Beenden-Hook.
    /// Ein angehaltener Undo-Auftrag muss vor dem Verwerfen der übrigen Kopien enden.
    @MainActor
    private static func runMarkdownImageQuitTest() {
        guard let workspace = Workspace.shared,
              let window = CommandTargeting.registeredWindow(for: workspace),
              let root = window.contentView else { finish(false, "kein Dokumentfenster für Bild-Undo beim Beenden") }
        let base = selfTestTemporaryDirectory().canonicalFileURL.appendingPathComponent("fastra-mdimagequit-\(UUID().uuidString)")
        let document = base.appendingPathComponent("Notizen.md")
        let source = base.appendingPathComponent("quelle.png")
        do {
            try FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
            try writeSolidPNG(to: source, width: 8, height: 8)
            let bytes = try Data(contentsOf: source)
            let saved = try MarkdownImageStore.storeImageFile(source, documentURL: document)
            try (saved.link + "\n").write(to: document, atomically: true, encoding: .utf8)
            workspace.loadFile(at: document) { loaded in
                guard loaded, let index = workspace.tabs.firstIndex(where: { $0.url == document }) else {
                    finish(false, "gespeichertes Markdown lädt vor Beenden nicht")
                }
                workspace.tabs[index].markdownVisualOverride = false
                waitFor(budget: 8, pause: 0.03,
                    condition: { (editorTextView(in: root) as? TextView)?.string == saved.link + "\n" },
                    onTimeout: { _ in finish(false, "Quelltexteditor vor Beenden nicht bereit") }, then: {
                        guard let editor = editorTextView(in: root) as? TextView else { finish(false, "Quelltexteditor fehlt") }
                        do {
                            let unused = try MarkdownImageStore.storeImageFile(source, documentURL: document)
                            let undone = try MarkdownImageStore.storeImageFile(source, documentURL: document)
                            for image in [unused, undone] {
                                editor.replaceCharacters(in: NSRange(location: (editor.string as NSString).length, length: 0), with: image.link + "\n")
                                MarkdownImageUndo.register(textView: editor, insertion: image.link,
                                    storedImages: [image], documentURL: document, workspace: workspace)
                                editor.undoManager?.endUndoGrouping()
                            }
                            workspace.confirmCloseHandler = { _ in .dontSave }
                            let release = DispatchSemaphore(value: 0)
                            MarkdownImageUndoSideEffect.ioQueue.async { release.wait() }
                            editor.undoManager?.undo()
                            guard editor.undoManager?.isUndoing == true else { finish(false, "Dateiphase des Undo wurde nicht angehalten") }
                            let targetDirectory = base.appendingPathComponent("copy")
                            try FileManager.default.createDirectory(at: targetDirectory, withIntermediateDirectories: true)
                            let target = targetDirectory.appendingPathComponent("copy.md")
                            let releaseSave = DispatchSemaphore(value: 0)
                            let saveQueue = DispatchQueue(label: "Fastra.SelfTest.MarkdownSaveAs")
                            saveQueue.async { releaseSave.wait() }
                            workspace.markdownSaveAsQueue = saveQueue
                            workspace.saveTabAs(id: workspace.activeTabID!, to: target, expectedTargetState: .absent, isMarkdown: true) { success in
                                guard success else { finish(false, "Speichern unter vor Beenden scheiterte") }
                            }
                            workspace.activeTab!.undoHistory.whenIdle {
                                DispatchQueue.main.async {
                                    guard MarkdownImageUndoSideEffect.pendingIO.wait(timeout: .now()) == .timedOut else {
                                        releaseSave.signal()
                                        finish(false, "Speichern unter zählt seine angehaltene Bildkopie nicht als laufende Dateiphase")
                                    }
                                    releaseSave.signal()
                                }
                            }
                            _ = NotificationCenter.default.addObserver(forName: NSApplication.willTerminateNotification,
                                object: NSApp, queue: .main) { _ in
                                    let files = try? FileManager.default.contentsOfDirectory(atPath: base.appendingPathComponent("images").path)
                                    let copied = (try? String(contentsOf: target, encoding: .utf8)).map {
                                        MarkdownImageCleanup.references($0, documentURL: target)
                                    }
                                    let ok = copied?.count == 2
                                        && copied?.allSatisfy({ (try? Data(contentsOf: $0)) == bytes }) == true
                                        && MarkdownImageUndoSideEffect.pendingIO.wait(timeout: .now()) == .success
                                        && !FileManager.default.fileExists(atPath: unused.fileURL.path)
                                        && !FileManager.default.fileExists(atPath: undone.fileURL.path)
                                        && (try? Data(contentsOf: saved.fileURL)) == bytes
                                        && files == [saved.fileURL.lastPathComponent]
                                        && MarkdownImageUndoBuffer.shared.byteCount == 0
                                    try? FileManager.default.removeItem(at: base)
                                    finish(ok, "Beenden wartet auf Bild-Undo und Speichern unter, entfernt verworfene Kopien und erhält gespeicherte Bilder")
                                }
                            // AppKits Beenden-Schleife muss die Main-Queue bedienen können.
                            // Deshalb aus dem echten Tastaturereignis starten, nicht aus diesem Callback.
                            var quitMonitor: Any?
                            quitMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
                                if event.modifierFlags.contains(.command), event.charactersIgnoringModifiers == "q" {
                                    if let quitMonitor { NSEvent.removeMonitor(quitMonitor) }
                                    DispatchQueue.main.async { release.signal() }
                                }
                                return event
                            }
                            guard quitMonitor != nil else { finish(false, "Command-Q-Beobachter fehlt") }
                            window.makeKeyAndOrderFront(nil)
                            postCmd("q", keyCode: 12, windowNumber: window.windowNumber)
                            waitFor(budget: 10, pause: 0.03, condition: { false },
                                onTimeout: { _ in finish(false, "Beenden erreichte den Abschluss nicht") }, then: {})
                        } catch { finish(false, "Bildkopien vor Beenden: \(error.localizedDescription)") }
                    })
            }
        } catch { finish(false, "Fixture für Bild-Undo beim Beenden: \(error.localizedDescription)") }
    }

    // MARK: - Selbsttest mdassist

    /// End-to-End-Prüfung des assistierten Markdown-Schreibens:
    /// (a) Markdown-Toolbar ist für den Markdown-Tab real layoutet.
    /// (b) ⌘V-Pfad mit programmatisch befülltem Pasteboard (PNG): Datei
    ///     entsteht im images-Unterordner, relativer Link steht im Editor,
    ///     die Vorschau rendert das Bild und scrollt zur Einfügestelle.
    /// (c) Undo/Redo entfernt und restauriert Link und erzeugte Datei.
    /// (d) Drop-Abgrenzung: Bilddatei wird eingefügt, Textdatei geöffnet.
    private static func runMarkdownAssistTest() {
        testLabel = "mdassist"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-mdassist-\(UUID().uuidString)")
        let doc = base.appendingPathComponent("Notizen.md")
        // Wirklich außerhalb des Dokumentordners — sonst greift die
        // „schon im Dokumentbaum → nur verlinken“-Regel statt der Kopie.
        let outside = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-mdassist-src-\(UUID().uuidString)")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            try fm.createDirectory(at: outside, withIntermediateDirectories: true)
            // Langes Dokument: Die Einfügestelle liegt am Ende, damit der
            // Vorschau-Scroll real beobachtbar ist (scrollY > 0).
            let filler = (1...60).map { "Absatz \($0) mit etwas Text." }
                .joined(separator: "\n\n")
            try ("# Notizen\n\n" + filler + "\n\n")
                .write(to: doc, atomically: true, encoding: .utf8)
            try writeSolidPNG(to: outside.appendingPathComponent("quelle.png"),
                              width: 8, height: 8)
            try "Begleittext".write(to: outside.appendingPathComponent("begleit.txt"),
                                    atomically: true, encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixtures nicht schreibbar: \(error.localizedDescription)")
        }

        ws.loadFile(at: doc) { ok in
            guard ok else { finish(false, "(setup) Notizen.md lädt nicht") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                guard let tvView = editorTextView(in: root), let tv = tvView as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                // (a) Toolbar real im Layout?
                guard markerViewExists(id: "markdownToolbar", in: root) else {
                    finish(false, "(a) Markdown-Toolbar fehlt für den Markdown-Tab")
                }
                // (b) Paste-Pfad: Fenster + Editor fokussieren, PNG ins
                // Pasteboard, dann der echte ⌘V-Interceptions-Pfad. Der
                // Key-Status kommt asynchron — deshalb mit Wiederholungen.
                tv.selectionManager.setSelectedRange(
                    NSRange(location: (tv.string as NSString).length, length: 0))
                let png = (try? Data(contentsOf: outside.appendingPathComponent("quelle.png"))) ?? Data()
                writeSelfTestPasteboardData(
                    png, type: NSPasteboard.PasteboardType("public.png")
                )
                attemptMarkdownPaste(ws, tv: tv, root: root, base: base,
                                     outside: outside, window: mainWindow)
            }
        }
    }

    /// Fokus + ⌘V-Pfad mit Wiederholungen: `NSApp.activate` und der
    /// Key-Status greifen erst nach ein paar Runloop-Ticks zuverlässig —
    /// besonders wenn der Desktop gerade aktiv benutzt wird.
    private static func attemptMarkdownPaste(_ ws: Workspace, tv: TextView,
                                             root: NSView, base: URL, outside: URL,
                                             window: NSWindow) {
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    // Jeder Durchlauf bittet erneut um Fokus und versucht den Paste.
                    activateApplication(ignoringOtherApps: true)
                    window.makeKeyAndOrderFront(nil)
                    window.makeFirstResponder(tv)
                    return MainActor.assumeIsolated { MarkdownAssist.handlePasteCommand() }
                },
                onTimeout: { book in
                    let responder = String(describing: type(of: window.firstResponder as Any))
                    finish(false, "(b) handlePasteCommand übernimmt nicht "
                        + "(keyWindow=\(NSApp.keyWindow != nil), isKey=\(window.isKeyWindow), "
                        + "responder=\(responder)) — \(book.summary)")
                },
                then: {
                    pollMarkdownPaste(ws, tv: tv, root: root, base: base,
                                      outside: outside)
                })
    }

    // Ein HTML-Bildknoten kann auch bei kaputten Bilddaten existieren.
    // Die Paste-Fixture ist ein 8×8-PNG; erst seine dekodierten Maße zählen.
    static let markdownPastePreviewObservation = """
    [Array.from(document.images).filter(image => image.complete
        && image.naturalWidth === 8 && image.naturalHeight === 8).length, window.scrollY]
    """

    private static func pollMarkdownPaste(_ ws: Workspace, tv: TextView, root: NSView,
                                          base: URL, outside: URL) {
        let imagesDirectory = base.appendingPathComponent("images", isDirectory: true)
        var imageFile: String?
        var linkInEditor = false
        var images = 0
        var scrollY = 0.0
        var scriptError: Error?
        waitForAsync(
            budget: 10, pause: 0.25,
            check: { answer in
                let files = (try? FileManager.default.contentsOfDirectory(
                    atPath: imagesDirectory.path)) ?? []
                imageFile = files.first { $0 == "1.png" }
                linkInEditor = tv.string.contains("![1](images/1.png)")
                guard imageFile != nil, linkInEditor else {
                    answer(false)
                    return
                }
                // Vorschau: Bild gerendert + zur Einfügestelle gescrollt.
                guard let webView = firstWebView(in: root) else {
                    finish(false, "(b) keine Markdown-Vorschau-WebView gefunden")
                }
                webView.evaluateJavaScript(
                    markdownPastePreviewObservation
                ) { value, error in
                    let pair = value as? [Any]
                    images = pair?.first as? Int ?? 0
                    scrollY = (pair?.last as? Double) ?? Double(pair?.last as? Int ?? 0)
                    scriptError = error
                    answer(images >= 1 && scrollY > 50)
                }
            },
            onTimeout: { book in
                guard imageFile != nil, linkInEditor else {
                    finish(false, "(b) Datei=\(String(describing: imageFile)), "
                        + "Link=\(linkInEditor) — \(book.summary)")
                }
                finish(false, "(b) Vorschau: dekodierte Bilder=\(images), scrollY=\(scrollY); "
                    + "JavaScript-Fehler=\(scriptError?.localizedDescription ?? "keiner") — \(book.summary)")
            },
            then: {
                guard let imageFile else { finish(false, "(b) Bilddatei nach Erfolg verschwunden") }
                runMarkdownPasteUndoPhase(ws, tv: tv, base: base,
                                          outside: outside, storedImage: imageFile)
            }
        )
    }

    /// (c) Undo/Redo umfasst Link und ausschließlich die von Fastra gerade
    /// erzeugte Datei. Der Dateiname wird nicht aus dem Link neu geraten,
    /// sondern stammt aus der beobachteten images-Ablage.
    private static func runMarkdownPasteUndoPhase(_ ws: Workspace, tv: TextView,
                                                  base: URL, outside: URL,
                                                  storedImage: String) {
        tv.undoManager?.undo()
        pollMarkdownPasteUndo(ws, tv: tv, base: base, outside: outside,
                              storedImage: storedImage)
    }

    private static func pollMarkdownPasteUndo(_ ws: Workspace, tv: TextView,
                                              base: URL, outside: URL,
                                              storedImage: String) {
        let file = base.appendingPathComponent("images/\(storedImage)")
        waitFor(budget: 4, pause: 0.1,
                condition: {
                    tv.undoManager?.isUndoing != true
                        && !tv.string.contains("![1](images/1.png)")
                        && !FileManager.default.fileExists(atPath: file.path)
                },
                onTimeout: { book in
                    finish(false, "(c) Undo ließ Link oder erzeugte Bilddatei stehen — \(book.summary)")
                },
                then: {
                    tv.undoManager?.redo()
                    pollMarkdownPasteRedo(ws, tv: tv, base: base, outside: outside,
                                          storedImage: storedImage)
                })
    }

    private static func pollMarkdownPasteRedo(_ ws: Workspace, tv: TextView,
                                              base: URL, outside: URL,
                                              storedImage: String) {
        let file = base.appendingPathComponent("images/\(storedImage)")
        waitFor(budget: 4, pause: 0.1,
                condition: {
                    tv.undoManager?.isRedoing != true
                        && tv.string.contains("![1](images/1.png)")
                        && FileManager.default.fileExists(atPath: file.path)
                },
                onTimeout: { book in
                    finish(false, "(c) Redo stellte Link oder Bilddatei nicht wieder her — \(book.summary)")
                },
                then: {
                    runMarkdownDropPhase(ws, tv: tv, base: base, outside: outside)
                })
    }

    /// (d) Drop-Abgrenzung: eine Bilddatei + eine Textdatei „fallen" auf den
    /// Markdown-Editor — das Bild wird kopiert + verlinkt, der Text geöffnet.
    private static func runMarkdownDropPhase(_ ws: Workspace, tv: TextView,
                                             base: URL, outside: URL) {
        let tabsBefore = ws.tabs.count
        let linksBefore = tv.string.components(separatedBy: "![2](images/2.png)").count - 1
        _ = MainActor.assumeIsolated {
            MarkdownAssist.handleDroppedFileURLs([
                outside.appendingPathComponent("quelle.png"),
                outside.appendingPathComponent("begleit.txt"),
            ], workspace: ws)
        }
        pollMarkdownDrop(ws, tv: tv, base: base, outside: outside,
                         tabsBefore: tabsBefore, linksBefore: linksBefore)
    }

    private static func pollMarkdownDrop(_ ws: Workspace, tv: TextView, base: URL,
                                         outside: URL, tabsBefore: Int, linksBefore: Int) {
        var copied = false
        var linked = false
        var opened = false
        func cleanup() {
            try? FileManager.default.removeItem(at: base)
            try? FileManager.default.removeItem(at: outside)
        }
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    copied = FileManager.default.fileExists(
                        atPath: base.appendingPathComponent("images/2.png").path)
                    linked = tv.string.components(separatedBy: "![2](images/2.png)").count - 1 == linksBefore + 1
                    opened = ws.tabs.contains { $0.title == "begleit.txt" }
                    let exactlyOneTabAdded = ws.tabs.count == tabsBefore + 1
                    return copied && linked && opened && exactlyOneTabAdded
                },
                onTimeout: { book in
                    cleanup()
                    finish(false, "(d) kopiert=\(copied), verlinkt=\(linked), "
                        + "geöffnet=\(opened), Tabs=\(ws.tabs.count) statt \(tabsBefore + 1) — \(book.summary)")
                },
                then: {
                    cleanup()
                    finish(true, "Toolbar layoutet, Bild-Paste legt images-Datei + relativen Link an, "
                        + "Undo/Redo umfasst beides; Vorschau rendert + scrollt, "
                        + "Drop trennt einfügen/öffnen")
                })
    }

    private static func firstWebView(in view: NSView) -> WKWebView? {
        if let webView = view as? WKWebView { return webView }
        for sub in view.subviews {
            if let found = firstWebView(in: sub) { return found }
        }
        return nil
    }

    // MARK: - Selbsttest mdindent / mddropcursor

    /// Reproduktion der gemeldeten Desktop-`.txt`-Datei: `(1,5)` ist normaler
    /// Fließtext, kein geöffneter Code-Klammerblock. Auch nach einer bewusst
    /// leeren Zeile darf Return nicht wieder vier Leerzeichen hervorholen.
    private static func runMarkdownIndentTest() {
        testLabel = "mdindent"
        guard let workspace = Workspace.shared,
              let window = NSApp.windows.first(where: {
                  $0.frameAutosaveName != SearchWindow.frameAutosaveName
                      && $0.contentView != nil && $0.isVisible
              }), let root = window.contentView else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        let file = selfTestTemporaryDirectory().appendingPathComponent(
            "fastra-mdindent-\(UUID().uuidString).txt"
        )
        let original = "2026-08-10\n\n- Vorbereitungen abgeschlossen\n\n(1,5) ggf. nicht abrechnen"
        do { try Data(original.utf8).write(to: file) }
        catch { finish(false, "Fixture nicht schreibbar: \(error.localizedDescription)") }
        workspace.loadFile(at: file) { loaded in
            guard loaded else {
                try? FileManager.default.removeItem(at: file)
                finish(false, "Text-Fixture lädt nicht")
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                guard let textView = editorTextView(in: root) as? TextView else {
                    try? FileManager.default.removeItem(at: file)
                    finish(false, "echte Editor-TextView fehlt")
                }
                textView.selectionManager.setSelectedRange(
                    NSRange(location: (textView.string as NSString).length, length: 0)
                )
                textView.insertNewline(nil)
                let first = textView.string
                let firstHasIndent = first.hasSuffix("\n    ") || first.hasSuffix("\n\t")

                // Genau der gemeldete zweite Schritt: automatisch entstandene
                // Einrückung manuell entfernen, dann erneut Return.
                if firstHasIndent {
                    let ns = textView.string as NSString
                    let lastLine = ns.lineRange(for: NSRange(location: ns.length, length: 0))
                    let whitespace = ns.substring(with: lastLine).prefix {
                        $0 == " " || $0 == "\t"
                    }
                    if !whitespace.isEmpty {
                        textView.replaceCharacters(
                            in: NSRange(location: lastLine.location,
                                       length: (String(whitespace) as NSString).length),
                            with: ""
                        )
                    }
                }
                textView.insertNewline(nil)
                let secondHasIndent = textView.string.hasSuffix("\n    ")
                    || textView.string.hasSuffix("\n\t")
                try? FileManager.default.removeItem(at: file)
                finish(!firstHasIndent && !secondHasIndent,
                       "(1,5)-Zeile: erstes Return eingerückt=\(firstHasIndent), "
                        + "nach manuellem Reset erneut eingerückt=\(secondHasIndent)")
            }
        }
    }

    /// Treibt CodeEditTextViews echte Drag-Destination mit einer Bilddatei.
    /// Beobachtet werden sichtbare Einfügemarke, stationärer Rand-Autoscroll
    /// und die endgültige Linkposition im Dokument.
    private static func runMarkdownDropCursorTest() {
        testLabel = "mddropcursor"
        guard let workspace = Workspace.shared,
              let window = NSApp.windows.first(where: {
                  $0.frameAutosaveName != SearchWindow.frameAutosaveName
                      && $0.contentView != nil && $0.isVisible
              }), let root = window.contentView else {
            finish(false, "Workspace oder Hauptfenster fehlt")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory().appendingPathComponent(
            "fastra-mddropcursor-\(UUID().uuidString)", isDirectory: true
        )
        let document = base.appendingPathComponent("Ziel.md")
        let source = base.appendingPathComponent("Quelle.png")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            let lines = (1...500).map { "Markdown-Zeile \($0) mit genügend Text" }
            try Data(lines.joined(separator: "\n").utf8).write(to: document)
            try writeSolidPNG(to: source, width: 8, height: 8)
        } catch {
            try? fm.removeItem(at: base)
            finish(false, "Fixture nicht schreibbar: \(error.localizedDescription)")
        }
        workspace.loadFile(at: document) { loaded in
            guard loaded else {
                try? fm.removeItem(at: base)
                finish(false, "Markdown-Fixture lädt nicht")
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                guard let textView = editorTextView(in: root) as? TextView,
                      let scrollView = textView.enclosingScrollView else {
                    try? fm.removeItem(at: base)
                    finish(false, "Editor oder ScrollView fehlt")
                }
                // Die Handler müssen vom normalen Editor-Aufbau stammen.
                // Hier nachzurüsten würde genau einen Verdrahtungsfehler verdecken.
                textView.selectionManager.setSelectedRange(NSRange(location: 0, length: 0))
                let visible = textView.visibleRect
                let localPoint = NSPoint(x: visible.minX + 120, y: visible.maxY - 2)
                let mock = MockDraggingInfo(
                    fileURL: source, location: textView.convert(localPoint, to: nil)
                )
                let beforeY = scrollView.contentView.bounds.minY
                let operation = textView.draggingEntered(mock)
                guard operation.contains(.copy), textView.fastraShowsExternalDropCursor,
                      textView.fastraExternalDropInsertionOffset != nil else {
                    try? fm.removeItem(at: base)
                    finish(false, "Drag zeigt keine positionsgebundene Einfügemarke")
                }
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.45) {
                    let afterY = scrollView.contentView.bounds.minY
                    guard afterY > beforeY + 2,
                          textView.fastraShowsExternalDropCursor,
                          let dropOffset = textView.fastraExternalDropInsertionOffset else {
                        textView.draggingExited(mock)
                        try? fm.removeItem(at: base)
                        finish(false, "stationärer Drag am unteren Rand scrollte nicht "
                            + "(y \(beforeY) → \(afterY))")
                    }
                    let accepted = textView.performDragOperation(mock)
                    guard accepted, !textView.fastraShowsExternalDropCursor else {
                        try? fm.removeItem(at: base)
                        finish(false, "Drop wurde nicht angenommen oder Cursor blieb stehen")
                    }
                    pollMarkdownDropPosition(textView: textView, base: base,
                                             dropOffset: dropOffset, scrolled: afterY - beforeY)
                }
            }
        }
    }

    private static func pollMarkdownDropPosition(textView: TextView, base: URL,
                                                 dropOffset: Int, scrolled: CGFloat) {
        let link = "![1](images/1.png)"
        var range = NSRange(location: NSNotFound, length: 0)
        waitFor(budget: 8, pause: 0.1,
                condition: {
                    range = (textView.string as NSString).range(of: link)
                    let copied = FileManager.default.fileExists(
                        atPath: base.appendingPathComponent("images/1.png").path
                    )
                    return copied && range.location != NSNotFound
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Bildlink/Ablage nach Drop nicht fertig — \(book.summary)")
                },
                then: {
                    let correctPosition = range.location == dropOffset
                    try? FileManager.default.removeItem(at: base)
                    finish(correctPosition,
                           "Drag-Cursoroffset=\(dropOffset), Linkoffset=\(range.location), "
                            + "Rand-Autoscroll=\(Int(scrolled)) pt")
                })
    }

    // MARK: - Selbsttest help

    /// End-to-End-Prüfung der Hilfe:
    /// (a) Beide Sprachdateien laden aus dem gepackten Bundle.
    /// (b) Das Hilfe-Fenster rendert echte Überschriften (DOM-Beobachtung
    ///     in der WKWebView, analog zum `markdown`-Selbsttest).
    /// (c) „Hilfe öffnen bei Anker X“ scrollt real zum Abschnitt.
    /// (d) Gezieltes Schließen der Hilfe lässt mindestens zwei
    ///     Hintergrund-Dokument-Tabs exakt unverändert. Das echte ⌘W-Routing
    ///     prüft der fokuspflichtige Sammeltest `cmdw`.
    private static func runHelpTest() {
        testLabel = "help"
        guard HelpContent.markdown(languageCode: "de") != nil,
              HelpContent.markdown(languageCode: "en") != nil,
              let workspace = Workspace.shared else {
            finish(false, "(a) Hilfe-Markdown (de/en) fehlt im gepackten Bundle")
        }
        while workspace.tabs.count < 2 { workspace.openNewTab() }
        let tabSnapshot = workspace.tabs.map { "\($0.id.uuidString)|\($0.content)" }
        MainActor.assumeIsolated { HelpWindow.show() }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            pollHelpRendered(workspace: workspace, tabSnapshot: tabSnapshot)
        }
    }

    private static func pollHelpRendered(workspace: Workspace, tabSnapshot: [String]) {
        guard let webView = MainActor.assumeIsolated({ HelpWindow.currentWebView }) else {
            finish(false, "(b) Hilfe-Fenster ohne WebView")
        }
        var count = 0
        waitForAsync(
            budget: 10, pause: 0.25,
            check: { answer in
                webView.evaluateJavaScript("document.querySelectorAll('h2').length") { value, _ in
                    count = value as? Int ?? 0
                    answer(count >= HelpSection.allCases.count)
                }
            },
            onTimeout: { book in
                finish(false, "(b) nur \(count) gerenderte h2-Überschriften "
                    + "(erwartet ≥ \(HelpSection.allCases.count)) — \(book.summary)")
            },
            then: {
                Task { @MainActor in
                    do {
                        let code = try await webView.evaluateJavaScript("document.querySelector('pre > code')?.textContent")
                        guard let code = code as? String, !code.isEmpty else {
                            finish(false, "Hilfe enthält keinen prüfbaren Codeblock")
                        }
                        prepareSelfTestPasteboardMutationOrFinish()
                        _ = try await webView.evaluateJavaScript("document.querySelector('.fastra-code-copy')?.click()")
                        try await nativeUIWait("Hilfecode vollständig kopiert") {
                            NSPasteboard.general.string(forType: .string) == code
                        }
                        noteSelfTestPasteboardMutationOrFinish(expectedItems: try plainTextPasteboardItems(code))
                        let label = try await webView.evaluateJavaScript("document.querySelector('.fastra-code-copy')?.getAttribute('aria-label')")
                        guard label as? String == L10n.string("Code kopiert") else {
                            finish(false, "Codekopie zeigt keine Erfolgsrückmeldung")
                        }
                        HelpWindow.show(anchor: HelpSection.encodings.anchor())
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                            pollHelpAnchorScrolled(webView: webView, workspace: workspace,
                                                   tabSnapshot: tabSnapshot)
                        }
                    } catch { finish(false, "Codekopie in der Hilfe: " + error.localizedDescription) }
                }
            }
        )
    }

    private static func pollHelpAnchorScrolled(webView: WKWebView, workspace: Workspace,
                                               tabSnapshot: [String]) {
        var y = 0.0
        waitForAsync(
            budget: 5, pause: 0.25,
            check: { answer in
                webView.evaluateJavaScript("window.scrollY") { value, _ in
                    y = (value as? Double) ?? Double(value as? Int ?? 0)
                    answer(y > 50)
                }
            },
            onTimeout: { book in
                finish(false, "(c) Anker-Sprung scrollt nicht (scrollY=\(y)) — \(book.summary)")
            },
            then: {
                guard let helpWindow = NSApp.windows.first(where: HelpWindow.isHelpWindow) else {
                    finish(false, "(d) Hilfe-Fenster zum Schließen nicht auffindbar")
                }
                MainActor.assumeIsolated { HelpWindow.close() }
                pollHelpClosed(helpWindow, workspace: workspace,
                               tabSnapshot: tabSnapshot, anchorY: y)
            }
        )
    }

    private static func pollHelpClosed(_ helpWindow: NSWindow, workspace: Workspace,
                                       tabSnapshot: [String], anchorY: Double) {
        waitFor(budget: 3, pause: 0.03,
                condition: { !helpWindow.isVisible },
                onTimeout: { book in
                    finish(false, "(d) gezieltes Schließen ließ das Hilfe-Fenster offen — \(book.summary)")
                },
                then: {
                    let currentTabs = workspace.tabs.map { "\($0.id.uuidString)|\($0.content)" }
                    guard currentTabs == tabSnapshot, workspace.tabs.count >= 2 else {
                        finish(false, "(d) Schließen der Hilfe veränderte einen Hintergrund-Tab")
                    }
                    finish(true, "Hilfe aus dem Bundle gerendert "
                        + "(\(HelpSection.allCases.count)+ Abschnitte), Anker-Sprung (y=\(Int(anchorY))); "
                        + "gezieltes Schließen lässt zwei Dokument-Tabs erhalten")
                })
    }

    // MARK: - Selbsttest searchmark

    /// Zählt die Emphasis-Layer der Live-Trefferanzeige in der Editor-
    /// TextView — echte Beobachtung des gerenderten Layer-Baums (analog
    /// `highlight`, das echte Vordergrundfarben beobachtet). Unsere Layer
    /// sind CAShapeLayer im Outline-Stil: Border 0,5 pt und Füllfarbe.
    private static func searchEmphasisLayerCount(in tv: TextView) -> Int {
        (tv.layer?.sublayers ?? []).filter { layer in
            guard let shape = layer as? CAShapeLayer else { return false }
            return shape.fillColor != nil && abs(shape.borderWidth - 0.5) < 0.01
        }.count
    }

    /// Liegt mindestens ein Emphasis-Layer im sichtbaren Ausschnitt der
    /// TextView? Nach einem Sprung ans Dokumentende beweist das, dass der
    /// Scroll-Relay die Anzeige für neu ausgelegte Zeilen nachzeichnet.
    private static func searchEmphasisVisible(in tv: TextView) -> Bool {
        let visible = tv.visibleRect
        return (tv.layer?.sublayers ?? []).contains { layer in
            guard let shape = layer as? CAShapeLayer,
                  shape.fillColor != nil,
                  abs(shape.borderWidth - 0.5) < 0.01 else { return false }
            return visible.intersects(shape.frame)
        }
    }

    /// End-to-End-Prüfung der Live-Trefferanzeige:
    /// (a) 120 Treffer im Datei-Scope → Emphasis-Layer real in der TextView
    ///     (nur der ausgelegte Bereich bekommt Layer, daher > 0 und ≤ 120),
    ///     Tab bleibt sauber (reine Anzeige, kein Dirty).
    /// (b) Navigation ans Listenende → die NSTableView der Trefferliste
    ///     scrollt real mit und der Editor zeigt am Sprungziel markierte
    ///     Treffer (Scroll-Relay zeichnet neu ausgelegte Zeilen nach).
    /// (c) Dialog schließen → alle Emphasis-Layer sind geräumt.
    private static func runSearchMarkTest() {
        testLabel = "searchmark"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let mainWindow = NSApp.windows.first(where: {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.contentView != nil && $0.isVisible
        }), let root = mainWindow.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        // 120 Zeilen mit je einem Treffer — genug, damit die Trefferliste
        // scrollen muss und die Layer-Zahl aussagekräftig ist.
        let content = (1...120).map { "zeile \($0) MARKTREFFER ende" }
            .joined(separator: "\n")
        let tmp = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-searchmark-\(UUID().uuidString).txt")
        do { try content.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }

        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                guard let tvView = editorTextView(in: root), let tv = tvView as? TextView else {
                    finish(false, "Editor-TextView nicht erreichbar")
                }
                ws.scope = .file
                ws.useRegex = false
                ws.caseSensitive = true
                ws.findPattern = "MARKTREFFER"
                pollSearchMarkDrawn(ws, tv: tv)
            }
        }
    }

    private static func pollSearchMarkDrawn(_ ws: Workspace, tv: TextView) {
        // 5 s (Debounce + async-Zeichnung)
        var layers = 0
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    layers = searchEmphasisLayerCount(in: tv)
                    return !ws.bufferSearching && ws.bufferMatches.count == 120
                        && layers > 0 && layers <= 120 && searchEmphasisVisible(in: tv)
                },
                onTimeout: { book in
                    finish(false, "(a) erwartet 120 Treffer + sichtbare Layer, "
                        + "ist: matches=\(ws.bufferMatches.count), layer=\(layers), "
                        + "sichtbar=\(searchEmphasisVisible(in: tv)), "
                        + "searching=\(ws.bufferSearching) — \(book.summary)")
                },
                then: {
                    guard ws.activeTab?.isDirty == false else {
                        finish(false, "(a) Live-Markierung machte den Tab dirty — sie muss reine Anzeige sein")
                    }
                    // (b) Tief ins Dokument navigieren: genug, damit die Liste sicher
                    // scrollt, aber mit ausreichend Zeilen unter dem Ziel für eine
                    // geometrisch mögliche Editor-Zentrierung. Ein Treffer neun
                    // Zeilen vor Dokumentende kann naturgemäß nicht mittig stehen.
                    NotificationCenter.default.post(name: .fastraGotoFirstMatch, object: nil)
                    for _ in 0..<70 {
                        NotificationCenter.default.post(name: .fastraGotoNextMatch, object: nil)
                    }
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                        pollSearchMarkListScrolled(ws, tv: tv)
                    }
                })
    }

    private static func pollSearchMarkListScrolled(_ ws: Workspace, tv: TextView) {
        var firstVisible = -1
        var centeredLine = -1
        waitFor(budget: 2, pause: 0.05,
                condition: {
                    guard let searchWin = NSApp.windows.first(where: {
                        $0.frameAutosaveName == SearchWindow.frameAutosaveName && $0.isVisible
                    }), let searchRoot = searchWin.contentView else {
                        finish(false, "(b) keine sichtbare Suchmaske")
                    }
                    // Die SwiftUI-`List` ist NSTableView-backed — die erste sichtbare
                    // Zeile verrät die echte Scroll-Position der Trefferliste.
                    let table = firstTableView(in: searchRoot)
                    firstVisible = table.map { $0.rows(in: $0.visibleRect).location } ?? -1
                    centeredLine = tv.layoutManager.textLineForPosition(tv.visibleRect.midY)
                        .map { $0.index + 1 } ?? -1
                    return ws.activeMatchIndex == 70 && firstVisible > 20
                        && abs(centeredLine - 71) <= 2 && searchEmphasisVisible(in: tv)
                },
                onTimeout: { book in
                    finish(false, "(b) Trefferliste/Editor folgen nicht: "
                        + "activeIndex=\(ws.activeMatchIndex), ersteSichtbareZeile=\(firstVisible), "
                        + "Editor-Mitte=Zeile \(centeredLine), erwartet≈71, "
                        + "editorMarkierungSichtbar=\(searchEmphasisVisible(in: tv)) — \(book.summary)")
                },
                then: {
                    // (c) Dialog schließen → Markierung muss vollständig verschwinden.
                    ws.showSearchDialog = false
                    pollSearchMarkCleared(tv: tv)
                })
    }

    private static func pollSearchMarkCleared(tv: TextView) {
        var layers = 0
        waitFor(budget: 2, pause: 0.05,
                condition: {
                    layers = searchEmphasisLayerCount(in: tv)
                    return layers == 0
                },
                onTimeout: { book in
                    finish(false, "(c) nach Dialogschluss bleiben \(layers) Emphasis-Layer übrig — \(book.summary)")
                },
                then: {
                    finish(true, "Treffer live markiert (Layer real beobachtet, auch nach "
                        + "Sprung ans Ende), Liste scrollt und Editor zentriert den aktiven Treffer, "
                        + "Dialogschluss räumt alles")
                })
    }

    private static func firstTableView(in view: NSView) -> NSTableView? {
        if let table = view as? NSTableView { return table }
        for sub in view.subviews {
            if let found = firstTableView(in: sub) { return found }
        }
        return nil
    }

    private static func runGitRemoteDialogsTest() {
        testLabel = "gitremotedialogs"
        var status = GitStatusSummary.empty
        status.branch = "main"
        status.upstream = "mirror/development"
        let remotes = ["mirror", "source", "team/fork"]
        let variants: [(String, Bool, Bool, String?)] = [
            ("fetch-all", false, true, nil),
            ("pull-upstream", true, true, "mirror"),
            ("pull-source", true, true, "source"),
            ("pull-all", true, true, nil),
            ("pull-after-all", true, false, "source")
        ]
        let directory = ProcessInfo.processInfo.environment["FASTRA_REMOTE_DIALOG_DIR"]
        func show(_ index: Int) {
            guard index < variants.count else {
                finish(true, "Fetch/Pull-Dialoge: Remote-/Alle-Auswahl, Branchwechsel, Geometrie und native Bestätigung geprüft")
            }
            let (name, isPull, allowAll, remote) = variants[index]
            let alert = GitRemoteActionDialog.makeAlert(remotes: remotes, status: status,
                                                        isPull: isPull, allowAll: allowAll)
            guard let accessory = alert.accessoryView as? GitRemoteActionAccessory else {
                finish(false, "Remote-Auswahl fehlt")
            }
            if let remote { accessory.popup.selectItem(withTitle: remote) }
            else { accessory.popup.selectItem(at: 0) }
            accessory.popup.sendAction(accessory.popup.action, to: accessory.popup.target)
            let expectedBranch = remote == "mirror" ? "development" : "main"
            if isPull, remote != nil, accessory.branchField.stringValue != expectedBranch {
                finish(false, "Branch-Vorschlag passt nicht zur gewählten Quelle")
            }
            if isPull, remote == nil, accessory.branchField.isEnabled {
                finish(false, "Alle-Auswahl aktiviert fälschlich den Branch")
            }
            // runModal läuft innerhalb eines Main-Queue-Callbacks. Ein weiterer
            // Dispatch-Callback wird dort nicht bedient; ein RunLoop-Timer schon.
            let deadline = ProcessInfo.processInfo.systemUptime + 5
            let driver = Timer(timeInterval: 0.1, repeats: true) { timer in
                guard alert.window.isVisible, alert.window.isKeyWindow, NSApp.isActive else {
                    if ProcessInfo.processInfo.systemUptime >= deadline {
                        timer.invalidate()
                        finish(.environment, "Remote-Dialog wird nicht sichtbar")
                    }
                    return
                }
                timer.invalidate()
                guard let content = alert.window.contentView else { finish(false, "Dialog hat keine Ansicht") }
                content.layoutSubtreeIfNeeded()
                let popupRect = accessory.popup.convert(accessory.popup.bounds, to: content)
                guard content.bounds.contains(popupRect), popupRect.width >= 340 else {
                    finish(false, "Remote-Auswahl liegt außerhalb des Dialogs")
                }
                if let directory,
                   let bitmap = content.bitmapImageRepForCachingDisplay(in: content.bounds) {
                    content.cacheDisplay(in: content.bounds, to: bitmap)
                    if let data = bitmap.representation(using: .png, properties: [:]) {
                        let folder = URL(fileURLWithPath: directory)
                        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
                        try? data.write(to: folder.appendingPathComponent(name + ".png"))
                    }
                }
                let button = alert.buttons[0]
                button.performClick(nil)
            }
            RunLoop.main.add(driver, forMode: .common)
            RunLoop.main.add(driver, forMode: RunLoop.Mode(rawValue: "NSModalPanelRunLoopMode"))
            activateApplication(ignoringOtherApps: true)
            let response = alert.runModal()
            driver.invalidate()
            guard response == .alertFirstButtonReturn else { finish(false, "Dialog-Bestätigung kam nicht an") }
            if let remote {
                guard accessory.choice == .remote(remote, branch: isPull ? expectedBranch : "") else {
                    finish(false, "Bestätigte Quelle stimmt nicht mit der Auswahl überein")
                }
            } else if accessory.choice != .all { finish(false, "Alle-Auswahl nicht übernommen") }
            DispatchQueue.main.async { show(index + 1) }
        }
        show(0)
    }

    // MARK: - Selbsttest sidebarheader

    /// Sucht eine `SelfTestMarker`-NSView (per Accessibility-Identifier) im
    /// NSView-Baum des Fensters. SwiftUI erzeugt die Marker-View nur, wenn
    /// der zugehörige View wirklich layoutet wird — Existenz der Marker-View
    /// belegt also die echte Sichtbarkeitsbedingung.
    private static func markerViewExists(id: String, in view: NSView) -> Bool {
        if view.accessibilityIdentifier() == id { return true }
        return view.subviews.contains { markerViewExists(id: id, in: $0) }
    }

    /// Sucht eine `fastraHelp`-Tooltip-Overlay-NSView mit nicht-leerem
    /// AppKit-`toolTip` im Fensterbaum. Belegt, dass die Tooltip-Brücke für
    /// (auch deaktivierte) Bedienelemente wirklich montiert ist.
    private static func fastraTooltipExists(in view: NSView) -> Bool {
        if String(describing: type(of: view)).contains("PassthroughView"),
           let tip = view.toolTip, !tip.isEmpty { return true }
        return view.subviews.contains { fastraTooltipExists(in: $0) }
    }

    /// Sichtbares Hauptfenster (nicht der Suchdialog) für AX-Prüfungen.
    private static func mainWindowForAXChecks() -> NSWindow? {
        let candidates = NSApp.windows.filter {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.isVisible && $0.contentView != nil
        }
        // `NSApp.windows` ist nicht nach Vordergrund sortiert (siehe
        // AGENTS.md). Hat ein früherer Test im selben Lauf zwei Fenster
        // wiederhergestellt, liefert `first` irgendeines davon — die Prüfung
        // sucht die Tabs aus `Workspace.shared` dann in der Ansicht eines
        // fremden Fensters und findet dort keinen einzigen Marker. Genau so
        // fiel `tabcompare` nur im Gesamtlauf aus, einzeln nie. Deshalb
        // zuerst das Fenster nehmen, das wirklich zu `Workspace.shared`
        // gehört; ohne Zuordnung bleibt es beim bisherigen Verhalten.
        if let shared = Workspace.shared,
           let bound = candidates.first(where: {
               WorkspaceWindowRegistry.workspace(for: $0) === shared
           }) {
            return bound
        }
        // Ist (noch) keine Registry-Bindung da, entscheidet die nach
        // Vordergrund sortierte Fensterliste — nie `candidates.first` aus
        // `NSApp.windows`: Bei mehreren Dokumentfenstern wäre das ein
        // zufälliges, womöglich fremdes Fenster (siehe AGENTS.md).
        return NSApp.orderedWindows.first {
            $0.frameAutosaveName != SearchWindow.frameAutosaveName
                && $0.isVisible && $0.contentView != nil
        }
    }

    /// Liefert `Workspace.shared` und sein über die Registry gebundenes,
    /// sichtbares Fenster als Paar — und pollt, bis diese Bindung wirklich
    /// steht. Bewusst kein Rückfall auf irgendein anderes Fenster: Wer den
    /// Inhalt aus `Workspace.shared` liest, aber einen getrennt gesuchten
    /// Editor misst, verbindet bei mehreren Dokumentfenstern zwei
    /// verschiedene Fenster miteinander (siehe AGENTS.md).
    private static func pollSharedWorkspaceWindow(
        then body: @escaping (Workspace, NSWindow, NSView) -> Void
    ) {
        var found: (Workspace, NSWindow, NSView)?
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    guard let ws = Workspace.shared,
                          let window = NSApp.windows.first(where: {
                              $0.frameAutosaveName != SearchWindow.frameAutosaveName
                                  && $0.contentView != nil && $0.isVisible
                                  && WorkspaceWindowRegistry.workspace(for: $0) === ws
                          }), let root = window.contentView else { return false }
                    found = (ws, window, root)
                    return true
                },
                onTimeout: { book in
                    finish(false, "Workspace.shared ist an kein "
                        + "sichtbares Fenster gebunden (Registry-Bindung fehlt) — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Fensterbindung nach Erfolg verschwunden") }
                    body(found.0, found.1, found.2)
                })
    }

    @MainActor
    private static func verifyPathCopyMenus(_ workspace: Workspace) async throws {
        guard let window = CommandTargeting.registeredWindow(for: workspace), let root = window.contentView,
              let tab = workspace.activeTab, let file = tab.url, let project = workspace.projectURL else {
            throw NSError(domain: "PathCopyMenu", code: 1)
        }
        for (markerID, expected) in [
            ("sidebarProjectHeader", project.standardizedFileURL.path),
            ("fileTreeRow-\(file.lastPathComponent)-voll", file.standardizedFileURL.path),
            ("documentTab-current-\(tab.id.uuidString)", file.standardizedFileURL.path)
        ] {
            guard let marker = markerView(id: markerID, in: root) else {
                throw NSError(domain: "PathCopyMenu", code: 2, userInfo: [NSLocalizedDescriptionKey: "Kontextmenü-Anker fehlt: \(markerID)"])
            }
            let rect = marker.convert(marker.bounds, to: nil)
            let point = NSPoint(x: rect.midX, y: rect.midY)
            var shown: NSMenu?, timer: Timer?, done = false, selected = false, ticks = 0
            let observer = NotificationCenter.default.addObserver(forName: NSMenu.didBeginTrackingNotification, object: nil, queue: .main) { notification in
                if let menu = notification.object as? NSMenu { shown = menu }
            }
            timer = Timer(timeInterval: 0.05, repeats: true) { _ in
                ticks += 1
                guard let menu = shown else { if ticks >= 100 { done = true; timer?.invalidate() }; return }
                let items = menu.items.filter { $0.title == L10n.string("Pfad kopieren") }
                if items.count == 1, let item = items.first, item.isEnabled,
                   menu.items.contains(where: { $0.title == L10n.string("Im Finder zeigen…") }) {
                    if !selected {
                        if menu.highlightedItem === item {
                            prepareSelfTestPasteboardMutationOrFinish()
                            selected = true
                            postKey("\r", keyCode: 36, windowNumber: window.windowNumber)
                        } else {
                            postKey("\u{F701}", keyCode: 125, windowNumber: window.windowNumber)
                        }
                    } else if NSPasteboard.general.string(forType: .string) == expected,
                              NSPasteboard.general.changeCount == selfTestPasteboardSession.expectedChangeCount {
                        timer?.invalidate(); timer = nil; done = true
                    }
                    if ticks >= 100 { timer?.invalidate(); menu.cancelTracking(); done = true }
                } else if ticks >= 100 { timer?.invalidate(); menu.cancelTracking(); done = true }
            }
            if let timer { RunLoop.main.add(timer, forMode: .common); RunLoop.main.add(timer, forMode: .eventTracking) }
            for type in [NSEvent.EventType.rightMouseDown, .rightMouseUp] {
                if let event = NSEvent.mouseEvent(with: type, location: point, modifierFlags: [],
                    timestamp: ProcessInfo.processInfo.systemUptime, windowNumber: window.windowNumber,
                    context: nil, eventNumber: 0, clickCount: 1, pressure: type == .rightMouseUp ? 0 : 1) {
                    NSApp.postEvent(event, atStart: false)
                }
            }
            for _ in 0..<220 { if done { break }; try await Task.sleep(for: .milliseconds(25)) }
            if selected {
                for _ in 0..<200 {
                    if NSPasteboard.general.string(forType: .string) == expected,
                       NSPasteboard.general.changeCount == selfTestPasteboardSession.expectedChangeCount { break }
                    try await Task.sleep(for: .milliseconds(25))
                }
            }
            timer?.invalidate(); shown?.cancelTracking(); NotificationCenter.default.removeObserver(observer)
            if selected { noteSelfTestPasteboardMutationOrFinish(expectedItems: try plainTextPasteboardItems(expected)) }
            guard selected, NSPasteboard.general.string(forType: .string) == expected else {
                throw NSError(domain: "PathCopyMenu", code: 3, userInfo: [NSLocalizedDescriptionKey: "Echter Pfad-kopieren-Befehl fehlgeschlagen: \(markerID), gedrückt=\(selected), erwartet=\(expected), Clipboard=\(NSPasteboard.general.string(forType: .string) ?? "nil")"])
            }
            FileHandle.standardError.write(Data("PATH_COPY_MENU passed \(markerID)\n".utf8))
        }
    }

    /// Prüft im echten Fenster: (a) Nach dem Projekt-Öffnen erscheint der
    /// gemeinsame Seitenleisten- Kopf (`sidebarProjectHeader`) im
    /// Accessibility-Baum. (b) Der Ansichts-Umschalter (`viewModePicker`) liegt
    /// in der Fußzeile, sobald die geladene Datei mehr als eine Ansicht bietet.
    /// (c) Für einen ungespeicherten Tab (nur Text-Ansicht) verschwindet der
    /// Umschalter wieder.
    private static func runSidebarHeaderTest() {
        testLabel = "sidebarheader"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-sidebarheader-\(UUID().uuidString)")
        let project = base.appendingPathComponent("projekt")
        do {
            try fm.createDirectory(at: project, withIntermediateDirectories: true)
            try fm.createDirectory(at: base.appendingPathComponent("nachbar"),
                                   withIntermediateDirectories: true)
            try "KOPFTEST".write(to: project.appendingPathComponent("notiz.txt"),
                                 atomically: true, encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Testprojekt nicht anlegbar: \(error.localizedDescription)")
        }
        ws.openProject(at: project)
        ws.loadFile(at: project.appendingPathComponent("notiz.txt")) { ok in
            guard ok else {
                try? fm.removeItem(at: base)
                finish(false, "(setup) notiz.txt lädt nicht")
            }
            pollSidebarHeader(ws, base: base)
        }
    }

    private static func pollSidebarHeader(_ ws: Workspace, base: URL) {
        var headerFound = false
        var pickerFound = false
        waitFor(budget: 10, pause: 0.25,   // 10 s Beobachtungsfenster
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    headerFound = content.map { markerViewExists(id: "sidebarProjectHeader", in: $0) } ?? false
                    pickerFound = content.map { markerViewExists(id: "viewModePickerMarker", in: $0) } ?? false
                    return headerFound && pickerFound
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Seitenleisten-Kopf=\(headerFound), "
                        + "Fußzeilen-Umschalter=\(pickerFound) — \(book.summary)")
                },
                then: {
                    // (c) Ungespeicherter Tab bietet nur die Text-Ansicht — der
                    // Umschalter muss aus der Fußzeile verschwinden.
                    Task { @MainActor in
                        do {
                            try await verifyPathCopyMenus(ws)
                            try await verifyExternalFileLocations(ws, base: base)
                        }
                        catch {
                            try? FileManager.default.removeItem(at: base)
                            finish(false, "Finder-Kontextmenüs: \(error.localizedDescription)")
                        }
                        ws.openNewTab()
                        pollViewModePickerGone(base: base)
                    }
                })
    }

    @MainActor
    private static func verifyExternalFileLocations(_ workspace: Workspace, base: URL) async throws {
        let base = base.canonicalFileURL
        func require(_ value: Bool, _ message: String) throws {
            if !value { throw NSError(domain: "FileLocations", code: 1, userInfo: [NSLocalizedDescriptionKey: message]) }
        }
        func wait(_ condition: () -> Bool) async throws {
            for _ in 0..<200 {
                if condition() { return }
                try await Task.sleep(for: .milliseconds(50))
            }
            try require(condition(), "Pfad oder Ansicht wurde nicht aktualisiert")
        }
        guard let original = workspace.activeTab?.url,
              let window = CommandTargeting.registeredWindow(for: workspace), let root = window.contentView else {
            throw NSError(domain: "FileLocations", code: 2)
        }
        try await wait { workspace.projectLocationReference != nil }
        workspace.activeTabContent.wrappedValue = "KOPFTEST – ungespeichert"
        let renamed = original.deletingLastPathComponent().appendingPathComponent("Umbenannt.txt")
        try FileManager.default.moveItem(at: original, to: renamed)
        workspace.checkExternalChanges()
        try await wait { workspace.activeTab?.url == renamed && markerViewExists(id: "fileTreeRow-Umbenannt.txt-voll", in: root) }
        try require(workspace.activeTab?.content == "KOPFTEST – ungespeichert", "Ungespeicherter Inhalt verloren")
        try await verifyPathCopyMenus(workspace)
        let newDirectory = base.appendingPathComponent("Neuer Ordner").canonicalFileURL
        try FileManager.default.moveItem(at: renamed.deletingLastPathComponent(), to: newDirectory)
        workspace.checkExternalChanges()
        try await wait { workspace.projectURL?.path == newDirectory.path && workspace.activeTab?.url?.path == newDirectory.appendingPathComponent("Umbenannt.txt").path }
        try await wait { markerViewExists(id: "fileTreeRow-Umbenannt.txt-voll", in: root) }
        try await verifyPathCopyMenus(workspace)
        let target = base.appendingPathComponent("nachbar/Gespeichert.txt").canonicalFileURL
        var saved: Bool?
        workspace.saveTabAs(id: workspace.activeTab!.id, to: target, expectedTargetState: .absent, isMarkdown: false) { saved = $0 }
        try await wait { saved == true && workspace.projectURL == target.deletingLastPathComponent() }
        try await wait { markerViewExists(id: "fileTreeRow-Gespeichert.txt-voll", in: root) }
        try await verifyPathCopyMenus(workspace)
        try require(try String(contentsOf: target, encoding: .utf8) == "KOPFTEST – ungespeichert", "Gespeicherter Inhalt weicht ab")
        if let directory = ProcessInfo.processInfo.environment["FASTRA_FILE_LOCATIONS_DIR"] {
            let output = URL(fileURLWithPath: directory).appendingPathComponent("file-locations.png")
            try FileManager.default.createDirectory(at: output.deletingLastPathComponent(), withIntermediateDirectories: true)
            await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
                typeScrollCapture(window: window) { snapshot in
                    try? snapshot?.data.write(to: output)
                    continuation.resume()
                }
            }
        }
    }

    private static func pollViewModePickerGone(base: URL) {
        waitFor(budget: 5, pause: 0.25,
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    let pickerFound = content.map { markerViewExists(id: "viewModePickerMarker", in: $0) } ?? true
                    return !pickerFound
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Umschalter bleibt trotz ungespeicherten Tabs sichtbar — \(book.summary)")
                },
                then: {
                    try? FileManager.default.removeItem(at: base)
                    finish(true, "Kopf + Fußzeilen-Umschalter real im Fenster layoutet; "
                        + "Umschalter verschwindet für ungespeicherte Tabs")
                })
    }

    private static func runEditorOptionsTest() {
        testLabel = "editoroptions"
        Task { @MainActor in
            guard let ws = Workspace.shared,
                  let window = CommandTargeting.registeredWindow(for: ws),
                  let root = window.contentView else { finish(false, "Dokumentfenster fehlt") }
            func require(_ value: Bool, _ message: String) throws {
                if !value { throw NSError(domain: "EditorOptionsTest", code: 1,
                                           userInfo: [NSLocalizedDescriptionKey: message]) }
            }
            func wait(_ stage: String, _ condition: () -> Bool) async throws {
                for _ in 0..<150 {
                    if condition() { return }
                    try await Task.sleep(nanoseconds: 50_000_000)
                }
                try require(condition(), "Ansicht wurde nicht bereit: \(stage)")
            }
            func capture(_ name: String, _ target: NSWindow) async {
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_EDITOR_OPTIONS_DIR"],
                      !directory.isEmpty else { return }
                let url = URL(fileURLWithPath: directory).appendingPathComponent(name + ".png")
                try? FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
                    typeScrollCapture(window: target) { snapshot in
                        try? snapshot?.data.write(to: url)
                        continuation.resume()
                    }
                }
            }
            var optionsObserver: NSObjectProtocol?
            do {
                let source = "Leerzeichen  zwischen Wörtern\n\tTabulator\nEnde 😀\n"
                // Eigenes Dokument statt des möglicherweise asynchronen
                // Neu-Tab-Befehls einer wiederhergestellten WYSIWYG-Sitzung.
                let textTab = EditorTab(title: "Zeichen.txt", path: "", content: source)
                ws.projectURL = nil
                ws.showSearchDialog = false
                ws.tabs = [textTab]
                ws.activeTabID = textTab.id
                window.setContentSize(NSSize(width: 900, height: 650))
                try await wait("Textdokument") { (editorTextView(in: root) as? TextView)?.string == source }
                guard let textView = editorTextView(in: root) as? TextView else { finish(false, "Texteditor fehlt") }
                let dirty = ws.activeTab?.isDirty
                textView.selectionManager.setSelectedRange(NSRange(location: 4, length: 5))
                guard let gear = markerView(id: "editorOptionsButton", in: root) else {
                    finish(false, "Zahnrad fehlt")
                }
                var shownOptions: NSPopover?
                let popoverObserver = NotificationCenter.default.addObserver(
                    forName: NSPopover.didShowNotification, object: nil, queue: .main
                ) { notification in
                    MainActor.assumeIsolated {
                        guard let popover = notification.object as? NSPopover,
                              let content = popover.contentViewController?.view,
                              markerViewExists(id: "editorOptionsPopover", in: content) else { return }
                        shownOptions = popover
                        FileHandle.standardError.write(Data("EDITOR_OPTIONS_POPOVER_DID_SHOW\n".utf8))
                    }
                }
                optionsObserver = popoverObserver
                try require(sendMouseClick(at: gear.convert(NSPoint(x: gear.bounds.midX, y: gear.bounds.midY), to: nil),
                                           in: window, modifiers: [], viaApp: true), "Zahnrad nicht klickbar")
                var panel: NSWindow?
                try await wait("Options-Popover") {
                    panel = NSApp.windows.first { candidate in
                        candidate.contentView.map { markerViewExists(id: "editorOptionsPopover", in: $0) } == true
                    }
                    return panel != nil && shownOptions?.isShown == true
                }
                guard let panel, let panelRoot = panel.contentView,
                      let toggle = markerView(id: "showInvisiblesToggle", in: panelRoot) else {
                    NotificationCenter.default.removeObserver(popoverObserver)
                    finish(false, "Popover oder Zeichenschalter fehlt")
                }
                // Die Markierung existiert schon während der Öffnungsanimation.
                // Ein synthetischer Klick braucht die endgültige Bildschirmposition,
                // auch wenn keine optionale Aufnahme den Ablauf verzögert.
                var previousToggleFrame: NSRect?
                var stableToggleTicks = 0
                try await wait("Popover-Geometrie") {
                    let frame = panel.convertToScreen(toggle.convert(toggle.bounds, to: nil))
                    if panel.isVisible && panel.alphaValue >= 0.99 && frame == previousToggleFrame {
                        stableToggleTicks += 1
                    } else { stableToggleTicks = 0 }
                    previousToggleFrame = frame
                    return stableToggleTicks >= 3
                }
                await capture("options", panel)
                try require(sendMouseClick(at: toggle.convert(NSPoint(x: toggle.bounds.midX, y: toggle.bounds.midY), to: nil),
                                           in: panel, modifiers: [], viaApp: true), "Zeichenschalter nicht klickbar")
                try await wait("Hauptschalter ein") { ws.editorDisplayOptions.showInvisibles }
                try await wait("Zeichen-Renderer ein") {
                    textView.layoutManager.invisibleCharacterDelegate?.triggerCharacters.contains(32) == true
                }
                let delegate = textView.layoutManager.invisibleCharacterDelegate
                for character: UInt16 in [32, 9, 10] {
                    try require(delegate?.invisibleStyle(for: character, at: NSRange(location: 1, length: 1),
                                                       lineRange: NSRange(location: 0, length: source.utf16.count)) != nil,
                                "Zeichen \(character) besitzt keinen sichtbaren Ersatz")
                }
                // Über das echte Darstellungsmenü ausschalten: prüft Routing
                // und Bindung unabhängig vom Popover.
                panel.close()
                window.makeKeyAndOrderFront(nil)
                // SwiftUI baut Menüeinträge erst beim echten Öffnen auf.
                // Der Timer muss auch während AppKits Menü-Tracking laufen.
                @MainActor func checkInvisiblesMenu(enabled: Bool, press: Bool) async -> Bool {
                    await withCheckedContinuation { continuation in
                        guard let mainMenu = NSApp.mainMenu,
                              let menuRoot = mainMenu.items.first(where: {
                                  $0.title == "Darstellung" || $0.title == "View"
                              }), let viewMenu = menuRoot.submenu else {
                            continuation.resume(returning: false)
                            return
                        }
                        var timer: Timer?
                        var ticks = 0
                        var pressed = false
                        func conclude(_ result: Bool) {
                            timer?.invalidate()
                            timer = nil
                            viewMenu.cancelTracking()
                            mainMenu.cancelTracking()
                            continuation.resume(returning: result)
                        }
                        timer = Timer(timeInterval: 0.1, repeats: true) { _ in
                            ticks += 1
                            if ticks > 50 { conclude(false); return }
                            if !pressed {
                                pressed = true
                                _ = menuRoot.accessibilityPerformPress()
                            } else if let item = viewMenu.items.first(where: {
                                $0.title == L10n.string("Unsichtbare Zeichen anzeigen")
                            }) {
                                if press && item.isEnabled { _ = item.accessibilityPerformPress() }
                                conclude(item.isEnabled == enabled)
                            }
                        }
                        if let timer {
                            RunLoop.main.add(timer, forMode: .common)
                            RunLoop.main.add(timer, forMode: .eventTracking)
                        }
                    }
                }
                let menuWorked = await checkInvisiblesMenu(enabled: true, press: true)
                try require(menuWorked, "Menüeintrag fehlt oder ist nicht bedienbar")
                try await wait("Menü schaltet aus") { !ws.editorDisplayOptions.showInvisibles }
                ws.setEditorDisplayOption(\.showSpaces, false)
                ws.setEditorDisplayOption(\.showInvisibles, true)
                try await wait("Unterauswahl") {
                    let triggers = textView.layoutManager.invisibleCharacterDelegate?.triggerCharacters
                    return triggers?.contains(32) == false && triggers?.contains(9) == true
                }
                try require(textView.string == source && ws.activeTab?.content == source
                            && ws.activeTab?.isDirty == dirty,
                            "Darstellungswechsel verändert Dokument oder Änderungsstatus")
                try require(textView.selectedRange() == NSRange(location: 4, length: 5), "Auswahl ging verloren")
                ws.setEditorDisplayOption(\.showGutter, false)
                try await Task.sleep(nanoseconds: 250_000_000)
                await capture("invisibles", window)
                NSApp.appearance = NSAppearance(named: .darkAqua)
                try await Task.sleep(nanoseconds: 300_000_000)
                await capture("invisibles-dark", window)
                NSApp.appearance = NSAppearance(named: .aqua)
                let project = selfTestTemporaryDirectory().appendingPathComponent("editor-options-project")
                try FileManager.default.createDirectory(at: project, withIntermediateDirectories: true)
                ws.projectURL = project
                ws.sidebarWidth = SidebarLayout.minimumSidebarWidth
                workspaceDefaults().set(true, forKey: "editor.sidebarVisible")
                window.setContentSize(NSSize(width: 760, height: 680))
                try await Task.sleep(nanoseconds: 300_000_000)
                guard let narrowGear = markerView(id: "editorOptionsButton", in: root),
                      let close = window.standardWindowButton(.closeButton) else {
                    finish(false, "Schmale Titelleiste unvollständig")
                }
                let gearPoint = narrowGear.convert(NSPoint.zero, to: root)
                let closeFrame = close.convert(close.bounds, to: root)
                try require(gearPoint.x > closeFrame.maxX + 40
                            && gearPoint.x + 14 < CGFloat(SidebarLayout.minimumSidebarWidth),
                            "Zahnrad überlagert Ampelknöpfe oder Tabs bei schmaler Seitenleiste")
                await capture("sidebar-narrow", window)
                ws.projectURL = nil
                try FileManager.default.removeItem(at: project)
                for tab in [EditorTab(title: "Verlauf", path: "Git", content: "Historie", gitKind: .log),
                            EditorTab(title: "Vorversion", path: "", content: "Vorher", readOnlyReason: "Vorversion")] {
                    ws.tabs = [tab]
                    ws.activeTabID = tab.id
                    try await Task.sleep(nanoseconds: 300_000_000)
                    try require(await checkInvisiblesMenu(enabled: false, press: false),
                                "Zeichen-Menü muss in \(tab.title) deaktiviert sein")
                    await capture(tab.gitKind == nil ? "readonly-options" : "history-options", window)
                }

                workspaceDefaults().set(false, forKey: MarkdownEditingMode.defaultsKey)
                workspaceDefaults().set(true, forKey: "markdown.integratedPreview")
                let markdown = "# Listenabstände\n\n" + ["Suchfeld", "Art", "Firma", "Vorname", "Nachname", "Straße", "PLZ", "Ort"]
                    .map { "- \($0) = OK" }.joined(separator: "\n\n")
                    + "\n\n- [x] Prüfung bestanden\n\n- [ ] Nächster Schritt\n\nAbsatz nach der Liste.\n"
                let tab = EditorTab(title: "Listen.md", path: "", content: markdown)
                ws.tabs = [tab]
                ws.activeTabID = tab.id
                try await wait("Markdown-Vorschau") { markdownWebView(in: root) != nil }
                for visual in [false, true] {
                    if visual {
                        ws.tabs[0].markdownVisualOverride = true
                        try await wait("WYSIWYG") { ws.visualMarkdownEditor?.ready == true }
                    }
                    for width: CGFloat in [760, 1100] {
                        window.setContentSize(NSSize(width: width, height: 680))
                        try await Task.sleep(nanoseconds: 300_000_000)
                        await capture("lists-\(visual ? "wysiwyg" : "preview")-\(Int(width))", window)
                    }
                }
                try require(ws.activeTab?.content == markdown, "Ansichtswechsel änderte Markdown")
                if let optionsObserver { NotificationCenter.default.removeObserver(optionsObserver) }
                finish(true, "Zahnrad, Popover, echter Menüpfad, drei Zeichenarten, Unteroptionen, unveränderter Text/Auswahl/Änderungsstatus und beide Markdown-Ansichten bei 760/1100 pt geprüft")
            } catch {
                if let optionsObserver { NotificationCenter.default.removeObserver(optionsObserver) }
                finish(false, error.localizedDescription)
            }
        }
    }

    // MARK: - Selbsttest footerfit

    /// Liegt die Fußzeile vollständig im Fenster?
    ///
    /// Sie hatte eine feste Höhe von 24 Punkten. Sobald der Ansichts-
    /// Umschalter dazukam — er erscheint nur für eine gespeicherte Datei und
    /// ist als Segmentregler höher als reiner Text —, wuchs ihr Inhalt über
    /// diesen Rahmen hinaus, und der Fensterrand schnitt ihn unten ab. Genau
    /// dieser Fall wird hier mit einer echten Datei nachgestellt und am
    /// wirklichen Layout gemessen.
    private static func runFooterFitTest() {
        testLabel = "footerfit"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let window = mainWindowForAXChecks(), let root = window.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-footerfit-\(UUID().uuidString)")
        let doc = base.appendingPathComponent("fusszeile.txt")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            try "Zeile 1\nZeile 2\n".write(to: doc, atomically: true, encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixture nicht schreibbar: \(error.localizedDescription)")
        }
        ws.loadFile(at: doc) { ok in
            guard ok else {
                try? fm.removeItem(at: base)
                finish(false, "(setup) fusszeile.txt lädt nicht")
            }
            pollFooterFit(root: root, base: base)
        }
    }

    private static func pollFooterFit(root: NSView, base: URL) {
        // Erst messen, wenn die Fußzeile steht und der Umschalter wirklich
        // drin liegt — er ist der Grund, aus dem sie höher wird.
        var footer: NSView?
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard let candidate = markerView(id: "footerBar", in: root),
                          markerViewExists(id: "viewModePickerMarker", in: root),
                          markerViewExists(id: "formatDocumentButtonMarker", in: root),
                          candidate.frame.height > 1 else { return false }
                    footer = candidate
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "keine gemessene Fußzeile mit Ansichts- und Formatieren-Schalter — \(book.summary)")
                },
                then: {
                    guard let footer else { finish(false, "Fußzeile nach Erfolg verschwunden") }
                    let frame = footer.convert(footer.bounds, to: root)
                    // SwiftUIs AppKit-Views sind geflippt: y wächst nach unten, die
                    // Unterkante ist `maxY`. Vor der Zusage trotzdem nachfragen.
                    let overflow = root.isFlipped
                        ? frame.maxY - root.bounds.maxY
                        : root.bounds.minY - frame.minY
                    try? FileManager.default.removeItem(at: base)
                    guard overflow <= 0.5 else {
                        finish(false, String(
                            format: "Fußzeile ragt %.1f pt über den unteren Fensterrand hinaus "
                                + "(Höhe %.1f pt, Fenster %.1f pt)",
                            overflow, frame.height, root.bounds.height
                        ))
                    }
                    finish(true, String(
                        format: "Fußzeile mit Ansichts-Umschalter vollständig im Fenster "
                            + "(Höhe %.1f pt, Reserve %.1f pt)",
                        frame.height, -overflow
                    ))
                })
    }

    // MARK: - Selbsttest windowheight

    /// Wächst ein zu flach gespeichertes Fenster wirklich auf eine praktische
    /// Höhe — und bleibt die Korrektur danach einmalig?
    ///
    /// Gemessen wird am echten Fenster mit einer eigenen Defaults-Suite; die
    /// Merkmarke des Nutzers bleibt dadurch unberührt.
    private static func runWindowHeightTest() {
        testLabel = "windowheight"
        guard let window = mainWindowForAXChecks() else {
            finish(false, "kein Hauptfenster gefunden")
        }
        guard let screen = window.screen ?? NSScreen.main else {
            finish(.environment, "Umgebungsproblem: kein Bildschirm ermittelbar")
        }
        let suiteName = "fastra-windowheight-\(UUID().uuidString)"
        guard let defaults = UserDefaults(suiteName: suiteName) else {
            finish(.environment, "Umgebungsproblem: (setup) eigene Defaults-Suite nicht anlegbar")
        }
        defaults.removePersistentDomain(forName: suiteName)
        // Beim zentralen Aufräumer anmelden: Jeder Abschluss dieses Tests geht
        // über `finish` und damit über `exit()`. Der Swift-Stack wird dabei
        // nicht abgewickelt, das `defer` unten liefe also nie — ohne die
        // Anmeldung bliebe pro Selbsttestlauf eine weitere Preferences-Domain
        // liegen (der Stale-Aufräumer fasst sie erst nach einer Stunde an).
        // Das `defer` bleibt trotzdem stehen: Es greift, sollte der Test
        // irgendwann regulär zurückkehren.
        guard TestDefaultsPurge.register(suiteName) else {
            finish(.environment, "Umgebungsproblem: Test-Preferences-Suite nicht registrierbar")
        }
        defer { defaults.removePersistentDomain(forName: suiteName) }

        let visible = screen.visibleFrame
        let expected = MainWindowSizing.newWindowSize(inVisibleScreen: visible.size).height
        // Absichtlich flache Fenstergeometrie.
        let flat = NSRect(x: visible.minX + 40, y: visible.maxY - 460,
                          width: MainWindowSizing.defaultWidth, height: 420)
        window.setFrame(flat, display: true)
        guard abs(window.frame.height - 420) < 1 else {
            finish(.environment, "Umgebungsproblem: Fenster nimmt die Testgröße nicht an "
                + "(\(window.frame.height) pt)")
        }

        guard MainActor.assumeIsolated({
            MainWindowHeightNormalization.runOnce(defaults: defaults)
        }) else {
            finish(false, "Korrektur lief nicht, obwohl sie noch nie lief")
        }
        let corrected = window.frame.height
        guard corrected >= expected - 1 else {
            finish(false, String(
                format: "Fenster bleibt mit %.0f pt zu flach (erwartet mindestens %.0f pt)",
                corrected, expected
            ))
        }
        guard corrected <= visible.height + 1 else {
            finish(false, String(format: "Fenster ragt mit %.0f pt über den Bildschirm",
                                 corrected))
        }

        // Einmaligkeit: Ein zweiter Aufruf darf eine bewusst kleine Größe
        // nicht wieder anfassen.
        window.setFrame(flat, display: true)
        guard !MainActor.assumeIsolated({
            MainWindowHeightNormalization.runOnce(defaults: defaults)
        }) else {
            finish(false, "Korrektur lief ein zweites Mal")
        }
        guard abs(window.frame.height - 420) < 1 else {
            finish(false, "Korrektur hat die bewusst kleine Größe erneut verändert")
        }
        finish(true, String(
            format: "flaches Fenster von 420 pt auf %.0f pt korrigiert "
                + "(mindestens %.0f pt bei %.0f pt Bildschirmhöhe), Korrektur bleibt einmalig",
            corrected, expected, visible.height
        ))
    }

    // MARK: - Selbsttest mdformat

    /// Folgt die Markdown-Vorschau der Formatwahl aus der Fußzeile?
    ///
    /// Geprüft wird an einer Datei ohne Markdown-Endung:
    /// (a) Vor der Wahl gibt es keine Vorschau.
    /// (b) Wahl „Markdown" öffnet sie wirklich (echte WKWebView im Layout).
    /// (c) Wahl eines anderen Formats schließt sie wieder.
    /// (d) Die Wahl ist danach für diese Datei gemerkt.
    private static func runMarkdownFormatSwitchTest() {
        testLabel = "mdformat"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let window = mainWindowForAXChecks(), let root = window.contentView else {
            finish(false, "kein Hauptfenster gefunden")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-mdformat-\(UUID().uuidString)")
        // Bewusst ohne Endung: Genau hier kann die Automatik nichts erkennen.
        let doc = base.appendingPathComponent("protokoll")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            try "# Protokoll\n\nErster Absatz.\n".write(to: doc, atomically: true,
                                                        encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixture nicht schreibbar: \(error.localizedDescription)")
        }
        ws.loadFile(at: doc) { ok in
            guard ok else {
                try? fm.removeItem(at: base)
                finish(false, "(setup) protokoll lädt nicht")
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                guard markdownWebView(in: root) == nil else {
                    try? fm.removeItem(at: base)
                    finish(false, "(a) Vorschau ist ohne Markdown-Format schon offen")
                }
                ws.setLanguageOverride(.markdown)
                pollMarkdownFormatPreview(ws, root: root, base: base,
                                          document: doc)
            }
        }
    }

    private static func pollMarkdownFormatPreview(_ ws: Workspace, root: NSView,
                                                  base: URL, document: URL) {
        waitFor(budget: 10, pause: 0.25,
                condition: { markdownWebView(in: root) != nil },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "(b) Vorschau öffnet nicht, obwohl das Format auf "
                        + "Markdown steht — \(book.summary)")
                },
                then: {
                    // (d) Gemerkte Wahl der Datei — sie muss ein erneutes Öffnen
                    // überleben, sonst ist die Endungslosigkeit wieder das Problem.
                    guard ws.languageChoices.choiceID(for: document)
                            == LanguageMenuSupport.Entry.grammar(.markdown).id else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "(d) Formatwahl wurde für die Datei nicht gemerkt")
                    }
                    ws.setLanguageOverride(.json)
                    pollMarkdownFormatPreviewClosed(root: root, base: base)
                })
    }

    private static func pollMarkdownFormatPreviewClosed(root: NSView, base: URL) {
        waitFor(budget: 10, pause: 0.25,
                condition: { markdownWebView(in: root) == nil },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "(c) Vorschau bleibt offen, obwohl das Format nicht mehr "
                        + "Markdown ist — \(book.summary)")
                },
                then: {
                    try? FileManager.default.removeItem(at: base)
                    finish(true, "Vorschau folgt der Formatwahl der Fußzeile: öffnet bei "
                        + "Markdown, schließt beim Wechsel, Wahl bleibt gemerkt")
                })
    }

    // MARK: - Selbsttest sidebarfilter

    /// Prüft den Dateinamens-Filter der Projekt-Seitenleiste im echten
    /// Fenster:
    /// (a) Ausgangslage: Datei der obersten Ebene gerendert, Datei im
    ///     eingeklappten Unterordner nicht.
    /// (b) Filter tippen (case-insensitiv) → Treffer-Datei erscheint samt
    ///     aufgeklapptem Elternordner, Nicht-Treffer verschwinden, der
    ///     Zähler „1 von 3 Dateien" ist real gerendert.
    /// (c) Filter leeren → voriger Aufklappzustand kehrt zurück (Unterordner
    ///     wieder zu, Nicht-Treffer wieder da).
    private static func runSidebarFilterTest() {
        testLabel = "sidebarfilter"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-sidebarfilter-\(UUID().uuidString)")
        let project = base.appendingPathComponent("projekt")
        do {
            try fm.createDirectory(at: project.appendingPathComponent("sub"),
                                   withIntermediateDirectories: true)
            try "A".write(to: project.appendingPathComponent("eins.txt"),
                          atomically: true, encoding: .utf8)
            try "B".write(to: project.appendingPathComponent("zwei.md"),
                          atomically: true, encoding: .utf8)
            try "C".write(to: project.appendingPathComponent("sub/drei-treffer.txt"),
                          atomically: true, encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Testprojekt nicht anlegbar: \(error.localizedDescription)")
        }
        // Die Regression wechselt auf Graph; dafür muss die Fixture ein
        // echtes Repository sein, sonst zeigt die App absichtlich Dateien.
        GitRunner.runDetailed(["init", "-b", "main"], in: project) { outcome in
            DispatchQueue.main.async {
                guard case .completed(let result) = outcome, result.ok else {
                    finish(.environment, "Testrepository nicht initialisierbar")
                }
                ws.openProject(at: project)
                pollSidebarFilterBaseline(ws, base: base)
            }
        }
    }

    private static func pollSidebarFilterBaseline(_ ws: Workspace, base: URL) {
        // Die Marker-IDs enden auf die Filterphase („voll"/„gefiltert") —
        // gepoolte LazyVStack-Views alter Phasen stören die Prüfung so nie.
        var topLevelVisible = false
        var nestedHidden = false
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    topLevelVisible = content.map {
                        markerViewExists(id: "fileTreeRow-zwei.md-voll", in: $0)
                    } ?? false
                    nestedHidden = content.map {
                        !markerViewExists(id: "fileTreeRow-drei-treffer.txt-voll", in: $0)
                    } ?? false
                    return topLevelVisible && nestedHidden && ws.gitStatus != nil
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Ausgangslage falsch: zwei.md sichtbar=\(topLevelVisible), "
                        + "verschachtelte Datei verborgen=\(nestedHidden) — \(book.summary)")
                },
                then: {
                    // Groß geschrieben tippen — die Datei heißt klein „…-treffer…":
                    // belegt die Case-Insensitivität am echten Baum.
                    ws.fileTreeFilterQuery = "TREFFER"
                    pollSidebarFilterFiltered(ws, base: base)
                })
    }

    private static func pollSidebarFilterFiltered(_ ws: Workspace, base: URL) {
        // 10 s (Debounce 150 ms + Scan)
        var matchVisible = false
        var nonMatchHidden = false
        var counterVisible = false
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    matchVisible = content.map {
                        markerViewExists(id: "fileTreeRow-drei-treffer.txt-gefiltert", in: $0)
                    } ?? false
                    nonMatchHidden = content.map {
                        !markerViewExists(id: "fileTreeRow-zwei.md-gefiltert", in: $0)
                    } ?? false
                    counterVisible = content.map {
                        markerViewExists(id: "sidebarFilterState-n1-m3", in: $0)
                    } ?? false
                    return matchVisible && nonMatchHidden && counterVisible
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Filter „TREFFER\u{201C}: Treffer sichtbar=\(matchVisible), "
                        + "Nicht-Treffer verborgen=\(nonMatchHidden), Zähler 1/3=\(counterVisible) "
                        + "— \(book.summary)")
                },
                then: {
                    ws.fileTreeFilterQuery = ""
                    pollSidebarFilterRestored(base: base)
                })
    }

    private static func pollSidebarFilterRestored(base: URL) {
        var nestedHiddenAgain = false
        var topLevelBack = false
        waitFor(budget: 5, pause: 0.25,
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    nestedHiddenAgain = content.map {
                        !markerViewExists(id: "fileTreeRow-drei-treffer.txt-voll", in: $0)
                    } ?? false
                    topLevelBack = content.map {
                        markerViewExists(id: "fileTreeRow-zwei.md-voll", in: $0)
                    } ?? false
                    return nestedHiddenAgain && topLevelBack
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Nach Filter-Leeren: Unterordner wieder zu=\(nestedHiddenAgain), "
                        + "zwei.md wieder da=\(topLevelBack) — \(book.summary)")
                },
                then: {
                    guard let ws = Workspace.shared else { finish(false, "Workspace fehlt") }
                    pollSidebarFilterInactiveMutation(ws, base: base)
                })
    }

    private static func pollSidebarFilterInactiveMutation(_ ws: Workspace, base: URL) {
        ws.fileTreeFilterQuery = "neu"
        waitFor(budget: 5, pause: 0.25,
            condition: { ws.fileTreeFilterResult?.matchCount == 0 && ws.fileTreeFilterResult?.query == "neu" },
            onTimeout: { book in finish(false, "Nulltreffer-Ausgangslage fehlt — \(book.summary)") },
            then: {
                ws.sidebarMode = .graph
                // Der Dateien-Tab muss vor der Änderung abgebaut sein.
                let removedAfter = Date().addingTimeInterval(0.5)
                waitFor(budget: 3, pause: 0.1, condition: {
                    guard Date() >= removedAfter,
                          let content = mainWindowForAXChecks()?.contentView else { return false }
                    return !markerViewExists(id: "sidebarFilterState-n0-m3", in: content)
                },
                    onTimeout: { book in finish(false, "Tababbau verzögert — \(book.summary)") },
                    then: {
                        do {
                            try "neu".write(to: base.appendingPathComponent("projekt/neu.txt"),
                                atomically: true, encoding: .utf8)
                        } catch { finish(false, "Fixture nicht schreibbar: \(error)") }
                        ws.refreshAfterProjectFileMutation()
                        // Der neue SinceNow-Wächter darf das frühere Ereignis
                        // beim Rückwechsel nicht als zufällige Hilfe bekommen.
                        let eventsAfter = Date().addingTimeInterval(0.5)
                        waitFor(budget: 3, pause: 0.1, condition: { Date() >= eventsAfter },
                            onTimeout: { book in finish(false, "Dateiereignisse verzögert — \(book.summary)") },
                            then: { pollSidebarFilterMutationRestored(ws, base: base) })
                    })
            })
    }

    private static func pollSidebarFilterMutationRestored(_ ws: Workspace, base: URL) {
        ws.sidebarMode = .files
        waitFor(budget: 10, pause: 0.25,
            condition: {
                guard let content = mainWindowForAXChecks()?.contentView else { return false }
                return markerViewExists(id: "fileTreeRow-neu.txt-gefiltert", in: content)
                    && markerViewExists(id: "sidebarFilterState-n1-m4", in: content)
            },
            onTimeout: { book in
                try? FileManager.default.removeItem(at: base)
                finish(false, "Neue Datei nach Graph-Rückkehr verborgen — \(book.summary)")
            },
            then: {
                try? FileManager.default.removeItem(at: base)
                finish(true, "Filterzeilen, Zähler und Aufklappzustand korrekt; eigene Änderung im Graph-Tab nach Rückkehr sichtbar")
            })
    }

    // MARK: - Selbsttest tabflood (Layout-Invariante)

    /// Feste Seitenleisten-Elemente müssen mit 40 offenen Tabs im Fenster
    /// bleiben. Die tatsächliche Geometrie von Kopf und „Datei öffnen…“-Knopf
    /// prüfen; bloße Existenz im View-Baum erkennt verdrängte Views nicht.
    // MARK: - Seitenleiste: ohne Projekt keine, Umschalten schnell und ohne Wachstum

    /// Ohne Projekt keine Seitenleiste, auch bei weiteren Tabs. Mit Projekt
    /// bleibt sie beim Ausblenden montiert. Hunderte Umschaltungen prüfen Dauer
    /// und Speicherentwicklung ohne erneuten Dateibaumaufbau.
    private static var sidebarToggleFixtureDirectory: URL?

    private static func runSidebarToggleTest() {
        testLabel = "sidebartoggle"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard let content = mainWindowForAXChecks()?.contentView else {
            finish(false, "kein Hauptfenster")
        }
        let defaults = SelfTest.workspaceDefaults()
        defaults.set(true, forKey: "editor.sidebarVisible")
        ws.enterWelcomeState()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
            guard ws.isWelcomeScreen, ws.projectURL == nil else {
                finish(false, "Willkommenszustand nicht erreicht")
            }
            guard !markerViewExists(id: "sidebarVisibleMarker", in: content),
                  !markerViewExists(id: "sidebarOpenFileButton", in: content) else {
                finish(false, "Willkommensbildschirm ohne Projekt zeigt eine Seitenleiste")
            }
            // Weitere Tabs ohne Projekt: weiterhin keine Seitenleiste.
            ws.openNewTab()
            ws.openNewTab()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                guard ws.tabs.count >= 3 else { finish(false, "Tabs nicht angelegt") }
                guard !markerViewExists(id: "sidebarVisibleMarker", in: content),
                      !markerViewExists(id: "sidebarOpenFileButton", in: content) else {
                    finish(false, "ohne Projekt zeigt ein Fenster mit mehreren Tabs eine Seitenleiste")
                }
                let base = selfTestTemporaryDirectory()
                    .appendingPathComponent("fastra-sidebartoggle-\(UUID().uuidString)")
                sidebarToggleFixtureDirectory = base
                let project = base.appendingPathComponent("projekt")
                do {
                    try FileManager.default.createDirectory(at: project, withIntermediateDirectories: true)
                    for index in 1...12 {
                        try "Zeile \(index)\n".write(
                            to: project.appendingPathComponent("datei-\(index).txt"),
                            atomically: true, encoding: .utf8)
                    }
                } catch {
                    finish(.environment, "Umgebungsproblem: (setup) Testprojekt nicht anlegbar: \(error.localizedDescription)")
                }
                ws.openProject(at: project)
                pollSidebarToggleReady(ws, content: content, defaults: defaults, base: base)
            }
        }
    }

    private static func pollSidebarToggleReady(_ ws: Workspace, content: NSView,
                                               defaults: UserDefaults, base: URL) {
        var header: NSView?
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard markerViewExists(id: "sidebarVisibleMarker", in: content),
                          let candidate = markerView(id: "sidebarProjectHeader", in: content) else { return false }
                    header = candidate
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Seitenleiste erscheint nach Projektöffnung nicht — \(book.summary)")
                },
                then: {
                    guard let header else { finish(false, "Projektkopf nach Erfolg verschwunden") }
                    // Identität des Projektkopfs: Bleibt sie über alle Umschaltungen
                    // gleich, wurde die Seitenleiste nie neu aufgebaut.
                    let headerIdentity = ObjectIdentifier(header)
                    let state = SidebarToggleMeasurement(headerIdentity: headerIdentity)
                    runSidebarToggleCycle(ws, content: content, defaults: defaults, base: base,
                                          state: state, cycle: 0, hiding: true, startedAt: ContinuousClock.now,
                                          tick: 0)
                })
    }

    private final class SidebarToggleMeasurement {
        let headerIdentity: ObjectIdentifier
        var latenciesMs: [Double] = []
        var footprintAfterWarmup: UInt64 = 0
        static let cycles = 300
        static let warmupCycles = 20
        init(headerIdentity: ObjectIdentifier) { self.headerIdentity = headerIdentity }
    }

    /// Ein halber Zyklus: Schalter setzen und warten, bis die Ansicht folgt.
    /// Gemessen wird die Zeit vom Setzen bis zur sichtbaren Wirkung.
    private static func runSidebarToggleCycle(_ ws: Workspace, content: NSView,
                                              defaults: UserDefaults, base: URL,
                                              state: SidebarToggleMeasurement, cycle: Int,
                                              hiding: Bool, startedAt: ContinuousClock.Instant,
                                              tick: Int) {
        if tick == 0 {
            defaults.set(!hiding, forKey: "editor.sidebarVisible")
        }
        let visible = markerViewExists(id: "sidebarVisibleMarker", in: content)
        let settled = hiding ? !visible : visible
        guard settled else {
            guard tick < 400 else {
                try? FileManager.default.removeItem(at: base)
                finish(false, "Seitenleiste folgt dem Schalter nach 2 s nicht (Zyklus \(cycle), \(hiding ? "ausblenden" : "einblenden"))")
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.005) {
                runSidebarToggleCycle(ws, content: content, defaults: defaults, base: base,
                                      state: state, cycle: cycle, hiding: hiding,
                                      startedAt: startedAt, tick: tick + 1)
            }
            return
        }
        let elapsed = startedAt.duration(to: ContinuousClock.now)
        state.latenciesMs.append(Double(elapsed.components.seconds) * 1000
                                 + Double(elapsed.components.attoseconds) / 1e15)
        if !hiding {
            // Der Projektkopf muss derselbe AppKit-Knoten geblieben sein —
            // sonst wurde die Seitenleiste doch neu aufgebaut.
            guard let header = markerView(id: "sidebarProjectHeader", in: content),
                  ObjectIdentifier(header) == state.headerIdentity else {
                try? FileManager.default.removeItem(at: base)
                finish(false, "Seitenleiste wurde beim Einblenden neu aufgebaut (Zyklus \(cycle))")
            }
            let nextCycle = cycle + 1
            if nextCycle == SidebarToggleMeasurement.warmupCycles {
                state.footprintAfterWarmup = physicalFootprint()
            }
            if nextCycle >= SidebarToggleMeasurement.cycles {
                finishSidebarToggleTest(ws, defaults: defaults, base: base, state: state)
                return
            }
            runSidebarToggleCycle(ws, content: content, defaults: defaults, base: base,
                                  state: state, cycle: nextCycle, hiding: true,
                                  startedAt: ContinuousClock.now, tick: 0)
        } else {
            runSidebarToggleCycle(ws, content: content, defaults: defaults, base: base,
                                  state: state, cycle: cycle, hiding: false,
                                  startedAt: ContinuousClock.now, tick: 0)
        }
    }

    private static func finishSidebarToggleTest(_ ws: Workspace, defaults: UserDefaults,
                                                base: URL, state: SidebarToggleMeasurement) {
        let footprintEnd = physicalFootprint()
        let growthMiB = (Double(footprintEnd) - Double(state.footprintAfterWarmup)) / 1_048_576
        let sorted = state.latenciesMs.sorted()
        let mean = sorted.reduce(0, +) / Double(max(1, sorted.count))
        let p95 = sorted[min(sorted.count - 1, Int(Double(sorted.count) * 0.95))]
        let maximum = sorted.last ?? 0
        defaults.set(true, forKey: "editor.sidebarVisible")
        try? FileManager.default.removeItem(at: base)
        NSLog("PERFORMANCE sidebartoggle cycles=%d mean_ms=%.2f p95_ms=%.2f max_ms=%.2f footprint_growth_mib=%.2f",
              SidebarToggleMeasurement.cycles, mean, p95, maximum, growthMiB)
        // Grobe Grenzen: Ein Neuaufbau je Umschaltung läge weit darüber, ein
        // Leck wüchse über 280 Zyklen um zweistellige MiB.
        guard mean < 100 else {
            finish(false, String(format: "Umschalten dauert im Mittel %.1f ms (Grenze 100 ms)", mean))
        }
        guard growthMiB < 12 else {
            finish(false, String(format: "Speicher wuchs über %d Umschaltzyklen um %.1f MiB",
                                 SidebarToggleMeasurement.cycles - SidebarToggleMeasurement.warmupCycles,
                                 growthMiB))
        }
        finish(true, String(format: "Willkommen und weitere Tabs ohne Projekt zeigen keine Seitenleiste; mit Projekt erscheint sie; %d Umschaltzyklen ohne Neuaufbau, im Mittel %.1f ms (p95 %.1f ms, max %.1f ms), Speicher %+.1f MiB nach Aufwärmphase",
                            SidebarToggleMeasurement.cycles, mean, p95, maximum, growthMiB))
    }

    /// Aktueller physischer Speicherbedarf des Prozesses (Bytes).
    private static func physicalFootprint() -> UInt64 {
        var usage = rusage_info_v4()
        let result = withUnsafeMutablePointer(to: &usage) {
            $0.withMemoryRebound(to: rusage_info_t?.self, capacity: 1) {
                proc_pid_rusage(getpid(), RUSAGE_INFO_V4, $0)
            }
        }
        return result == 0 ? usage.ri_phys_footprint : 0
    }

