    private static func pollTabFloodReady(_ ws: Workspace, base: URL) {
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard let content = mainWindowForAXChecks()?.contentView else { return false }
                    return markerViewExists(id: "sidebarProjectHeader", in: content)
                        && markerViewExists(id: "sidebarOpenFileButton", in: content)
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Seitenleiste nicht bereit — \(book.summary)")
                },
                then: {
                    // Fluten: 40 zusätzliche Tabs — deutlich mehr, als je in die
                    // Fensterhöhe passen würden.
                    for _ in 0..<40 { ws.openNewTab() }
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                        verifyTabFloodGeometry(ws, base: base)
                    }
                })
    }

    private static func verifyTabFloodGeometry(_ ws: Workspace, base: URL) {
        // Aufräumen von `base` übernimmt `finish` (tabFloodFixtureDirectory).
        guard ws.tabs.count >= 40 else {
            finish(false, "Nur \(ws.tabs.count) Tabs offen — Fluten fehlgeschlagen")
        }
        guard let window = mainWindowForAXChecks(),
              let content = window.contentView,
              let header = markerView(id: "sidebarProjectHeader", in: content),
              let openButton = markerView(id: "sidebarOpenFileButton", in: content) else {
            finish(false, "Marker nach dem Fluten verschwunden — Seitenleisten-Chrome "
                + "wurde von den Tabs aus dem Layout gedrängt")
        }
        window.layoutIfNeeded()
        // Die Marker sind 0-Punkt-Views im Zentrum ihres Elements; ihr
        // Ursprung in Content-Koordinaten muss im sichtbaren Bereich liegen.
        let bounds = content.bounds.insetBy(dx: -1, dy: -1)
        let headerPoint = header.convert(NSPoint.zero, to: content)
        let buttonPoint = openButton.convert(NSPoint.zero, to: content)
        guard bounds.contains(headerPoint) else {
            finish(false, "Seitenleisten-Kopf liegt außerhalb des Fensters "
                + "(y=\(Int(headerPoint.y)) bei Höhe \(Int(content.bounds.height))) — "
                + "wachsender Inhalt verdrängt das feste Chrome")
        }
        guard bounds.contains(buttonPoint) else {
            finish(false, "„Datei öffnen…\u{201C}-Knopf liegt außerhalb des Fensters "
                + "(y=\(Int(buttonPoint.y)) bei Höhe \(Int(content.bounds.height))) — "
                + "wachsender Inhalt verdrängt das feste Chrome")
        }
        // Der Tab-Zähler-Knopf neben der Tab-Leiste muss den gefluteten
        // Stand zeigen (40 neue Tabs + der Start-Tab = 41; der Marker trägt
        // die angezeigte Zahl im Namen).
        guard markerView(id: "tabCountButton-\(ws.tabs.count)", in: content) != nil else {
            finish(false, "Tab-Zähler-Knopf fehlt oder zeigt nicht "
                + "\(ws.tabs.count) Tabs")
        }
        verifyNativeWindowTabSelection(workspace: ws, window: window) { ok, detail in
            finish(ok, "40 Tabs: Seitenleisten-Kopf und Öffnen-Knopf sichtbar; " + detail)
        }
    }

    /// Öffnet die echte Menüleiste und ihr Dokument-Untermenü über AppKits
    /// öffentlichen Accessibility-Weg. Dessen Bool-Rückgabe ist auf macOS
    /// trotz ausgeführter Aktion false; maßgeblich sind Tracking und Tabwechsel.
    private static func verifyNativeWindowTabSelection(
        workspace: Workspace, window: NSWindow, requireTabChange: Bool = true,
        completion: @escaping (Bool, String) -> Void
    ) {
        let selectedIndex = workspace.tabs.firstIndex(where: { $0.id != workspace.activeTabID })
            ?? (requireTabChange ? nil : workspace.tabs.indices.first)
        guard let mainMenu = NSApp.mainMenu, let windowsMenu = NSApp.windowsMenu,
              let root = mainMenu.items.first(where: { $0.submenu === windowsMenu }),
              let targetIndex = selectedIndex else {
            completion(false, "Fenstermenü oder alternativer Tab fehlt")
            return
        }
        let expectedTitles = workspace.tabs.map {
            WindowTabsMenuModel.rowTitle(title: $0.title, hasUnsavedChanges: $0.hasUnsavedChanges)
        }
        let targetID = workspace.tabs[targetIndex].id
        var tracked = false
        let observer = NotificationCenter.default.addObserver(
            forName: NSMenu.didBeginTrackingNotification, object: mainMenu, queue: .main
        ) { _ in tracked = true }
        var timer: Timer?
        var phase = 0
        var ticks = 0
        var submenu: NSMenu?
        func conclude(_ ok: Bool, _ detail: String) {
            timer?.invalidate()
            timer = nil
            NotificationCenter.default.removeObserver(observer)
            submenu?.cancelTracking()
            windowsMenu.cancelTracking()
            mainMenu.cancelTracking()
            DispatchQueue.main.async { completion(ok, detail) }
        }
        activateApplication(ignoringOtherApps: true)
        window.makeKeyAndOrderFront(nil)
        timer = Timer(timeInterval: 0.1, repeats: true) { _ in
            ticks += 1
            if ticks >= 100 {
                conclude(false, "Nativer Menüwechsel ausstehend: Phase=\(phase), "
                    + "Tracking=\(tracked), aktiv=\(NSApp.isActive)")
                return
            }
            switch phase {
            case 0:
                guard NSApp.isActive, window.isKeyWindow else { return }
                phase = 1
                _ = root.accessibilityPerformPress()
            case 1:
                guard tracked,
                      let document = windowsMenu.items.first(where: {
                          $0.title == window.title && $0.submenu != nil
                      }) else { return }
                submenu = document.submenu
                phase = 2
                _ = document.accessibilityPerformPress()
            case 2:
                guard let submenu, submenu.items.map(\.title) == expectedTitles else { return }
                phase = 3
                _ = submenu.items[targetIndex].accessibilityPerformPress()
            default:
                guard workspace.activeTabID == targetID, window.isKeyWindow else { return }
                conclude(true, "echtes Fenstermenü geöffnet, \(expectedTitles.count) Tab-Einträge "
                    + "geprüft und \(requireTabChange ? "anderen" : "zugehörigen") Tab darüber ausgewählt")
            }
        }
        if let timer {
            // Menü-Tracking bedient den normalen Runloop-Modus nicht.
            RunLoop.main.add(timer, forMode: .common)
            RunLoop.main.add(timer, forMode: .eventTracking)
        }
    }

    // MARK: - Selbsttests tool4d

    /// Prüft den echten localhost-TCP-/LSP-Start gegen ein bereits lokal
    /// installiertes tool4d und eine ausdrücklich übergebene sichere
    /// Projektkopie. Ein `null`-Ergebnis reicht nicht: Der Test besteht nur
    /// bei einem echten LSP-Report. Fehlt tool4d oder die sichere Testkopie,
    /// meldet der Runner bewusst ein Umgebungsproblem statt einen grünen Skip.
    private static func runTool4DLSPIntegrationTest() {
        testLabel = "tool4dlsp"
        guard let tool = Tool4DAssist.installedTool() else {
            finish(.environment, "Umgebungsproblem: tool4d ist nicht installiert — Integrations-Selbsttest übersprungen")
        }
        let environment = ProcessInfo.processInfo.environment
        guard let rawRoot = environment["FASTRA_TOOL4D_TEST_PROJECT"],
              !rawRoot.isEmpty else {
            finish(.environment, "Umgebungsproblem: tool4d ist vorhanden, aber FASTRA_TOOL4D_TEST_PROJECT verweist auf keine sichere Projektkopie")
        }
        let root = URL(fileURLWithPath: rawRoot).canonicalFileURL
        guard Tool4DProjectLocator.projectFile(in: root) != nil else {
            finish(.environment, "Umgebungsproblem: FASTRA_TOOL4D_TEST_PROJECT enthält keine .4DProject-Datei")
        }
        let document: URL?
        if let rawDocument = environment["FASTRA_TOOL4D_TEST_DOCUMENT"], !rawDocument.isEmpty {
            let candidate = URL(fileURLWithPath: rawDocument).canonicalFileURL
            let rootPrefix = root.path.hasSuffix("/") ? root.path : root.path + "/"
            document = candidate.path.hasPrefix(rootPrefix) ? candidate : nil
        } else {
            let methods = root.appendingPathComponent("Project/Sources/Methods", isDirectory: true)
            let files = try? FileManager.default.contentsOfDirectory(
                at: methods, includingPropertiesForKeys: [.isRegularFileKey],
                options: [.skipsHiddenFiles, .skipsPackageDescendants]
            )
            // Die Auswahl bleibt für eine sichere Projektkopie reproduzierbar;
            // bei mehreren Methoden entscheidet nicht die zufällige Reihenfolge
            // des Dateisystems über den Integrations-Selbsttest.
            document = files?
                .filter { $0.pathExtension.lowercased() == "4dm" }
                .sorted {
                    $0.lastPathComponent.localizedStandardCompare($1.lastPathComponent)
                        == .orderedAscending
                }
                .first
        }
        guard let document,
              let text = try? String(contentsOf: document, encoding: .utf8) else {
            finish(.environment, "Umgebungsproblem: sichere 4D-Testmethode fehlt oder ist nicht UTF-8 lesbar")
        }

        let validation = Tool4DLSPValidation()
        retainedTool4DValidation = validation
        validation.start(executable: tool.executableURL, workspaceRoot: root, documentURL: document,
                         text: text,
                         timeout: 6) { result in
            retainedTool4DValidation = nil
            switch result {
            case .success(let diagnostics):
                finish(true, "tool4d-LSP verbunden; Pull-Diagnosen empfangen (\(diagnostics.count))")
            case .failure(.noDiagnosticResult):
                finish(false, "tool4d-LSP lieferte nur null statt eines echten Diagnose-Reports")
            case .failure(let error):
                finish(false, "tool4d-LSP-Integration fehlgeschlagen: \(error.localizedDescription)")
            }
        }
    }

    // MARK: - Selbsttest macro4dengine (tool4d-Engine, Idee #28)

    /// End-to-End-Beweis der tool4d-Engine: braucht ein echtes Engine-Projekt
    /// mit der Startup-Methode `MacroRun` (über `FASTRA_MACRO_ENGINE_PROJECT`)
    /// und ein installiertes tool4d. Ohne beides ist das ein Umgebungs-Skip,
    /// kein grüner Lauf.
    private static func runFourDMacroEngineTest() {
        testLabel = "macro4dengine"
        let env = ProcessInfo.processInfo.environment
        guard let engineRoot = env["FASTRA_MACRO_ENGINE_PROJECT"],
              !engineRoot.isEmpty else {
            finish(.environment, "Umgebungsproblem: FASTRA_MACRO_ENGINE_PROJECT ist nicht gesetzt (Wurzel des MacroRun-Engine-Projekts)")
        }
        guard let projectFile = FourDMacroEngine.engineProjectFile(
            root: URL(fileURLWithPath: engineRoot)) else {
            finish(.environment, "Umgebungsproblem: keine .4DProject-Datei unter \(engineRoot)")
        }
        guard let tool = Tool4DAssist.installedTool() else {
            finish(.environment, "Umgebungsproblem: kein installiertes tool4d gefunden")
        }
        // Untokenisierter, var-basierter Methodencode: genau die Form, die
        // die Engine nach dem Detokenisieren übergibt. Klassische
        // C_XXX-Deklarationen verträgt das Makro nicht.
        let code = "// Probemethode für den Engine-Selbsttest\n"
            + "var $text : Text\n"
            + "var $laenge : Integer\n"
            + "$text:=\"eins\"\n"
            + "$laenge:=Length($text)\n"
            + "ALERT($text+String($laenge))\n"
        FourDMacroEngine.run(
            tool4d: tool.executableURL,
            engineProjectRoot: URL(fileURLWithPath: engineRoot),
            engineProjectFile: projectFile,
            code: code,
            variant: FourDKomplettierenVariant.standard.rawValue,
            methodName: "FastraEngineProbe"
        ) { result in
            switch result {
            case .changed(let output):
                guard output.contains("FastraEngineProbe") else {
                    finish(false, "Engine lieferte Code ohne den erwarteten Methodenkopf: \(String(output.prefix(120)))")
                }
                finish(true, "tool4d-Engine lief durch; Makro ergänzte den Methodenkopf (Ausgabe \(output.count) Zeichen)")
            case .unchanged:
                finish(true, "tool4d-Engine lief durch; Makro meldete „Keine Änderungen“")
            case .failed(let text):
                finish(false, "Engine-Lauf fehlgeschlagen: \(text)")
            case .cancelledBeforeStart:
                finish(false, "Engine-Lauf wurde vor dem Start verworfen")
            }
        }
    }

    // MARK: - Selbsttest macro4d (4D-Makros, Idee #28)

    /// Beweist die Kette „Discovery → XML-Parse → Katalog → natives
    /// Text-Makro": Ein Fixture-Projekt bringt eine Komponente mit eigener
    /// „Macros v2"-XML mit; nach dem Öffnen der `.4dm` muss der Katalog das
    /// Makro kennen, der Kürzel-Aufruf fügt den gerenderten Text als einen
    /// Undo-Schritt ein und setzt den Cursor an die `<caret/>`-Marke.
    private static func runFourDMacroSelfTest() {
        testLabel = "macro4d"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-macro4d-\(UUID().uuidString)")
        let methods = base.appendingPathComponent("Project/Sources/Methods")
        let macrosDir = base
            .appendingPathComponent("Components/Fixture.4dbase/Macros v2")
        let document = methods.appendingPathComponent("Probe.4dm")
        let originalCode = "ALERT:C41(\"x\")\n"
        do {
            try fm.createDirectory(at: methods, withIntermediateDirectories: true)
            try fm.createDirectory(at: macrosDir, withIntermediateDirectories: true)
            try Data().write(to: base.appendingPathComponent("Project/Test.4DProject"))
            try originalCode.write(to: document, atomically: true, encoding: .utf8)
            let xml = """
            <?xml version="1.0" encoding="UTF-8"?>
            <macros>
              <macro name="Testkommentar /y" version="2">
                <text>// <method_name/> <caret/>fertig</text>
              </macro>
            </macros>
            """
            try xml.write(to: macrosDir.appendingPathComponent("fixture.xml"),
                          atomically: true, encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixtures nicht anlegbar: \(error.localizedDescription)")
        }
        ws.loadFile(at: document) { ok in
            guard ok else {
                try? fm.removeItem(at: base)
                finish(false, "Fixture-Methode wurde nicht geladen")
            }
            pollFourDMacroCatalog(ws, base: base)
        }
    }

    /// Wartet auf den asynchron gescannten Katalog und führt dann das Makro aus.
    private static func pollFourDMacroCatalog(_ ws: Workspace, base: URL) {
        // Zwei Stufen in einer Frist: erst der Katalog, dann der Editor.
        var stage = 0
        var found: (window: NSWindow, textView: TextView)?
        waitFor(budget: 6, pause: 0.05,
                condition: {
                    guard ws.fourDMacros.contains(where: { $0.shortcutKey == "y" }) else {
                        stage = 0
                        return false
                    }
                    stage = 1
                    guard let window = mainWindowForAXChecks(), let content = window.contentView,
                          let textView = editorTextView(in: content) as? TextView else { return false }
                    found = (window, textView)
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    if stage == 0 {
                        finish(false, "Makro-Katalog fand das Fixture-Makro nicht "
                            + "(Katalog: \(ws.fourDMacros.map(\.displayName))) — \(book.summary)")
                    }
                    finish(false, "Editor-TextView für das Makro nicht gefunden — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Editor nach Erfolg verschwunden") }
                    let (window, textView) = found
                    activateApplication(ignoringOtherApps: true)
                    window.makeKeyAndOrderFront(nil)
                    let originalCode = textView.string
                    // Selbsttests laufen auf der Main-Queue; die Zusicherung entspricht
                    // dem Muster der übrigen @MainActor-Aufrufe in dieser Datei.
                    let handled = MainActor.assumeIsolated {
                        ws.runFourDMacro(shortcut: "y")
                    }
                    guard handled else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Kürzel-Aufruf fand das Katalog-Makro nicht")
                    }
                    let expectedPrefix = "// Probe fertig"
                    let expectedCaret = ("// Probe " as NSString).length
                    guard textView.string.hasPrefix(expectedPrefix),
                          textView.string.hasSuffix(originalCode) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Makro-Einfügung falsch: \(String(textView.string.prefix(40)))")
                    }
                    guard textView.fastraSafeSelectedRange.location == expectedCaret else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Cursor steht nicht an der Caret-Marke "
                            + "(ist \(textView.fastraSafeSelectedRange.location), soll \(expectedCaret))")
                    }
                    textView.undoManager?.undo()
                    guard textView.string == originalCode else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Undo stellte den Ausgangstext nicht her")
                    }
                    try? FileManager.default.removeItem(at: base)
                    finish(true, "Fixture-Makro erschien im Katalog, Kürzel fügte den "
                        + "gerenderten Text als einen Undo-Schritt mit Caret-Position ein")
                })
    }

    // MARK: - Selbsttest tool4dhint

    /// Prüft den 4D-Erst-Kontakt-Hinweis im echten Fenster:
    /// (a) Erste `.4dm`-Datei → Hinweis-Leiste erscheint.
    /// (b) Echter Klick auf „Einrichtung anzeigen" → Hilfe-Fenster öffnet
    ///     (Anker „4D & tool4d"), Leiste verschwindet, Flag gesetzt.
    /// (c) Zweite `.4dm`-Datei → Hinweis erscheint nicht erneut
    ///     („einmal pro Nutzer"). Die Defaults sind die isolierte
    ///     Selbsttest-Suite — das echte Nutzer-Flag bleibt unberührt.
    private static func runTool4DHintTest() {
        testLabel = "tool4dhint"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        guard !Tool4DAssist.firstContactHintShown else {
            finish(false, "(setup) Flag ist in der frischen Selbsttest-Suite schon gesetzt")
        }
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-tool4dhint-\(UUID().uuidString)")
        let first = base.appendingPathComponent("Methode.4dm")
        let second = base.appendingPathComponent("Andere.4dm")
        do {
            try FileManager.default.createDirectory(at: base,
                                                    withIntermediateDirectories: true)
            try "$x:=1".write(to: first, atomically: true, encoding: .utf8)
            try "$y:=2".write(to: second, atomically: true, encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixtures nicht anlegbar: \(error.localizedDescription)")
        }
        ws.loadFile(at: first) { ok in
            guard ok else {
                try? FileManager.default.removeItem(at: base)
                finish(false, "(setup) Methode.4dm lädt nicht")
            }
            pollTool4DHintVisible(ws, base: base, second: second)
        }
    }

    private static func pollTool4DHintVisible(_ ws: Workspace, base: URL,
                                              second: URL) {
        var windowFound = false
        var found: (window: NSWindow, button: NSView)?
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard let window = mainWindowForAXChecks(), let content = window.contentView else {
                        windowFound = false
                        return false
                    }
                    windowFound = true
                    guard let button = markerView(id: "tool4dHintHelpButton", in: content),
                          markerViewExists(id: "tool4dHintBar", in: content) else { return false }
                    found = (window, button)
                    return true
                },
                onTimeout: { book in
                    guard windowFound else { finish(false, "kein Hauptfenster — \(book.summary)") }
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Hinweis-Leiste erscheint nicht für Methode.4dm — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Hinweis-Leiste nach Erfolg verschwunden") }
                    let (window, button) = found
                    // Echter Klick auf „Einrichtung anzeigen" (Down+Up durch die
                    // Event-Pipeline; der 0×0-Marker sitzt in der Button-Mitte).
                    let point = button.convert(NSPoint.zero, to: nil)
                    let time = ProcessInfo.processInfo.systemUptime
                    guard let down = NSEvent.mouseEvent(
                        with: .leftMouseDown, location: point, modifierFlags: [],
                        timestamp: time, windowNumber: window.windowNumber, context: nil,
                        eventNumber: 0, clickCount: 1, pressure: 1
                    ), let up = NSEvent.mouseEvent(
                        with: .leftMouseUp, location: point, modifierFlags: [],
                        timestamp: time + 0.05, windowNumber: window.windowNumber,
                        context: nil, eventNumber: 1, clickCount: 1, pressure: 0
                    ) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Maus-Events nicht baubar")
                    }
                    window.sendEvent(down)
                    window.sendEvent(up)
                    pollTool4DHelpOpened(ws, base: base, second: second)
                })
    }

    private static func pollTool4DHelpOpened(_ ws: Workspace, base: URL,
                                             second: URL) {
        var helpOpen = false
        var hintGone = false
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    helpOpen = NSApp.windows.contains {
                        $0.frameAutosaveName == "FastraHelpWindow" && $0.isVisible
                    }
                    hintGone = mainWindowForAXChecks()?.contentView.map {
                        !markerViewExists(id: "tool4dHintBar", in: $0)
                    } ?? false
                    return helpOpen && hintGone && Tool4DAssist.firstContactHintShown
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Nach Klick: Hilfe offen=\(helpOpen), Leiste weg=\(hintGone), "
                        + "Flag=\(Tool4DAssist.firstContactHintShown) — \(book.summary)")
                },
                then: {
                    // (c) Zweite 4D-Datei — der Hinweis darf nicht wiederkommen.
                    ws.loadFile(at: second) { ok in
                        guard ok else {
                            try? FileManager.default.removeItem(at: base)
                            finish(false, "(setup) Andere.4dm lädt nicht")
                        }
                        // Negativ-Beweis mit fester Frist: nach 1,5 s immer noch weg.
                        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                            let stillGone = mainWindowForAXChecks()?.contentView.map {
                                !markerViewExists(id: "tool4dHintBar", in: $0)
                            } ?? false
                            try? FileManager.default.removeItem(at: base)
                            finish(stillGone,
                                   stillGone
                                   ? "Hinweis erschien genau einmal; Klick öffnete die Hilfe "
                                     + "(Anker 4D & tool4d); zweite 4D-Datei ohne erneuten Hinweis"
                                   : "Hinweis erschien nach Quittierung erneut")
                        }
                    }
                })
    }

    // MARK: - Selbsttest gototarget

    /// Prüft Alt-Doppelklick „Gehe zum Ziel" mit echten synthetischen
    /// Mausereignissen (über die App-Event-Queue, damit der lokale Monitor
    /// sie sieht):
    /// (a) 4D: Klick auf einen Methodennamen öffnet die Projektmethode.
    /// (b) Markdown: Klick auf einen relativen Link öffnet die Zieldatei.
    private static func runGoToTargetTest() {
        testLabel = "gototarget"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-gototarget-\(UUID().uuidString)")
        let methods = base.appendingPathComponent("Project/Sources/Methods")
        let caller = methods.appendingPathComponent("Aufrufer.4dm")
        let target = methods.appendingPathComponent("ZielMethode.4dm")
        let markdown = base.appendingPathComponent("start.md")
        let markdownTarget = base.appendingPathComponent("ziel-datei.md")
        do {
            try fm.createDirectory(at: methods, withIntermediateDirectories: true)
            try "ZielMethode($x)\n".write(to: caller, atomically: true,
                                          encoding: .utf8)
            try "$y:=1\n".write(to: target, atomically: true, encoding: .utf8)
            try "Siehe [Ziel](ziel-datei.md) hier.\n".write(
                to: markdown, atomically: true, encoding: .utf8)
            try "# Ziel\n".write(to: markdownTarget, atomically: true,
                                 encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixtures nicht anlegbar: \(error.localizedDescription)")
        }
        ws.loadFile(at: caller) { ok in
            guard ok else {
                try? fm.removeItem(at: base)
                finish(false, "(setup) Aufrufer.4dm lädt nicht")
            }
            goToTargetClick(ws, base: base, needle: "ZielMethode",
                            expectedFile: "ZielMethode.4dm") {
                // (b) Markdown-Teil im Anschluss.
                ws.loadFile(at: markdown) { ok in
                    guard ok else {
                        try? fm.removeItem(at: base)
                        finish(false, "(setup) start.md lädt nicht")
                    }
                    goToTargetClick(ws, base: base, needle: "Ziel]",
                                    expectedFile: "ziel-datei.md") {
                        try? fm.removeItem(at: base)
                        finish(true, "Alt-Doppelklick öffnete real die 4D-Methode "
                            + "und das Markdown-Linkziel (echte Events über die Queue)")
                    }
                }
            }
        }
    }

    /// Wartet auf den Editor mit `needle` im Text, synthetisiert einen
    /// Alt-Doppelklick auf dessen erster Fundstelle und pollt, bis der
    /// aktive Tab `expectedFile` zeigt — dann `completion`.
    private static func goToTargetClick(_ ws: Workspace, base: URL,
                                        needle: String, expectedFile: String,
                                        completion: @escaping () -> Void) {
        var found: (window: NSWindow, textView: TextView, rect: CGRect)?
        let sourceTabID = ws.activeTabID
        var previousGeometry: (view: TextView, point: NSPoint, visible: NSRect)?
        var readiness = "noch keine Geometrie"
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    guard ws.activeTabID == sourceTabID,
                          let window = mainWindowForAXChecks(),
                          let content = window.contentView,
                          let textView = editorTextView(in: content) as? TextView,
                          textView.string.contains(needle) else { return false }
                    window.layoutIfNeeded()
                    let range = (textView.string as NSString).range(of: needle)
                    // Der TextStorage ist nach einem Dateiwechsel früher sichtbar als
                    // das asynchron erzeugte Zeilenlayout. Unter Last darf diese
                    // normale Zwischenlage nicht als kaputter Zielsprung gelten.
                    guard let rect = textView.layoutManager.rectsFor(range:
                        NSRange(location: range.location, length: 1)).first else { return false }
                    let textPoint = NSPoint(x: rect.midX, y: rect.midY)
                    let point = textView.convert(textPoint, to: nil)
                    let hit = content.hitTest(content.convert(point, from: nil))
                    var ancestor = hit
                    while let candidate = ancestor, !(candidate is TextView) {
                        ancestor = candidate.superview
                    }
                    let offset = textView.layoutManager.textOffsetAtPoint(textPoint)
                    readiness = "Hit=\(hit.map { String(describing: type(of: $0)) } ?? "nil"), "
                        + "Offset=\(offset.map(String.init) ?? "nil"), Punkt=\(point)"
                    guard ancestor === textView, textView.visibleRect.contains(textPoint),
                          let offset, NSLocationInRange(offset, range) else {
                        previousGeometry = nil
                        return false
                    }
                    // Die Queue stellt erst später zu. Beim Markdown-Wechsel
                    // müssen Toolbar und Vorschau ihre Fenstergeometrie behalten.
                    let stable = previousGeometry.map {
                        $0.view === textView && $0.visible == textView.visibleRect
                            && abs($0.point.x - point.x) < 0.5
                            && abs($0.point.y - point.y) < 0.5
                    } ?? false
                    previousGeometry = (textView, point, textView.visibleRect)
                    guard stable else { return false }
                    found = (window, textView, rect)
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Editor mit „\(needle)“ nicht anklickbar: \(readiness) — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Editor nach Erfolg verschwunden") }
                    let (window, textView, rect) = found
                    // Punkt in Fenster-Koordinaten; Events über die App-Queue posten,
                    // damit der lokale Monitor (GoToTargetGesture) sie wirklich sieht.
                    let windowPoint = textView.convert(NSPoint(x: rect.midX, y: rect.midY),
                                                       to: nil)
                    let time = ProcessInfo.processInfo.systemUptime
                    for (clickCount, type) in [(1, NSEvent.EventType.leftMouseDown),
                                               (1, .leftMouseUp),
                                               (2, .leftMouseDown),
                                               (2, .leftMouseUp)] {
                        guard let event = NSEvent.mouseEvent(
                            with: type, location: windowPoint, modifierFlags: [.option],
                            timestamp: time, windowNumber: window.windowNumber, context: nil,
                            eventNumber: 0, clickCount: clickCount, pressure: 1
                        ) else {
                            try? FileManager.default.removeItem(at: base)
                            finish(false, "Maus-Events nicht baubar")
                        }
                        NSApp.postEvent(event, atStart: false)
                    }
                    pollGoToTargetResult(ws, base: base, expectedFile: expectedFile, completion: completion)
                })
    }

    private static func pollGoToTargetResult(_ ws: Workspace, base: URL,
                                             expectedFile: String,
                                             completion: @escaping () -> Void) {
        waitFor(budget: 10, pause: 0.25,
                condition: { ws.activeTab?.url?.lastPathComponent == expectedFile },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Sprung nach „\(expectedFile)“ blieb aus "
                        + "(aktiver Tab: \(ws.activeTab?.title ?? "?")) — \(book.summary)")
                },
                then: completion)
    }

    // MARK: - Selbsttest gototargetwin

    /// Alt-Doppelklick „Gehe zum Ziel" bei zwei offenen Fenstern: Die Geste
    /// muss im Fenster des Klicks wirken — auch wenn `Workspace.shared`
    /// gerade auf das andere Fenster zeigt.
    ///
    /// Der Fehler dahinter: `GoToTargetGesture` holte Workspace und Tab aus
    /// dem globalen `Workspace.shared`, die geklickte TextView aber aus dem
    /// Event-Fenster. Bei zwei Fenstern verband das zwei verschiedene
    /// Dokumente — der Methodensprung landete im falschen Fenster (dieselbe
    /// Fehlerklasse wie die mit v1.64.0 behobenen Menübefehle).
    ///
    /// `Workspace.shared` zeigt im echten Betrieb regelmäßig nicht auf das
    /// geklickte Fenster: Der lokale Maus-Monitor sieht den Doppelklick,
    /// bevor das hintere Fenster durch den Klick Key wird (erst danach
    /// aktualisiert die Aktivierungsbrücke `shared`), und nach einer
    /// Sitzungswiederherstellung zeigt `shared` auf den zuletzt erzeugten
    /// Workspace. Der Test stellt diese Lage deshalb gezielt her.
    private static func runGoToTargetTwoWindowTest() {
        testLabel = "gototargetwin"
        guard let firstWorkspace = Workspace.shared,
              let firstWindow = NSApp.windows.first(where: {
                  !SearchWindow.isSearchWindow($0)
                      && WorkspaceWindowRegistry.workspace(for: $0) === firstWorkspace
                      && $0.isVisible
              }) else {
            finish(false, "kein erstes Dokumentfenster mit Workspace-Zuordnung")
        }
        // Zwei getrennte 4D-Projekte mit gleichnamiger Methode: Nur so ist
        // sichtbar, wessen Methode der Sprung öffnet.
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-gototargetwin-\(UUID().uuidString)")
        let frontMethods = base.appendingPathComponent("vorn/Project/Sources/Methods")
        let backMethods = base.appendingPathComponent("hinten/Project/Sources/Methods")
        let frontCaller = frontMethods.appendingPathComponent("Haupt.4dm")
        let frontTarget = frontMethods.appendingPathComponent("ZielMethode.4dm")
        let backCaller = backMethods.appendingPathComponent("Aufrufer.4dm")
        let backTarget = backMethods.appendingPathComponent("ZielMethode.4dm")
        do {
            try fm.createDirectory(at: frontMethods, withIntermediateDirectories: true)
            try fm.createDirectory(at: backMethods, withIntermediateDirectories: true)
            try "ZielMethode($vorn)\n".write(to: frontCaller, atomically: true,
                                             encoding: .utf8)
            try "// Methode vorn\n".write(to: frontTarget, atomically: true,
                                          encoding: .utf8)
            try "ZielMethode($hinten)\n".write(to: backCaller, atomically: true,
                                               encoding: .utf8)
            try "// Methode hinten\n".write(to: backTarget, atomically: true,
                                            encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixtures nicht anlegbar: \(error.localizedDescription)")
        }
        let secondWorkspace = MainActor.assumeIsolated {
            DocumentWindowController.openNewDocument(defaults: workspaceDefaults())
        }
        guard let secondWindow = NSApp.windows.first(where: {
            !SearchWindow.isSearchWindow($0)
                && WorkspaceWindowRegistry.workspace(for: $0) === secondWorkspace
                && $0.isVisible
        }) else {
            try? fm.removeItem(at: base)
            finish(false, "kein zweites Dokumentfenster mit Workspace-Zuordnung")
        }
        firstWorkspace.loadFile(at: frontCaller) { ok in
            guard ok else {
                try? fm.removeItem(at: base)
                finish(false, "(setup) Haupt.4dm lädt nicht")
            }
            secondWorkspace.loadFile(at: backCaller) { ok in
                guard ok else {
                    try? fm.removeItem(at: base)
                    finish(false, "(setup) Aufrufer.4dm lädt nicht")
                }
                // Teil 1: Klick ins hintere Fenster, während das vordere die
                // Tastatur hat und `Workspace.shared` auf das vordere zeigt.
                firstWindow.makeKeyAndOrderFront(nil)
                goToTargetTwoWindowClick(
                    clicked: (secondWorkspace, secondWindow),
                    other: (firstWorkspace, firstWindow),
                    needle: "ZielMethode($hinten)",
                    sharedPointsTo: firstWorkspace,
                    expectedTarget: backTarget,
                    otherStaysAt: frontCaller,
                    cleanup: base,
                    label: "hinteres Fenster"
                ) {
                    // Teil 2: Klick ins vordere Fenster, während `shared` —
                    // wie nach einer Sitzungswiederherstellung — auf das
                    // hintere zeigt.
                    goToTargetTwoWindowClick(
                        clicked: (firstWorkspace, firstWindow),
                        other: (secondWorkspace, secondWindow),
                        needle: "ZielMethode($vorn)",
                        sharedPointsTo: secondWorkspace,
                        expectedTarget: frontTarget,
                        otherStaysAt: backTarget,
                        cleanup: base,
                        label: "vorderes Fenster"
                    ) {
                        try? fm.removeItem(at: base)
                        finish(true, "Alt-Doppelklick öffnete in beiden Fenstern "
                            + "die Methode des JEWEILS geklickten Projekts; das "
                            + "andere Fenster blieb unberührt")
                    }
                }
            }
        }
    }

    /// Synthetisiert einen Alt-Doppelklick auf `needle` im Fenster `clicked`
    /// und prüft anschließend beide Fenster: Das geklickte muss
    /// `expectedTarget` öffnen, das andere bei `otherStaysAt` bleiben.
    /// `sharedPointsTo` stellt vor dem Klick den globalen Zustand her, der
    /// den Fehler auslöste: `Workspace.shared` zeigt auf das andere Fenster.
    private static func goToTargetTwoWindowClick(
        clicked: (workspace: Workspace, window: NSWindow),
        other: (workspace: Workspace, window: NSWindow),
        needle: String,
        sharedPointsTo: Workspace,
        expectedTarget: URL,
        otherStaysAt: URL,
        cleanup base: URL,
        label: String,
        completion: @escaping () -> Void
    ) {
        waitForEditorShowing(
            window: clicked.window, text: needle,
            onTimeout: {
                try? FileManager.default.removeItem(at: base)
                finish(false, "(\(label)) Editor zeigt „\(needle)“ nicht binnen 5 s")
            }
        ) { _, textView, range in
            // Das Klickfenster zunächst vorholen, damit AppKit und SwiftUI seine
            // endgültige Geometrie auslegen. Danach den Fensterstapel wiederherstellen
            // und erst messen/klicken: Eine zuvor nie sichtbare TextView kann noch
            // Koordinaten innerhalb der Seitenleiste melden. Der geprüfte Klick ins
            // hintere Fenster bleibt dadurch erhalten.
            clicked.window.makeKeyAndOrderFront(nil)
            clicked.window.layoutIfNeeded()
            clicked.window.displayIfNeeded()
            _ = textView.layoutManager.layoutLines(in: textView.bounds)
            guard let rect = textView.layoutManager.rectsFor(range:
                NSRange(location: range.location, length: 1)).first else {
                try? FileManager.default.removeItem(at: base)
                finish(false, "(\(label)) keine Layout-Position für „\(needle)“")
            }
            // Punkt in Fenster-Koordinaten; Events über die App-Queue posten,
            // damit der lokale Monitor (GoToTargetGesture) sie wirklich sieht.
            let windowPoint = textView.convert(NSPoint(x: rect.midX, y: rect.midY),
                                               to: nil)
            // Und der Beweis, dass der Punkt wirklich im Text landet: Der
            // Produktpfad sucht die Textansicht per `hitTest`. Trifft der
            // Punkt sie nicht, ist die Messung falsch — dann soll der Test das
            // sagen, statt zehn Sekunden auf einen Sprung zu warten, den
            // niemand ausgelöst hat.
            guard let contentView = clicked.window.contentView else {
                try? FileManager.default.removeItem(at: base)
                finish(false, "(\(label)) Fensterinhalt fehlt")
            }
            let contentPoint = contentView.convert(windowPoint, from: nil)
            var hitsTextView = false
            var probe: NSView? = contentView.hitTest(contentPoint)
            while let view = probe {
                if view === textView { hitsTextView = true; break }
                probe = view.superview
            }
            guard hitsTextView else {
                try? FileManager.default.removeItem(at: base)
                finish(false, "(\(label)) Klickpunkt \(contentPoint) trifft nicht "
                    + "die Textansicht, sondern "
                    + "\(contentView.hitTest(contentPoint).map { String(describing: type(of: $0)) } ?? "nichts")"
                    + " — die gemessene Geometrie gehört nicht zum sichtbaren Fenster")
            }
            // Erst jetzt den Stapel und `Workspace.shared` in die Prüflage
            // bringen: Der Klick geht ins hintere Fenster, während das andere
            // die Tastatur hat.
            other.window.makeKeyAndOrderFront(nil)
            Workspace.shared = sharedPointsTo
            let time = ProcessInfo.processInfo.systemUptime
            for (clickCount, type) in [(1, NSEvent.EventType.leftMouseDown),
                                       (1, .leftMouseUp),
                                       (2, .leftMouseDown),
                                       (2, .leftMouseUp)] {
                guard let event = NSEvent.mouseEvent(
                    with: type, location: windowPoint, modifierFlags: [.option],
                    timestamp: time, windowNumber: clicked.window.windowNumber,
                    context: nil, eventNumber: 0, clickCount: clickCount,
                    pressure: 1
                ) else {
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "(\(label)) Maus-Events nicht baubar")
                }
                NSApp.postEvent(event, atStart: false)
            }
            pollGoToTargetTwoWindowResult(
                clicked: clicked.workspace, other: other.workspace,
                expectedTarget: expectedTarget, otherStaysAt: otherStaysAt,
                cleanup: base, label: label, completion: completion
            )
        }
    }

    private static func pollGoToTargetTwoWindowResult(
        clicked: Workspace, other: Workspace,
        expectedTarget: URL, otherStaysAt: URL,
        cleanup base: URL, label: String,
        completion: @escaping () -> Void
    ) {
        // Symlink-aufgelöst vergleichen: Die Fixtures liegen unter
        // `/var/folders/…`, der geladene Tab meldet `/private/var/…` —
        // dieselbe Falle wie bei `FileLoader` (siehe AGENTS.md).
        func resolved(_ url: URL?) -> String? {
            url?.resolvingSymlinksInPath().path
        }
        var clickedPath: String?
        var otherPath: String?
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    clickedPath = resolved(clicked.activeTab?.url)
                    otherPath = resolved(other.activeTab?.url)
                    return clickedPath == resolved(expectedTarget)
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    // Für die Diagnose zeigen, wo die Datei stattdessen landete —
                    // beim ursprünglichen Fehler öffnete das andere Fenster seine
                    // gleichnamige Methode.
                    finish(false, "(\(label)) Sprung blieb im geklickten Fenster aus "
                        + "(dort aktiv: \(clickedPath ?? "kein Pfad"), "
                        + "anderes Fenster: \(otherPath ?? "kein Pfad")) — \(book.summary)")
                },
                then: {
                    // Der Sprung kam im richtigen Fenster an — das andere darf sich
                    // dabei nicht bewegt haben.
                    guard otherPath == resolved(otherStaysAt) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "(\(label)) Sprung veränderte auch das andere "
                            + "Fenster: aktiver Tab dort \(otherPath ?? "kein Pfad")")
                    }
                    completion()
                })
    }

    // MARK: - Selbsttest filediff

    /// Liefert die Marker-NSView selbst (nicht nur ihre Existenz) — für
    /// Positionsermittlung beim synthetischen Klick.
    private static func markerView(id: String, in view: NSView) -> NSView? {
        if view.accessibilityIdentifier() == id { return view }
        for sub in view.subviews {
            if let found = markerView(id: id, in: sub) { return found }
        }
        return nil
    }

    /// Der separate CLI-Runner startet diese App ausschließlich durch den
    /// gebündelten Helfer. So belegt der Test den echten LaunchServices-Kaltstart.
    @MainActor
    private static func pollExternalDiffCold() {
        testLabel = "externaldiffcold"
        sessionRestorationTests.pollExternalDiffCold()
    }

    /// Echte Helferprozesse und Mach-Nachrichten, danach gerenderte Fenster
    /// und unveränderte Quelldateien prüfen. Der Runner isoliert Preferences.
    @MainActor
    private static func runExternalDiffTest() {
        testLabel = "externaldiff"
        let root = selfTestTemporaryDirectory().appendingPathComponent("external-diff-\(UUID())")
        let left = root.appendingPathComponent("-ä links.txt")
        let right = root.appendingPathComponent("右 rechts.txt")
        let before = Data("eins\nalt\ndrei\n".utf8)
        let after = Data("eins\nneu\ndrei\n".utf8)
        do {
            try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
            try before.write(to: left)
            try after.write(to: right)
        } catch { finish(.environment, "Fixture-Dateien nicht anlegbar") }
        let defaults = workspaceDefaults()
        let sidebarBefore = defaults.object(forKey: "editor.sidebarVisible") as? Bool
        let normalWindows = DocumentWindowController.visibleDocumentWindows()
        let normalFrames = normalWindows.map(\.frame)
        let helper = Bundle.main.bundleURL.appendingPathComponent("Contents/Helpers/fastra-diff")
        let endpoint = DiffProtocol.endpoint(bundleIdentifier: Bundle.main.bundleIdentifier!)
        runExternalDiffHelper(helper, arguments: [
            "--read-only", "--left-label", "Links α", "--right-label", "Rechts β",
            "--", left.path, right.path
        ], in: root) { helperErrors in
            var errors = helperErrors
            let invocation = try! DiffInvocation.parse(["--read-only", "--focus-diff", "--", left.path, right.path], directory: root)!
            let requests = (0..<3).map { _ in DiffWireRequest(invocation) }
            // Jeder Auftrag kommt dreimal, auch gleichzeitig. Der Server muss
            // daraus genau drei weitere Fenster machen, niemals neun.
            let lock = NSLock()
            DispatchQueue.concurrentPerform(iterations: 9) { index in
                let data = try! JSONEncoder().encode(requests[index % 3])
                var reply: DiffWireReply?
                let deadline = Date().addingTimeInterval(5)
                repeat {
                    reply = DiffMessageClient.send(data, to: endpoint, timeout: 0.25)
                } while reply == nil && Date() < deadline
                if reply?.code != 0 { lock.withLock { errors.append("Gleichzeitiger Auftrag nicht bestätigt") } }
            }
            // Gleiche ID mit verändertem Inhalt sowie abgelaufene und fremde
            // Protokolle dürfen keine weiteren Fenster erzeugen.
            var changed = requests[0]
            changed.leftLabel = "anderer Inhalt"
            var expired = DiffWireRequest(invocation)
            expired.deadline = 0
            var unsupported = DiffWireRequest(invocation)
            unsupported.version = 2
            for (request, expected): (DiffWireRequest, Int32) in [(changed, 6), (expired, 6), (unsupported, 4)] {
                let reply = DiffMessageClient.send(try! JSONEncoder().encode(request), to: endpoint, timeout: 1)
                if reply?.code != expected { errors.append("Ablehnung hat falschen Exit-Code") }
            }
            let failures = errors
            DispatchQueue.main.async {
                pollExternalDiff(root: root, left: left, right: right, before: before, after: after,
                                 sidebarBefore: sidebarBefore, normalWindows: normalWindows,
                                 normalFrames: normalFrames, errors: failures)
            }
        }
    }

    /// Nutzt denselben begrenzten Prozessweg wie andere externe Werkzeuge.
    /// Die Completion läuft im Hintergrund, da danach Mach-Nachrichten folgen.
    @discardableResult
    static func runExternalDiffHelper(_ executable: URL, arguments: [String],
                                      in directory: URL,
                                      completion: @escaping ([String]) -> Void)
        -> GitCancellationToken {
        GitRunner.runExecutable(
            executable, arguments: arguments, in: directory,
            outputLimit: GitOutputLimit(stdoutBytes: 64 * 1024, stderrBytes: 64 * 1024),
            policy: GitExecutionPolicy(timeout: 13, terminationGracePeriod: 0.5),
            completionQueue: .global(qos: .userInitiated)
        ) { outcome in
            switch outcome {
            case .completed(let result):
                let silentSuccess = result.ok && result.stdoutData.isEmpty
                    && result.stderrData.isEmpty && !result.stdoutWasTruncated
                    && !result.stderrWasTruncated
                completion(silentSuccess ? [] : ["Helfer bestätigt nicht still mit Exit 0"])
            case .timedOut:
                completion(["Helfer überschreitet seine Frist"])
            case .startFailed:
                completion(["Helfer konnte nicht ausgeführt werden"])
            case .cancelled:
                completion(["Helfer wurde abgebrochen"])
            case .captureFailed:
                completion(["Helferausgabe konnte nicht vollständig gelesen werden"])
            }
        }
    }

    @MainActor
    private static func pollExternalDiff(root: URL, left: URL, right: URL, before: Data, after: Data,
                                         sidebarBefore: Bool?, normalWindows: [NSWindow],
                                         normalFrames: [NSRect], errors: [String]) {
        var windows = ExternalDiffWindow.openWindows
        var ready = false
        // Ausgewertet wird in beiden Ausgängen; `ready` trägt das Ergebnis.
        func evaluate() {
            var failures = errors
            if !ready { failures.append("Erwartet: vier echte Fenster mit je einem gerenderten Unterschied; vorhanden: \(windows.count)") }
            if !windows.contains(where: { $0.model.request.left.name == "Links α" && $0.model.request.right.name == "Rechts β" }) {
                failures.append("Labels fehlen")
            }
            for controller in windows {
                controller.window.makeKeyAndOrderFront(nil)
                if CommandTargeting.targetWorkspace() != nil || CommandTargeting.targetEditorTextView() != nil {
                    failures.append("Externes Fenster besitzt ein schreibbares Dokumentziel")
                    continue
                }
                // Dieselben globalen Menübefehle wie beim Nutzer: Speichern darf
                // keinen fremden Workspace erreichen; der native Responder ebenfalls nicht.
                CommandTargeting.targetWorkspace()?.saveActiveTab()
                _ = NSApp.sendAction(Selector(("saveDocument:")), to: nil, from: nil)
            }
            if (try? Data(contentsOf: left)) != before || (try? Data(contentsOf: right)) != after {
                failures.append("Quelldateien verändert")
            }
            if workspaceDefaults().object(forKey: "editor.sidebarVisible") as? Bool != sidebarBefore {
                failures.append("Globale Seitenleisteneinstellung verändert")
            }
            if normalWindows.map(\.frame) != normalFrames || normalWindows.contains(where: { !$0.isVisible }) {
                failures.append("Normale Fenster verändert")
            }
            for controller in windows { controller.window.close() }
            try? FileManager.default.removeItem(at: root)
            finish(failures.isEmpty, failures.isEmpty
                   ? "Helfer still bestätigt; 3×3 IPC-Aufträge erzeugen drei Fenster; vier Diffs gerendert; Labels, Schreibschutz, globale Seitenleiste und andere Fenster geprüft"
                   : failures.joined(separator: "; "))
        }
        waitFor(budget: 8, pause: 0.1,
                condition: {
                    windows = ExternalDiffWindow.openWindows
                    ready = windows.count == 4 && windows.allSatisfy { controller in
                        controller.model.document?.result?.blocks.count == 1
                            && controller.window.contentView.map { markerViewExists(id: "diffState-b1-c0", in: $0) } == true
                    }
                    return ready || !errors.isEmpty
                },
                onTimeout: { _ in evaluate() },
                then: { evaluate() })
    }

    /// Prüft echte Blockbefehle, die genaue Bestätigung und natives Undo/Redo
    /// einschließlich aktueller Diffs beim Zurückwechseln.
    @MainActor
    private static func nativeUIWait(_ detail: String, _ condition: @MainActor () -> Bool) async throws {
        var budget = SelfTestPollBudget(budget: 10, pause: 0.03, hardCap: 18,
            now: ProcessInfo.processInfo.systemUptime)
        while !condition() {
            guard budget.recordMiss(now: ProcessInfo.processInfo.systemUptime) == .keepWaiting else {
                throw NSError(domain: "NativeUISelfTest", code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "Nicht bereit: " + detail])
            }
            try await Task.sleep(for: .milliseconds(30))
        }
    }

    @MainActor
    private static func stableMarkerClick(_ id: String, in target: NSWindow, stage: String,
                                          repetitions: Int = 1) async throws {
        target.makeKeyAndOrderFront(nil)
        var previous: (marker: NSView, point: NSPoint, window: NSRect)?
        var stableTicks = 0
        var found: NSPoint?
        try await nativeUIWait(stage + " / Stabile Klickposition: " + id) {
            target.layoutIfNeeded()
            guard let root = target.contentView, let marker = markerView(id: id, in: root),
                  marker.window === target, !marker.isHiddenOrHasHiddenAncestor else {
                previous = nil; stableTicks = 0; return false
            }
            let point = marker.convert(NSPoint(x: marker.bounds.midX, y: marker.bounds.midY), to: nil)
            guard root.visibleRect.contains(root.convert(point, from: nil)) else {
                previous = nil; stableTicks = 0; return false
            }
            // Gepostete Events kommen später an. Eine ein-/ausfahrende
            // Seitenleiste darf den Knopf bis dahin nicht verschieben.
            let stable = previous.map {
                $0.marker === marker && $0.window == target.frame
                    && abs($0.point.x - point.x) < 0.5 && abs($0.point.y - point.y) < 0.5
            } ?? false
            stableTicks = stable ? stableTicks + 1 : 0
            previous = (marker, point, target.frame)
            guard stableTicks >= 3 else { return false }
            found = point
            let hit = root.hitTest(root.convert(point, from: nil))
            FileHandle.standardError.write(Data(("NATIVE_UI_CLICK stage=\(stage) id=\(id) point=\(point) hit=\(hit.map { String(describing: type(of: $0)) } ?? "nil")\n").utf8))
            return true
        }
        guard let found else { throw NSError(domain: "NativeUISelfTest", code: 2) }
        for _ in 0..<repetitions {
            guard sendMouseClick(at: found, in: target, modifiers: [], viaApp: true) else {
                throw NSError(domain: "NativeUISelfTest", code: 3,
                    userInfo: [NSLocalizedDescriptionKey: "Klick fehlgeschlagen: " + id])
            }
        }
    }

    private static func runMarkdownReferencesTest() {
        testLabel = "mdreferences"
        Task { @MainActor in
            guard let workspace = Workspace.shared,
                  let window = CommandTargeting.registeredWindow(for: workspace) else { finish(false, "Dokumentfenster fehlt") }
            let base = selfTestTemporaryDirectory().appendingPathComponent("fastra-references-native-\(UUID().uuidString)")
            let appearance = NSApp.appearance
            let gate = DispatchSemaphore(value: 0)
            let controller = workspace.markdownReferences
            var stage = "Fixture"
            @MainActor func cleanup() {
                gate.signal(); controller.close(); NSApp.appearance = appearance
                try? FileManager.default.removeItem(at: base)
            }
            func require(_ ok: Bool, _ message: String) throws {
                if !ok { throw NSError(domain: "MarkdownReferencesSelfTest", code: 1, userInfo: [NSLocalizedDescriptionKey: message]) }
            }
            func value<T>(_ input: T?, _ message: String) throws -> T {
                guard let input else { throw NSError(domain: "MarkdownReferencesSelfTest", code: 2, userInfo: [NSLocalizedDescriptionKey: message]) }
                return input
            }
            @MainActor func wait(_ detail: String, _ condition: @MainActor () -> Bool) async throws {
                try await nativeUIWait(stage + " / " + detail, condition)
            }
            @MainActor func click(_ marker: String, in target: NSWindow) async throws {
                try await stableMarkerClick(marker, in: target, stage: stage)
            }
            @MainActor func matrix(_ name: String, in target: NSWindow, minimum: CGFloat = 640) async throws {
                guard let output = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] else { return }
                for (mode, appearance) in [("light", NSAppearance.Name.aqua), ("dark", .darkAqua)] {
                    NSApp.appearance = NSAppearance(named: appearance)
                    for width in [minimum, 1100] {
                        target.setContentSize(NSSize(width: width, height: 720))
                        try await Task.sleep(for: .milliseconds(350))
                        try require(abs((target.contentView?.bounds.width ?? 0) - width) < 1, "Breite stimmt nicht")
                        let snapshot: TypeScrollSnapshot? = await withCheckedContinuation { continuation in
                            typeScrollCapture(window: target) { continuation.resume(returning: $0) }
                        }
                        guard let snapshot, snapshot.source == "screen" else { cleanup(); finish(.environment, "Echte Fensteraufnahme fehlt: " + name) }
                        let url = URL(fileURLWithPath: output).appendingPathComponent(name + "-" + mode + "-\(Int(width)).png")
                        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                        try snapshot.data.write(to: url)
                    }
                }
            }
            do {
                try FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
                let source = "# Gleich\r\n\r\n## Gleich\r\n\r\n[Mehrdeutig](#gleich)\r\n[Fehlt](missing.md)\r\n![Bild](bild%231.png)\r\n[Ziel][ref]\r\n[Netz](https://example.invalid)\r\n\r\n[ref]: target.md#titel\r\n"
                let expectedOffset = "# Gleich\r\n\r\n## Gleich\r\n\r\n[Mehrdeutig](#gleich)\r\n".utf16.count
                let sourceURL = base.appendingPathComponent("doc.md")
                try Data(source.utf8).write(to: sourceURL)
                try Data("# Titel\n".utf8).write(to: base.appendingPathComponent("target.md"))
                try Data([0, 255, 1]).write(to: base.appendingPathComponent("bild#1.png"))
                var tab = EditorTab(title: "doc.md", path: sourceURL.path, url: sourceURL, content: source, isDirty: true)
                tab.markdownVisualOverride = false
                workspace.tabs = [tab]; workspace.activeTabID = tab.id
                workspace.projectURL = base
                NSApp.activate(ignoringOtherApps: true); window.makeKeyAndOrderFront(nil)
                stage = "Markdown-Menü"
                try await wait("Aktives Dokument") { NSApp.isActive && window.isKeyWindow && workspace.activeTabIsMarkdown }
                guard let main = NSApp.mainMenu, let root = main.items.first(where: { $0.title == "Markdown" }), let menu = root.submenu else { throw NSError(domain: "MarkdownReferenceMenu", code: 1) }
                let menuError: String? = await withCheckedContinuation { continuation in
                    var tracking = false, ticks = 0
                    let observer = NotificationCenter.default.addObserver(forName: NSMenu.didBeginTrackingNotification, object: main, queue: .main) { _ in tracking = true }
                    var timer: Timer?
                    timer = Timer(timeInterval: 0.05, repeats: true) { _ in
                        ticks += 1
                        if tracking, let item = menu.items.first(where: { $0.title == L10n.string("Lokale Verweise prüfen…") }), item.isEnabled {
                            timer?.invalidate(); timer = nil; NotificationCenter.default.removeObserver(observer)
                            menu.performActionForItem(at: menu.index(of: item)); menu.cancelTracking(); main.cancelTracking()
                            continuation.resume(returning: nil)
                        } else if ticks >= 100 {
                            timer?.invalidate(); timer = nil; NotificationCenter.default.removeObserver(observer)
                            menu.cancelTracking(); main.cancelTracking(); continuation.resume(returning: "Menüeintrag fehlt oder bleibt deaktiviert")
                        }
                    }
                    if let timer { RunLoop.main.add(timer, forMode: .common); RunLoop.main.add(timer, forMode: .eventTracking) }
                    DispatchQueue.main.async { _ = root.accessibilityPerformPress() }
                }
                try require(menuError == nil, menuError ?? "")
                try await wait("Leeres Sheet") { window.attachedSheet?.contentView.flatMap { markerView(id: "referenceStart", in: $0) } != nil }
                let sheet = try value(window.attachedSheet, "Sheet fehlt")
                try await matrix("reference-empty", in: sheet)
                stage = "Befundliste"
                try await click("referenceStart", in: sheet)
                try await wait("Prüfung vollständig") { controller.report?.isComplete == true && !controller.running }
                let report = try value(controller.report, "Bericht fehlt")
                try require(report.findings.map(\.status) == [.ambiguous, .missing, .valid, .valid] && report.remoteCount == 1, "Lokale Ergebnisse falsch")
                try await matrix("reference-problems", in: sheet)
                @MainActor func toggleProblems() async throws {
                    var point: NSPoint?
                    var previous: NSPoint?
                    var stable = 0
                    try await wait("Checkbox-Geometrie") {
                        sheet.layoutIfNeeded()
                        guard let root = sheet.contentView,
                              let marker = markerView(id: "referenceProblemsOnly", in: root),
                              marker.bounds.width > 20, marker.bounds.height > 10 else { return false }
                        // Das Kästchen liegt am linken Rand der gemessenen Toggle-Zeile;
                        // deren Mitte kann weit rechts im leeren Hintergrund liegen.
                        let next = marker.convert(NSPoint(x: marker.bounds.minX + marker.bounds.height / 2,
                                                          y: marker.bounds.midY), to: nil)
                        stable = previous == next ? stable + 1 : 0
                        previous = next; point = next
                        return stable >= 3
                    }
                    try require(sendMouseClick(at: try value(point, "Filterposition fehlt"), in: sheet,
                                               modifiers: [], viaApp: true), "Filterklick fehlt")
                }
                stage = "Problemfilter ausschalten"
                try await toggleProblems()
                try await wait("Alle vier Befunde sichtbar") {
                    guard let root = sheet.contentView else { return false }
                    return markerViewExists(id: "referenceFilterOff", in: root)
                        && markerViewExists(id: "referenceFinding-7", in: root)
                        && markerViewExists(id: "referenceFinding-8", in: root)
                }
                try await matrix("reference-results", in: sheet)
                stage = "Problemfilter einschalten"
                try await toggleProblems()
                try await wait("Nur zwei Probleme sichtbar") {
                    guard let root = sheet.contentView else { return false }
                    return markerViewExists(id: "referenceFilterOn", in: root)
                        && !markerViewExists(id: "referenceFinding-7", in: root)
                        && !markerViewExists(id: "referenceFinding-8", in: root)
                }
                stage = "Projektbereich"
                func segmentedControl(in view: NSView) -> NSSegmentedControl? {
                    if let control = view as? NSSegmentedControl, control.segmentCount == 2 { return control }
                    return view.subviews.lazy.compactMap { segmentedControl(in: $0) }.first
                }
                let control = try value(sheet.contentView.flatMap { segmentedControl(in: $0) }, "Bereichsauswahl fehlt")
                let point = control.convert(NSPoint(x: control.bounds.width * 0.75, y: control.bounds.midY), to: nil)
                try require(sendMouseClick(at: point, in: sheet, modifiers: [], viaApp: true), "Projektbereich nicht bedienbar")
                try await wait("Projekt ausgewählt") { sheet.contentView.flatMap { markerView(id: "referenceScopeProject", in: $0) } != nil }
                try require(controller.report == nil && !controller.running, "Alter Bericht überlebt Bereichswechsel")
                try await click("referenceStart", in: sheet)
                try await wait("Projekt vollständig geprüft") { controller.report?.sources.count == 2 && controller.report?.isComplete == true && !controller.running }
                try await matrix("reference-project", in: sheet)
                stage = "Nativer Quellsprung"
                try await click("referenceFinding-6", in: sheet)
                try await wait("Sprung freigegeben") { sheet.contentView.flatMap { markerView(id: "referenceJumpReady", in: $0) } != nil }
                try await click("referenceJumpReady", in: sheet)
                try await wait("Geprüfte Quellposition") {
                    window.attachedSheet == nil && workspace.activeTab?.documentID == tab.documentID
                        && CommandTargeting.editorTextView(for: workspace)?.fastraSafeSelectedRange.location == expectedOffset
                }
                try await matrix("reference-source", in: window, minimum: MainWindowSizing.minimumWidth)
                stage = "Prüfung aus WYSIWYG"
                try await click("markdownEditingModeButton", in: window)
                try await wait("Visueller Editor bereit") { workspace.activeMarkdownIsVisual && workspace.visualMarkdownEditor?.ready == true }
                controller.present(in: workspace)
                try await wait("Synchronisiertes Sheet") { window.attachedSheet != nil }
                let visualSheet = try value(window.attachedSheet, "Visuelles Prüfsheet fehlt")
                try await click("referenceStart", in: visualSheet)
                try await wait("Visuelle Quelle geprüft") { controller.report?.findings.count == 4 && !controller.running }
                try require(workspace.activeTab?.content.utf8.elementsEqual(source.utf8) == true, "Visuelle Prüfung änderte Quelle")
                try await matrix("reference-from-visual", in: visualSheet)
                try await click("referenceFinding-6", in: visualSheet)
                try await click("referenceJumpReady", in: visualSheet)
                try await wait("Visueller Quellsprung") {
                    window.attachedSheet == nil && !workspace.activeMarkdownIsVisual
                        && CommandTargeting.editorTextView(for: workspace)?.fastraSafeSelectedRange.location == expectedOffset
                }
                stage = "Veraltete Quelle"
                controller.present(in: workspace)
                try await wait("Sheet erneut geöffnet") { window.attachedSheet != nil }
                let staleSheet = try value(window.attachedSheet, "Sheet fehlt")
                try await click("referenceStart", in: staleSheet)
                try await wait("Erneut geprüft") { controller.report != nil && !controller.running }
                workspace.tabs[0].content = source + "\r\nGeändert\r\n"
                try await wait("Veralteter Bericht erkannt") { controller.hasChanged(in: workspace) }
                try await matrix("reference-stale", in: staleSheet)
                try await click("referenceFinding-6", in: staleSheet)
                try await click("referenceJumpReady", in: staleSheet)
                try await wait("Sprung abgewiesen") { controller.notice != nil && window.attachedSheet != nil }
                stage = "Abbruch während Renderqueue belegt"
                MarkdownRichText.renderQueue.async { _ = gate.wait(timeout: .now() + 10) }
                try await click("referenceStart", in: staleSheet)
                try await wait("Prüfung läuft") { controller.running && controller.progress != nil }
                try await click("referenceCancel", in: staleSheet)
                gate.signal()
                try await wait("Abbruch sichtbar") { controller.cancelled && !controller.running }
                try await matrix("reference-cancelled", in: staleSheet)
                try require(try Data(contentsOf: sourceURL) == Data(source.utf8), "Quelldatei geschrieben")
                try require(workspace.tabs.count == 1 && workspace.tabs[0].content.utf8.elementsEqual((source + "\r\nGeändert\r\n").utf8), "Speicherquelle verändert")
                cleanup(); finish(true, "Lokale Verweise: echtes Markdown-Menü, Liste/Filter, Quellsprung, stale Guard, Abbruch und unveränderte Dateien")
            } catch {
                if let output = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] {
                    let target = window.attachedSheet ?? window
                    let snapshot: TypeScrollSnapshot? = await withCheckedContinuation { continuation in typeScrollCapture(window: target) { continuation.resume(returning: $0) } }
                    if let snapshot { try? snapshot.data.write(to: URL(fileURLWithPath: output).appendingPathComponent("failure.png")) }
                }
                cleanup(); finish(false, stage + ": " + error.localizedDescription)
            }
        }
    }

    private static func runFolderComparisonTest() {
        testLabel = "foldercompare"
        Task { @MainActor in
            guard let workspace = Workspace.shared,
                  let window = CommandTargeting.registeredWindow(for: workspace) else { finish(false, "Dokumentfenster fehlt") }
            let base = selfTestTemporaryDirectory().appendingPathComponent("fastra-folder-native-\(UUID().uuidString)")
            let left = base.appendingPathComponent("left"), right = base.appendingPathComponent("right")
            let blocked = left.appendingPathComponent("blocked")
            let appearance = NSApp.appearance
            var stage = "Fixture"
            @MainActor func cleanup() {
                workspace.fileDiffComputations.cancelAll()
                NSApp.appearance = appearance
                try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: blocked.path)
                try? FileManager.default.removeItem(at: base)
            }
            func require(_ ok: Bool, _ message: String) throws {
                if !ok { throw NSError(domain: "FolderComparisonSelfTest", code: 1,
                    userInfo: [NSLocalizedDescriptionKey: message]) }
            }
            func value<T>(_ input: T?, _ message: String) throws -> T {
                guard let input else { throw NSError(domain: "FolderComparisonSelfTest", code: 2,
                    userInfo: [NSLocalizedDescriptionKey: message]) }
                return input
            }
            @MainActor func wait(_ detail: String, _ condition: @MainActor () -> Bool) async throws {
                try await nativeUIWait(stage + " / " + detail, condition)
            }
            @MainActor func click(_ id: String, in target: NSWindow? = nil) async throws {
                try await stableMarkerClick(id, in: target ?? window, stage: stage)
            }
            func write(_ data: Data, at url: URL) throws {
                try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                try data.write(to: url)
            }
            @MainActor func matrix(_ name: String, in target: NSWindow, minimum: CGFloat, height: CGFloat) async throws {
                guard let output = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] else { return }
                for (mode, appearance) in [("light", NSAppearance.Name.aqua), ("dark", .darkAqua)] {
                    NSApp.appearance = NSAppearance(named: appearance)
                    for width in [minimum, 1100] {
                        target.setContentSize(NSSize(width: width, height: height))
                        try await Task.sleep(for: .milliseconds(350))
                        try require(abs((target.contentView?.bounds.width ?? 0) - width) < 1, "Fensterbreite stimmt nicht")
                        let snapshot: TypeScrollSnapshot? = await withCheckedContinuation { continuation in
                            typeScrollCapture(window: target) { continuation.resume(returning: $0) }
                        }
                        guard let snapshot, snapshot.source == "screen" else {
                            cleanup(); finish(.environment, "Echte Fensteraufnahme fehlt: " + name)
                        }
                        let url = URL(fileURLWithPath: output).appendingPathComponent(name + "-" + mode + "-\(Int(width)).png")
                        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                        try snapshot.data.write(to: url)
                    }
                }
            }
            @MainActor func selectTab(_ id: UUID) async throws {
                let root = try value(window.contentView, "Fensterinhalt fehlt")
                scrollTabIntoView(id: id, in: root)
                let marker = try value(["current", "comparison", "idle"].compactMap {
                    markerView(id: "documentTab-" + $0 + "-" + id.uuidString, in: root)
                }.first, "Tabmarker fehlt")
                try require(sendTabClick(on: marker, in: window, modifiers: []) == nil, "Tabklick fehlgeschlagen")
                try await wait("Tab montiert") {
                    workspace.activeTabID == id && window.contentView.flatMap { markerView(id: "folderComparisonFinished", in: $0) } != nil
                }
            }
            @MainActor func typeFilter(_ text: String) async throws {
                let root = try value(window.contentView, "Fensterinhalt fehlt")
                var fields: [NSTextField] = []
                collectEditableFields(in: root, into: &fields)
                // SwiftUI kann den Identifier am Wrapper anbringen. Der
                // eindeutige lokalisierte Placeholder bezeichnet dasselbe Feld.
                let field = try value(fields.first {
                    $0.accessibilityIdentifier() == "folderComparisonFilter"
                        || $0.placeholderString == L10n.string("Ergebnisse filtern")
                }, "Filterfeld fehlt: " + fields.map { describe($0) }.joined(separator: ", "))
                try require(window.makeFirstResponder(field), "Filterfokus fehlt")
                let editor = try value(field.currentEditor(), "Nativer Feldeditor fehlt")
                editor.selectAll(nil)
                editor.insertText(text)
            }
            @MainActor func openFromMenu() async throws {
                guard let main = NSApp.mainMenu,
                      let root = main.items.first(where: { $0.title == L10n.string("Suchen") }),
                      let menu = root.submenu else { throw NSError(domain: "FolderComparisonMenu", code: 1) }
                // SwiftUI erzeugt die Einträge erst beim echten Öffnen.
                // Der Timer läuft deshalb auch in AppKits Menü-Tracking.
                let failure: String? = await withCheckedContinuation { continuation in
                    var timer: Timer?, ticks = 0
                    timer = Timer(timeInterval: 0.05, repeats: true) { _ in
                        ticks += 1
                        if let item = menu.items.first(where: { $0.title == L10n.string("Ordner vergleichen…") }), item.isEnabled {
                            timer?.invalidate(); timer = nil
                            _ = item.accessibilityPerformPress()
                            continuation.resume(returning: nil)
                        } else if ticks >= 100 {
                            timer?.invalidate(); timer = nil; menu.cancelTracking(); main.cancelTracking()
                            continuation.resume(returning: menu.items.map { "\($0.title):\($0.isEnabled)" }.joined(separator: ", "))
                        }
                    }
                    if let timer { RunLoop.main.add(timer, forMode: .common); RunLoop.main.add(timer, forMode: .eventTracking) }
                    DispatchQueue.main.async { _ = root.accessibilityPerformPress() }
                }
                try require(failure == nil, "Ordnervergleich im geöffneten Menü nicht bedienbar: " + (failure ?? ""))
            }
            do {
                for root in [left, right] { try write(Data([0, 1, 255]), at: root.appendingPathComponent("über/common.bin")) }
                try write(Data("left\n".utf8), at: left.appendingPathComponent("über/change.txt"))
                try write(Data("right\n".utf8), at: right.appendingPathComponent("über/change.txt"))
                try write(Data(), at: left.appendingPathComponent("only-left.txt"))
                try write(Data(), at: right.appendingPathComponent("only-right.txt"))
                let untouched = EditorTab(title: "kept.txt", path: "", content: "keep this document", isDirty: true)
                workspace.tabs = [untouched]; workspace.activeTabID = untouched.id
                NSApp.activate(ignoringOtherApps: true); window.makeKeyAndOrderFront(nil)
                window.setContentSize(NSSize(width: MainWindowSizing.minimumWidth, height: 700))
                stage = "Ordnerauswahl"
                try await wait("Aktives Dokumentfenster") {
                    NSApp.isActive && window.isKeyWindow && CommandTargeting.targetWorkspace() === workspace
                }
                try await openFromMenu()
                try await wait("Leeres Sheet sperrt Start") {
                    window.attachedSheet?.contentView.flatMap { markerView(id: "folderComparisonStartBlocked", in: $0) } != nil
                }
                try await click("folderComparisonDialogCancel", in: try value(window.attachedSheet, "Sheet fehlt"))
                try await wait("Menüsheet geschlossen") { window.attachedSheet == nil && !workspace.showFolderComparisonDialog }
                workspace.presentFolderComparisonDialog(left: left, right: right)
                try await wait("Vorausgefülltes Sheet") {
                    window.attachedSheet?.contentView.flatMap { markerView(id: "folderComparisonStartReady", in: $0) } != nil
                }
                let sheet = try value(window.attachedSheet, "Auswahlsheet fehlt")
                try await matrix("folder-dialog", in: sheet, minimum: 640, height: 480)
                try await click("folderComparisonStart", in: sheet)
                try await wait("Vollständiges Ergebnis") {
                    window.attachedSheet == nil && workspace.activeTab?.folderComparison?.result?.isComplete == true
                        && window.contentView.flatMap { markerView(id: "folderComparisonFinished", in: $0) } != nil
                }
                let folderID = try value(workspace.activeTabID, "Ergebnistab fehlt")
                let initial = try value(workspace.activeTab?.folderComparison, "Ordnerzustand fehlt")
                try require(initial.result?.rows.count == 5 && initial.result?.budgetBytes == 17, "Einträge oder Bytebudget falsch")
                try require(workspace.activeTab?.isEditableTextDocument == false && workspace.activeTab?.hasUnsavedChanges == false, "Ordnerergebnis editierbar oder dirty")
                stage = "Vollständige Liste und Filter"
                try await matrix("folder-results", in: window, minimum: MainWindowSizing.minimumWidth, height: 700)
                try await typeFilter("only-left")
                try await wait("Ein gefilterter Eintrag") { window.contentView.flatMap { markerView(id: "folderComparisonVisibleCount-1", in: $0) } != nil }
                try await typeFilter("")
                try await wait("Filter zurückgesetzt") { window.contentView.flatMap { markerView(id: "folderComparisonVisibleCount-5", in: $0) } != nil }
                let changedRow = try value(initial.result?.rows.first { $0.path.hasSuffix("/change.txt") }, "Textpaar fehlt")
                try await click("folderComparisonRow-" + changedRow.id.base64EncodedString())
                try await wait("Dateipaar freigegeben") { window.contentView.flatMap { markerView(id: "folderComparisonOpenPairReady", in: $0) } != nil }
                stage = "Dateipaar im vorhandenen Vergleich"
                try await click("folderComparisonOpenPairReady")
                try await wait("Frischer Datei-Diff") { workspace.activeTab?.fileDiffDocument?.result?.blocks.count == 1 }
                try require(workspace.activeTab?.fileDiffRequest?.left.documentOrigin == nil
                    && workspace.activeTab?.fileDiffRequest?.right.documentOrigin == nil, "Externe Dateiseite hat Schreibursprung")
                try await matrix("folder-pair", in: window, minimum: MainWindowSizing.minimumWidth, height: 700)
                try await selectTab(folderID)
                stage = "Fremdänderung und erneute Prüfung"
                try Data("left\n".utf8).write(to: right.appendingPathComponent("über/change.txt"), options: .atomic)
                try await click("folderComparisonRefresh")
                try await wait("Aktuelle Dateistände") {
                    guard let state = workspace.activeTab?.folderComparison, state.request.id != initial.request.id,
                          let row = state.result?.rows.first(where: { $0.id == changedRow.id }) else { return false }
                    return row.status == .identical && !state.running
                }
                try await matrix("folder-refreshed", in: window, minimum: MainWindowSizing.minimumWidth, height: 700)
                stage = "Nicht prüfbare Einträge"
                for root in [left, right] {
                    try write(Data(), at: root.appendingPathComponent("blocked/a.txt"))
                    let file = root.appendingPathComponent("large.bin")
                    FileManager.default.createFile(atPath: file.path, contents: nil)
                    let handle = try FileHandle(forWritingTo: file)
                    try handle.truncate(atOffset: FileSnapshot.maximumReadBytes + 1); try handle.close()
                }
                try FileManager.default.createSymbolicLink(at: left.appendingPathComponent("linked.txt"), withDestinationURL: right.appendingPathComponent("über/change.txt"))
                try FileManager.default.setAttributes([.posixPermissions: 0o000], ofItemAtPath: blocked.path)
                try await click("folderComparisonRefresh")
                try await wait("Ergebnis sichtbar unvollständig") {
                    workspace.activeTab?.folderComparison?.result?.isComplete == false && workspace.activeTab?.folderComparison?.running == false
                }
                let incomplete = try value(workspace.activeTab?.folderComparison?.result, "Unvollständige Liste fehlt")
                let large = try value(incomplete.rows.first { $0.path == "large.bin" }, "Großdatei fehlt")
                try require(large.status == .unavailable && !large.canOpenPair, "Großdatei fälschlich freigegeben")
                try await matrix("folder-incomplete", in: window, minimum: MainWindowSizing.minimumWidth, height: 700)
                try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: blocked.path)
                stage = "Native Abbruchaktion"
                let cancelLeft = base.appendingPathComponent("cancel-left"), cancelRight = base.appendingPathComponent("cancel-right")
                for root in [cancelLeft, cancelRight] {
                    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
                    for index in 0..<8 {
                        let file = root.appendingPathComponent("part-\(index).bin")
                        FileManager.default.createFile(atPath: file.path, contents: nil)
                        let handle = try FileHandle(forWritingTo: file)
                        try handle.truncate(atOffset: 128 * 1024 * 1024); try handle.close()
                    }
                }
                workspace.openFolderComparison(request: .init(left: cancelLeft, right: cancelRight, options: .init()))
                try await wait("Sichtbarer Abbrechen-Knopf") { window.contentView.flatMap { markerView(id: "folderComparisonCancel", in: $0) } != nil }
                try await click("folderComparisonCancel")
                try await wait("Abgebrochen und ausgetragen") {
                    workspace.activeTab?.folderComparison?.cancelled == true && workspace.fileDiffComputations.activeCount == 0
                }
                try await Task.sleep(for: .milliseconds(250))
                try require(workspace.activeTab?.folderComparison?.result == nil, "Abbruch veröffentlichte spät ein Ergebnis")
                try await matrix("folder-cancelled", in: window, minimum: MainWindowSizing.minimumWidth, height: 700)
                try require(workspace.tabs.first { $0.id == untouched.id }?.content == untouched.content
                    && workspace.tabs.first { $0.id == untouched.id }?.isDirty == true, "Offenes Dokument verändert")
                try require(try Data(contentsOf: left.appendingPathComponent("über/change.txt")) == Data("left\n".utf8), "Linke Datei verändert")
                cleanup()
                finish(true, "Native Ordnerauswahl, vollständige/ungeprüfte Liste, Filter, Dateipaar, Fremdänderung, erneute Prüfung und Abbruch; Quellen und Dokument geschützt")
            } catch {
                FileHandle.standardError.write(Data(("FOLDER_COMPARE_FAILURE stage=\(stage) error=\(error.localizedDescription)\n").utf8))
                if let output = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] {
                    let snapshot: TypeScrollSnapshot? = await withCheckedContinuation { continuation in
                        typeScrollCapture(window: window.attachedSheet ?? window) { continuation.resume(returning: $0) }
                    }
                    if let snapshot {
                        let directory = URL(fileURLWithPath: output)
                        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
                        try? snapshot.data.write(to: directory.appendingPathComponent("folder-failure-" + snapshot.source + ".png"))
                    }
                }
                cleanup(); finish(false, stage + ": " + error.localizedDescription)
            }
        }
    }

    private static func runFileDiffTransferTest() {
        testLabel = "filedifftransfer"
        Task { @MainActor in
            guard let ws = Workspace.shared, let window = CommandTargeting.registeredWindow(for: ws) else {
                finish(false, "Dokumentfenster fehlt")
            }
            var stage = "Fixture"
            let appearance = NSApp.appearance
            let base = selfTestTemporaryDirectory().appendingPathComponent("fastra-block-transfer-\(UUID().uuidString)")
            @MainActor func cleanup() { NSApp.appearance = appearance; try? FileManager.default.removeItem(at: base) }
            func require(_ value: Bool, _ message: String) throws {
                if !value { throw NSError(domain: "FileDiffTransferSelfTest", code: 1,
                    userInfo: [NSLocalizedDescriptionKey: message]) }
            }
            func value<T>(_ input: T?, _ message: String) throws -> T {
                guard let input else { throw NSError(domain: "FileDiffTransferSelfTest", code: 2,
                    userInfo: [NSLocalizedDescriptionKey: message]) }
                return input
            }
            @MainActor func wait(_ detail: String, _ condition: @MainActor () -> Bool) async throws {
                try await nativeUIWait(stage + " / " + detail, condition)
            }
            @MainActor func click(_ id: String, in target: NSWindow, repetitions: Int = 1) async throws {
                try await stableMarkerClick(id, in: target, stage: stage, repetitions: repetitions)
            }
            @MainActor func selectTab(_ id: UUID) async throws {
                let root = try value(window.contentView, "Fensterinhalt fehlt")
                window.makeKeyAndOrderFront(nil)
                scrollTabIntoView(id: id, in: root)
                let marker = try value(["current", "comparison", "idle"].compactMap {
                    markerView(id: "documentTab-" + $0 + "-" + id.uuidString, in: root)
                }.first, "Tabmarker fehlt")
                try require(sendTabClick(on: marker, in: window, modifiers: []) == nil, "Tabklick fehlgeschlagen")
                try await wait("Tabwechsel") { ws.activeTabID == id }
            }
            @MainActor func sheet() -> NSWindow? {
                window.sheets.first { $0.contentView.flatMap { markerView(id: "fileDiffTransferSheet", in: $0) } != nil }
            }
            @MainActor func matrix(_ name: String, in target: NSWindow, minimum: CGFloat, height: CGFloat) async throws {
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] else { return }
                for (mode, appearance) in [("light", NSAppearance.Name.aqua), ("dark", .darkAqua)] {
                    NSApp.appearance = NSAppearance(named: appearance)
                    for width in [minimum, 1100] {
                        target.setContentSize(NSSize(width: width, height: height))
                        try await Task.sleep(for: .milliseconds(350))
                        try require(abs((target.contentView?.bounds.width ?? 0) - width) < 1, "Fensterbreite stimmt nicht")
                        let snapshot: TypeScrollSnapshot? = await withCheckedContinuation { continuation in
                            typeScrollCapture(window: target) { continuation.resume(returning: $0) }
                        }
                        guard let snapshot, snapshot.source == "screen" else {
                            cleanup(); finish(.environment, "Echte Fensteraufnahme fehlt: " + name)
                        }
                        let output = URL(fileURLWithPath: directory).appendingPathComponent(name + "-" + mode + "-\(Int(width)).png")
                        try FileManager.default.createDirectory(at: output.deletingLastPathComponent(), withIntermediateDirectories: true)
                        try snapshot.data.write(to: output)
                    }
                }
            }
            @MainActor func prepare(_ direction: FileDiffTransfer.Direction) async throws -> NSWindow {
                try await wait("Aktueller Vergleich montiert") {
                    guard let request = ws.activeTab?.fileDiffRequest, let root = window.contentView else { return false }
                    return ws.activeTab?.fileDiffDocument?.result != nil
                        && markerView(id: "fileDiffRequest-" + request.id.uuidString, in: root) != nil
                        && markerView(id: "fileDiffTransferRefreshReady", in: root) != nil
                }
                let request = try value(ws.activeTab?.fileDiffRequest, "Aktueller Auftrag fehlt")
                let readyID = (direction == .toLeft ? "fileDiffTransferLeftReady-" : "fileDiffTransferRightReady-") + request.id.uuidString
                let initialReady = window.contentView.flatMap { markerView(id: readyID, in: $0) } != nil
                let initialSheets = window.sheets.count
                let started = ProcessInfo.processInfo.systemUptime
                try await wait("Aktiver Übernahmeknopf und freies Dokumentfenster") {
                    window.attachedSheet == nil && window.contentView.flatMap { markerView(id: readyID, in: $0) } != nil
                }
                FileHandle.standardError.write(Data(("FILE_DIFF_TRANSFER_READY stage=\(stage) initialReady=\(initialReady) initialSheets=\(initialSheets) waitedMs=\((ProcessInfo.processInfo.systemUptime - started) * 1000)\n").utf8))
                try await click(direction == .toLeft ? "fileDiffTransferLeft" : "fileDiffTransferRight", in: window)
                try await wait("Bestätigungsvorschau") {
                    sheet()?.contentView.flatMap { markerView(id: "fileDiffTransferApplyReady", in: $0) } != nil
                }
                return try value(sheet(), "Vorschausheet fehlt")
            }
            @MainActor func focusEditor(_ id: UUID, content: String) async throws {
                let wasActive = NSApp.isActive
                NSApp.activate(ignoringOtherApps: true)
                window.makeKeyAndOrderFront(nil)
                try await wait("Aktives Dokumentfenster ohne Sheet") {
                    NSApp.isActive && window.isKeyWindow && NSApp.keyWindow === window && window.attachedSheet == nil
                }
                try await selectTab(id)
                let initial = CommandTargeting.editorTextView(for: ws)
                let started = ProcessInfo.processInfo.systemUptime
                try await wait("Editor tatsächlich im Dokumentfenster montiert") {
                    guard let editor = CommandTargeting.editorTextView(for: ws), let root = window.contentView else { return false }
                    return editor.window === window && editor.isDescendant(of: root)
                        && !editor.isHiddenOrHasHiddenAncestor && editor.visibleRect.width > 1 && editor.visibleRect.height > 1
                        && editor.string == content
                }
                let editor = try value(CommandTargeting.editorTextView(for: ws), "Editor fehlt")
                FileHandle.standardError.write(Data(("FILE_DIFF_TRANSFER_FOCUS stage=\(stage) wasActive=\(wasActive) initialWindowMatches=\(initial?.window === window) sameEditor=\(initial === editor) mountedAfterMs=\((ProcessInfo.processInfo.systemUptime - started) * 1000)\n").utf8))
                try require(window.makeFirstResponder(nil), "Alter Editorfokus ließ sich nicht freigeben")
                let rect = editor.visibleRect
                let point = editor.convert(NSPoint(x: rect.minX + min(100, rect.width / 2),
                    y: rect.minY + min(20, rect.height / 2)), to: nil)
                var mouseUpDelivered = false
                let focusStage = stage
                let monitor = NSEvent.addLocalMonitorForEvents(matching: .leftMouseUp) { event in
                    if event.windowNumber == window.windowNumber,
                       abs(event.locationInWindow.x - point.x) < 1,
                       abs(event.locationInWindow.y - point.y) < 1 {
                        DispatchQueue.main.async {
                            mouseUpDelivered = true
                            FileHandle.standardError.write(Data(("FILE_DIFF_FOCUS_MOUSE_UP stage=\(focusStage) time=\(ProcessInfo.processInfo.systemUptime)\n").utf8))
                        }
                    }
                    return event
                }
                defer { if let monitor { NSEvent.removeMonitor(monitor) } }
                try require(sendMouseClick(at: point, in: window, modifiers: [], viaApp: true), "Editorklick fehlt")
                try await wait("Editorfokus") {
                    guard let current = CommandTargeting.editorTextView(for: ws) else { return false }
                    return mouseUpDelivered && NSApp.isActive && window.isKeyWindow && NSApp.keyWindow === window
                        && current.window === window && window.firstResponder === current && current.string == content
                }
            }
            @MainActor func compare(_ left: EditorTab, _ right: EditorTab, options: FileDiffOptions = FileDiffOptions()) async throws -> UUID {
                try await wait("Vorgänger-Sheet vollständig geschlossen") { window.attachedSheet == nil }
                ws.tabs = [left, right, EditorTab(title: "untouched.txt", path: "", content: "unberührt")]
                ws.activeTabID = left.id
                let lhs = try value(FileDiffSide.document(left, in: ws), "Linker Ursprung fehlt")
                let rhs = try value(FileDiffSide.document(right, in: ws), "Rechter Ursprung fehlt")
                ws.openFileDiffTab(request: FileDiffRequest(left: lhs, right: rhs, options: options))
                let id = try value(ws.activeTabID, "Vergleichstab fehlt")
                try await wait("Diff") { ws.activeTab?.fileDiffDocument?.result != nil }
                return id
            }
            do {
                try FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
                let url = base.appendingPathComponent("left.txt")
                let original = "one\r\nleft\r\nend\r\n", rightText = "one\nright\nend\nextra\n"
                let bytes = Data(original.utf8); try bytes.write(to: url)
                var left = EditorTab(title: "left.txt", path: url.path, content: original)
                left.url = url
                let right = EditorTab(title: "right.txt", path: "", content: rightText)
                ws.tabs = [left, right, EditorTab(title: "untouched.txt", path: "", content: "unberührt")]
                ws.activeTabID = left.id
                window.setContentSize(NSSize(width: max(760, window.contentMinSize.width), height: 700))
                ws.presentCompareFilesDialog(prefillingTabIDs: [left.id, right.id])
                try await wait("Vergleichsdialog") { window.attachedSheet?.contentView.flatMap { markerView(id: "compareFilesStart", in: $0) } != nil }
                try await matrix("block-compare-dialog", in: window,
                    minimum: max(760, window.contentMinSize.width), height: 700)
                try await click("compareFilesStart", in: window.attachedSheet!)
                try await wait("Dialog geschlossen, zwei Blöcke") {
                    !ws.showCompareFilesDialog && window.attachedSheet == nil && ws.activeTab?.fileDiffDocument?.result?.blocks.count == 2
                }
                let diff = try value(ws.activeTabID, "Vergleichstab fehlt")
                let minimum = max(760, window.contentMinSize.width)
                stage = "Dateivergleich: zwei Richtungen"
                try await matrix("block-diff", in: window, minimum: minimum, height: 700)
                let confirmation = try await prepare(.toLeft)
                try require(ws.fileDiffTransferPreview?.hasAnnotations == true, "Zeilenenden nicht in genauer Vorschau sichtbar")
                try await matrix("block-preview", in: confirmation, minimum: 620, height: 600)
                try await click("fileDiffTransferApply", in: confirmation)
                let changed = "one\r\nright\nend\r\n"
                try await wait("Übernahme und Neuberechnung") {
                    sheet() == nil && ws.tabs.first { $0.id == left.id }?.content == changed
                        && ws.activeTab?.fileDiffDocument?.result?.blocks.count == 1
                }
                try require(ws.tabs.first { $0.id == left.id }?.isDirty == true, "Dirty fehlt")
                try require(try Data(contentsOf: url) == bytes, "Plattendatei ohne Speichern verändert")
                try require(ws.tabs.first { $0.id == right.id }?.content == rightText, "Falsches Dokument verändert")
                stage = "Undo: Dokumenteditor fokussieren"
                try await focusEditor(left.id, content: changed)
                stage = "Native Rücknahme"
                let systemUndo = try await requestSystemUndoIfAvailable(before: changed, expected: original, mode: "block-transfer-undo")
                if !systemUndo { try await undoFromEditMenu() }
                try await wait("Original nach Undo-Menü") { ws.activeTab?.content == original }
                try await selectTab(diff)
                try await wait("Aktueller Diff nach Undo") { ws.activeTab?.fileDiffDocument?.result?.blocks.count == 2 }
                stage = "Redo: Dokumenteditor fokussieren"
                try await focusEditor(left.id, content: original)
                stage = "Natives Wiederholen"
                try await redoFromEditMenu()
                try await wait("Übernahme nach Redo-Menü") { ws.activeTab?.content == changed }
                if let output = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] {
                    let directory = URL(fileURLWithPath: output)
                    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
                    let proof: [String: Any] = ["undo": systemUndo ? "system-command-z" : "appkit-menu-action",
                        "redo": "appkit-menu-action", "restoredAfterUndo": true, "restoredAfterRedo": ws.activeTab?.content == changed]
                    try JSONSerialization.data(withJSONObject: proof, options: [.sortedKeys]).write(
                        to: directory.appendingPathComponent("native-history.json"), options: .atomic)
                }
                try await selectTab(diff)
                try await wait("Aktueller Diff nach Redo") { ws.activeTab?.fileDiffDocument?.result?.blocks.count == 1 }
                stage = "Richtung rechts: EOF-Löschung"
                let deletion = try await prepare(.toRight)
                try await click("fileDiffTransferApply", in: deletion)
                try await wait("Rechter Block entfernt") { sheet() == nil && ws.activeTab?.fileDiffDocument?.result?.isIdentical == true }
                try require(ws.tabs.first { $0.id == right.id }?.content == "one\nright\nend\n", "EOF-Löschung falsch")
                try require(ws.tabs.first { $0.id == right.id }?.isDirty == true, "Rechtes Dirty fehlt")
                try require(ws.tabs.first { $0.title == "untouched.txt" }?.content == "unberührt", "Unbeteiligtes Dokument verändert")
                try require(try Data(contentsOf: url) == bytes, "Platte nach zweiter Übernahme verändert")
                try await matrix("block-identical", in: window, minimum: minimum, height: 700)

                stage = "EOF, Einfügen, Entfernen und ignorierte Unterschiede"
                for (caseIndex, example) in [
                    ("a", "a\n", "a\n", FileDiffOptions()),
                    ("a\r\n", "a", "a", FileDiffOptions()),
                    ("a\nz\n", "a\nx\nz\n", "a\nx\nz\n", FileDiffOptions()),
                    ("a\nx\nz\n", "a\nz\n", "a\nz\n", FileDiffOptions()),
                    ("a  \nold\nz", "A\nnew\nz", "a  \nnew\nz", FileDiffOptions(ignoreTrailingWhitespace: true, ignoreCase: true))
                ].enumerated() {
                    let (before, sourceText, expected, options) = example
                    stage = "EOF/Einfügen/Löschen/ignoriert, Fall \(caseIndex)"
                    let target = EditorTab(title: "target.txt", path: "", content: before)
                    let source = EditorTab(title: "source.txt", path: "", content: sourceText)
                    _ = try await compare(target, source, options: options)
                    let confirmation = try await prepare(.toLeft)
                    try await click("fileDiffTransferApply", in: confirmation)
                    try await wait("Einzelblock abgeschlossen") { sheet() == nil && ws.activeTab?.fileDiffDocument?.result != nil }
                    try require(ws.tabs.first { $0.id == target.id }?.content.utf8.elementsEqual(expected.utf8) == true, "Einzelblock verändert falsche Bytes")
                    try require(ws.tabs.first { $0.id == source.id }?.content == source.content, "Quellseite verändert")
                }
                stage = "Veraltete Quelle im offenen Sheet"
                let target = EditorTab(title: "target.txt", path: "", content: "old\n")
                let source = EditorTab(title: "source.txt", path: "", content: "new\n")
                _ = try await compare(target, source)
                let stale = try await prepare(.toLeft)
                let sourceIndex = try value(ws.tabs.firstIndex { $0.id == source.id }, "Quelle fehlt")
                ws.tabs[sourceIndex].content = "external\n"
                try await wait("Anwenden gesperrt") { stale.contentView.flatMap { markerView(id: "fileDiffTransferApplyBlocked", in: $0) } != nil }
                try await matrix("block-stale", in: stale, minimum: 620, height: 600)
                try await click("fileDiffTransferApply", in: stale)
                try await click("fileDiffTransferClose", in: stale)
                try await wait("Sheet geschlossen") { sheet() == nil }
                try require(ws.tabs.first { $0.id == target.id }?.content == target.content, "Veraltete Quelle angewandt")
                stage = "Schnelle Folgeaktionen und Schließen"
                try await click("fileDiffTransferRefresh", in: window)
                try await wait("Neuer Diff") { ws.activeTab?.fileDiffDocument?.result != nil }
                try await click("fileDiffTransferLeft", in: window, repetitions: 2)
                try await wait("Einzelnes Vorschausheet") { sheet() != nil }
                try require(window.sheets.count == 1, "Mehrere Vorschauen nach schnellem Doppelklick")
                try await click("fileDiffTransferClose", in: sheet()!)
                try await wait("Vorschau verworfen") { sheet() == nil && ws.fileDiffTransferPreview == nil }
                try require(ws.tabs.first { $0.id == target.id }?.content == target.content, "Abgebrochene Vorschau übernommen")

                stage = "Laufende Vorbereitung über sichtbaren Abbrechen-Knopf beenden"
                let largeText = (1...150_000).map { "stable-\($0) " + String(repeating: "x", count: 130) }.joined(separator: "\n") + "\n"
                let largeTarget = EditorTab(title: "large-target.txt", path: "", content: largeText)
                let largeSource = EditorTab(title: "large-source.txt", path: "", content:
                    largeText.replacingOccurrences(of: "stable-75000 ", with: "changed-75000 "))
                _ = try await compare(largeTarget, largeSource)
                try await wait("Großer Vergleich montiert") {
                    guard let request = ws.activeTab?.fileDiffRequest, let root = window.contentView else { return false }
                    return markerView(id: "fileDiffRequest-" + request.id.uuidString, in: root) != nil
                        && markerView(id: "fileDiffTransferRefreshReady", in: root) != nil
                }
                try await click("fileDiffTransferLeft", in: window)
                try await wait("Abbrechen tatsächlich montiert") {
                    ws.activeTab?.fileDiff?.pendingTransferID != nil
                        && window.contentView.flatMap { markerView(id: "fileDiffTransferCancelReady", in: $0) } != nil
                }
                try await click("fileDiffTransferCancelReady", in: window)
                try await wait("Vorbereitung abgebrochen") { ws.activeTab?.fileDiff?.pendingTransferID == nil && ws.fileDiffComputations.activeCount == 0 }
                try await Task.sleep(for: .milliseconds(250))
                try require(sheet() == nil && ws.fileDiffTransferPreview == nil, "Abgebrochene Vorbereitung öffnet spät eine Vorschau")
                try require(ws.tabs.first { $0.id == largeTarget.id }?.content.utf8.elementsEqual(largeText.utf8) == true, "Abbruch verändert großen Zieltext")
                _ = try await compare(target, source)

                stage = "Externe Dateiquellen bleiben schreibgeschützt"
                let file = base.appendingPathComponent("external.txt")
                try Data("external-file\n".utf8).write(to: file)
                try FileManager.default.setAttributes([.posixPermissions: 0o400], ofItemAtPath: file.path)
                ws.openFileDiffTab(request: FileDiffRequest(left: .file(file),
                    right: try value(FileDiffSide.document(ws.tabs.first { $0.id == target.id }!, in: ws), "Dokumentursprung fehlt"), options: FileDiffOptions()))
                try await wait("Externer Vergleich") { ws.activeTab?.fileDiffDocument?.result != nil }
                let external = try value(ws.activeTab, "Externer Vergleich fehlt")
                let request = try value(external.fileDiffRequest, "Externer Auftrag fehlt")
                try require(!ws.fileDiffTransferIsAvailable(tabID: external.id, requestID: request.id, direction: .toLeft), "Externe Datei ist Schreibziel")
                try require(ws.fileDiffTransferIsAvailable(tabID: external.id, requestID: request.id, direction: .toRight), "Offenes Ziel trotz lesbarer Read-only-Quelle gesperrt")
                try await matrix("block-external", in: window, minimum: minimum, height: 700)
                let externalSheet = try await prepare(.toRight)
                try Data("changed-source\n".utf8).write(to: file, options: .atomic)
                try await click("fileDiffTransferApply", in: externalSheet)
                try await wait("Datei-Preflight erklärt Fehler") { externalSheet.contentView.flatMap { markerView(id: "fileDiffTransferApplyBlocked", in: $0) } != nil }
                try require(ws.tabs.first { $0.id == target.id }?.content == target.content, "Veraltete Plattendatei angewandt")
                try await click("fileDiffTransferClose", in: externalSheet)
                try await wait("Letzte Vorschau geschlossen") { sheet() == nil }
                try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: file.path)
                cleanup()
                finish(true, "Blockübernahme links/rechts, genaue Vorschau, native Undo/Redo mit aktuellem Diff, EOF, ignorierte Unterschiede, stale Speicher/Platte, schnelle Folgeaktionen und Read-only-Quelle geprüft")
            } catch {
                FileHandle.standardError.write(Data(("FILE_DIFF_TRANSFER_FAILURE stage=\(stage) active=\(NSApp.isActive) keyWindow=\(NSApp.keyWindow === window) currentEditorInWindow=\(CommandTargeting.editorTextView(for: ws)?.window === window) currentEditorFocused=\(window.firstResponder === CommandTargeting.editorTextView(for: ws)) sheets=\(window.sheets.count) pending=\(String(describing: ws.activeTab?.fileDiff?.pendingTransferID)) preview=\(String(describing: ws.fileDiffTransferPreview?.id)) transferError=\(String(describing: ws.activeTab?.fileDiff?.transferError))\n").utf8))
                if let directory = ProcessInfo.processInfo.environment["FASTRA_TEXT_WORKFLOW_DIR"] {
                    let snapshot: TypeScrollSnapshot? = await withCheckedContinuation { continuation in
                        typeScrollCapture(window: sheet() ?? window) { continuation.resume(returning: $0) }
                    }
                    if let snapshot {
                        let output = URL(fileURLWithPath: directory).appendingPathComponent("block-failure-" + snapshot.source + ".png")
                        try? FileManager.default.createDirectory(at: output.deletingLastPathComponent(), withIntermediateDirectories: true)
                        try? snapshot.data.write(to: output)
                    }
                }
                cleanup(); finish(false, stage + ": " + error.localizedDescription)
            }
        }
    }

    private static func runFileDiffTest() {
        testLabel = "filediff"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        // ── Fixtures: identische Basis, drei gezielte Unterschiede ────────
        // Drei längere Blöcke statt bloß weit auseinanderliegender Einzelzeilen:
        // unveränderte Zwischenräume werden im Renderer eingeklappt und würden
        // allein deshalb keine Scrollstrecke garantieren. Die sichtbaren
        // Änderungszeilen selbst müssen höher als der Viewport sein.
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-filediff-\(UUID().uuidString)")
        var leftLines = (1...155).map { "zeile \($0)" }
        var rightLines = leftLines
        for index in 1..<31 {
            leftLines[index] = "alpha \(index) ALT"
            rightLines[index] = "alpha \(index) NEU"
        }
        leftLines.insert(
            contentsOf: (1...30).map { "nur-links \($0)" },
            at: 80
        )
        for offset in 0..<30 {
            leftLines[leftLines.count - 1 - offset] = "omega \(offset) ALT"
            rightLines[rightLines.count - 1 - offset] = "omega \(offset) NEU"
        }
        let leftURL = base.appendingPathComponent("links.txt")
        let rightURL = base.appendingPathComponent("rechts.txt")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            try leftLines.joined(separator: "\n")
                .write(to: leftURL, atomically: true, encoding: .utf8)
            try rightLines.joined(separator: "\n")
                .write(to: rightURL, atomically: true, encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixtures nicht anlegbar: \(error.localizedDescription)")
        }
        // ── (a) Dialog öffnen — erscheint ein echtes Sheet? ────────────────
        ws.showCompareFilesDialog = true
        pollFileDiffSheet(ws, base: base, left: leftURL, right: rightURL)
    }

    private static func pollFileDiffSheet(_ ws: Workspace, base: URL,
                                          left: URL, right: URL) {
        waitFor(budget: 10, pause: 0.25,
                condition: { mainWindowForAXChecks()?.attachedSheet != nil },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "„Dateien vergleichen…“-Sheet erscheint nicht — \(book.summary)")
                },
                then: {
                    // Dialog ist real da — wieder schließen und den Vergleich über
                    // denselben Pfad starten, den der „Vergleichen"-Button nimmt.
                    ws.showCompareFilesDialog = false
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                        ws.openFileDiffTab(request: FileDiffRequest(
                            left: .file(left), right: .file(right),
                            options: FileDiffOptions()
                        ))
                        pollFileDiffRendered(ws, base: base)
                    }
                })
    }

    private static func pollFileDiffRendered(_ ws: Workspace, base: URL) {
        // Marker trägt Blockzahl + Auswahl: 3 Blöcke, Start beim ersten
        // Unterschied (wie der Git-Diff: „Unterschied 1 von 3").
        waitFor(budget: 10, pause: 0.25,
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    return content.map { markerViewExists(id: "diffState-b3-c0", in: $0) } ?? false
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Diff-Tab rendert keine 3 Unterschiede "
                        + "(Marker diffState-b3-c0 fehlt) — \(book.summary)")
                },
                then: {
                    // Modell-Gegenprobe: der Tab hält wirklich 3 Differenz-Blöcke.
                    guard let tab = ws.tabs.first(where: { $0.fileDiffRequest != nil }),
                          let result = tab.fileDiffDocument?.result,
                          result.blocks.count == 3 else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Marker gerendert, aber Modell hat nicht 3 Blöcke")
                    }
                    clickLastFileDiffListRow(ws, base: base)
                })
    }

    /// Größte Scroll-View im Fenster = der Diff-Bereich (die Differenzen-
    /// Liste ist auf 132 pt Höhe fixiert, das Sheet ist zu).
    private static func largestScrollView(in view: NSView) -> NSScrollView? {
        var best: NSScrollView? = nil
        func walk(_ v: NSView) {
            if let scroll = v as? NSScrollView {
                if scroll.frame.height > (best?.frame.height ?? 0) { best = scroll }
            }
            v.subviews.forEach(walk)
        }
        walk(view)
        return best
    }

    /// Echter Mausklick (Down+Up durch die Event-Pipeline) auf den letzten
    /// Eintrag der Differenzen-Liste — der 0×0-Marker sitzt in Zeilenmitte.
    private static func clickLastFileDiffListRow(_ ws: Workspace, base: URL) {
        guard let window = mainWindowForAXChecks(),
              let content = window.contentView,
              let marker = markerView(id: "diffListRow-2", in: content) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Listeneintrag „Block 2“ nicht im Fensterbaum gefunden")
        }
        let scrollBefore = largestScrollView(in: content)?
            .contentView.documentVisibleRect.origin.y ?? -1
        let point = marker.convert(NSPoint.zero, to: nil)
        let time = ProcessInfo.processInfo.systemUptime
        guard let down = NSEvent.mouseEvent(
            with: .leftMouseDown, location: point, modifierFlags: [],
            timestamp: time, windowNumber: window.windowNumber, context: nil,
            eventNumber: 0, clickCount: 1, pressure: 1
        ), let up = NSEvent.mouseEvent(
            with: .leftMouseUp, location: point, modifierFlags: [],
            timestamp: time + 0.05, windowNumber: window.windowNumber, context: nil,
            eventNumber: 1, clickCount: 1, pressure: 0
        ) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Maus-Events nicht baubar")
        }
        window.sendEvent(down)
        window.sendEvent(up)
        pollFileDiffJumped(base: base, scrollBefore: scrollBefore)
    }

    private static func pollFileDiffJumped(base: URL, scrollBefore: CGFloat) {
        // 5 s (Scroll-Animation: 0,16 s)
        var selected = false
        var scrollNow = scrollBefore
        waitFor(budget: 5, pause: 0.25,
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    selected = content.map {
                        markerViewExists(id: "diffState-b3-c2", in: $0)
                    } ?? false
                    scrollNow = content.flatMap { largestScrollView(in: $0) }?
                        .contentView.documentVisibleRect.origin.y ?? scrollBefore
                    return selected && scrollNow != scrollBefore
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Klick auf Differenzen-Liste: Auswahl=\(selected), "
                        + "Scroll \(Int(scrollBefore)) → \(Int(scrollNow)) — Sprung fehlt — \(book.summary)")
                },
                then: {
                    try? FileManager.default.removeItem(at: base)
                    finish(true, "Sheet real geöffnet; 3 Unterschiede gerendert; Klick "
                        + "auf Differenzen-Liste wählt Block 3 und scrollt den Diff "
                        + "(\(Int(scrollBefore)) → \(Int(scrollNow)))")
                })
    }

