    private static func pollGitStickyHeader(_ ws: Workspace, base: URL) {
        var found: (window: NSWindow, content: NSView, header: NSView, discard: NSView)?
        waitFor(budget: 6, pause: 0.05,
                condition: {
                    guard let window = mainWindowForAXChecks(),
                          let content = window.contentView,
                          let header = markerView(id: "gitSectionHeader-unstaged", in: content),
                          let discard = markerView(id: "gitHeaderDiscardAll", in: content),
                          // Seit 1.114.0 zeigt der Änderungen-Tab die Anzahl geänderter
                          // Dateien als Badge — bei genau 60 geänderten Dateien muss dort
                          // „60" stehen (der Marker trägt die angezeigte Zahl im Namen).
                          markerView(id: "sidebarChangesBadge-60", in: content) != nil,
                          // Seit 1.115.0 tragen (auch deaktivierbare) Knöpfe ihre
                          // Tooltips über die AppKit-Overlay-Brücke; mindestens der
                          // Commit-Knopf dieser Ansicht muss so einen Tooltip montieren.
                          fastraTooltipExists(in: content),
                          (ws.gitStatus?.unstagedChanges.count ?? 0) >= 60 else { return false }
                    found = (window, content, header, discard)
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Abschnittskopf, Knopf oder Tab-Badge fehlt "
                        + "(Änderungen: \(ws.gitStatus?.unstagedChanges.count ?? 0)) — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Abschnittskopf nach Erfolg verschwunden") }
                    let (window, content, header, discard) = found
                    runGitStickyHeaderMeasurement(window: window, content: content,
                                                  header: header, discard: discard, base: base)
                })
    }

    /// Der Messteil von `pollGitStickyHeader`, sobald Kopf, Knopf, Badge und
    /// Tooltip im Fenster stehen.
    private static func runGitStickyHeaderMeasurement(window: NSWindow, content: NSView,
                                                      header: NSView, discard: NSView,
                                                      base: URL) {
        window.layoutIfNeeded()
        // Die NSScrollView, in der der Kopf liegt — dieselbe, die der Nutzer
        // mit dem Trackpad bewegt.
        var scroll: NSScrollView?
        var view: NSView? = header.superview
        while let current = view {
            if let candidate = current as? NSScrollView { scroll = candidate; break }
            view = current.superview
        }
        guard let scroll else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Keine NSScrollView über dem Abschnittskopf gefunden")
        }
        // Die Fixture beginnt oben, unabhängig von einem gespeicherten Offset.
        scrollGitChangesList(scroll, by: 0)
        let initialScrollY = scroll.contentView.bounds.origin.y
        let before = header.convert(header.bounds, to: content)
        let heightBefore = scroll.documentView?.bounds.height ?? 0
        guard heightBefore > scroll.contentView.bounds.height + 100 else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Liste ist nicht scrollbar (Inhalt \(Int(heightBefore)) pt, "
                + "Sichtfenster \(Int(scroll.contentView.bounds.height)) pt)")
        }
        // Scrollen über den regulären AppKit-Weg der gefundenen ScrollView.
        let target: CGFloat = 400
        scrollGitChangesList(scroll, by: target)

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
            // Kein `defer`: Jeder Ausgang dieses Blocks geht über `finish`,
            // und das endet in `exit()` — der Stack wird nicht abgewickelt.
            func cleanUp() { try? FileManager.default.removeItem(at: base) }
            guard let contentNow = window.contentView,
                  let headerNow = markerView(id: "gitSectionHeader-unstaged",
                                             in: contentNow),
                  let discardNow = markerView(id: "gitHeaderDiscardAll",
                                              in: contentNow),
                  let scrollNow = enclosingScrollView(of: headerNow) else {
                cleanUp()
                finish(false, "Abschnittskopf ist nach dem Scrollen verschwunden — "
                    + "er scrollt mit statt oben zu bleiben")
            }
            let after = headerNow.convert(headerNow.bounds, to: contentNow)
            // Offset und Kopf im selben Callback an der aktuellen Hierarchie
            // messen. SwiftUI kann den vorherigen Scrollstand zurückgesetzt
            // oder sogar die alte ScrollView ersetzt haben.
            let scrolled = scrollNow.contentView.bounds.origin.y - initialScrollY
            let viewport = scrollNow.contentView.convert(scrollNow.contentView.bounds,
                                                         to: contentNow)
            _ = discard
            // (a) Es wurde wirklich gescrollt. Ohne diese Prüfung bestünde der
            // Test auch dann, wenn die Liste stillstand — der Kopf sitzt ja
            // ungescrollt ohnehin oben.
            guard scrolled > 100 else {
                cleanUp()
                finish(false, "Die Liste hat sich nicht dauerhaft bewegt (Scroll-Differenz "
                    + "\(Int(scrolled)) pt) — die Zusage ist so nicht prüfbar")
            }
            // (b) Der Kopf ist trotz des Scrollens an derselben Stelle im
            // Fenster geblieben. Genau das ist das Festpinnen.
            guard abs(after.minY - before.minY) < 2 else {
                cleanUp()
                finish(false, "Der Abschnittskopf ist mitgescrollt "
                    + "(vorher y=\(Int(before.minY)), nachher y=\(Int(after.minY)))")
            }
            // (c) Und er sitzt an der Oberkante der Liste. Welche Kante „oben"
            // ist, hängt am Koordinatensystem: SwiftUIs Hosting-Views sind
            // geflippt (y wächst nach unten), AppKit-Views nicht.
            let listTop = contentNow.isFlipped ? viewport.minY : viewport.maxY
            let headerTop = contentNow.isFlipped ? after.minY : after.maxY
            guard abs(headerTop - listTop) < 2 else {
                cleanUp()
                finish(false, "Der Abschnittskopf klebt nicht an der Oberkante "
                    + "(Kopf \(Int(headerTop)), Listenoberkante \(Int(listTop)))")
            }
            // (d) Die Knöpfe sind mitgekommen und liegen im stehenden Kopf.
            let button = discardNow.convert(discardNow.bounds, to: contentNow)
            guard button.width > 0, button.height > 0,
                  button.midY >= after.minY - 1, button.midY <= after.maxY + 1 else {
                cleanUp()
                finish(false, "Der Verwerfen-Knopf sitzt nicht im stehenden Kopf "
                    + "(Knopf \(Int(button.minY))–\(Int(button.maxY)), "
                    + "Kopf \(Int(after.minY))–\(Int(after.maxY)))")
            }
            // (e) Auch der letzte Knopf ist vollständig sichtbar. In einer
            // schmalen Seitenleiste schnitt der Titel ihn vorher ab, weil er
            // auf seiner Idealbreite bestand.
            guard let stageNow = markerView(id: "gitHeaderStageAll",
                                            in: contentNow) else {
                cleanUp()
                finish(false, "Der Bereitstellen-Knopf fehlt im Kopf")
            }
            let stageFrame = stageNow.convert(stageNow.bounds, to: contentNow)
            guard stageFrame.width > 0,
                  stageFrame.maxX <= viewport.maxX + 1 else {
                cleanUp()
                finish(false, "Der letzte Kopf-Knopf ist abgeschnitten "
                    + "(Knopf endet bei \(Int(stageFrame.maxX)), Seitenleiste "
                    + "bei \(Int(viewport.maxX)))")
            }
            cleanUp()
            finish(true, "60 Änderungen, Liste um \(Int(scrolled)) pt gescrollt: "
                + "der Abschnittskopf bleibt an der Listenoberkante stehen "
                + "(y=\(Int(after.minY)) vor und nach dem Scrollen) und die "
                + "Sammel-Knöpfe sitzen weiter darin")
        }
    }

    /// Mehrfachauswahl über echte Zeilenklicks prüfen: Klick auf die M-Zeile,
    /// Shift-Klick bis zur letzten Zeile, Cmd-Klick zum Abwählen der unversionierten
    /// Datei. Verwerfen über den Hover-Knopf soll nur die zwei gewählten
    /// versionierten Dateien zurücksetzen.
    private static func runGitMultiDiscardTest() {
        testLabel = "gitmultidiscard"
        guard ProcessInfo.processInfo.environment["FASTRA_SIDEBAR"] == "changes" else {
            finish(false, "Launch-Fixture FASTRA_SIDEBAR=changes fehlt")
        }
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        guard GitRunner.isAvailable else {
            finish(.skip, "git nicht verfügbar — Git-Ansicht bleibt erwartungsgemäß verborgen")
        }
        ws.gitInteraction.presentsDialogs = false
        // Der erste Klick soll ausdrücklich von flach nach Baum wechseln.
        workspaceDefaults().set(GitChangesLayoutMode.flat.rawValue, forKey: "git.changesLayout")

        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-gitmultidiscard-\(UUID().uuidString)")
        let repo = base.appendingPathComponent("working-copy")
        do {
            try fm.createDirectory(at: repo, withIntermediateDirectories: true)
            try fm.createDirectory(at: repo.appendingPathComponent("a-files"),
                                   withIntermediateDirectories: false)
            try "Original A\n".write(to: repo.appendingPathComponent("a-files/a-modified.txt"),
                                     atomically: true, encoding: .utf8)
            try "Original M\n".write(to: repo.appendingPathComponent("m-deleted.txt"),
                                     atomically: true, encoding: .utf8)
        } catch {
            finish(false, "(setup) \(error.localizedDescription)")
        }

        let setup: [[String]] = [
            ["init", "-b", "main"],
            ["config", "user.email", "t@t"],
            ["config", "user.name", "T"],
            ["config", "status.showUntrackedFiles", "normal"],
            ["add", "-A"],
            ["commit", "-m", "init"],
        ]
        runGitSequence(setup, in: repo) { ok, error in
            guard ok else {
                try? fm.removeItem(at: base)
                finish(false, "(setup git) \(error)")
            }
            do {
                // Drei Zustände: geändert (M), gelöscht (D), unversioniert (U).
                // Die Namen sortieren in jeder von git gelieferten Reihenfolge
                // gleich: a… vor m… vor z… — die z-Zeile ist sicher die letzte.
                try "Geändert A\n".write(to: repo.appendingPathComponent("a-files/a-modified.txt"),
                                         atomically: true, encoding: .utf8)
                try fm.removeItem(at: repo.appendingPathComponent("m-deleted.txt"))
                try "Neu Z\n".write(to: repo.appendingPathComponent("z-untracked.txt"),
                                    atomically: true, encoding: .utf8)
            } catch {
                try? fm.removeItem(at: base)
                finish(false, "(working tree setup) \(error.localizedDescription)")
            }
            DispatchQueue.main.async {
                ws.openProject(at: repo)
                pollGitMultiDiscardRows(ws, base: base, repo: repo)
            }
        }
    }

    /// Wartet, bis alle drei ungestageten Zeilen samt Klick-Markern wirklich
    /// im Fenster stehen, und startet dann die Klick-Folge.
    private static func pollGitMultiDiscardRows(_ ws: Workspace, base: URL, repo: URL) {
        let wanted = ["a-files/a-modified.txt", "m-deleted.txt", "z-untracked.txt"]
        var rows: [GitChange] = []
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    let unstaged = ws.gitStatus?.unstagedChanges ?? []
                    rows = wanted.compactMap { name in
                        unstaged.first(where: { $0.path == name })
                    }
                    let content = mainWindowForAXChecks()?.contentView
                    return rows.count == wanted.count && content.map { view in
                        rows.allSatisfy {
                            markerView(id: "gitChangeRow-unstaged-\($0.rawPath.hashValue)",
                                       in: view) != nil
                        } && markerView(id: "gitDiscardAction-\(rows[0].rawPath.hashValue)",
                                        in: view) != nil
                    } == true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    let shown = ws.gitStatus?.unstagedChanges.map(\.path) ?? []
                    finish(false, "Änderungszeilen oder Marker fehlen im Fenster "
                        + "(sichtbar: \(shown)) — \(book.summary)")
                },
                then: {
                    runGitLayoutToggleCheck(
                        ws, base: base, repo: repo,
                        deletedHash: rows[1].rawPath.hashValue,
                        rowHashes: (first: rows[0].rawPath.hashValue,
                                    last: rows[2].rawPath.hashValue)
                    )
                })
    }

    /// Der echte Kopfknopf muss flach → Baum → flach umschalten und dabei
    /// ausschließlich die isolierte Selbsttest-Einstellung verändern.
    private static func runGitLayoutToggleCheck(
        _ ws: Workspace, base: URL, repo: URL, deletedHash: Int,
        rowHashes: (first: Int, last: Int)
    ) {
        guard let window = mainWindowForAXChecks(), let content = window.contentView,
              let marker = markerView(id: "gitChangesLayoutToggle", in: content) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Umschalter für flache/Baum-Ansicht fehlt")
        }
        window.layoutIfNeeded()
        let point = marker.convert(
            NSPoint(x: marker.bounds.midX, y: marker.bounds.midY), to: nil)
        guard sendMouseClick(at: point, in: window, modifiers: [], viaApp: true) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Umschalter zur Baumansicht nicht klickbar")
        }
        pollGitLayoutToggle(ws, base: base, repo: repo,
                            deletedHash: deletedHash, rowHashes: rowHashes,
                            expected: .tree)
    }

    private static func pollGitLayoutToggle(
        _ ws: Workspace, base: URL, repo: URL, deletedHash: Int,
        rowHashes: (first: Int, last: Int),
        expected: GitChangesLayoutMode, treeFolderOpened: Bool = false
    ) {
        // SwiftUI behält die alte flache Zeile verborgen im Ansichtsbaum.
        // Deshalb alle passenden Marker durchsuchen und nur sichtbare zählen.
        func visibleMarker(id: String, in view: NSView) -> NSView? {
            guard !view.isHiddenOrHasHiddenAncestor else { return nil }
            if view.accessibilityIdentifier() == id && !view.visibleRect.isEmpty { return view }
            for child in view.subviews {
                if let found = visibleMarker(id: id, in: child) { return found }
            }
            return nil
        }
        var raw: String?
        var folder: NSView?
        var child: NSView?
        waitFor(budget: 3, pause: 0.05,
                condition: {
                    raw = workspaceDefaults().string(forKey: "git.changesLayout")
                    let content = mainWindowForAXChecks()?.contentView
                    folder = content.flatMap { visibleMarker(id: "gitChangeFolder-unstaged-a-files", in: $0) }
                    child = content.flatMap {
                        visibleMarker(id: "gitChangeRow-unstaged-\(rowHashes.first)", in: $0)
                    }
                    let hierarchyMatches = expected == .tree
                        ? folder != nil && (child != nil) == treeFolderOpened
                        : folder == nil && child != nil
                    return raw == expected.rawValue && hierarchyMatches
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Ansicht „\(expected.rawValue)“ nicht vollständig angekommen "
                        + "(Einstellung=\(raw ?? "nil"), Ordner=\(folder != nil), "
                        + "Dateizeile=\(child != nil), aufgeklappt erwartet=\(treeFolderOpened), "
                        + "Dateizeile verborgen=\(child?.isHiddenOrHasHiddenAncestor.description ?? "nil"), "
                        + "Dateizeile frame=\(child.map { NSStringFromRect($0.frame) } ?? "nil"), "
                        + "Dateizeile sichtbar=\(child.map { NSStringFromRect($0.visibleRect) } ?? "nil")) "
                        + "— \(book.summary)")
                },
                then: {
                    guard expected == .tree else {
                        runGitDeletedPreviewCheck(ws, base: base, repo: repo,
                                                  deletedHash: deletedHash,
                                                  rowHashes: rowHashes)
                        return
                    }
                    guard let window = mainWindowForAXChecks(),
                          let content = window.contentView,
                          let marker = markerView(id: "gitChangesLayoutToggle", in: content) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Umschalter verschwand in der Baumansicht")
                    }
                    if !treeFolderOpened {
                        guard let folder else { finish(false, "Baumordner verschwand vor dem Klick") }
                        let point = folder.convert(
                            NSPoint(x: folder.bounds.midX, y: folder.bounds.midY), to: nil)
                        guard sendMouseClick(at: point, in: window, modifiers: [], viaApp: true) else {
                            finish(false, "Ordner der Baumansicht nicht klickbar")
                        }
                        pollGitLayoutToggle(ws, base: base, repo: repo,
                                            deletedHash: deletedHash, rowHashes: rowHashes,
                                            expected: .tree, treeFolderOpened: true)
                        return
                    }
                    window.layoutIfNeeded()
                    let point = marker.convert(
                        NSPoint(x: marker.bounds.midX, y: marker.bounds.midY), to: nil)
                    guard sendMouseClick(at: point, in: window,
                                         modifiers: [], viaApp: true) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Rückschalten zur flachen Ansicht nicht klickbar")
                    }
                    pollGitLayoutToggle(ws, base: base, repo: repo,
                                        deletedHash: deletedHash, rowHashes: rowHashes,
                                        expected: .flat)
                })
    }

    /// Vor der Mehrfachauswahl prüft derselbe echte Fensterlauf den gemeldeten
    /// Löschfall: Ein Doppelklick darf nicht piepen, sondern muss die
    /// Index-Fassung als auswählbaren read-only Tab laden — dauerhaft, und
    /// anstelle der Diff-Vorschau, die sein erster Klick angelegt hat.
    private static func runGitDeletedPreviewCheck(
        _ ws: Workspace, base: URL, repo: URL, deletedHash: Int,
        rowHashes: (first: Int, last: Int)
    ) {
        guard let window = mainWindowForAXChecks(), let content = window.contentView,
              let marker = markerView(id: "gitChangeRow-unstaged-\(deletedHash)",
                                      in: content) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Gelöschte Dateizeile fehlt für die read-only Prüfung")
        }
        window.layoutIfNeeded()
        let point = marker.convert(
            NSPoint(x: marker.bounds.midX, y: marker.bounds.midY), to: nil)
        // Ein echter Doppelklick besteht aus zwei Klickpaaren; das zweite
        // trägt clickCount 2. Der erste öffnet die Diff-Vorschau, der zweite
        // ersetzt sie durch die Datei.
        guard sendMouseClick(at: point, in: window, modifiers: [], viaApp: true),
              sendMouseClick(at: point, in: window, modifiers: [], viaApp: true,
                             clickCount: 2) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Doppelklick auf die gelöschte Dateizeile nicht erzeugbar")
        }
        pollGitDeletedPreview(ws, base: base, repo: repo,
                              rowHashes: rowHashes)
    }

    private static func pollGitDeletedPreview(
        _ ws: Workspace, base: URL, repo: URL,
        rowHashes: (first: Int, last: Int)
    ) {
        var tab: EditorTab?
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    let editorVisible = mainWindowForAXChecks()?.contentView.map {
                        markerView(id: "gitDeletedReadOnlyEditor", in: $0) != nil
                    } == true
                    guard let candidate = ws.activeTab, !candidate.isLoading,
                          candidate.gitSnapshotRequest?.path == "m-deleted.txt", editorVisible else {
                        return false
                    }
                    tab = candidate
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Read-only Editor der gelöschten Datei erschien nicht — \(book.summary)")
                },
                then: {
                    guard let tab, tab.content == "Original M\n", !tab.isPreview,
                          tab.readOnlyReason != nil else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Gelöschte Datei wurde nicht als dauerhafter read-only Tab geladen")
                    }
                    guard !ws.tabs.contains(where: {
                        $0.gitDiffRequest?.source.changeListPath == "m-deleted.txt"
                    }) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Die Diff-Vorschau des ersten Klicks blieb neben dem read-only Tab stehen")
                    }
                    performGitMultiDiscardClicks(ws, base: base, repo: repo,
                                                 rowHashes: rowHashes, step: 0)
                })
    }

    /// Führt die vier Klicks nacheinander aus. Nach jedem Auswahl-Klick
    /// wartet der Test über den `gitChangesSelCount`-Marker auf die erwartete
    /// Auswahlgröße. Jeder Marker wird vor seinem Klick frisch aufgelöst,
    /// weil SwiftUI die Zeilen nach jeder Auswahl-Änderung neu rendert.
    private static func performGitMultiDiscardClicks(
        _ ws: Workspace, base: URL, repo: URL,
        rowHashes: (first: Int, last: Int), step: Int
    ) {
        // Erwartete Auswahlgrößen: Klick auf M → 1; Shift-Klick auf die
        // letzte Zeile → Bereich aus 3; Cmd-Klick auf die U-Zeile → 2.
        let steps: [(markerID: String, flags: NSEvent.ModifierFlags,
                     expectedCount: Int?, name: String)] = [
            ("gitChangeRow-unstaged-\(rowHashes.first)", [], 1,
             "Klick auf die M-Zeile"),
            ("gitChangeRow-unstaged-\(rowHashes.last)", [.shift], 3,
             "Shift-Klick auf die U-Zeile"),
            ("gitChangeRow-unstaged-\(rowHashes.last)", [.command], 2,
             "Cmd-Klick auf die U-Zeile"),
            ("gitDiscardAction-\(rowHashes.first)", [], nil,
             "Klick auf Verwerfen"),
        ]
        guard step < steps.count else {
            pollGitMultiDiscardResult(base: base, repo: repo)
            return
        }
        guard let window = mainWindowForAXChecks(),
              let content = window.contentView else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Hauptfenster verschwand während der Klick-Folge")
        }
        let current = steps[step]
        guard let marker = markerView(id: current.markerID, in: content) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Marker \(current.markerID) fehlt vor: \(current.name)")
        }
        window.layoutIfNeeded()
        guard marker.bounds.width > 0, marker.bounds.height > 0 else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Marker ohne klickbare Fläche vor: \(current.name)")
        }
        // Zeilenmitte treffen — die im Test dauerhaft eingeblendeten
        // Hover-Knöpfe überlagern nur das rechte Zeilenende.
        let local = NSPoint(x: marker.bounds.midX, y: marker.bounds.midY)
        let point = marker.convert(local, to: nil)
        // Diagnose: Welche AppKit-View nimmt den Klick an dieser Stelle an?
        if let superview = content.superview {
            let hit = content.hitTest(superview.convert(point, from: nil))
            var chain: [String] = []
            var view: NSView? = hit
            while let v = view, chain.count < 4 {
                chain.append(String(describing: type(of: v)))
                view = v.superview
            }
            lastHitTestChain = chain.joined(separator: " < ")
        }
        guard sendMouseClick(at: point, in: window, modifiers: current.flags,
                             viaApp: true) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "\(current.name) nicht erzeugbar")
        }
        guard let expected = current.expectedCount else {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                performGitMultiDiscardClicks(ws, base: base, repo: repo,
                                             rowHashes: rowHashes, step: step + 1)
            }
            return
        }
        pollGitMultiDiscardSelection(ws, base: base, repo: repo,
                                     rowHashes: rowHashes, step: step,
                                     expected: expected, name: current.name)
    }

    /// Wartet nach einem Auswahl-Klick auf die erwartete Auswahlgröße und
    /// meldet bei Timeout präzise, welcher Klick nicht ankam und welcher
    /// Zählerstand stattdessen sichtbar ist.
    private static func pollGitMultiDiscardSelection(
        _ ws: Workspace, base: URL, repo: URL,
        rowHashes: (first: Int, last: Int), step: Int,
        expected: Int, name: String
    ) {
        waitFor(budget: 3, pause: 0.05,
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    return content.map {
                        markerView(id: "gitChangesSelCount-\(expected)", in: $0) != nil
                    } == true
                },
                onTimeout: { book in
                    // Zur Diagnose den tatsächlich sichtbaren Zählerstand suchen.
                    let content = mainWindowForAXChecks()?.contentView
                    let actual = content.flatMap { view in
                        (0...8).first(where: {
                            markerView(id: "gitChangesSelCount-\($0)", in: view) != nil
                        })
                    }
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "\(name) kam nicht in der Auswahl an "
                        + "(erwartet \(expected), sichtbar \(actual.map(String.init) ?? "kein Marker"), "
                        + "HitTest: \(lastHitTestChain)) — \(book.summary)")
                },
                then: {
                    performGitMultiDiscardClicks(ws, base: base, repo: repo,
                                                 rowHashes: rowHashes, step: step + 1)
                })
    }

    /// Erwartung nach dem Sammel-Verwerfen: beide getrackten Dateien stehen
    /// wieder auf dem Commit-Stand, die per Cmd-Klick abgewählte untracked
    /// Datei existiert weiter — und git meldet als einzigen Eintrag
    /// `?? z-untracked.txt`.
    private static func pollGitMultiDiscardResult(base: URL, repo: URL) {
        let fm = FileManager.default
        let aURL = repo.appendingPathComponent("a-files/a-modified.txt")
        let mURL = repo.appendingPathComponent("m-deleted.txt")
        let zURL = repo.appendingPathComponent("z-untracked.txt")
        var entries: [String] = []
        var aContent = ""
        waitForAsync(
            budget: 7, pause: 0.05,
            check: { answer in
                guard fm.fileExists(atPath: zURL.path) else {
                    try? fm.removeItem(at: base)
                    finish(false, "Cmd-Klick nahm die untracked Datei nicht aus der "
                        + "Auswahl — das Sammel-Verwerfen hat sie mitgelöscht")
                }
                GitRunner.run(["status", "--porcelain", "-z"], in: repo) { result in
                    entries = result?.stdoutData.split(separator: 0).map {
                        String(decoding: $0, as: UTF8.self)
                    } ?? []
                    aContent = (try? String(contentsOf: aURL, encoding: .utf8)) ?? ""
                    answer(result?.ok == true
                        && entries == ["?? z-untracked.txt"]
                        && aContent == "Original A\n"
                        && fm.fileExists(atPath: mURL.path))
                }
            },
            onTimeout: { book in
                try? fm.removeItem(at: base)
                finish(false, "Sammel-Verwerfen unvollständig (Status: \(entries), "
                    + "a-modified: \(aContent.debugDescription)) — \(book.summary)")
            },
            then: {
                DispatchQueue.main.async {
                    runGitMultiDiscardDoubleClick(base: base, repo: repo)
                }
            }
        )
    }

    /// Nachspiel zum Klickpfad-Umbau (Zeilen-Button statt Tap-Gesten): Der
    /// Einzelklick aus Schritt 1 muss den Diff der M-Datei als Vorschau
    /// geöffnet haben. Der Doppelklick auf die verbliebene z-Zeile ersetzt
    /// diese Vorschau (erst durch den z-Diff, dann durch die Datei) und
    /// steckt genau den neuen Datei-Tab dauerhaft fest.
    private static func runGitMultiDiscardDoubleClick(base: URL, repo: URL) {
        guard let ws = Workspace.shared, let window = mainWindowForAXChecks(),
              let content = window.contentView else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Fenster für die Doppelklick-Prüfung verschwunden")
        }
        guard ws.tabs.contains(where: {
            $0.gitDiffRequest?.source.changeListPath == "a-files/a-modified.txt"
                && $0.isPreview
        }) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Der Einzelklick auf die M-Zeile öffnete keine Diff-Vorschau")
        }
        guard let zChange = ws.gitStatus?.unstagedChanges.first(where: {
            $0.path == "z-untracked.txt"
        }), let marker = markerView(
            id: "gitChangeRow-unstaged-\(zChange.rawPath.hashValue)", in: content
        ) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "z-Zeile fehlt für die Doppelklick-Prüfung")
        }
        window.layoutIfNeeded()
        let point = marker.convert(
            NSPoint(x: marker.bounds.midX, y: marker.bounds.midY), to: nil)
        // Ein echter Doppelklick besteht aus zwei Klickpaaren; das zweite
        // trägt clickCount 2.
        guard sendMouseClick(at: point, in: window, modifiers: [], viaApp: true),
              sendMouseClick(at: point, in: window, modifiers: [], viaApp: true,
                             clickCount: 2) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Doppelklick nicht erzeugbar")
        }
        pollGitMultiDiscardPinnedTab(ws, base: base, repo: repo)
    }

    private static func pollGitMultiDiscardPinnedTab(_ ws: Workspace, base: URL, repo: URL) {
        let zURL = repo.appendingPathComponent("z-untracked.txt")
        var zTab: EditorTab?
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    let zTabs = ws.tabs.filter {
                        $0.url?.standardizedFileURL == zURL.standardizedFileURL
                    }
                    guard zTabs.count == 1, zTabs[0].isLoading == false else { return false }
                    zTab = zTabs[0]
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Der Doppelklick öffnete keinen dauerhaften Datei-Tab — \(book.summary)")
                },
                then: {
                    guard let zTab, zTab.isPreview == false else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Der Doppelklick ließ den Datei-Tab nur als Vorschau offen")
                    }
                    // Der erste Klick des Doppelklicks öffnete den z-Diff als
                    // Vorschau; die Datei muss genau diesen Platz übernommen haben.
                    guard !ws.tabs.contains(where: {
                        $0.gitDiffRequest?.source.changeListPath == "z-untracked.txt"
                    }) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Die Diff-Vorschau des ersten Klicks blieb neben dem Datei-Tab stehen")
                    }
                    guard !ws.tabs.contains(where: {
                        $0.gitDiffRequest?.source.changeListPath == "a-files/a-modified.txt"
                    }) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Die neue Vorschau ersetzte die vorherige Diff-Vorschau nicht")
                    }
                    runGitMultiDiscardHeaderPhase(ws, base: base, repo: repo)
                })
    }

    /// Kopf-Aktionen der ÄNDERUNGEN-Sektion:
    /// Der Diff-Knopf öffnet den Gesamt-Diff-Tab (`git diff HEAD`), der
    /// Verwerfen-Knopf verwirft die komplette Sektion — hier die letzte
    /// verbliebene untracked Datei.
    private static func runGitMultiDiscardHeaderPhase(_ ws: Workspace,
                                                      base: URL, repo: URL) {
        guard let window = mainWindowForAXChecks(),
              let content = window.contentView,
              let marker = markerView(id: "gitHeaderOpenDiff", in: content) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Kopf-Knopf für den Gesamt-Diff fehlt")
        }
        window.layoutIfNeeded()
        let point = marker.convert(NSPoint(x: marker.bounds.midX,
                                           y: marker.bounds.midY), to: nil)
        guard sendMouseClick(at: point, in: window, modifiers: [], viaApp: true) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Klick auf den Gesamt-Diff-Knopf nicht erzeugbar")
        }
        pollGitMultiDiscardOverallDiff(ws, base: base, repo: repo)
    }

    private static func pollGitMultiDiscardOverallDiff(_ ws: Workspace, base: URL, repo: URL) {
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    ws.tabs.contains { $0.gitDiffRequest?.source == .workingTree(path: nil) }
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Der Gesamt-Diff-Tab erschien nicht — \(book.summary)")
                },
                then: {
                    runGitMultiDiscardHeaderDiscard(base: base, repo: repo)
                })
    }

    /// Letzter Schritt: „Alle Änderungen verwerfen“ im Abschnitts-Kopf muss
    /// die verbliebene untracked Datei löschen und das Repo sauber hinterlassen.
    private static func runGitMultiDiscardHeaderDiscard(base: URL, repo: URL) {
        guard let window = mainWindowForAXChecks(),
              let content = window.contentView,
              let marker = markerView(id: "gitHeaderDiscardAll", in: content) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Kopf-Knopf „Alle Änderungen verwerfen“ fehlt")
        }
        window.layoutIfNeeded()
        let point = marker.convert(NSPoint(x: marker.bounds.midX,
                                           y: marker.bounds.midY), to: nil)
        guard sendMouseClick(at: point, in: window, modifiers: [], viaApp: true) else {
            try? FileManager.default.removeItem(at: base)
            finish(false, "Klick auf „Alle Änderungen verwerfen“ nicht erzeugbar")
        }
        pollGitMultiDiscardFinal(base: base, repo: repo)
    }

    private static func pollGitMultiDiscardFinal(base: URL, repo: URL) {
        var entries: [String] = []
        waitForAsync(
            budget: 7, pause: 0.05,
            check: { answer in
                GitRunner.run(["status", "--porcelain", "-z"], in: repo) { result in
                    entries = result?.stdoutData.split(separator: 0).map {
                        String(decoding: $0, as: UTF8.self)
                    } ?? []
                    answer(result?.ok == true && entries.isEmpty)
                }
            },
            onTimeout: { book in
                try? FileManager.default.removeItem(at: base)
                finish(false, "„Alle Änderungen verwerfen“ räumte nicht auf "
                    + "(Status: \(entries)) — \(book.summary)")
            },
            then: {
                try? FileManager.default.removeItem(at: base)
                finish(true, "Klick + Shift-Klick markieren den Bereich, Cmd-Klick "
                    + "nimmt die untracked Zeile heraus, Verwerfen setzt genau die "
                    + "zwei getrackten Dateien in einem Zug zurück; Einzelklick "
                    + "zeigt den Diff als Vorschau, Doppelklick öffnet die Datei an "
                    + "dessen Platz; die Kopf-Knöpfe öffnen den Gesamt-Diff und "
                    + "verwerfen den Rest der Sektion")
            }
        )
    }

    /// Reproduziert zwei echte Pushs eines sauberen Projekts. `primary` und
    /// `github` müssen als getrennte klickbare Flächen erscheinen. Beide Pushs
    /// lassen den Branch bewusst ohne Upstream.
    private static func runGitPushButtonTest() {
        testLabel = "gitpushbutton"
        guard ProcessInfo.processInfo.environment["FASTRA_SIDEBAR"] == "changes" else {
            finish(false, "Launch-Fixture FASTRA_SIDEBAR=changes fehlt")
        }
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        guard GitRunner.isAvailable else {
            finish(.skip, "git nicht verfügbar — Git-Ansicht bleibt erwartungsgemäß verborgen")
        }
        ws.gitInteraction.presentsDialogs = false

        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-gitpushbutton-\(UUID().uuidString)")
        let repo = base.appendingPathComponent("working-copy")
        let primary = base.appendingPathComponent("primary.git")
        let github = base.appendingPathComponent("github.git")
        gitPushButtonExpectedSourcePrefix = ""
        gitPushButtonConfirmedRemotes = []
        // Der Fenstertest klickt beide echten Push-Flächen. Die Vorschau wird
        // nicht umgangen, sondern je Remote gegen Name und Adresse geprüft.
        ws.gitMutationConfirmationHandler = { confirmation in
            let candidates = [("primary", primary.path), ("github", github.path)]
            for (remote, address) in candidates {
                let expected = L10n.format(
                    "Remote: %@\nAdresse: %@\nZiel: %@\nQuell-Commit: %@",
                    remote, address, "refs/heads/main",
                    gitPushButtonExpectedSourcePrefix
                )
                if !gitPushButtonExpectedSourcePrefix.isEmpty,
                   confirmation.explanation.contains(expected) {
                    gitPushButtonConfirmedRemotes.insert(remote)
                    return true
                }
            }
            return false
        }
        do {
            try fm.createDirectory(at: repo, withIntermediateDirectories: true)
            try fm.createDirectory(at: primary, withIntermediateDirectories: true)
            try fm.createDirectory(at: github, withIntermediateDirectories: true)
            try "Basis\n".write(to: repo.appendingPathComponent("README.md"),
                                atomically: true, encoding: .utf8)
        } catch {
            finish(false, "(setup) \(error.localizedDescription)")
        }

        runGitSequence([["init", "--bare", "-b", "main"]], in: primary) {
            primaryOK, primaryError in
            guard primaryOK else {
                try? fm.removeItem(at: base)
                finish(false, "(primary setup) \(primaryError)")
            }
            runGitSequence([["init", "--bare", "-b", "main"]], in: github) {
                githubOK, githubError in
                guard githubOK else {
                    try? fm.removeItem(at: base)
                    finish(false, "(github setup) \(githubError)")
                }
                let setup: [[String]] = [
                    ["init", "-b", "main"],
                    ["config", "user.email", "t@t"],
                    ["config", "user.name", "T"],
                    ["add", "--", "README.md"],
                    ["commit", "-m", "lokaler Commit"],
                    // Reihenfolge ist die Sicherheitsbehauptung des Tests.
                    ["remote", "add", "primary", primary.path],
                    ["remote", "add", "github", github.path],
                ]
                runGitSequence(setup, in: repo) { ok, error in
                    guard ok else {
                        try? fm.removeItem(at: base)
                        finish(false, "(repo setup) \(error)")
                    }
                    GitRunner.run(["rev-parse", "HEAD"], in: repo) { result in
                        DispatchQueue.main.async {
                            guard let sourceOID = result?.stdout
                                .trimmingCharacters(in: .whitespacesAndNewlines),
                                  result?.ok == true,
                                  sourceOID.count >= 12 else {
                                try? fm.removeItem(at: base)
                                finish(false, "(repo setup) Quell-Commit fehlt")
                            }
                            gitPushButtonExpectedSourcePrefix = String(sourceOID.prefix(12))
                            ws.openProject(at: repo)
                            pollGitPushButton(ws, base: base, repo: repo,
                                              primary: primary, github: github)
                        }
                    }
                }
            }
        }
    }

    /// Wartet auf beide gerenderten Sicherheitsflächen und klickt zuerst
    /// `primary` über AppKits echtes Fenster-Hit-Testing.
    private static func pollGitPushButton(_ ws: Workspace, base: URL, repo: URL,
                                          primary: URL, github: URL) {
        let expectedPrimary = GitPushTarget(remote: "primary",
                                            addresses: [primary.path])
        let expectedGithub = GitPushTarget(remote: "github",
                                           addresses: [github.path])
        let expected = [expectedPrimary, expectedGithub]
        let primaryAddressID = "gitPrimaryPushAddress-primary-"
            + "\(expectedPrimary.displayAddress.hashValue)"
        let githubAddressID = "gitPrimaryPushAddress-github-"
            + "\(expectedGithub.displayAddress.hashValue)"
        // Zwei Stufen in einer Frist: erst beide Flächen samt Adressen, dann
        // das Key-Fenster für den Klick.
        var stage = 0
        var found: (window: NSWindow, button: NSView)?
        waitFor(budget: 6, pause: 0.05,
                condition: {
                    guard ws.gitPushTargets == expected,
                          GitChangesPrimaryAction.resolve(status: ws.gitStatus,
                                                          targets: ws.gitPushTargets)
                            == .push(expected),
                          !ws.gitOperationsAreBusy,
                          let window = mainWindowForAXChecks(),
                          let content = window.contentView,
                          let primaryButton = markerView(id: "gitPrimaryPush-primary",
                                                         in: content),
                          let githubButton = markerView(id: "gitPrimaryPush-github",
                                                        in: content),
                          let primaryAddress = markerView(id: primaryAddressID, in: content),
                          let githubAddress = markerView(id: githubAddressID, in: content) else {
                        stage = 0
                        return false
                    }
                    window.layoutIfNeeded()
                    guard primaryButton.bounds.width > 0, primaryButton.bounds.height > 0,
                          githubButton.bounds.width > 0, githubButton.bounds.height > 0,
                          primaryAddress.bounds.width > 0, primaryAddress.bounds.height > 0,
                          githubAddress.bounds.width > 0, githubAddress.bounds.height > 0 else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Push-Fläche oder Zieladresse besitzt keinen sichtbaren Bereich")
                    }
                    let primaryFrame = primaryButton.convert(primaryButton.bounds, to: content)
                    let githubFrame = githubButton.convert(githubButton.bounds, to: content)
                    guard abs(primaryFrame.midY - githubFrame.midY) <= 2,
                          primaryFrame.maxX <= githubFrame.minX + 1 else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Push-Flächen für primary und github liegen nicht nebeneinander")
                    }
                    stage = 1
                    activateApplication(ignoringOtherApps: true)
                    window.makeKeyAndOrderFront(nil)
                    guard window.isKeyWindow else { return false }
                    found = (window, primaryButton)
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    if stage == 0 {
                        finish(false, "Getrennte Push-Flächen mit sichtbaren Adressen "
                            + "erschienen nicht (Ziele: \(ws.gitPushTargets), Status: "
                            + "\(String(describing: ws.gitStatus))) — \(book.summary)")
                    }
                    finish(false, "Dokumentfenster wurde für den primary-Push nicht Key — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Push-Fläche nach Erfolg verschwunden") }
                    let (window, primaryButton) = found
                    let point = primaryButton.convert(
                        NSPoint(x: primaryButton.bounds.midX, y: primaryButton.bounds.midY),
                        to: nil
                    )
                    guard sendMouseClick(at: point, in: window, modifiers: []) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Mausklick auf Push zu primary nicht erzeugbar")
                    }
                    pollGitPushPhaseIndicator(ws, base: base, repo: repo,
                                              primary: primary, github: github)
                })
    }

    /// Nach dem Klick muss die Karte ihre Phase sichtbar machen: erst der
    /// Kreis-Indikator (`running`), nach dem Abschluss zwei Sekunden das
    /// Häkchen (`succeeded`). Der Test akzeptiert beide Marker, weil ein
    /// schneller lokaler Push den `running`-Zustand überholen kann.
    private static func pollGitPushPhaseIndicator(
        _ ws: Workspace, base: URL, repo: URL, primary: URL, github: URL
    ) {
        waitFor(budget: 6, pause: 0.05,
                condition: {
                    let content = mainWindowForAXChecks()?.contentView
                    return content.map {
                        markerView(id: "gitPushPhase-primary-running", in: $0) != nil
                            || markerView(id: "gitPushPhase-primary-succeeded", in: $0) != nil
                    } ?? false
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Push-Karte zeigte nach dem Klick weder Kreis-"
                        + "Indikator noch Erfolgs-Häkchen (gitPushPhase-primary-*) — \(book.summary)")
                },
                then: {
                    pollGitPrimaryPushResult(ws, base: base, repo: repo,
                                             primary: primary, github: github)
                })
    }

    /// Nach dem ersten Klick muss ausschließlich `primary` den Branch besitzen;
    /// die Upstream-Konfiguration bleibt leer. Danach folgt der github-Klick.
    private static func pollGitPrimaryPushResult(
        _ ws: Workspace, base: URL, repo: URL, primary: URL, github: URL
    ) {
        var primaryOK = false
        var githubAbsent = false
        var remoteConfig: GitResult?
        var mergeConfig: GitResult?
        waitForAsync(
            budget: 7.5, pause: 0.05,
            check: { answer in
                GitRunner.run(["rev-parse", "--verify", "refs/heads/main"], in: primary) {
                    primaryResult in
                    GitRunner.run(
                        ["show-ref", "--verify", "--quiet", "refs/heads/main"], in: github
                    ) { githubResult in
                        readGitUpstreamConfig(in: repo) {
                            remote, merge in
                            DispatchQueue.main.async {
                                if githubResult?.ok == true {
                                    try? FileManager.default.removeItem(at: base)
                                    finish(false, "Push traf den nicht ausgewählten Remote github")
                                }
                                primaryOK = primaryResult?.ok == true
                                githubAbsent = gitRefIsAbsent(githubResult)
                                remoteConfig = remote
                                mergeConfig = merge
                                answer(primaryOK
                                    && gitConfigValueIsAbsent(remote)
                                    && gitConfigValueIsAbsent(merge)
                                    && githubAbsent)
                            }
                        }
                    }
                }
            },
            onTimeout: { book in
                try? FileManager.default.removeItem(at: base)
                finish(false, "Push zu primary nicht vollständig "
                    + "(primary: \(primaryOK), "
                    + "github unberührt: \(githubAbsent), "
                    + "remote-config: \(String(describing: remoteConfig)), "
                    + "merge-config: \(String(describing: mergeConfig))) — \(book.summary)")
            },
            then: {
                pollGitSecondPushButton(ws, base: base, repo: repo, primary: primary,
                                        github: github)
            }
        )
    }

    private static func pollGitSecondPushButton(
        _ ws: Workspace, base: URL, repo: URL, primary: URL, github: URL
    ) {
        let expected = [
            GitPushTarget(remote: "primary", addresses: [primary.path]),
            GitPushTarget(remote: "github", addresses: [github.path]),
        ]
        // Die Fläche muss über drei Durchläufe dieselbe View bleiben — erst
        // dann gilt sie als stabil klickbereit.
        var previousMarker: NSView?
        var stableTicks = 0
        var found: (window: NSWindow, marker: NSView)?
        var diagnosis = ""
        waitFor(budget: 6, pause: 0.05,
                condition: {
                    let window = mainWindowForAXChecks()
                    let content = window?.contentView
                    let marker = content.flatMap {
                        markerView(id: "gitPrimaryPush-github", in: $0)
                    }
                    if let window, !window.isKeyWindow {
                        activateApplication(ignoringOtherApps: true)
                        window.makeKeyAndOrderFront(nil)
                    }
                    let ready = !ws.gitOperationsAreBusy
                        && ws.gitPushTargets == expected
                        && window?.isKeyWindow == true
                        && marker != nil
                    stableTicks = ready && marker === previousMarker ? stableTicks + 1 : 0
                    previousMarker = marker
                    diagnosis = "busy=\(ws.gitOperationsAreBusy), "
                        + "Ziele=\(ws.gitPushTargets), Key=\(window?.isKeyWindow == true), "
                        + "Marker=\(marker != nil), stabil=\(stableTicks)"
                    guard ready, stableTicks >= 3, let window, let marker else { return false }
                    found = (window, marker)
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "github-Push-Fläche wurde nach primary-Push nicht "
                        + "stabil klickbereit (\(diagnosis)) — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "github-Push-Fläche nach Erfolg verschwunden") }
                    let (window, marker) = found
                    window.layoutIfNeeded()
                    guard marker.bounds.width > 0, marker.bounds.height > 0 else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "github-Push-Fläche besitzt keinen sichtbaren Bereich")
                    }
                    let point = marker.convert(
                        NSPoint(x: marker.bounds.midX, y: marker.bounds.midY), to: nil
                    )
                    guard sendMouseClick(at: point, in: window, modifiers: []) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Mausklick auf Push zu github nicht erzeugbar")
                    }
                    pollGitSecondPushResult(ws, base: base, repo: repo,
                                            primary: primary, github: github)
                })
    }

    /// Beide Ziele müssen nun exakt den lokalen HEAD enthalten; auch nach dem
    /// zweiten Push bleibt der Branch bewusst ohne Upstream.
    private static func pollGitSecondPushResult(
        _ ws: Workspace, base: URL, repo: URL, primary: URL, github: URL
    ) {
        var githubOK = false
        var remoteConfig: GitResult?
        var mergeConfig: GitResult?
        waitForAsync(
            budget: 7.5, pause: 0.05,
            check: { answer in
                GitRunner.run(["rev-parse", "HEAD"], in: repo) { localResult in
                    GitRunner.run(["rev-parse", "refs/heads/main"], in: primary) {
                        primaryResult in
                        GitRunner.run(["rev-parse", "refs/heads/main"], in: github) {
                            githubResult in
                            readGitUpstreamConfig(in: repo) {
                                remote, merge in
                                DispatchQueue.main.async {
                                    // Nach dem Ende beider Abläufe (das Häkchen steht
                                    // maximal zwei Sekunden) darf keine Karte mehr
                                    // einen Phasen-Marker tragen — die Anzeige muss
                                    // sich selbst zurücknehmen.
                                    let content = mainWindowForAXChecks()?.contentView
                                    let phasesCleared = content.map { view in
                                        ["primary", "github"].allSatisfy { remote in
                                            markerView(id: "gitPushPhase-\(remote)-running",
                                                       in: view) == nil
                                                && markerView(id: "gitPushPhase-\(remote)-succeeded",
                                                              in: view) == nil
                                        }
                                    } ?? false
                                    githubOK = githubResult?.ok == true
                                    remoteConfig = remote
                                    mergeConfig = merge
                                    answer(localResult?.ok == true
                                        && localResult?.stdout == primaryResult?.stdout
                                        && localResult?.stdout == githubResult?.stdout
                                        && gitConfigValueIsAbsent(remote)
                                        && gitConfigValueIsAbsent(merge)
                                        && phasesCleared
                                        && gitPushButtonConfirmedRemotes == ["primary", "github"])
                                }
                            }
                        }
                    }
                }
            },
            onTimeout: { book in
                try? FileManager.default.removeItem(at: base)
                finish(false, "Push zu github oder Upstream-Schutz "
                    + "unvollständig (github: "
                    + "\(githubOK), remote-config: "
                    + "\(String(describing: remoteConfig)), merge-config: "
                    + "\(String(describing: mergeConfig)), Vorschauen: "
                    + "\(gitPushButtonConfirmedRemotes.sorted())) — \(book.summary)")
            },
            then: {
                try? FileManager.default.removeItem(at: base)
                finish(true, "Zwei getrennte Push-Flächen lagen "
                    + "nebeneinander; echte Klicks pushten nach "
                    + "primary und github mit sichtbarer Phase, "
                    + "der Branch blieb ohne Upstream")
            }
        )
    }

    /// Liest beide Upstream-Schlüssel einzeln. `rev-parse @{u}` genügt hier
    /// nicht: Auch eine nur halb geschriebene Konfiguration lässt die
    /// Auflösung scheitern und sähe fälschlich wie „kein Upstream“ aus.
    private static func readGitUpstreamConfig(
        in repo: URL, branch: String = "main",
        completion: @escaping (GitResult?, GitResult?) -> Void
    ) {
        GitRunner.run(["config", "--get", "branch.\(branch).remote"], in: repo) {
            remoteResult in
            GitRunner.run(["config", "--get", "branch.\(branch).merge"], in: repo) {
                mergeResult in
                completion(remoteResult, mergeResult)
            }
        }
    }

    /// Git meldet einen fehlenden `config --get`-Wert mit Exit 1 und leerer
    /// Ausgabe. Ein Start-/I/O-Fehler oder ein anderer Exit-Code ist kein
    /// Beweis für eine fehlende Konfiguration.
    private static func gitConfigValueIsAbsent(_ result: GitResult?) -> Bool {
        result?.exitCode == 1
            && result?.stdout.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == true
            && result?.stderr.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == true
    }

    /// `git show-ref --verify --quiet` benutzt ausschließlich Exit 1 für
    /// „Ref fehlt“. Ein nicht gestarteter Prozess oder jeder andere Fehler
    /// darf nicht als Beleg für ein unberührtes Remote gelten.
    private static func gitRefIsAbsent(_ result: GitResult?) -> Bool {
        result?.exitCode == 1
            && result?.stdout.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == true
            && result?.stderr.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == true
    }

    /// Fensterlos — kuratierte Git-Aktionen end-to-end über die echten
    /// Workspace-Methoden mit einem lokalen bare-Remote: Push, Pull
    /// (Fast-Forward), Amend, Branch-Wechsel, Pickaxe. Braucht installiertes git.
    private static func runGitActionsTest() {
        testLabel = "gitactions"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        guard GitRunner.isAvailable else {
            finish(.skip, "git nicht verfügbar — Aktionen bleiben still weg (erwartet)")
        }
        // Fehler-Dialoge unterdrücken, damit ein unerwarteter Fehler den Lauf
        // nicht an einem modalen NSAlert aufhängt.
        ws.gitInteraction.presentsDialogs = false

        let fm = FileManager.default
        let base = selfTestTemporaryDirectory().appendingPathComponent("fastra-gitactions-\(UUID().uuidString)")
        let repo = base.appendingPathComponent("work")
        let bare = base.appendingPathComponent("remote.git")
        // Auch der fensterlose Aktionslauf muss die sichtbare Push-Vorschau
        // durchlaufen. Bestätigt wird nur das lokale Test-Remote.
        ws.gitMutationConfirmationHandler = { confirmation in
            confirmation.explanation.contains("origin")
                && confirmation.explanation.contains(bare.path)
        }
        do {
            try fm.createDirectory(at: repo, withIntermediateDirectories: true)
            try fm.createDirectory(at: bare, withIntermediateDirectories: true)
            try "PICKAXE_MARKER\n".write(to: repo.appendingPathComponent("marker.txt"),
                                         atomically: true, encoding: .utf8)
            try "v1\n".write(to: repo.appendingPathComponent("app.txt"),
                             atomically: true, encoding: .utf8)
        } catch { finish(false, "(setup) \(error)") }

        // Setup: bare-Remote initialisieren, Arbeitskopie einrichten + push -u.
        runGitSequence([["init", "--bare", "-b", "main"]], in: bare) { ok0, e0 in
            guard ok0 else { finish(false, "(bare) \(e0)") }
            let setup: [[String]] = [
                ["init", "-b", "main"],
                ["config", "user.email", "t@t"],
                ["config", "user.name", "T"],
                ["add", "-A"],
                ["commit", "-m", "init"],
                ["remote", "add", "origin", bare.path],
                ["push", "-u", "origin", "main"],
            ]
            runGitSequence(setup, in: repo) { ok1, e1 in
                guard ok1 else { finish(false, "(setup) \(e1)") }
                ws.openProject(at: repo)
                gitActionsPush(ws, repo: repo, bare: bare, base: base, fm: fm)
            }
        }
    }

    /// PUSH: neuen Commit lokal anlegen, `gitPush()` aufrufen, warten bis der
    /// bare-Remote 2 Commits hat (Ground Truth statt lokalem Status-Cache —
    /// der Cache-Wert vor der Aktion würde sonst eine Race auslösen).
    private static func gitActionsPush(_ ws: Workspace, repo: URL, bare: URL, base: URL, fm: FileManager) {
        try? "feature\n".write(to: repo.appendingPathComponent("feature.txt"),
                               atomically: true, encoding: .utf8)
        runGitSequence([["add", "-A"], ["commit", "-m", "feature"]], in: repo) { ok, e in
            guard ok else { try? fm.removeItem(at: base); finish(false, "(push-setup) \(e)") }
            ws.gitPush()
            pollAsync(budget: 4.5, base: base, fm: fm, label: "push",
                      check: { done in
                          GitRunner.run(["rev-list", "--count", "main"], in: bare) { r in
                              done(Int(r?.stdout.trimmingCharacters(in: .whitespacesAndNewlines) ?? "") == 2)
                          }
                      },
                      next: { gitActionsPull(ws, repo: repo, bare: bare, base: base, fm: fm) })
        }
    }

    /// PULL (Fast-Forward): über einen zweiten Klon einen Remote-Commit erzeugen,
    /// dann `gitPullFastForward()` im Original — die neue Datei muss auftauchen.
    private static func gitActionsPull(_ ws: Workspace, repo: URL, bare: URL, base: URL, fm: FileManager) {
        let clone = base.appendingPathComponent("clone")
        runGitSequence([["clone", bare.path, clone.path]], in: base) { ok, e in
            guard ok else { try? fm.removeItem(at: base); finish(false, "(clone) \(e)") }
            try? "vom-remote\n".write(to: clone.appendingPathComponent("remote.txt"),
                                      atomically: true, encoding: .utf8)
            let push2: [[String]] = [
                ["config", "user.email", "t@t"], ["config", "user.name", "T"],
                ["add", "-A"], ["commit", "-m", "remote-commit"], ["push"],
            ]
            runGitSequence(push2, in: clone) { ok2, e2 in
                guard ok2 else { try? fm.removeItem(at: base); finish(false, "(push2) \(e2)") }
                gitActionsWhenIdle(ws, base: base, fm: fm, label: "pull-idle") {
                    ws.gitPullFastForward()
                }
                pollUntil(budget: 4.5, base: base, fm: fm, label: "pull",
                          cond: { fm.fileExists(atPath: repo.appendingPathComponent("remote.txt").path) },
                          next: { gitActionsAmend(ws, repo: repo, bare: bare, base: base, fm: fm) })
            }
        }
    }

    /// AMEND: app.txt ändern, `gitAmendNoEdit()` — die Änderung muss in den
    /// letzten Commit wandern (`show HEAD:app.txt` == v2, Commit-Zahl gleich).
    /// Ground Truth via git, um den lokalen Status-Cache-Race zu vermeiden.
    private static func gitActionsAmend(_ ws: Workspace, repo: URL, bare: URL, base: URL, fm: FileManager) {
        GitRunner.run(["rev-list", "--count", "HEAD"], in: repo) { before in
            let countBefore = Int(before?.stdout.trimmingCharacters(in: .whitespacesAndNewlines) ?? "") ?? -1
            try? "v2\n".write(to: repo.appendingPathComponent("app.txt"),
                              atomically: true, encoding: .utf8)
            var sawAmendConfirmation = false
            ws.gitMutationConfirmationHandler = { confirmation in
                let expected = confirmation.title
                        == L10n.string("Letzten Commit wirklich ergänzen?")
                    && confirmation.confirmTitle == L10n.string("Commit ersetzen")
                    && confirmation.isDestructive
                if expected { sawAmendConfirmation = true }
                return expected
            }
            gitActionsWhenIdle(ws, base: base, fm: fm, label: "amend-idle") {
                ws.gitAmendNoEdit()
            }
            pollAsync(budget: 4.5, base: base, fm: fm, label: "amend",
                      check: { done in
                          GitRunner.run(["show", "HEAD:app.txt"], in: repo) { r in
                              done(r?.ok == true && r!.stdout.contains("v2"))
                          }
                      },
                      next: {
                          GitRunner.run(["rev-list", "--count", "HEAD"], in: repo) { after in
                              let countAfter = Int(after?.stdout.trimmingCharacters(in: .whitespacesAndNewlines) ?? "") ?? -2
                              guard sawAmendConfirmation else {
                                  try? fm.removeItem(at: base)
                                  finish(false, "(amend) erwartete destruktive Bestätigung fehlte")
                              }
                              guard countAfter == countBefore else {
                                  try? fm.removeItem(at: base)
                                  finish(false, "(amend) Commit-Zahl \(countBefore) → \(countAfter) (amend darf nicht erhöhen)")
                              }
                              gitActionsSwitch(ws, repo: repo, bare: bare, base: base, fm: fm)
                          }
                      })
        }
    }

    /// SWITCH: neuen Branch anlegen, Liste neu laden und über die neue explizite
    /// Branch-Auswahl zurück auf main wechseln. Prüft zugleich Erfolgs-Feedback.
    private static func gitActionsSwitch(_ ws: Workspace, repo: URL, bare: URL, base: URL, fm: FileManager) {
        runGitSequence([["switch", "-c", "feature"]], in: repo) { ok, e in
            guard ok else { try? fm.removeItem(at: base); finish(false, "(switch-setup) \(e)") }
            ws.refreshGitBranches()
            // Ein vollständiger Fenstertestlauf kann den gemeinsam revidierten
            // Git-Snapshot unter Last später liefern. Nur der Fehlerfall darf
            // deshalb bis 9 s warten; der Erfolgsweg läuft sofort weiter.
            pollUntil(budget: 9.0, base: base, fm: fm, label: "branch-list",
                      cond: {
                          ws.gitBranches.contains(where: { $0.name == "main" })
                              && ws.gitBranches.contains(where: { $0.name == "feature" && $0.isCurrent })
                      },
                      next: {
                          gitActionsWhenIdle(ws, base: base, fm: fm, label: "switch-idle") {
                              ws.gitSwitchBranch("main")
                          }
                          pollAsync(budget: 4.5, base: base, fm: fm, label: "switch",
                                    check: { done in
                                        GitRunner.run(["branch", "--show-current"], in: repo) { r in
                                            let onMain = r?.stdout.trimmingCharacters(in: .whitespacesAndNewlines) == "main"
                                            let feedback = ws.gitFeedback?.message.contains("main") == true
                                            done(onMain && feedback)
                                        }
                                    },
                                    next: { gitActionsWorktreeBlock(ws, repo: repo, bare: bare, base: base, fm: fm) })
                      })
        }
    }

    /// Ein in einem zweiten Worktree ausgecheckter Branch ist im Hauptworktree
    /// gesperrt (Git-Exit 128). Fastra muss die Sperre erklären und den Weg zum
    /// anderen Arbeitsverzeichnis anbieten.
    private static func gitActionsWorktreeBlock(_ ws: Workspace, repo: URL, bare: URL,
                                                base: URL, fm: FileManager) {
        let linked = base.appendingPathComponent("zweitkopie")
        runGitSequence([["worktree", "add", "-q", "-b", "belegt", linked.path, "main"]],
                       in: repo) { ok, e in
            guard ok else { try? fm.removeItem(at: base); finish(false, "(worktree-setup) \(e)") }
            ws.refreshGitBranches()
            pollUntil(budget: 9.0, base: base, fm: fm, label: "worktree-branchliste",
                      cond: {
                          ws.gitBranches.first { $0.name == "belegt" }?
                              .blockingWorktree != nil
                      },
                      next: {
                          var block: GitBranchWorktreeBlock?
                          ws.gitBranchWorktreeBlockHandler = { seen in
                              block = seen
                              // `false`: Das andere Verzeichnis nicht öffnen —
                              // der Projektwechsel würde die restlichen Stufen
                              // dieses Laufs entwerten.
                              return false
                          }
                          gitActionsWhenIdle(ws, base: base, fm: fm, label: "worktree-idle") {
                              ws.gitSwitchBranch("belegt")
                          }
                          pollUntil(budget: 9.0, base: base, fm: fm, label: "worktree-absage",
                                    cond: { block != nil },
                                    next: {
                                        gitActionsWorktreeBlockVerdict(
                                            ws, block: block, repo: repo, bare: bare,
                                            base: base, fm: fm, linked: linked
                                        )
                                    })
                      })
        }
    }

    /// Bewertet die Absage getrennt von der Warteschleife: richtiger Branch,
    /// richtiges Verzeichnis, und das Hauptverzeichnis steht unverändert auf
    /// `main` — ein Wechsel darf hier gerade nicht stattgefunden haben.
    private static func gitActionsWorktreeBlockVerdict(
        _ ws: Workspace, block: GitBranchWorktreeBlock?, repo: URL, bare: URL,
        base: URL, fm: FileManager, linked: URL
    ) {
        guard let block, block.branch == "belegt",
              URL(fileURLWithPath: block.worktree).resolvingSymlinksInPath().path
                  == linked.resolvingSymlinksInPath().path,
              block.worktreeExists,
              block.informativeText.contains(block.worktree) else {
            ws.gitBranchWorktreeBlockHandler = ws.gitInteraction.defaultGitBranchWorktreeBlock
            try? fm.removeItem(at: base)
            finish(false, "(worktree-absage) unerwartet: \(String(describing: block))")
        }
        ws.gitBranchWorktreeBlockHandler = ws.gitInteraction.defaultGitBranchWorktreeBlock
        GitRunner.run(["branch", "--show-current"], in: repo) { r in
            let current = r?.stdout.trimmingCharacters(in: .whitespacesAndNewlines)
            guard current == "main" else {
                try? fm.removeItem(at: base)
                finish(false, "(worktree-absage) Branch ist \(current ?? "nil") statt main")
            }
            gitActionsWorktreeGone(ws, repo: repo, bare: bare, base: base,
                                   fm: fm, linked: linked)
        }
    }

    /// Dieselbe Branch-Sperre bei gelöschtem Worktree-Ordner prüfen: Git kennt
    /// die Zuordnung noch, obwohl `fileExists` false liefert. Der Dialog mit dem
    /// Hinweis auf `git worktree prune` muss trotzdem erscheinen; seine Ausführung
    /// darf nicht am Existenztest kurzgeschlossen werden.
    private static func gitActionsWorktreeGone(_ ws: Workspace, repo: URL, bare: URL,
                                               base: URL, fm: FileManager, linked: URL) {
        do {
            try fm.removeItem(at: linked)
        } catch {
            try? fm.removeItem(at: base)
            finish(false, "(worktree-weg-setup) \(error.localizedDescription)")
        }
        var block: GitBranchWorktreeBlock?
        ws.gitBranchWorktreeBlockHandler = { seen in
            block = seen
            return false
        }
        gitActionsWhenIdle(ws, base: base, fm: fm, label: "worktree-weg-idle") {
            ws.gitSwitchBranch("belegt")
        }
        pollUntil(budget: 9.0, base: base, fm: fm, label: "worktree-weg",
                  cond: { block != nil },
                  next: {
                      ws.gitBranchWorktreeBlockHandler =
                          ws.gitInteraction.defaultGitBranchWorktreeBlock
                      guard let block, block.branch == "belegt",
                            !block.worktreeExists,
                            block.informativeText.contains("prune") else {
                          try? fm.removeItem(at: base)
                          finish(false, "(worktree-weg) unerwartet: "
                              + "\(String(describing: block))")
                      }
                      runGitSequence([["worktree", "prune"]], in: repo) { ok, e in
                          guard ok else {
                              try? fm.removeItem(at: base)
                              finish(false, "(worktree-abbau) \(e)")
                          }
                          gitActionsPickaxe(ws, repo: repo, bare: bare, base: base, fm: fm)
                      }
                  })
    }

    /// PICKAXE: `git log -S` muss den Commit finden, der PICKAXE_MARKER einführte.
    private static func gitActionsPickaxe(_ ws: Workspace, repo: URL, bare: URL, base: URL, fm: FileManager) {
        GitRunner.run(["log", "-SPICKAXE_MARKER", "--oneline"], in: repo) { r in
            guard let r, r.ok, !r.stdout.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                try? fm.removeItem(at: base)
                finish(false, "(pickaxe) kein Treffer: \(r?.stderr ?? "nil")")
            }
            gitActionsAutoUpstream(ws, repo: repo, bare: bare, base: base, fm: fm)
        }
    }

    /// Neuer Branch ohne Upstream: `gitPush()` legt den Remote-Ref an, lässt
    /// die lokale Upstream-Konfiguration aber bewusst unberührt.
    private static func gitActionsAutoUpstream(_ ws: Workspace, repo: URL, bare: URL, base: URL, fm: FileManager) {
        runGitSequence([["switch", "-c", "ohne-upstream"]], in: repo) { ok, e in
            guard ok else { try? fm.removeItem(at: base); finish(false, "(auto-u setup) \(e)") }
            ws.gitMutationConfirmationHandler = { confirmation in
                confirmation.explanation.contains("origin")
                    && confirmation.explanation.contains(bare.path)
            }
            gitActionsWhenIdle(ws, base: base, fm: fm, label: "auto-upstream-idle") {
                ws.gitPush()
            }
            pollAsync(budget: 4.5, base: base, fm: fm, label: "auto-upstream",
                      check: { done in
                          // Der Branch muss im bare-Remote existieren, ohne dass
                          // Fastra dabei einen lokalen Upstream erfindet.
                          GitRunner.run(["rev-parse", "--verify", "refs/heads/ohne-upstream"], in: bare) { r in
                              readGitUpstreamConfig(in: repo, branch: "ohne-upstream") {
                                  remoteConfig, mergeConfig in
                                  done(gitPushWithoutUpstreamSucceeded(
                                      remoteRef: r, remoteConfig: remoteConfig,
                                      mergeConfig: mergeConfig
                                  ))
                              }
                          }
                      },
                      next: {
                          gitActionsWorktreeOpen(ws, repo: repo, base: base, fm: fm)
                      })
        }
    }

    /// Worktree öffnen: Die Absage bietet an, das blockierende
    /// Arbeitsverzeichnis als Projekt zu öffnen — dort liegt der gesuchte
    /// Stand ja bereits. Diese Stufe belegt, dass der Knopf das auch tut; sie
    /// steht am Ende, weil sie das Projekt des Laufs bewusst wechselt.
    private static func gitActionsWorktreeOpen(_ ws: Workspace, repo: URL,
                                               base: URL, fm: FileManager) {
        let linked = base.appendingPathComponent("oeffnen")
        runGitSequence([["worktree", "add", "-q", "-b", "zumOeffnen", linked.path, "main"]],
                       in: repo) { ok, e in
            guard ok else { try? fm.removeItem(at: base); finish(false, "(worktree-open-setup) \(e)") }
            ws.refreshGitBranches()
            pollUntil(budget: 9.0, base: base, fm: fm, label: "worktree-open-liste",
                      cond: {
                          ws.gitBranches.first { $0.name == "zumOeffnen" }?
                              .blockingWorktree != nil
                      },
                      next: {
                          // `true`: Der Nutzer wählt „Arbeitsverzeichnis öffnen".
                          ws.gitBranchWorktreeBlockHandler = { _ in true }
                          gitActionsWhenIdle(ws, base: base, fm: fm, label: "worktree-open-idle") {
                              ws.gitSwitchBranch("zumOeffnen")
                          }
                          let target = linked.resolvingSymlinksInPath().path
                          pollUntil(budget: 9.0, base: base, fm: fm, label: "worktree-open",
                                    cond: {
                                        ws.projectURL?.resolvingSymlinksInPath().path == target
                                    },
                                    next: {
                                        ws.gitBranchWorktreeBlockHandler =
                                            ws.gitInteraction.defaultGitBranchWorktreeBlock
                                        try? fm.removeItem(at: base)
                                        finish(true, "Git-Aktionen: Push (ahead→0), Pull-FF (Remote-Datei da), "
                                            + "Amend (Datei in Commit, Zahl gleich), Branch-Liste + Auswahl, "
                                            + "Worktree-Sperre erklärt statt git-Rohtext und öffnet das "
                                            + "blockierende Verzeichnis, Pickaxe, Push ohne Upstream-Änderung ok")
                                    })
                      })
        }
    }

    /// Prüft den Nachweis des Pushs getrennt von der asynchronen Abfrage.
    static func gitPushWithoutUpstreamSucceeded(
        remoteRef: GitResult?, remoteConfig: GitResult?, mergeConfig: GitResult?
    ) -> Bool {
        remoteRef?.ok == true
            && gitConfigValueIsAbsent(remoteConfig)
            && gitConfigValueIsAbsent(mergeConfig)
    }

    /// Vor der nächsten Workspace-Aktion auf Freigabe des Git-Koordinators
    /// warten. Die echte UI deaktiviert Aktionen während `gitOperationsAreBusy`;
    /// ein direkter Testaufruf soll dieselbe Vorbedingung einhalten.
    private static func gitActionsWhenIdle(_ ws: Workspace, base: URL, fm: FileManager,
                                           label: String,
                                           then action: @escaping () -> Void) {
        // Bisher 150 × 30 ms = 4,5 s.
        waitFor(budget: 4.5, pause: 0.03,
                condition: { !ws.gitOperationsAreBusy },
                onTimeout: { book in
                    try? fm.removeItem(at: base)
                    finish(false, "(\(label)) Git-Koordinator wird nicht frei — \(book.summary)")
                },
                then: action)
    }

    /// Kleiner Poll-Helfer: ruft `cond` alle 30 ms, bei `true` → `next`; ist
    /// die Frist aufgebraucht → FAIL mit Label. Räumt bei Timeout das
    /// Basis-Verzeichnis ab. `budget` ist die frühere Tick-Zahl mal Pause —
    /// 4,5 s für 150 Ticks, 9,0 s für 300 —, zählt aber nur bediente Zeit
    /// (Begründung in `SelfTestPolling.swift`).
    private static func pollUntil(budget: TimeInterval, base: URL, fm: FileManager, label: String,
                                  cond: @escaping () -> Bool, next: @escaping () -> Void) {
        waitFor(budget: budget, pause: 0.03,
                condition: cond,
                onTimeout: { book in
                    try? fm.removeItem(at: base)
                    finish(false, "(\(label)) Timeout — \(book.summary)")
                },
                then: next)
    }

    /// Wie `pollUntil`, aber mit asynchroner Bedingung (`check` liefert das
    /// Ergebnis über einen Callback) — für Ground-Truth-Checks, die selbst git
    /// aufrufen. Vermeidet den Race mit dem lokalen Status-Cache.
    private static func pollAsync(budget: TimeInterval, base: URL, fm: FileManager, label: String,
                                  check: @escaping (@escaping (Bool) -> Void) -> Void,
                                  next: @escaping () -> Void) {
        waitForAsync(budget: budget, pause: 0.03,
                     check: check,
                     onTimeout: { book in
                         try? fm.removeItem(at: base)
                         finish(false, "(\(label)) Timeout — \(book.summary)")
                     },
                     then: next)
    }

    private static func runSearchTest() {
        testLabel = "search"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        SelfTestSearchSemantics(workspace: ws, waitFor: waitFor, finish: finish).runSearchTest()
    }

    private static func runSelSearchTest() {
        testLabel = "selsearch"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        SelfTestSearchSemantics(workspace: ws, waitFor: waitFor, finish: finish).runSelSearchTest()
    }

    private static func runWildcardTest() {
        testLabel = "wildcard"
        guard let ws = Workspace.shared else {
            finish(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        SelfTestSearchSemantics(workspace: ws, waitFor: waitFor, finish: finish).runWildcardTest()
    }

    private static var screenshotFixtureDirectories: [URL] = []

    /// Sichtbare Demo-Namen bleiben lesbar, ihr Elternordner gehört aber
    /// ausschließlich diesem Aufruf. Nie einen vorhandenen Demo-Ordner löschen.
    static func makeScreenshotFixtureDirectory(
        in parent: URL? = nil,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> URL {
        // Foundation kann den systemweiten Temp-Pfad zwischenspeichern. Der
        // Runner räumt hingegen exakt sein TMPDIR auch nach Prozessabbruch auf.
        let root = parent ?? environment["TMPDIR"].flatMap {
            $0.isEmpty ? nil : URL(fileURLWithPath: $0, isDirectory: true)
        } ?? selfTestTemporaryDirectory()
        let directory = root.appendingPathComponent("fastra-shot-\(UUID().uuidString)")
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: false)
        } catch {
            finish(.environment, "Screenshot-Fixture nicht anlegbar: \(error.localizedDescription)")
        }
        screenshotFixtureDirectories.append(directory)
        return directory
    }

    static func cleanupScreenshotFixtures() {
        for directory in screenshotFixtureDirectories {
            try? FileManager.default.removeItem(at: directory)
        }
        screenshotFixtureDirectories.removeAll()
    }

    private static func finishScreenshotDiagnostic() -> Never {
        cleanupScreenshotFixtures()
        exit(0)
    }

    // MARK: - Screenshot-Setup für Platzhalter-Pillen + Live-Vorschau (Diagnose)

    /// Diagnose-Setup für einen fenstergezielten Screenshot der neuen
    /// Platzhalter-Oberflächen: nummerierte Pillen + inline
    /// Live-Vorschau. Lädt mehrzeiligen Demo-Text, schaltet RegEx aus, setzt
    /// `*, the` / `The *`, wartet auf die Live-Treffer (damit Pillen und
    /// Vorschau Daten haben) und dumpt dann die Fenster-Nummer der Suchmaske
    /// für `screencapture -l <nr>`. Hält die Maske ~12 s offen, dann `exit(0)`.
    /// Kein PASS/FAIL-Funktionstest — die Funktion deckt der `wildcard`-Test ab.
    private static func runWildcardShot() {
        testLabel = "wildcardshot"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        // Fester, lesbarer Name — der Dateiname erscheint im Trefferbaum und
        // damit auf README-Screenshots (UUID-Namen sähen dort wüst aus). Der
        // Screenshot-Runner wählt passend zur App-Sprache die Beispielsprache.
        let fileName = screenshotIsEnglish ? "MovieList.txt" : "Filmliste.txt"
        let tmp = makeScreenshotFixtureDirectory()
            .appendingPathComponent(fileName)
        // Mehrere Zeilen → die Live-Vorschau zeigt „erste 3 + … und N weitere".
        // Die Jahreszahlen liegen hinter dem Treffer. Damit belegen die
        // README-Screenshots sichtbar, dass die Trefferliste auch den Rest
        // der jeweiligen Zeile als schwächeren Kontext anzeigt.
        let demo = "ring, The — 2002\nhobbit, The — 2012\nempire, The — 1980\nphantom menace, The — 1999\nmatrix, The — 1999\n"
        do { try demo.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            ws.scope = .file
            ws.useRegex = false
            ws.treatWildcardLiterally = false
            ws.replacePattern = "The *"   // → $1: Vorher „ring, The" / Nachher „The ring"
            ws.findPattern = "*, the"
            pollWildcardShot(ws)
        }
    }

    /// Diagnose-Setup (`-selftest regexshot`): wie `runWildcardShot`, aber im
    /// RegEx-Modus — gleicher Demo-Inhalt, Muster `(\w+), (\w+)` → `$2 $1`
    /// (Capture Groups + Token-Highlighting sichtbar). Dumpt die Fenster-Nummer
    /// der Suchmaske für `screencapture -l <nr>`, ~12 s offen, dann `exit(0)`.
    private static func runRegexShot() {
        testLabel = "regexshot"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        // Fester, lesbarer Name — erscheint im Trefferbaum (README-Screenshots).
        let fileName = screenshotIsEnglish ? "MovieList.txt" : "Filmliste.txt"
        let tmp = makeScreenshotFixtureDirectory()
            .appendingPathComponent(fileName)
        // Der RegEx-Treffer endet vor der Jahreszahl; ihr sichtbar schwächerer
        // Text prüft auch in dieser Aufnahme den neuen Zeilenkontext.
        let demo = "ring, The — 2002\nhobbit, The — 2012\nempire, The — 1980\nphantom menace, The — 1999\nmatrix, The — 1999\n"
        do { try demo.write(to: tmp, atomically: true, encoding: .utf8) }
        catch { finish(false, "Temp-Datei nicht schreibbar: \(error.localizedDescription)") }
        ws.loadFile(at: tmp) { ok in
            try? FileManager.default.removeItem(at: tmp)
            guard ok else { finish(false, "loadFile schlug fehl (completion false)") }
            ws.scope = .file
            ws.useRegex = true
            ws.replacePattern = "$2 $1"
            ws.findPattern = "(\\w+), (\\w+)"
            pollRegexShot(ws)
        }
    }

    /// Wartet auf Live-Treffer im RegEx-Modus, holt die Suchmaske nach vorn
    /// und gibt ihre Fenster-Nummer aus, dann Selbst-Exit (wie Wildcard-Shot).
    private static func pollRegexShot(_ ws: Workspace) {
        var win: NSWindow?
        waitFor(budget: 3, pause: 0.03,
                condition: {
                    guard ws.bufferMatches.count >= 1, ws.searchError == nil else { return false }
                    win = NSApp.windows.first(where: {
                        $0.frameAutosaveName == SearchWindow.frameAutosaveName && $0.isVisible
                    })
                    return win != nil
                },
                onTimeout: { book in
                    finish(false, "(regexshot) keine Treffer/Suchmaske "
                        + "(bufferMatches=\(ws.bufferMatches.count), error=\(ws.searchError ?? "nil")) — \(book.summary)")
                },
                then: {
                    guard let win else { finish(false, "(regexshot) Suchmaske nach Erfolg verschwunden") }
                    win.orderFront(nil)
                    FileHandle.standardError.write(Data("REGEXSHOT-WINDOW \(win.windowNumber)\n".utf8))
                    DispatchQueue.main.asyncAfter(deadline: .now() + 12) { finishScreenshotDiagnostic() }
                })
    }

    /// Diagnose (`-selftest searchshot`): Suchmaske im leeren Ausgangszustand
    /// nach vorn holen und die Fenster-Nummer ausgeben (für `screencapture -l`),
    /// nach 12 s Selbst-Exit. Kein Funktionstest — ein Screenshot-Helfer wie
    /// `wildcardshot`, nur ohne Feld-Befüllung (Placeholder sichtbar).
    private static func runSearchShot() {
        testLabel = "searchshot"
        // Felder explizit leeren — der Erststart lädt sonst den Demo-Inhalt
        // mit vorbefülltem Suchmuster, und die Placeholder wären unsichtbar.
        Workspace.shared?.findPattern = ""
        Workspace.shared?.replacePattern = ""
        guard let win = NSApp.windows.first(where: {
            $0.frameAutosaveName == SearchWindow.frameAutosaveName && $0.isVisible
        }) else {
            finish(false, "(searchshot) Suchmaske nicht sichtbar")
        }
        win.orderFront(nil)
        FileHandle.standardError.write(Data("SEARCHSHOT-WINDOW \(win.windowNumber)\n".utf8))
        DispatchQueue.main.asyncAfter(deadline: .now() + 12) { finishScreenshotDiagnostic() }
    }

    /// Diagnose (`-selftest welcomeshot`): Willkommensbildschirm mit gefüllter
    /// Projektliste herstellen, Fenster-Nummer des Hauptfensters ausgeben
    /// (für `screencapture -l`), nach 12 s Selbst-Exit. Kein Funktionstest —
    /// die Logik deckt der `project`-Selbsttest ab.
    private static func runWelcomeShot() {
        testLabel = "welcomeshot"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        // Startzustand simulieren: unberührter leerer Tab (zeigt den
        // Willkommens-Platzhalter) plus Beispiel-Projekte, damit die Liste
        // auf dem Screenshot gefüllt ist.
        ws.tabs = [Workspace.makeScratchTab()]
        ws.activeTabID = ws.tabs.first?.id
        ws.projectURL = nil
        ws.recentProjects = [
            ProjectEntry(path: "~/git/fastra"),
            ProjectEntry(path: "~/git/Beispielprojekt"),
            ProjectEntry(path: "~/Projekte/Newsletter"),
        ]
        dumpMainWindowThenExit(prefix: "WELCOMESHOT-WINDOW")
    }

    /// Diagnose (`-selftest welcometabshot`): Projekt mit offener Datei und
    /// frischem ⌘T-Tab. Die Aufnahme zeigt die Starthilfe über dem Editor ohne
    /// Projekt-Sperre. Logik prüfen die Unit-Tests und der `project`-Selbsttest.
    private static func runWelcomeTabShot() {
        testLabel = "welcometabshot"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        // Echtes kleines Projekt-Fixture, damit Seitenleiste und Datei-Tab
        // dem Alltag entsprechen.
        let root = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-welcometabshot-\(UUID().uuidString)")
        do {
            try FileManager.default.createDirectory(at: root,
                                                    withIntermediateDirectories: true)
            try "Bestehende Arbeit\n".write(
                to: root.appendingPathComponent("notiz.txt"),
                atomically: true, encoding: .utf8)
        } catch {
            finish(false, "Fixture nicht anlegbar: \(error)")
        }
        ws.openProject(at: root)
        ws.loadFile(at: root.appendingPathComponent("notiz.txt")) { _ in
            // ⌘T-Äquivalent: frischer leerer Tab im Projektfenster.
            ws.openNewTab()
            dumpMainWindowThenExit(prefix: "WELCOMETABSHOT-WINDOW")
        }
    }

    /// Am echten Fenster breite Diff-Zeilen auf Spaltenüberlauf prüfen:
    /// Spalten gleich breit, rechte hinter der linken und lange Textzeile
    /// mehrzeilig. So muss der Text umbrechen statt die Nachbarspalte zu überzeichnen.
    @MainActor
    private static func runDiffSelectionTest(background: Bool = false) {
        testLabel = background ? "diffselectionbackground" : "diffselection"
        guard let ws = Workspace.shared else { finish(false, "Workspace fehlt") }
        let tail = String(repeating: "lange Vergleichszeile ", count: 12)
        let left = "alt α\né 🇩🇪\nEnde alt " + tail + "\n"
        let right = "neu β\n日本\nEnde neu " + tail + "\n"
        let request = FileDiffRequest(left: .text(left, name: "before.txt"),
                                      right: .text(right, name: "after.txt"),
                                      options: FileDiffOptions())
        let document = Workspace.computeFileDiffDocument(request: request)
        let patch = "diff --git a/test.txt b/test.txt\n--- a/test.txt\n+++ b/test.txt\n@@ -1,3 +1,3 @@\n"
            + left.split(separator: "\n").map { "-" + $0 }.joined(separator: "\n") + "\n"
            + right.split(separator: "\n").map { "+" + $0 }.joined(separator: "\n") + "\n"
        let gitDocument = GitDiffParser.parse(Data(patch.utf8))
        let gitRequest = GitDiffRequest(repositoryPath: selfTestTemporaryDirectory().path,
                                       source: .workingTree(path: "test.txt"))
        let windowType: NSWindow.Type = background ? BackgroundDiffSelectionWindow.self : NSWindow.self
        let window = windowType.init(contentRect: NSRect(x: 150, y: 150, width: 760, height: 700),
                              styleMask: [.titled, .closable, .resizable], backing: .buffered, defer: false)
        window.isReleasedWhenClosed = false
        window.title = "fastra-diffselection-\(UUID().uuidString)"
        let title = window.title
        var phase = 0
        var largeDiffViewCount = 0
        func views(in root: NSView) -> [DiffSelectionTextView] {
            (root as? DiffSelectionTextView).map { [$0] } ?? root.subviews.flatMap { views(in: $0) }
        }
        func selectionEndX(in view: DiffSelectionTextView) -> CGFloat {
            guard let manager = view.layoutManager, let container = view.textContainer else { return 1 }
            manager.ensureLayout(for: container)
            // Bei CJK kann usedRect die ganze Containerbreite enthalten.
            // Der Klick gehört hinter die tatsächlichen Glyphen; die rechte
            // Spaltenkante liegt im schmalen Fenster außerhalb des Ausschnitts.
            let glyphs = manager.glyphRange(for: container)
            return min(view.bounds.width - 1,
                       manager.boundingRect(forGlyphRange: glyphs, in: container).maxX + 1)
        }
        func startPoint(of view: DiffSelectionTextView, atEnd: Bool) -> NSPoint {
            view.convert(NSPoint(x: atEnd ? selectionEndX(in: view) : 1,
                                 y: min(5, view.bounds.height / 2)), to: nil)
        }
        func step() {
            guard phase < (background ? 11 : 10) else {
                window.orderOut(nil)
                window.close()
                let scaleReport = background ? "; 20.000-Zeilen-Diff: \(largeDiffViewCount) montierte Textansichten" : ""
                finish(true, "Datei-, strukturierter Git- und einfacher Git-Diff: native Mausauswahl vorwärts/rückwärts, beide Spalten, zwei Breiten und Soft Wrap; Copy mit Unicode ohne Zeilennummern\(scaleReport)")
            }
            let raw = phase >= 8
            let wrapped = phase % 2 == 0
            let narrow = raw ? phase == 8 : phase % 4 < 2
            window.setContentSize(NSSize(width: narrow ? 760 : 1100, height: 700))
            let root: AnyView
            if raw {
                let content = phase == 10 ? patch + String(repeating: "+short line\n", count: 20_000) : patch
                root = AnyView(GitTextView(kind: .diff, content: content).environmentObject(ws))
            } else if phase < 4 {
                root = AnyView(FileDiffView(request: request, document: document,
                                           softWrapEnabled: wrapped).environmentObject(ws))
            } else {
                root = AnyView(GitDualPaneDiffView(request: gitRequest, document: gitDocument,
                                                  fallbackText: "", softWrapEnabled: wrapped).environmentObject(ws))
            }
            window.contentView = NSHostingView(rootView: root)
            if background { window.orderBack(nil) } else { window.makeKeyAndOrderFront(nil) }
            let expectedFirst = raw ? "-alt α" : "alt α"
            let expectedLast = raw ? "-é 🇩🇪" : "é 🇩🇪"
            var pair: (DiffSelectionTextView, DiffSelectionTextView)?
            var hitReport = ""
            waitFor(budget: 4, pause: 0.05, condition: {
                guard let content = window.contentView else { return false }
                content.layoutSubtreeIfNeeded()
                let rendered = views(in: content)
                guard let first = rendered.first(where: { $0.before && $0.string == expectedFirst }),
                      let last = rendered.first(where: { $0.before && $0.string == expectedLast }),
                      first.bounds.width > 10, last.bounds.width > 10,
                      first.selection?.contains(first) == true,
                      last.selection?.contains(last) == true else { return false }
                // SwiftUI kann die Textansichten schon einhängen, während
                // Scrollposition und Clipping noch auf das vorige Layout zeigen.
                // Erst reale Trefferpunkte freigeben, dann im selben Tick ziehen.
                for before in raw ? [true] : [true, false] {
                    guard let startView = before ? first : rendered.first(where: { !$0.before && $0.string == "neu β" }),
                          let endView = before ? last : rendered.first(where: { !$0.before && $0.string == "日本" }) else { return false }
                    // AppKits hitTest erwartet Koordinaten der übergeordneten
                    // Ansicht. Der Hosting-Inhalt und der Fensterrahmen können
                    // unterschiedliche y-Richtungen haben.
                    let start = startView.convert(NSPoint(x: 1, y: min(5, startView.bounds.height / 2)), to: content.superview)
                    let end = endView.convert(NSPoint(x: selectionEndX(in: endView), y: min(5, endView.bounds.height / 2)), to: content.superview)
                    let startHit = content.hitTest(start), endHit = content.hitTest(end)
                    hitReport = "Seite \(before), Start \(start), Ende \(end), Treffer \(String(describing: startHit)) / \(String(describing: endHit))"
                    guard startHit === startView, endHit === endView else { return false }
                }
                pair = (first, last)
                return true
            }, onTimeout: { _ in
                func failed() {
                    window.orderOut(nil)
                    finish(false, "Diff-Textansichten oder Mauspunkte fehlen, Phase \(phase): \(hitReport)")
                }
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_DIFFSELECTION_DIR"],
                      !directory.isEmpty else { failed(); return }
                typeScrollCapture(window: window) { snapshot in
                    if let snapshot {
                        let base = URL(fileURLWithPath: directory)
                        try? FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
                        try? snapshot.data.write(to: base.appendingPathComponent("diffselection-failed-\(phase).png"))
                    }
                    failed()
                }
            }, then: {
                guard window.title == title,
                      background ? !NSApp.isActive : (window.isKeyWindow && NSApp.isActive),
                      let content = window.contentView, let pair else {
                    window.orderOut(nil)
                    finish(.environment, "Diff-Fixture hat den Fokus verloren")
                }
                let rendered = views(in: content)
                if phase == 10 {
                    largeDiffViewCount = rendered.count
                    guard largeDiffViewCount < 200 else {
                        window.orderOut(nil); finish(false, "Großer Git-Diff montiert \(largeDiffViewCount) Textansichten statt sichtbarer Zeilen")
                    }
                }
                let sides = raw ? [true] : [true, false]
                for before in sides {
                    let firstText = before ? expectedFirst : "neu β"
                    let lastText = before ? expectedLast : "日本"
                    guard let first = before ? pair.0 : rendered.first(where: { !$0.before && $0.string == firstText }),
                          let last = before ? pair.1 : rendered.first(where: { !$0.before && $0.string == lastText }) else {
                        window.orderOut(nil); finish(false, "Gegenseite fehlt")
                    }
                    let start = first.convert(NSPoint(x: 1, y: min(5, first.bounds.height / 2)), to: nil)
                    let end = last.convert(NSPoint(x: selectionEndX(in: last), y: min(5, last.bounds.height / 2)), to: nil)
                    guard let parent = content.superview,
                          content.hitTest(parent.convert(start, from: nil)) === first,
                          content.hitTest(parent.convert(end, from: nil)) === last else {
                        window.orderOut(nil); finish(false, "Mauspunkte treffen nicht den gerenderten Diff-Text")
                    }
                    for reversed in [false, true] {
                        guard window.title == title,
                              sendSplitterDrag(from: reversed ? end : start, to: reversed ? start : end, in: window),
                              first.selectedRange().length == firstText.utf16.count,
                              last.selectedRange().length == lastText.utf16.count else {
                            window.orderOut(nil); finish(false, "Zeilenübergreifender Drag unvollständig, Phase \(phase), Seite \(before), rückwärts \(reversed)")
                        }
                        let expected = firstText + "\n" + lastText
                        prepareSelfTestPasteboardMutationOrFinish()
                        let copied = background
                            ? window.firstResponder?.tryToPerform(#selector(NSTextView.copy(_:)), with: nil) == true
                            : NSApp.sendAction(#selector(NSTextView.copy(_:)), to: nil, from: nil)
                        guard copied else {
                            window.orderOut(nil); finish(false, "Copy nicht im Responderpfad erreichbar")
                        }
                        guard let items = try? plainTextPasteboardItems(expected) else { finish(false, "Copy-Erwartung fehlt") }
                        noteSelfTestPasteboardMutationOrFinish(expectedItems: items)
                        guard NSPasteboard.general.string(forType: .string) == expected else {
                            window.orderOut(nil); finish(false, "Copy enthält falschen Text, Zeilennummern oder Gegenseite")
                        }
                    }
                }
                guard sendMouseClick(at: startPoint(of: pair.0, atEnd: true), in: window, modifiers: []),
                      pair.0.selection?.range.length == 0,
                      sendMouseClick(at: startPoint(of: pair.1, atEnd: true), in: window, modifiers: .shift),
                      pair.0.selection?.range.length == expectedLast.utf16.count + 1,
                      !background || !NSApp.isActive else {
                    window.orderOut(nil); finish(false, "Shift-Klick erweitert den Cursor nicht über die Folgezeile, Phase \(phase)")
                }
                let longRows = rendered.filter { $0.string.contains("lange Vergleichszeile") }
                if !raw {
                    guard longRows.count == 2, longRows.allSatisfy({ view in
                        guard let manager = view.layoutManager else { return false }
                        let height = manager.defaultLineHeight(for: view.font!)
                        return wrapped ? view.bounds.height > height * 2 : view.bounds.height < height * 2
                    }) else {
                        window.orderOut(nil); finish(false, "Lange Diff-Zeilen haben falsche Umbruchhöhe, Phase \(phase)")
                    }
                }
                @MainActor func next() { phase += 1; step() }
                guard let directory = ProcessInfo.processInfo.environment["FASTRA_DIFFSELECTION_DIR"],
                      !directory.isEmpty else { MainActor.assumeIsolated { next() }; return }
                typeScrollCapture(window: window) { snapshot in
                    guard let snapshot else { finish(.environment, "Diff-Auswahlaufnahme fehlt") }
                    do {
                        let destination = URL(fileURLWithPath: directory)
                        try FileManager.default.createDirectory(at: destination, withIntermediateDirectories: true)
                        try snapshot.data.write(to: destination.appendingPathComponent("diffselection-\(phase).png"))
                    } catch { finish(.environment, "Diff-Auswahlaufnahme nicht schreibbar") }
                    MainActor.assumeIsolated { next() }
                }
            })
        }
        step()
    }

    private static func runDiffWideTest() {
        testLabel = "diffwide"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        // Beide Seiten der Zeile weit jenseits jeder halben Fensterbreite —
        // nur so ist Prüfung (e) „gleich hoch" überhaupt aussagekräftig.
        guard let fixture = makeDiffOverflowFixture(label: "diffwide",
                                                    longRightLine: true) else {
            finish(false, "(setup) Vergleichsdateien nicht anlegbar")
        }
        ws.openFileDiffTab(request: FileDiffRequest(
            left: .file(fixture.left), right: .file(fixture.right),
            options: FileDiffOptions()
        ))
        pollDiffWideCells(ws, base: fixture.base)
    }

    private static func pollDiffWideCells(_ ws: Workspace, base: URL) {
        // Die Zeilen-IDs heißen „row-N". Welche Nummer die lange Zeile trägt,
        // lässt der Test offen: Er sammelt alle gerenderten Zellen und nimmt
        // die höchste als die umgebrochene, die niedrigste als Kontrollzeile.
        var pairCount = 0
        var found: (tallest: (ordinal: Int, before: CGRect, after: CGRect),
                    shortest: (ordinal: Int, before: CGRect, after: CGRect))?
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    guard let content = mainWindowForAXChecks()?.contentView else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Hauptfenster nicht erreichbar")
                    }
                    let pairs = diffCellPairs(in: content)
                    pairCount = pairs.count
                    guard pairs.count >= 2,
                          let tallest = pairs.max(by: { $0.before.height < $1.before.height }),
                          let shortest = pairs.min(by: { $0.before.height < $1.before.height })
                    else { return false }
                    found = (tallest, shortest)
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    finish(false, "Zell-Marker der Diff-Zeilen fehlen im AppKit-Baum "
                        + "(gefunden: \(pairCount)) — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Diff-Zellen nach Erfolg verschwunden") }
                    let (tallest, shortest) = found
                    let left = tallest.before
                    let right = tallest.after
                    let short = shortest.before
                    // Kein `defer`: Jeder Ausgang unten geht über `finish`, und das endet
                    // in `exit()`. Der Swift-Stack wird dabei nicht abgewickelt, ein
                    // `defer` liefe also nie (siehe auch Kommentar bei `TestDefaultsPurge`).
                    func cleanUp() { try? FileManager.default.removeItem(at: base) }

                    // (a) Beide Spalten gleich breit — sonst wäre die Trennlinie schief.
                    guard abs(left.width - right.width) < 1 else {
                        cleanUp()
                        finish(false, "Spalten sind unterschiedlich breit "
                            + "(links \(Int(left.width)) pt, rechts \(Int(right.width)) pt)")
                    }
                    // (b) Die Spaltenbreite folgt dem Fenster, nicht dem Inhalt: Die lange
                    // Zeile ist genauso breit wie die kurze Kontrollzeile.
                    guard abs(left.width - short.width) < 1 else {
                        cleanUp()
                        finish(false, "Die lange Zeile hat ihre Spalte verbreitert "
                            + "(\(Int(left.width)) pt statt \(Int(short.width)) pt) — die "
                            + "zweite Spalte wandert damit aus dem Bild")
                    }
                    // (c) Die rechte Spalte beginnt hinter der linken.
                    guard right.minX >= left.maxX - 1 else {
                        cleanUp()
                        finish(false, "Die Spalten überlappen "
                            + "(links endet \(Int(left.maxX)), rechts beginnt \(Int(right.minX)))")
                    }
                    // (d) Langer Text muss in seiner Spalte umbrechen; einzeilige Höhe (22 pt)
                    // würde Überlauf zulassen.
                    guard left.height > short.height * 2 else {
                        cleanUp()
                        finish(false, "Die lange Zeile ist nur \(Int(left.height)) pt hoch "
                            + "(kurze Zeile \(Int(short.height)) pt) — der Text bricht nicht "
                            + "um, sondern läuft über die Spaltengrenze")
                    }
                    // (e) Beide Seiten derselben Zeile sind gleich hoch, damit die
                    // Hintergründe nicht mitten in der Zeile enden.
                    guard abs(left.height - right.height) < 1 else {
                        cleanUp()
                        finish(false, "Die beiden Seiten der langen Zeile sind unterschiedlich "
                            + "hoch (links \(Int(left.height)), rechts \(Int(right.height)))")
                    }
                    cleanUp()
                    finish(true, "Spalten je \(Int(left.width)) pt breit und gleich hoch; "
                        + "die ~900 Zeichen lange Zeile bricht auf \(Int(left.height)) pt "
                        + "Höhe in ihrer Spalte um, statt über die Grenze zu laufen")
                })
    }

    // MARK: - Vergleich: Soft Wrap aus und ziehbarer Trenner

    /// Legt einen Vergleich mit genau einer sehr langen Zeile an.
    ///
    /// - Parameter longRightLine: `false` (Standard) lässt die rechte Seite
    ///   dieser Zeile kurz — nur so ist messbar, ob links etwas in die rechte
    ///   Spalte hineinragt (`diffnowrap`, `diffsplit`). `true` macht auch die
    ///   rechte Seite lang; das braucht `diffwide`, um zu belegen, dass beide
    ///   Seiten derselben Zeile gleich hoch bleiben.
    private static func makeDiffOverflowFixture(label: String,
                                                longRightLine: Bool = false)
        -> (base: URL, left: URL, right: URL)? {
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-\(label)-\(UUID().uuidString)")
        let longLeft = "ALT " + String(repeating: "links-links-links ", count: 60)
        var leftLines = (1...8).map { "gemeinsame zeile \($0)" }
        var rightLines = leftLines
        leftLines[3] = longLeft
        rightLines[3] = longRightLine
            ? "NEU " + String(repeating: "rechts-rechts-rechts ", count: 60)
            : "NEU kurz"
        let leftURL = base.appendingPathComponent("links.txt")
        let rightURL = base.appendingPathComponent("rechts.txt")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            try leftLines.joined(separator: "\n")
                .write(to: leftURL, atomically: true, encoding: .utf8)
            try rightLines.joined(separator: "\n")
                .write(to: rightURL, atomically: true, encoding: .utf8)
        } catch {
            return nil
        }
        return (base, leftURL, rightURL)
    }

    /// Sammelt die gerenderten Zell-Paare der Diff-Zeilen samt ihren Frames im
    /// Fensterinhalt. Gemeinsame Messbasis von `diffwide`, `diffnowrap` und
    /// `diffsplit`.
    private static func diffCellPairs(in content: NSView)
        -> [(ordinal: Int, before: CGRect, after: CGRect)] {
        content.window?.layoutIfNeeded()
        var pairs: [(ordinal: Int, before: CGRect, after: CGRect)] = []
        for ordinal in 0...20 {
            guard let before = markerView(id: "diffCell-before-row-\(ordinal)",
                                          in: content),
                  let after = markerView(id: "diffCell-after-row-\(ordinal)",
                                         in: content) else { continue }
            let beforeFrame = before.convert(before.bounds, to: content)
            let afterFrame = after.convert(after.bounds, to: content)
            guard beforeFrame.width > 0, afterFrame.width > 0 else { continue }
            pairs.append((ordinal, beforeFrame, afterFrame))
        }
        return pairs
    }

    /// Anteil von Bildpunkten, die von der vorherrschenden Farbe abweichen.
    /// Übergelaufener Text kann unter dem halbdurchlässigen Nachbarhintergrund
    /// blass sein; ausschließlich dunkle Pixel zu zählen würde ihn übersehen.
    /// Ein leerer Zellbereich bleibt dagegen einfarbig.
    static func diffForeignPixelFraction(_ bitmap: NSBitmapImageRep,
                                         tolerance: CGFloat = 0.03) -> Double {
        // Je Eimer wird nicht nur gezählt, sondern auch summiert. Der
        // Bezugswert ist dann der Mittelwert der Bildpunkte im häufigsten
        // Eimer — nicht dessen Untergrenze. Das ist keine Feinheit: Ein Eimer
        // ist 1/31 ≈ 0,0323 breit und damit breiter als die Toleranz von 0,03.
        // Läge ein Kanal des einfarbigen Hintergrunds im oberen Teil seines
        // Eimers, wäre der Abstand zur Untergrenze größer als die Toleranz und
        // jeder Bildpunkt gälte als fremd — der Test meldete „100 % Fremdtext"
        // auf einer leeren Fläche.
        var counts: [Int: Int] = [:]
        var sums: [Int: (CGFloat, CGFloat, CGFloat)] = [:]
        var colors: [(CGFloat, CGFloat, CGFloat)] = []
        colors.reserveCapacity(bitmap.pixelsWide * bitmap.pixelsHigh)
        for y in 0..<bitmap.pixelsHigh {
            for x in 0..<bitmap.pixelsWide {
                guard let color = bitmap.colorAt(x: x, y: y)?
                        .usingColorSpace(.sRGB) else { continue }
                let rgb = (color.redComponent, color.greenComponent,
                           color.blueComponent)
                colors.append(rgb)
                // 5 Bit je Kanal: fasst Kantenglättung derselben Fläche
                // zusammen, trennt aber Schrift vom Hintergrund.
                let key = (Int(rgb.0 * 31) << 10) | (Int(rgb.1 * 31) << 5)
                    | Int(rgb.2 * 31)
                counts[key, default: 0] += 1
                let sum = sums[key] ?? (0, 0, 0)
                sums[key] = (sum.0 + rgb.0, sum.1 + rgb.1, sum.2 + rgb.2)
            }
        }
        guard !colors.isEmpty,
              let dominantKey = counts.max(by: { $0.value < $1.value })?.key,
              let sum = sums[dominantKey], let count = counts[dominantKey],
              count > 0
        else { return 0 }
        let n = CGFloat(count)
        let dominant = (sum.0 / n, sum.1 / n, sum.2 / n)
        let foreign = colors.filter { rgb in
            abs(rgb.0 - dominant.0) > tolerance
                || abs(rgb.1 - dominant.1) > tolerance
                || abs(rgb.2 - dominant.2) > tolerance
        }
        return Double(foreign.count) / Double(colors.count)
    }

    /// Soft Wrap aus: Der Vergleich zeigt die echten Zeilen (einzeilig hoch),
    /// und was nicht in die Spalte passt, wird abgeschnitten statt in die
    /// andere Seite gezeichnet. Gemessen wird
    /// beides: die Zeilenhöhe an den Zell-Frames und die Schrift im rechten
    /// Spaltenbereich an echten Bildpunkten.
    private static func runDiffNoWrapTest() {
        testLabel = "diffnowrap"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        guard let fixture = makeDiffOverflowFixture(label: "diffnowrap") else {
            finish(false, "(setup) Vergleichsdateien nicht anlegbar")
        }
        ws.openFileDiffTab(request: FileDiffRequest(
            left: .file(fixture.left), right: .file(fixture.right),
            options: FileDiffOptions()
        ))
        // Erst mit Umbruch (Werkstandard) messen, dann ohne — nur der
        // Vergleich beider Zustände belegt, dass der Schalter wirkt.
        pollDiffNoWrap(ws, base: fixture.base, phase: 0, longOrdinal: -1,
                       wrappedHeight: 0)
    }

    /// `longOrdinal` ist die in Phase 0 ermittelte Zeilennummer der überlangen
    /// linken Zeile. Ohne sie wäre sie in Phase 1 nicht mehr auffindbar: Ohne
    /// Umbruch sind alle Zeilen gleich hoch, und „die höchste Zeile" trifft
    /// dann irgendeine — der Test maß so eine harmlose Zeile mit leerer
    /// rechter Seite und bestand auch ohne Beschneidung.
    private static func pollDiffNoWrap(_ ws: Workspace, base: URL, phase: Int,
                                       longOrdinal: Int,
                                       wrappedHeight: CGFloat) {
        var pairCount = 0
        var tallestHeight: CGFloat = 0
        var foundPhase0: (height: CGFloat, ordinal: Int)?
        var foundLong: (ordinal: Int, before: CGRect, after: CGRect)?
        var foundContent: NSView?
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    guard let window = mainWindowForAXChecks(), let content = window.contentView else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Hauptfenster nicht erreichbar")
                    }
                    let pairs = diffCellPairs(in: content)
                    pairCount = pairs.count
                    guard pairs.count >= 2,
                          let tallest = pairs.max(by: { $0.before.height < $1.before.height }),
                          let shortest = pairs.min(by: { $0.before.height < $1.before.height })
                    else { return false }
                    tallestHeight = tallest.before.height
                    if phase == 0 {
                        // Phase 0: Werkstandard — die lange Zeile muss umbrechen.
                        guard tallest.before.height > shortest.before.height * 2 else { return false }
                        foundPhase0 = (tallest.before.height, tallest.ordinal)
                        return true
                    }
                    // Phase 1: ohne Umbruch sind alle Zeilen gleich einzeilig hoch.
                    guard let long = pairs.first(where: { $0.ordinal == longOrdinal }),
                          long.before.height < wrappedHeight / 2 else { return false }
                    foundLong = long
                    foundContent = content
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    guard pairCount >= 2 else {
                        finish(false, "Zell-Marker fehlen (gefunden: \(pairCount)) — \(book.summary)")
                    }
                    if phase == 0 {
                        finish(false, "Mit Soft Wrap bricht die lange Zeile nicht um "
                            + "(\(Int(tallestHeight)) pt) — \(book.summary)")
                    }
                    finish(false, "Ohne Soft Wrap bleibt die lange Zeile "
                        + "\(Int(tallestHeight)) pt hoch (mit Umbruch: "
                        + "\(Int(wrappedHeight)) pt) — der Schalter wirkt nicht — \(book.summary)")
                },
                then: {
                    if phase == 0 {
                        guard let foundPhase0 else { finish(false, "Diff-Zeilen nach Erfolg verschwunden") }
                        guard ws.activeTabShowsDiff else {
                            try? FileManager.default.removeItem(at: base)
                            finish(false, "Der Vergleichs-Tab ist nicht aktiv — der "
                                + "Soft-Wrap-Schalter der Fußzeile träfe das falsche Profil")
                        }
                        // Genau der Weg der Fußzeile (und des Ansicht-Menüs): Der
                        // Schalter dort ruft `toggleSoftWrap()`.
                        ws.toggleSoftWrap()
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                            pollDiffNoWrap(ws, base: base, phase: 1, longOrdinal: foundPhase0.ordinal,
                                           wrappedHeight: foundPhase0.height)
                        }
                        return
                    }
                    guard let foundLong, let foundContent else {
                        finish(false, "Diff-Zeilen nach Erfolg verschwunden")
                    }
                    finishDiffNoWrap(ws, base: base, content: foundContent,
                                     wrappedHeight: wrappedHeight, row: foundLong)
                })
    }

    /// Der eigentliche Befund: Ragt die linke Seite in die rechte Spalte?
    /// Gemessen an echten Bildpunkten rechts der kurzen rechten Zeile.
    private static func finishDiffNoWrap(
        _ ws: Workspace, base: URL, content: NSView, wrappedHeight: CGFloat,
        row: (ordinal: Int, before: CGRect, after: CGRect)
    ) {
        // Das Profil ist persistent — der Testlauf darf keinen veränderten
        // Stand hinterlassen. Kein `defer`: Jeder Ausgang geht über `finish`,
        // das mit `exit()` endet und den Stack nicht abwickelt.
        func cleanUp() {
            ws.setSoftWrapEnabled(true)
            try? FileManager.default.removeItem(at: base)
        }
        // Messfenster: rechte Spalte ab deutlich hinter dem kurzen Text
        // („NEU kurz" ist ~60 pt breit) bis kurz vor ihr Ende.
        let probe = CGRect(x: row.after.minX + 160, y: row.after.minY,
                           width: max(0, row.after.width - 180),
                           height: row.after.height)
        guard probe.width > 40, content.bounds.contains(probe) else {
            cleanUp()
            finish(.environment, "Fenster zu schmal für die Bildpunktprobe "
                + "(\(Int(probe.width)) pt)")
        }
        guard let bitmap = content.bitmapImageRepForCachingDisplay(in: probe) else {
            cleanUp()
            finish(false, "Bildausschnitt der rechten Spalte nicht erzeugbar")
        }
        content.cacheDisplay(in: probe, to: bitmap)
        let foreign = diffForeignPixelFraction(bitmap)
        // Der Bereich zeigt nur den Zellhintergrund. Etwas Rauschen durch
        // Kantenglättung ist erlaubt; übergelaufener Text färbt hier ein
        // Vielfaches davon ein.
        guard foreign < 0.02 else {
            cleanUp()
            finish(false, "Die linke Seite ragt in die rechte Spalte: "
                + "\(Int(foreign * 100)) % der Bildpunkte im rechten "
                + "Spaltenbereich tragen fremde Schrift")
        }
        cleanUp()
        finish(true, "Soft Wrap aus: lange Zeile von \(Int(wrappedHeight)) pt "
            + "auf \(Int(row.before.height)) pt (einzeilig), und im rechten "
            + "Spaltenbereich weichen nur \(String(format: "%.2f", foreign * 100)) % "
            + "der Bildpunkte vom Hintergrund ab — links wird abgeschnitten "
            + "statt hinüberzuzeichnen")
    }

    /// Ziehbarer Trenner: Ein Zug nach rechts verbreitert die linke Seite um
    /// genau diesen Weg, die rechte schrumpft um denselben Betrag, und die
    /// Gesamtbreite bleibt.
    private static func runDiffSplitTest() {
        testLabel = "diffsplit"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        guard let fixture = makeDiffOverflowFixture(label: "diffsplit") else {
            finish(false, "(setup) Vergleichsdateien nicht anlegbar")
        }
        ws.openFileDiffTab(request: FileDiffRequest(
            left: .file(fixture.left), right: .file(fixture.right),
            options: FileDiffOptions()
        ))
        pollDiffSplit(ws, base: fixture.base)
    }

    private static func pollDiffSplit(_ ws: Workspace, base: URL) {
        var found: (window: NSWindow, content: NSView,
                    row: (ordinal: Int, before: CGRect, after: CGRect), handle: NSView)?
        var pairCount = 0
        waitFor(budget: 5, pause: 0.05,
                condition: {
                    guard let window = mainWindowForAXChecks(), let content = window.contentView else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Hauptfenster nicht erreichbar")
                    }
                    let pairs = diffCellPairs(in: content)
                    pairCount = pairs.count
                    guard let row = pairs.first,
                          let handle = markerView(id: "diffSplitter", in: content) else { return false }
                    found = (window, content, row, handle)
                    return true
                },
                onTimeout: { book in
                    try? FileManager.default.removeItem(at: base)
                    let handleExists = mainWindowForAXChecks()?.contentView
                        .map { markerView(id: "diffSplitter", in: $0) != nil } ?? false
                    finish(false, "Zellen oder Splitter-Griff fehlen im Fensterbaum "
                        + "(Zeilen: \(pairCount), Griff: \(handleExists)) — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Diff-Zellen nach Erfolg verschwunden") }
                    let (window, content, row, handle) = found
                    let beforeLeft = row.before.width
                    let beforeRight = row.after.width
                    let handleFrame = handle.convert(handle.bounds, to: content)
                    // Der Griff ist dokumenthoch; angefasst wird er auf Höhe der ersten
                    // Zeile, damit der Punkt sicher im sichtbaren Bereich liegt.
                    let grab = NSPoint(x: handleFrame.midX, y: row.before.midY)
                    guard handleFrame.insetBy(dx: -1, dy: 0).contains(grab) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Greifpunkt \(grab) liegt nicht im Griff \(handleFrame)")
                    }
                    // Messung und Klick im selben Main-Thread-Durchlauf: `sendEvent`
                    // stellt synchron zu, ein Nachlayout kann sich nicht dazwischen
                    // schieben (siehe AGENTS.md zu `armSingleShiftClick`).
                    let distance: CGFloat = 120
                    let startInWindow = content.convert(grab, to: nil)
                    let endInWindow = NSPoint(x: startInWindow.x + distance, y: startInWindow.y)
                    guard sendSplitterDrag(from: startInWindow, to: endInWindow, in: window) else {
                        try? FileManager.default.removeItem(at: base)
                        finish(false, "Zieh-Ereignisse nicht erzeugbar")
                    }
                    pollDiffSplitResult(ws, base: base, beforeLeft: beforeLeft,
                                        beforeRight: beforeRight, distance: distance)
                })
    }

    /// Maus-Zug auf dem Splitter: Down, mehrere Zwischenschritte, Up. Der
    /// Griff ist eine AppKit-View, `sendEvent` erreicht sie direkt.
    private static func sendSplitterDrag(from start: NSPoint, to end: NSPoint,
                                         in window: NSWindow) -> Bool {
        let time = ProcessInfo.processInfo.systemUptime
        func event(_ type: NSEvent.EventType, _ point: NSPoint,
                   _ offset: Double, _ number: Int) -> NSEvent? {
            NSEvent.mouseEvent(with: type, location: point, modifierFlags: [],
                               timestamp: time + offset,
                               windowNumber: window.windowNumber, context: nil,
                               eventNumber: number, clickCount: 1,
                               pressure: type == .leftMouseUp ? 0 : 1)
        }
        guard let down = event(.leftMouseDown, start, 0, 0) else { return false }
        window.sendEvent(down)
        for step in 1...4 {
            let fraction = CGFloat(step) / 4
            let point = NSPoint(x: start.x + (end.x - start.x) * fraction,
                                y: start.y + (end.y - start.y) * fraction)
            guard let drag = event(.leftMouseDragged, point,
                                   0.01 * Double(step), step) else { return false }
            window.sendEvent(drag)
        }
        guard let up = event(.leftMouseUp, end, 0.06, 9) else { return false }
        window.sendEvent(up)
        return true
    }

    private static func pollDiffSplitResult(_ ws: Workspace, base: URL,
                                            beforeLeft: CGFloat,
                                            beforeRight: CGFloat,
                                            distance: CGFloat) {
        // Die Teilung ist persistent, das Verzeichnis liegt im Temp-Ordner:
        // Beides muss vor jedem Ausgang weg. Kein `defer` — `finish` endet in
        // `exit()` und wickelt den Stack nicht ab.
        func cleanUp() {
            SelfTest.workspaceDefaults()
                .removeObject(forKey: DiffColumnLayout.splitRatioDefaultsKey)
            try? FileManager.default.removeItem(at: base)
        }
        var afterLeft: CGFloat = 0
        var afterRight: CGFloat = 0
        var found: (window: NSWindow, content: NSView,
                    row: (ordinal: Int, before: CGRect, after: CGRect))?
        waitFor(budget: 3, pause: 0.05,
                condition: {
                    guard let window = mainWindowForAXChecks(), let content = window.contentView else {
                        cleanUp()
                        finish(false, "Hauptfenster nicht erreichbar")
                    }
                    guard let row = diffCellPairs(in: content).first else {
                        cleanUp()
                        finish(false, "Diff-Zeilen verschwunden")
                    }
                    afterLeft = row.before.width
                    afterRight = row.after.width
                    found = (window, content, row)
                    return abs(afterLeft - beforeLeft - distance) <= 2
                },
                onTimeout: { book in
                    cleanUp()
                    finish(false, "Der Trenner folgte dem Zug nicht: links "
                        + "\(Int(beforeLeft)) → \(Int(afterLeft)) pt statt "
                        + "\(Int(beforeLeft + distance)) pt — \(book.summary)")
                },
                then: {
                    guard let found else { finish(false, "Diff-Zeilen nach Erfolg verschwunden") }
                    let (window, content, row) = found
                    // Die rechte Seite gibt exakt den Platz ab, den die linke gewinnt —
                    // sonst bliebe rechts ein Streifen frei oder die Fläche wüchse.
                    guard abs((beforeLeft + beforeRight) - (afterLeft + afterRight)) < 2 else {
                        cleanUp()
                        finish(false, "Die Gesamtbreite änderte sich beim Ziehen: "
                            + "\(Int(beforeLeft + beforeRight)) → "
                            + "\(Int(afterLeft + afterRight)) pt")
                    }
                    guard abs(beforeRight - afterRight - distance) <= 2 else {
                        cleanUp()
                        finish(false, "Die rechte Seite gab \(Int(beforeRight - afterRight)) pt "
                            + "ab statt \(Int(distance)) pt")
                    }
                    // Zweite Stufe: Doppelklick auf den Griff stellt die Werksteilung
                    // wieder her. Ohne diesen Rückweg träfe man die exakte Hälfte nach dem
                    // ersten Zug nur noch zufällig — und zwar dauerhaft, weil die Teilung
                    // für alle Vergleiche gemerkt wird.
                    guard let handle = markerView(id: "diffSplitter", in: content) else {
                        cleanUp()
                        finish(false, "Splitter-Griff ist nach dem Zug verschwunden")
                    }
                    let handleFrame = handle.convert(handle.bounds, to: content)
                    let point = content.convert(NSPoint(x: handleFrame.midX, y: row.before.midY),
                                                to: nil)
                    guard sendSplitterDoubleClick(at: point, in: window) else {
                        cleanUp()
                        finish(false, "Doppelklick-Ereignisse nicht erzeugbar")
                    }
                    pollDiffSplitReset(ws, base: base, draggedLeft: afterLeft,
                                       draggedRight: afterRight, distance: distance)
                })
    }

    /// Doppelklick auf dem Griff: zwei Down/Up-Paare, das zweite mit
    /// `clickCount: 2`. `HandleView` liest die Klickzahl aus diesem Ereignis —
    /// `NSApp.currentEvent` wäre bei `sendEvent` gar nicht gesetzt (AGENTS.md).
    private static func sendSplitterDoubleClick(at point: NSPoint,
                                                in window: NSWindow) -> Bool {
        let time = ProcessInfo.processInfo.systemUptime
        func event(_ type: NSEvent.EventType, _ offset: Double,
                   _ clicks: Int, _ number: Int) -> NSEvent? {
            NSEvent.mouseEvent(with: type, location: point, modifierFlags: [],
                               timestamp: time + offset,
                               windowNumber: window.windowNumber, context: nil,
                               eventNumber: number, clickCount: clicks,
                               pressure: type == .leftMouseUp ? 0 : 1)
        }
        for (index, clicks) in [1, 2].enumerated() {
            guard let down = event(.leftMouseDown, 0.02 * Double(index), clicks, 20 + index),
                  let up = event(.leftMouseUp, 0.02 * Double(index) + 0.01,
                                 clicks, 30 + index) else { return false }
            window.sendEvent(down)
            window.sendEvent(up)
        }
        return true
    }

    private static func pollDiffSplitReset(_ ws: Workspace, base: URL,
                                           draggedLeft: CGFloat,
                                           draggedRight: CGFloat,
                                           distance: CGFloat) {
        func cleanUp() {
            SelfTest.workspaceDefaults()
                .removeObject(forKey: DiffColumnLayout.splitRatioDefaultsKey)
            try? FileManager.default.removeItem(at: base)
        }
        var left: CGFloat = 0
        var right: CGFloat = 0
        waitFor(budget: 3, pause: 0.05,
                condition: {
                    guard let content = mainWindowForAXChecks()?.contentView else {
                        cleanUp()
                        finish(false, "Hauptfenster nicht erreichbar")
                    }
                    guard let row = diffCellPairs(in: content).first else {
                        cleanUp()
                        finish(false, "Diff-Zeilen verschwunden")
                    }
                    left = row.before.width
                    right = row.after.width
                    return abs(left - right) < 1
                },
                onTimeout: { book in
                    cleanUp()
                    finish(false, "Der Doppelklick stellte die Werksteilung nicht her: "
                        + "links \(Int(left)) pt, rechts \(Int(right)) pt — \(book.summary)")
                },
                then: {
                    cleanUp()
                    finish(true, "Trenner um \(Int(distance)) pt gezogen: links auf "
                        + "\(Int(draggedLeft)) pt, rechts auf \(Int(draggedRight)) pt, "
                        + "Gesamtbreite unverändert; ein Doppelklick auf den Griff stellt "
                        + "die Werksteilung wieder her (je \(Int(left)) pt)")
                })
    }

    /// Diagnose (`-selftest gitstickyshot`): Änderungen-Liste mit 60 Dateien,
    /// bereits nach unten gescrollt. Die Aufnahme zeigt, ob der Abschnittskopf
    /// samt Sammel-Knöpfen oben stehen bleibt.
    private static func runGitStickyShot() {
        testLabel = "gitstickyshot"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        ws.gitInteraction.presentsDialogs = false
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-gitstickyshot-\(UUID().uuidString)")
        let repo = base.appendingPathComponent("working-copy")
        do {
            try fm.createDirectory(at: repo, withIntermediateDirectories: true)
            for index in 1...60 {
                try "Basis \(index)\n".write(
                    to: repo.appendingPathComponent(String(format: "datei-%02d.txt", index)),
                    atomically: true, encoding: .utf8)
            }
        } catch {
            finish(false, "(setup) \(error.localizedDescription)")
        }
        runGitSequence([["init", "-b", "main"], ["config", "user.email", "t@t"],
                        ["config", "user.name", "T"], ["add", "-A"],
                        ["commit", "-m", "init"]], in: repo) { ok, error in
            guard ok else { finish(false, "(setup git) \(error)") }
            do {
                for index in 1...60 {
                    try "Geändert \(index)\n".write(
                        to: repo.appendingPathComponent(String(format: "datei-%02d.txt", index)),
                        atomically: true, encoding: .utf8)
                }
            } catch {
                finish(false, "(working tree) \(error.localizedDescription)")
            }
            DispatchQueue.main.async {
                ws.openProject(at: repo)
                pollGitStickyShot(ws)
            }
        }
    }

    private static func pollGitStickyShot(_ ws: Workspace) {
        var header: NSView?
        waitFor(budget: 6, pause: 0.05,
                condition: {
                    guard let window = mainWindowForAXChecks(),
                          let content = window.contentView,
                          let candidate = markerView(id: "gitSectionHeader-unstaged", in: content),
                          (ws.gitStatus?.unstagedChanges.count ?? 0) >= 60 else { return false }
                    header = candidate
                    return true
                },
                onTimeout: { book in
                    finish(false, "(gitstickyshot) Liste nicht bereit — \(book.summary)")
                },
                then: {
                    guard let header else { finish(false, "(gitstickyshot) Kopf nach Erfolg verschwunden") }
                    var scroll: NSScrollView?
                    var view: NSView? = header.superview
                    while let current = view {
                        if let candidate = current as? NSScrollView { scroll = candidate; break }
                        view = current.superview
                    }
                    if let scroll { scrollGitChangesList(scroll, by: 400) }
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                        dumpMainWindowThenExit(prefix: "GITSTICKYSHOT-WINDOW")
                    }
                })
    }

    /// Diagnose (`-selftest filesgitshot`): Frisches Git-Projekt im Dateien-Tab
    /// öffnen und Fensternummer für `screencapture -l` ausgeben. Die Aufnahme dient
    /// der Sichtprüfung von Projektkopf, Filterfeld und zweizeiligem Branch-Bereich.
    private static func runFilesGitShot() {
        testLabel = "filesgitshot"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        guard GitRunner.isAvailable else { finish(.environment, "git nicht verfügbar") }
        ws.gitInteraction.presentsDialogs = false
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-filesgitshot-\(UUID().uuidString)")
        let repo = base.appendingPathComponent("Webseite")
        do {
            try fm.createDirectory(at: repo.appendingPathComponent("styles"),
                                   withIntermediateDirectories: true)
            try "<!doctype html>\n".write(
                to: repo.appendingPathComponent("index.html"),
                atomically: true, encoding: .utf8)
            try "body{margin:0}\n".write(
                to: repo.appendingPathComponent("styles/main.css"),
                atomically: true, encoding: .utf8)
        } catch {
            finish(false, "(setup) \(error.localizedDescription)")
        }
        runGitSequence([["init", "-b", "main"], ["config", "user.email", "t@t"],
                        ["config", "user.name", "T"], ["add", "-A"],
                        ["commit", "-m", "init"]], in: repo) { ok, error in
            guard ok else { finish(false, "(setup git) \(error)") }
            // Eine offene Änderung, damit Diff-Knopf und Änderungen-Badge
            // im Bild etwas zu zeigen haben.
            try? "<!doctype html>\n<h1>Hallo</h1>\n".write(
                to: repo.appendingPathComponent("index.html"),
                atomically: true, encoding: .utf8)
            DispatchQueue.main.async {
                prepareRemoteBadgeShot(repository: repo, workspace: ws) {
                    ws.openProject(at: repo)
                    pollFilesGitShot(ws)
                }
            }
        }
    }

    /// Optionaler echter Remote-Zustand für die schmale/breite Sichtprüfung.
    private static func prepareRemoteBadgeShot(repository: URL, workspace: Workspace,
                                               completion: @escaping () -> Void) {
        guard ProcessInfo.processInfo.environment["FASTRA_REMOTE_BADGE_SCREENSHOT"] == "1" else {
            completion(); return
        }
        let remotes = ["cached", "failed", "source"]
        let commands = remotes.flatMap { remote in
            [["remote", "add", remote, repository.path], ["fetch", "--", remote]]
        } + [["remote", "set-url", "failed", repository.appendingPathComponent("missing.git").path]]
        runGitSequence(commands, in: repository) { ok, error in
            guard ok else { finish(false, "Remote-Screenshot-Fixture: \(error)") }
            workspace.gitRepositoryStore.recordSuccessfulFetch(repository: repository, remote: "source")
            _ = workspace.gitRepositoryStore.fetch(repository: repository,
                preferences: GitPreferences(), remotes: remotes, selection: .remote("failed")) { outcome in
                guard case .completed(let result) = outcome, !result.ok else {
                    finish(false, "Remote-Screenshot-Fixture erzeugte keinen Fehler")
                }
                DispatchQueue.main.async { completion() }
            }
        }
    }

    private static func pollFilesGitShot(_ ws: Workspace) {
        // Warten, bis Branch-Zeile (gitStatus) und Baum wirklich da sind.
        waitFor(budget: 6, pause: 0.05,
                condition: { ws.gitStatus != nil && mainWindowForAXChecks() != nil },
                onTimeout: { book in
                    finish(false, "(filesgitshot) Git-Status/Fenster nicht bereit — \(book.summary)")
                },
                then: {
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                        dumpMainWindowThenExit(prefix: "FILESGITSHOT-WINDOW")
                    }
                })
    }

    /// Diagnose (`-selftest diffwideshot`): Diff mit überbreiten Zeilen aufnehmen,
    /// um Abschneiden an der Spaltengrenze statt Zeichnung in der Nachbarspalte
    /// sichtbar zu prüfen.
    private static func runDiffWideShot() {
        testLabel = "diffwideshot"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        let fm = FileManager.default
        let base = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-diffwideshot-\(UUID().uuidString)")
        // Lange Zeilen mit sichtbar unterschiedlichem Inhalt beider Seiten:
        // Läuft der linke Text über, überschreibt er rechten Text.
        let longLeft = "ALT " + String(repeating: "links-links-links ", count: 12)
        let longRight = "NEU " + String(repeating: "rechts-rechts-rechts ", count: 12)
        var leftLines = (1...12).map { "gemeinsame zeile \($0)" }
        var rightLines = leftLines
        leftLines[3] = longLeft
        rightLines[3] = longRight
        leftLines[6] = longLeft + "ende"
        rightLines[6] = longRight + "ende"
        let leftURL = base.appendingPathComponent("links.txt")
        let rightURL = base.appendingPathComponent("rechts.txt")
        do {
            try fm.createDirectory(at: base, withIntermediateDirectories: true)
            try leftLines.joined(separator: "\n")
                .write(to: leftURL, atomically: true, encoding: .utf8)
            try rightLines.joined(separator: "\n")
                .write(to: rightURL, atomically: true, encoding: .utf8)
        } catch {
            finish(false, "Fixture nicht anlegbar: \(error.localizedDescription)")
        }
        ws.openFileDiffTab(request: FileDiffRequest(
            left: .file(leftURL), right: .file(rightURL), options: FileDiffOptions()
        ))
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
            dumpMainWindowThenExit(prefix: "DIFFWIDESHOT-WINDOW")
        }
    }

