    /// Echte WebKit-Vorschau samt Bundle-Bibliotheken am DOM prüfen:
    /// Bilddekodierung, KaTeX-MathML, Mermaid-SVG und Syntaxhervorhebung.
    /// Externen Bildaustausch am gleichen Pfad über `naturalWidth` nachweisen
    /// (1 px → 2 px). FSEvents und dateigebundener Bild-Token müssen auch die
    /// bereits offene Vorschau aktualisieren.
    ///
    /// „Einfügen und Einrückung angleichen“ über den echten Befehlsweg prüfen:
    /// Zwischenablage setzen, Menü-Notification posten, Ergebnis und Undo prüfen.
    private static func runPasteMatchIndentationTest() {
        testLabel = "pasteindent"
        guard let ws = Workspace.shared else {
            finishPasteIndent(false, "Workspace.shared ist nil (Test-Hook fehlt)")
        }
        let url = selfTestTemporaryDirectory()
            .appendingPathComponent("fastra-pasteindent-\(UUID().uuidString).txt")
        let original = "    ziel\n"
        do { try original.write(to: url, atomically: true, encoding: .utf8) }
        catch {
            finishPasteIndent(.environment, "Umgebungsproblem: (setup) Fixture nicht schreibbar: \(error.localizedDescription)")
        }
        ws.loadFile(at: url) { ok in
            try? FileManager.default.removeItem(at: url)
            guard ok else { finishPasteIndent(false, "Fixture lädt nicht") }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                guard let window = NSApp.windows.first(where: {
                    $0.frameAutosaveName != SearchWindow.frameAutosaveName
                        && $0.contentView != nil && $0.isVisible
                }), let root = window.contentView,
                      let textView = editorTextView(in: root) as? TextView else {
                    finishPasteIndent(false, "Editor-TextView nicht gefunden")
                }
                window.makeFirstResponder(textView)
                // Cursor ans Dokumentende (leerer Zeilenanfang hinter der
                // eingerückten Zielzeile → Kontext erbt deren 4 Spalten).
                textView.selectionManager.setSelectedRange(
                    NSRange(location: (textView.string as NSString).length, length: 0)
                )
                // Der runnerweite Schutz sichert itemgetreu und zusätzlich auf
                // Platte, damit auch ein Crash vor dem Abschluss heilbar ist.
                writeSelfTestPasteboardString("if x {\n    y()\n}\n")
                NotificationCenter.default.post(
                    name: .fastraPasteMatchingIndentation, object: nil
                )
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                    let expected = "    ziel\n    if x {\n        y()\n    }\n"
                    guard textView.string == expected else {
                        finishPasteIndent(false, "Einfügung falsch: \(textView.string.debugDescription) statt \(expected.debugDescription)")
                    }
                    // Genau eine Undo-Aktion stellt den Ausgangstext her.
                    textView.undoManager?.undo()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                        guard textView.string == original else {
                            finishPasteIndent(false, "Undo stellte nicht den Ausgangstext her: \(textView.string.debugDescription)")
                        }
                        finishPasteIndent(true, "Block sitzt auf der Ziel-Einrückung (relativ erhalten), eine Undo-Aktion stellt alles zurück")
                    }
                }
            }
        }
    }

    /// Behält den sprechenden Abschlussnamen des Tests; die zentrale
    /// `finish`-Funktion gibt die Zwischenablage für alle Selbsttests zurück.
    private static func finishPasteIndent(_ ok: Bool, _ message: String) -> Never {
        finishPasteIndent(ok ? .pass : .fail, message)
    }

    private static func finishPasteIndent(
        _ outcome: SelfTestOutcome, _ message: String
    ) -> Never {
        finish(outcome, message)
    }

    private static func runMarkdownImageWatchTest() {
        testLabel = "mdimagewatch"
        guard let ws = Workspace.shared else { finish(false, "Workspace.shared ist nil") }
        let directory = selfTestTemporaryDirectory()
            .appendingPathComponent("Fastra-MdImageWatch-\(UUID().uuidString)")
        let file = directory.appendingPathComponent("Bildwechsel.md")
        let image = directory.appendingPathComponent("wechsel.png")
        let onePixel = Data(base64Encoded:
            "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=")!
        // Der 2×2-Ersatz stammt aus einem echten PNG-Encoder-Lauf; sollte die
        // Base64-Form je beschädigt werden, bricht der Test hier ehrlich ab.
        guard let replacement = Data(base64Encoded:
            "iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEUlEQVR4nGP4z8DwH4QZYAwAR8oH+WdZbrcAAAAASUVORK5CYII=") else {
            finish(false, "2×2-PNG-Fixture ist nicht dekodierbar")
        }
        do {
            try FileManager.default.createDirectory(at: directory,
                                                    withIntermediateDirectories: true)
            try onePixel.write(to: image, options: .atomic)
            try "# Bildwechsel\n\n![Wechselbild](wechsel.png)\n"
                .write(to: file, atomically: true, encoding: .utf8)
        } catch {
            finish(.environment, "Umgebungsproblem: (setup) Fixtures nicht schreibbar: \(error.localizedDescription)")
        }
        workspaceDefaults().set(true, forKey: "markdown.integratedPreview")
        ws.loadFile(at: file) { ok in
            guard ok else { finish(false, "Markdown-Datei konnte nicht geladen werden") }
            pollImageWatchWidth(expected: 1, directory: directory) {
                do {
                    // Austausch am gleichen Pfad — atomar, wie es externe
                    // Werkzeuge tun. Markdown und Stil bleiben unverändert;
                    // nur der Wächter kann die Vorschau aktualisieren.
                    try replacement.write(to: image, options: .atomic)
                } catch {
                    try? FileManager.default.removeItem(at: directory)
                    finish(false, "Bild-Austausch nicht schreibbar: \(error.localizedDescription)")
                }
                pollImageWatchWidth(expected: 2, directory: directory) {
                    try? FileManager.default.removeItem(at: directory)
                    finish(true, "extern ausgetauschtes Bild erschien in der offenen Vorschau (1 px → 2 px)")
                }
            }
        }
    }

    /// Wartet, bis das erste Vorschau-Bild die erwartete natürliche Breite
    /// zeigt — der Beweis, dass wirklich die neue Datei gerendert ist.
    private static func pollImageWatchWidth(expected: Int, directory: URL,
                                            then continuation: @escaping () -> Void) {
        waitForAsync(
            budget: 12, pause: 0.1,
            check: { answer in
                guard let root = NSApp.windows.first(where: {
                    $0.frameAutosaveName != SearchWindow.frameAutosaveName
                        && $0.contentView != nil && $0.isVisible
                })?.contentView,
                      let webView = markdownWebView(in: root) else {
                    answer(false)
                    return
                }
                let script = "(() => { const i = document.images[0]; return i ? i.naturalWidth : 0; })()"
                webView.evaluateJavaScript(script) { result, _ in
                    answer((result as? Int) == expected)
                }
            },
            onTimeout: { book in
                try? FileManager.default.removeItem(at: directory)
                finish(false, "Vorschau-Bild erreichte Breite \(expected) nicht — \(book.summary)")
            },
            then: continuation
        )
    }

