    /// Gemeinsames Shot-Finale: größtes sichtbares Fenster (= Hauptfenster)
    /// nach vorn ordnen, Fenster-Nummer auf stderr ausgeben, nach 12 s
    /// Selbst-Exit — gleiche Mechanik wie die Suchmasken-Shots.
    private static func dumpMainWindowThenExit(prefix: String) {
        if let value = ProcessInfo.processInfo.environment["FASTRA_SIDEBAR_SCREENSHOT_WIDTH"],
           let width = Double(value), (SidebarLayout.minimumSidebarWidth...500).contains(width),
           let workspace = Workspace.shared, workspace.sidebarWidth != width {
            workspace.sidebarWidth = width
            Task { @MainActor in
                try? await Task.sleep(for: .milliseconds(300))
                dumpMainWindowThenExit(prefix: prefix)
            }
            return
        }
        let main = NSApp.windows
            .filter { $0.isVisible }
            .max(by: { ($0.frame.width * $0.frame.height) < ($1.frame.width * $1.frame.height) })
        guard let win = main else { finish(false, "kein sichtbares Hauptfenster") }
        win.orderFront(nil)
        FileHandle.standardError.write(Data("\(prefix) \(win.windowNumber)\n".utf8))
        DispatchQueue.main.asyncAfter(deadline: .now() + 12) { finishScreenshotDiagnostic() }
    }

    /// Wartet auf die ersten Live-Treffer (Pillen + Vorschau gefüllt), holt die
    /// Suchmaske nach vorn und gibt ihre Fenster-Nummer aus, dann Selbst-Exit.
    private static func pollWildcardShot(_ ws: Workspace) {
        var win: NSWindow?
        waitFor(budget: 3, pause: 0.03,
                condition: {
                    guard ws.bufferMatches.count >= 1, ws.searchError == nil else { return false }
                    win = NSApp.windows.first(where: {
                        $0.frameAutosaveName == SearchWindow.frameAutosaveName && $0.isVisible
                    })
                    return win != nil
                },
                onTimeout: { book in
                    finish(false, "(wildcardshot) keine Treffer/Suchmaske "
                        + "(bufferMatches=\(ws.bufferMatches.count), error=\(ws.searchError ?? "nil")) — \(book.summary)")
                },
                then: {
                    guard let win else { finish(false, "(wildcardshot) Suchmaske nach Erfolg verschwunden") }
                    win.orderFront(nil)
                    // Fenster-Nummer == CGWindowID → direkt für `screencapture -l` nutzbar.
                    FileHandle.standardError.write(Data("WILDCARDSHOT-WINDOW \(win.windowNumber)\n".utf8))
                    DispatchQueue.main.asyncAfter(deadline: .now() + 12) { finishScreenshotDiagnostic() }
                })
    }

    /// Leere Treffer allein können noch vom vorherigen Suchbereich stammen.
    /// Erst eine abgeschlossene Suche mit den aktuellen Optionen ist ein Beleg.
    static func hasCompletedEmptyBufferSearch(_ ws: Workspace) -> Bool {
        !ws.bufferSearching && ws.searchError == nil && ws.bufferMatches.isEmpty
            && ws.visibleBufferResultsOptions == ws.currentSearchOptions
    }

